#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    int *key_ptr;
    long *offset_ptr;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initialize_records(int num_records, int key_range_min, int key_range_max, long offset_range_min, long offset_range_max) {
    pthread_mutex_lock(&mutex);

    // Allocate memory for keys and offsets
    int *keys = malloc(num_records * sizeof(int));
    long *offsets = malloc(num_records * sizeof(long));

    if (!keys || !offsets) {
        printf("Memory allocation failed\n");
        free(keys);
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Allocate memory for records
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        free(keys);
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize random number generator
    srand(time(NULL));

    int initialized_count = 0;

    for (int i = 0; i < num_records; ++i) {
        keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
        offsets[i] = offset_range_min + rand() % (offset_range_max - offset_range_min + 1);

        records[i].value = rand(); // Random value
        records[i].key_ptr = &keys[i];
        records[i].offset_ptr = &offsets[i];

        initialized_count++;
    }

    printf("Successfully initialized %d records\n", initialized_count);

    pthread_mutex_unlock(&mutex);

    // Return pointers to the caller for further use, or manage them in a larger system
    return 0; // Indicate success
}

void cleanup(int *keys, long *offsets, record *records) {
    if (keys) free(keys);
    if (offsets) free(offsets);
    if (records) free(records);

    pthread_mutex_unlock(&mutex); // Ensure mutex is unlocked on exit
}

// Example usage within a multi-threaded context
void* thread_function(void* arg) {
    int num_records = *(int*)arg;
    initialize_records(num_records, 0, 100, 0, 1000000);
    return NULL;
}

int main() {
    pthread_t threads[10];
    int sizes[] = {100, 200, 300, 400, 500, 600, 700, 800, 900, 1000};

    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &sizes[i]);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup should be handled where resources are managed
    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex ensures that only one thread can execute the memory allocation and initialization at a time, preventing race conditions.
- **Error Handling**: Checks for successful memory allocations and handles failures gracefully.
- **Cleanup**: Provides a cleanup function to free allocated resources and unlock the mutex.
- **Random Initialization**: Uses `rand()` seeded with `time(NULL)` for random value generation.
- **Multi-threading Example**: Demonstrates how the function can be used in a multi-threaded environment.']

