#define MAX_LINE_LENGTH 1024

void print_help() {
    printf("Usage: config_processor [options] file1 [file2 ...]\n");
    printf("Options:\n");
    printf("  --help           Display this help message\n");
    printf("  -o output_file   Redirect output to a specified file\n");
}

int file_exists(const char *filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

int validate_schema(const char *content) {
    // Placeholder for schema validation logic
    // Return 1 if valid, 0 otherwise
    return 1; // Assume all files are valid for this example
}

void log_error(const char *message) {
    printf("Error: %s\n", message);
}

void process_file(const char *filename, int output_fd, int *total_lines, int *total_chars) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error(strcat("Cannot open file ", filename));
        return;
    }

    char line[MAX_LINE_LENGTH];
    int lines = 0, chars = 0;
    while (fgets(line, sizeof(line), file)) {
        lines++;
        for (char *p = line; *p != '\0'; p++) {
            if (*p != ' ') chars++;
        }
    }

    if (ferror(file)) {
        log_error(strcat("Error reading file ", filename));
        fclose(file);
        return;
    }

    fclose(file);

    if (!validate_schema(filename)) {
        log_error(strcat("Invalid schema in file ", filename));
        return;
    }

    *total_lines += lines;
    *total_chars += chars;

    dprintf(output_fd, "Processed %s: %d lines, %d characters\n", filename, lines, chars);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_help();
        return 1;
    }

    int output_fd = STDOUT_FILENO;
    const char *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        }
    }

    if (output_file) {
        output_fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (output_fd < 0) {
            perror("Failed to open output file");
            return 1;
        }
    }

    int total_lines = 0, total_chars = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-o") == 0) continue;

        if (!file_exists(argv[i])) {
            log_error(strcat("File does not exist: ", argv[i]));
            continue;
        }

        process_file(argv[i], output_fd, &total_lines, &total_chars);
    }

    dprintf(output_fd, "Summary: %d lines, %d characters across all valid files\n", total_lines, total_chars);

    if (output_fd != STDOUT_FILENO) {
        close(output_fd);
    }

    return 0;
}
