void log_warning(const char *message) {
    // Log warnings without overwhelming the system
    fprintf(stderr, "Warning: %s\n", message);
}

int open_file_safely(FILE **file, const char *filename, const char *mode) {
    while (*file == NULL && errno == EAGAIN) {
        *file = fopen(filename, mode);
    }
    return (*file != NULL);
}

void process_large_binary_file(ProcessParams params) {
    FILE *input_file = NULL;
    FILE *output_file = NULL;

    if (!open_file_safely(&input_file, params.input_file, "rb")) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }

    if (!open_file_safely(&output_file, params.output_file, "wb")) {
        perror("Failed to open output file");
        fclose(input_file);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t chunk_size = CHUNK_SIZE;
    uint8_t *chunk = malloc(chunk_size);
    if (!chunk) {
        perror("Memory allocation failed");
        fclose(input_file);
        fclose(output_file);
        exit(EXIT_FAILURE);
    }

    int processed_records = 0;
    while (fread(chunk, 1, chunk_size, input_file) > 0 && processed_records < params.max_records) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, process_chunk, chunk)) {
            perror("Failed to create thread");
            free(chunk);
            fclose(input_file);
            fclose(output_file);
            exit(EXIT_FAILURE);
        }

        pthread_join(thread, NULL);

        processed_records++;
    }

    free(chunk);
    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <config_file> <max_records> <prioritize_performance>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ProcessParams params = {
        .input_file = argv[1],
        .output_file = argv[2],
        .config_file = argv[3],
        .max_records = atoi(argv[4]),
        .prioritize_performance = atoi(argv[5])
    };

    process_large_binary_file(params);

    return EXIT_SUCCESS;
}
