#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dns.h>  // Hypothetical DNS library
#include <unistd.h>
#include <fcntl.h>

#define MAX_THREADS 10
#define DEFAULT_TIMEOUT 5
#define RETRY_LIMIT 3

typedef struct {
    char *filename;
    size_t chunk_size;
    int timeout;
} FileTask;

typedef struct {
    pthread_t threads[MAX_THREADS];
    int thread_count;
} ThreadPool;

typedef struct {
    char *hostname;
    char *line;
    double average;
} DNSResult;

void *dns_resolve(void *arg) {
    DNSResult *result = (DNSResult *)arg;
    dns_context context;
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (dns_init(&context, result->hostname, DEFAULT_TIMEOUT)) {
            break; // Success
        }
        retries++;
        sleep(1); // Wait before retrying
    }

    if (!dns_resolved(context)) {
        fprintf(stderr, "DNS resolution failed for %s\n", result->hostname);
        free(result->line);
        free(result);
        return NULL;
    }

    char *ip_address = dns_get_ip(context);
    printf("Resolved IP: %s\n", ip_address);

    // Calculate average of the last two numeric fields
    double num1, num2;
    if (sscanf(result->line + strlen(result->line) - 20, "%lf,%lf", &num1, &num2) == 2) {
        result->average = (num1 + num2) / 2.0;
    } else {
        fprintf(stderr, "Failed to parse numbers from line: %s\n", result->line);
        free(result->line);
        free(result);
        return NULL;
    }

    char *output_line = malloc(strlen(result->line) + 40); // Extra space for average
    sprintf(output_line, "%s,%f", result->line, result->average);

    printf("Processed line: %s\n", output_line);

    free(ip_address);
    dns_cleanup(context);
    free(result->line);
    free(result);
    free(output_line);
    return NULL;
}

void process_chunk(FileTask *task) {
    int fd = open(task->filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return;
    }

    char *buffer = malloc(task->chunk_size);
    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer, task->chunk_size)) > 0) {
        char *line_start = buffer;
        for (ssize_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                buffer[i] = '\0'; // Null-terminate the line
                DNSResult *result = malloc(sizeof(DNSResult));
                result->hostname = "example.com"; // Replace with actual hostname extraction logic
                result->line = strdup(line_start);

                pthread_t thread;
                if (pthread_create(&thread, NULL, dns_resolve, result) != 0) {
                    perror("Failed to create thread");
                    free(result->line);
                    free(result);
                } else {
                    pthread_detach(thread); // Detach the thread for independent execution
                }

                line_start = buffer + i + 1; // Move to next line start
            }
        }
    }

    if (bytes_read == -1) {
        perror("Failed to read file");
    }

    free(buffer);
    close(fd);
}

void *thread_function(void *arg) {
    FileTask *task = (FileTask *)arg;
    process_chunk(task);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ThreadPool pool = { .thread_count = 0 };
    for (int i = 1; i < argc; ++i) {
        FileTask *task = malloc(sizeof(FileTask));
        task->filename = argv[i];
        task->chunk_size = 4096; // Configurable chunk size
        task->timeout = DEFAULT_TIMEOUT;

        if (pool.thread_count < MAX_THREADS) {
            pthread_create(&pool.threads[pool.thread_count], NULL, thread_function, task);
            pool.thread_count++;
        } else {
            fprintf(stderr, "Maximum number of concurrent threads reached\n");
            free(task);
        }
    }

    for (int i = 0; i < pool.thread_count; ++i) {
        pthread_join(pool.threads[i], NULL); // Wait for all threads to finish
    }

    return EXIT_SUCCESS;
}
