#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct Node {
    int data;
    int count;
    struct Node* next;
} Node;

Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->count = 1;
    new_node->next = NULL;
    return new_node;
}

void update_linked_list(Node** head, int value) {
    Node* current = *head;
    Node* prev = NULL;

    while (current != NULL && current->data < value) {
        prev = current;
        current = current->next;
    }

    if (current != NULL && current->data == value) {
        current->count++;
    } else {
        Node* new_node = create_node(value);
        new_node->next = current;

        if (prev == NULL) {
            *head = new_node;
        } else {
            prev->next = new_node;
        }
    }
}

void process_stream() {
    FILE* input = stdin;
    int value, largest = INT_MIN;
    Node* head = NULL;
    int processed_count = 0;

    while (processed_count < 1000 && fscanf(input, "%d", &value) == 1) {
        update_linked_list(&head, value);

        if (value > largest) {
            largest = value;
        }

        processed_count++;
    }

    printf("Largest number: %d\n", largest);

    Node* current = head;
    while (current != NULL) {
        printf("Number %d appeared %d times\n", current->data, current->count);
        Node* temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    process_stream();
    return 0;
}
