// Function to initialize the cipher context based on input data and environment
EVP_CIPHER_CTX *initialize_cipher(int data_size, const unsigned char *key, int key_len, 
                                  const unsigned char *iv, int iv_len, const char *mode) {

    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = NULL;

    // Select cipher based on key length and mode
    if (key_len == 16 && strcmp(mode, "CBC") == 0) {
        cipher = EVP_aes_128_cbc();
    } else if (key_len >= 24 && strcmp(mode, "GCM") == 0) {
        cipher = EVP_aes_256_gcm();
    } else if (strcmp(mode, "CTR") == 0) {
        cipher = EVP_chacha20_poly1305_ietf();
    } else if (data_size > 1024 * 1024 && strcmp(mode, "GCM") == 0) { // Large data size
        cipher = EVP_aead_aes_256_gcm();
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing encryption operation\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Additional configurations for specific modes
    if (strcmp(mode, "GCM") == 0) {
        unsigned int tag_len = 16; // Example tag length
