    unsigned char iv[EVP_MAX_IV_length] = {0};   // Example IV

    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating random bytes\n");
        return 1;
    }

    EVP_CIPHER *cipher = select_and_init_cipher(key, sizeof(key), iv, sizeof(iv));
    if (cipher) {
        printf("Cipher initialized successfully: %s\n", EVP_CIPHER_name(cipher));
        // Further operations with the cipher...
    } else {
        fprintf(stderr, "Failed to initialize cipher\n");
    }

    return 0;
}
