    private final Map<String, String> cache = new HashMap<>();

    public String generateReport(Pokemon pokemon, Optional<String> filterType) {
        if (pokemon == null || pokemon.getName() == null) {
            return "Invalid input: Pokemon or name is null.";
        }

        List<String> types = pokemon.getTypes();
        if (types == null || types.isEmpty()) {
            return String.format("Pokemon %s has no types.", pokemon.getName());
        }

        StringBuilder report = new StringBuilder();

        for (String type : types) {
