            }

            Set<String> strengths = TypeData.getStrengths(type);
            Set<String> weaknesses = TypeData.getWeaknesses(type);

            if (filterType.isPresent() && !filterType.get().equals(type)) {
                continue;
            }

            report.append(String.format("\n%s Type Report:\n", type));
            report.append("Strengths: ").append(getFormattedSet(strengths)).append("\n");
            report.append("Weaknesses: ").append(getFormattedSet(weaknesses)).append("\n");

            // Cache the result
            cacheResult(pokemon.getName(), type, strengths, weaknesses);
        }

        return report.length() > 0 ? report.toString() : String.format("No valid data for %s.", pokemon.getName());
    }

    private String getFormattedSet(Set<String> set) {
        if (set.isEmpty()) {
            return "None";
        }
