#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <sys/stat.h>
#include <errno.h>

#define MIN_FILE_SIZE 128 // Minimum size in bytes for configuration file

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int is_initialized;
    pthread_mutex_t lock;
} CipherCache;

CipherCache cache = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    return -1;
}

int validate_file_path(const char *file_path) {
    struct stat st;
    if (stat(file_path, &st) != 0) {
        return log_error("File does not exist or cannot be accessed.");
    }
    if (!S_ISREG(st.st_mode)) {
        return log_error("Path is not a regular file.");
    }
    if (st.st_size < MIN_FILE_SIZE) {
        return log_error("File size is below the minimum required limit.");
    }
    return 0;
}

int load_configuration(const char *file_path, const char **algorithm, int *key_length, const char **iv) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        return log_error("Failed to open configuration file.");
    }

    // Simulated parsing logic
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "algorithm=", 10) == 0) {
            *algorithm = strdup(line + 10);
            *(strchr(*algorithm, '\n')) = '\0';
        } else if (strncmp(line, "key_length=", 11) == 0) {
            *key_length = atoi(line + 11);
        } else if (strncmp(line, "iv=", 3) == 0) {
            *iv = strdup(line + 3);
            *(strchr(*iv, '\n')) = '\0';
        }
    }

    fclose(file);

    if (!*algorithm || !*iv) {
        return log_error("Configuration file is missing required fields.");
    }

    return 0;
}

EVP_CIPHER_CTX *initialize_cipher(const char *algorithm, int key_length, const char *iv, int encrypt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_error("Failed to allocate memory for cipher context.");
        return NULL;
    }

    const EVP_CIPHER *cipher = EVP_get_cipherbyname(algorithm);
    if (!cipher) {
        EVP_CIPHER_CTX_free(ctx);
        log_error("Unknown encryption algorithm specified.");
        return NULL;
    }

    int dir = encrypt ? 1 : 0;
    if (EVP_CipherInit_ex(ctx, cipher, NULL, NULL, NULL, dir) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        log_error("Failed to initialize cipher context.");
        return NULL;
    }

    if (EVP_CIPHER_CTX_set_key_length(ctx, key_length) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        log_error("Invalid key length specified.");
        return NULL;
    }

    if (EVP_CipherInit_ex(ctx, NULL, NULL, (unsigned char *)iv, NULL, dir) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        log_error("Failed to set IV for cipher context.");
        return NULL;
    }

    return ctx;
}

EVP_CIPHER_CTX *manage_encryption_service(const char *file_path, int encrypt) {
    if (validate_file_path(file_path)) {
        return NULL;
    }

    const char *algorithm = NULL;
    int key_length = 0;
    const char *iv = NULL;

    if (load_configuration(file_path, &algorithm, &key_length, &iv)) {
        return NULL;
    }

    pthread_mutex_lock(&cache.lock);
    if (!cache.ctx || !cache.is_initialized) {
        EVP_CIPHER_CTX_free(cache.ctx);
        cache.ctx = initialize_cipher(algorithm, key_length, iv, encrypt);
        cache.is_initialized = (cache.ctx != NULL);
    }
    pthread_mutex_unlock(&cache.lock);

    if (!cache.ctx) {
        return NULL;
    }

    return EVP_CIPHER_CTX_dup(cache.ctx);
}

void free_resources(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

// Example unit test function
void test_manage_encryption_service() {
    // Implement various test cases here
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file_path> <encrypt|decrypt>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *file_path = argv[1];
    int encrypt = strcmp(argv[2], "encrypt") == 0;

    EVP_CIPHER_CTX *ctx = manage_encryption_service(file_path, encrypt);
    if (ctx) {
        printf("Cipher context initialized successfully.\n");
        EVP_CIPHER_CTX_free(ctx);
    } else {
        fprintf(stderr, "Failed to initialize cipher context.\n");
    }

    return EXIT_SUCCESS;
}
```

