#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
import <unistd.h>  // For usleep

#define MAX_SEMAPHORES 10
#define RETRY_LIMIT 5
#define RETRY_DELAY_MS 100

typedef struct SemaphorePool {
    sem_t *semaphores[MAX_SEMAPHORES];
    pthread_mutex_t lock;
    int count;  // Number of active semaphores
} SemaphorePool;

SemaphorePool pool = {{NULL}, PTHREAD_MUTEX_INITIALIZER, 0};

// Initialize semaphore pool
int init_semaphore_pool() {
    return pthread_mutex_lock(&pool.lock) == 0 ? 0 : -1;
}

// Destroy semaphore pool
void destroy_semaphore_pool() {
    for (int i = 0; i < pool.count; ++i) {
        if (pool.semaphores[i] != NULL) {
            sem_destroy(pool.semaphores[i]);
            free(pool.semaphores[i]);
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

// Create a new semaphore
sem_t* create_semaphore(int init_value, int retries) {
    for (int attempt = 0; attempt < RETRY_LIMIT && retries > 0; ++attempt) {
        sem_t *new_sem = malloc(sizeof(sem_t));
        if (!new_sem || sem_init(new_sem, 0, init_value) == -1) {
            usleep(RETRY_DELAY_MS * 1000);  // Delay before retry
            continue;
        }
        return new_sem;
    }
    return NULL;  // Failed to create semaphore after retries
}

// Allocate a semaphore from the pool
sem_t* allocate_semaphore(int init_value) {
    if (pthread_mutex_lock(&pool.lock) != 0) return NULL;

    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (pool.semaphores[i] == NULL) {
            sem_t *new_sem = create_semaphore(init_value, RETRY_LIMIT);
            if (new_sem) {
                pool.semaphores[i] = new_sem;
                ++pool.count;
                pthread_mutex_unlock(&pool.lock);
                return new_sem;
            }
        }
    }

    pthread_mutex_unlock(&pool.lock);
    return NULL;  // No available slots
}

// Free a semaphore and remove it from the pool
void free_semaphore(sem_t *sem) {
    if (pthread_mutex_lock(&pool.lock) != 0 || sem == NULL) return;

    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (pool.semaphores[i] == sem) {
            sem_destroy(pool.semaphores[i]);
            free(pool.semaphores[i]);
            pool.semaphores[i] = NULL;
            --pool.count;
            break;
        }
    }

    pthread_mutex_unlock(&pool.lock);
}

// Example usage of semaphore
void* thread_function(void *arg) {
    sem_t *sem = (sem_t*) arg;

    if (sem != NULL) {
        sem_wait(sem);
        printf("Semaphore acquired by thread %ld\n", pthread_self());
        usleep(1000);  // Simulate work
        sem_post(sem);
    }

    return NULL;
}

int main() {
    pthread_t threads[20];
    sem_t *sem1 = allocate_semaphore(1);

    if (sem1 == NULL) {
        fprintf(stderr, "Failed to allocate semaphore\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) {
        pthread_create(&threads[i], NULL, thread_function, sem1);
    }

    for (int i = 0; i < 20; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_semaphore(sem1);
    destroy_semaphore_pool();

    return EXIT_SUCCESS;
}
```']

