#include <iostream>
#include <mutex>

class Node {
public:
    int value;
    Node* next;

    Node(int val) : value(val), next(nullptr) {}
};

class DynamicLinkedList {
private:
    Node* head;
    std::mutex mtx;

public:
    DynamicLinkedList() : head(nullptr) {}

    ~DynamicLinkedList() {
        clear();
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mtx);
        while (head != nullptr) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void initialize(int first, int second, int third) {
        std::lock_guard<std::mutex> lock(mtx);
        if (!head) {
            head = new Node(first);
            head->next = new Node(second);
            head->next->next = new Node(third);
        }
    }

    void insertAfter(int target, int newValue) {
        std::lock_guard<std::mutex> lock(mtx);

        Node* current = head;
        while (current != nullptr && current->value != target) {
            current = current->next;
        }

        if (current != nullptr) {
            Node* newNode = new Node(newValue);
            newNode->next = current->next;
            current->next = newNode;
        } else {
            append(newValue);
        }
    }

    void append(int newValue) {
        std::lock_guard<std::mutex> lock(mtx);

        Node* newNode = new Node(newValue);
        if (!head) {
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = newNode;
        }
    }

    void display() const {
        std::lock_guard<std::mutex> lock(mtx);

        Node* current = head;
        while (current != nullptr) {
            std::cout << current->value << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }

    void manageList(int first, int second, int third) {
        if (first < 0 || second < 0 || third < 0) {
            throw std::invalid_argument("All inputs must be non-negative integers.");
        }

        insertAfter(second, third);

        if (!head) {
            initialize(first, second, third);
        }
    }
};

// Test suite
void testSuite() {
    DynamicLinkedList list;

    // Test initialization and insertion when empty
    list.manageList(1, 2, 3);
    list.display(); // Expected: 1 2 3

    // Test inserting after existing value
    list.manageList(0, 2, 4);
    list.display(); // Expected: 1 2 4 3

    // Test appending when target not found
    list.manageList(0, 5, 6);
    list.display(); // Expected: 1 2 4 3 6

    // Test handling of non-negative constraints
    try {
        list.manageList(-1, -2, -3); // Should throw an exception
    } catch (const std::invalid_argument& e) {
        std::cout << "Caught expected exception: " << e.what() << std::endl;
    }

    // Test with large data manipulation
    for (int i = 0; i < 10000; ++i) {
        list.manageList(i, i % 10, i * 2);
    }
    std::cout << "Large data manipulation completed." << std::endl;

    // Final state display
    list.display();
}

int main() {
    testSuite();
    return 0;
}
