#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <memory>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <queue>
#include <functional>

namespace LoggingSystem {

    enum class LogLevel {
        DEBUG,
        INFO,
        WARNING,
        ERROR,
        FATAL
    };

    struct LogMessage {
        LogLevel level;
        std::string message;
    };

    class Logger {
    public:
        using LogHandler = std::function<void(const LogMessage&)>;

        Logger(LogLevel logLevel, const std::vector<LogHandler>& handlers)
            : currentLogLevel(logLevel), logHandlers(handlers) {}

        void log(LogLevel level, const std::string& message) {
            if (level < currentLogLevel) return;

            auto logMsg = LogMessage{level, message};
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                logQueue.push(logMsg);
            }
            condition.notify_one();
        }

    private:
        LogLevel currentLogLevel;
        std::vector<LogHandler> logHandlers;
        std::queue<LogMessage> logQueue;
        std::mutex queueMutex;
        std::condition_variable condition;
        bool done = false;

        void processLogs() {
            while (true) {
                LogMessage logMsg;
                {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    condition.wait(lock, [this] { return !logQueue.empty() || done; });

                    if (done && logQueue.empty()) break;

                    logMsg = logQueue.front();
                    logQueue.pop();
                }

                for (const auto& handler : logHandlers) {
                    handler(logMsg);
                }
            }
        }

    public:
        void start() {
            workerThread = std::thread(&Logger::processLogs, this);
        }

        void stop() {
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                done = true;
            }
            condition.notify_one();
            if (workerThread.joinable()) {
                workerThread.join();
            }
        }

    private:
        std::thread workerThread;
    };

    void logToConsole(const LogMessage& msg) {
        switch (msg.level) {
            case LogLevel::DEBUG: std::cout << "[DEBUG] " << msg.message << std::endl; break;
            case LogLevel::INFO:  std::cout << "[INFO] " << msg.message << std::endl; break;
            case LogLevel::WARNING: std::cout << "[WARNING] " << msg.message << std::endl; break;
            case LogLevel::ERROR: std::cerr << "[ERROR] " << msg.message << std::endl; break;
            case LogLevel::FATAL: std::cerr << "[FATAL] " << msg.message << std::endl; break;
        }
    }

    void logToFile(const LogMessage& msg, const std::string& filename) {
        static std::ofstream fileStream(filename, std::ios::app);
        if (!fileStream.is_open()) return;

        switch (msg.level) {
            case LogLevel::DEBUG: fileStream << "[DEBUG] " << msg.message << "\n"; break;
            case LogLevel::INFO:  fileStream << "[INFO] " << msg.message << "\n"; break;
            case LogLevel::WARNING: fileStream << "[WARNING] " << msg.message << "\n"; break;
            case LogLevel::ERROR: fileStream << "[ERROR] " << msg.message << "\n"; break;
            case LogLevel::FATAL: fileStream << "[FATAL] " << msg.message << "\n"; break;
        }
    }

    void logToRemoteServer(const LogMessage& msg) {
        // Simulated remote logging
        std::cout << "Logging to server: [" 
                  << (msg.level == LogLevel::DEBUG ? "DEBUG" : 
                      msg.level == LogLevel::INFO ? "INFO" :
                      msg.level == LogLevel::WARNING ? "WARNING" :
                      msg.level == LogLevel::ERROR ? "ERROR" : "FATAL") 
                  << "] " << msg.message << std::endl;
    }

} // namespace LoggingSystem

int main() {
    using namespace LoggingSystem;

    std::vector<LogHandler> handlers = { 
        logToConsole,
        [filename = "log.txt"](const LogMessage& msg) { logToFile(msg, filename); },
        logToRemoteServer
    };

    Logger logger(LogLevel::INFO, handlers);
    logger.start();

    logger.log(LogLevel::DEBUG, "This is a debug message.");
    logger.log(LogLevel::INFO, "Application started successfully.");
    logger.log(LogLevel::WARNING, "Low disk space warning.");
    logger.log(LogLevel::ERROR, "Failed to open file.");
    logger.log(LogLevel::FATAL, "Fatal error occurred!");

    std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate work

    logger.stop();

    return 0;
}
