using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
using System.Net.Http;
using System.Threading.Tasks;

namespace DynamicMapApplication
{
    public class MapSettings
    {
        public List<int> ResolutionLevels { get; set; }
        public double ZoomSensitivity { get; set; }
        public int DataRefreshInterval { get; set; } // In seconds
    }

    public class ExternalDataSource
    {
        public string Name { get; set; }
        public Uri Endpoint { get; set; }
    }

    public class CacheItem
    {
        public byte[] Data { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class MapCache
    {
        private readonly Dictionary<string, CacheItem> _cache = new();
        private readonly TimeSpan _maxAge;

        public MapCache(TimeSpan maxAge)
        {
            _maxAge = maxAge;
        }

        public bool TryGet(string key, out byte[] data)
        {
            if (_cache.TryGetValue(key, out var cacheItem))
            {
                if (DateTime.UtcNow - cacheItem.Timestamp < _maxAge)
                {
                    data = cacheItem.Data;
                    return true;
                }
                else
                {
                    _cache.Remove(key);
                }
            }

            data = null;
            return false;
        }

        public void Add(string key, byte[] data)
        {
            _cache[key] = new CacheItem { Data = data, Timestamp = DateTime.UtcNow };
        }

        // Consider adding logic to periodically clean up old cache entries
    }

    class Program
    {
        private static readonly HttpClient httpClient = new();
        private static MapSettings settings;
        private static List<ExternalDataSource> dataSources = new();
        private static MapCache mapCache;

        static async Task Main(string[] args)
        {
            LoadConfiguration("config.json");

            // Initialize cache with a max age of 5 minutes
            mapCache = new MapCache(TimeSpan.FromMinutes(5));

            // Start background task to update map data at specified intervals
            var cancellationTokenSource = new System.Threading.CancellationTokenSource();
            Task.Run(async () => await UpdateMapDataPeriodically(cancellationTokenSource.Token), cancellationTokenSource.Token);

            Console.WriteLine("Application is running. Press Enter to exit.");
            Console.ReadLine();

            cancellationTokenSource.Cancel();
        }

        private static void LoadConfiguration(string filePath)
        {
            var json = File.ReadAllText(filePath);
            settings = JsonConvert.DeserializeObject<MapSettings>(json);

            // Add logic for parsing data sources if present in JSON
        }

        private static async Task UpdateMapDataPeriodically(System.Threading.CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                try
                {
                    foreach (var dataSource in dataSources)
                    {
                        var key = GetCacheKey(dataSource);
                        byte[] data;

                        if (mapCache.TryGet(key, out data))
                        {
                            // Use cached data
                            Console.WriteLine("Using cached data from: " + dataSource.Name);
                        }
                        else
                        {
                            data = await FetchDataAsync(dataSource.Endpoint, cancellationToken);
                            mapCache.Add(key, data);
                        }

                        // Process and update the map with data...
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error updating map data: {ex.Message}");
                }

                await Task.Delay(TimeSpan.FromSeconds(settings.DataRefreshInterval), cancellationToken);
            }
        }

        private static async Task<byte[]> FetchDataAsync(Uri endpoint, System.Threading.CancellationToken cancellationToken)
        {
            using var response = await httpClient.GetAsync(endpoint, cancellationToken);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsByteArrayAsync();
        }

        private static string GetCacheKey(ExternalDataSource dataSource)
        {
            return $"{dataSource.Name}-{DateTime.UtcNow.Ticks}";
        }
    }
}
```

