public class XmlProcessor
{
    private readonly ILogger<XmlProcessor> _logger;

    public XmlProcessor(ILogger<XmlProcessor> logger)
    {
        _logger = logger;
    }

    public void ProcessXml(string xmlFilePath, string elementName, string envVarName, string directoryPath)
    {
        try
        {
            // Load XML file with deferred loading for performance
            var xmlDocument = XDocument.Load(xmlFilePath, LoadOptions.SetLineInfo | LoadOptions.DontExpandEntities);

            var elements = xmlDocument.Descendants(elementName).ToList();

            if (elements.Count > 1)
            {
                _logger.LogError($"Multiple occurrences of element '{elementName}' found in XML.");
            }

            var firstElement = elements.FirstOrDefault();
            if (firstElement != null)
            {
                // Process the first occurrence
                string value = firstElement.Value;
                _logger.LogInformation($"First occurrence of '{elementName}': {value}");
            }
            else
            {
                _logger.LogWarning($"No occurrences of element '{elementName}' found in XML.");
            }

            // Validate directory path with external service (mocked as a method call)
            bool isPathValid = ValidateDirectoryPathWithExternalService(directoryPath);
            if (!isPathValid)
            {
                _logger.LogError("Invalid directory path.");
                return;
            }

            string fullPath = Path.GetFullPath(directoryPath);

            // Manage environment variable
            string currentEnvValue = Environment.GetEnvironmentVariable(envVarName);
            if (string.IsNullOrEmpty(currentEnvValue) || !File.Exists(currentEnvValue))
            {
                Environment.SetEnvironmentVariable(envVarName, fullPath);
                _logger.LogInformation($"Set environment variable '{envVarName}' to {fullPath}.");
            }
            else
            {
                Environment.SetEnvironmentVariable(envVarName, fullPath);
                _logger.LogInformation($"Updated environment variable '{envVarName}' to {fullPath}.");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while processing the XML file.");
        }
    }

    private bool ValidateDirectoryPathWithExternalService(string directoryPath)
    {
        // Mock validation logic
