['Below is a Java implementation using Spring Boot to create a service that processes incoming text messages from an external API endpoint, computes their MD5 hashes in parallel, and integrates with a message queue for handling backlogs.

```java
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.annotation.EnableScheduling;

import java.security.MessageDigest;
import java.util.List;
import java.util.concurrent.*;
import java.util.stream.Collectors;
import org.springframework.jms.annotation.JmsListener;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import javax.jms.Message;
import javax.jms.TextMessage;

@SpringBootApplication
@EnableScheduling
public class MessageProcessingService {

    @Bean
    public ScheduledRateLimiter rateLimiter(int messagesPerMinute) {
        return new ScheduledRateLimiter(messagesPerMinute);
    }

    public static void main(String[] args) {
        SpringApplication.run(MessageProcessingService.class, args);
    }
}

@Service
class TextMessageProcessor {

    private final ExecutorService executor;
    private final ScheduledRateLimiter rateLimiter;

    @Value("${batch.size:10}")
    private int batchSize;

    public TextMessageProcessor(ScheduledRateLimiter rateLimiter) {
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.rateLimiter = rateLimiter;
    }

    @JmsListener(destination = "textMessages")
    public void processMessage(Message message) throws Exception {
        if (!(message instanceof TextMessage)) return;

        TextMessage textMessage = (TextMessage) message;
        String text = textMessage.getText();

        List<String> batch = splitBatch(text);
        for (List<String> messages : partition(batch, batchSize)) {
            rateLimiter.acquire(messages.size());
            CompletableFuture<?>[] futures = messages.stream()
                    .map(msg -> CompletableFuture.runAsync(() -> computeMD5Hash(msg), executor))
                    .toArray(CompletableFuture[]::new);

            CompletableFuture.allOf(futures).join();
        }
    }

    private List<String> splitBatch(String text) {
        // Split the incoming message into chunks if needed (up to 1024 characters)
        return List.of(text.substring(0, Math.min(text.length(), 1024)));
    }

    private <T> Iterable<List<T>> partition(List<T> list, int size) {
        final int parts = (list.size() + size - 1) / size;
        for (int i = 0; i < parts; i++) {
            final int start = i * size;
            final int end = Math.min(start + size, list.size());
            if (start >= list.size()) break;
            yield(list.subList(start, end));
        }
    }

    private void computeMD5Hash(String text) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(text.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            System.out.println("MD5: " + hexString.toString());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

class ScheduledRateLimiter {

    private final Semaphore semaphore;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public ScheduledRateLimiter(int permitsPerMinute) {
        this.semaphore = new Semaphore(permitsPerMinute);
        scheduler.scheduleAtFixedRate(this::refresh, 0, 60, TimeUnit.SECONDS);
    }

    public void acquire(int permits) throws InterruptedException {
        semaphore.acquire(permits);
    }

    private void refresh() {
        semaphore.release(semaphore.availablePermits());
    }
}
```

### Key Points:

- **Concurrency**: Utilizes a fixed thread pool for parallel processing.
- **Rate Limiting**: Uses `ScheduledRateLimiter` to limit hash computations per minute.
- **Batch Processing**: Messages are processed in configurable batch sizes.
- **Message Queue Integration**: Listens to messages from a JMS queue (`textMessages`).
- **Fault Tolerance**: Handles exceptions within the hashing function.']

['```php
<?php

session_start();

function manageUserRequest($_REQUEST) {
    $response = ['status' => 'error', 'message' => 'Invalid request'];

    // Ensure user is authenticated
    if (!isset($_SESSION['user_id'])) {
        return json_encode(['status' => 'error', 'message' => 'Unauthorized']);
    }

    $id = $_REQUEST['id'] ?? null;
    $name = $_REQUEST['name'] ?? '';
    $email = $_REQUEST['email'] ?? '';
    $password = $_REQUEST['password'] ?? '';
    $sub_action = $_REQUEST['sub_action'] ?? '';

    // Validate sub_action
    if (!in_array($sub_action, ['create', 'update', 'delete', 'fetch'])) {
        return json_encode(['status' => 'error', 'message' => 'Invalid action']);
    }

    try {
        $db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');

        switch ($sub_action) {
            case 'create':
                if (empty($name) || empty($email) || empty($password)) {
                    throw new Exception('Missing required fields for creation');
                }
                $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

                $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
                $stmt->execute([':name' => $name, ':email' => $email, ':password' => $hashedPassword]);

                if ($stmt->rowCount() > 0) {
                    $response = ['status' => 'success', 'message' => 'User created'];
                } else {
                    throw new Exception('Failed to create user');
                }
                break;

            case 'update':
                if (empty($id) || empty($name) || empty($email)) {
                    throw new Exception('Missing required fields for update');
                }

                $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
                $stmt->execute([':id' => $id]);
                $user = $stmt->fetch();

                if (!$user) {
                    throw new Exception('User not found');
                }

                $hashedPassword = !empty($password) ? password_hash($password, PASSWORD_DEFAULT) : $user['password'];

                $updateStmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
                $updateStmt->execute([':name' => $name, ':email' => $email, ':password' => $hashedPassword]);

                if ($updateStmt->rowCount() > 0) {
                    $response = ['status' => 'success', 'message' => 'User updated'];
                } else {
                    throw new Exception('Failed to update user');
                }
                break;

            case 'delete':
                if (empty($id)) {
                    throw new Exception('Missing ID for deletion');
                }

                $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
                $stmt->execute([':id' => $id]);
                $user = $stmt->fetch();

                if (!$user) {
                    throw new Exception('User not found');
                }

                $deleteStmt = $db->prepare("DELETE FROM users WHERE id = :id");
                $deleteStmt->execute([':id' => $id]);

                if ($deleteStmt->rowCount() > 0) {
                    $response = ['status' => 'success', 'message' => 'User deleted'];
                } else {
                    throw new Exception('Failed to delete user');
                }
                break;

            case 'fetch':
                if (empty($id)) {
                    throw new Exception('Missing ID for fetching');
                }

                $stmt = $db->prepare("SELECT id, name, email FROM users WHERE id = :id");
                $stmt->execute([':id' => $id]);
                $user = $stmt->fetch();

                if ($user) {
                    $response = ['status' => 'success', 'message' => 'User fetched', 'data' => $user];
                } else {
                    throw new Exception('User not found');
                }
                break;
        }
    } catch (Exception $e) {
        $response['message'] = $e->getMessage();
    }

    return json_encode($response);
}

echo manageUserRequest($_REQUEST);

