        {
            if (!ModelState.IsValid || string.IsNullOrEmpty(request.SectionId) || string.IsNullOrEmpty(request.ElementId))
                return BadRequest("Invalid input");

            try
            {
                await _pageService.BeginTransactionAsync();

                var sanitizedContent = await YourExternalService.SanitizeContentAsync(request.Content);

                bool updateSuccess = await _pageService.UpdateElementContentAsync(
                    request.SectionId, request.ElementId, sanitizedContent);

                if (updateSuccess)
                {
                    await _notificationQueue.EnqueueUpdateNotificationAsync(request.SectionId, request.ElementId);
                }

                await _pageService.CommitTransactionAsync();

                var shouldRefreshImmediately = CheckClientCapabilitiesAndNetwork();

                return Ok(new { refresh = shouldRefreshImmediately });
