const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const glob = require('glob');
const validate = require('jsonschema').validate;
const asyncPool = require('tiny-async-pool');

const readFileAsync = promisify(fs.readFile);
const readdirAsync = promisify(fs.readdir);

const MAX_CONCURRENT_FILES = 10;

let cache = new Map();

async function processFiles(directory, schema) {
    const files = glob.sync(path.join(directory, '**', '*.*'));
    let validCount = 0;
    let invalidCount = 0;

    async function processFile(file) {
        try {
            if (cache.has(file)) {
                return cache.get(file);
            }

            const content = await readFileAsync(file, 'utf-8');
            const data = JSON.parse(content);

            const validationResult = validate(data, schema);
            const isValid = validationResult.valid;

            cache.set(file, isValid);

            return isValid ? validCount++ : invalidCount++;
        } catch (error) {
            console.error(`Error processing file ${file}:`, error.message);
            return invalidCount++;
        }
    }

    await asyncPool(MAX_CONCURRENT_FILES, files, processFile);

    return { valid: validCount, invalid: invalidCount };
}

// Example usage
const schema = {
    type: "object",
    properties: {
        name: { type: "string" },
        age: { type: "number" }
    },
    required: ["name", "age"]
};

processFiles('./path/to/directory', schema)
    .then(summary => console.log('Summary:', summary))
    .catch(error => console.error('Error:', error));
```

Note:
- Ensure you have `tiny-async-pool` and `jsonschema` installed in your project (`npm install tiny-async-pool jsonschema`).
- Adjust `MAX_CONCURRENT_FILES` based on system resources.
- The caching mechanism uses a simple JavaScript Map to store validation results.']

["```javascript
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const log4js = require('log4js');
const blueslip = require('blueslip');

const readFileAsync = promisify(fs.readFile);
const lstatAsync = promisify(fs.lstat);

let testSuite = {
  total: 0,
  passed: 0,
  failed: 0,
  retried: 0,
};

log4js.configure({
  appenders: { out: { type: 'file', filename: 'test-log.log' } },
  categories: { default: { appenders: ['out'], level: 'info' } }
});
const logger = log4js.getLogger();

async function loadModules(dir) {
  const files = await readdirAsync(dir);
  let modules = {};

  for (let file of files) {
    const filePath = path.join(dir, file);
    const stat = await lstatAsync(filePath);

    if (stat.isDirectory()) {
      modules[file] = await loadModules(filePath);
    } else if (file.endsWith('.js')) {
      try {
        modules[file.replace('.js', '')] = require(filePath);
      } catch (error) {
        logger.error(`Failed to load module ${filePath}: ${error.message}`);
      }
    }
  }

  return modules;
}

async function runTest(testDir, label, f, timeout) {
  const startTime = Date.now();
  let attempt = 0;

  async function execute() {
    if (attempt > 2) throw new Error('Max retries reached');

    try {
      await blueslip.resetToInitialState();
      await promisify(setImmediate)(() => f());
      testSuite.passed++;
    } catch (error) {
      logger.error(`Test failed on attempt ${attempt + 1}: ${label}`, { error });

      if (isTransientError(error)) {
        attempt++;
        testSuite.retried++;
        logger.info(`Retrying test: ${label}, Attempt: ${attempt}`);
        await execute();
      } else {
        testSuite.failed++;
      }
    } finally {
      blueslip.resetToInitialState();

      const endTime = Date.now();
      if (endTime - startTime > timeout) {
        logger.warn(`Test exceeded timeout: ${label}`);
      }

      const remainingTime = timeout - (endTime - startTime);
      setTimeout(async () => {
        await execute();
      }, Math.max(0, remainingTime));
    }
  }

  testSuite.total++;
  await execute();
}

async function runTests(testDir) {
  const modules = await loadModules(testDir);

  const promises = Object.keys(modules).map((key) => 
    runTest(testDir, key, modules[key].testFunction || async () => {}, 5000)
  );

  try {
    await Promise.all(promises);
    console.log('Test Suite Summary:', testSuite);
  } catch (error) {
    logger.error(`Unexpected error during tests: ${error.message}`);
  }
}

async function readdirAsync(directory) {
  return promisify(fs.readdir)(directory, { withFileTypes: true });
}

function isTransientError(error) {
  // Implement logic to determine if the error is transient
  return ['NetworkError', 'TimeoutError'].includes(error.name);
}
```

This JavaScript module provides an implementation for executing a suite of tests in an asynchronous environment. It dynamically loads modules from a specified directory, handles circular dependencies with recursive loading, and manages test execution including retries for transient failures. A global `testSuite` object tracks progress and results while `blueslip` is reset after each test to maintain state integrity. Logging captures detailed information without overwhelming the system. The module ensures tests are executed within a timeout limit, retrying failed tests up to three times for transient errors."]

