// Import necessary libraries
const natural = require('natural');
const axios = require('axios');

class ContractProcessor {
  constructor(config) {
    this.config = config;
    this.stopWords = new Set(natural.stopwords.words());
    this.tfidf = new natural.TfIdf();
  }

  async loadDocuments(documents) {
    return documents.map(document => this.normalizeText(document));
  }

  normalizeText(text) {
    // Remove punctuation, special characters and convert to lowercase
    text = text.toLowerCase().replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ");

    // Tokenize and remove stop words
    let tokens = natural.wordTokenizer.tokenize(text);
    return tokens.filter(token => !this.stopWords.has(token));
  }

  async fetchTermDefinitions() {
    const response = await axios.get(this.config.termDefinitionsUrl);
    this.definitions = response.data;
  }

  extractTerms(documents) {
    documents.forEach(document => {
      document.forEach(word => {
        this.tfidf.addDocument([word]);
      });
    });

    let results = {};
    Object.keys(this.definitions).forEach(term => {
      const termRegex = new RegExp(`\\b${term}\\b`, 'g');
      this.tfidf.listTerms(0, (item) => {
        if (item.term.match(termRegex)) {
          results[term] = (results[term] || 0) + item.tfidf;
        }
      });
    });

    return results;
  }

  process(documents) {
    // Normalize and process documents
    const normalizedDocs = this.loadDocuments(documents);

    // Extract terms based on predefined configurations or fetched definitions
    if (!this.definitions && this.config.termDefinitionsUrl) {
      throw new Error("Term definitions URL must be configured.");
    } else if (!this.definitions) {
      return this.extractTerms(normalizedDocs);
    }

    const results = {};
    normalizedDocs.forEach((doc, index) => {
      Object.keys(this.definitions).forEach(term => {
        const termRegex = new RegExp(`\\b${term}\\b`, 'g');
        const matches = doc.filter(word => word.match(termRegex));
        if (matches.length > 0 && !this.config.exclusions.includes(matches[0])) {
          results[term] = (results[term] || 0) + this.tfidf.tfidfs(index, [matches[0]])[0].tfidf;
        }
      });
    });

    return results;
  }

  async initialize() {
    if (this.config.termDefinitionsUrl) {
      await this.fetchTermDefinitions();
    }
  }
}

// Example usage
const config = {
  termDefinitionsUrl: 'https://api.example.com/definitions',
  exclusions: ['exampleExclusion']
};

(async () => {
  const processor = new ContractProcessor(config);
  await processor.initialize();

  const documents = [
    // Large corpus of legal contracts and policies as strings
  ];

  const results = processor.process(documents);
  console.log(results);
})();
