function integrateScripts(scripts) {
    const footer = document.querySelector('footer') || document.createElement('footer');
    document.body.appendChild(footer);

    // Helper function to generate a unique ID if there's a conflict
    function generateUniqueID(baseId, existingIds) {
        let uniqueId = baseId;
        let counter = 1;
        while (existingIds.includes(uniqueId)) {
            uniqueId = `${baseId}-${counter++}`;
        }
        return uniqueId;
    }

    // Collect all existing script IDs to check for conflicts
    const existingScriptIds = Array.from(document.querySelectorAll('script'))
        .map(script => script.id || '');

    scripts.forEach((scriptObj, index) => {
        if (typeof scriptObj !== 'object' || scriptObj === null) return;

        let { id = `default-id-${index}`, src = '', type = 'text/javascript' } = scriptObj;

        // Handle ID conflicts
        const uniqueId = generateUniqueID(id, existingScriptIds);

        // Create the script element
        const scriptElement = document.createElement('script');
        scriptElement.id = uniqueId;
        if (src) scriptElement.src = src;
        scriptElement.type = type;

        footer.appendChild(scriptElement);

        // Update existing IDs list to include new ID
        existingScriptIds.push(uniqueId);
    });

    return new XMLSerializer().serializeToString(footer).replace(/\n/g, '').trim();
}

// Example usage:
const scriptsArray = [
    { id: 'main', src: 'https://example.com/main.js' },
    { src: 'https://cdn.example.com/helper.js', type: 'module' },
    // Add more script objects as needed
];

console.log(integrateScripts(scriptsArray));
