// AngularJS Controller Function for Dynamic Dialog Refresh

app.controller('DialogController', ['$scope', '$http', function($scope, $http) {
    const resourceIds = ['id1', 'id2']; // Example resource IDs
    const fieldsToRefresh = ['nameField', 'descriptionField'];
    const urls = {
        nameField: '/api/name',
        descriptionField: '/api/description'
    };

    $scope.dialogFields = {
        nameField: '',
        descriptionField: ''
    };

    async function refreshDialogFields() {
        try {
            const requests = resourceIds.map(async (resourceId) => {
                for (const field of fieldsToRefresh) {
                    if ($scope.dialogFields[field]) {
                        const response = await $http.get(`${urls[field]}?id=${resourceId}`);

                        // Handle unexpected responses
                        if (!response.data || !response.data.value) {
                            console.error(`Unexpected response structure for ${field}:`, response);
                            continue;
                        }

                        $scope.dialogFields[field] = response.data.value; 
                    }
                }
            });

            await Promise.all(requests);
        } catch (error) {
            console.error('Error during field refresh:', error);
        }
    }

    // Call the function to refresh fields
    refreshDialogFields();
}]);
