import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class FileProcessor {

    private static final Logger logger = Logger.getLogger(FileProcessor.class.getName());
    private final ConcurrentMap<String, Integer> fileTypeCountCache = new ConcurrentHashMap<>();
    private final MetadataService metadataService = new MetadataServiceImpl();
    private final int cacheSize = 1000; // Adjust size based on memory considerations

    public Map<String, Long> processFileList(List<Path> filePaths) {
        long startTime = System.nanoTime();

        Map<String, Long> fileTypeCounts = new ConcurrentHashMap<>();

        for (Path filePath : filePaths) {
            if (filePath == null || !Files.exists(filePath)) continue;

            String extension = getFileExtension(filePath);
            if (extension == null || extension.isEmpty()) continue;

            String typeKey = "type:" + extension;
            Integer cachedCount = fileTypeCountCache.get(typeKey);

            if (cachedCount != null) {
                fileTypeCounts.merge(typeKey, cachedCount, Long::sum);
                continue;
            }

            try {
                Metadata metadata = metadataService.retrieveMetadata(filePath.toUri());
                String fileCategory = categorizeFile(metadata);

                fileTypeCountCache.putIfAbsent(fileCategory, 1);
                fileTypeCounts.merge(fileCategory, 1L, Long::sum);

            } catch (IOException | RateLimitExceededException e) {
                logger.warning("Failed to process " + filePath + ": " + e.getMessage());
                // Handle rate limit or retry logic if necessary
            }
        }

        cleanupCache();

        long endTime = System.nanoTime();
        logger.info("Processing completed in " + (endTime - startTime) / 1_000_000.0 + " ms");

        return fileTypeCounts;
    }

    private String getFileExtension(Path path) {
        String fileName = path.getFileName().toString();
        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex > 0 && dotIndex < fileName.length() - 1) {
            return fileName.substring(dotIndex + 1);
        }
        return null;
    }

    private String categorizeFile(Metadata metadata) throws IOException {
        // Use regex or other logic to determine the file category based on metadata
        Pattern pattern = Pattern.compile(".*\\.jpg|jpeg");
        if (pattern.matcher(metadata.getExtension()).matches()) {
            return "image/jpeg";
        }
        // Add more patterns as necessary
        return "other/" + metadata.getExtension();
    }

    private void cleanupCache() {
        if (fileTypeCountCache.size() > cacheSize) {
            fileTypeCountCache.keySet().removeIf(key -> fileTypeCountCache.values().stream().min(Long::compare).orElse(1L) == 1);
        }
    }
}

class MetadataService {

    public Metadata retrieveMetadata(String uri) throws IOException, RateLimitExceededException {
        // Simulate latency and rate limits
        try {
            Thread.sleep((long) (Math.random() * 100)); // Simulating network delay
            return new Metadata(uri.substring(uri.lastIndexOf('.') + 1));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Metadata retrieval interrupted", e);
        }
    }

}

class MetadataServiceImpl extends MetadataService {}

class Metadata {
    private final String extension;

    public Metadata(String extension) {
        this.extension = extension;
    }

    public String getExtension() {
        return extension;
    }
}

class RateLimitExceededException extends Exception {
    public RateLimitExceededException(String message) {
        super(message);
    }
}
```

