            current_load = len(self.cache) / self.cache.maxsize
            if current_load > threshold:
                # Cleanup strategy based on LRU
                while current_load > threshold and self.cache:
                    self.cache.popitem(last=False)
                    current_load = len(self.cache) / self.cache.maxsize

