        ServiceInstance instance = new ServiceInstance(id, messagingSystem, configManager, healthMonitor);
        serviceInstances.put(id, instance);
        executorService.submit(instance::run);
    }

    private void adjustServiceParameters() {
        for (ServiceInstance instance : serviceInstances.values()) {
            instance.updateConfig(configManager.getConfigForInstance(instance.getId()));
        }
    }

