        ExternalConfigManager configManager = new ExternalConfigManager();
        MessagingSystem messagingSystem = new MessagingSystem();

        FleetManager manager = new FleetManager(configManager, messagingSystem);
        manager.start();

        // Add services
        for (int i = 0; i < 500; i++) {
            manager.addServiceInstance("service-" + i);
        }
    }
}

