<?php

// Step 1: Manage Environment Variables
function loadEnvironmentVariables($envFile) {
    if (!file_exists($envFile)) {
        throw new Exception("Environment file not found.");
    }

    $envVars = parse_ini_file($envFile, true);
    foreach ($envVars as $key => $value) {
        putenv("$key=$value");
        $_ENV[$key] = $value;
        $_SERVER[$key] = $value;
    }
}

loadEnvironmentVariables(__DIR__ . '/.env');

// Step 2: Dynamically Load Dependencies
function loadDependencies($dependenciesFile) {
    if (!file_exists($dependenciesFile)) {
        throw new Exception("Dependencies file not found.");
    }

    $dependencies = json_decode(file_get_contents($dependenciesFile), true);
    foreach ($dependencies as $package => $version) {
        // Assume Composer autoloader is available
        require_once __DIR__ . '/vendor/autoload.php';
    }
}

loadDependencies(__DIR__ . '/dependencies.json');

// Step 3: Configurations with JSON
function loadConfiguration($configFile, $env) {
    if (!file_exists($configFile)) {
        throw new Exception("Config file not found.");
    }

    $config = json_decode(file_get_contents($configFile), true);
    $envConfigFile = __DIR__ . "/{$env}.json";

    if (file_exists($envConfigFile)) {
        $envConfig = json_decode(file_get_contents($envConfigFile), true);
        $config = array_merge($config, $envConfig);
    }

    return $config;
}

$config = loadConfiguration(__DIR__ . '/config.json', getenv('APP_ENV'));

// Step 4: Caching Mechanism
class Cache {
    private $cacheDir;

    public function __construct($dir) {
        $this->cacheDir = $dir;
    }

    public function get($key, $expiration = 3600) {
        $filePath = "{$this->cacheDir}/{$key}.cache";

        if (file_exists($filePath) && (time() - filemtime($filePath)) < $expiration) {
            return unserialize(file_get_contents($filePath));
        }

        return null;
    }

    public function set($key, $data, $expiration = 3600) {
        $filePath = "{$this->cacheDir}/{$key}.cache";
        file_put_contents($filePath, serialize($data), LOCK_EX);
    }
}

$cache = new Cache(__DIR__ . '/cache');

// Step 5: Logging Mechanism
class Logger {
    private $logFile;

    public function __construct($file) {
        $this->logFile = $file;
    }

    public function log($message, $level = 'INFO') {
        $formattedMessage = sprintf("[%s] %s: %s\n", date('Y-m-d H:i:s'), strtoupper($level), $message);
        file_put_contents($this->logFile, $formattedMessage, FILE_APPEND | LOCK_EX);

        if (filesize($this->logFile) > 1024 * 1024) { // Rotate logs larger than 1MB
            rename($this->logFile, "{$this->logFile}." . time());
        }
    }

    public function filterLogs($minLevel = 'INFO') {
        $levelsOrder = ['DEBUG', 'INFO', 'WARN', 'ERROR'];
        $indexMinLevel = array_search(strtoupper($minLevel), $levelsOrder);

        if ($indexMinLevel === false) return [];

        $logs = file_get_contents($this->logFile);
        preg_match_all('/\[(.*?)\] (.*?): (.*)/', $logs, $matches);

        $filteredLogs = [];
        foreach ($matches[1] as $i => $level) {
            if ($levelsOrder[array_search(strtoupper($level), $levelsOrder)] >= $indexMinLevel) {
                $filteredLogs[] = [
                    'timestamp' => $matches[0][$i],
                    'level' => $matches[1][$i],
                    'message' => $matches[3][$i]
                ];
            }
        }

        return $filteredLogs;
    }
}

$logger = new Logger(__DIR__ . '/app.log');

