<?php

function handleFileAndGenerateString($stringLength, $characterSet, $directoryPath, $timeoutSeconds = 5) {
    // Cache to store frequently accessed files
    static $fileCache = [];

    // Generate random unique string
    function generateRandomUniqueString($length, $characters) {
        if ($length > strlen($characters)) {
            throw new Exception("Length exceeds the number of unique characters available.");
        }

        $charactersArray = str_split($characters);
        shuffle($charactersArray);

        return implode('', array_slice($charactersArray, 0, $length));
    }

    // Handle file reading with timeout and caching
    function readFileWithTimeout($filePath, $timeout) {
        global $fileCache;

        if (isset($fileCache[$filePath])) {
            return $fileCache[$filePath];
        }

        $startTime = time();

        if (!is_readable($filePath)) {
            throw new Exception("File is not readable.");
        }

        ob_start();
        set_time_limit(0);

        $handle = fopen($filePath, 'rb');
        if (!$handle) {
            throw new Exception("Unable to open file.");
        }

        stream_set_blocking($handle, true);

        // Read the file in chunks to manage memory usage
        while (!feof($handle)) {
            if (time() - $startTime > $timeout) {
                ob_end_clean();
                fclose($handle);
                return "File reading operation timed out.";
            }

            echo fread($handle, 8192); // Adjust chunk size as necessary

            flush(); // Ensure data is sent to the output buffer
        }

        $content = ob_get_clean();
        fclose($handle);

        $fileCache[$filePath] = $content;

        return $content;
    }

    try {
        if (!is_dir($directoryPath)) {
            throw new Exception("Directory does not exist.");
        }

        // Generate random string
        $randomString = generateRandomUniqueString($stringLength, $characterSet);

        // Read file with timeout handling
        $filePath = rtrim($directoryPath, '/') . '/targetfile.txt'; // Assuming 'targetfile.txt' is the target file in the directory

        if (!file_exists($filePath)) {
            throw new Exception("File does not exist.");
        }

        $fileContent = readFileWithTimeout($filePath, $timeoutSeconds);

    } catch (Exception $e) {
        return "Error: " . $e->getMessage();
    }

    return [
        'randomString' => $randomString,
        'fileContent' => $fileContent
    ];
}
