async function combineOAuthData(oauthRequest) {
  const { privateKeyPath, certificatePath } = oauthRequest;

  let isPaused = false;
  let buffer = [];
  let bufferSizeLimit = 10 * 1024 * 1024; // Limit to 10MB for example

  const loadResourceAsync = async (path) => {
    try {
      const response = await fetch(path);
      if (!response.ok) throw new Error(`Failed to load resource from ${path}`);
      return await response.text();
    } catch (error) {
      console.error(error);
      throw error;
    }
  };

  const pauseStream = () => isPaused = true;
  const resumeStream = () => isPaused = false;

  const processStreamData = async (dataStream) => {
    for await (const chunk of dataStream) {
      if (isPaused) await new Promise(resolve => setTimeout(resolve, 100));

      buffer.push(chunk);
      if (Buffer.concat(buffer).length > bufferSizeLimit) {
        console.warn('Buffer size limit exceeded');
        pauseStream();
      }
    }

    const combinedData = Buffer.concat(buffer).toString();
    return combinedData;
  };

  try {
    const [privateKey, certificate] = await Promise.all([
      loadResourceAsync(privateKeyPath),
      loadResourceAsync(certificatePath)
    ]);

    // Assuming dataStream is available from some source for demonstration
    let dataStream; // Replace with actual stream source

    const combinedPemData = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n\n`
                   + `-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----\n`;

    const additionalDataStream = await processStreamData(dataStream);

    return combinedPemData + additionalDataStream;
  } catch (error) {
    console.error('Error during PEM combination:', error);
    throw error;
  }
}
