#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to fetch data from an API using OAuth2 token
static void fetchUserData(const char* url, const char* session_token) {
    CURL *curl;
    CURLcode res;

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Authorization: Bearer ");
    headers = curl_slist_append(headers, session_token);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_URL, url);

        // Response handling
        MemoryStruct chunk;
        chunk.data = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void *ptr, size_t size, size_t nmemb, void *userp) -> size_t {
            MemoryStruct *mem = (MemoryStruct *) userp;

            char *ptr_old = mem->data;

            size_t new_size = mem->size + size*nmemb;
            mem->data = realloc(mem->data, new_size+1);
            if (mem->data == NULL) {
                // out of memory!
                fprintf(stderr, "not enough memory (realloc returned NULL)\n");
                return 0;
            }

            memcpy(&(mem->data[mem->size]), ptr, size*nmemb);
            mem->size = new_size;
            mem->data[new_size] = '\0';

            return size*nmemb;
        });

        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Use chunk.data and chunk.size
            printf("Data received: %.*s\n", (int)chunk.size, chunk.data);
        }

        free(chunk.data);

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

// Function to resolve hostname to IP address with retry logic
static int resolveHostnameToIP(const char* hostname, u_char *ip_array) {
    struct addrinfo hints, *res, *p;
    int status, retries = 0;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    while (retries < MAX_RETRIES) {
        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) == 0) {
            for(p = res; p != NULL; p = p->ai_next) {
                void *addr;
                struct sockaddr_in *ipv4;

                if (p->ai_family == AF_INET) { // Check it is IP version 4
                    ipv4 = (struct sockaddr_in *) p->ai_addr;
                    addr = &(ipv4->sin_addr);
                    inet_ntop(p->ai_family, addr, ip_array, INET_ADDRSTRLEN);

                    freeaddrinfo(res); // Free the linked list
                    return 0; // Success
                }
            }
        } else {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        }

        retries++;
        sleep(RETRY_DELAY);
    }

    freeaddrinfo(res);
    return -1; // Failure after retries
}

// Main function to resolve hostname and fetch user data
void resolveAndFetch(const char* hostname, const char* api_url, const char* session_token) {
    u_char ip_array[INET_ADDRSTRLEN];

    if (resolveHostnameToIP(hostname, ip_array)) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", hostname);
        return;
    }

    printf("Resolved IP address: %s\n", ip_array);

    // Ensure thread safety with a mutex lock
    pthread_mutex_lock(&mutex);
    fetchUserData(api_url, session_token);
    pthread_mutex_unlock(&mutex);
}

int main() {
    const char *hostname = "example.com";
    const char *api_url = "https://api.example.com/userdata";
    const char *session_token = "your_access_token";

    resolveAndFetch(hostname, api_url, session_token);

    return 0;
}
```

This code implements a C function that resolves a hostname to an IP address and fetches user data from an external API using OAuth2. It handles DNS resolution errors with retry logic, manages concurrent requests using a mutex for thread safety, and provides detailed logging without exposing sensitive information. The code is modular and designed for maintainability.']

['```php
<?php

class PasswordManager {
    private $db;
    private $authServiceApiKey;
    private $logServiceEndpoint;
    private const PASSWORD_HISTORY_LIMIT = 5;
    private const RATE_LIMIT_ATTEMPTS = 3; // Max attempts per minute
    private const MAX_RETRY_DELAY = 60; // Maximum retry delay in seconds

    public function __construct($db, $authServiceApiKey, $logServiceEndpoint) {
        $this->db = $db;
        $this->authServiceApiKey = $AuthServiceApiKey;
        $this->logServiceEndpoint = $LogServiceEndpoint;
    }

    public function updatePassword(int $userId, string $newPassword): array {
        try {
            // Start transaction
            $this->db->beginTransaction();

            // Lock the user's row to handle concurrency
            $user = $this->fetchUserWithLock($userId);
            if (!$user) throw new Exception("User not found.");

            // Check rate limiting
            if ($this->isRateLimited($userId)) {
                throw new Exception("Too many requests. Please try again later.");
            }

            // Password history management
            if ($this->isPasswordUsedRecently($userId, $newPassword)) {
                throw new Exception("This password has been used recently. Please choose a different one.");
            }

            // Hash the new password (for simplicity, using bcrypt)
            $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);

            // Update password in local database
            $this->updateUserPasswordInDb($userId, $hashedPassword);

            // Integrate with external authentication service
            if (!$this->updatePasswordExternalAuthService($userId, $hashedPassword)) {
                throw new Exception("Failed to update the password on the external service.");
            }

            // Commit transaction
            $this->db->commit();

            // Log success
            $this->logEvent('SUCCESS', $userId);

            return ['status' => 'success', 'message' => "Password updated successfully."];

        } catch (Exception $e) {
            // Rollback in case of error
            $this->db->rollBack();

            // Log failure
            $this->logEvent('FAILURE', $userId, $e->getMessage());

            return ['status' => 'error', 'message' => $e->getMessage()];
        }
    }

    private function fetchUserWithLock(int $userId) {
        return $this->db->query("SELECT * FROM users WHERE id = ? FOR UPDATE", [$userId])->fetch();
    }

    private function isRateLimited(int $userId): bool {
        $attempts = $this->getRecentAttempts($userId);
        return count($attempts) >= self::RATE_LIMIT_ATTEMPTS;
    }

    private function getRecentAttempts(int $userId): array {
        return $this->db->query("SELECT * FROM password_attempts WHERE user_id = ? AND timestamp > NOW() - INTERVAL 1 MINUTE", [$userId])->fetchAll();
    }

    private function isPasswordUsedRecently(int $userId, string $newPassword): bool {
        $recentPasswords = $this->db->query("SELECT password_hash FROM password_history WHERE user_id = ? ORDER BY used_at DESC LIMIT ?", [$userId, self::PASSWORD_HISTORY_LIMIT])->fetchAll(PDO::FETCH_COLUMN);

        foreach ($recentPasswords as $hash) {
            if (password_verify($newPassword, $hash)) return true;
        }

        return false;
    }

    private function updateUserPasswordInDb(int $userId, string $hashedPassword) {
        $this->db->query("UPDATE users SET password_hash = ? WHERE id = ?", [$hashedPassword, $userId]);
    }

    private function updatePasswordExternalAuthService(int $userId, string $hashedPassword): bool {
        $attempts = 0;
        do {
            try {
                $response = file_get_contents($this->logServiceEndpoint . "/update-password", false, stream_context_create([
                    'http' => [
                        'method' => 'POST',
                        'header' => "Authorization: Bearer {$this->authServiceApiKey}\r\nContent-Type: application/json",
                        'content' => json_encode(['userId' => $userId, 'passwordHash' => $hashedPassword])
                    ]
                ]));

                if ($response === FALSE || !($json = json_decode($response)) || $json->success !== true) {
                    throw new Exception("Failed to connect to external authentication service.");
                }

                return true;
            } catch (Exception $e) {
                sleep(pow(2, $attempts)); // Exponential backoff
                if ($attempts++ >= 5) break; // Limit retries
            }
        } while (true);

        return false;
    }

    private function logEvent(string $status, int $userId, string $message = '') {
        file_put_contents('password_changes.log', sprintf("[%s] %s - UserID: %d - Message: %s\n", date("Y-m-d H:i:s"), $status, $userId, $message), FILE_APPEND);
    }
}
```

This implementation includes password history management, rate limiting, concurrency handling with database row locking, and integration with an external authentication service with retry logic. It provides robust logging for monitoring and feedback to the user upon success or failure of a password change attempt. The code follows best practices by using transactions for atomic operations and ensuring that resources are managed efficiently.']

['Here's a C implementation that addresses the given requirements for dynamically managing state lists within a finite state automaton (FSA):

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STATE_LENGTH 1000

typedef struct {
    int *states;
    size_t length;
} StateList;

typedef struct {
    int *state_table; // Array of valid states
    size_t num_states;
    pthread_mutex_t lock;
} FSA;

int is_valid_state(FSA *fsa, int state) {
    for (size_t i = 0; i < fsa->num_states; ++i) {
        if (fsa->state_table[i] == state) {
            return 1;
        }
    }
    return 0;
}

StateList* create_state_list(FSA *fsa, int *input_states, size_t num_input_states, size_t max_length) {
    if (!fsa || !input_states || num_input_states == 0 || max_length == 0) {
        return NULL;
    }

    pthread_mutex_lock(&fsa->lock);

    StateList *state_list = (StateList *)malloc(sizeof(StateList));
    if (!state_list) {
        pthread_mutex_unlock(&fsa->lock);
        return NULL;
    }

    state_list->states = (int *)malloc(max_length * sizeof(int));
    if (!state_list->states) {
        free(state_list);
        pthread_mutex_unlock(&fsa->lock);
        return NULL;
    }

    size_t valid_state_count = 0;

    for (size_t i = 0; i < num_input_states && valid_state_count < max_length; ++i) {
        if (!is_valid_state(fsa, input_states[i])) {
            pthread_mutex_unlock(&fsa->lock);
            free(state_list->states);
            free(state_list);
            return NULL;
        }
        state_list->states[valid_state_count++] = input_states[i];
    }

    state_list->length = valid_state_count;

    pthread_mutex_unlock(&fsa->lock);

    if (valid_state_count == 0) {
        free(state_list->states);
        free(state_list);
        return NULL;
    }

    return state_list;
}

void deallocate_state_list(StateList *state_list) {
    if (!state_list) return;

    free(state_list->states);
    free(state_list);
}

int main() {
    // Example usage
    int valid_states[] = {0, 1, 2, 3, 4};
    FSA fsa = {.state_table = valid_states, .num_states = 5, .lock = PTHREAD_MUTEX_INITIALIZER};

    int input_states[] = {0, 2, 4};
    StateList *state_list = create_state_list(&fsa, input_states, 3, MAX_STATE_LENGTH);

    if (state_list) {
        printf("State list created with %zu states.\n", state_list->length);
        for (size_t i = 0; i < state_list->length; ++i) {
            printf("%d ", state_list->states[i]);
        }
        printf("\n");
        deallocate_state_list(state_list);
    } else {
        printf("Failed to create state list.\n");
    }

    pthread_mutex_destroy(&fsa.lock);

    return 0;
}
```

### Key Points:
- **State Validation**: The `is_valid_state` function checks if a given state exists in the FSA's state table.
- **Resource Management**: Limits the number of states in the list to `max_length`.
- **Concurrency Handling**: Uses a mutex (`pthread_mutex_t`) for synchronizing access to the FSA structure.
- **Performance Optimization**: Allocates memory once and checks validity before adding states.
- **Scalability Considerations**: Designed to handle large state lists efficiently.
- **Resource Deallocation**: Provides `deallocate_state_list` function to free allocated resources.
- **Error Handling**: Returns `NULL` on errors, such as invalid inputs or insufficient memory.
- **Configuration Flexibility**: Uses a configurable `max_length` for the maximum number of states in the list.']

