#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DEVICES 1000
#define INITIAL_WINDOW_SIZE 100

typedef struct {
    time_t timestamp;
    double value;
    char device_id[50];
} DataPoint;

typedef struct Node {
    DataPoint data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    double sum_values;
    double squared_sum_values;
} SlidingWindow;

typedef struct {
    char device_id[50];
    SlidingWindow window;
    double peak_value;
    time_t last_update;
} DeviceData;

DeviceData devices[MAX_DEVICES];
int num_devices = 0;

void init_device_data(DeviceData* device, const char* id) {
    strcpy(device->device_id, id);
    device->window.head = NULL;
    device->window.tail = NULL;
    device->window.size = 0;
    device->window.sum_values = 0.0;
    device->window.squared_sum_values = 0.0;
    device->peak_value = -1.0;
    device->last_update = 0;
}

void add_data_point(DeviceData* device, const DataPoint* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // handle memory allocation failure
    new_node->data = *data;

    // Add to sliding window
    if (device->window.size == 0) {
        device->window.head = new_node;
        device->window.tail = new_node;
    } else {
        device->window.tail->next = new_node;
        device->window.tail = new_node;
    }
    device->window.size++;

    // Update statistics
    double value = data->value;
    if (value > device->peak_value) {
        device->peak_value = value;
    }

    device->window.sum_values += value;
    device->window.squared_sum_values += value * value;

    // Remove old entries based on time and adjust window size dynamically
    Node* current = device->window.head;
    while (current != NULL && difftime(data->timestamp, current->data.timestamp) > 60) { // 1 minute window
        if (current == device->window.head) {
            device->window.head = current->next;
            free(current);
            current = device->window.head;
        } else {
            Node* to_free = current;
            current = current->next;
            free(to_free);
        }
        device->window.size--;
    }

    // Adjust window size based on system load (simplified logic)
    int dynamic_window_size = INITIAL_WINDOW_SIZE; 
    if (device->window.size > dynamic_window_size) {
        while (current != NULL && difftime(data->timestamp, current->data.timestamp) < 60 &&
               device->window.size > dynamic_window_size / 2) {
            Node* to_free = current;
            current = current->next;
            free(to_free);
            device->window.size--;
        }
    }

    // Update last update time
    device->last_update = data->timestamp;
}

double calculate_average_variance(DeviceData* device) {
    if (device->window.size <= 1) return 0.0;
    double mean = device->window.sum_values / device->window.size;
    double variance = (device->window.squared_sum_values - 
                       2 * mean * device->window.sum_values + 
                       mean * mean * device->window.size) / 
                      (device->window.size - 1);
    return variance;
}

void process_data_point(const DataPoint* data) {
    for (int i = 0; i < num_devices; ++i) {
        if (strcmp(devices[i].device_id, data->device_id) == 0) {
            add_data_point(&devices[i], data);
            return;
        }
    }

    // If device not found, initialize new device
    if (num_devices < MAX_DEVICES) {
        init_device_data(&devices[num_devices++], data->device_id);
        add_data_point(&devices[num_devices - 1], data);
    }
}

void print_metrics() {
    for (int i = 0; i < num_devices; ++i) {
        printf("Device: %s, Peak Value: %.2f, Average Variance: %.6f\n",
               devices[i].device_id,
               devices[i].peak_value,
               calculate_average_variance(&devices[i]));
    }
}

int main() {
    // Simulate incoming data
    for (int i = 0; i < 10000; ++i) {
        DataPoint data;
        time_t now = time(NULL);
        data.timestamp = now - rand() % 120; // simulate up to 2 minutes old data
        data.value = rand() / (double)RAND_MAX * 100.0;
        snprintf(data.device_id, sizeof(data.device_id), "Device%d", rand() % MAX_DEVICES);

        process_data_point(&data);
    }

    print_metrics();

    return 0;
}
