#include <chrono>
#include <mutex>
#include <algorithm>

// Global variables to track the last execution time of each maneuver.
std::vector<std::chrono::steady_clock::time_point> last_execution_times(3);
std::mutex mtx; // Mutex for synchronizing access to shared resources.

const int COOLDOWN_PERIOD = 9;
const int BALANCE_PERIOD = 30;

void select_offensive_maneuver() {
    std::lock_guard<std::mutex> lock(mtx); // Ensure thread-safe access.

    auto current_time = std::chrono::steady_clock::now();
    std::vector<int> eligible_moves; // Stores indices of maneuvers that can be used.

    for (int i = 0; i < last_execution_times.size(); ++i) {
        if (std::chrono::duration_cast<std::chrono::seconds>(
                current_time - last_execution_times[i]).count() >= COOLDOWN_PERIOD) {
            eligible_moves.push_back(i);
        }
    }

    // If no move is eligible, relax the constraint to allow any move.
    if (eligible_moves.empty()) {
        for (int i = 0; i < last_execution_times.size(); ++i) {
            if (std::chrono::duration_cast<std::chrono::seconds>(
                    current_time - last_execution_times[i]).count() >= BALANCE_PERIOD) {
                eligible_moves.push_back(i);
            }
        }
    }

    // If still no move is available, choose the first one that can be used.
    if (eligible_moves.empty()) {
        for (int i = 0; i < last_execution_times.size(); ++i) {
            eligible_moves.push_back(i);
        }
    }

    // Randomly select a maneuver from eligible ones to ensure fairness over time.
    int selected_move = eligible_moves[rand() % eligible_moves.size()];
    std::cout << "Selected Maneuver: " << selected_move + 1 << std::endl;

    last_execution_times[selected_move] = current_time; // Update the execution time.
}

int main() {
    srand(static_cast<unsigned>(std::chrono::system_clock::now().time_since_epoch().count()));

    while (true) { // This loop simulates continuous gameplay.
        select_offensive_maneuver();

        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate game tick every second.
    }

    return 0;
}
