    pthread_mutex_init(&pool->pool_lock, NULL);
    pool->config = config;
    pool->size = config.max_connections;
    pool->connections = (NetworkConnection*)malloc(pool->size * sizeof(NetworkConnection));

    for (int i = 0; i < pool->size; ++i) {
        network_connection->is_available = 1;
        pthread_mutex_init(&connection->lock, NULL);
    }
}

// Acquire a connection from the pool
NetworkConnection* acquire_connection(ConnectionPool* pool) {
    NetworkConnection* conn = NULL;

    pthread_mutex_lock(&pool->pool_lock);

    for (int i = 0; i < pool->size; ++i) {
        if (pool->connections[i].is_available) {
            conn = &pool->connections[i];
            pool->connections[i].is_available = 0;
            pthread_mutex_unlock(&conn->lock);
            break;
        }
    }

    pthread_mutex_unlock(&pool->pool_lock);

    if (!conn) {
        log_message("No available connections in the pool");
    } else {
        pthread_mutex_lock(&conn->lock);
    }

    return conn;
}

// Release a connection back to the pool
void release_connection(ConnectionPool* pool, NetworkConnection* connection) {
    pthread_mutex_lock(&pool->pool_lock);

    for (int i = 0; i < pool->size; ++i) {
        if (&pool->connections[i] == connection) {
            connection->is_available = 1;
            break;
        }
    }

    pthread_mutex_unlock(&pool->pool_lock);
}

// Logging function integration stub
void log_message(const char* message) {
    // Example logging implementation
    printf("[LOG]: %s\n", message);
}

// Cleanup resources
void cleanup_connection_pool(ConnectionPool* pool) {
    for (int i = 0; i < pool->size; ++i) {
        pthread_mutex_destroy(&pool->connections[i].lock);
    }
    free(pool->connections);
    pthread_mutex_destroy(&pool->pool_lock);
}
