#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a basic structure for DOM elements.
typedef struct DOMElement {
    char* name;
    int hasChild;
    struct DOMElement** children;
} DOMElement;

// Define the result list structure.
typedef struct ElementNameList {
    char** names;
    size_t count;
    size_t capacity;
} ElementNameList;

// Function prototype for element matching logic, e.g., based on tag name.
int matchesSelector(DOMElement* element, const char* selector);

// Callback function type definition
typedef void (*ElementCallback)(DOMElement*);

// Helper functions to manage the result list
void initElementNameList(ElementNameList* list) {
    list->count = 0;
    list->capacity = 10; // Initial capacity
    list->names = (char**)malloc(list->capacity * sizeof(char*));
}

void freeElementNameList(ElementNameList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->names[i]);
    }
    free(list->names);
}

void addElementName(ElementNameList* list, const char* name) {
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->names = (char**)realloc(list->names, list->capacity * sizeof(char*));
    }
    list->names[list->count] = strdup(name);
    ++list->count;
}

// Core function to process DOM elements
ElementNameList* processDOMElements(DOMElement* root, const char* selector, size_t sizeLimit, ElementCallback callback) {
    if (!root || !selector || !callback) return NULL;

    // Initialize result list
    ElementNameList* resultList = (ElementNameList*)malloc(sizeof(ElementNameList));
    initElementNameList(resultList);

    // Recursive function to traverse and process DOM elements
    void traverse(DOMElement* element) {
        if (!element) return;

        // Process current element with callback
        callback(element);

        // Check if the element matches selector
        if (matchesSelector(element, selector)) {
            size_t nameLength = strlen(element->name);
            // Append to result list if within size limit
            if (nameLength <= sizeLimit) {
                addElementName(resultList, element->name);
            }
        }

        // Recursively process children if they exist
        for (int i = 0; i < (element->hasChild ? 2 : 0); ++i) {
            traverse(element->children[i]);
        }
    }

    // Start the traversal from root
    traverse(root);

    return resultList;
}

// Example matchesSelector implementation
int matchesSelector(DOMElement* element, const char* selector) {
    return element && strcmp(element->name, selector) == 0;
}
