    config->aes_enabled = cJSON_GetObjectItemCaseSensitive(json, "AES")->valueint;
    config->camellia_enabled = cJSON_GetObjectItemCaseSensitive(json, "Camellia")->valueint;
    config->md5_enabled = cJSON_GetObjectItemCaseSensitive(json, "MD5")->valueint;
    config->sha_enabled = cJSON_GetObjectItemCaseSensitive(json, "SHA")->valueint;
