#include <string.h>

#define AES_KEY_SIZE 32 // 256 bits
#define AES_BLOCK_SIZE 16
#define PBKDF2_ITERATIONS 10000

typedef struct {
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
} AES_Cipher;

// Function to derive a secure encryption key using PBKDF2
int derive_key_and_iv(const char *passphrase, const unsigned char *salt, int salt_len,
                      unsigned char *key, int key_len, unsigned char *iv, int iv_len) {
    return PKCS5_PBKDF2_HMAC(passphrase, strlen(passphrase), salt, salt_len, 
                             PBKDF2_ITERATIONS, EVP_sha256(), key_len + iv_len, iv);
}

// Function to initialize AES-256-CBC cipher
int init_aes_cipher(AES_Cipher *cipher, const char *passphrase) {
    unsigned char salt[8];

    // Generate a secure random salt
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Error generating salt\n");
        return -1;
    }

    // Derive key and IV from passphrase using PBKDF2
    if (derive_key_and_iv(passphrase, salt, sizeof(salt), cipher->key, AES_KEY_SIZE, 
                          cipher->iv, AES_BLOCK_SIZE) != (AES_KEY_SIZE + AES_BLOCK_SIZE)) {
        fprintf(stderr, "Error deriving key/IV\n");
        return -1;
    }

    // Set up encryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "EVP_CIPHER_CTX allocation failed\n");
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Error initializing encryption context\n");
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx); // Clean up after setup
    return 0;
}

