using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class MessageProcessor
{
    public string ProcessEncryptedMessage(string base64EncodedMessage, string hexKey, string hexIv)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage) || 
            string.IsNullOrEmpty(hexKey) ||
            string.IsNullOrEmpty(hexIv))
        {
            return "";
        }

        try
        {
            // Validate and decode Base64 input
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

            // Convert hex key and IV to byte arrays
            byte[] key = HexToByteArray(hexKey);
            byte[] iv = HexToByteArray(hexIv);

            if (key == null || iv == null)
                return "";

            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                tdes.Key = key;
                tdes.IV = iv;
                tdes.Mode = CipherMode.CBC;
                tdes.Padding = PaddingMode.PKCS7;

                try
                {
                    // Decrypt the message
                    using (ICryptoTransform decryptor = tdes.CreateDecryptor())
                    {
                        byte[] decryptedBytes = PerformCryptography(encryptedBytes, decryptor);

                        // Ensure length is a multiple of 8 bytes
                        int excessLength = decryptedBytes.Length % 8;
                        if (excessLength != 0)
                            Array.Resize(ref decryptedBytes, decryptedBytes.Length - excessLength);

                        return Encoding.UTF8.GetString(decryptedBytes);
                    }
                }
                catch (CryptographicException ex)
                {
                    // Log the error internally
                    LogDecryptionError(ex);
                    return null;
                }
            }
        }
        catch (FormatException)
        {
            // Return empty string if Base64 is invalid or if key/IV are incorrect lengths
            return "";
        }
    }

    private byte[] HexToByteArray(string hex)
    {
        if ((hex.Length % 2) != 0)
            return null;

        byte[] bytes = new byte[hex.Length / 2];
        try
        {
            for (int i = 0; i < bytes.Length; i++)
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
        }
        catch
        {
            return null;
        }

        return bytes;
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, cryptoTransform, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
                cs.FlushFinalBlock();
                return ms.ToArray();
            }
        }
    }

    private void LogDecryptionError(Exception ex)
    {
        // Implement your logging mechanism here
        Console.WriteLine("Decryption error: " + ex.Message);
    }
}
```

### Explanation of Key Aspects:

- **Base64 Validation**: The function checks if the Base64 string is valid using `Convert.FromBase64String`. Invalid strings will throw a `FormatException`, which we catch to return an empty string.

- **Hexadecimal Conversion**: Converts hex key and IV to byte arrays. If conversion fails or results in incorrect lengths, it returns an empty string.

- **Triple DES Decryption**: Uses TripleDES for decryption with the provided key and IV. Any failure during decryption is caught and logged without exposing details to the caller.

- **Length Validation**: Ensures that decrypted data length is a multiple of 8 bytes by trimming excess bytes if necessary.

- **Error Handling**: Catches cryptographic errors, logs them internally, and returns null instead of throwing exceptions, making it robust against runtime failures.']

['```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class FileProcessor
{
    private readonly long _fileSizeThreshold;
    private readonly IMetadataService _metadataService;
    private static readonly NLog.Logger Logger = NLog.LogManager.GetCurrentClassLogger();

    public FileProcessor(long fileSizeThreshold, IMetadataService metadataService)
    {
        _fileSizeThreshold = fileSizeThreshold;
        _metadataService = metadataService;
    }

    public async Task ProcessFilesAsync(List<string> filePaths)
    {
        foreach (var filePath in filePaths)
        {
            try
            {
                if (!File.Exists(filePath))
                {
                    Logger.Warn($"File does not exist: {filePath}");
                    continue;
                }

                var fileInfo = new FileInfo(filePath);

                // Skip files exceeding the size threshold
                if (fileInfo.Length > _fileSizeThreshold)
                {
                    Logger.Info($"Skipping file due to size limit: {filePath}");
                    continue;
                }

                string hash = await CalculateSHA256Async(filePath);
                var metadata = await FetchMetadataWithRetriesAsync(fileInfo);

                // Log result or further process as needed
                Logger.Info($"Processed File: {filePath}, SHA-256: {hash}, Created: {metadata.CreationDate}, Modified: {metadata.LastModified}");
            }
            catch (Exception ex)
            {
                Logger.Error(ex, $"Error processing file: {filePath}");
            }
        }
    }

    private async Task<string> CalculateSHA256Async(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = File.OpenRead(filePath);

        byte[] hashBytes;
        using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            hashBytes = sha256.ComputeHash(memoryStream.ToArray());
        }

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private async Task<FileMetadata> FetchMetadataWithRetriesAsync(FileInfo fileInfo)
    {
        const int maxRetryAttempts = 3;
        for (int attempt = 1; attempt <= maxRetryAttempts; attempt++)
        {
            try
            {
                return await _metadataService.GetFileMetadataAsync(fileInfo);
            }
            catch (Exception ex) when (attempt < maxRetryAttempts)
            {
                Logger.Warn(ex, $"Attempt {attempt} failed. Retrying...");
                await Task.Delay(1000); // Exponential backoff could be implemented here
            }
        }

        Logger.Error($"Failed to fetch metadata after {maxRetryAttempts} attempts for file: {fileInfo.FullName}");
        return new FileMetadata { CreationDate = fileInfo.CreationTime, LastModified = fileInfo.LastWriteTime };
    }
}

public interface IMetadataService
{
    Task<FileMetadata> GetFileMetadataAsync(FileInfo fileInfo);
}

public class FileMetadata
{
    public DateTime CreationDate { get; set; }
    public DateTime LastModified { get; set; }
}
```

In this implementation:
- **File size check** skips files exceeding a specified threshold.
- **SHA-256 hashing** is performed asynchronously to ensure efficient processing of large files.
- **Metadata fetching** includes retry logic for handling potential external service failures.
- The use of `NLog` or similar logging frameworks provides robust error tracking without interrupting the primary process flow.']

