using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly int _keySizeInBits;

    public AesCbcDecryptor(byte[] key)
    {
        if (key == null || (key.Length != 16 && key.Length != 32))
            throw new ArgumentException("Key must be either 128 bits or 256 bits.");

        _key = key;
        _keySizeInBits = key.Length * 8;
    }

    public async Task<IEnumerable<byte[]>> DecryptDataAsync(IEnumerable<(byte[] ciphertext, byte[] iv, byte[] hmac)> data,
                                                           Func<Task<byte[], Exception?>> generateHmacAsync)
    {
        var tasks = data.Select(async item =>
        {
            var (ciphertext, iv, expectedHmac) = item;

            if (!ValidateHmac(ciphertext, expectedHmac))
                throw new CryptographicException("Invalid HMAC. Data integrity could not be verified.");

            return await DecryptCiphertextAsync(ciphertext, iv);
        });

        return await Task.WhenAll(tasks);
    }

    private bool ValidateHmac(byte[] data, byte[] hmac)
    {
        using var hash = new HMACSHA256(_key);
        var computedHmac = hash.ComputeHash(data);
        return computedHmac.SequenceEqual(hmac);
    }

    private async Task<byte[]> DecryptCiphertextAsync(byte[] ciphertext, byte[] iv)
    {
        if (iv.Length != (_keySizeInBits == 128 ? 16 : 32))
            throw new ArgumentException("Invalid IV length.");

        using var aes = Aes.Create();
        aes.Key = _key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7; // You can make this configurable

        byte[] plaintext;

        try
        {
            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var ms = new System.IO.MemoryStream(ciphertext))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (var buffer = new byte[ciphertext.Length])
            {
                var bytesRead = await cs.ReadAsync(buffer, 0, buffer.Length);
                plaintext = buffer.Take(bytesRead).ToArray();
            }
        }
        catch
        {
            // Handle padding errors if no padding is expected.
            aes.Padding = PaddingMode.None;
            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var ms = new System.IO.MemoryStream(ciphertext))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (var buffer = new byte[ciphertext.Length])
            {
                var bytesRead = await cs.ReadAsync(buffer, 0, buffer.Length);
                plaintext = buffer.Take(bytesRead).ToArray();
            }
        }

        return plaintext;
    }

    public static byte[] GenerateSecureIV(int bitSize)
    {
        using var rng = RandomNumberGenerator.Create();
        int bytesLength = bitSize / 8;
        var iv = new byte[bytesLength];
        rng.GetBytes(iv);
        return iv;
    }
}

