import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.lang.reflect.Field;
import java.util.concurrent.ConcurrentHashMap;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

public class ConfigurationLoader {

    private static final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();

    public static MyConfiguration loadConfiguration(byte[] data) throws SchemaMismatchException {
        String hashKey = generateHashKey(data);

        // Check cache
        if (cache.containsKey(hashKey)) {
            return (MyConfiguration) cache.get(hashKey);
        }

        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {

            Object obj;
            try {
                obj = ois.readObject();
            } catch (ClassNotFoundException e) {
                throw new SchemaMismatchException("Class not found during deserialization", e);
            }

            MyConfiguration config = validateAndCast(obj);

            // Cache the result
            cache.put(hashKey, config);

            return config;
        } catch (IOException | ClassNotFoundException e) {
            throw new SchemaMismatchException("Deserialization failed: " + e.getMessage(), e);
        }
    }

    private static String generateHashKey(byte[] data) {
        // Implement a simple hash function or use java.util.Objects.hash
        int hashCode = java.util.Arrays.hashCode(data);
        return Integer.toString(hashCode);
    }

    private static MyConfiguration validateAndCast(Object obj) throws SchemaMismatchException {
        try {
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse("configSchema.xml");
            doc.getDocumentElement().normalize();

            NodeList fieldList = doc.getElementsByTagName("field");

            for (int i = 0; i < fieldList.getLength(); i++) {
                Element field = (Element) fieldList.item(i);
                String fieldName = field.getAttribute("name");
                String fieldType = field.getAttribute("type");

                Field classField;
                try {
                    classField = obj.getClass().getDeclaredField(fieldName);
                    classField.setAccessible(true);

                    Object fieldValue = classField.get(obj);

                    if (!fieldType.equals(fieldValue.getClass().getName())) {
                        throw new SchemaMismatchException(
                                String.format("Field %s expected type %s but got %s", fieldName, fieldType, 
                                              fieldValue.getClass().getName()));
                    }
                } catch (NoSuchFieldException | IllegalAccessException e) {
                    throw new SchemaMismatchException(String.format("Schema validation failed for field: %s", fieldName), e);
                }
            }

            return (MyConfiguration) obj;
        } catch (IOException | javax.xml.parsers.ParserConfigurationException e) {
            throw new SchemaMismatchException("Failed to parse schema XML file", e);
        }
    }

    // Custom exception class
    public static class SchemaMismatchException extends Exception {
        public SchemaMismatchException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    // Define the expected configuration object interface/class
    public static class MyConfiguration {
        // Fields and methods as per your application's requirement
    }
}
