import random

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int read_integers(int **array) {
    int count, capacity = 10, i;
    *array = (int *)malloc(capacity * sizeof(int));

    if (*array == NULL) return -1;

    if (scanf("%d", &count) != 1 || count < 0) return -2;

    for (i = 0; i < count; ++i) {
        if (i >= capacity) {
            capacity *= 2;
            *array = (int *)realloc(*array, capacity * sizeof(int));
            if (*array == NULL) return -3;
        }

        if (scanf("%d", &((*array)[i])) != 1) return -4;
    }

    return count;
}

void find_and_print_largest(const int *array, int size) {
    int largest = array[0];

    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest Integer: %d\n", largest);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list == NULL) return NULL;

    for (int i = 0; i < num_pdus; ++i) {
        list[i].RX_UE_INFORMATION_TAG = random.randint(1, 100);
        list[i].RNTI = random.randint(1, 100);
        list[i].CRC_INDICATION_REL8_TAG = random.randint(1, 10);
        list[i].CRCFLAG = random.choice([0, 1]);
    }

    return list;
}

void free_resources(int *array, NFAPI_CRC_INDICATION_PDU_T *list) {
    if (array != NULL) free(array);
    if (list != NULL) free(list);
}

int main() {
    int *integer_array = NULL;
    int result = read_integers(&integer_array);

    if (result < 0) {
        fprintf(stderr, "Error reading integers.\n");
        return EXIT_FAILURE;
    }

    find_and_print_largest(integer_array, result);

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu_list(result);

    if (pdu_list == NULL) {
        fprintf(stderr, "Memory allocation failed for PDU list.\n");
        free_resources(integer_array, pdu_list);
        return EXIT_FAILURE;
    }

    // Here you would process the PDU list as required

