        offsets[i] = rand() % 1000; // Example offset initialization
    }
    for (int i = 0; i < key_count; ++i) {
        keys[i] = rand() % 256; // Example key initialization
    }
}

// Function to add a new algorithm to the cryptographic library
void add_algorithm(CryptoLib *crypto_lib, void (*encrypt)(void *, size_t), void (*hash)(const void *, size_t, unsigned char *)) {
    pthread_mutex_lock(&crypto_lib_mutex);
    if (crypto_lib) {
        crypto_lib->encrypt = encrypt;
        crypto_lib->hash = hash;
    }
    pthread_mutex_unlock(&crypto_lib_mutex);
}

