namespace RecordStorage {

    struct Record {
        int value;
        std::shared_ptr<int> keyPtr;
        std::shared_ptr<long> offsetPtr;

        Record(int val, std::shared_ptr<int> kptr, std::shared_ptr<long> optr)
            : value(val), keyPtr(kptr), offsetPtr(optr) {}
    };

    class MemoryManager {
    public:
        MemoryManager(size_t recordCount, int rangeMin, int rangeMax)
            : recordCount_(recordCount), rangeMin_(rangeMin), rangeMax_(rangeMax),
              rng_(std::random_device{}()), dist_(rangeMin_, rangeMax_),
              initializedRecords_(0) {}

        ~MemoryManager() {
            releaseResources();
        }

        void initialize() {
            std::lock_guard<std::mutex> lock(mutex_);

            for (size_t i = 0; i < recordCount_; ++i) {
                try {
                    auto keyPtr = std::make_shared<int>(static_cast<int>(i));
                    auto offsetPtr = std::make_shared<long>(static_cast<long>(i * 10)); // Example calculation
                    int value = dist_(rng_);

                    records_.emplace_back(std::make_unique<Record>(value, keyPtr, offsetPtr));
                    ++initializedRecords_;
                } catch (const std::bad_alloc&) {
                    // Handle allocation failure gracefully
                    break;
                }
            }
        }

        size_t getInitializedRecordsCount() const {
            return initializedRecords_;
        }

    private:
        void releaseResources() {
            std::lock_guard<std::mutex> lock(mutex_);
            records_.clear();
        }

        const size_t recordCount_;
        int rangeMin_, rangeMax_;
        std::mt19937 rng_;
        std::uniform_int_distribution<int> dist_;
        mutable std::mutex mutex_;
        std::vector<std::unique_ptr<Record>> records_;
        std::atomic<size_t> initializedRecords_;
    };

} // namespace RecordStorage

int main() {
    RecordStorage::MemoryManager manager(1000, 1, 100);

    manager.initialize();

    std::cout << "Initialized Records: "
              << manager.getInitializedRecordsCount()
              << std::endl;

    return 0;
}
