#define LOG_FILE "file_processor.log"
#define AES_KEY_SIZE 256
#define RSA_KEY_SIZE 2048

// Function prototypes
void log_message(const char *message);
int process_file(const char *input_filename, const char *output_filename, int encrypt, int method);
int perform_symmetric_encryption(FILE *in, FILE *out, unsigned char key[AES_KEY_SIZE / 8], unsigned char iv[16]);
int perform_asymmetric_encryption(FILE *in, FILE *out, RSA *rsa_pub_key);
int generate_keys(const char *key_path);

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

int process_file(const char *input_filename, const char *output_filename, int encrypt, int method) {
    FILE *in = fopen(input_filename, "rb");
    if (!in) {
        log_message("Error opening input file");
        return errno;
    }

    FILE *out = fopen(output_filename, "wb");
    if (!out) {
        fclose(in);
        log_message("Error opening output file");
        return errno;
    }

    unsigned char key[AES_KEY_SIZE / 8];
    unsigned char iv[16] = {0}; // Simple IV for illustration

    RSA *rsa_pub_key = NULL;
    if (method == 2) {
        int res = generate_keys("keys.pem"); // Generate keys if not present
        if (res != 0) return res;

        rsa_pub_key = PEM_read_RSA_PUBKEY(fp, NULL, NULL, NULL);
        if (!rsa_pub_key) {
            log_message("Failed to load public key");
            fclose(in);
            fclose(out);
            return errno;
        }
    }

    int result = (method == 1) ? perform_symmetric_encryption(in, out, key, iv) : perform_asymmetric_encryption(in, out, rsa_pub_key);

    if (rsa_pub_key) RSA_free(rsa_pub_key);
    fclose(in);
    fclose(out);

    return result;
}

int perform_symmetric_encryption(FILE *in, FILE *out, unsigned char key[AES_KEY_SIZE / 8], unsigned char iv[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return errno;

    int len;
    int ciphertext_len;
    unsigned char buffer[1024];
    unsigned char encrypted_buffer[1024 + AES_BLOCK_SIZE];

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return errno;
    }

    while ((len = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        int ret = EVP_EncryptUpdate(ctx, encrypted_buffer, &len, buffer, len);
        if (ret <= 0) break;

        fwrite(encrypted_buffer, 1, len, out);

        ciphertext_len += len;
    }

    if (EVP_EncryptFinal_ex(ctx, encrypted_buffer, &len)) {
        fwrite(encrypted_buffer, 1, len, out);
        ciphertext_len += len;
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return errno;
    }

    EVP_CIPHER_CTX_free(ctx);

    log_message("Symmetric encryption completed");
    return 0;
}

int perform_asymmetric_encryption(FILE *in, FILE *out, RSA *rsa_pub_key) {
    int rsa_len = RSA_size(rsa_pub_key);
    unsigned char buffer[1024];
    unsigned char encrypted_buffer[RSA_MAX_LENGTH];

    while (1) {
        size_t len = fread(buffer, 1, sizeof(buffer), in);
        if (!len) break;

        int ret = RSA_public_encrypt(len, buffer, encrypted_buffer, rsa_pub_key, RSA_PKCS1_OAEP_PADDING);
        if (ret == -1) {
            log_message("Error encrypting data");
            return errno;
        }

        fwrite(encrypted_buffer, 1, ret, out);
    }

    log_message("Asymmetric encryption completed");
    return 0;
}

int generate_keys(const char *key_path) {
    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();

    if (!BN_set_word(e, RSA_F4)) { // 65537
        log_message("Error setting public exponent");
        return errno;
    }

    if (1 != RSA_generate_key_ex(rsa, RSA_KEY_SIZE, e, NULL)) {
        log_message("Error generating RSA key pair");
        return errno;
    }

    FILE *fp = fopen(key_path, "wb");
    if (!fp) {
        log_message("Error opening keys file");
        return errno;
    }

    PEM_write_RSA_PUBKEY(fp, rsa);
    PEM_write_RSAPrivateKey(fp, rsa, NULL, NULL, 0, NULL, NULL);

    RSA_free(rsa);
    BN_free(e);
    fclose(fp);

    log_message("Keys generated and stored successfully");
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input file> <output file> <encrypt(1)/decrypt(0)> <method(1=symmetric,2=asymmetric)>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];
    int encrypt = atoi(argv[3]);
    int method = atoi(argv[4]);

    int result = process_file(input_filename, output_filename, encrypt, method);

    if (result != 0) {
        log_message("File processing failed");
        return EXIT_FAILURE;
    }

    log_message("File processed successfully");
    return EXIT_SUCCESS;
}
```

**Note:**
- This code uses OpenSSL for encryption/decryption. Ensure that OpenSSL is installed and linked properly in your build environment.
