['```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_INPUT 1000

int find_largest_integer() {
    int *numbers = NULL;
    size_t capacity = 10;
    size_t count = 0;
    int number;

    numbers = malloc(capacity * sizeof(int));
    if (!numbers) return -1; // Memory allocation failed

    printf("Enter integers (press Ctrl+D to finish):\n");

    while (scanf("%d", &number) == 1 && count < MAX_INPUT) {
        if (count >= capacity) {
            capacity *= 2;
            int *new_numbers = realloc(numbers, capacity * sizeof(int));
            if (!new_numbers) {
                free(numbers);
                return -1; // Memory allocation failed
            }
            numbers = new_numbers;
        }
        numbers[count++] = number;
    }

    int largest = (count > 0) ? numbers[0] : -1;

    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    free(numbers);
    printf("Largest integer: %d\n", largest);

    return 0;
}
