#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define CRC_FAILURE_PROBABILITY 0.05

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    int error_logged;
} CRCDynamicList;

void log_error(const char* message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);
    fprintf(stderr, "Error: %s\n", message);
    pthread_mutex_unlock(&log_lock);
}

int generate_crc_flag() {
    return (rand() / (double)RAND_MAX) < CRC_FAILURE_PROBABILITY;
}

CRCDynamicList* create_crclist(size_t initial_capacity) {
    CRCDynamicList *list = malloc(sizeof(CRCDynamicList));
    if (!list) {
        log_error("Failed to allocate memory for list.");
        return NULL;
    }
    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        log_error("Failed to allocate memory for data array.");
        return NULL;
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->error_logged = 0;
    return list;
}

int add_crc_indication(CRCDynamicList *list, uint16_t rx_ue_tag, uint16_t rnti, uint8_t crc_rel8_tag) {
    if (list->size >= MAX_STRUCTURES || !pthread_mutex_trylock(&list->lock)) {
        return -1; // List is full or unable to acquire lock
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == rx_ue_tag) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RX_UE_INFORMATION_TAG found
        }
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            log_error("Memory reallocation failed.");
            return -3; // Realloc failure
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[list->size++];
    element->RX_UE_INFORMATION_TAG = rx_ue_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    element->CRCFLAG = generate_crc_flag() ? 0 : 1;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_crclist(CRCDynamicList *list) {
    if (!list) return;
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

