unsigned int get_random_crcflag(unsigned int seed) {
    unsigned int lcg = seed;
    pthread_mutex_lock(&rand_lock);
    lcg = (lcg * 1664525u + 1013904223u) % 4294967296U; // Linear Congruential Generator
    pthread_mutex_unlock(&rand_lock);
    return lcg & 1; // Ensure CRCFLAG is either 0 or 1
}

// Validate PDU structure
int validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu != NULL && (pdu->crc_tag.CRCFLAG == 0 || pdu->crc_tag.CRCFLAG == 1);
