NFAPI_CRC_INDICATION_PDU_T* create_pdus(int batch_size, unsigned int seed) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (int i = 0; i < batch_size; ++i) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            pdus[i].crc_tag.CRCFLAG = get_random_crcflag(seed + i);
            if (validate_pdu(&pdus[i])) break;
            retries++;
        }
        if (retries == MAX_RETRIES) {
            free(pdus);
            return NULL; // Failed to create valid PDU
        }
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
