#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000
#define CRC_FAILURE_PROBABILITY 0.05

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // 1 for failure, 0 for success
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} List;

List* initialize_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_tag_present(List* list, int tag) {
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == tag)
            return 1;
        current = current->next;
    }
    return 0;
}

void add_pdu_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T pdu, int max_age) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES) {
        fprintf(stderr, "Maximum number of structures reached.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (is_tag_present(list, pdu.RX_UE_INFORMATION_TAG)) {
        fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG detected.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Simulate CRC failure
    srand(time(NULL) ^ (uintptr_t)pthread_self());
    pdu.CRCFLAG = (rand() / (RAND_MAX + 1.0)) < CRC_FAILURE_PROBABILITY;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    // Remove old entries
    time_t now = time(NULL);
    Node *current = list->head, *prev = NULL;
    while (current) {
        if ((now - current->data.timestamp) > max_age) {
            Node* to_delete = current;
            current = current->next;
            if (prev)
                prev->next = current;
            else
                list->head = current;

            free(to_delete);
            list->count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void log_error(const char* message) {
    // Implement logging mechanism here
    fprintf(stderr, "%s\n", message);
}

int main() {
