    if (!list) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 1;
    pdu.RNTI = 1234;
    pdu.CRC_INDICATION_REL8_TAG = 5678;
    pdu.timestamp = time(NULL);

    add_pdu_to_list(list, pdu, 60); // max_age of 60 seconds

    free(list);
    return EXIT_SUCCESS;
}
