#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_POOL_SIZE 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[2];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Block {
    size_t size;
    int free;
    struct Block* next;
    void* data;
} Block;

static Block* head = NULL;

Block* find_free_block(Block** last, size_t size);
void split_block(Block* block, size_t size);

int init_memory_pool(size_t pool_size) {
    if (pool_size == 0 || pool_size > MAX_POOL_SIZE)
        return -1;

    void* memory = malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory)
        return -1;

    head = (Block*)malloc(sizeof(Block));
    if (!head) {
        free(memory);
        return -1;
    }

    head->size = pool_size;
    head->free = 1;
    head->next = NULL;
    head->data = memory;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    Block* last = NULL;
    Block* block = find_free_block(&last, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!block) {
        fprintf(stderr, "Allocation failed: No free blocks available.\n");
        return NULL;
    }

    block->free = 0;
    split_block(block, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)block->data;

    // Initialize PDU
    srand((unsigned int)time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 65536;
    pdu->RNTI = rand() % 65536; 
    memset(pdu->CRC_INDICATION_REL8_TAG, rand() & 0xFF, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    pdu->CRCFLAG = rand() & 1;

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Block* block = (Block*)((char*)pdu - offsetof(Block, data));
    block->free = 1;

    if (block->next && block->next->free)
        merge_blocks(block);
}

int validate_and_populate_pool(size_t pool_size, size_t max_structures) {
    int retries = 0;
    uint16_t rnti_set[MAX_POOL_SIZE] = {0};
    NFAPI_CRC_INDICATION_PDU_T* pdu;

    if (init_memory_pool(pool_size)) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return -1;
    }

    size_t count = 0;
    while (count < max_structures) {
        int retry_count = 0;

        do {
            pdu = allocate_pdu();

            if (!pdu) {
                fprintf(stderr, "Allocation attempt failed.\n");
                break;
            }

            uint16_t rnti = ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RNTI;
            for (int i = 0; i < MAX_POOL_SIZE && retry_count < 3; ++i) {
                if (rnti_set[i] == rnti) {
                    free_pdu(pdu);
                    pdu = NULL;
                    retries++;
                    ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RNTI = rand() % 65536;
                    retry_count++;
                } else {
                    break;
                }
            }

        } while (!pdu && retry_count < 3);

        if (!pdu) {
            fprintf(stderr, "Failed to allocate unique RNTI after retries.\n");
            break;
        }

        rnti_set[count] = ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RNTI;
        count++;
    }

    printf("Total retries: %d\n", retries);
    return 0;
}

void merge_blocks(Block* block) {
    if (block->next && block->next->free) {
        block->size += (block->next->size + sizeof(Block));
        block->next = block->next->next;
    }
}

Block* find_free_block(Block** last, size_t size) {
    Block* current = head;

    while (current && !(current->free && current->size >= size)) {
        *last = current;
        current = current->next;
    }

    return current;
}

void split_block(Block* block, size_t size) {
    if ((block->size - size) >= sizeof(Block)) {
        Block* new_block = (Block*)((char*)block + size + sizeof(Block));

        new_block->size = block->size - size - sizeof(Block);
        new_block->free = 1;
        new_block->next = block->next;

        block->size = size;
        block->next = new_block;
    }
}

void report_memory_usage() {
    Block* current = head;
    int free_blocks = 0, total_blocks = 0;
    while (current) {
        total_blocks++;
        if (current->free)
            free_blocks++;
        current = current->next;
    }

    printf("Total Blocks: %d, Free Blocks: %d\n", total_blocks, free_blocks);
}

int main() {
    size_t pool_size = 100; // Example configurable parameter
    size_t max_structures = 50; // Maximum structures

    if (validate_and_populate_pool(pool_size, max_structures) != 0) {
        fprintf(stderr, "Failed to populate pool.\n");
    }

    report_memory_usage();

    return 0;
}
