#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCLinkedList;

CRCLinkedList* createList() {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void destroyList(CRCLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addOrUpdateCRCIndication(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current) {
        if ((*current)->data.RNTI == pdu.RNTI) {
            (*current)->data.CRCFLAG = (unsigned char)(rand() % 2); // Randomly set CRCFLAG
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = &((*current)->next);
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    newNode->data = pdu;
    newNode->data.CRCFLAG = (unsigned char)(rand() % 2); // Randomly set CRCFLAG
    newNode->next = NULL;
    *current = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeCRCIndication(CRCLinkedList* list, unsigned int rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current) {
        if ((*current)->data.RNTI == rnti) {
            Node* toDelete = *current;
            *current = (*current)->next;
            free(toDelete);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int serializeList(CRCLinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    Node* current = list->head;
    while (current) {
        if (fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            fclose(file);
            return -1;
        }
        current = current->next;
    }

    fclose(file);
    return 0;
}

int deserializeList(CRCLinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    Node** current = &(list->head);
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        size_t readBytes = fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (readBytes != 1) break;

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fclose(file);
            return -1;
        }
        newNode->data = pdu;
        newNode->next = NULL;
        *current = newNode;
        current = &((*current)->next);
    }

    fclose(file);
    return 0;
}
```

