#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void* memory_pool;
    size_t pool_size;
    pthread_mutex_t lock; // For controlling access to random seed
} MemoryPoolConfig;

static inline bool validate_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return (pdu->RX_UE_INFORMATION_TAG >= 0 &&
            pdu->RNTI >= 0 &&
            (pdu->CRCFLAG == 0 || pdu->CRCFLAG == 1));
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdus(
    MemoryPoolConfig* config,
    size_t batch_size,
    unsigned int seed) {

    if (!config || !config->memory_pool || batch_size <= 0) {
        return NULL;
    }

    pthread_mutex_lock(&config->lock);
    srand(seed); // Initialize random number generator
    pthread_mutex_unlock(&config->lock);

    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*) config->memory_pool;

    for (size_t i = 0; i < batch_size; ++i) {
        bool success = false;
        int attempts = 0;

        while (!success && attempts < 3) {
            size_t offset = (pdus - (NFAPI_CRC_INDICATION_PDU_T*)config->memory_pool) + i * pdu_size;

            if (offset >= config->pool_size) {
                fprintf(stderr, "Memory pool exhausted during allocation\n");
                return NULL; // Pool is insufficient
            }

            NFAPI_CRC_INDICATION_PDU_T* pdu = pdus + i;

            // Populate fields
            pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
            pdu->RNTI = rand() % 500;
            pdu->CRCFLAG = (rand() % 2);

            success = validate_pdu(pdu);

            if (!success) {
                fprintf(stderr, "Validation failed for PDU at index %zu. Attempt: %d\n", i, attempts + 1);
            }

            ++attempts;
        }

        if (!success) {
            fprintf(stderr, "Failed to create valid PDU after multiple attempts.\n");
            return NULL; // Failed after retries
        }
    }

    return pdus;
}

void setup_memory_pool(MemoryPoolConfig* config, size_t pool_size) {
    if (config) {
        config->memory_pool = malloc(pool_size);
        config->pool_size = pool_size;
        pthread_mutex_init(&config->lock, NULL);
    }
}

void cleanup_memory_pool(MemoryPoolConfig* config) {
    if (config && config->memory_pool) {
        free(config->memory_pool);
        pthread_mutex_destroy(&config->lock);
    }
}
