int allocate_and_populate_nfa_api_crc_indication_pdu(int num_pdus, NFAPI_CRC_INDICATION_PDU_T** pdus_out) {
    srand(time(NULL));

    if (num_pdus <= 0 || pdus_out == NULL) {
        log_error("Invalid input parameters.");
        return -1;
    }

    *pdus_out = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus_out == NULL) {
        log_error("Memory allocation failed.");
        return -2;
    }

    uint16_t rntis[num_pdus];
    memset(rntis, 0, num_pdus * sizeof(uint16_t));

    int retry_count = 0;
    for (int i = 0; i < num_pdus; ++i) {
        int unique_rnti_found = 0;

        while (!unique_rnti_found && retry_count < 3) {
            (*pdus_out)[i].rx_ue_information_tag = rand();
            (*pdus_out)[i].rnti = (uint16_t)(rand() % 65536);
            (*pdus_out)[i].crc_indication_rel8_tag = (uint8_t)(rand() & 0xFF);
            (*pdus_out)[i].crcflag = (uint8_t)(rand() & 1);
            (*pdus_out)[i].timestamp = time(NULL);

            unique_rnti_found = 1;
            for (int j = 0; j < i; ++j) {
                if ((*pdus_out)[j].rnti == (*pdus_out)[i].rnti) {
                    unique_rnti_found = 0;
                    break;
                }
            }

            if (!unique_rnti_found) {
                retry_count++;
                log_info("Retrying RNTI generation. Attempt: %d", retry_count);
            }
        }

        if (retry_count >= 3 && !unique_rnti_found) {
            free(*pdus_out);
            log_error("Failed to generate unique RNTI after retries.");
            return -3;
        }

        rntis[i] = (*pdus_out)[i].rnti;
    }

    // Sort structures based on timestamp for priority handling
    qsort(*pdus_out, num_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), [](const void* a, const void* b) {
        NFAPI_CRC_INDICATION_PDU_T *pa = (NFAPI_CRC_INDICATION_PDU_T *)a;
        NFAPI_CRC_INDICATION_PDU_T *pb = (NFAPI_CRC_INDICATION_PDU_T *)b;
        return pa->timestamp > pb->timestamp; // Sort descending by timestamp
    });

    log_info("Successfully allocated and populated structures.");

    return 0;
}

void deallocate_nfa_api_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdus) {
