['Below is an implementation of a thread-safe C function to manage a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures. The solution uses a hash table for fast lookups while ensuring minimal latency and resource contention through mutex locks.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash(unsigned int rnti, unsigned int table_size) {
    return rnti % table_size;
}

HashTable* create_hash_table() {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = calloc(HASH_TABLE_SIZE, sizeof(Node*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable* ht) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* entry = ht->table[i];
        while (entry) {
            Node* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void add_or_update_pdu(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!ht) return;

    unsigned int index = hash(pdu.RNTI, HASH_TABLE_SIZE);

    pthread_mutex_lock(&ht->lock);

    Node** entry = &ht->table[index];
    while (*entry) {
        if ((*entry)->data.RNTI == pdu.RNTI) {
            (*entry)->data = pdu;
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        entry = &(*entry)->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = NULL;
    *entry = new_node;

    pthread_mutex_unlock(&ht->lock);
}

void remove_pdu(HashTable* ht, unsigned int rnti) {
    if (!ht) return;

    unsigned int index = hash(rnti, HASH_TABLE_SIZE);

    pthread_mutex_lock(&ht->lock);

    Node** entry = &ht->table[index];
    while (*entry) {
        if ((*entry)->data.RNTI == rnti) {
            Node* to_remove = *entry;
            *entry = (*entry)->next;
            free(to_remove);
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        entry = &(*entry)->next;
    }

    pthread_mutex_unlock(&ht->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(HashTable* ht, unsigned int rnti) {
    if (!ht) return NULL;

    unsigned int index = hash(rnti, HASH_TABLE_SIZE);

    pthread_mutex_lock(&ht->lock);

    Node* entry = ht->table[index];
    while (entry) {
        if (entry->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* pdu_copy = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pdu_copy) {
                *pdu_copy = entry->data;
            }
            pthread_mutex_unlock(&ht->lock);
            return pdu_copy;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;
}
```

