#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int id;
    int priority;
} Message;

typedef struct {
    Message **messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MessageCollection;

MessageCollection* create_message_collection(size_t initial_capacity) {
    MessageCollection *collection = malloc(sizeof(MessageCollection));
    collection->messages = malloc(initial_capacity * sizeof(Message *));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_message_collection(MessageCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->messages[i]);
    }
    free(collection->messages);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_message(MessageCollection *collection, int id, int priority) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Message **new_messages = realloc(collection->messages, new_capacity * sizeof(Message *));
        if (!new_messages) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Out of memory
        }
        collection->messages = new_messages;
        collection->capacity = new_capacity;
    }

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->messages[i]->id == id) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Duplicate ID
        }
    }

    Message *new_message = malloc(sizeof(Message));
    if (!new_message) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Out of memory
    }

    new_message->timestamp = time(NULL);
    new_message->id = id;
    new_message->priority = priority;
    collection->messages[collection->size++] = new_message;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_message(MessageCollection *collection, int id, int new_priority) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->messages[i]->id == id) {
            collection->messages[i]->priority = new_priority;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Message not found
}

Message* get_message(MessageCollection *collection, int id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->messages[i]->id == id) {
            pthread_mutex_unlock(&collection->lock);
            return collection->messages[i];
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int compare_messages(const void *a, const void *b) {
    Message *msg_a = *(Message **)a;
    Message *msg_b = *(Message **)b;
    return (msg_a->timestamp > msg_b->timestamp) - (msg_a->timestamp < msg_b->timestamp);
}

void iterate_messages(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    qsort(collection->messages, collection->size, sizeof(Message *), compare_messages);

    for (size_t i = 0; i < collection->size; ++i) {
        printf("ID: %d, Timestamp: %ld, Priority: %d\n", 
               collection->messages[i]->id, collection->messages[i]->timestamp,
               collection->messages[i]->priority);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Usage example
int main() {
    MessageCollection *collection = create_message_collection(10);

    add_message(collection, 1, 5);
    add_message(collection, 2, 3);
    update_message(collection, 1, 7);

    Message *msg = get_message(collection, 1);
    if (msg) {
        printf("Retrieved - ID: %d, Priority: %d\n", msg->id, msg->priority);
    }

    iterate_messages(collection);

    destroy_message_collection(collection);
    return 0;
}
