from collections import defaultdict

# Function to find and print the largest integer in an array
void findLargest(int *arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Read integers from standard input and find the largest
void readAndFindLargest() {
    int *array, size;

    // Read number of elements
    scanf("%d", &size);
    array = (int *)malloc(size * sizeof(int));

    // Read each integer into the array
    for (int i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }

    // Find and print largest integer
    findLargest(array, size);

    free(array);
}

class Graph:
    def __init__(self):
        self.vertices = defaultdict(dict)
        self.edges = defaultdict(list)

    def add_vertex(self, vertex_id, properties=None):
        if properties is None:
            properties = {}
        self.vertices[vertex_id] = properties

    def add_edge(self, from_vertex, to_vertex, edge_properties=None):
        if edge_properties is None:
            edge_properties = {}
        self.edges[from_vertex].append((to_vertex, edge_properties))

    def update_property(self, vertex_or_edge, property_name, value):
        lock = threading.Lock()
        with lock:
            if isinstance(vertex_or_edge, tuple):  # Edge
                from_vertex, to_vertex = vertex_or_edge
                self.edges[from_vertex] = [
                    (to, props) if to != to_vertex else (to, {**props, property_name: value})
                    for to, props in self.edges[from_vertex]
                ]
            else:
                self.vertices[vertex_or_edge][property_name] = value

    def query(self, vertex_id=None, edge_from_to=None):
        if vertex_id is not None:
            return self.vertices.get(vertex_id)
        elif edge_from_to is not None:
            from_vertex, to_vertex = edge_from_to
            for to, props in self.edges[from_vertex]:
                if to == to_vertex:
                    return props

