#include <pthread.h>

#define MAX_SEQ_NUMBER 1000000

typedef struct {
    int SRS_TX_CONFIG_TAG;
    int SRS_TX_REQ_TAG;
} NR_PDU;

typedef struct Node {
    NR_PDU pdu;
    int SEQUENCE_NUMBER;
    int STATUS_FLAG;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PduList;

PduList* create_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_node(Node* node) {
    free(node);
}

int add_pdu(PduList* list, NR_PDU pdu, int sequence_number, int status_flag) {
    if (sequence_number < 0 || sequence_number > MAX_SEQ_NUMBER) {
        fprintf(stderr, "Invalid SEQUENCE_NUMBER: %d\n", sequence_number);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->pdu = pdu;
    new_node->SEQUENCE_NUMBER = sequence_number;
    new_node->STATUS_FLAG = status_flag;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_pdu(PduList* list, int sequence_number, NR_PDU pdu, int status_flag) {
    if (sequence_number < 0 || sequence_number > MAX_SEQ_NUMBER) {
        fprintf(stderr, "Invalid SEQUENCE_NUMBER: %d\n", sequence_number);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->SEQUENCE_NUMBER == sequence_number) {
            current->pdu = pdu;
            current->STATUS_FLAG = status_flag;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    fprintf(stderr, "SEQUECNE_NUMBER not found: %d\n", sequence_number);
    pthread_mutex_unlock(&list->lock);
    return -1;
}

int remove_pdu(PduList* list, int sequence_number) {
    if (sequence_number < 0 || sequence_number > MAX_SEQ_NUMBER) {
        fprintf(stderr, "Invalid SEQUENCE_NUMBER: %d\n", sequence_number);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->SEQUENCE_NUMBER == sequence_number) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            destroy_node(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    fprintf(stderr, "SEQUENCE_NUMBER not found: %d\n", sequence_number);
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void free_list(PduList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void external_sync(PduList* list, /* Parameters for external sync */) {
    // Placeholder for integrating with external systems
    pthread_mutex_lock(&list->lock);

    // Simulate fetching and updating data from an external system
    Node* current = list->head;
    while (current) {
        // Example: Update status based on external data
        current->STATUS_FLAG = /* Updated value */;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage of the PduList system
int main() {
    PduList* list = create_list();

    NR_PDU pdu = { .SRS_TX_CONFIG_TAG = 1, .SRS_TX_REQ_TAG = 2 };
    add_pdu(list, pdu, 1001, 0);
    update_pdu(list, 1001, (NR_PDU){.SRS_TX_CONFIG_TAG = 3, .SRS_TX_REQ_TAG = 4}, 1);
    remove_pdu(list, 1001);

    external_sync(list /*, external parameters */);

    free_list(list);

