#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

Record* initialize_records(Record *records, size_t size, int seed1, int seed2, long min_offset, long max_offset) {
    if (size == 0 || size > 10000) return NULL;

    // Allocate memory for records in a single call
    records = (Record *)malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(seed1);

    // Generate unique offsets and keys
    long used_offsets[10000] = {0};

    for (size_t i = 0; i < size; ++i) {
        int is_unique;

        do {
            is_unique = 1;
            records[i].offset = min_offset + rand() % (max_offset - min_offset + 1);

            // Ensure the offset is unique
            for (int j = 0; j < i; ++j) {
                if (records[j].offset == records[i].offset) {
                    is_unique = 0;
                    break;
                }
            }

        } while (!is_unique);

        used_offsets[i] = records[i].offset;
        records[i].key = rand();
    }

    srand(seed2);

    // Initialize record values using a polynomial formula and noise
    double coef_a = (double)rand() / RAND_MAX * 10.0; // Example coefficient calculation
    double coef_b = (double)rand() / RAND_MAX * 5.0;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = coef_a * records[i].key + coef_b * records[i].offset +
                           ((double)rand() / RAND_MAX - 0.5); // Adding noise
    }

    return records;
}

void free_records(Record *records) {
    if (records) {
        free(records);
    }
}
