#include <string.h>
#include <pthread.h>

#define MAX_CONFIGS 10000
#define CRC_FAILURE_PROBABILITY 0.05

typedef struct {
    int ssid_length;
    char ssid[32];
    // Add more fields as required
} WIFI_NETWORK_PARAMS;

typedef struct {
    WIFI_NETWORK_PARAMS params;
    unsigned long RX_UE_INFORMATION_TAG;
    int CRCFLAG;
} WIFI_NETWORK_CONFIGURATION;

typedef struct {
    WIFI_NETWORK_CONFIGURATION *configs;
    size_t count;
    pthread_mutex_t lock;
} NetworkConfigManager;

// Function to simulate network condition for CRC flag
int should_set_crc_flag() {
    return (rand() / (double)RAND_MAX) < CRC_FAILURE_PROBABILITY;
}

// Thread-safe function to add a configuration
void add_network_configuration(NetworkConfigManager *manager, const WIFI_NETWORK_PARAMS *params, unsigned long tag) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_CONFIGS) {
        printf("Maximum configurations limit reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Check for unique RX_UE_INFORMATION_TAG
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].RX_UE_INFORMATION_TAG == tag) {
            printf("Duplicate RX_UE_INFORMATION_TAG found.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Resize the configuration array
    WIFI_NETWORK_CONFIGURATION *new_configs = realloc(manager->configs, sizeof(WIFI_NETWORK_CONFIGURATION) * (manager->count + 1));
    if (!new_configs) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->configs = new_configs;

    // Initialize the new configuration
    manager->configs[manager->count].params = *params;
    manager->configs[manager->count].RX_UE_INFORMATION_TAG = tag;
    manager->configs[manager->count].CRCFLAG = should_set_crc_flag();

    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

// Initialize the NetworkConfigManager
void init_network_config_manager(NetworkConfigManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->configs = malloc(sizeof(WIFI_NETWORK_CONFIGURATION));
    if (!manager->configs) {
        fprintf(stderr, "Failed to allocate initial memory for configurations.\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
}

// Destroy the NetworkConfigManager
void destroy_network_config_manager(NetworkConfigManager *manager) {
    free(manager->configs);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    // Initialize random seed for CRC simulation
    srand((unsigned int)time(NULL));

    NetworkConfigManager manager;
    init_network_config_manager(&manager);

    WIFI_NETWORK_PARAMS params = {5, "Network1"};
    add_network_configuration(&manager, &params, 12345ULL);

    // Add more configurations as needed

    destroy_network_config_manager(&manager);
    return 0;
}
