#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define constants
#define MAX_UE_ID 1000
#define RETENTION_PERIOD_SECONDS 3600 // Example: 1 hour

typedef struct Cell {
    char *cell_id;
} Cell;

typedef struct Notification {
    int ue_id;
    time_t timestamp;
    Cell *cells;
    size_t cell_count;
    struct Notification *next;
} Notification;

typedef struct NotificationList {
    Notification *head[MAX_UE_ID];
} NotificationList;

// Function prototypes
void add_notification(NotificationList *list, int ue_id, time_t timestamp, Cell *cells, size_t cell_count);
void remove_outdated_notifications(NotificationList *list, time_t current_time);
void retrieve_notifications(NotificationList *list, int ue_id, time_t start_time, time_t end_time);

// Helper functions
static Notification* create_notification(int ue_id, time_t timestamp, Cell *cells, size_t cell_count);
static void free_notification(Notification *notification);
static void remove_node(Notification **head, Notification *node);
static void cleanup_expired_notifications(NotificationList *list, int ue_id, time_t current_time);

// Main function implementations
void add_notification(NotificationList *list, int ue_id, time_t timestamp, Cell *cells, size_t cell_count) {
    if (ue_id < 0 || ue_id >= MAX_UE_ID) return;

    Notification *new_notification = create_notification(ue_id, timestamp, cells, cell_count);
    if (!new_notification) return;

    new_notification->next = list->head[ue_id];
    list->head[ue_id] = new_notification;
}

void remove_outdated_notifications(NotificationList *list, time_t current_time) {
    for (int i = 0; i < MAX_UE_ID; ++i) {
        cleanup_expired_notifications(list, i, current_time);
    }
}

void retrieve_notifications(NotificationList *list, int ue_id, time_t start_time, time_t end_time) {
    if (ue_id < 0 || ue_id >= MAX_UE_ID) return;

    Notification *current = list->head[ue_id];
    while (current) {
        if (current->timestamp >= start_time && current->timestamp <= end_time) {
            printf("UE ID: %d, Timestamp: %ld\n", current->ue_id, current->timestamp);
            for (size_t i = 0; i < current->cell_count; ++i) {
                printf("Cell ID: %s\n", current->cells[i].cell_id);
            }
        }
        current = current->next;
    }
}

// Helper function implementations
static Notification* create_notification(int ue_id, time_t timestamp, Cell *cells, size_t cell_count) {
    Notification *notification = (Notification *)malloc(sizeof(Notification));
    if (!notification) return NULL;

    notification->ue_id = ue_id;
    notification->timestamp = timestamp;
    notification->cell_count = cell_count;
    notification->cells = (Cell *)malloc(cell_count * sizeof(Cell));

    if (!notification->cells) {
        free(notification);
        return NULL;
    }

    for (size_t i = 0; i < cell_count; ++i) {
        notification->cells[i].cell_id = strdup(cells[i].cell_id);
        if (!notification->cells[i].cell_id) {
            while (--i >= 0) free(notification->cells[i].cell_id);
            free(notification->cells);
            free(notification);
            return NULL;
        }
    }

    notification->next = NULL;
    return notification;
}

static void free_notification(Notification *notification) {
    for (size_t i = 0; i < notification->cell_count; ++i) {
        free(notification->cells[i].cell_id);
    }
    free(notification->cells);
    free(notification);
}

static void remove_node(Notification **head, Notification *node) {
    if (!*head || !node) return;

    if (*head == node) {
        *head = node->next;
    } else {
        Notification *current = *head;
        while (current && current->next != node) {
            current = current->next;
        }
        if (current) {
            current->next = node->next;
        }
    }

    free_notification(node);
}

static void cleanup_expired_notifications(NotificationList *list, int ue_id, time_t current_time) {
    Notification **indirect = &list->head[ue_id];
    while (*indirect) {
        if (current_time - (*indirect)->timestamp > RETENTION_PERIOD_SECONDS) {
            remove_node(indirect, *indirect);
        } else {
            indirect = &(*indirect)->next;
        }
    }
}

// Example usage
int main() {
    NotificationList list = {0};

    // Add some notifications for testing
    Cell cells1[] = {{.cell_id = "CellA"}, {.cell_id = "CellB"}};
    add_notification(&list, 1, time(NULL), cells1, 2);

    // Simulate waiting and adding more notifications
    sleep(2);
    Cell cells2[] = {{.cell_id = "CellC"}};
    add_notification(&list, 1, time(NULL) + 1000, cells2, 1);

    // Retrieve notifications for UE ID 1 in the last hour
    retrieve_notifications(&list, 1, time(NULL) - RETENTION_PERIOD_SECONDS, time(NULL));

    // Remove outdated notifications
    remove_outdated_notifications(&list, time(NULL));

    return 0;
}
