    // Update cache with new structures (assuming no overflow)
    for (size_t i = 0; i < N && cache_index < CACHE_SIZE; ++i) {
        structure_cache[cache_index++] = &pdu_array[i];
    }

    return pdu_array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t N) {
    if (array) {
        free(array);
        // Clear cache index after freeing
        memset(structure_cache, 0, sizeof(structure_cache));
        cache_index = 0;
