    newNode->next = trafficMonitor.head;
    trafficMonitor.head = newNode;

    pthread_mutex_unlock(&trafficMonitor.lock);
}

void remove_outdated_entries() {
    pthread_mutex_lock(&trafficMonitor.lock);

    Node *current = trafficMonitor.head, *prev = NULL;
    time_t current_time = time(NULL);

    while (current) {
        if (difftime(current_time, current->data.timestamp) > trafficMonitor.retention_period) {
            Node* to_delete = current;
            if (prev == NULL)
                trafficMonitor.head = current->next; // Deleting head
            else
                prev->next = current->next;

            free(to_delete);
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&trafficMonitor.lock);
}

void* retrieve_traffic_data(void* arg) {
    char vehicle_id[20];
    double area_min_lat, area_max_lat, area_min_long, area_max_long;
    time_t start_time, end_time;

    memcpy(vehicle_id, arg, sizeof(char) * 20);
    memcpy(&area_min_lat, (char*)arg + 20, sizeof(double));
    memcpy(&area_max_lat, (char*)arg + 28, sizeof(double));
    memcpy(&area_min_long, (char*)arg + 36, sizeof(double));
    memcpy(&area_max_long, (char*)arg + 44, sizeof(double));
    memcpy(&start_time, (char*)arg + 52, sizeof(time_t));
    memcpy(&end_time, (char*)arg + 60, sizeof(time_t));

    pthread_mutex_lock(&trafficMonitor.lock);

    Node* current = trafficMonitor.head;
    while (current) {
        if ((strcmp(current->data.vehicle_id, vehicle_id) == 0)
            && (current->data.latitude >= area_min_lat && current->data.latitude <= area_max_lat)
            && (current->data.longitude >= area_min_long && current->data.longitude <= area_max_long)
            && (difftime(current->data.timestamp, start_time) >= 0)
            && (difftime(end_time, current->data.timestamp) >= 0)) {

            printf("Vehicle ID: %s\nTimestamp: %ld\nLatitude: %.2f Longitude: %.2f Speed: %.2f Sensors: ", 
                   current->data.vehicle_id, current->data.timestamp, current->data.latitude, current->data.longitude,
                   current->data.speed);
            for (int i = 0; current->data.sensors_triggered[i] != -1; ++i) {
                printf("%d ", current->data.sensors_triggered[i]);
            }
            printf("\n");
        }

        current = current->next;
    }

    pthread_mutex_unlock(&trafficMonitor.lock);
}

void set_retention_period(size_t new_period) {
    pthread_mutex_lock(&trafficMonitor.lock);
    trafficMonitor.retention_period = new_period;
    pthread_mutex_unlock(&trafficMonitor.lock);
}

int main() {
    // Example setup and operations
    TrafficData data1 = {"V123", time(NULL), 40.7128, -74.0060, 60.5, (int[]){1, 2, -1}};
    add_traffic_data(data1);

    // Simulate setting a different retention period
    set_retention_period(1800); // 30 minutes

    // Example retrieval setup
    char params[64];
    strcpy(params, "V123");
    *(double*)(params + 20) = 40.710;
    *(double*)(params + 28) = 40.715;
    *(double*)(params + 36) = -74.008;
    *(double*)(params + 44) = -74.005;
    time_t now = time(NULL);
    *(time_t*)(params + 52) = now - 3600; // last hour
    *(time_t*)(params + 60) = now;

    retrieve_traffic_data(params);

    return 0;
}
