        manager->sessions = calloc(MAX_SESSIONS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->count = 0;
        pthread_mutex_init(&manager->lock, NULL);
    }
    return manager;
}

// Function to update CRC status in a thread-safe manner.
void update_crc_status(NFAPI_CRC_MANAGER_T* manager, uint32_t RX_UE_INFORMATION_TAG, int crc_flag) {
    if (!manager || !manager->sessions) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            manager->sessions[i].CRCFLAG = crc_flag;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to add a new UE session.
void add_ue_session(NFAPI_CRC_MANAGER_T* manager, uint32_t tag, uint16_t rnti, uint8_t crc_tag) {
    if (!manager || !manager->sessions || manager->count >= MAX_SESSIONS) return;

    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T new_session = {tag, rnti, crc_tag, 0};
    manager->sessions[manager->count++] = new_session;
    pthread_mutex_unlock(&manager->lock);
}

// Cleanup function to free allocated resources.
void cleanup_crc_manager(NFAPI_CRC_MANAGER_T* manager) {
    if (manager) {
