#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Assuming these structures are defined elsewhere in your application.
typedef struct {
    int CRCFLAG; // Randomly set 0 or 1 for simplicity
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

#define MAX_NODES 1000

// Doubly linked list structure with thread safety
typedef struct {
    Node* head;
    Node* tail;
    size_t node_count;
    pthread_mutex_t lock; // For synchronizing access
    size_t allocation_count;
    size_t deallocation_count;
} DoublyLinkedList;

void initialize_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->node_count = 0;
    list->allocation_count = 0;
    list->deallocation_count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }

    *(&(new_node->data)) = *data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void free_node(Node* node) {
    free(node);
}

// Insert a new node at the end of the list
int insert_node(DoublyLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    if (list->node_count >= MAX_NODES) {
        reset_list(list); // Reset and reinitialize the list
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Failed to allocate memory for node
    }

    if (list->tail == NULL) {  // Empty list case
        list->head = new_node;
        list->tail = new_node;
    } else {  // Non-empty list
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    list->node_count++;
    list->allocation_count++;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

// Remove the first node from the list (FIFO order)
int remove_first_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {  // Empty list case
        pthread_mutex_unlock(&list->lock);
        return -1; // Nothing to remove
    }

    Node* node_to_remove = list->head;
    *data = node_to_remove->data;

    list->head = node_to_remove->next;
    if (list->head == NULL) {  // Only one element was in the list
        list->tail = NULL;
    } else {
        list->head->prev = NULL;
    }

    free_node(node_to_remove);
    list->node_count--;
    list->deallocation_count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Reset the entire list and reinitialize it
void reset_list(DoublyLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T dummy_data;
    while (remove_first_node(list, &dummy_data) == 0);  // Clear all nodes

    initialize_list(list);
}

// Example function to randomly set CRCFLAG and fill the structure
void populate_random_data(NFAPI_CRC_INDICATION_PDU_T* data) {
    data->RX_UE_INFORMATION_TAG = rand();
    data->RNTI = rand();
    data->crc_tag.CRCFLAG = rand() % 2;
}

// Function to log memory operations for debugging and performance tuning
void log_memory_operations(const DoublyLinkedList* list) {
    printf("Allocations: %zu, Deallocations: %zu\n", list->allocation_count, list->deallocation_count);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    DoublyLinkedList list;
    initialize_list(&list);

    for (size_t i = 0; i < MAX_NODES + 10; ++i) {  // Test beyond max nodes to trigger reset
        NFAPI_CRC_INDICATION_PDU_T data;
        populate_random_data(&data);

        if (insert_node(&list, &data) != 0) {
            fprintf(stderr, "Failed to insert node\n");
        }
    }

    log_memory_operations(&list);

    // Clean up the list
    NFAPI_CRC_INDICATION_PDU_T dummy_data;
    while (remove_first_node(&list, &dummy_data) == 0);
    pthread_mutex_destroy(&list.lock);

    return 0;
}
``` 

This code implements a thread-safe doubly linked list managing `NFAPI_CRC_INDICATION_PDU_T` structures with dynamic insertion and removal capabilities. The list is reset once it reaches its maximum capacity (1000 nodes), ensuring no memory leaks occur. Memory allocation and deallocation operations are tracked for performance monitoring, and the code is designed to be modular and extendable for future enhancements. Random values are assigned to the `CRCFLAG` for demonstration purposes.']

