#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
    long *offset_ptr;
    int *key_ptr;
    struct Record *next;
} Record;

typedef struct {
    Record **head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = (Record **)malloc(sizeof(Record *));
    if (!list->head) {
        free(list);
        return NULL;
    }
    *(list->head) = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

long* allocate_offsets(size_t count) {
    return (long *)calloc(count, sizeof(long));
}

int* allocate_keys(size_t count) {
    return (int *)calloc(count, sizeof(int));
}

Record** allocate_records(size_t count) {
    return (Record **)calloc(count, sizeof(Record *));
}

void insert_record(LinkedList *list, int key, int value, long offset) {
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) return;

    new_record->value = value;
    new_record->offset_ptr = &offset;
    new_record->key_ptr = &key;
    new_record->next = NULL;

    pthread_mutex_lock(&list->lock);
    Record **current = list->head;
    while (*current && key > *(*current)->key_ptr) {
        current = &(*current)->next;
    }
    new_record->next = *current;
    *current = new_record;
    pthread_mutex_unlock(&list->lock);
}

void remove_record(LinkedList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record **current = list->head;
    while (*current && *(*current)->key_ptr != key) {
        current = &(*current)->next;
    }
    if (*current) {
        Record *to_remove = *current;
        *current = to_remove->next;
        free(to_remove);
    }
    pthread_mutex_unlock(&list->lock);
}

void process_batch(LinkedList *list, int start_key, int end_key, void (*process)(Record *)) {
    pthread_mutex_lock(&list->lock);
    Record *current = *(list->head);
    while (current) {
        if (current->value >= start_key && current->value <= end_key) {
            process(current);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Record *current = *(list->head);
    while (current) {
        Record *to_free = current;
        current = current->next;
        free(to_free);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list->head);
    free(list);
}

// Example usage
void example_process(Record *record) {
    printf("Processing record with key: %d, value: %d\n", *(record->key_ptr), record->value);
}

int main() {
    LinkedList *list = create_linked_list();
    if (!list) return 1;

    long *offsets = allocate_offsets(1000000);
    int *keys = allocate_keys(1000000);
    Record **records = allocate_records(1000000);

    // Example insertions
    for (int i = 0; i < 10; ++i) {
        insert_record(list, i, i * 10, i * 100);
    }

    process_batch(list, 20, 50, example_process);

    free(offsets);
    free(keys);
    free(records);
    free_linked_list(list);

    return 0;
}
```

### Key Points:

- **Concurrency**: The linked list operations are protected with a mutex to ensure thread safety.
- **Memory Management**: Memory is dynamically allocated and freed appropriately. Use of `calloc` initializes memory to zero, which can help prevent undefined behavior.
- **Batch Processing**: Records within a specified key range can be processed in batches.
- **Graceful Handling**: The code checks for null pointers after allocations and returns early if necessary to handle out-of-memory conditions gracefully.
- **Efficiency**: The linked list allows efficient insertion and deletion operations based on keys.']

