    NetworkEvent *new_events = (NetworkEvent*)realloc(array->events, new_capacity * sizeof(NetworkEvent));
    if (!new_events) exit(EXIT_FAILURE); // Handle memory allocation error
    array->events = new_events;
    array->capacity = new_capacity;
}

