    strncpy(new_event.DeviceIdentifier, device_id, sizeof(new_event.DeviceIdentifier));
    new_event.Timestamp = timestamp;
    memcpy(new_event.DataPacket, data_packet, sizeof(new_event.DataPacket));

    array->events[array->count++] = new_event;
    return 0; // Success
}

