NetworkEvent* getNetworkEventByTimestamp(EventArray *array, time_t timestamp) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i].Timestamp == timestamp) return &array->events[i];
    }
    return NULL; // Not found
}

// Update an existing network event with new data packet
int updateNetworkEvent(EventArray *array, time_t timestamp, const unsigned char *new_data_packet) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i].Timestamp == timestamp) {
            memcpy(array->events[i].DataPacket, new_data_packet, sizeof(array->events[i].DataPacket));
            return 0; // Success
        }
    }
    return -1; // Not found
}

// Free the dynamic array resources
