#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint16_t rnti;
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    // Assume some fields are defined here
    uint32_t ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 1048575
#define LOG_FILE "nfa_api_log.txt"

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
    uint16_t crcflag_threshold;
    FILE* log_file;
} CRCList;

// Utility function to write logs
void log_message(CRCList* list, const char* message) {
    if (list->log_file) {
        fprintf(list->log_file, "%s\n", message);
        fflush(list->log_file); // Ensure the log is written immediately
    }
}

// Validate RX_UE_INFORMATION_TAG and RNTI
int validate_tag_and_rnti(uint32_t ue_info_tag, uint16_t rnti) {
    return (ue_info_tag > 0 && rnti <= MAX_RNTI);
}

// Check uniqueness of RNTI in the list
int is_unique_rnti(CRCList* list, uint16_t rnti) {
    ListNode* node = list->head;
    while (node != NULL) {
        if (node->data.crc_indication_rel8.rnti == rnti)
            return 0; // RNTI already exists
        node = node->next;
    }
    return 1;
}

// Add a new element to the list with thread safety
int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    if (!validate_tag_and_rnti(new_data.ue_info_tag, new_data.crc_indication_rel8.rnti)) {
        log_message(list, "Invalid UE information tag or RNTI");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (!is_unique_rnti(list, new_data.crc_indication_rel8.rnti)) {
        log_message(list, "Duplicate RNTI detected");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        log_message(list, "Memory allocation failed for new list node");
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;

    log_message(list, "Element added successfully");

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Filter elements based on CRCFLAG threshold
void filter_elements(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    ListNode* prev = NULL;

    while (current != NULL) {
        if (current->data.crc_indication_rel8.crcflag < list->crcflag_threshold) {
            if (prev == NULL) { // head needs to be removed
                list->head = current->next;
                free(current);
                current = list->head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }

    log_message(list, "Filtering operation completed");

    pthread_mutex_unlock(&list->lock);
}

// Serialize the list to a binary file
int serialize_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message(list, "Failed to open file for serialization");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    ListNode* node = list->head;
    while (node != NULL) {
        fwrite(&(node->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        node = node->next;
    }

    log_message(list, "Serialization successful");

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Deserialize the list from a binary file
int deserialize_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message(list, "Failed to open file for deserialization");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        if (add_element(list, data) != 0) {
            log_message(list, "Failed to add element during deserialization");
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -2;
        }
    }

    log_message(list, "Deserialization successful");

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Initialize the CRCList
CRCList* init_crc_list(uint16_t crcflag_threshold) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->crcflag_threshold = crcflag_threshold;
    list->log_file = fopen(LOG_FILE, "a");

    if (!list->log_file) {
        free(list);
        return NULL;
    }

    return list;
}

// Clean up the CRCList
void cleanup_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }

    log_message(list, "Cleanup completed");

    pthread_mutex_unlock(&list->lock);

    fclose(list->log_file);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Periodic checkpoint function
void* periodic_checkpoint(void* arg) {
    CRCList* list = (CRCList*)arg;
    const char* filename = "checkpoint.bin";

    while (1) {
        sleep(60); // Save every 60 seconds
        serialize_list(list, filename);
    }
}

// Usage example:
int main() {
    CRCList* crc_list = init_crc_list(10);

    if (!crc_list) {
        fprintf(stderr, "Failed to initialize CRC list\n");
        return -1;
    }

    pthread_t checkpoint_thread;
    pthread_create(&checkpoint_thread, NULL, periodic_checkpoint, crc_list);

    // Add elements, filter, serialize, deserialize as needed...

    cleanup_crc_list(crc_list);
    return 0;
}
