// QuickSort algorithm for sorting linked list by RNTI
void swap(Node* a, Node* b) {
    NFAPI_CRC_INDICATION_PDU_T temp = a->data;
    a->data = b->data;
    b->data = temp;
}

Node* partition(Node *low, Node *high, Node **new_high) {
    unsigned int pivotRNTI = high->data.crc_rel8_tag.RNTI;

    Node *i = low->prev;

    for (Node *j = low; j != high; j = j->next) {
        if (j->data.crc_rel8_tag.RNTI <= pivotRNTI) {
            i = (i == NULL) ? low : i->next;
            swap(i, j);
        }
    }

    i = (i == NULL) ? low : i->next;
    swap(i, high);

    *new_high = i;

    return i;
}

void quickSortRecur(Node* low, Node* high) {
    if (!low || low == high || low == high->next)
        return;

    Node* new_high;
    Node* p = partition(low, high, &new_high);

    quickSortRecur(low, p->prev);
    quickSortRecur(new_high->next, high);
}

void sort_list_by_rnti() {
