    if (head == NULL || head->next == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    Node* start = head;

    // Find the tail of the linked list
    while (start->next != NULL)
        start = start->next;

    quickSortRecur(head, start);

    pthread_mutex_unlock(&lock);
}

// Function to free all nodes in the linked list
void free_list() {
    Node* current = head;
    Node* next_node;

    while (current) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    head = NULL;
}

