typedef enum { IDLE, CONNECTED } RRC_STATE;
typedef struct {
    int signal_strength;
    double frequency;
} MeasurementReport;

typedef struct {
    int preamble_info;
    int srs_info;
} ReceptionInfo;

typedef struct {
    int UE_ID;
    RRC_STATE rrc_state;
    ReceptionInfo preamble_reception_info;
    ReceptionInfo srs_reception_info;
    MeasurementReport measurement_report;
} NR_UE_CONTEXT;

typedef struct Node {
    NR_UE_CONTEXT data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int size;
} UE_Context_Array;

void log_action(const char* action, int ue_id) {
    // Simple logging mechanism
    printf("Action: %s, UE_ID: %d\n", action, ue_id);
}

UE_Context_Array* create_ue_context_array() {
    UE_Context_Array* array = (UE_Context_Array*)malloc(sizeof(UE_Context_Array));
    if (!array) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->size = 0;
    return array;
}

int add_ue_context(UE_Context_Array* array, NR_UE_CONTEXT context) {
    pthread_mutex_lock(&array->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory allocation failed
    }

    new_node->data = context;
    new_node->next = array->head;
    array->head = new_node;
    array->size++;

    log_action("Added", context.UE_ID);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_ue_context(UE_Context_Array* array, int ue_id, NR_UE_CONTEXT updated_context) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        if (current->data.UE_ID == ue_id) {
            current->data = updated_context;
            log_action("Updated", ue_id);
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // UE_ID not found
}

int remove_ue_context(UE_Context_Array* array, int ue_id) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *prev = NULL;
    while (current) {
        if (current->data.UE_ID == ue_id) {
            if (prev) prev->next = current->next;
            else array->head = current->next;

            free(current);
            array->size--;
            log_action("Removed", ue_id);

            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // UE_ID not found
}

void serialize_array(const UE_Context_Array* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        fwrite(&(current->data), sizeof(NR_UE_CONTEXT), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    fclose(file);
}

int deserialize_array(UE_Context_Array* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&array->lock);

    NR_UE_CONTEXT context;
    while (fread(&context, sizeof(NR_UE_CONTEXT), 1, file)) {
        add_ue_context(array, context);
    }

    pthread_mutex_unlock(&array->lock);
    fclose(file);
    return 0;
}

void free_ue_context_array(UE_Context_Array* array) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage
int main() {
    UE_Context_Array* array = create_ue_context_array();
    if (!array) return -1;

    NR_UE_CONTEXT context = { .UE_ID = 1, .rrc_state = CONNECTED, .preamble_reception_info = {1}, .srs_reception_info = {2}, .measurement_report = {100, 1800.0} };
    add_ue_context(array, context);

    serialize_array(array, "ue_data.bin");
    deserialize_array(array, "ue_data.bin");

    free_ue_context_array(array);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The array is protected with a mutex to ensure thread-safe operations.
- **Error Handling**: Memory allocation failures are checked and handled gracefully.
- **Logging**: A simple logging function tracks actions without significant performance overhead.
- **Serialization/Deserialization**: Binary format is used for efficient storage and retrieval of the data.
- **Memory Management**: Proper freeing of allocated memory to prevent leaks.

This implementation provides a robust foundation for managing UE contexts in a multi-threaded environment.']

