#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RETENTION_PERIOD 60 // seconds, configurable

typedef struct {
    int valid;
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    time_t timestamp; // Time when the entry was added
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock; // For thread-safe operations
} NFACache;

// Initialize cache
NFACache* initCache() {
    NFACache* cache = (NFACache*)malloc(sizeof(NFACache));
    cache->head = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Add new entry
void addEntry(NFACache* cache, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&cache->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = entry;
    newNode->next = cache->head;
    cache->head = newNode;

    pthread_mutex_unlock(&cache->lock);
}

// Remove outdated entries
void removeOutdatedEntries(NFACache* cache) {
    pthread_mutex_lock(&cache->lock);

    time_t currentTime = time(NULL);
    Node *current = cache->head, *prev = NULL;

    while (current != NULL) {
        if ((currentTime - current->data.timestamp) > RETENTION_PERIOD) {
            Node* toDelete = current;
            if (prev == NULL) { // Removing head
                cache->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(toDelete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

// Retrieve entries for a specific RNTI within a time range
void retrieveEntries(NFACache* cache, unsigned long rnti, time_t startTime, time_t endTime, NFAPI_CRC_INDICATION_PDU_T** results, int* count) {
    pthread_mutex_lock(&cache->lock);

    *count = 0;
    Node* current = cache->head;

    while (current != NULL) {
        if (current->data.RNTI == rnti &&
            current->data.timestamp >= startTime &&
            current->data.timestamp <= endTime) {
            (*results)[(*count)++] = current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
}

// Cleanup cache
void cleanupCache(NFACache* cache) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current != NULL) {
        Node* toDelete = current;
        current = current->next;
        free(toDelete);
    }

    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Example usage
int main() {
    NFACache* cache = initCache();

    NFAPI_CRC_INDICATION_PDU_T entry1 = {1, 12345, 67890, 0x01, 0xFF, time(NULL)};
    addEntry(cache, entry1);

    // Simulate passage of time
    sleep(61);

    removeOutdatedEntries(cache);

    // Cleanup
    cleanupCache(cache);

    return 0;
}
