typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    time_t current_time;
    float variance_threshold;
    int system_load; // Simulated system load for dynamic window adjustment
} SlidingWindow;

void init_sliding_window(SlidingWindow *window, size_t initial_capacity) {
    window->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    window->capacity = initial_capacity;
    window->count = 0;
    time(&window->current_time);
    window->variance_threshold = 0.5; // Example threshold
    window->system_load = 50; // Simulated load percentage
}

void free_sliding_window(SlidingWindow *window) {
    free(window->data);
}

void adjust_window_size(SlidingWindow *window) {
    if (window->system_load > 75) {
        window->capacity = MAX(100, window->capacity / 2);
    } else if (window->system_load < 25 && window->count == window->capacity) {
        window->capacity *= 2;
    }
}

void process_data_point(SlidingWindow *window, NFAPI_CRC_INDICATION_PDU_T data_point) {
    time(&data_point.timestamp);

    // Adjust window size based on system load
    adjust_window_size(window);

    if (window->count == window->capacity) {
        memmove(window->data, &window->data[1], (window->capacity - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        window->count--;
    }

    window->data[window->count++] = data_point;
}

void calculate_metrics(SlidingWindow *window) {
    float sum = 0, variance_sum = 0;
    uint32_t peak_value = 0;

    for (size_t i = 0; i < window->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &window->data[i];
        sum += pdu->CRCFLAG;
        variance_sum += pdu->CRCFLAG * pdu->CRCFLAG;
        if (pdu->RNTI > peak_value) {
            peak_value = pdu->RNTI;
        }
    }

    float average = sum / window->count;
    float variance = variance_sum / window->count - average * average;

    printf("Average Variance: %f\n", variance);
    printf("Peak Value: %u\n", peak_value);

    // Calculate data freshness
    time_t now;
    time(&now);
    size_t fresh_count = 0;
    for (size_t i = 0; i < window->count; ++i) {
        if ((now - window->data[i].timestamp) <= 60) { // Consider data within the last minute as fresh
            fresh_count++;
        }
    }

    float freshness_percentage = (fresh_count / (float)window->count) * 100;
    printf("Data Freshness: %.2f%%\n", freshness_percentage);
}

void simulate_data_input(SlidingWindow *window, size_t num_points) {
    for (size_t i = 0; i < num_points; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.valid_RX_UE_INFORMATION_TAG = rand() % 1024;
        pdu.RNTI = rand() % 1000000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = (rand() % 2 == 0) ? 1 : -1; // Randomly set CRCFLAG

        process_data_point(window, pdu);
    }
}

int main() {
    SlidingWindow window;
    init_sliding_window(&window, INITIAL_WINDOW_SIZE);

    simulate_data_input(&window, MAX_DATA_POINTS);

    calculate_metrics(&window);

    free_sliding_window(&window);
    return 0;
}
