    new_node->data.rnti = rnti;
    new_node->data.crcflag = crcflag;
    new_node->data.timestamp = time(NULL);

    new_node->next = list.head;
    list.head = new_node;

    pthread_mutex_unlock(&list.lock);
}

void remove_outdated_entries() {
    pthread_mutex_lock(&list.lock);

    Node *current = list.head, *prev = NULL;
    time_t now = time(NULL);

    while (current) {
        if (difftime(now, current->data.timestamp) > list.retention_period) {
            Node* to_delete = current;
            current = current->next;

            if (prev)
                prev->next = current;
            else
                list.head = current;

            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list.lock);
}

void* get_entries_for_rnti(unsigned int rnti, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current) {
        if (current->data.rnti == rnti &&
            difftime(current->data.timestamp, start_time) >= 0 &&
            difftime(end_time, current->data.timestamp) >= 0) {

            // Process the entry or store it in a result structure
            printf("RNTI: %u, CRCFLAG: %d, Timestamp: %ld\n",
                   current->data.rnti,
                   current->data.crcflag,
                   current->data.timestamp);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);

    return NULL; // or a pointer to the result structure
}

void set_retention_period(time_t new_retention) {
    pthread_mutex_lock(&list.lock);
    list.retention_period = new_retention;
    pthread_mutex_unlock(&list.lock);
}

void cleanup() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list.head = NULL;

    pthread_mutex_unlock(&list.lock);
}

int main() {
    // Example usage
    set_retention_period(60); // Set retention period to 1 minute

    for (int i = 0; i < MAX_UE_IDENTIFIERS; ++i) {
        add_entry(i, rand() % 256);
    }

    remove_outdated_entries();

    get_entries_for_rnti(12345, time(NULL) - 300, time(NULL));

    cleanup();
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for synchronization.
- **Memory Management**: Ensures no memory leaks by freeing nodes when they are removed or during cleanup.
- **Dynamic Retention Period**: Allows setting the retention period at runtime.
- **Efficient Removal**: Traverses the list to remove outdated entries based on the retention period.
- **Entry Retrieval**: Retrieves entries for a specific RNTI within a time range.

This code is designed to be efficient and scalable, handling high volumes of data with minimal memory usage. Adjustments may be needed based on specific system constraints or additional requirements.']

