// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned short CRCFLAG; // Randomly set CRC flag
    time_t timestamp;       // Timestamp of creation
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define a structure for managing the dynamic list
typedef struct {
    Node* head;
    time_t retention_period; // Configurable retention period
} DynamicList;

// Function prototypes
void initialize_list(DynamicList* list, time_t retention_period);
void add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry);
void remove_outdated_entries(DynamicList* list);
NFAPI_CRC_INDICATION_PDU_T* retrieve_entries_for_RNTI(DynamicList* list, unsigned long RNTI, time_t start_time, time_t end_time);
void free_list(DynamicList* list);

// Function implementations
void initialize_list(DynamicList* list, time_t retention_period) {
    list->head = NULL;
    list->retention_period = retention_period;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = entry;
    new_node->next = NULL;
    return new_node;
}

void add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    Node* new_node = create_node(entry);
    new_node->next = list->head;
    list->head = new_node;
}

void remove_outdated_entries(DynamicList* list) {
    time_t current_time = time(NULL);
    while (list->head && (current_time - list->head->data.timestamp > list->retention_period)) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_entries_for_RNTI(DynamicList* list, unsigned long RNTI, time_t start_time, time_t end_time) {
    Node* current = list->head;
    size_t count = 0;

    // First pass to count the entries
    while (current) {
        if (current->data.RNTI == RNTI &&
            current->data.timestamp >= start_time &&
            current->data.timestamp <= end_time) {
            count++;
        }
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entries) {
        perror("Failed to allocate memory for retrieval");
        return NULL;
    }

    // Second pass to collect the entries
    current = list->head;
    size_t index = 0;
    while (current) {
        if (current->data.RNTI == RNTI &&
            current->data.timestamp >= start_time &&
            current->data.timestamp <= end_time) {
            entries[index++] = current->data;
        }
        current = current->next;
    }

    return entries; // Caller is responsible for freeing this memory
}

void free_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
}
