int message_count = 0;

void add_or_update_message(int transaction_id, NasMessageType type, const char *emm_data) {
    LTE_NAS_Message *current = head;
    LTE_NAS_Message *prev = NULL;

    while (current != NULL && current->transaction_id != transaction_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Add new message
        if (message_count >= MAX_MESSAGES) {
            fprintf(stderr, "Maximum message limit reached.\n");
            return;
        }
        current = malloc(sizeof(LTE_NAS_Message));
        if (!current) {
            perror("Failed to allocate memory for new message");
            return;
        }

        memset(current, 0, sizeof(LTE_NAS_Message));
        current->transaction_id = transaction_id;
        current->type = type;

        if (emm_data != NULL) {
            current->emm_message = malloc(sizeof(EMM_Message));
            if (!current->emm_message) {
                perror("Failed to allocate memory for EMM message");
                free(current);
                return;
            }
            current->emm_message->emm_length = strlen(emm_data);
            current->emm_message->emm_message = strdup(emm_data);
            if (!current->emm_message->emm_message) {
                perror("Failed to duplicate EMM message data");
                free(current->emm_message);
                free(current);
                return;
            }
        }

        current->next = head;
        head = current;
        message_count++;
    } else { // Update existing message
        if (current->type != type || (!emm_data && current->emm_message)) {
            fprintf(stderr, "Updating transaction ID %d with new data\n", transaction_id);
        }
        current->type = type;

        if (emm_data != NULL) {
            free(current->emm_message->emm_message);
            current->emm_message->emm_length = strlen(emm_data);
            current->emm_message->emm_message = strdup(emm_data);
            if (!current->emm_message->emm_message) {
                perror("Failed to duplicate EMM message data");
                return;
            }
        } else if (current->emm_message != NULL) {
            free(current->emm_message->emm_message);
            free(current->emm_message);
            current->emm_message = NULL;
        }
    }

    // Push to external messaging service
    push_to_messaging_service(transaction_id, type, current->emm_message);

    // Serialize to binary file
    serialize_message(transaction_id, type, current->emm_message);
}

void remove_messages_by_condition(void (*condition)(LTE_NAS_Message *message)) {
    LTE_NAS_Message *current = head;
    LTE_NAS_Message *prev = NULL;

    while (current != NULL) {
        if (condition(current)) {
            if (prev == NULL) { // Remove head
                head = current->next;
            } else {
                prev->next = current->next;
            }

            free_message(current);
            message_count--;
        }
        prev = current;
        current = current->next;
    }
}

void free_message(LTE_NAS_Message *message) {
    if (message->emm_message != NULL) {
        free(message->emm_message->emm_message);
        free(message->emm_message);
    }
    free(message);
}

void push_to_messaging_service(int transaction_id, NasMessageType type, EMM_Message *emm_message) {
    // Simulate pushing to an external messaging service
    // Implement actual network call with retry logic here
    printf("Pushing message %d of type %d to messaging service\n", transaction_id, type);
}

void serialize_message(int transaction_id, NasMessageType type, EMM_Message *emm_message) {
    FILE *file = fopen("messages.bin", "ab");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    // Serialize the message
    fwrite(&transaction_id, sizeof(transaction_id), 1, file);
    fwrite(&type, sizeof(type), 1, file);

    size_t emm_length = emm_message ? emm_message->emm_length : 0;
    fwrite(&emm_length, sizeof(emm_length), 1, file);
    if (emm_length > 0) {
        fwrite(emm_message->emm_message, sizeof(char), emm_length, file);
    }

    fclose(file);
}

// Example condition function
void example_condition(LTE_NAS_Message *message) {
