    if (message->transaction_id % 2 == 0) { // Example condition: even transaction IDs
        return;
    }
    printf("Message %d does not meet removal condition\n", message->transaction_id);
}

int main() {
    add_or_update_message(1, NAS_MESSAGE_TYPE_1, "EMM data for message 1");
    add_or_update_message(2, NAS_MESSAGE_TYPE_2, NULL);

    remove_messages_by_condition(example_condition);

    return 0;
}
