#define MAX_RNTI 1000
#define MIN_RNTI 1
#define STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define REPORT_DETAILED 1
#define REPORT_SUMMARY 2

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[10];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
} NFAPI_CRC_LIST_T;

int generate_crc_list(NFAPI_CRC_LIST_T *list, size_t n, int report_level);
void export_to_binary(const char *filename, const NFAPI_CRC_LIST_T *list);
void free_crc_list(NFAPI_CRC_LIST_T *list);

int main() {
    NFAPI_CRC_LIST_T crcList;
    if (generate_crc_list(&crcList, 100, REPORT_DETAILED)) {
        export_to_binary("output.bin", &crcList);
    }
    free_crc_list(&crcList);
    return 0;
}

int generate_crc_list(NFAPI_CRC_LIST_T *list, size_t n, int report_level) {
    list->data = malloc(n * STRUCT_SIZE);
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    list->count = 0;

    srand(time(NULL));
    unsigned int used_rntis[MAX_RNTI] = {0};
    size_t successful_creations = 0;

    while (successful_creations < n) {
        if ((list->count + 1) * STRUCT_SIZE > malloc_usable_size(list->data)) {
            fprintf(stderr, "Memory limit reached\n");
            free_crc_list(list);
            return -2;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)((char *)list->data + list->count * STRUCT_SIZE);

        unsigned int rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        if (used_rntis[rnti]) {
            continue;
        }

        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rnti;
        memset(pdu->CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu->CRC_INDICATION_REL8_TAG));
        pdu->CRCFLAG = (rand() % 2) ? 1 : 0;

        used_rntis[rnti] = 1;
        list->count++;
        successful_creations++;

        if (report_level == REPORT_DETAILED) {
            printf("Generated PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
        }
    }

    if (report_level == REPORT_DETAILED || report_level == REPORT_SUMMARY) {
        printf("Total structures created: %zu\n", list->count);
    }

    return 0;
}

void export_to_binary(const char *filename, const NFAPI_CRC_LIST_T *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(list->data, STRUCT_SIZE, list->count, file);
    fclose(file);

    if (printf("Exported %zu structures to %s\n", list->count, filename)) {}
}

void free_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->data);
}
