#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int NAS_Message_Id;
    char *Message;
    int Status;
} LTE_NAS_Message;

typedef struct {
    LTE_NAS_Message **messages;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_NAS_Array;

static void resize_array(LTE_NAS_Array *arr) {
    size_t new_capacity = arr->capacity ? arr->capacity * 2 : 4;
    LTE_NAS_Message **new_messages = realloc(arr->messages, new_capacity * sizeof(LTE_NAS_Message *));
    if (new_messages) {
        arr->messages = new_messages;
        arr->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to resize array\n");
    }
}

LTE_NAS_Array* create_array() {
    LTE_NAS_Array *arr = malloc(sizeof(LTE_NAS_Array));
    if (arr) {
        arr->messages = NULL;
        arr->size = 0;
        arr->capacity = 0;
        pthread_mutex_init(&arr->lock, NULL);
    }
    return arr;
}

void free_array(LTE_NAS_Array *arr) {
    if (!arr) return;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->messages[i]->Message);
        free(arr->messages[i]);
    }
    free(arr->messages);

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_message(LTE_NAS_Array *arr, LTE_NAS_Message *msg) {
    if (!arr || !msg) return -1;

    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        resize_array(arr);
    }

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->messages[i]->NAS_Message_Id == msg->NAS_Message_Id) {
            pthread_mutex_unlock(&arr->lock);
            return -2; // Message ID already exists
        }
    }

    LTE_NAS_Message *new_msg = malloc(sizeof(LTE_NAS_Message));
    if (!new_msg) {
        pthread_mutex_unlock(&arr->lock);
        return -3; // Memory allocation failed
    }

    new_msg->NAS_Message_Id = msg->NAS_Message_Id;
    new_msg->Message = strdup(msg->Message);
    new_msg->Status = msg->Status;

    arr->messages[arr->size++] = new_msg;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int update_message(LTE_NAS_Array *arr, int NAS_Message_Id, char *new_message, int new_status) {
    if (!arr || !new_message) return -1;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->messages[i]->NAS_Message_Id == NAS_Message_Id) {
            free(arr->messages[i]->Message);
            arr->messages[i]->Message = strdup(new_message);
            arr->messages[i]->Status = new_status;
            pthread_mutex_unlock(&arr->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -2; // Message ID not found
}

int remove_message(LTE_NAS_Array *arr, int NAS_Message_Id) {
    if (!arr) return -1;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->messages[i]->NAS_Message_Id == NAS_Message_Id) {
            free(arr->messages[i]->Message);
            free(arr->messages[i]);

            // Shift remaining elements
            memmove(&arr->messages[i], &arr->messages[i + 1], (arr->size - i - 1) * sizeof(LTE_NAS_Message *));
            arr->size--;

            pthread_mutex_unlock(&arr->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -2; // Message ID not found
}

void cleanup(void (*cleanup_func)(LTE_NAS_Array *)) {
    atexit(cleanup_func);
}
