#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    int napi;
    unsigned long rx_ue_information_tag;
    unsigned short rnti;
    bool crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned char* data;
    size_t length;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    unsigned int message_count;
    // Assuming maximum messages we might handle
    unsigned int max_messages;
    void** messages; // Array of pointers to Message objects
} MessageCollection;

typedef struct Message {
    time_t timestamp;
    unsigned long id;
    int priority;
    bool valid;
} Message;

// Function Prototypes
MessageCollection* create_message_collection(unsigned int max_messages);
void destroy_message_collection(MessageCollection* collection);
bool add_message(MessageCollection* collection, unsigned long id, time_t timestamp, int priority);
bool update_message(MessageCollection* collection, unsigned long id, time_t new_timestamp, int new_priority);
Message* get_message(MessageCollection* collection, unsigned long id);
void iterate_messages_in_chronological_order(MessageCollection* collection);

NFAPI_CRC_INDICATION_PDU_T* process_rx_ues(RX_UE_INFORMATION_TAG rx_ues[], size_t count);
void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t* count);

// Function Definitions
MessageCollection* create_message_collection(unsigned int max_messages) {
    MessageCollection* collection = malloc(sizeof(MessageCollection));
    if (!collection) return NULL;

    pthread_mutex_init(&collection->lock, NULL);
    collection->message_count = 0;
    collection->max_messages = max_messages;
    collection->messages = calloc(max_messages, sizeof(void*));

    return collection;
}

void destroy_message_collection(MessageCollection* collection) {
    if (collection) {
        for (unsigned int i = 0; i < collection->message_count; ++i) {
            free(collection->messages[i]);
        }
        free(collection->messages);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

bool add_message(MessageCollection* collection, unsigned long id, time_t timestamp, int priority) {
    if (timestamp <= 0 || priority < 0) return false;

    pthread_mutex_lock(&collection->lock);

    for (unsigned int i = 0; i < collection->message_count; ++i) {
        Message* msg = (Message*)collection->messages[i];
        if (msg && msg->id == id) {
            pthread_mutex_unlock(&collection->lock);
            return false; // Duplicate ID found
        }
    }

    if (collection->message_count >= collection->max_messages) {
        pthread_mutex_unlock(&collection->lock);
        return false; // Collection full
    }

    Message* msg = malloc(sizeof(Message));
    if (!msg) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }

    msg->id = id;
    msg->timestamp = timestamp;
    msg->priority = priority;
    msg->valid = true;

    collection->messages[collection->message_count++] = msg;
    pthread_mutex_unlock(&collection->lock);
    return true;
}

bool update_message(MessageCollection* collection, unsigned long id, time_t new_timestamp, int new_priority) {
    if (new_timestamp <= 0 || new_priority < 0) return false;

    pthread_mutex_lock(&collection->lock);

    for (unsigned int i = 0; i < collection->message_count; ++i) {
        Message* msg = (Message*)collection->messages[i];
        if (msg && msg->id == id) {
            msg->timestamp = new_timestamp;
            msg->priority = new_priority;
            pthread_mutex_unlock(&collection->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return false; // Message not found
}

Message* get_message(MessageCollection* collection, unsigned long id) {
    pthread_mutex_lock(&collection->lock);

    for (unsigned int i = 0; i < collection->message_count; ++i) {
        Message* msg = (Message*)collection->messages[i];
        if (msg && msg->id == id) {
            pthread_mutex_unlock(&collection->lock);
            return msg;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Message not found
}

void iterate_messages_in_chronological_order(MessageCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    // Create a temporary array to sort messages by timestamp
    Message** sorted_messages = malloc(collection->message_count * sizeof(Message*));
    if (!sorted_messages) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    for (unsigned int i = 0; i < collection->message_count; ++i) {
        sorted_messages[i] = (Message*)collection->messages[i];
    }

    // Simple bubble sort for demonstration purposes
    bool swapped;
    do {
        swapped = false;
        for (unsigned int i = 1; i < collection->message_count; ++i) {
            if (sorted_messages[i-1]->timestamp > sorted_messages[i]->timestamp) {
                Message* temp = sorted_messages[i-1];
                sorted_messages[i-1] = sorted_messages[i];
                sorted_messages[i] = temp;
                swapped = true;
            }
        }
    } while (swapped);

    for (unsigned int i = 0; i < collection->message_count; ++i) {
        printf("Message ID: %lu, Timestamp: %ld, Priority: %d\n", 
               sorted_messages[i]->id, sorted_messages[i]->timestamp, sorted_messages[i]->priority);
    }

    free(sorted_messages);
    pthread_mutex_unlock(&collection->lock);
}

NFAPI_CRC_INDICATION_PDU_T* process_rx_ues(RX_UE_INFORMATION_TAG rx_ues[], size_t count) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return NULL;

    for (size_t i = 0; i < count; ++i) {
        pdu_list[i].data = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!pdu_list[i].data) {
            // Handle allocation failure
            break;
        }

        CRC_INDICATION_REL8_TAG* tag = (CRC_INDICATION_REL8_TAG*)pdu_list[i].data;
        memset(tag, 0, sizeof(CRC_INDICATION_REL8_TAG));

        tag->napi = rx_ues[i].napi;
        tag->rx_ue_information_tag = rx_ues[i].rx_ue_information_tag;
        tag->rnti = rx_ues[i].rnti;

        // Randomly set CRCFLAG
        tag->crcflag = rand() % 2 == 0;
    }

    return pdu_list;
}

void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t* count) {
    *pdu_list = process_rx_ues(/* RX_UE_INFORMATION_TAG data */, /* Count */);
    if (*pdu_list) {
        *count = /* Number of processed entries */;
    } else {
        *count = 0;
    }
}

// Usage Example
int main() {
    MessageCollection* collection = create_message_collection(100);

    add_message(collection, 1, time(NULL), 5);
    update_message(collection, 1, time(NULL) + 3600, 10);

    Message* msg = get_message(collection, 1);
    if (msg) {
        printf("Retrieved Message ID: %lu\n", msg->id);
    }

    iterate_messages_in_chronological_order(collection);

    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
    populate_crc_indications(&pdu_list, &count);

    // Clean up
    destroy_message_collection(collection);

    return 0;
}
