#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TID 1000
#define MIN_TID 1

typedef struct {
    int logical_channel_group;
    int tid;
    int transmit_buffer_state;
} MAC_CONTEXT_T;

typedef struct Node {
    MAC_CONTEXT_T context;
    struct Node* next;
} Node;

// Function to check if a TID is already used in the list
int is_tid_used(Node* head, int tid) {
    Node* current = head;
    while (current != NULL) {
        if (current->context.tid == tid) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Function to generate and populate MAC_CONTEXT_T structures
Node* generate_mac_context_list(int count, int valid_channel_group_min, int valid_channel_group_max,
                                int valid_buffer_state_min, int valid_buffer_state_max) {
    Node* head = NULL;
    Node** ptr = &head;

    for (int i = 0; i < count;) {
        MAC_CONTEXT_T context;
        int tid;

        do {
            context.logical_channel_group = rand() % (valid_channel_group_max - valid_channel_group_min + 1) + valid_channel_group_min;
            context.transmit_buffer_state = rand() % (valid_buffer_state_max - valid_buffer_state_min + 1) + valid_buffer_state_min;
            tid = rand() % (MAX_TID - MIN_TID + 1) + MIN_TID;
        } while (is_tid_used(head, tid));

        context.tid = tid;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL; // Return on failure
        }

        new_node->context = context;
        new_node->next = NULL;
        *ptr = new_node;
        ptr = &new_node->next;

        i++;
    }

    return head;
}

// Function to export MAC_CONTEXT_T structures to a text-based format
int export_mac_context_list(Node* head, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    Node* current = head;
    while (current != NULL) {
        fprintf(file, "Logical Channel Group: %d, TID: %d, Transmit Buffer State: %d\n",
                current->context.logical_channel_group,
                current->context.tid,
                current->context.transmit_buffer_state);
        current = current->next;
    }

    fclose(file);
    return 0; // Success
}

// Function to generate a detailed report
void generate_report(Node* head, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    int count = 0;
    Node* current = head;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    fprintf(file, "Total MAC_CONTEXT_T structures created: %d\n", count);

    fclose(file);
}

// Main function for demonstration
int main() {
    int count = 10; // Number of structures to generate

    Node* mac_context_list = generate_mac_context_list(count, 0, 5, 0, 10);
    if (mac_context_list) {
        export_mac_context_list(mac_context_list, "output.txt");
        generate_report(mac_context_list, "report.txt");

        // Free allocated memory
        Node* current = mac_context_list;
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    return 0;
}
