    return (rnti >= RNTI_RANGE_START && rnti <= RNTI_RANGE_END);
}

void initialize_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int data_present) {
    pdu->rx_ue_info_tag.rx_ue_information_tag_valid = 1; // Assume valid for this example
    pdu->crc_rel8_tag.crc_indication_rel8_tag = (data_present ? 0x01 : 0x00);
}

void init_nfa_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t num_elements) {
    if (!pdu_list || num_elements > MAX_ELEMENTS) {
        log_error("Invalid parameters for NFAPI_CRC_INDICATION_PDU list initialization.");
        return;
    }

    uint16_t rnti_values[MAX_ELEMENTS];
    int used_rntis = 0;

    // Initialize RNTIs with unique values within the specified range
    for (uint16_t i = RNTI_RANGE_START; i <= RNTI_RANGE_END && used_rntis < num_elements; ++i) {
        rnti_values[used_rntis++] = i;
    }

    if (used_rntis < num_elements) {
        log_error("Not enough unique RNTIs available.");
        return;
    }

    // Shuffle the array to randomize RNTI assignment
    for (size_t i = 0; i < num_elements - 1; ++i) {
        size_t j = i + rand() / (RAND_MAX / (num_elements - i) + 1);
        uint16_t temp = rnti_values[j];
        rnti_values[j] = rnti_values[i];
        rnti_values[i] = temp;
    }

    // Populate the list with NFAPI_CRC_INDICATION_PDU structures
    for (size_t i = 0; i < num_elements; ++i) {
        uint16_t rnti = rnti_values[i];

        if (!validate_rnti(rnti)) {
            log_error("Invalid RNTI encountered during initialization.");
            continue;
        }

        pdu_list[i].rx_ue_info_tag.rnti = rnti;

        // Simulate presence of data for CRC indication
        initialize_crc_indication_pdu(&pdu_list[i], 1); // Assuming data is present
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu_list[MAX_ELEMENTS];

    init_nfa_crc_pdu_list(pdu_list, MAX_ELEMENTS);

    return 0;
}
```

