#include <time.h>
#include <pthread.h>

#define MAX_CONTENT_LENGTH 256
#define TIMESTAMP_MIN 1609459200 // Example: Unix timestamp for Jan 1, 2021
#define TIMESTAMP_MAX 2147483647

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int rnti;
    CRC_INDICATION_REL8_TAG crcRel8Tag;
} RNTI;

typedef struct {
    unsigned short ueIndex;
    RNTI rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int header;
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    char message[MAX_CONTENT_LENGTH + 1];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Message {
    time_t timestamp;
    unsigned long id;
    int priority;
    char content[MAX_CONTENT_LENGTH + 1];
    struct Message* next;
} Message;

typedef struct {
    Message* head;
    pthread_mutex_t mutex;
    unsigned long current_id;
} MessageLibrary;

MessageLibrary* create_message_library() {
    MessageLibrary* lib = malloc(sizeof(MessageLibrary));
    if (!lib) return NULL;
    lib->head = NULL;
    pthread_mutex_init(&lib->mutex, NULL);
    lib->current_id = 1; // Start IDs from 1
    return lib;
}

void destroy_message_library(MessageLibrary* lib) {
    Message* current = lib->head;
    while (current) {
        Message* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}

int is_valid_timestamp(time_t timestamp) {
    return timestamp >= TIMESTAMP_MIN && timestamp <= TIMESTAMP_MAX;
}

int add_message(MessageLibrary* lib, time_t timestamp, int priority, const char* content) {
    if (!is_valid_timestamp(timestamp) || strlen(content) > MAX_CONTENT_LENGTH)
        return -1;

    pthread_mutex_lock(&lib->mutex);

    Message* new_msg = malloc(sizeof(Message));
    if (!new_msg) {
        pthread_mutex_unlock(&lib->mutex);
        return -1;
    }

    new_msg->timestamp = timestamp;
    new_msg->id = lib->current_id++;
    new_msg->priority = priority;
    strncpy(new_msg->content, content, MAX_CONTENT_LENGTH);
    new_msg->next = NULL;

    if (!lib->head || timestamp < lib->head->timestamp) {
        new_msg->next = lib->head;
        lib->head = new_msg;
    } else {
        Message* current = lib->head;
        while (current->next && current->next->timestamp <= timestamp) {
            current = current->next;
        }
        new_msg->next = current->next;
        current->next = new_msg;
    }

    pthread_mutex_unlock(&lib->mutex);
    return 0;
}

int update_message(MessageLibrary* lib, unsigned long id, time_t timestamp, const char* content) {
    if (!is_valid_timestamp(timestamp) || strlen(content) > MAX_CONTENT_LENGTH)
        return -1;

    pthread_mutex_lock(&lib->mutex);

    Message* current = lib->head;
    while (current && current->id != id) {
        current = current->next;
    }

    if (current) {
        current->timestamp = timestamp;
        strncpy(current->content, content, MAX_CONTENT_LENGTH);
    } else {
        pthread_mutex_unlock(&lib->mutex);
        return -1;
    }

    pthread_mutex_unlock(&lib->mutex);
    return 0;
}

Message* get_message(MessageLibrary* lib, unsigned long id) {
    Message default_msg = { .timestamp = TIMESTAMP_MIN, .id = id, .priority = 0 };
    memset(default_msg.content, '\0', MAX_CONTENT_LENGTH + 1);

    pthread_mutex_lock(&lib->mutex);

    Message* current = lib->head;
    while (current && current->id != id) {
        current = current->next;
    }

    Message* result = current ? current : &default_msg;

    pthread_mutex_unlock(&lib->mutex);
    return result;
}

void iterate_messages(MessageLibrary* lib, void (*callback)(Message*)) {
    pthread_mutex_lock(&lib->mutex);

    for (Message* msg = lib->head; msg != NULL; msg = msg->next) {
        callback(msg);
    }

    pthread_mutex_unlock(&lib->mutex);
}

NFAPI_CRC_INDICATION_PDU_T populate_pdu(RX_UE_INFORMATION_TAG rxUeInfoTag, int crcFlag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.header = 0; // Example header
    pdu.rxUeInfoTag = rxUeInfoTag;
    CRC_INDICATION_REL8_TAG* crcRel8Tag = &pdu.rxUeInfoTag.rnti.crcRel8Tag;
    crcRel8Tag->crcFlag = (crcFlag >= 0 && crcFlag <= 1) ? crcFlag : rand() % 2;

    return pdu;
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        RX_UE_INFORMATION_TAG rxUeInfoTag = { .ueIndex = rand() % 1000 };
        int crcFlag = rand() % 2;
        list[i] = populate_pdu(rxUeInfoTag, crcFlag);
    }
}

void log_event(const char* event) {
    // Example logging function
    printf("LOG: %s\n", event);
}

int main() {
    MessageLibrary* lib = create_message_library();

    if (!lib) {
        log_event("Failed to initialize message library.");
        return -1;
    }

    add_message(lib, time(NULL), 1, "Hello World");
    iterate_messages(lib, [](Message* msg) { printf("ID: %lu, Content: %s\n", msg->id, msg->content); });

    destroy_message_library(lib);
    return 0;
}
