int allocate_memory(long **offset_array, int **key_array, record **records, size_t num_records) {
    // Validate and handle integer overflow for array sizes
    if (num_records > SIZE_MAX / sizeof(long)) return -1;
    if (num_records > SIZE_MAX / sizeof(int)) return -1;

    // Allocate memory for the arrays
    *offset_array = malloc(num_records * sizeof(long));
    *key_array = malloc(num_records * sizeof(int));

    // Check allocation failures
    if (!*offset_array || !*key_array) {
        free(*offset_array);
        free(*key_array);
        return -1;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for records array
    *records = malloc(num_records * sizeof(record));
    if (!*records) {
        free(*offset_array);
        free(*key_array);
        return -1;
    }

    // Populate arrays with initial values and setup pointers
    for (size_t i = 0; i < num_records; ++i) {
        (*offset_array)[i] = i * sizeof(long);  // Example offset calculation
        (*key_array)[i] = rand() % 100;         // Random int within range 0-99

        // Initialize record structure
        (*records)[i].value = rand() % 100;    // Random int within range 0-99
        (*records)[i].offset_ptr = &(*offset_array)[i];
    }

    return 0;
}

// Function to free all allocated memory
void free_memory(long *offset_array, int *key_array, record *records) {
    if (offset_array) free(offset_array);
    if (key_array) free(key_array);
    if (records) free(records);

    offset_array = NULL;
    key_array = NULL;
    records = NULL;
}

