    int allocation_result = allocate_memory(&offset_array, &key_array, &records, num_records);

    if (allocation_result != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Use the allocated memory for operations

    free_memory(offset_array, key_array, records);
    return EXIT_SUCCESS;
}
