typedef struct {
    unsigned int timestamp;
    unsigned long message_id;
    int priority_level;
} Message;

typedef struct {
    unsigned int CRCFLAG;
    // Additional fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    // RX_UE_INFORMATION_TAG fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    // RNTI fields...
} RNTI;

typedef struct {
    unsigned int CRCFLAG;
    // CRC_INDICATION_REL8_TAG fields...
} CRC_INDICATION_REL8_TAG;

typedef struct MessageNode {
    Message message;
    struct MessageNode* next;
} MessageNode;

typedef struct {
    MessageNode* head;
    pthread_mutex_t lock;
} MessageList;

MessageList* create_message_list() {
    MessageList* list = malloc(sizeof(MessageList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool add_message(MessageList* list, unsigned int timestamp, unsigned long message_id, int priority_level) {
    if (timestamp == 0 || priority_level < 0) return false;

    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        if (current->message.message_id == message_id) {
            pthread_mutex_unlock(&list->lock);
            return false; // Duplicate ID
        }
        current = current->next;
    }

    MessageNode* new_node = malloc(sizeof(MessageNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false; // Memory allocation failed
    }
    new_node->message.timestamp = timestamp;
    new_node->message.message_id = message_id;
    new_node->message.priority_level = priority_level;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool update_message(MessageList* list, unsigned long message_id, int new_priority) {
    if (new_priority < 0) return false;

    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        if (current->message.message_id == message_id) {
            current->message.priority_level = new_priority;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return false; // Message not found
}

Message* get_message(MessageList* list, unsigned long message_id) {
    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        if (current->message.message_id == message_id) {
            pthread_mutex_unlock(&list->lock);
            return &current->message;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Message not found
}

void iterate_messages(MessageList* list, void (*process)(Message*)) {
    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        process(&current->message);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void populate_crc_list(MessageList* list, NFAPI_CRC_INDICATION_PDU_T* output, size_t max_size) {
    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    size_t count = 0;

    while (current != NULL && count < max_size) {
        output[count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        // Populate other fields...
        current = current->next;
        count++;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_message_list(MessageList* list) {
    pthread_mutex_lock(&list->lock);

    MessageNode* current = list->head;
    while (current != NULL) {
        MessageNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
void print_message(Message* msg) {
    printf("ID: %lu, Timestamp: %u, Priority: %d\n", msg->message_id, msg->timestamp, msg->priority_level);
}

int main() {
    MessageList* list = create_message_list();

    add_message(list, time(NULL), 1, 5);
    add_message(list, time(NULL) + 10, 2, 3);

    update_message(list, 1, 7);

    Message* msg = get_message(list, 1);
    if (msg) {
        print_message(msg);
    }

    iterate_messages(list, print_message);

    NFAPI_CRC_INDICATION_PDU_T crc_list[10];
    populate_crc_list(list, crc_list, 10);

    free_message_list(list);
    return 0;
}
