        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to allocate memory for list expansion");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[list->size];
    pdu->RX_UE_INFORMATION_TAG = rxTag;
    pdu->RNTI = rnti;
    pdu->crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->size++;
    return 0;
}

int serialize_list(const NFList* list, unsigned char** buffer, size_t* bufferSize) {
    if (!list || !buffer || !bufferSize) return -1;

    *bufferSize = sizeof(uint16_t) + sizeof(uint16_t) + sizeof(int); // rxTag + rnti + CRCFLAG
    *bufferSize *= list->size;

    *buffer = (unsigned char*)malloc(*bufferSize);
    if (!*buffer) {
        perror("Failed to allocate buffer for serialization");
        return -1;
    }

    unsigned char* ptr = *buffer;
    for (size_t i = 0; i < list->size; ++i) {
        const NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[i];

        memcpy(ptr, &pdu->RX_UE_INFORMATION_TAG, sizeof(uint16_t));
        ptr += sizeof(uint16_t);
        memcpy(ptr, &pdu->RNTI, sizeof(uint16_t));
        ptr += sizeof(uint16_t);
        memcpy(ptr, &pdu->crcIndicationRel8Tag.CRCFLAG, sizeof(int));
        ptr += sizeof(int);
    }

    return 0;
}

// Example usage
int main() {
    initialize_random();

    NFList* list = create_list();
    if (!list) return -1;

    add_pdu_to_list(list, 1, 100);
    add_pdu_to_list(list, 2, 200);

    unsigned char *serializedData = NULL;
    size_t serializedSize = 0;
    serialize_list(list, &serializedData, &serializedSize);

    if (serializedData) {
        printf("Serialized data size: %zu\n", serializedSize);
        free(serializedData);
    }

    destroy_list(list);
    return 0;
}
```

