#include <stdio.h>
#include <stdlib.h>
import stdlib.h
#include <pthread.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_STRUCTURES 10000
#define CRC_FAILURE_PROBABILITY 0.05

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // 1 for failure, 0 for success
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* structure_list[MAX_STRUCTURES];
int list_count = 0;
FILE *log_file;

void initialize_log() {
    log_file = fopen("dns_query.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void log_message(const char* message) {
    pthread_mutex_lock(&mutex);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
}

int set_crc_flag() {
    return (rand() / (RAND_MAX + 1.0)) < CRC_FAILURE_PROBABILITY ? 1 : 0;
}

void add_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (list_count >= MAX_STRUCTURES) {
        log_message("Error: Maximum number of structures reached.");
        return;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < list_count; ++i) {
        if (structure_list[i]->RX_UE_INFORMATION_TAG == structure->RX_UE_INFORMATION_TAG) {
            pthread_mutex_unlock(&mutex);
            log_message("Error: Duplicate RX_UE_INFORMATION_TAG.");
            return;
        }
    }

    structure_list[list_count++] = structure;
    pthread_mutex_unlock(&mutex);
}

int resolve_dns(const char* hostname, u_char* ip_buffer, int buffer_size) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "DNS resolution error: %s", gai_strerror(status));
        log_message(error_message);
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        if (snprintf((char*)ip_buffer, buffer_size, "%s", ipstr) >= buffer_size) {
            log_message("Error: IP address buffer overflow.");
            freeaddrinfo(res);
            return -1;
        }
    }

    freeaddrinfo(res);
    return 0;
}

int create_crc_indication_pdu(int rx_ue_tag, int rnti, int crc_rel8_tag) {
    if (list_count >= MAX_STRUCTURES) {
        log_message("Error: Cannot add more structures.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_message("Error: Memory allocation failure.");
        return -1;
    }

    pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    pdu->CRCFLAG = set_crc_flag();

    add_structure(pdu);
    log_message("CRC indication PDU created successfully.");
    return 0;
}

int main() {
    initialize_log();

    u_char ip_buffer[INET6_ADDRSTRLEN];
    if (resolve_dns("example.com", ip_buffer, sizeof(ip_buffer)) == 0) {
        printf("Resolved IP: %s\n", ip_buffer);

        create_crc_indication_pdu(12345, 67890, 54321);
    }

    // Cleanup
    for (int i = 0; i < list_count; ++i) {
        free(structure_list[i]);
    }
    fclose(log_file);

    pthread_mutex_destroy(&mutex);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on shared resources.
- **Logging**: Logs messages to a file for error tracking and performance metrics.
- **Dynamic List Management**: Manages a list of structures, ensuring uniqueness of `RX_UE_INFORMATION_TAG`.
- **CRC Flag Setting**: Implements a probabilistic algorithm for setting the CRC flag with a 5% failure probability.
- **DNS Resolution**: Uses `getaddrinfo` to resolve DNS queries and handle both IPv4 and IPv6 addresses.
- **Memory Management**: Allocates memory dynamically for each structure and ensures proper cleanup.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // Example maximum memory size (1 MB)
#define INACTIVITY_TIMEOUT_INTERVAL 60 // Default inactivity timeout in seconds

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG:1; // Assuming other fields are present
        // Other members...
    } CRC_INDICATION_REL8_TAG;
    time_t last_accessed;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    pthread_mutex_t lock;
    size_t max_memory;
    int inactivity_timeout_interval;
} CRC_Indication_Manager;

void update_parameters(CRC_Indication_Manager *manager, size_t new_max_memory, int new_inactivity_timeout) {
    pthread_mutex_lock(&manager->lock);
    manager->max_memory = new_max_memory;
    manager->inactivity_timeout_interval = new_inactivity_timeout;
    pthread_mutex_unlock(&manager->lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_array(CRC_Indication_Manager *manager, size_t N) {
    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (required_size > manager->max_memory) {
        return NULL; // Not enough memory
    }

    pthread_mutex_lock(&manager->lock);

    manager->array = realloc(manager->array, required_size);
    if (!manager->array) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        manager->array[i].RX_UE_INFORMATION_TAG = rand(); // Replace with actual logic
        manager->array[i].RNTI = rand() & 0xFFFFF;       // Example RNTI value
        manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        manager->array[i].last_accessed = time(NULL);
    }

    manager->count = N;

    pthread_mutex_unlock(&manager->lock);

    return manager->array;
}

void garbage_collect(CRC_Indication_Manager *manager) {
    pthread_mutex_lock(&manager->lock);

    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(current_time, manager->array[i].last_accessed) > manager->inactivity_timeout_interval) {
            // Mark the slot as free
            memset(&manager->array[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void periodic_garbage_collection(CRC_Indication_Manager *manager) {
    while (1) {
        sleep(manager->inactivity_timeout_interval);

        pthread_mutex_lock(&manager->lock);

        // Free inactive structures
        for (size_t i = 0; i < manager->count; ++i) {
            if (!manager->array[i].RX_UE_INFORMATION_TAG) { // Assuming zeroed structure is free
                memmove(&manager->array[i], &manager->array[i + 1],
                        (manager->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                manager->count--;
            }
        }

        pthread_mutex_unlock(&manager->lock);
    }
}

void init_crc_manager(CRC_Indication_Manager *manager, size_t max_memory, int inactivity_timeout_interval) {
    memset(manager, 0, sizeof(*manager));

    pthread_mutex_init(&manager->lock, NULL);

    manager->max_memory = max_memory;
    manager->inactivity_timeout_interval = inactivity_timeout_interval;

    // Start a background thread for garbage collection
    pthread_t gc_thread;
    if (pthread_create(&gc_thread, NULL, (void*(*)(void*))periodic_garbage_collection, manager) != 0) {
        perror("Failed to create garbage collector thread");
    }
}

int main() {
    CRC_Indication_Manager manager;

    init_crc_manager(&manager, MAX_MEMORY, INACTIVITY_TIMEOUT_INTERVAL);

    size_t N = 10; // Example user input
    if (allocate_crc_array(&manager, N)) {
        printf("Successfully allocated %zu structures\n", N);
    } else {
        fprintf(stderr, "Failed to allocate memory for %zu structures\n", N);
    }

    return 0;
}
```

This code creates a thread-safe structure for managing `NFAPI_CRC_INDICATION_PDU_T` structures with dynamic memory allocation. It includes garbage collection logic and allows updating of parameters for memory management. The function ensures safe concurrent access using mutexes, supports periodic garbage collection through a separate thread, and can adjust to changes in external configuration data.']

