#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INT_SIZE 12 // Buffer size for largest possible integer (signed)
#define RANGE_MIN -1000000
#define RANGE_MAX 1000000

// Function prototypes
int validate_and_store_integers(int **numbers, int *count);
void print_average(const int *numbers, int count);

int main() {
    int *numbers = NULL;
    int count = 0;

    if (!validate_and_store_integers(&numbers, &count)) {
        free(numbers);
        return EXIT_FAILURE;
    }

    print_average(numbers, count);
    free(numbers);
    return EXIT_SUCCESS;
}

// Reads integers from standard input and validates them
int validate_and_store_integers(int **numbers, int *count) {
    char buffer[MAX_INT_SIZE];
    size_t buffer_size = sizeof(buffer);

    printf("Enter integers (end with EOF):\n");

    // Dynamically allocate memory to store numbers
    *numbers = NULL;
    *count = 0;

    while (fgets(buffer, buffer_size, stdin)) {
        // Remove newline character if present
        buffer[strcspn(buffer, "\n")] = '\0';

        char *endptr;
        long int num = strtol(buffer, &endptr, 10);

        // Validate number format and range
        if (*endptr == '\0' && num >= RANGE_MIN && num <= RANGE_MAX) {
            *numbers = realloc(*numbers, (*count + 1) * sizeof(int));
            if (*numbers == NULL) {
                perror("Failed to allocate memory");
                return 0;
            }
            (*numbers)[*count] = (int)num;
            (*count)++;
        } else {
            fprintf(stderr, "Invalid input: %s\n", buffer);
        }
    }

    // Handle EOF or other read errors
    if (ferror(stdin)) {
        perror("Error reading input");
        free(*numbers);
        return 0;
    }

    return *count > 0 ? 1 : 0;
}

// Calculates and prints the average of stored integers
void print_average(const int *numbers, int count) {
    if (count == 0) {
        printf("No valid integers found.\n");
        return;
    }

    long sum = 0;
    for (int i = 0; i < count; ++i) {
        sum += numbers[i];
    }

    double average = (double)sum / count;
    printf("Average of valid integers: %.2f\n", average);
}
```

