```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    CONNECTION_ESTABLISHMENT,
    HANDOVER
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    int status_code;
} NetworkEventStruct;

// Thread-safe dynamic array structure
typedef struct {
    NetworkEventStruct *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} EventArray;

// Function to initialize the dynamic array
void init_event_array(EventArray *array, size_t initial_capacity) {
    if (initial_capacity == 0) initial_capacity = 10; // Default initial capacity
    array->events = malloc(initial_capacity * sizeof(NetworkEventStruct));
    if (!array->events) exit(EXIT_FAILURE); // Handle memory allocation failure

    array->capacity = initial_capacity;
    array->count = 0;

    pthread_mutex_init(&array->mutex, NULL);
}

// Function to resize the dynamic array
void resize_event_array(EventArray *array) {
    size_t new_capacity = array->capacity * 2;
    NetworkEventStruct *new_events = realloc(array->events, new_capacity * sizeof(NetworkEventStruct));
    if (!new_events) exit(EXIT_FAILURE); // Handle memory allocation failure

    array->events = new_events;
    array->capacity = new_capacity;
}

// Function to add an event to the dynamic array
void add_event(EventArray *array, NetworkEventStruct event) {
    pthread_mutex_lock(&array->mutex);

    if (array->count == array->capacity) {
        resize_event_array(array);
    }

    array->events[array->count++] = event;

    pthread_mutex_unlock(&array->mutex);
}

// Function to free the dynamic array
void free_event_array(EventArray *array) {
    pthread_mutex_lock(&array->mutex);

    free(array->events);
    array->events = NULL;
    array->capacity = 0;
    array->count = 0;

    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

// Function to simulate logging an event (stub for integration)
void log_event_as_json(const NetworkEventStruct *event) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer),
             "{\"timestamp\": %ld, \"event_type\": %d, \"status_code\": %d}",
             (long)event->timestamp, event->event_type, event->status_code);
    printf("%s\n", buffer); // Simulated logging
}

// Example of populating and managing the array with simulated data
void simulate_network_traffic(EventArray *array) {
    for (int i = 0; i < 100; ++i) { // Simulate adding 100 events
        NetworkEventStruct event = {
            .timestamp = time(NULL),
            .event_type = i % 2 == 0 ? CONNECTION_ESTABLISHMENT : HANDOVER,
            .status_code = rand() % 100
        };

        add_event(array, event);
    }

    // Log each event as JSON
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        log_event_as_json(&array->events[i]);
    }

    pthread_mutex_unlock(&array->mutex);
}

// Example usage
int main() {
    EventArray event_array;
    init_event_array(&event_array, 10);

    simulate_network_traffic(&event_array);

    free_event_array(&event_array);

    return 0;
}
```

### Design Rationale

1. **Performance and Memory Usage**: The dynamic array starts with a reasonable initial capacity to minimize reallocations. Doubling the size on demand optimizes both time (less frequent allocations) and space.

2. **Concurrency**: A mutex is used to ensure thread-safe operations, preventing race conditions when accessing or modifying the array. This allows for concurrent processing of network events in multi-threaded environments.

3. **Scalability**: The use of a dynamic array ensures that the system can handle increasing data volumes efficiently without degrading performance.

4. **Integration and Serialization**: A stub function (`log_event_as_json`) simulates event serialization to JSON, ensuring compatibility with existing systems expecting this format. This design is flexible enough for future extensions (e.g., XML or binary formats).

5. **Error Handling**: Memory allocation failures are handled by exiting the program gracefully. More sophisticated error handling can be added as needed.

6. **Configuration**: While not explicitly shown in this code, configuration options such as logging level and data retention policies could be implemented using global variables or configuration files.

This implementation balances efficiency, usability, maintainability, and scalability while addressing the specified constraints.']

