// Function to initialize a semaphore with a timeout mechanism
int createNfareSemaphore(sem_t **sem, unsigned int initial_value) {
    if (sem == NULL || (*sem = malloc(sizeof(sem_t))) == NULL) {
        return errno; // Return error code on memory allocation failure
    }

    // Initialize the semaphore with an initial value of 1
    if (sem_init(*sem, 0, initial_value) != 0) {
        free(*sem);
        return errno;
    }

    return 0; // Success
}

// Function to create and manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
int createNfareSemaphoreWithList(sem_t **sem, size_t num_elements) {
    int status = createNfareSemaphore(sem, 1);
    if (status != 0) return status;

    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        sem_destroy(*sem); // Ensure semaphore is destroyed on failure
        free(*sem);
        return ENOMEM;
    }

    pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Populate the list with random data
    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *item = &list[i];

        pthread_mutex_lock(&list_mutex);

        item->RX_UE_INFORMATION_TAG = rand(); // Randomly set the tag
        item->RNTI = rand() % 1000;           // Randomly set the RNTI

        item->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        pthread_mutex_unlock(&list_mutex);
    }

    // Simulate timeout mechanism for semaphore
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += 5; // Timeout after 5 seconds

    if (sem_timedwait(*sem, &ts) != 0) {
        free(list);
        sem_destroy(*sem);
        free(*sem);
        return ETIMEDOUT;
    }

    // Ensure to destroy the semaphore and free resources on completion
    if (pthread_mutex_lock(&list_mutex)) {
        free(list);
        sem_destroy(*sem);
        free(*sem);
        return EPERM; // Return error code if mutex lock fails
    }

    pthread_mutex_unlock(&list_mutex);

    // Clean-up phase, normally done by the caller or at function end
    free(list);
    sem_destroy(*sem); 
    free(*sem);
    return 0;
}
