```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 100
#define RX_UE_INFO_MIN 1
#define RX_UE_INFO_MAX 10
#define RNTI_MIN 0x0000
#define RNTI_MAX 0xFFFF

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    int overflow_flag;
} List;

int is_valid_rx_ue_info(unsigned short tag) {
    return (tag >= RX_UE_INFO_MIN && tag <= RX_UE_INFO_MAX);
}

int is_valid_rnti(unsigned short rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

void init_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->overflow_flag = 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void append_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS && list->overflow_flag == 1) {
        printf("Overflow warning: Max elements reached with CRCFLAG set.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (data.CRC_INDICATION.CRCFLAG && list->count >= MAX_ELEMENTS - 1) {
        list->overflow_flag = 1;
        free(new_node);
    } else {
        new_node->next = list->head;
        list->head = new_node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
}

void clear_unused_nodes(List* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        // Example criteria for clearing unused nodes
        if (rand() % 10 == 0) { // Randomly clear some nodes for demonstration
            Node* to_delete = current;
            current = current->next;
            free(to_delete);
            list->count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void initialize_list(List* list, int n) {
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % (RX_UE_INFO_MAX - RX_UE_INFO_MIN + 1) + RX_UE_INFO_MIN;
        pdu.RNTI = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        pdu.CRC_INDICATION.CRCFLAG = rand() % 2;

        if (is_valid_rx_ue_info(pdu.RX_UE_INFORMATION_TAG) && is_valid_rnti(pdu.RNTI)) {
            append_to_list(list, pdu);
        }
    }

    // Periodically clear unused nodes
    while (1) {
        sleep(10); // Adjust the period as needed
        clear_unused_nodes(list);
    }
}

int main() {
    List list;
    init_list(&list);

    initialize_list(&list, 120); // Example: Initialize with more elements than MAX_ELEMENTS

    destroy_list(&list);
    return 0;
}
```

