#define CRC_FAILURE_PROBABILITY 0.05

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRCFLAG;
    int CRC_INDICATION_REL8_TAG; // Assuming it's an integer type for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;
size_t current_count = 0;

int is_unique_tag(int tag) {
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < current_count; ++i) {
        if (crc_indication_list[i].RX_UE_INFORMATION_TAG == tag) {
            pthread_mutex_unlock(&list_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list_mutex);
    return 1;
}

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

int allocate_list(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_indication_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!new_list) {
        log_error("Memory allocation failed");
        return 0;
    }
    crc_indication_list = new_list;
    return 1;
}

void initialize_crc_flag(unsigned char *crc_flag) {
    *crc_flag = (rand() < CRC_FAILURE_PROBABILITY * RAND_MAX) ? 1 : 0;
}

void populate_initial_list(size_t initial_size) {
    srand((unsigned int)time(NULL));

    pthread_mutex_lock(&list_mutex);
    if (!allocate_list(initial_size)) return;

    current_count = initial_size;
    for (size_t i = 0; i < current_count; ++i) {
        do {
            crc_indication_list[i].RX_UE_INFORMATION_TAG = rand() % MAX_STRUCTURES + 1; // Ensure non-zero
        } while (!is_unique_tag(crc_indication_list[i].RX_UE_INFORMATION_TAG));

        crc_indication_list[i].RNTI = rand();
        initialize_crc_flag(&crc_indication_list[i].CRCFLAG);
        crc_indication_list[i].CRC_INDICATION_REL8_TAG = rand(); // Random assignment
    }
    pthread_mutex_unlock(&list_mutex);
}

void update_list(size_t new_size) {
    pthread_mutex_lock(&list_mutex);

    if (new_size > MAX_STRUCTURES) {
        log_error("Requested size exceeds maximum limit");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    if (!allocate_list(new_size)) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    current_count = new_size;

    for (size_t i = 0; i < current_count; ++i) {
        do {
            crc_indication_list[i].RX_UE_INFORMATION_TAG = rand() % MAX_STRUCTURES + 1;
        } while (!is_unique_tag(crc_indication_list[i].RX_UE_INFORMATION_TAG));

        crc_indication_list[i].RNTI = rand();
        initialize_crc_flag(&crc_indication_list[i].CRCFLAG);
        crc_indication_list[i].CRC_INDICATION_REL8_TAG = rand(); // Random assignment
    }

    pthread_mutex_unlock(&list_mutex);
}

void free_resources() {
    pthread_mutex_lock(&list_mutex);
    if (crc_indication_list) {
        free(crc_indication_list);
        crc_indication_list = NULL;
    }
    current_count = 0;
    pthread_mutex_unlock(&list_mutex);
}
```

### Explanation:

- **Thread Safety**: Mutex (`pthread_mutex_t list_mutex`) is used to ensure thread-safe access and modification of the shared data structure.

- **Unique Tags**: The `is_unique_tag` function checks for uniqueness within the existing list, ensuring no duplicate `RX_UE_INFORMATION_TAG`.

- **Probabilistic CRC Flag**: `initialize_crc_flag` sets the `CRCFLAG` based on a 5% probability of failure.

- **Dynamic Memory Management**: Handles reallocation with error checking and logging for memory allocation failures via `allocate_list`.

- **Initial Population & Updates**: Functions `populate_initial_list` and `update_list` initialize or update the list, maintaining unique tags and valid structures. 

- **Resource Cleanup**: The `free_resources` function safely frees allocated memory.

This implementation aims to balance thread safety, performance, scalability, and maintainability in a multi-threaded environment.']

