    size_t current_connections;
    time_t timeout;
    int retry_policy;
    NFAPI_CRC_INDICATION_PDU_T* pool;
    void (*log_func)(const char*);
} ConnectionPool;

typedef struct {
    int value;
    long* offset_ptr;
} Record;

// Function prototypes
void initialize_pool(ConnectionPool* pool, size_t max_connections, time_t timeout, int retry_policy, void (*log_func)(const char*));
int add_connection(ConnectionPool* pool);
void free_pool(ConnectionPool* pool);
void allocate_arrays(long** offsets, int** keys, size_t offset_size, size_t key_size);
void deallocate_arrays(long* offsets, int* keys);
void initialize_records(Record** records, size_t record_count, int min_value, int max_value, void (*log_func)(const char*), int validation_mode);

// Function implementations
void initialize_pool(ConnectionPool* pool, size_t max_connections, time_t timeout, int retry_policy, void (*log_func)(const char*)) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->max_connections = max_connections;
    pool->current_connections = 0;
    pool->timeout = timeout;
    pool->retry_policy = retry_policy;
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_connections * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->log_func = log_func;
    if (!pool->pool) {
        if (log_func) log_func("Memory allocation failed for connection pool.");
        exit(EXIT_FAILURE);
    }
}

int add_connection(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_connections < pool->max_connections) {
        memset(&pool->pool[pool->current_connections], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        srand(time(NULL));
        pool->pool[pool->current_connections].RX_UE_INFORMATION_TAG = rand() % 100;
        pool->pool[pool->current_connections].RNTI = rand();
        for (int i = 0; i < 4; ++i) {
            pool->pool[pool->current_connections].CRC_INDICATION_REL8_TAG[i] = rand() & 1;
        }
        pool->current_connections++;
        pthread_mutex_unlock(&pool->lock);
        return 0;
    }
    pthread_mutex_unlock(&pool->lock);
    return -1; // Pool is full
}

void free_pool(ConnectionPool* pool) {
    if (pool->pool) {
        free(pool->pool);
        pool->current_connections = 0;
    }
    pthread_mutex_destroy(&pool->lock);
}

void allocate_arrays(long** offsets, int** keys, size_t offset_size, size_t key_size) {
    *offsets = (long*)malloc(offset_size * sizeof(long));
    *keys = (int*)malloc(key_size * sizeof(int));

    if (!(*offsets) || !(*keys)) {
        fprintf(stderr, "Memory allocation failed for arrays.\n");
        exit(EXIT_FAILURE);
    }
}

void deallocate_arrays(long* offsets, int* keys) {
    free(offsets);
    free(keys);
}

void initialize_records(Record** records, size_t record_count, int min_value, int max_value, void (*log_func)(const char*), int validation_mode) {
    *records = (Record*)malloc(record_count * sizeof(Record));

    if (!(*records)) {
        if (validation_mode == 1) {
            fprintf(stderr, "Memory allocation failed for records.\n");
            exit(EXIT_FAILURE);
        } else {
            if (log_func) log_func("Warning: Memory allocation failed for records.");
            return;
        }
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        long* offset = malloc(sizeof(long));
        if (!offset && validation_mode == 1) {
            free(*records);
            fprintf(stderr, "Memory allocation failed for offset.\n");
            exit(EXIT_FAILURE);
        } else if (!offset) {
            if (log_func) log_func("Warning: Memory allocation failed for offset.");
            (*records)[i].offset_ptr = NULL;
            continue;
        }
        *offset = rand() % 1000000;
        (*records)[i].offset_ptr = offset;
    }
}

void free_records(Record* records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        if (records[i].offset_ptr != NULL) {
            free(records[i].offset_ptr);
        }
    }
    free(records);
}
```

### Key Points:
