#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define MIN_POOL_SIZE 500
#define MAX_POOL_SIZE 10000
#define INITIAL_POOL_SIZE 1000
#define MAX_RETRY_ATTEMPTS 3
#define TIMEOUT_MS 200

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Connection {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int active;
    pthread_mutex_t lock;
    time_t last_used;
} Connection;

typedef struct ConnectionPool {
    Connection **connections;
    size_t pool_size;
    size_t active_connections;
    pthread_mutex_t pool_lock;
    pthread_cond_t condition_var;
    int max_connections;
    int min_connections;
} ConnectionPool;

ConnectionPool *create_connection_pool(int min_conn, int max_conn) {
    ConnectionPool *pool = (ConnectionPool *)malloc(sizeof(ConnectionPool));
    pool->min_connections = min_conn;
    pool->max_connections = max_conn;
    pool->connections = (Connection **)calloc(max_conn, sizeof(Connection *));
    pthread_mutex_init(&pool->pool_lock, NULL);
    pthread_cond_init(&pool->condition_var, NULL);

    for (int i = 0; i < initial_pool_size && i < max_conn; ++i) {
        Connection *conn = (Connection *)malloc(sizeof(Connection));
        conn->active = 1;
        pthread_mutex_init(&conn->lock, NULL);
        pool->connections[i] = conn;
    }

    pool->pool_size = initial_pool_size;
    return pool;
}

void adjust_connection_pool_size(ConnectionPool *pool) {
    size_t new_size = pool->active_connections + ((rand() % 2 == 0) ? (rand() % 100) : -(rand() % 100));
    if (new_size > MAX_POOL_SIZE) new_size = MAX_POOL_SIZE;
    else if (new_size < MIN_POOL_SIZE) new_size = MIN_POOL_SIZE;

    pthread_mutex_lock(&pool->pool_lock);
    while (pool->pool_size < new_size && pool->pool_size < pool->max_connections) {
        Connection *conn = (Connection *)malloc(sizeof(Connection));
        conn->active = 1;
        pthread_mutex_init(&conn->lock, NULL);
        pool->connections[pool->pool_size++] = conn;
    }
    while (pool->pool_size > new_size && pool->pool_size > pool->min_connections) {
        Connection *conn = pool->connections[--pool->pool_size];
        free(conn);
    }
    pthread_mutex_unlock(&pool->pool_lock);
}

Connection *get_connection(ConnectionPool *pool) {
    time_t current_time;
    pthread_mutex_lock(&pool->pool_lock);

    while (1) {
        for (size_t i = 0; i < pool->pool_size; ++i) {
            Connection *conn = pool->connections[i];
            if (pthread_mutex_trylock(&conn->lock) == 0 && conn->active) {
                pthread_mutex_unlock(&pool->pool_lock);
                conn->last_used = time(NULL);
                return conn;
            }
        }

        adjust_connection_pool_size(pool);

        pthread_cond_wait(&pool->condition_var, &pool->pool_lock);
    }
}

void release_connection(Connection *conn) {
    conn->active = 0;
    pthread_mutex_unlock(&conn->lock);
}

int main() {
    srand(time(NULL));

    ConnectionPool *pool = create_connection_pool(MIN_POOL_SIZE, MAX_POOL_SIZE);

    // Simulating concurrent connections
    for (int i = 0; i < 1000; ++i) {
        pthread_t thread;
        void *(*connection_handler)(void *) = [](void *arg) -> void * {
            ConnectionPool *pool = (ConnectionPool *)arg;

            Connection *conn = get_connection(pool);

            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rx_ue_information_tag = rand();
            pdu.rnti = rand();
            pdu.crc_flag = rand() % 2;

            conn->pdu = pdu;

            sleep(1); // Simulate some processing
            release_connection(conn);

            return NULL;
        };

        pthread_create(&thread, NULL, connection_handler, pool);
        pthread_detach(thread);
    }

    // Clean up
    for (size_t i = 0; i < pool->pool_size; ++i) {
        Connection *conn = pool->connections[i];
        free(conn);
    }
    free(pool->connections);
    free(pool);

    return 0;
}
