['Below is a C code implementation for managing a dynamic list of PDU Session Establishment Accept (PSEEA) messages in a scalable 5G network simulation framework. This function populates the list with unique S-TMSI values, ensuring no duplicates and validating them against a dynamically fetched range.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int pduSessionID;
    char sNssai[10];
} PduSessionInfo;

typedef struct {
    int stmsi;
} PduSsrslEntry;

typedef struct {
    PduSessionInfo sessionInfo;
    PduSsrslEntry* pduSsrslList;
    size_t pduSsrslCount;
} PseeaMessage;

// Function prototypes
bool fetchStmsiRange(int* minStmsi, int* maxStmsi);
void generateUniqueStmsis(PseeaMessage* messages, size_t count, int minStmsi, int maxStmsi);

PseeaMessage* createMessages(size_t count) {
    PseeaMessage* messages = (PseeaMessage*)malloc(count * sizeof(PseeaMessage));
    if (!messages) return NULL;

    for (size_t i = 0; i < count; ++i) {
        messages[i].pduSsrslList = NULL;
        messages[i].pduSsrslCount = 0;
    }

    int minStmsi, maxStmsi;
    if (!fetchStmsiRange(&minStmsi, &maxStmsi)) {
        free(messages);
        return NULL;
    }

    generateUniqueStmsis(messages, count, minStmsi, maxStmsi);

    return messages;
}

bool fetchStmsiRange(int* minStmsi, int* maxStmsi) {
    // Simulate fetching from an external data source
    *minStmsi = 1000;   // Example range start
    *maxStmsi = 9999;   // Example range end
    return true;
}

void generateUniqueStmsis(PseeaMessage* messages, size_t count, int minStmsi, int maxStmsi) {
    srand(time(NULL));
    bool* usedStmsi = (bool*)calloc((maxStmsi - minStmsi + 1), sizeof(bool));

    for (size_t i = 0; i < count; ++i) {
        size_t entryCount = rand() % 10 + 1; // Random number of entries per message
        messages[i].pduSsrslList = (PduSsrslEntry*)malloc(entryCount * sizeof(PduSsrslEntry));
        if (!messages[i].pduSsrslList) continue;

        for (size_t j = 0; j < entryCount; ++j) {
            int stmsi;
            do {
                stmsi = minStmsi + rand() % (maxStmsi - minStmsi + 1);
            } while (usedStmsi[stmsi - minStmsi]);

            messages[i].pduSsrslList[j].stmsi = stmsi;
            usedStmsi[stmsi - minStmsi] = true;
        }
        messages[i].pduSsrslCount = entryCount;
    }

    free(usedStmsi);
}

void freeMessages(PseeaMessage* messages, size_t count) {
    if (!messages) return;

    for (size_t i = 0; i < count; ++i) {
        free(messages[i].pduSsrslList);
    }
    free(messages);
}

int main() {
    size_t messageCount = 10000;
    PseeaMessage* messages = createMessages(messageCount);

    if (!messages) {
        fprintf(stderr, "Failed to create PSEEA messages.\n");
        return EXIT_FAILURE;
    }

    // Simulation code here...

    freeMessages(messages, messageCount);
    return EXIT_SUCCESS;
}
