import java.util.Arrays;

class UnionFind {
    private int[] parent, rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    private int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]);
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);

        if (rootP == rootQ) return;

        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
        } else if (rank[rootP] < rank[rootQ]) {
            parent[rootP] = rootQ;
        } else {
            parent[rootQ] = rootP;
            rank[rootP]++;
        }
    }

    public boolean connected(int p, int q) {
        return find(p) == find(q);
    }
}

public class DisjointPairsCounter {

    public static int countDisjointPairs(int[] array) {
        int n = array.length;
        UnionFind uf = new UnionFind(n);

        long startTime, endTime;

        int disjointPairCount = 0;

        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                startTime = System.currentTimeMillis();

                if (!uf.connected(i, j)) {
                    uf.union(i, j);
                    disjointPairCount++;
                }

                endTime = System.currentTimeMillis();
                System.out.println("Checking pair (" + array[i] + ", " + array[j] + ") took " + (endTime - startTime) + " ms");
            }
        }

        return disjointPairCount;
    }

    public static void main(String[] args) {
        int[] inputArray = {1, 2, 3, 4, 5};
        System.out.println("Number of disjoint pairs: " + countDisjointPairs(inputArray));
    }
}
