    } else if (load < 30) { // Low load
        config->buffer_size = MAX(config->buffer_size - 1024, INITIAL_BUFFER_SIZE);
    }

    // Adjust timeout based on load
    config->timeout_ms = MIN_TIMEOUT_MS + (MAX_TIMEOUT_MS - MIN_TIMEOUT_MS) * (100 - load) / 100;

    // Optionally adjust flow control settings
    if (load > 90 && !config->flow_control_enabled) {
        config->flow_control_enabled = 1;
    } else if (load < 50 && config->flow_control_enabled) {
        config->flow_control_enabled = 0;
    }
