    pthread_mutex_lock(&list->lock);

    size_t i = 0;
    while (i < list->count) {
        if (should_clear(list->elements[i])) { // Define `should_clear` condition
            memmove(&list->elements[i], &list->elements[i + 1],
                    (list->count - i - 1) * sizeof(NFAPI_RACH_INDICATION_PDU_T));
            list->count--;
        } else {
            i++;
        }
    }

    if (list->capacity > M && list->count < M / 2) { // Optimize memory usage
        resize_list(list, M);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(RACH_LIST *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
