NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int count, int* success_count) {
    *success_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed.");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        int retries = 0;
        int rnti = rand() % MAX_RNTI;
        char rx_ue_information_tag[256];
        snprintf(rx_ue_information_tag, sizeof(rx_ue_information_tag), "UE%d", i);

        while (retries < MAX_RETRIES) {
            if (is_unique_rnti(list, *success_count, rnti) && is_unique_rx_ue_info(list, *success_count, rx_ue_information_tag)) {
                list[*success_count].rnti = rnti;
                strncpy(list[*success_count].rx_ue_information_tag, rx_ue_information_tag, sizeof(list[*success_count].rx_ue_information_tag));
                list[*success_count].crc_flag = rand() % 2; // Randomly set CRCFLAG
                log_message("Insertion successful.");
                (*success_count)++;
                break;
            }
            rnti = (rnti + 1) % MAX_RNTI;
            retries++;
        }

        if (retries == MAX_RETRIES) {
            log_message("Failed to insert due to exhausted RNTI values.");
        }
    }

    return list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list, int success_count) {
    free(list);
}
