    pthread_mutex_t lock;
    bool *allocated; // Track allocated elements
} MemoryPool;

// Logging levels
enum { LOG_NONE, LOG_ERROR, LOG_INFO, LOG_DEBUG };

pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
bool rnti_map[MAX_RNTI] = { false };

void log_message(int level, const char *message) {
    if (level >= LOG_DEBUG) {
        printf("%s\n", message);
    }
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->pool = aligned_alloc(64, size); // 64-byte cache line alignment
    pool->pool_size = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool->allocated = calloc(pool->pool_size, sizeof(bool));

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->allocated);
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

bool is_rnti_unique(uint16_t rnti) {
    pthread_mutex_lock(&rnti_lock);
    if (rnti >= MAX_RNTI || rnti_map[rnti]) {
        pthread_mutex_unlock(&rnti_lock);
        return false;
    }
    rnti_map[rnti] = true;
    pthread_mutex_unlock(&rnti_lock);
    return true;
}

void release_rnti(uint16_t rnti) {
    pthread_mutex_lock(&rnti_lock);
    if (rnti < MAX_RNTI) {
        rnti_map[rnti] = false;
    }
    pthread_mutex_unlock(&rnti_lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_validate_structures(MemoryPool *pool, size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    if (count > pool->pool_size) {
        log_message(LOG_ERROR, "Requested allocation exceeds available memory.");
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);
    array = &pool->pool[0]; // Simulating allocation from the top of the pool

    for (size_t i = 0; i < count; ++i) {
        uint16_t rnti;
        do {
            rnti = rand() % MAX_RNTI;
        } while (!is_rnti_unique(rnti));

        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF;
        array[i].CRCFLAG = rand() & 1;

        pool->allocated[i] = true; // Mark as allocated
    }

    pthread_mutex_unlock(&pool->lock);

    for (size_t i = 0; i < count; ++i) {
        if (!array[i].RX_UE_INFORMATION_TAG || !is_rnti_unique(array[i].RNTI)) {
            log_message(LOG_ERROR, "Validation failed. Cleaning up resources.");

            pthread_mutex_lock(&pool->lock);
            for (size_t j = 0; j <= i; ++j) {
                release_rnti(array[j].RNTI);
                pool->allocated[j] = false;
            }
            pthread_mutex_unlock(&pool->lock);

            return NULL;
        }
    }

    log_message(LOG_INFO, "Allocation and validation successful.");
    return array;
}

void periodic_memory_cleanup(MemoryPool *pool) {
    while (true) {
        sleep(10); // Periodically every 10 seconds
        pthread_mutex_lock(&pool->lock);

        for (size_t i = 0; i < pool->pool_size; ++i) {
            if (!pool->allocated[i]) {
                memset(&pool->pool[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }

        pthread_mutex_unlock(&pool->lock);
    }
}

int main() {
    MemoryPool *memory_pool = create_memory_pool(MEMORY_POOL_SIZE);

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, (void *(*)(void *))periodic_memory_cleanup, memory_pool) != 0) {
        log_message(LOG_ERROR, "Failed to create periodic cleanup thread.");
        destroy_memory_pool(memory_pool);
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = allocate_and_validate_structures(memory_pool, 100);

    if (data) {
        // Use the allocated and validated data
    }

    pthread_join(cleanup_thread, NULL); 
    destroy_memory_pool(memory_pool);

    return EXIT_SUCCESS;
}
```

### Key Points:

1. **Thread Safety**: Mutexes are used for synchronization when accessing shared resources like `rnti_map`.

2. **Unique RNTI Values**: A simple bit map is employed to ensure the uniqueness of RNTI values within the array.

3. **Memory Pool Management**: A fixed-size memory pool is managed manually, with structures allocated from this pool.

4. **Error Handling and Cleanup**: If validation fails, a cleanup process releases resources partially allocated.

5. **Logging System**: Logging function `log_message` is used to log events at different verbosity levels.

6. **Concurrency**: The system supports concurrent operations by using mutexes for synchronization.

7. **Performance Optimization**: Using cache-aligned memory allocation and manual pool management reduces fragmentation and improves performance.

8. **Modular Design**: Functions are designed to be modular, allowing easy integration and extension.']

