// Cache structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *cache;
    size_t cache_size;
    size_t next_free_index;
} Cache;

Cache global_cache = {NULL, 0, 0};

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N, unsigned int seed) {
    if (N == 0 || N > MAX_SYSTEM_LIMIT) {
        fprintf(stderr, "Invalid input size: %zu\n", N);
        return NULL;
    }

    // Attempt to use cached structures
    if (global_cache.next_free_index + N <= global_cache.cache_size) {
        printf("Using cached memory for allocation.\n");
        return &global_cache.cache[global_cache.next_free_index];
    }

    // Allocate new memory with error handling
    size_t size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size);

    if (!array) {
        fprintf(stderr, "Memory allocation failed for %zu structures.\n", N);
        return NULL;
    }

    // Initialize random number generator
    srand(seed);

    // Initialize each structure in the allocated array
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    printf("Memory allocated and initialized successfully.\n");

    // Update cache if needed
    if (!global_cache.cache || global_cache.next_free_index + N > global_cache.cache_size) {
        if (global_cache.cache) {
            free(global_cache.cache);
        }
        global_cache.cache = array;
        global_cache.cache_size = N;
    } else {
        memcpy(&global_cache.cache[global_cache.next_free_index], array, size);
    }

    global_cache.next_free_index += N;

    return array;
}

int main() {
    // Example usage
    size_t N = 10;
    unsigned int seed = 42;
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_crc_pdu_array(N, seed);

