#include <stdint.h>
#include <string.h>

// Define constants
#define CHECKSUM_SIZE 4

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t tile_size;
    size_t world_width;
    size_t world_height;
    float camera_speed;
} EnvironmentConfig;

// Function to calculate checksum
uint32_t calculate_checksum(const uint8_t *data, size_t len) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < len; ++i) {
        checksum += data[i];
    }
    return checksum;
}

// Function to deserialize configuration from binary file
int load_config(const char *filename, EnvironmentConfig *config, uint8_t *error_msg) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        snprintf(error_msg, 256, "Error opening file: %s", filename);
        return -1;
    }

    // Read checksum
    uint32_t expected_checksum;
    fread(&expected_checksum, sizeof(expected_checksum), 1, file);

    // Calculate buffer size for data
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file) - CHECKSUM_SIZE;

    if (file_size <= 0) {
        snprintf(error_msg, 256, "Invalid file size");
        fclose(file);
        return -1;
    }

    // Read data and calculate checksum
    uint8_t *data = malloc(file_size);
    fseek(file, sizeof(expected_checksum), SEEK_SET);
    fread(data, 1, file_size, file);

    uint32_t actual_checksum = calculate_checksum(data, file_size);
    fclose(file);

    if (actual_checksum != expected_checksum) {
        snprintf(error_msg, 256, "Checksum mismatch");
        free(data);
        return -2;
    }

    // Deserialize data
    size_t offset = 0;

    memcpy(&config->tile_size, data + offset, sizeof(config->tile_size));
    offset += sizeof(config->tile_size);

    if (config->tile_size % 16 != 0) {
        snprintf(error_msg, 256, "Tile size not a multiple of 16");
        free(data);
        return -3;
    }

    memcpy(&config->world_width, data + offset, sizeof(config->world_width));
    offset += sizeof(config->world_width);

    if (config->world_width <= 0) {
        snprintf(error_msg, 256, "Invalid world width");
        free(data);
        return -4;
    }

    memcpy(&config->world_height, data + offset, sizeof(config->world_height));
    offset += sizeof(config->world_height);

    if (config->world_height <= 0) {
        snprintf(error_msg, 256, "Invalid world height");
        free(data);
        return -5;
    }

    memcpy(&config->camera_speed, data + offset, sizeof(config->camera_speed));

    free(data);
    return 0;
}

// Function to create and populate NFAPI_CRC_INDICATION_PDU_T structures
int create_nfa_pdu_list(size_t n, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) return -1;

    for (size_t i = 0; i < n; ++i) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        (*pdus)[i].RNTI = rand() % 65536;
        (*pdus)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
    return 0;
}

// Main function demonstrating usage
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    EnvironmentConfig config = {0};
    uint8_t error_msg[256] = {0};

    int result = load_config(argv[1], &config, error_msg);
    if (result != 0) {
        fprintf(stderr, "Configuration loading failed: %s\n", error_msg);
        return EXIT_FAILURE;
    }

    const size_t pdu_count = 10; // Example count
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    result = create_nfa_pdu_list(pdu_count, &pdus);
    if (result != 0) {
        fprintf(stderr, "Failed to create NFA PI list\n");
        return EXIT_FAILURE;
    }

    // Use the pdus and config as needed...

    free(pdus);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Checksum Verification**: Ensures data integrity by comparing calculated checksums.
- **Error Handling**: Provides detailed error messages for debugging.
- **Validation Checks**: Ensures tile size is a multiple of 16 and dimensions are positive.
- **Memory Management**: Allocates and frees memory appropriately to avoid leaks.
- **Random CRCFLAG Setting**: Uses `rand()` to set the CRCFLAG randomly.']

