NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t n, ConfigParams *config) {
    if (n == 0 || config == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
