        list[i].RNTI = rand() % 65535 + 1;

        // Set CRCFLAG randomly for CRC_INDICATION_REL8_TAG
        list[i].crc_indication.CRCFLAG = (rand() % 2) ? 0xFF : 0x00;
    }

    return list;
}

ConfigParams fetch_config_with_fallback() {
    ConfigParams config = {DEFAULT_TILE_SIZE, DEFAULT_WORLD_DIMENSIONS.width,
                           DEFAULT_WORLD_DIMENSIONS.height, DEFAULT_CAMERA_SPEED};

    // Use a separate thread to fetch the configuration asynchronously
    pthread_t fetch_thread;
    int status = pthread_create(&fetch_thread, NULL, (void *(*)(void *)) fetch_config_service, &config);

    if (status != 0) {
        fprintf(stderr, "Failed to create config fetch thread\n");
        return config; // Return defaults on failure
    }

    // Wait for the configuration with a timeout of 500ms
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    int received_config = 0;

    if (pthread_mutex_lock(&mutex) == 0) {
        // Use timed wait to implement the timeout
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 0.5; // 500ms

        while (!received_config && pthread_cond_timedwait(&cond, &mutex, &ts) == ETIMEDOUT) {
            if (status != 0) {
                break;
            }
        }

        pthread_mutex_unlock(&mutex);
    }

    pthread_cancel(fetch_thread); // Ensure thread is cancelled
    pthread_join(fetch_thread, NULL);

    return config; // Config may be updated by the fetch thread
}

void* fetch_config_service(void* arg) {
    ConfigParams *config = (ConfigParams *)arg;

    // Simulate fetching from an external service with variable latency
    sleep(rand() % 3); // Random delay between 0-2 seconds

    if (rand() % 5 == 0) { // Introduce a failure condition randomly
        return NULL;
    }

    config->tile_size = /* fetched tile size or use DEFAULT_TILE_SIZE */;
    config->world_width = /* fetched world width or use DEFAULT_WORLD_DIMENSIONS.width */;
    config->world_height = /* fetched world height or use DEFAULT_WORLD_DIMENSIONS.height */;
    config->camera_speed = /* fetched camera speed or use DEFAULT_CAMERA_SPEED */;

    // Notify the waiting thread that config is ready
    pthread_mutex_t mutex;
    pthread_cond_t cond;

    if (pthread_mutex_lock(&mutex) == 0) {
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    size_t num_elements = 10000; // Example for a large list
    ConfigParams config = fetch_config_with_fallback();

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_nfa_pi_list(num_elements, &config);

    // Use pdu_list...

    free(pdu_list); // Ensure no memory leaks
    return 0;
}
