bool resize_list(NFAPICRCList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entries) return false;
    list->entries = new_entries;
    list->capacity = new_capacity;
    return true;
}

NFAPICRCList* create_crc_list() {
    NFAPICRCList *list = malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    list->entries = malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->capacity = MAX_ENTRIES;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    log_event("CRC List created");
    return list;
}

bool add_crc_pdu(NFAPICRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_NFAPI_CRC_INDICATION_PDU(&pdu)) {
        log_event("Validation failed for PDU");
        return false;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        bool success = resize_list(list, new_capacity);
        if (!success) {
            log_event("Memory allocation failed during resize");
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    list->entries[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);

    log_event("PDU added successfully");
    return true;
}

void serialize_crc_list(NFAPICRCList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_event("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list->lock);
    fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    log_event("List serialized successfully");
}

bool deserialize_crc_list(NFAPICRCList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_event("Failed to open file for deserialization");
        return false;
    }

    size_t count = fread(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->capacity, file);
    if (ferror(file)) {
        fclose(file);
        log_event("Read error during deserialization");
        return false;
    }

    pthread_mutex_lock(&list->lock);
    list->count = count;
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    log_event("List deserialized successfully");

    return true;
}

void free_crc_list(NFAPICRCList *list) {
    if (list) {
        free(list->entries);
        pthread_mutex_destroy(&list->lock);
        free(list);
        log_event("CRC List freed");
    }
}
