    NFAPI_CRC_INDICATION_PDU_T *dataArray;
    size_t count;
} CRCManager;

Status initialize_crc_manager(CRCManager *manager) {
    if (pthread_mutex_init(&manager->lock, NULL) != 0) return FAILURE;
    manager->dataArray = NULL;
    manager->count = 0;
    return SUCCESS;
}

void free_crc_manager(CRCManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->dataArray);
    manager->dataArray = NULL;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

Status add_pdu_to_array(CRCManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (manager->count >= MAX_ELEMENTS) return FAILURE;

    pthread_mutex_lock(&manager->lock);

    size_t newSize = manager->count + 1;
    NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(manager->dataArray, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        pthread_mutex_unlock(&manager->lock);
        return FAILURE;
    }

    newArray[manager->count] = pdu;
    manager->dataArray = newArray;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return SUCCESS;
}

Status fetch_external_data_async(CRCManager *manager, int index) {
