    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;

    Status status = add_pdu_to_array(manager, pdu);

    pthread_mutex_unlock(&manager->lock);
    return status;
}

void *async_data_fetcher(void *arg) {
