// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity);
int add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T element);
int remove_element_by_index(DynamicArray *dyn_array, size_t index);
void print_all_elements(const DynamicArray *dyn_array);
void free_dynamic_array(DynamicArray *dyn_array);

// Function implementations
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity > MAX_ARRAY_SIZE) {
        return NULL;
    }

    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) {
        perror("Failed to allocate memory for DynamicArray");
        return NULL;
    }

    dyn_array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        perror("Failed to allocate memory for array elements");
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->size = 0;

    return dyn_array;
}

int add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (dyn_array->size >= dyn_array->capacity || dyn_array->capacity > MAX_ARRAY_SIZE) {
        return -1; // Cannot add more elements
    }

    memcpy(&dyn_array->array[dyn_array->size], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dyn_array->size++;

    return 0;
}

int remove_element_by_index(DynamicArray *dyn_array, size_t index) {
    if (index >= dyn_array->size) {
        return -1; // Invalid index
    }

    memmove(&dyn_array->array[index], &dyn_array->array[index + 1],
            (dyn_array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dyn_array->size--;

    return 0;
}

void print_all_elements(const DynamicArray *dyn_array) {
    for (size_t i = 0; i < dyn_array->size; ++i) {
        printf("Element %zu: ID=%d, Data=%s\n", i, dyn_array->array[i].id,
               dyn_array->array[i].data);
    }
}

void free_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        free(dyn_array);
    }
}
