#define MAX_ARRAY_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*CustomProcessingFunc)(NFAPI_CRC_INDICATION_PDU_T*);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    bool logging_service_connected;
} CRCArrayManager;

void init_crc_array_manager(CRCArrayManager* manager, size_t initial_capacity) {
    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->logging_service_connected = true; // Assume connected for this example
}

void free_crc_array_manager(CRCArrayManager* manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
}

bool resize_if_needed(CRCArrayManager* manager, size_t new_size) {
    if (new_size > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity < new_size) new_capacity = new_size;

        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            fprintf(stderr, "Memory reallocation failed\n");
            return false;
        }
        manager->array = temp;
        manager->capacity = new_capacity;
    }
    return true;
}

bool add_element(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= MAX_ARRAY_SIZE) {
        fprintf(stderr, "Max array size reached\n");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    if (!resize_if_needed(manager, manager->size + 1)) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    manager->array[manager->size++] = element;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool remove_element(CRCArrayManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->size) {
        fprintf(stderr, "Invalid index\n");
        pthread_mutex_unlock(&manager->lock);
        return false;
    }

    for (size_t i = index; i < manager->size - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

void iterate_and_process(CRCArrayManager* manager, CustomProcessingFunc process_func) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (process_func) {
            process_func(&manager->array[i]);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void log_operation(const char* operation, bool success) {
    // Simulated logging function
    printf("Operation: %s, Success: %d\n", operation, success);

    if (!success && !logging_service_connected) {
        // Retry logic for network failure
        fprintf(stderr, "Logging service disconnected. Retrying...\n");
        // Implement retry mechanism here
    }
}

void custom_processing_example(NFAPI_CRC_INDICATION_PDU_T* element) {
    printf("Processing Element - RX: %d, RNTI: %d, CRCFLAG: %u\n",
           element->RX_UE_INFORMATION_TAG,
           element->RNTI,
           element->CRCFLAG);
}

int main() {
    CRCArrayManager manager;
    init_crc_array_manager(&manager, 10);

    NFAPI_CRC_INDICATION_PDU_T new_element = {1, 12345, rand() % 2};
    if (add_element(&manager, new_element)) {
        log_operation("Add Element", true);
    } else {
        log_operation("Add Element", false);
    }

    iterate_and_process(&manager, custom_processing_example);

    remove_element(&manager, 0);
    log_operation("Remove Element", true);

    free_crc_array_manager(&manager);
    return 0;
}
