#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ACTIVE_CONNECTIONS 1000

typedef struct TCPConnectionRecord {
    int id; // Unique identifier for the connection
    char state[50]; // Connection state
    struct TCPConnectionRecord *next;
} TCP_CONNECTION_RECORD;

// Global head pointer for the linked list
TCP_CONNECTION_RECORD *head = NULL;
int active_connections = 0;
pthread_mutex_t lock; // Mutex for thread-safe operations

void handle_memory_allocation_failure(void *ptr) {
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
}

TCP_CONNECTION_RECORD* create_connection(int id, const char *state) {
    TCP_CONNECTION_RECORD *new_conn = malloc(sizeof(TCP_CONNECTION_RECORD));
    handle_memory_allocation_failure(new_conn);

    new_conn->id = id;
    strncpy(new_conn->state, state, sizeof(new_conn->state) - 1);
    new_conn->next = NULL;

    return new_conn;
}

void add_connection(int id, const char *state) {
    pthread_mutex_lock(&lock);

    if (active_connections >= MAX_ACTIVE_CONNECTIONS) {
        fprintf(stderr, "Max active connections reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    TCP_CONNECTION_RECORD *new_conn = create_connection(id, state);

    // Add to the beginning of the list for O(1) insertion
    new_conn->next = head;
    head = new_conn;

    active_connections++;
    pthread_mutex_unlock(&lock);
}

TCP_CONNECTION_RECORD* find_connection(int id) {
    TCP_CONNECTION_RECORD *current = head;
    while (current != NULL) {
        if (current->id == id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void remove_connection(int id) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    TCP_CONNECTION_RECORD *current = head;
    TCP_CONNECTION_RECORD *prev = NULL;

    while (current != NULL && current->id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Connection not found
        pthread_mutex_unlock(&lock);
        return;
    }

    if (prev == NULL) { // Removing head
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    active_connections--;

    pthread_mutex_unlock(&lock);
}

void iterate_and_log(void (*process_func)(TCP_CONNECTION_RECORD*)) {
    pthread_mutex_lock(&lock);

    TCP_CONNECTION_RECORD *current = head;
    while (current != NULL) {
        process_func(current);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

// Example usage of the iteration function
void log_connection_state(TCP_CONNECTION_RECORD *conn) {
    printf("Connection ID: %d, State: %s\n", conn->id, conn->state);
}

int main() {
    // Initialize mutex
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        return EXIT_FAILURE;
    }

    // Example usage
    add_connection(1, "ESTABLISHED");
    add_connection(2, "CLOSED");

    iterate_and_log(log_connection_state);

    remove_connection(1);

    iterate_and_log(log_connection_state);

    // Destroy mutex
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
