#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MAC_ID_LEN 18

typedef struct L2Entity {
    char l2_entity_id[MAX_MAC_ID_LEN];
    struct L2Entity* next;
} L2Entity;

typedef struct MACEntityDescriptor {
    char mac_entity_id[MAX_MAC_ID_LEN];
    L2Entity* l2_entities_head;
    pthread_mutex_t lock; // For synchronization
    struct MACEntityDescriptor* next;
} MACEntityDescriptor;

MACEntityDescriptor* mac_entity_list = NULL;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

int is_mac_id_unique(const char* id) {
    pthread_mutex_lock(&global_lock);
    for (MACEntityDescriptor* current = mac_entity_list; current != NULL; current = current->next) {
        if (strcmp(current->mac_entity_id, id) == 0) {
            pthread_mutex_unlock(&global_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&global_lock);
    return 1;
}

MACEntityDescriptor* create_mac_entity(const char* mac_id) {
    if (!is_mac_id_unique(mac_id)) {
        fprintf(stderr, "Error: MAC entity ID %s already exists.\n", mac_id);
        return NULL;
    }

    MACEntityDescriptor* new_mac = (MACEntityDescriptor*)malloc(sizeof(MACEntityDescriptor));
    if (!new_mac) {
        perror("Failed to allocate memory for MAC entity");
        return NULL;
    }

    strncpy(new_mac->mac_entity_id, mac_id, MAX_MAC_ID_LEN);
    new_mac->l2_entities_head = NULL;
    pthread_mutex_init(&new_mac->lock, NULL);
    new_mac->next = NULL;

    pthread_mutex_lock(&global_lock);
    new_mac->next = mac_entity_list;
    mac_entity_list = new_mac;
    pthread_mutex_unlock(&global_lock);

    return new_mac;
}

int add_l2_entity(MACEntityDescriptor* mac_entity, const char* l2_id) {
    if (!mac_entity || !is_mac_id_unique(l2_id)) {
        fprintf(stderr, "Error: Invalid MAC entity or L2 ID.\n");
        return 0;
    }

    pthread_mutex_lock(&mac_entity->lock);

    // Check for duplicate L2 entity within the same MAC entity
    for (L2Entity* current = mac_entity->l2_entities_head; current != NULL; current = current->next) {
        if (strcmp(current->l2_entity_id, l2_id) == 0) {
            pthread_mutex_unlock(&mac_entity->lock);
            fprintf(stderr, "Error: L2 entity ID %s already exists in MAC entity %s.\n", l2_id, mac_entity->mac_entity_id);
            return 0;
        }
    }

    // Add new L2 entity
    L2Entity* new_l2 = (L2Entity*)malloc(sizeof(L2Entity));
    if (!new_l2) {
        perror("Failed to allocate memory for L2 entity");
        pthread_mutex_unlock(&mac_entity->lock);
        return 0;
    }

    strncpy(new_l2->l2_entity_id, l2_id, MAX_MAC_ID_LEN);
    new_l2->next = mac_entity->l2_entities_head;
    mac_entity->l2_entities_head = new_l2;

    pthread_mutex_unlock(&mac_entity->lock);

    return 1;
}

void verify_integrity() {
    pthread_mutex_lock(&global_lock);
    for (MACEntityDescriptor* current_mac = mac_entity_list; current_mac != NULL; current_mac = current_mac->next) {
        pthread_mutex_lock(&current_mac->lock);

        // Verify uniqueness of L2 entities within the same MAC entity
        for (L2Entity* l2_current = current_mac->l2_entities_head; l2_current != NULL; l2_current = l2_current->next) {
            for (L2Entity* l2_check = l2_current->next; l2_check != NULL; l2_check = l2_check->next) {
                if (strcmp(l2_current->l2_entity_id, l2_check->l2_entity_id) == 0) {
                    fprintf(stderr, "Integrity Error: Duplicate L2 entity ID %s in MAC entity %s.\n", l2_current->l2_entity_id, current_mac->mac_entity_id);
                }
            }
        }

        pthread_mutex_unlock(&current_mac->lock);
    }
    pthread_mutex_unlock(&global_lock);
}

void cleanup() {
    pthread_mutex_lock(&global_lock);
    for (MACEntityDescriptor* mac = mac_entity_list; mac != NULL;) {
        MACEntityDescriptor* to_free = mac;
        mac = mac->next;

        // Free L2 entities
        L2Entity* l2 = to_free->l2_entities_head;
        while (l2) {
            L2Entity* next_l2 = l2->next;
            free(l2);
            l2 = next_l2;
        }

        pthread_mutex_unlock(&to_free->lock);
        pthread_mutex_destroy(&to_free->lock);

        free(to_free);
    }
    pthread_mutex_unlock(&global_lock);
}

int main() {
    MACEntityDescriptor* mac1 = create_mac_entity("00:11:22:33:44:55");
    if (mac1) add_l2_entity(mac1, "L2-01");
    if (mac1) add_l2_entity(mac1, "L2-02");

    MACEntityDescriptor* mac2 = create_mac_entity("66:77:88:99:AA:BB");
    if (mac2) add_l2_entity(mac2, "L2-03");

    verify_integrity();

    cleanup();
    return 0;
}
