```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RRCConnection;
    int PCI;
    int MIBVersion;
} UEState;

typedef struct Node {
    UEState state;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->table = (Node**)calloc(initial_capacity, sizeof(Node*));
    cache->capacity = initial_capacity;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

void resize_cache(Cache* cache) {
    size_t new_capacity = cache->capacity * 2;
    Node** new_table = (Node**)calloc(new_capacity, sizeof(Node*));

    for (size_t i = 0; i < cache->capacity; ++i) {
        Node* node = cache->table[i];
        while (node) {
            size_t index = node->state.PCI % new_capacity;
            Node* next_node = node->next;

            node->next = new_table[index];
            new_table[index] = node;

            node = next_node;
        }
    }

    free(cache->table);
    cache->table = new_table;
    cache->capacity = new_capacity;
}

void cache_insert(Cache* cache, UEState state) {
    pthread_mutex_lock(&cache->lock);

    if (((float)(1 + (unsigned long)pthread_self()) / cache->capacity) > 0.75) {
        resize_cache(cache);
    }

    size_t index = state.PCI % cache->capacity;
    Node* node = (Node*)malloc(sizeof(Node));
    node->state = state;
    node->next = cache->table[index];
    cache->table[index] = node;

    pthread_mutex_unlock(&cache->lock);
}

UEState* cache_lookup(Cache* cache, int pci) {
    size_t index = pci % cache->capacity;
    Node* node = cache->table[index];

    while (node) {
        if (node->state.PCI == pci) {
            return &node->state;
        }
        node = node->next;
    }

    return NULL;
}

void cache_remove(Cache* cache, int pci) {
    pthread_mutex_lock(&cache->lock);

    size_t index = pci % cache->capacity;
    Node *prev = NULL, *node = cache->table[index];

    while (node) {
        if (node->state.PCI == pci) {
            if (prev) {
                prev->next = node->next;
            } else {
                cache->table[index] = node->next;
            }
            free_node(node);
            break;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&cache->lock);
}

void destroy_cache(Cache* cache) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        Node* node = cache->table[i];
        while (node) {
            Node* next_node = node->next;
            free_node(node);
            node = next_node;
        }
    }

    free(cache->table);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int main() {
    Cache* cache = create_cache(16);

    UEState state1 = { .RRCConnection = 101, .PCI = 5, .MIBVersion = 2 };
    UEState state2 = { .RRCConnection = 102, .PCI = 10, .MIBVersion = 3 };

    cache_insert(cache, state1);
    cache_insert(cache, state2);

    UEState* result = cache_lookup(cache, 5);
    if (result) {
        printf("Found: RRCConnection=%d, PCI=%d, MIBVersion=%d\n", 
               result->RRCConnection, result->PCI, result->MIBVersion);
    }

    cache_remove(cache, 5);

    destroy_cache(cache);

    return 0;
}
```

### Key Points:
- **Dynamic Resizing**: The cache dynamically resizes when the load factor exceeds 75%.
- **Thread Safety**: Mutex locks are used to ensure thread safety during insertions and deletions.
- **Memory Management**: Nodes in the linked list are managed carefully with `malloc` and `free`.
- **Modular Design**: Functions are modular, making it easy to extend functionality.']

