void log_error(const char *error);

pthread_mutex_t nfa_crc_lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_crc_indications(size_t num_structs, RNTI min_rnti, RNTI max_rnti) {
    pthread_mutex_lock(&nfa_crc_lock);

    NFAPI_CRC_INDICATION_PDU_T *indication_list = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(16, num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indication_list) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&nfa_crc_lock);
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    size_t max_set_flags = num_structs / 2; // Limit to 50% of total
    size_t set_count = 0;

    for (size_t i = 0; i < num_structs; ++i) {
        indication_list[i].rx_ue_info_tag = /* Initialize RX_UE_INFORMATION_TAG */;
        indication_list[i].rnti = rand() % ((max_rnti - min_rnti + 1) + min_rnti);

        if (indication_list[i].rnti < min_rnti || indication_list[i].rnti > max_rnti) {
            // Handle RNTI range filtering
            free(indication_list);
            pthread_mutex_unlock(&nfa_crc_lock);
            return NULL;
        }

        indication_list[i].crc_indication_rel8_tag = /* Initialize CRC_INDICATION_REL8_TAG */;

        if (set_count < max_set_flags && rand() % 2 == 0) {
            indication_list[i].crcflag = 1; // Randomly set the flag
            ++set_count;
        } else {
            indication_list[i].crcflag = 0;
        }
    }

    log_message("NFAPI_CRC_INDICATION_PDU_T list generated successfully");

    pthread_mutex_unlock(&nfa_crc_lock);
    return indication_list;
}

void free_nfa_crc_indications(NFAPI_CRC_INDICATION_PDU_T *indication_list) {
    if (indication_list) {
        free(indication_list);
        log_message("NFAPI_CRC_INDICATION_PDU_T list deallocated");
    }
}

// Implement these logging functions as needed for your environment
