void custom_free(void* ptr) { free(ptr); }

typedef struct {
    UEState* array;
    int count;
    int capacity;
} DynamicArray;

typedef struct CacheNode {
    uint16_t pci;
    UEState state;
    time_t lastAccessed;
    struct CacheNode* next;
} CacheNode;

CacheNode* cacheHead = NULL;
int cacheCount = 0;

// Function prototypes
void insert_ue_state(DynamicArray* array, UEState state);
UEState* lookup_ue_state(DynamicArray* array, uint16_t pci);
void delete_ue_state(DynamicArray* array, uint16_t pci);
void log_operation(const char* operation, uint16_t pci);
UEState* get_from_cache(uint16_t pci);
void update_cache(UEState state);

// Helper functions
static void resize_array_if_needed(DynamicArray* array);
static CacheNode* create_cache_node(UEState state);
static void add_to_cache(CacheNode* node);
static void evict_oldest_cache_entry();

void insert_ue_state(DynamicArray* array, UEState state) {
    if (array->count == array->capacity) {
        resize_array_if_needed(array);
    }
    // Find and replace if exists
    for (int i = 0; i < array->count; ++i) {
        if (array->array[i].pci == state.pci) {
            array->array[i] = state;
            log_operation("Updated", state.pci);
            return;
        }
    }

    // Otherwise, insert new
    array->array[array->count++] = state;
    update_cache(state);
    log_operation("Inserted", state.pci);
}

UEState* lookup_ue_state(DynamicArray* array, uint16_t pci) {
    UEState* cached = get_from_cache(pci);
    if (cached) return cached;

    for (int i = 0; i < array->count; ++i) {
        if (array->array[i].pci == pci) {
            update_cache(array->array[i]);
            log_operation("Looked up", pci);
            return &array->array[i];
        }
    }

    log_operation("Not found", pci);
    return NULL;
}

void delete_ue_state(DynamicArray* array, uint16_t pci) {
    for (int i = 0; i < array->count; ++i) {
        if (array->array[i].pci == pci) {
            memmove(&array->array[i], &array->array[i + 1],
                    sizeof(UEState) * (array->count - i - 1));
            --array->count;
            log_operation("Deleted", pci);
            return;
        }
    }

    log_operation("Not found for delete", pci);
}

void resize_array_if_needed(DynamicArray* array) {
    if (array->capacity == 0 || array->count < array->capacity) return;

    int newCapacity = array->capacity * 2;
    UEState* newArray = (UEState*)custom_alloc(sizeof(UEState) * newCapacity);
    memcpy(newArray, array->array, sizeof(UEState) * array->count);

    custom_free(array->array);
    array->array = newArray;
    array->capacity = newCapacity;
}

void log_operation(const char* operation, uint16_t pci) {
    printf("[%s] PCI: %u\n", operation, pci);
}

CacheNode* create_cache_node(UEState state) {
    CacheNode* node = (CacheNode*)custom_alloc(sizeof(CacheNode));
    node->pci = state.pci;
    node->state = state;
    node->lastAccessed = time(NULL);
    node->next = NULL;
    return node;
}

void add_to_cache(CacheNode* node) {
    if (cacheCount >= CACHE_SIZE) evict_oldest_cache_entry();

    node->next = cacheHead;
    cacheHead = node;
    ++cacheCount;
}

UEState* get_from_cache(uint16_t pci) {
    CacheNode* current = cacheHead;
    while (current) {
        if (current->pci == pci) {
            current->lastAccessed = time(NULL);
            return &current->state;
        }
        current = current->next;
    }
    return NULL;
}

void update_cache(UEState state) {
    CacheNode* node = create_cache_node(state);
    add_to_cache(node);
}

void evict_oldest_cache_entry() {
    if (!cacheHead) return;

    CacheNode** prev = &cacheHead;
    CacheNode* oldest = cacheHead;
    CacheNode* current = cacheHead->next;

    while (current) {
        if ((time(NULL) - current->lastAccessed) > 60) { // Example eviction policy
            *prev = current;
            custom_free(oldest);
            --cacheCount;
            return;
        }
        prev = &current->next;
        oldest = current;
        current = current->next;
    }

    if (oldest == cacheHead) {
        cacheHead = cacheHead->next;
        custom_free(oldest);
        --cacheCount;
    } else {
        CacheNode* toRemove = cacheHead;
        while (toRemove->next != oldest) toRemove = toRemove->next;
        toRemove->next = oldest->next;
        custom_free(oldest);
        --cacheCount;
    }
}

int main() {
    DynamicArray array = {NULL, 0, 4};
    array.array = (UEState*)custom_alloc(sizeof(UEState) * array.capacity);

    UEState state1 = {1, 100, 2}; // Example data
    insert_ue_state(&array, state1);
    lookup_ue_state(&array, 100);
    delete_ue_state(&array, 100);

    custom_free(array.array);
    return 0;
}
