```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 1000
#define SCALE_FACTOR 2

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

uint64_t generate_unique_id(uint16_t rxTag, uint32_t rnti) {
    return ((uint64_t)rxTag << 32) | (rnti & 0xFFFFFFFF);
}

void initialize_list(DynamicList *list) {
    list->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void cleanup_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

int expand_capacity_if_needed(DynamicList *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * SCALE_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    return 0;
}

int add_element(DynamicList *list, uint16_t rxTag, uint32_t rnti, uint8_t crcTag) {
    pthread_mutex_lock(&list->lock);

    if (expand_capacity_if_needed(list) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[list->count++];
    element->RX_UE_INFORMATION_TAG = rxTag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crcTag;

    // Set CRCFLAG randomly
    srand(time(NULL) ^ (intptr_t)pthread_self()); // Seed with time and thread ID for randomness
    element->CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void cleanup_unused_elements(DynamicList *list, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);

    size_t i;
    for (i = 0; i < list->count;) {
        if (list->data[i].RNTI == rnti) {
            memmove(&list->data[i], &list->data[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicList nfa_list;
    initialize_list(&nfa_list);

    // Example usage
    add_element(&nfa_list, 1, 1000, 5);
    add_element(&nfa_list, 2, 2000, 6);

    cleanup_unused_elements(&nfa_list, 1000); // Clean up elements with RNTI = 1000

    cleanup_list(&nfa_list);
    return 0;
}
```

