```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>

// Assuming these types are defined elsewhere
typedef struct {
    // Structure members for RX_UE_INFORMATION_TAG, RNTI, etc.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    // CRC indication tag members
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

#define MAX_ARRAY_SIZE 1024

// Dynamic array structure with synchronization primitives
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_ARRAY_SIZE];
    size_t capacity;
    atomic_size_t active_count;
    pthread_mutex_t lock;
} NFAPIDynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(NFAPIDynamicArray *dyn_array, size_t capacity) {
    dyn_array->capacity = (capacity > MAX_ARRAY_SIZE) ? MAX_ARRAY_SIZE : capacity;
    for (size_t i = 0; i < dyn_array->capacity; ++i) {
        dyn_array->array[i] = NULL;
    }
    atomic_store(&dyn_array->active_count, 0);
    pthread_mutex_init(&dyn_array->lock, NULL);
}

// Function to add a structure to the dynamic array
bool add_structure(NFAPIDynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&dyn_array->lock);

    if (atomic_load(&dyn_array->active_count) >= dyn_array->capacity) {
        pthread_mutex_unlock(&dyn_array->lock);
        return false;
    }

    for (size_t i = 0; i < dyn_array->capacity; ++i) {
        if (dyn_array->array[i] == NULL) {
            dyn_array->array[i] = pdu;
            atomic_fetch_add(&dyn_array->active_count, 1);
            pthread_mutex_unlock(&dyn_array->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&dyn_array->lock);
    return false;
}

// Function to clear the entire array
void clear_dynamic_array(NFAPIDynamicArray *dyn_array) {
    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->capacity; ++i) {
        if (dyn_array->array[i] != NULL) {
            free(dyn_array->array[i]->crc_indication); // Assuming crc_indication is dynamically allocated
            dyn_array->array[i] = NULL;
        }
    }

    atomic_store(&dyn_array->active_count, 0);
    pthread_mutex_unlock(&dyn_array->lock);
}

// Function to safely iterate over the array
void iterate_dynamic_array(NFAPIDynamicArray *dyn_array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->capacity; ++i) {
        if (dyn_array->array[i] != NULL) {
            callback(dyn_array->array[i]);
        }
    }

    pthread_mutex_unlock(&dyn_array->lock);
}

// Function to free the dynamic array
void free_dynamic_array(NFAPIDynamicArray *dyn_array) {
    clear_dynamic_array(dyn_array);

    pthread_mutex_destroy(&dyn_array->lock);
}

// Example callback function for iteration
void print_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Print or process the structure as needed
}

int main() {
    NFAPIDynamicArray dyn_array;
    init_dynamic_array(&dyn_array, 100);

    // Add structures and perform operations...

    iterate_dynamic_array(&dyn_array, print_structure);

    free_dynamic_array(&dyn_array);
    return 0;
}
```

