#include <pthread.h>
#include <string.h>

#define MAX_ATTEMPTS 5

typedef struct L2Entity {
    int id;
    struct L2Entity* next;
} L2Entity;

typedef struct MACEntityDescriptor {
    int mac_id;
    L2Entity* l2_entities_head;
    pthread_mutex_t lock;
} MACEntityDescriptor;

MACEntityDescriptor* mac_entity_descriptors = NULL;
size_t descriptor_count = 0;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    printf("%s\n", message); // Placeholder for actual logging mechanism
}

int initialize_mac_entities(size_t initial_capacity) {
    pthread_mutex_lock(&global_lock);

    mac_entity_descriptors = calloc(initial_capacity, sizeof(MACEntityDescriptor));
    if (!mac_entity_descriptors) {
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&mac_entity_descriptors[i].lock, NULL);
    }

    descriptor_count = initial_capacity;
    pthread_mutex_unlock(&global_lock);

    log_message("MAC entity descriptors initialized successfully.");
    return 0;
}

int add_mac_entity(int mac_id) {
    if (mac_id < 0) return -1;

    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < descriptor_count; ++i) {
        MACEntityDescriptor* desc = &mac_entity_descriptors[i];

        pthread_mutex_lock(&desc->lock);
        if (desc->mac_id == 0 || desc->mac_id == mac_id) {
            desc->mac_id = mac_id;
            desc->l2_entities_head = NULL;

            log_message("Added new MAC entity.");
            pthread_mutex_unlock(&global_lock);
            return 0;
        }
        pthread_mutex_unlock(&desc->lock);
    }

    for (int attempts = 0; attempts < MAX_ATTEMPTS; ++attempts) {
        size_t new_capacity = descriptor_count * 2;

        MACEntityDescriptor* temp = realloc(mac_entity_descriptors, new_capacity * sizeof(MACEntityDescriptor));
        if (!temp) continue;

        mac_entity_descriptors = temp;
        for (size_t i = descriptor_count; i < new_capacity; ++i) {
            pthread_mutex_init(&mac_entity_descriptors[i].lock, NULL);
        }

        descriptor_count = new_capacity;

        log_message("MAC entity descriptors resized.");
        break;
    }

    if (!mac_entity_descriptors) {
        pthread_mutex_unlock(&global_lock);
        return -1; // Memory allocation failure
    }

    pthread_mutex_lock(&mac_entity_descriptors[descriptor_count - 1].lock);
    mac_entity_descriptors[descriptor_count - 1].mac_id = mac_id;
    mac_entity_descriptors[descriptor_count - 1].l2_entities_head = NULL;

    log_message("Added new MAC entity with resized array.");
    pthread_mutex_unlock(&global_lock);

    return 0;
}

int add_l2_entity_to_mac(int mac_id, int l2_id) {
    if (mac_id < 0 || l2_id < 0) return -1;

    for (size_t i = 0; i < descriptor_count; ++i) {
        MACEntityDescriptor* desc = &mac_entity_descriptors[i];

        pthread_mutex_lock(&desc->lock);
        if (desc->mac_id == mac_id) {
            L2Entity* new_l2 = malloc(sizeof(L2Entity));
            if (!new_l2) {
                pthread_mutex_unlock(&desc->lock);
                log_message("Failed to allocate memory for L2 entity.");
                return -1;
            }

            new_l2->id = l2_id;
            new_l2->next = desc->l2_entities_head;
            desc->l2_entities_head = new_l2;

            log_message("Added L2 entity to MAC entity.");
            pthread_mutex_unlock(&desc->lock);
            return 0;
        }
        pthread_mutex_unlock(&desc->lock);
    }

    log_message("MAC entity ID not found.");
    return -1;
}

int verify_mac_entities() {
    int unique_mac_ids[descriptor_count];
    memset(unique_mac_ids, -1, sizeof(unique_mac_ids));

    for (size_t i = 0; i < descriptor_count; ++i) {
        MACEntityDescriptor* desc = &mac_entity_descriptors[i];

        pthread_mutex_lock(&desc->lock);
        if (desc->mac_id >= 0) {
            for (int j = 0; j < descriptor_count; ++j) {
                if (unique_mac_ids[j] == desc->mac_id) {
                    log_message("Duplicate MAC entity ID found.");
                    pthread_mutex_unlock(&global_lock);
                    return -1;
                }
            }

            unique_mac_ids[i] = desc->mac_id;

            L2Entity* l2_iter = desc->l2_entities_head;
            while (l2_iter) {
                if (l2_iter->id < 0) {
                    log_message("Invalid L2 entity ID found.");
                    pthread_mutex_unlock(&global_lock);
                    return -1;
                }
                l2_iter = l2_iter->next;
            }
        }
        pthread_mutex_unlock(&desc->lock);
    }

    log_message("MAC entity configuration verified successfully.");
    return 0;
}

void cleanup_mac_entities() {
    if (!mac_entity_descriptors) return;

    for (size_t i = 0; i < descriptor_count; ++i) {
        MACEntityDescriptor* desc = &mac_entity_descriptors[i];

        pthread_mutex_lock(&desc->lock);
        L2Entity* l2_iter = desc->l2_entities_head;
        while (l2_iter) {
            L2Entity* temp = l2_iter;
            l2_iter = l2_iter->next;
            free(temp);
        }
        pthread_mutex_unlock(&desc->lock);
    }

    for (size_t i = 0; i < descriptor_count; ++i) {
        pthread_mutex_destroy(&mac_entity_descriptors[i].lock);
    }

    free(mac_entity_descriptors);

    log_message("MAC entity descriptors cleaned up.");
}
