// NICB Initialization Function
int initialize_nicb_array(NICB **nicbs, int num_interfaces, const char *config) {
    if (!nicbs || num_interfaces <= 0 || !config) {
        log_message("Invalid input parameters");
        return -1;
    }

    srand(time(NULL)); // Seed for random DNS selection

    *nicbs = (NICB *)malloc(num_interfaces * sizeof(NICB));
    if (*nicbs == NULL) {
        log_message("Memory allocation failed");
        return -2;
    }

    char *config_copy = strdup(config);
    if (!config_copy) {
        free(*nicbs);
        log_message("Failed to duplicate configuration string");
        return -3;
    }

    char *token = strtok(config_copy, ";");
    int index = 0;

    while (token && index < num_interfaces) {
        NICB *current_nicb = &((*nicbs)[index]);

        // Parse MAC address
        sscanf(token, "%[^;];%[^;];%[^;];%[^;];%[^;];%s", 
