               current_nicb->subnet_mask, current_nicb->gateway_ip,
               current_nicb->dns_server1, current_nicb->dns_server2);

        if (!is_valid_mac_address(current_nicb->mac_address) || !is_valid_ip_address(current_nicb->ip_address)) {
            log_message("Invalid MAC or IP address");
            free(*nicbs);
            free(config_copy);
            return -4;
        }

        // Validate reachability
        if (!is_reachable(current_nicb->gateway_ip, 1000) ||
            !is_reachable(current_nicb->dns_server1, 1000) ||
            !is_reachable(current_nicb->dns_server2, 1000)) {
            log_message("Network resource unreachable");
            free(*nicbs);
