        // Randomly select a DNS server for load balancing
        current_nicb->dns_server1 = (rand() % 2 == 0) ? current_nicb->dns_server1 : current_nicb->dns_server2;

        log_message("NICB initialized successfully");

        token = strtok(NULL, ";");
        index++;
    }

    free(config_copy);
    return 0;
}

