#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 1024

typedef struct L3RoutingEntry {
    char *destination;
    struct L3RoutingEntry *next;
} L3RoutingEntry;

typedef struct IPEntityDescriptor {
    int entityID;
    L3RoutingEntry *routingEntries;
    pthread_mutex_t lock; // For thread-safe access
} IPEntityDescriptor;

// Dynamic array of IP Entity Descriptors
typedef struct {
    IPEntityDescriptor **descriptors;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock; // Reader-writer lock for concurrent read/write
} DescriptorArray;

// Initialize the dynamic array
void init_descriptor_array(DescriptorArray *array) {
    array->descriptors = malloc(INITIAL_SIZE * sizeof(IPEntityDescriptor *));
    array->count = 0;
    array->capacity = INITIAL_SIZE;
    pthread_rwlock_init(&array->rwlock, NULL);
}

// Resize the dynamic array
void resize_descriptor_array(DescriptorArray *array) {
    size_t new_capacity = array->capacity * 2;
    IPEntityDescriptor **new_descriptors = realloc(array->descriptors, new_capacity * sizeof(IPEntityDescriptor *));
    if (new_descriptors == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    array->descriptors = new_descriptors;
    array->capacity = new_capacity;
}

// Add an IP Entity Descriptor
int add_ip_entity_descriptor(DescriptorArray *array, int entityID) {
    pthread_rwlock_wrlock(&array->rwlock);

    // Check for duplicate IDs
    for (size_t i = 0; i < array->count; ++i) {
        if (array->descriptors[i]->entityID == entityID) {
            pthread_rwlock_unlock(&array->rwlock);
            return -1; // Duplicate ID found
        }
    }

    if (array->count >= array->capacity) {
        resize_descriptor_array(array);
    }

    IPEntityDescriptor *descriptor = malloc(sizeof(IPEntityDescriptor));
    descriptor->entityID = entityID;
    descriptor->routingEntries = NULL;
    pthread_mutex_init(&descriptor->lock, NULL);

    array->descriptors[array->count++] = descriptor;

    pthread_rwlock_unlock(&array->rwlock);
    return 0; // Success
}

// Add a routing entry to an IP Entity Descriptor
int add_routing_entry(DescriptorArray *array, int entityID, const char *destination) {
    pthread_rwlock_rdlock(&array->rwlock);

    for (size_t i = 0; i < array->count; ++i) {
        IPEntityDescriptor *descriptor = array->descriptors[i];
        if (descriptor->entityID == entityID) {
            pthread_rwlock_unlock(&array->rwlock);
            pthread_mutex_lock(&descriptor->lock);

            L3RoutingEntry *entry = malloc(sizeof(L3RoutingEntry));
            entry->destination = strdup(destination);
            entry->next = descriptor->routingEntries;
            descriptor->routingEntries = entry;

            pthread_mutex_unlock(&descriptor->lock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&array->rwlock);
    return -1; // Entity ID not found
}

// Free the dynamic array and its contents
void free_descriptor_array(DescriptorArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        IPEntityDescriptor *descriptor = array->descriptors[i];

        pthread_mutex_lock(&descriptor->lock);
        L3RoutingEntry *entry = descriptor->routingEntries;
        while (entry != NULL) {
            L3RoutingEntry *next = entry->next;
            free(entry->destination);
            free(entry);
            entry = next;
        }
        pthread_mutex_unlock(&descriptor->lock);

        pthread_mutex_destroy(&descriptor->lock);
        free(descriptor);
    }

    free(array->descriptors);
    pthread_rwlock_destroy(&array->rwlock);
}

// Main function for testing
int main() {
    DescriptorArray array;
    init_descriptor_array(&array);

    add_ip_entity_descriptor(&array, 1);
    add_routing_entry(&array, 1, "192.168.0.1");

    free_descriptor_array(&array);
    return 0;
}
```

This code provides a basic implementation of a dynamic array to manage IP entity descriptors with associated L3 routing entries. It includes synchronization mechanisms for concurrent access and ensures thread safety using mutexes and reader-writer locks. The design is modular, allowing for future expansion and maintenance.']

