    size_t count;
} NICSettings;

static pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;
static NICSettings cached_settings = {NULL, 0};
static int is_cache_valid = 0;

void initialize_nic_settings(const char *xml_file_path) {
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;

    if (is_cache_valid) return; // Use cache if valid

    pthread_once(&once_control, []() {
        pthread_mutex_init(&file_lock, NULL);
    });

    pthread_mutex_lock(&file_lock);

    XMLNode *xml_root = parse_xml_file(xml_file_path);
    if (!xml_root) {
        log_error("Failed to parse the XML file.");
        pthread_mutex_unlock(&file_lock);
        return;
    }

    // Free previous cache
    free(cached_settings.configs);

    int entry_count = count_xml_entries(xml_root); // Assume this function counts valid entries
    cached_settings.configs = malloc(sizeof(NICConfig) * entry_count);
    if (!cached_settings.configs) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&file_lock);
        free_xml_node(xml_root);
        return;
    }

    NICConfig *config = cached_settings.configs;
    for (int i = 0; i < entry_count; ++i) {
        XMLNode *entry = get_next_valid_entry(xml_root, i); // Assume this gets valid entries
        if (!validate_ip_address(entry->ip_address)) {
            log_error("Invalid IP address.");
            continue;
        }

        if (!validate_subnet_mask(entry->subnet_mask)) {
            log_error("Invalid subnet mask.");
            continue;
        }

        if (!validate_gateway_address(entry->gateway_address, entry->subnet_mask)) {
            log_error("Invalid gateway address.");
            continue;
        }

        if (!validate_dns_server(entry->dns_server_1) || !validate_dns_server(entry->dns_server_2)) {
            log_error("Invalid DNS server configuration.");
            continue;
        }

        strncpy(config->ip_address, entry->ip_address, sizeof(config->ip_address));
        strncpy(config->subnet_mask, entry->subnet_mask, sizeof(config->subnet_mask));
        strncpy(config->gateway_address, entry->gateway_address, sizeof(config->gateway_address));
        strncpy(config->dns_server_1, entry->dns_server_1, sizeof(config->dns_server_1));
        strncpy(config->dns_server_2, entry->dns_server_2, sizeof(config->dns_server_2));

        config++;
    }

    cached_settings.count = (size_t)(config - cached_settings.configs);
    is_cache_valid = 1;

    pthread_mutex_unlock(&file_lock);

    free_xml_node(xml_root);
}

void release_nic_settings() {
    if (cached_settings.configs) {
        free(cached_settings.configs);
        cached_settings.configs = NULL;
    }
    cached_settings.count = 0;
    is_cache_valid = 0;

    pthread_mutex_destroy(&file_lock);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_nic_settings(argv[1]);

    // Use the NIC settings...

    release_nic_settings();
    return EXIT_SUCCESS;
}
