            while (current != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = current;
                current = (NFAPI_CRC_INDICATION_PDU_T*)current->CRC_INDICATION_REL8_TAG.CRCFLAG;  // Assume this points to next node
                free(temp);
