        // Populate the new node
        new_node->RX_UE_INFORMATION_TAG = rand();
        new_node->RNTI = rand();
        new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2);

        current->CRC_INDICATION_REL8_TAG.CRCFLAG = (NFAPI_CRC_INDICATION_PDU_T*)new_node;
        current = new_node; 
    }

    log_allocation_status("Allocation successful.");
    return head;
}

// Example usage of the logging function
