CRCIndicationList* create_crc_indication_list(unsigned int N, unsigned int seed, size_t max_memory_size) {
    if (N == 0 || max_memory_size == 0) return NULL;

    CRCIndicationList *list = malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);

