    unsigned int rnti_set[1024] = {0}; // Assuming a maximum of 1024 unique RNTIs
    int unique_rntis_found = 0;

    while (unique_rntis_found < N) {
        pthread_mutex_lock(&list->lock);

        if ((entry_size * (list->size + 1)) > max_memory_size) {
            pthread_mutex_unlock(&list->lock);
            break;
        }

        size_t new_capacity = list->capacity ? list->capacity * 2 : entry_size;
        if (new_capacity < entry_size || new_capacity > max_memory_size / entry_size) {
            pthread_mutex_unlock(&list->lock);
            free(list->data);
            free(list);
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * entry_size);
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            break;
        }
        list->data = new_data;
        list->capacity = new_capacity;

        unsigned int rnti = rand() % 1024; // Example RNTI generation
        while (rnti_set[rnti] || unique_rntis_found >= N) {
            rnti = rand() % 1024;
        }

        RX_UE_INFORMATION_TAG tag = { .valid = 1 }; // Assuming a valid tag for simplicity
        if (!verify_rx_ue_information_tag(&tag)) continue;

        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[list->size];
        pdu->rnti = rnti;
        pdu->rx_ue_info_tag = tag;
        pdu->crcflag = rand() % 2; // Randomly set CRCFLAG

        log_creation(pdu);
        rnti_set[rnti] = 1;
        list->size++;
        unique_rntis_found++;

        pthread_mutex_unlock(&list->lock);
    }

    update_performance_metrics(list->size, list->capacity * entry_size);

    return list;
}

void destroy_crc_indication_list(CRCIndicationList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}
