    NFAPI_CRC_INDICATION_PDU_T new_data;
    new_data.rx_ue_information_tag.RNTI = rnti;
    new_data.rx_ue_information_tag.sequence_number = ++sequence_counter;
    new_data.CRC_INDICATION_REL8_TAG = rand(); // Placeholder, set appropriately
    new_data.CRCFLAG = generate_random_crcflag();

    crc_list = binary_search_insert(&crc_list, new_data);
}

// Function to perform binary search and insert in sorted order
CRCNode* binary_search_insert(CRCNode** head, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (*head == NULL) {
        CRCNode* new_node = (CRCNode*)malloc(sizeof(CRCNode));
        if (new_node == NULL) return NULL;
        new_node->data = new_data;
        new_node->next = *head;
        *head = new_node;
        return *head;
    }

    // Using a simple linear search for simplicity in linked list context
    CRCNode* current = *head, *prev = NULL;

    while (current != NULL && current->data.rx_ue_information_tag.RNTI < new_data.RNTI) {
        prev = current;
        current = current->next;
    }

    CRCNode* new_node = (CRCNode*)malloc(sizeof(CRCNode));
    if (new_node == NULL) return NULL;

    new_node->data = new_data;
    new_node->next = current;

    if (prev == NULL) {
        // Insert at head
        *head = new_node;
    } else {
        prev->next = new_node;
    }

    return *head;
}

// Function to free all allocated resources
void free_crc_list() {
    CRCNode* current = crc_list;
    while (current != NULL) {
        CRCNode* next = current->next;
        free(current);
        current = next;
    }
    crc_list = NULL; // Reset the head pointer after freeing list
}

// Function to generate a random CRCFLAG value
uint8_t generate_random_crcflag() {
    return rand() % 2; // Randomly set as 0 or 1
}
