#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int tile_size;
    int world_width;
    int world_height;
    float camera_speed;
} Configuration;

typedef struct {
    unsigned short rnti;
    int rx_ue_information_tag;
    struct {
        unsigned char crcflag:1;
    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
Configuration default_config = {100, 1000, 500, 5.0f};

// Function prototypes
void fetch_configuration_async(Configuration *config);
int get_random_rnti();
int get_random_rx_ue_information_tag();

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pdu_list(size_t count, Configuration *config) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return NULL;

    pthread_mutex_lock(&config_lock);

    // Attempt to fetch configuration asynchronously
    fetch_configuration_async(config);

    // Use default config as a fallback
    Configuration current_config = *config;

    for (size_t i = 0; i < count; ++i) {
        pdu_list[i].rnti = get_random_rnti();
        pdu_list[i].rx_ue_information_tag = get_random_rx_ue_information_tag();
        pdu_list[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    pthread_mutex_unlock(&config_lock);
    return pdu_list;
}

void fetch_configuration_async(Configuration *config) {
    // Simulate async communication with the config service
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < 0.5) {  // 500ms timeout
        int success = rand() % 2; // Simulate a potential failure in fetching

        if (success) {
            pthread_mutex_lock(&config_lock);
            config->tile_size = 120;
            config->world_width = 1500;
            config->world_height = 600;
            config->camera_speed = 6.5f;
            pthread_mutex_unlock(&config_lock);

            return; // Exit if successful
        }
    }

    // Fallback to default configuration in case of failure or timeout
    pthread_mutex_lock(&config_lock);
    *config = default_config;
    pthread_mutex_unlock(&config_lock);
}

int get_random_rnti() {
    srand((unsigned int)time(NULL));
    return rand() % 65536; // RNTI range
}

int get_random_rx_ue_information_tag() {
    srand((unsigned int)time(NULL));
    return rand(); // Random tag for demonstration
}

// Example usage
int main() {
    Configuration config;
    size_t count = 10000;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_nfa_pdu_list(count, &config);

    if (pdu_list) {
        // Use the pdu_list for further processing...

        free(pdu_list);  // Ensure no memory leaks
    }

    return 0;
}
