typedef struct {
    int rrc_ue_identity_tag;
    char rrc_connection_reconfiguration_message[256];
} NFAPI_RRC_CFR_DUP_T;

#define MAX_BUFFER_SIZE 1000

typedef struct {
    NFAPI_RRC_CFR_DUP_T* buffer[MAX_BUFFER_SIZE];
    size_t count;
    size_t capacity;
} MessageBuffer;

// Function to initialize the message buffer
void initMessageBuffer(MessageBuffer *msgBuf) {
    msgBuf->count = 0;
    msgBuf->capacity = MAX_BUFFER_SIZE;
    for (size_t i = 0; i < msgBuf->capacity; ++i) {
        msgBuf->buffer[i] = NULL;
    }
}

// Function to add a message to the buffer
int addMessageToBuffer(MessageBuffer *msgBuf, const char* message, int identityTag) {
    if (msgBuf->count >= msgBuf->capacity) return -1; // Buffer full

    NFAPI_RRC_CFR_DUP_T* newEntry = malloc(sizeof(NFAPI_RRC_CFR_DUP_T));
    if (!newEntry) return -1; // Memory allocation failure

    strcpy(newEntry->rrc_connection_reconfiguration_message, message);
    newEntry->rrc_ue_identity_tag = identityTag;

    msgBuf->buffer[msgBuf->count++] = newEntry;
    return 0;
}

// Function to process buffered messages in batches
NFAPI_RRC_CFR_DUP_T* processBufferedMessages(MessageBuffer *msgBuf, size_t batchSize) {
    if (batchSize > msgBuf->count) batchSize = msgBuf->count;

    NFAPI_RRC_CFR_DUP_T* batchArray = malloc(batchSize * sizeof(NFAPI_RRC_CFR_DUP_T));
    if (!batchArray) return NULL; // Memory allocation failure

    for (size_t i = 0; i < batchSize; ++i) {
        batchArray[i] = *msgBuf->buffer[i];
        msgBuf->buffer[i] = msgBuf->buffer[msgBuf->count - 1]; 
        --msgBuf->count;
    }

    // Shift remaining messages to the front
    for (size_t i = batchSize; i < msgBuf->count; ++i) {
        msgBuf->buffer[i - batchSize] = msgBuf->buffer[i];
    }
    for (size_t i = msgBuf->count - batchSize; i < msgBuf->capacity; ++i) {
        msgBuf->buffer[i] = NULL;
    }

    return batchArray;
}

// Function to free the processed messages
void freeProcessedMessages(NFAPI_RRC_CFR_DUP_T* messages, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(&messages[i]);
    }
}

