['Below is a C implementation of the described function that manages a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures. The code integrates logging, handles memory allocation failures, maintains sorted order based on `RNTI`, and provides mechanisms for buffer management and efficient resource cleanup.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_SEQ_NUMBER 65535

typedef struct {
    uint32_t RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint16_t sequenceNumber;
    // Other fields...
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rxUeInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG_T crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Log function prototype
void log_message(const char *message);

// Structure to manage dynamic array of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    _Atomic uint32_t seq_number_map; // Using atomic for thread safety
    pthread_mutex_t lock;
} CRCArrayManager;

CRCArrayManager* create_crc_array_manager(size_t initial_capacity) {
    CRCArrayManager *manager = (CRCArrayManager*)malloc(sizeof(CRCArrayManager));
    if (!manager) {
        log_message("Memory allocation failed for CRCArrayManager");
        return NULL;
    }

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        log_message("Memory allocation failed for array");
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    atomic_init(&manager->seq_number_map, 0);
    pthread_mutex_init(&manager->lock, NULL);

    log_message("CRCArrayManager initialized successfully");

    return manager;
}

int add_crc_pdu(CRCArrayManager *manager, uint32_t rnti) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for existing RNTI and update sequence number
    int index = -1;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].rnti == rnti) {
            index = i;
            break;
        }
    }

    // Resize array if necessary
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            log_message("Memory reallocation failed for array");
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    // Add or update PDU
    int insert_pos = manager->count;
    uint32_t seq_number = atomic_fetch_add(&manager->seq_number_map, 1) % (MAX_SEQ_NUMBER + 1);

    if (index == -1) { // New RNTI
        index = manager->count++;
        manager->array[index].rnti = rnti;
    }

    manager->array[index].rxUeInformationTag.sequenceNumber = seq_number;
    manager->array[index].crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Random CRC flag

    // Maintain sorted order based on RNTI
    for (size_t i = insert_pos; i > 0 && manager->array[i - 1].rnti > rnti; --i) {
        NFAPI_CRC_INDICATION_PDU_T temp = manager->array[i];
        manager->array[i] = manager->array[i - 1];
        manager->array[i - 1] = temp;
    }

    pthread_mutex_unlock(&manager->lock);

    log_message("CRC PDU added or updated successfully");
    return 0;
}

void free_crc_array_manager(CRCArrayManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_message("CRCArrayManager resources freed successfully");
}

// Mock logging function
void log_message(const char *message) {
    // Asynchronous logging implementation would go here
    printf("%s\n", message);
}
```

### Key Points:
- **Thread Safety**: Uses a mutex lock to manage concurrent access and atomic operations for sequence numbers.
- **Memory Management**: Handles dynamic resizing of the array with `realloc`.
- **Sorted Insertion**: Maintains order based on `RNTI` using insertion sort logic.
- **Error Handling**: Returns error codes and logs messages for failures.
- **Logging**: Simple logging function provided; in practice, this would be asynchronous.']

['Below is a C function designed to manage a dynamic array of LTE UE Contexts efficiently:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int pduSessionId;
} PduSession;

typedef struct {
    int ueId;
    char lastRrcState[16]; // Assuming fixed size for RRC state representation
    PduSession* pduSessions;
    size_t pduCount;
} UeContext;

typedef struct {
    UeContext** contexts;
    size_t capacity;
    size_t size;
} UeContextArray;

void initUeContextArray(UeContextArray* array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->contexts = (UeContext**)malloc(array->capacity * sizeof(UeContext*));
    if (!array->contexts) {
        perror("Failed to allocate memory for UE Contexts");
        exit(EXIT_FAILURE);
    }
}

void freePduSessions(PduSession* pduSessions, size_t count) {
    free(pduSessions);
}

void addUeContext(UeContextArray* array, int ueId, const char* lastRrcState, PduSession* pduSessions, size_t pduCount) {
    if (array->size == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        UeContext** newContexts = (UeContext**)realloc(array->contexts, newCapacity * sizeof(UeContext*));
        if (!newContexts) {
            perror("Failed to reallocate memory for UE Contexts");
            exit(EXIT_FAILURE);
        }
        array->contexts = newContexts;
        array->capacity = newCapacity;
    }

    UeContext* context = (UeContext*)malloc(sizeof(UeContext));
    if (!context) {
        perror("Failed to allocate memory for UE Context");
        exit(EXIT_FAILURE);
    }

    context->ueId = ueId;
    strncpy(context->lastRrcState, lastRrcState, sizeof(context->lastRrcState) - 1);
    context->pduSessions = (PduSession*)malloc(pduCount * sizeof(PduSession));
    if (!context->pduSessions) {
        perror("Failed to allocate memory for PDU Sessions");
        free(context);
        exit(EXIT_FAILURE);
    }

    memcpy(context->pduSessions, pduSessions, pduCount * sizeof(PduSession));
    context->pduCount = pduCount;

    array->contexts[array->size++] = context;
}

void removeUeContext(UeContextArray* array, int ueId) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->contexts[i]->ueId == ueId) {
            freePduSessions(array->contexts[i]->pduSessions, array->contexts[i]->pduCount);
            free(array->contexts[i]);
            memmove(&array->contexts[i], &array->contexts[i + 1], (array->size - i - 1) * sizeof(UeContext*));
            --array->size;
            return;
        }
    }
}

void freeUeContextArray(UeContextArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        freePduSessions(array->contexts[i]->pduSessions, array->contexts[i]->pduCount);
        free(array->contexts[i]);
    }
    free(array->contexts);
}

int main() {
    UeContextArray ueArray;
    initUeContextArray(&ueArray);

    // Example usage
    PduSession pduSessions[] = {{1}, {2}};
    addUeContext(&ueArray, 1001, "RRC_CONNECTED", pduSessions, 2);

    removeUeContext(&ueArray, 1001);

    freeUeContextArray(&ueArray);
    return 0;
}
```

### Key Points:
- **Memory Management**: Uses `malloc`, `realloc`, and `free` for dynamic memory allocation.
- **Error Handling**: Checks for allocation failures and exits gracefully with error messages.
- **Scalability**: Doubles the capacity of the array when needed to accommodate more contexts.
- **Resource Efficiency**: Frees allocated memory for PDU sessions and UE contexts properly.
- **Integration Readiness**: Designed to be integrated into systems requiring real-time data handling.']

