```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure as per your specifications.
typedef struct {
    int cellID;
    int supportedBands[3]; // Assume 3 bands for simplicity; adjust as needed.
    int sib10ConfigDefault; 
} LTE_UERadioResourceConfigSIB10_T;

// Global variables
LTE_UERadioResourceConfigSIB10_T *dynamicArray = NULL;
size_t arraySize = 0;
pthread_mutex_t arrayMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the dynamic array.
void initDynamicArray(size_t initialCapacity) {
    pthread_mutex_lock(&arrayMutex);

    if (initialCapacity == 0) {
        fprintf(stderr, "Initial capacity must be greater than zero.\n");
        pthread_mutex_unlock(&arrayMutex);
        return;
    }

    dynamicArray = (LTE_UERadioResourceConfigSIB10_T *)malloc(initialCapacity * sizeof(LTE_UERadioResourceConfigSIB10_T));
    if (!dynamicArray) {
        fprintf(stderr, "Memory allocation failed for initial capacity.\n");
        pthread_mutex_unlock(&arrayMutex);
        return;
    }

    arraySize = initialCapacity;

    // Populate the array with default values
    for (size_t i = 0; i < arraySize; ++i) {
        dynamicArray[i].cellID = rand() % 10000 + 1; // Random cell ID between 1 and 10000
        for (int j = 0; j < 3; ++j) { // Assume 3 bands, adjust as necessary.
            dynamicArray[i].supportedBands[j] = rand() % 20 + 1; // Random band selection
        }
        dynamicArray[i].sib10ConfigDefault = 1; // Default configuration value
    }

    pthread_mutex_unlock(&arrayMutex);
}

// Function to resize the array when more space is needed.
void resizeDynamicArray(size_t newCapacity) {
    pthread_mutex_lock(&arrayMutex);

    if (newCapacity <= arraySize) {
        fprintf(stderr, "New capacity must be greater than current size.\n");
        pthread_mutex_unlock(&arrayMutex);
        return;
    }

    LTE_UERadioResourceConfigSIB10_T *tempArray = realloc(dynamicArray, newCapacity * sizeof(LTE_UERadioResourceConfigSIB10_T));
    if (!tempArray) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        pthread_mutex_unlock(&arrayMutex);
        return;
    }

    dynamicArray = tempArray;

    // Initialize the newly allocated portion of the array
    for (size_t i = arraySize; i < newCapacity; ++i) {
        dynamicArray[i].cellID = rand() % 10000 + 1;
        for (int j = 0; j < 3; ++j) {
            dynamicArray[i].supportedBands[j] = rand() % 20 + 1;
        }
        dynamicArray[i].sib10ConfigDefault = 1;
    }

    arraySize = newCapacity;

    pthread_mutex_unlock(&arrayMutex);
}

// Function to safely update a specific entry in the array.
int updateEntry(size_t index, LTE_UERadioResourceConfigSIB10_T config) {
    pthread_mutex_lock(&arrayMutex);

    if (index >= arraySize) {
        fprintf(stderr, "Index out of bounds.\n");
        pthread_mutex_unlock(&arrayMutex);
        return -1;
    }

    memcpy(&dynamicArray[index], &config, sizeof(LTE_UERadioResourceConfigSIB10_T));

    pthread_mutex_unlock(&arrayMutex);
    return 0;
}

// Function to safely free the array when done.
void cleanupDynamicArray() {
    pthread_mutex_lock(&arrayMutex);

    if (dynamicArray) {
        free(dynamicArray);
        dynamicArray = NULL;
    }
    arraySize = 0;

    pthread_mutex_unlock(&arrayMutex);
}
