['Here's a simplified version of how you could implement such a system in C, focusing on key areas like dynamic array management, thread safety, database interaction, and logging. This example uses POSIX threads (pthreads) for concurrency, SQLite for the database, and some custom memory management functions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <sqlite3.h>

#define MAX_SESSIONS 10

typedef struct {
    int session_id;
    double data_usage; // Example statistic
} PDU_Session;

typedef struct {
    char ue_id[32];
    char last_rrc_state[16];
    PDU_Session sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context **contexts;
    size_t count;
    sqlite3 *db;
    pthread_mutex_t db_lock;
} ContextManager;

void init_context(LTE_UE_Context *context) {
    memset(context, 0, sizeof(LTE_UE_Context));
    strncpy(context->ue_id, "default_ue", sizeof(context->ue_id) - 1);
    strcpy(context->last_rrc_state, "IDLE");
    pthread_mutex_init(&context->lock, NULL);
}

void free_context(LTE_UE_Context *context) {
    if (context) {
        pthread_mutex_destroy(&context->lock);
    }
}

LTE_UE_Context* allocate_context(ContextManager *manager) {
    LTE_UE_Context *new_context = malloc(sizeof(LTE_UE_Context));
    if (!new_context) return NULL;

    init_context(new_context);
    manager->contexts[manager->count++] = new_context;

    // Log allocation
    printf("Allocated context for UE ID: %s\n", new_context->ue_id);

    return new_context;
}

void free_all_contexts(ContextManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free_context(manager->contexts[i]);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    pthread_mutex_destroy(&manager->db_lock);
}

void log_message(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

int init_db(sqlite3 **db) {
    int rc = sqlite3_open("lte_contexts.db", db);
    if (rc) {
        log_message("ERROR", "Can't open database");
        return 0;
    }
    char *errMsg = NULL;
    const char *sql = "CREATE TABLE IF NOT EXISTS Contexts("
                      "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                      "ue_id TEXT UNIQUE, "
                      "last_rrc_state TEXT);";
    rc = sqlite3_exec(*db, sql, 0, 0, &errMsg);
    if (rc != SQLITE_OK) {
        log_message("ERROR", errMsg);
        sqlite3_free(errMsg);
        return 0;
    }
    return 1;
}

void close_db(sqlite3 *db) {
    sqlite3_close(db);
}

void insert_context(ContextManager *manager, LTE_UE_Context *context) {
    pthread_mutex_lock(&manager->db_lock);

    char sql[256];
    snprintf(sql, sizeof(sql), "INSERT INTO Contexts (ue_id, last_rrc_state) VALUES ('%s', '%s');", context->ue_id, context->last_rrc_state);

    int rc = sqlite3_exec(manager->db, sql, 0, 0, NULL);
    if (rc != SQLITE_OK) {
        log_message("ERROR", "Failed to insert context");
    }

    pthread_mutex_unlock(&manager->db_lock);
}

// Example function to merge contexts
void merge_contexts(ContextManager *manager, LTE_UE_Context *ctx1, LTE_UE_Context *ctx2) {
    pthread_mutex_lock(&ctx1->lock);
    pthread_mutex_lock(&ctx2->lock);

    // Merge logic (simple example)
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (ctx2->sessions[i].session_id != 0) {
            int found = 0;
            for (int j = 0; j < MAX_SESSIONS; ++j) {
                if (ctx1->sessions[j].session_id == ctx2->sessions[i].session_id) {
                    ctx1->sessions[j].data_usage += ctx2->sessions[i].data_usage;
                    found = 1;
                    break;
                }
            }
            if (!found && i < MAX_SESSIONS - 1) {
                ctx1->sessions[i].session_id = ctx2->sessions[i].session_id;
                ctx1->sessions[i].data_usage = ctx2->sessions[i].data_usage;
            }
        }
    }

    pthread_mutex_unlock(&ctx2->lock);
    pthread_mutex_unlock(&ctx1->lock);

    // Free the second context
    free_context(ctx2);
    free(ctx2);
}

int main() {
    ContextManager manager;
    manager.count = 0;
    manager.db_lock = (pthread_mutex_t){PTHREAD_MUTEX_INITIALIZER};

    if (!init_db(&manager.db)) return EXIT_FAILURE;

    manager.contexts = malloc(10 * sizeof(LTE_UE_Context *));
    if (!manager.contexts) {
        log_message("ERROR", "Failed to allocate context array");
        close_db(manager.db);
        return EXIT_FAILURE;
    }

    LTE_UE_Context *ctx1 = allocate_context(&manager);
    LTE_UE_Context *ctx2 = allocate_context(&manager);

    pthread_mutex_lock(&ctx1->lock);
    strcpy(ctx1->ue_id, "UE1234");
    strcpy(ctx1->last_rrc_state, "CONNECTED");

    pthread_mutex_lock(&ctx2->lock);
    strcpy(ctx2->ue_id, "UE5678");
    strcpy(ctx2->last_rrc_state, "CONNECTED");

    insert_context(&manager, ctx1);
    insert_context(&manager, ctx2);

    merge_contexts(&manager, ctx1, ctx2);

    free_all_contexts(&manager);
    close_db(manager.db);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to ensure thread-safe operations on context objects and database access.
- **Database Integration**: SQLite is used for simplicity; connection pooling can be added with more complex libraries.
- **Logging**: Basic logging is implemented using `printf`.
- **Memory Management**: Proper allocation and deallocation of contexts, including mutex destruction.
- **Context Merging**: A simple example of merging two context objects.

This code provides a foundation that you can expand upon to meet specific requirements like connection pooling, more sophisticated logging, and handling large-scale deployments.']

