int exponential_backoff(int attempt) {
    return INITIAL_BACKOFF_MS * (1 << attempt);
}

void acquire_data_with_retry(char *data, size_t size, int (*data_source_func)(char *, size_t)) {
    int attempt = 0;
    while (attempt < MAX_RETRIES) {
        if (data_source_func(data, size)) {
            return; // Success
        }
        sleep(exponential_backoff(attempt) / 1000.0);
        attempt++;
    }
}

