#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define constants
#define MAX_ARRAY_SIZE 1000 // Example system-defined maximum value
#define CHUNK_SIZE 100      // Allocation chunk size for large values of N

// Assuming a placeholder structure definition
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for synchronizing access to shared resources
pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu);
NFAPI_CRC_INDICATION_PDU_T** allocateNfadataPDUArray(size_t N);

// Initialize a single PDU structure with valid data
void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = 0xDEADBEEF; // Example valid value
        pdu->RNTI = 0xBADF00D;                    // Example valid value
        pdu->CRC_INDICATION_REL8_TAG = 0x1C;       // Example valid value
    }
}

// Allocate an array of NFAPI_CRC_INDICATION_PDU_T structures safely
NFAPI_CRC_INDICATION_PDU_T** allocateNfadataPDUArray(size_t N) {
    size_t adjusted_N = (N > MAX_ARRAY_SIZE) ? MAX_ARRAY_SIZE : ((N < 0) ? 0 : N);
    NFAPI_CRC_INDICATION_PDU_T **pdu_array = NULL;

    pthread_mutex_lock(&allocation_mutex);

    // Allocate memory for the array of pointers
    pdu_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(adjusted_N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (pdu_array == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    // Allocate memory for each structure in chunks to avoid fragmentation
    size_t i;
    for (i = 0; i < adjusted_N; i += CHUNK_SIZE) {
        size_t chunk_size = ((adjusted_N - i) > CHUNK_SIZE) ? CHUNK_SIZE : (adjusted_N - i);
        pdu_array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu_array[i] == NULL) {
            printf("Memory allocation failed at chunk starting index %zu\n", i);

            // Clean up previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(pdu_array[j]);
            }
            free(pdu_array);

            pthread_mutex_unlock(&allocation_mutex);
            return NULL;
        }

        // Initialize each PDU structure in the chunk
        for (size_t j = 0; j < chunk_size; ++j) {
            initialize_pdu(&pdu_array[i + j]);
        }
    }

    pthread_mutex_unlock(&allocation_mutex);
    return pdu_array;
}

// Example usage of allocateNfadataPDUArray
int main() {
    size_t N = 500;
    NFAPI_CRC_INDICATION_PDU_T **pdu_array = allocateNfadataPDUArray(N);

    if (pdu_array != NULL) {
        // Use the allocated array...

        // Cleanup after usage
        for (size_t i = 0; i < MAX_ARRAY_SIZE && pdu_array[i] != NULL; ++i) {
            free(pdu_array[i]);
        }
        free(pdu_array);
    }

    return 0;
}
