        new_node->next = *head;
        *head = new_node;
        return new_node;
    }

    MAC_RX_BUFFER_T *current = *head;
    while (current->next != NULL && current->next->sequence_number < seq_num) {
        current = current->next;
    }

    new_node->next = current->next;
    current->next = new_node;

    return new_node;
}

void free_list(MAC_RX_BUFFER_T *head) {
    MAC_RX_BUFFER_T *current = head;
    while (current != NULL) {
        MAC_RX_BUFFER_T *temp = current;
        current = current->next;
        free(temp->rx_pdu.data);  // Free RX_PDU data if allocated dynamically
        free(temp);
    }
}

void print_list(MAC_RX_BUFFER_T *head) {
    while (head != NULL) {
        printf("Sequence Number: %u, Timestamp: %ld\n", head->sequence_number, head->reception_timestamp);
        head = head->next;
    }
}

int main() {
    MAC_RX_BUFFER_T *list_head = NULL;

    add_sorted(&list_head, 5);
    add_sorted(&list_head, 3);
    add_sorted(&list_head, 8);

    print_list(list_head);

    free_list(list_head);

    return 0;
}
