    if (!array) {
        log_message(LOG_LEVEL_INFO, "Memory allocation failed.");
        stats->failed_initializations++;
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_configs; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        array[i].RNTI = rand() % 10000;
        array[i].CRCFLAG = rand() % 2;
        array[i].UNIQUE_IDENTIFIER = i + 1;

        log_message(LOG_LEVEL_DEBUG, "Configuring PDU: RX_UE_INFORMATION_TAG=");
