               array[i].RX_UE_INFORMATION_TAG,
               array[i].RNTI,
               array[i].CRCFLAG,
               array[i].UNIQUE_IDENTIFIER);
    }

    if (verify_integrity(array, num_configs) != 0) {
        free(array);
        stats->failed_initializations++;
        return NULL;
    }

    stats->successful_initializations += num_configs;
    log_message(LOG_LEVEL_INFO, "Array populated successfully.");
    return array;
}

void cleanup_and_report(NFAPI_CRC_INDICATION_PDU_T *array, InitializationStats *stats) {
