// Node for doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Doubly Linked List structure
typedef struct {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t lock;
    int allocations;
    int deallocations;
} LinkedList;

// Function prototypes
EVP_CIPHER *select_cipher(int mode);
LinkedList* initialize_list();
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data);
void insert_node(LinkedList* list, Node* node);
void remove_node(LinkedList* list, Node* node);
void free_list(LinkedList* list);
void update_keys();
void log_performance_metrics();

// Initialize the doubly linked list
LinkedList* initialize_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        perror("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->allocations = 0;
    list->deallocations = 0;
    return list;
}

// Create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Insert a new node into the list
void insert_node(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->count++;
    list->allocations++;

    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the list
void remove_node(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (node->prev)
        node->prev->next = node->next;
    else
        list->head = node->next;

    if (node->next)
        node->next->prev = node->prev;
    else
        list->tail = node->prev;

    free(node);
    list->count--;
    list->deallocations++;

    pthread_mutex_unlock(&list->lock);
}

// Free the entire list
void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Select and return the appropriate cipher
EVP_CIPHER *select_cipher(int mode) {
    switch (mode) {
        case 1: // ECB Mode
            return EVP_des_ede3_ecb();
        case 2: // EDE Mode
            return EVP_des_ede_cbc();
        case 3: // EDE3 Mode
            return EVP_des_ede3_cbc();
        case 4: // CFB Mode
            return EVP_des_cfb64();
        case 5: // Null Encryption
            return EVP_null_cipher();
        default:
            fprintf(stderr, "Invalid cipher mode\n");
            exit(EXIT_FAILURE);
    }
}

