#define BUFFER_SIZE 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populateData(NFAPI_CRC_INDICATION_PDU_T *data, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        data[i].RNTI = rand() % 10000;
        data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }
}

void createNfarxData(NFAPI_CRC_INDICATION_PDU_T **dataArray, size_t *dataCount) {
    static unsigned char buffer[BUFFER_SIZE];
    static size_t bufferSize = 0;
    static size_t dataCapacity = 0;

    if (!*dataArray || !dataCount) return;

    size_t newDataSize = (*dataCount > BUFFER_SIZE ? BUFFER_SIZE : *dataCount);

    if (bufferSize + newDataSize > BUFFER_SIZE) {
        // Resize buffer
        buffer = realloc(buffer, bufferSize + newDataSize);
        if (!buffer) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        BUFFER_SIZE += newDataSize;
    }

    NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T *)malloc(newDataSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    populateData(newData, newDataSize);
    memcpy(buffer + bufferSize, newData, newDataSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    bufferSize += newDataSize;

    if (dataCapacity < bufferSize) {
        dataCapacity = bufferSize;
        *dataArray = realloc(*dataArray, dataCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*dataArray) {
            fprintf(stderr, "Memory allocation failed\n");
            free(newData);
            return;
        }
    }

    memcpy(*dataArray, buffer, bufferSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    *dataCount = bufferSize;

    free(newData);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *dataArray = NULL;
    size_t dataCount = 0;

    createNfarxData(&dataArray, &dataCount);

    for (size_t i = 0; i < dataCount; ++i) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               dataArray[i].RX_UE_INFORMATION_TAG,
               dataArray[i].RNTI,
               dataArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    free(dataArray);
    return 0;
}
