    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        log_message("Max entries reached. Cannot add more.", log_file);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (!is_valid_rnti(entry.RNTI)) {
        char error_log[256];
        snprintf(error_log, sizeof(error_log), "Invalid RNTI: %u", entry.RNTI);
        log_message(error_log, log_file);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->entries[list->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries[list->count]) {
        log_message("Memory allocation failed.", log_file);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    memcpy(list->entries[list->count], &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;

    char success_log[256];
    snprintf(success_log, sizeof(success_log), "Added entry with RNTI: %u", entry.RNTI);
    log_message(success_log, log_file);

    pthread_mutex_unlock(&list->lock);
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]);
    }

    memset(list, 0, sizeof(DynamicList));

    pthread_mutex_unlock(&list->lock);
}

void initialize_list(DynamicList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

// Test function
void test_add_entry(DynamicList *list, const char *log_file) {
    NFAPI_CRC_INDICATION_PDU_T entry;

    // Simulating random RNTI and CRCFLAG
    for (int i = 0; i < 10500; ++i) {  // Exceeding max to test limit
        entry.RX_UE_INFORMATION_TAG = rand();
        entry.RNTI = (rand() % (RNTI_MAX + 1)) | 1;  // Ensure non-zero RNTI
        entry.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_entry(list, entry, log_file);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_file = argv[1];
    DynamicList list;

    initialize_list(&list);

    test_add_entry(&list, log_file);

    free_list(&list);

    return 0;
}
