        free(final_list);  // If this was previously allocated before failure
        pthread_mutex_unlock(&config.lock);
        return NULL;
    }

    memcpy(final_list, list, total_entries * entry_size);

    pthread_mutex_lock(&config.lock);
    free(list); // Free the temporary allocation
    pthread_mutex_unlock(&config.lock);

    return final_list;
