#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <getopt.h>

// Function declarations
void handle_command(int argc, char *argv[]);
void encrypt(const unsigned char *plaintext, int plaintext_len,
             const unsigned char *key, const unsigned char *iv,
             int cipher_mode);
void decrypt(const unsigned char *ciphertext, int ciphertext_len,
             const unsigned char *key, const unsigned char *iv,
             int cipher_mode);

// Configuration structure
typedef struct {
    const EVP_CIPHER *cipher;
    const unsigned char *key;
    size_t key_length;
    const unsigned char *iv;
    size_t iv_length;
} Config;

Config config = {EVP_aes_256_cbc(), NULL, 32, NULL, 16};

// Logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

int main(int argc, char *argv[]) {
    handle_command(argc, argv);
    return 0;
}

void handle_command(int argc, char *argv[]) {
    int opt, option_index = 0;
    static struct option long_options[] = {
        {"encrypt", no_argument, NULL, 'e'},
        {"decrypt", no_argument, NULL, 'd'},
        {"key", required_argument, NULL, 'k'},
        {"iv", required_argument, NULL, 'i'},
        {"config", required_argument, NULL, 'c'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "edk:i:c:", long_options, &option_index)) != -1) {
        switch (opt) {
            case 'e':
                // Encryption logic
                break;
            case 'd':
                // Decryption logic
                break;
            case 'k':
                config.key = (unsigned char *)malloc(strlen(optarg));
                strncpy((char *)config.key, optarg, strlen(optarg));
                config.key_length = strlen(optarg);
                break;
            case 'i':
                config.iv = (unsigned char *)malloc(strlen(optarg));
                strncpy((char *)config.iv, optarg, strlen(optarg));
                config.iv_length = strlen(optarg);
                break;
            case 'c':
                // Load configuration from file
                break;
        }
    }

    if (optind < argc) {
        const unsigned char *data = (unsigned char *)argv[optind];
        int data_len = strlen((char *)data);

        if (strcmp(argv[1], "encrypt") == 0) {
            encrypt(data, data_len, config.key, config.iv, EVP_CIPHER_iv_length(config.cipher));
        } else if (strcmp(argv[1], "decrypt") == 0) {
            decrypt(data, data_len, config.key, config.iv, EVP_CIPHER_iv_length(config.cipher));
        }
    }

    // Free resources
    free((void *)config.key);
    free((void *)config.iv);
}

void encrypt(const unsigned char *plaintext, int plaintext_len,
             const unsigned char *key, const unsigned char *iv, int iv_length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handleErrors();

    int len;
    unsigned char ciphertext[1024];
    unsigned char tag[EVP_MAX_MD_SIZE];

    if (1 != EVP_EncryptInit_ex(ctx, config.cipher, NULL, key, iv))
        handleErrors();

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        handleErrors();
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        handleErrors();
    ciphertext_len += len;

    if (1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, sizeof(tag), tag))
        handleErrors();

    log_message("Encryption completed");

    EVP_CIPHER_CTX_free(ctx);
}

void decrypt(const unsigned char *ciphertext, int ciphertext_len,
             const unsigned char *key, const unsigned char *iv, int iv_length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handleErrors();

    int len;
    unsigned char plaintext[1024];

    if (1 != EVP_DecryptInit_ex(ctx, config.cipher, NULL, key, iv))
        handleErrors();

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        handleErrors();
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        handleErrors();
    plaintext_len += len;

    log_message("Decryption completed");

    EVP_CIPHER_CTX_free(ctx);
}

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}
