void init_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint32_t tag, uint16_t rnti) {
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
BatchList* create_nfa_pi_list(size_t count, uint32_t (*tag_func)(void), uint16_t (*rnti_func)(void)) {
    pthread_mutex_lock(&lock);

    BatchList *batch = malloc(sizeof(BatchList));
    if (!batch) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    batch->data = calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!batch->data) {
        free(batch);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    batch->count = count;

    for (size_t i = 0; i < count; ++i) {
        uint32_t tag = tag_func();
        uint16_t rnti = rnti_func();
        init_pdu(&batch->data[i], tag, rnti);
    }

    pthread_mutex_unlock(&lock);

    return batch;
}

// Function to free the list
void free_nfa_pi_list(BatchList *batch) {
    if (batch) {
        if (batch->data) {
            free(batch->data);
        }
        free(batch);
    }
}

// Simple checksum function for data integrity
uint32_t calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *data, size_t count) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += data[i].RX_UE_INFORMATION_TAG;
        checksum += data[i].RNTI;
        checksum += data[i].CRC_INDICATION_REL8_TAG.CRCFLAG;
    }
    return checksum;
}

// Example usage
uint32_t example_tag_func(void) { return rand(); }
uint16_t example_rnti_func(void) { return rand() % 65536; }

int main() {
    srand(time(NULL));

    size_t list_size = 10;
    BatchList *list = create_nfa_pi_list(list_size, example_tag_func, example_rnti_func);

    if (list) {
        uint32_t checksum = calculate_checksum(list->data, list->count);
        printf("Checksum: %u\n", checksum);

        free_nfa_pi_list(list);
    } else {
        fprintf(stderr, "Failed to create list.\n");
    }

    return 0;
}
```

### Key Points:
- **Concurrency**: Uses a mutex to ensure thread safety.
- **Memory Management**: Allocates memory for the batch and individual PDUs. Ensures proper cleanup with `free_nfa_pi_list`.
- **Batch Processing**: Supports varying list sizes by parameterizing the count.
- **Error Handling**: Checks for allocation failures, returning `NULL` if unable to allocate.
- **Data Integrity**: Provides a checksum function for verifying data integrity post-population.
- **Random Data Generation**: Uses `rand()` for generating random values in PDUs.

This code is designed to be integrated into larger systems where thread safety and efficient memory usage are critical. Adjust the tag and RNTI generation functions (`example_tag_func` and `example_rnti_func`) as needed for your application context.']

['Below is a C++ program implementing a high-performance HTTP client with the described features:

```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <atomic>
#include <future>
#include <curl/curl.h>

class ServiceClient {
public:
    virtual std::string getMetadataIP(const std::string& url) = 0;
};

class MockServiceClient : public ServiceClient {
public:
    std::string getMetadataIP(const std::string& url) override {
        // Simulate network conditions
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 500 + 100));
        if (rand() % 10 < 2) { // 20% chance of failure
            throw std::runtime_error("Simulated network error");
        }
        return "192.168.1.1";
    }
};

class HttpClient {
public:
    HttpClient(size_t max_concurrent_requests, ServiceClient& client)
        : max_concurrent_requests_(max_concurrent_requests), service_client_(client) {}

    void start(const std::string& url, int interval_sec) {
        stop_ = false;
        for (size_t i = 0; i < max_concurrent_requests_; ++i) {
            workers_.emplace_back(&HttpClient::worker, this, url, interval_sec);
        }
    }

    void shutdown() {
        stop_ = true;
        cv_.notify_all();
        for (auto& worker : workers_) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

private:
    size_t max_concurrent_requests_;
    ServiceClient& service_client_;
    std::vector<std::thread> workers_;
    std::mutex queue_mutex_;
    std::condition_variable cv_;
    std::atomic<bool> stop_{false};

    void worker(const std::string& url, int interval_sec) {
        while (!stop_) {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            if (cv_.wait_for(lock, std::chrono::seconds(interval_sec), [this]() { return stop_ || active_requests_ < max_concurrent_requests_; })) {
                if (stop_) break;
                ++active_requests_;
                lock.unlock();

                auto start_time = std::chrono::high_resolution_clock::now();
                try {
                    std::string response = service_client_.getMetadataIP(url);
                    double latency = std::chrono::duration<double, std::milli>(std::chrono::high_resolution_clock::now() - start_time).count();
                    logRequest(latency, true);
                    std::cout << "Response: " << response << ", Latency: " << latency << " ms\n";
                } catch (const std::exception& e) {
                    double latency = std::chrono::duration<double, std::milli>(std::chrono::high_resolution_clock::now() - start_time).count();
                    logRequest(latency, false);
                    std::cerr << "Error: " << e.what() << ", Latency: " << latency << " ms\n";
                }

                lock.lock();
                --active_requests_;
            }
        }
    }

    void logRequest(double latency, bool success) {
        // Implement logging logic
        static std::atomic<int> total_requests{0};
        static std::atomic<int> successful_requests{0};

        ++total_requests;
        if (success) {
            ++successful_requests;
        }

        double success_rate = (double)successful_requests / total_requests * 100.0;
        std::cout << "Total Requests: " << total_requests << ", Successful: " << successful_requests << ", Success Rate: " << success_rate << "%, Latency: " << latency << " ms\n";
    }

    std::atomic<int> active_requests_{0};
};

int main() {
    MockServiceClient client;
    HttpClient http_client(5, client);

    http_client.start("http://example.com", 2);

    // Simulate running for some time
    std::this_thread::sleep_for(std::chrono::seconds(10));

    http_client.shutdown();
    return 0;
}
```

### Key Features:
- **Mock Service Client**: Simulates network conditions with latency and intermittent failures.
- **Concurrent Requests Management**: Uses a pool of threads to manage concurrent requests, ensuring the number does not exceed the limit.
- **Logging**: Tracks request metrics like latency, success rate, and errors.
- **Graceful Shutdown**: Ensures all resources are released properly upon shutdown.']

