    srand(seed);

    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t current_alloc_size = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;

    if (maxAllocSize < N * pdu_size) return NULL; // Not enough space for even one entry

    while (N > 0 && current_alloc_size + pdu_size <= maxAllocSize) {
