} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t n);
void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* array);
bool validate_unique_rntis(NFAPI_CRC_INDICATION_PDU_T* array, size_t n, unsigned int** unique_rnti_list);
NFAPI_CRC_INDICATION_PDU_T* remove_duplicates(NFAPI_CRC_INDICATION_PDU_T* array, size_t n);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t n) {
    if (n == 0 || n > 100000) return NULL;

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        array[i].ue_info.RNTI = rand() % 1000000; // Example RNTI generation
        array[i].rnti = array[i].ue_info.RNTI;
        array[i].crc_tag.CRCFLAG = rand() & 1;    // Randomly set CRCFLAG to 0 or 1
    }

    pthread_mutex_unlock(&mutex);

    unsigned int* unique_rnti_list = NULL;

    if (!validate_unique_rntis(array, n, &unique_rnti_list)) {
        free(unique_rnti_list);
        free_nfaapi_crc_indication_pdu(array);
        return allocate_and_initialize_array(n); // Retry allocation
    }

    free(unique_rnti_list);

    return array;
}

void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

bool validate_unique_rntis(NFAPI_CRC_INDICATION_PDU_T* array, size_t n, unsigned int** unique_rnti_list) {
    if (!array || !unique_rnti_list) return false;

    *unique_rnti_list = malloc(n * sizeof(unsigned int));
    if (!(*unique_rnti_list)) return false;

    size_t count = 0;
    for (size_t i = 0; i < n; ++i) {
        bool is_duplicate = false;
        for (size_t j = 0; j < count; ++j) {
            if ((*unique_rnti_list)[j] == array[i].rnti) {
                is_duplicate = true;
                break;
            }
        }

        if (!is_duplicate) {
            (*unique_rnti_list)[count++] = array[i].rnti;
        }
    }

    bool has_duplicates = count != n;
    *unique_rnti_list = realloc(*unique_rnti_list, count * sizeof(unsigned int));
    return !has_duplicates; // Return true if no duplicates
}

NFAPI_CRC_INDICATION_PDU_T* remove_duplicates(NFAPI_CRC_INDICATION_PDU_T* array, size_t n) {
    unsigned int* unique_rntis = NULL;

    if (!validate_unique_rntis(array, n, &unique_rntis)) {
        free(unique_rntis);
        return allocate_and_initialize_array(n); // Retry allocation
    }

    size_t unique_count = 0;
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = 0; j < unique_count; ++j) {
            if (unique_rntis[j] == array[i].rnti) break;
        }
        if (j == unique_count) {
            // No duplicate found, move element to new position
            memmove(&array[unique_count], &array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            ++unique_count;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* result = malloc(unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        free(array);
        return NULL; // Allocation failed
    }

    memcpy(result, array, unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    free(unique_rntis);

    free_nfaapi_crc_indication_pdu(array);

    pthread_mutex_unlock(&mutex);

    return result;
}
```

This code includes the allocation of an array with dynamically generated values for `RNTI` and `CRCFLAG`, ensures uniqueness of `RNTI`s, handles duplicates by reallocating memory without data loss, ensures thread safety using a mutex, and efficiently manages resources to avoid leaks.']

