MeasurementData* allocate_measurement_data() {
    MeasurementData *data = (MeasurementData*)malloc(sizeof(MeasurementData));
    if (!data) {
        perror("Failed to allocate measurement data");
        return NULL;
    }
    pthread_mutex_init(&data->lock, NULL);
    data->records = (NFMEASUREMENTS_RECORD_T*)calloc(INITIAL_CAPACITY, sizeof(NFMEASUREMENTS_RECORD_T));
    if (!data->records) {
        free(data);
        perror("Failed to allocate records");
        return NULL;
    }
    data->count = 0;
    data->capacity = INITIAL_CAPACITY;
    return data;
}

void resize_if_needed(MeasurementData *data) {
    if (data->count >= data->capacity) {
        size_t new_capacity = data->capacity * 2;
        NFMEASUREMENTS_RECORD_T *new_records = (NFMEASUREMENTS_RECORD_T*)realloc(data->records, new_capacity * sizeof(NFMEASUREMENTS_RECORD_T));
        if (!new_records) {
            perror("Failed to resize records");
            return;
        }
        data->records = new_records;
        data->capacity = new_capacity;
    }
}

int is_duplicate(MeasurementData *data, int cell_id) {
    for (size_t i = 0; i < data->count; ++i) {
        if (data->records[i].CELL_ID == cell_id) {
            return 1;
        }
    }
    return 0;
}

void add_measurement(MeasurementData *data, NFMEASUREMENTS_RECORD_T record) {
    pthread_mutex_lock(&data->lock);

    if (!is_duplicate(data, record.CELL_ID)) {
        resize_if_needed(data);
        data->records[data->count++] = record;
    } else {
        log_error("Duplicate CELL_ID detected and skipped.");
    }

    pthread_mutex_unlock(&data->lock);
}

void flush_to_storage(MeasurementData *data) {
    // Placeholder function for batch processing to persistent storage
    pthread_mutex_lock(&data->lock);

    if (data->count > 0) {
        printf("Flushing %zu records to storage...\n", data->count);
        data->count = 0;
    }

    pthread_mutex_unlock(&data->lock);
}

void free_measurement_data(MeasurementData *data) {
    if (data) {
        pthread_mutex_destroy(&data->lock);
        free(data->records);
        free(data);
    }
}
