}

NFAPI_CRC_INDICATION_PDU_T** allocate_crc_array(int max_elements, int *actual_size) {
    *actual_size = max_elements;
    NFAPI_CRC_INDICATION_PDU_T **array = malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        log_message("Memory allocation failed");
        return NULL;
    }

    // Populate array
    for (int i = 0; i < max_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_message("Memory allocation failed for PDU");
            break;
        }

        pdu->RX_UE_INFORMATION_TAG = rand(); // Random or valid tag
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();

        array[i] = pdu;
    }

    return array;
}

int is_unique(int *rnti_array, int size) {
    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (rnti_array[i] == rnti_array[j]) return 0;
        }
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T** ensure_unique_rntis(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    int *rnti_array = malloc(size * sizeof(int));
    if (!rnti_array) {
        log_message("Memory allocation failed for RNTI array");
        return NULL;
    }

    // Extract RNTIs
    for (int i = 0; i < size; ++i) {
        rnti_array[i] = array[i]->RNTI;
    }

    if (!is_unique(rnti_array, size)) {
        log_message("Duplicate RNTIs found. Reallocating...");

        int *unique_indices = malloc(size * sizeof(int));
        int unique_count = 0;

        for (int i = 0; i < size; ++i) {
            if (!unique_indices[rnti_array[i] % size]) { // Naive hash function
                unique_indices[rnti_array[i] % size] = 1;
                array[unique_count++] = array[i];
            }
        }

        free(unique_indices);
    }

    free(rnti_array);
    return realloc(array, unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

NFAPI_CRC_INDICATION_PDU_T** create_crc_indication_pdu(int max_elements) {
    int actual_size;
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T **array = allocate_crc_array(max_elements, &actual_size);
    if (!array) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    array = ensure_unique_rntis(array, actual_size);

    pthread_mutex_unlock(&lock);
    log_message("CRC Indication PDU array created successfully");

    return array;
}

void free_crc_array(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    for (int i = 0; i < size; ++i) {
        if (array[i]) {
            free(array[i]);
        }
    }
    free(array);
}

int main() {
    srand(time(NULL));

    int max_elements = DEFAULT_MAX_ELEMENTS;

    NFAPI_CRC_INDICATION_PDU_T **pdu_array = create_crc_indication_pdu(max_elements);

    if (!pdu_array) {
        log_message("Failed to create PDU array");
        return 1;
    }

