}

void serializeCRCList(FILE* file, CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

int addPDU(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!isValidRX_UE_INFORMATION_TAG(pdu.RX_UE_INFORMATION_TAG)) return -1;
    if (!isValidRNTI(pdu.RNTI)) return -2;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -3; // Memory allocation failure

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void clearList(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

