#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
import random

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG* crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** array;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    da->capacity = initial_capacity;
    da->count = 0;
    pthread_rwlock_init(&da->lock, NULL);
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_rwlock_wrlock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        free(da->array[i]->crc_indication_rel8_tag);
        free(da->array[i]);
    }
    free(da->array);
    pthread_rwlock_unlock(&da->lock);
    pthread_rwlock_destroy(&da->lock);
}

void adjust_capacity(DynamicArray *da, size_t new_capacity) {
    pthread_rwlock_wrlock(&da->lock);

    NFAPI_CRC_INDICATION_PDU_T** new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (new_array) {
        da->array = new_array;
        da->capacity = new_capacity;
    }

    pthread_rwlock_unlock(&da->lock);
}

void add_pdu(DynamicArray *da, uint32_t rx_ue_tag, uint16_t rnti) {
    pthread_rwlock_wrlock(&da->lock);

    if (da->count == da->capacity) {
        adjust_capacity(da, da->capacity * 2); // Double the capacity
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->RNTI = rnti;
    pdu->crc_indication_rel8_tag = malloc(sizeof(CRC_INDICATION_REL8_TAG));

    pdu->crc_indication_rel8_tag->CRCFLAG = random.randint(0, 1);

    da->array[da->count++] = pdu;

    pthread_rwlock_unlock(&da->lock);
}

void remove_pdu(DynamicArray *da, size_t index) {
    pthread_rwlock_wrlock(&da->lock);

    if (index < da->count) {
        free(da->array[index]->crc_indication_rel8_tag);
        free(da->array[index]);
        memmove(&da->array[index], &da->array[index + 1], (da->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        da->count--;
    }

    if (da->capacity > 4 && da->count <= da->capacity / 2) {
        adjust_capacity(da, da->capacity / 2); // Halve the capacity
    }

    pthread_rwlock_unlock(&da->lock);
}

// Plugin management functions can be implemented as follows:

typedef struct CRCPlugin {
    void (*create)(NFAPI_CRC_INDICATION_PDU_T*);
    void (*destroy)(CRC_INDICATION_REL8_TAG*);
} CRCPlugin;

void load_plugin(DynamicArray *da, CRCPlugin* plugin) {
    pthread_rwlock_wrlock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        plugin->create(da->array[i]);
    }
    pthread_rwlock_unlock(&da->lock);
}

void unload_plugin(DynamicArray *da, CRCPlugin* plugin) {
    pthread_rwlock_wrlock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        plugin->destroy(da->array[i]->crc_indication_rel8_tag);
    }
    pthread_rwlock_unlock(&da->lock);
}

// Garbage collection configuration can be implemented as follows:

#define GC_THRESHOLD_HIGH 0.75
#define GC_THRESHOLD_LOW 0.25

void garbage_collect(DynamicArray *da) {
    pthread_rwlock_wrlock(&da->lock);

    size_t free_count = 0;
    for (size_t i = 0; i < da->count; ++i) {
        // Implement condition to identify if an element is eligible for deletion
        if (random.random() > GC_THRESHOLD_HIGH) { 
            remove_pdu(da, i);
            --i;
        }
    }

    if ((double)da->count / da->capacity < GC_THRESHOLD_LOW) {
        adjust_capacity(da, da->capacity / 2); // Halve the capacity
    }

    pthread_rwlock_unlock(&da->lock);
}

// Detailed logging implementation

void log_operation(const char* operation, const char* detail) {
    printf("Operation: %s - Detail: %s\n", operation, detail);
}
