NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_pdus(int n) {
    if (n < 1 || n > 10000) {
        fprintf(stderr, "Number of structures must be between 1 and 10,000.\n");
        return NULL;
    }

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Seed the random number generator for consistent results
    srand(time(NULL));

    uint16_t used_rntis = 0;
    for (int i = 0; i < n; ++i) {
        // Ensure unique RX_UE_INFORMATION_TAG and RNTI
        pdus[i].rx_ue_information_tag.RNTI = used_rntis++;
        pdus[i].rnti = used_rntis;

        // Set CRCFLAG randomly but consistently for same input parameters
        static uint8_t crcflag_seed = rand();  // Seed based on initial call to ensure consistency
        pdus[i].crc_indication_rel8_tag.CRCFLAG = (rand_r(&crcflag_seed) % 256);
    }

    return pdus;
}

