        if (new_capacity > max_elements) new_capacity = max_elements;

        record_t *temp_records = realloc(array->records, new_capacity * sizeof(record_t));
        if (temp_records == NULL) return; // Handle memory allocation failure

        array->records = temp_records;
        array->capacity = new_capacity;
    }

    pthread_rwlock_unlock(&array->lock);
}

// Plugin management
typedef struct {
    DataManipulationPlugin **plugins;
    size_t plugin_count;
} PluginManager;

void load_plugin(PluginManager *manager, DataManipulationPlugin *plugin) {
    manager->plugins = realloc(manager->plugins, (manager->plugin_count + 1) * sizeof(DataManipulationPlugin *));
    if (manager->plugins == NULL) return; // Handle memory allocation failure

    manager->plugins[manager->plugin_count] = plugin;
    manager->plugin_count++;
}

void unload_plugin(PluginManager *manager, size_t index) {
    if (index < manager->plugin_count) {
        free(manager->plugins[index]);
        for (size_t i = index; i < manager->plugin_count - 1; ++i) {
            manager->plugins[i] = manager->plugins[i + 1];
        }

        manager->plugins = realloc(manager->plugins, (manager->plugin_count - 1) * sizeof(DataManipulationPlugin *));
    }
}

// Execute a plugin's function on the record array
void execute_plugin(PluginManager *manager, RecordArray *array, const char *name) {
    pthread_rwlock_rdlock(&array->lock);

    for (size_t i = 0; i < manager->plugin_count; ++i) {
        if (/* check plugin name */) {
            manager->plugins[i]->execute(array, name);
        }
    }

    pthread_rwlock_unlock(&array->lock);
}

// Clean up resources
void cleanup_record_array(RecordArray *array) {
    free(array->records);
    pthread_rwlock_destroy(&array->lock);
}

// Main function to demonstrate usage
int main() {
    RecordArray array;
    initialize_record_array(&array, 10, 0, 100);

    PluginManager manager = {NULL, 0};
    // Assume load_plugin and unload_plugin are called appropriately

    execute_plugin(&manager, &array, "sort");

    cleanup_record_array(&array);
    return 0;
}
```

This C code defines a dynamic array of `record_t` structures that can be manipulated using plugins. It supports thread-safe operations with read-write locks and provides mechanisms for loading/unloading plugins dynamically. The system is designed to handle resource constraints, adjusting capacity based on defined thresholds.']

