void* generate_nfa_api_list(size_t num_elements, int (*get_rnti)(size_t), int (*get_rx_ue_info_tag)(size_t)) {
    if (num_elements == 0 || !get_rnti || !get_rx_ue_info_tag) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    EVP_CIPHER_CTX** cipher_contexts = calloc(num_elements, sizeof(EVP_CIPHER_CTX*));

    if (!list || !cipher_contexts) {
        free(list);
        free(cipher_contexts);
        return NULL;
    }

    threading.Lock ciphers_lock;
    ciphers_lock.acquire();

    for (size_t i = 0; i < num_elements; ++i) {
        list[i].RX_UE_INFORMATION_TAG = get_rx_ue_info_tag(i);
        if (list[i].RX_UE_INFORMATION_TAG == -1) {
            fprintf(stderr, "Error obtaining RX UE Information Tag\n");
            continue;
        }

        unsigned long rnti = get_rnti(i);
        if (rnti == 0) {
            fprintf(stderr, "Error obtaining RNTI\n");
            continue;
        }

        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Example generation
        list[i].CRCFLAG = rand() % 2;

        cipher_contexts[i] = EVP_CIPHER_CTX_new();
        if (!cipher_contexts[i]) {
            fprintf(stderr, "Error initializing cipher context\n");
            continue;
        }

        int cipher_mode = rand() % 5; // Randomly select one of the five modes
        EVP_CIPHER* cipher = NULL;

        switch (cipher_mode) {
            case 0:
                cipher = EVP_des_ede3_ecb();
                break;
            case 1:
                cipher = EVP_des_ede3_cfb64();
                break;
            case 2:
                cipher = EVP_des_ede3();
                break;
            case 3:
                cipher = EVP_des_ede_cfb64();
                break;
            case 4:
                cipher = EVP_des_ecb();
                break;
            default:
                fprintf(stderr, "Error selecting cipher mode\n");
                continue;
        }

        if (!cipher) {
            EVP_CIPHER_CTX_free(cipher_contexts[i]);
            cipher_contexts[i] = NULL;
            continue;
        }

        if (EVP_EncryptInit_ex(cipher_contexts[i], cipher, NULL, NULL, NULL) != 1) {
            fprintf(stderr, "Error initializing encryption\n");
            EVP_CIPHER_CTX_free(cipher_contexts[i]);
            cipher_contexts[i] = NULL;
            continue;
        }
    }

    ciphers_lock.release();

    return list; // Caller responsible for freeing resources
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T* list, size_t num_elements, EVP_CIPHER_CTX** contexts) {
    if (!list || !contexts) return;

    threading.Lock ciphers_lock;
    ciphers_lock.acquire();

    for (size_t i = 0; i < num_elements; ++i) {
        if (contexts[i]) {
            EVP_CIPHER_CTX_free(contexts[i]);
        }
    }

    free(list);
    free(contexts);

    ciphers_lock.release();
}
