    LTE_PDCP_RX_SDU_T* array;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->capacity = initial_capacity;
    da->count = 0;

    pthread_mutex_init(&da->lock, NULL);

    da->array = (LTE_PDCP_RX_SDU_T*)aligned_alloc(16, sizeof(LTE_PDCP_RX_SDU_T) * initial_capacity);
    if (!da->array) {
        free(da->array);
        pthread_mutex_destroy(&da->lock);
        free(da);
        return NULL;
    }

    return da;
}

void free_dynamic_array(DynamicArray* da) {
    for (size_t i = 0; i < da->count; ++i) {
        free(da->array[i].tdata.data_buffer);
    }
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

int expand_dynamic_array(DynamicArray* da, size_t new_capacity) {
    LTE_PDCP_RX_SDU_T* new_array = (LTE_PDCP_RX_SDU_T*)aligned_alloc(16, sizeof(LTE_PDCP_RX_SDU_T) * new_capacity);
    if (!new_array) return -1;

    for (size_t i = 0; i < da->count; ++i) {
        memcpy(&new_array[i], &da->array[i], sizeof(LTE_PDCP_RX_SDU_T));
    }

    free(da->array);
    da->array = new_array;
    da->capacity = new_capacity;

    return 0;
}

int add_element(DynamicArray* da, LTE_PDCP_RX_SDU_HEADER_T header, size_t data_length) {
    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        int status = expand_dynamic_array(da, da->capacity * 2);
        if (status != 0) {
            pthread_mutex_unlock(&da->lock);
            return -1;
        }
    }

    LTE_PDCP_RX_SDU_T* element = &da->array[da->count++];
    element->header = header;

    for (int retries = 0; retries < MAX_RETRIES; ++retries) {
        element->tdata.data_buffer = (uint8_t*)malloc(data_length);
        if (element->tdata.data_buffer) break;

        fprintf(stderr, "Memory allocation failed, retrying...\n");
        sleep(1); // Backoff strategy
    }

    if (!element->tdata.data_buffer) {
        pthread_mutex_unlock(&da->lock);
        return -1; 
    }

    element->tdata.data_length = data_length;
    memset(element->tdata.data_buffer, 0, data_length);

    pthread_mutex_unlock(&da->lock);
    return 0;
}

void iterate_array(DynamicArray* da, void (*callback)(LTE_PDCP_RX_SDU_T*)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        callback(&da->array[i]);
    }

    pthread_mutex_unlock(&da->lock);
}

void serialize_array(DynamicArray* da, FILE* file) {
    fwrite(&da->capacity, sizeof(size_t), 1, file);
    fwrite(&da->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < da->count; ++i) {
        fwrite(&da->array[i], sizeof(LTE_PDCP_RX_SDU_T), 1, file);
    }
}

void deserialize_array(DynamicArray* da, FILE* file) {
    fread(&da->capacity, sizeof(size_t), 1, file);
    fread(&da->count, sizeof(size_t), 1, file);

    da->array = (LTE_PDCP_RX_SDU_T*)aligned_alloc(16, sizeof(LTE_PDCP_RX_SDU_T) * da->capacity);

    for (size_t i = 0; i < da->count; ++i) {
        fread(&da->array[i], sizeof(LTE_PDCP_RX_SDU_T), 1, file);

        if (da->array[i].tdata.data_length > 0) {
            da->array[i].tdata.data_buffer = (uint8_t*)malloc(da->array[i].tdata.data_length);
            fread(da->array[i].tdata.data_buffer, sizeof(uint8_t), da->array[i].tdata.data_length, file);
        }
    }
}
