#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NOTIFICATIONS_PER_SECOND 10000000
#define MAX_UES 10000

typedef struct {
    unsigned long timestamp;
    unsigned int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t retention_time;  // Time after which entry is considered outdated
    struct Entry *next;
} Entry;

typedef struct {
    Entry *head;
    pthread_mutex_t lock;
    unsigned int retention_period_seconds;  // Configurable retention period in seconds
} CRCManager;

CRCManager crc_manager = {NULL, PTHREAD_MUTEX_INITIALIZER, 60};

// Function to create a new entry
Entry* create_entry(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Entry *entry = (Entry *)malloc(sizeof(Entry));
    if (!entry) return NULL;
    entry->pdu = pdu;
    entry->retention_time = time(NULL) + crc_manager.retention_period_seconds;
    entry->next = NULL;
    return entry;
}

// Function to add a new entry
void add_entry(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&crc_manager.lock);

    Entry *entry = create_entry(pdu);
    if (!entry) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&crc_manager.lock);
        return;
    }

    entry->next = crc_manager.head;
    crc_manager.head = entry;

    pthread_mutex_unlock(&crc_manager.lock);
}

// Function to remove outdated entries
void remove_outdated_entries() {
    pthread_mutex_lock(&crc_manager.lock);

    Entry **current = &crc_manager.head;
    time_t now = time(NULL);

    while (*current) {
        if ((*current)->retention_time <= now) {
            Entry *old_entry = *current;
            *current = old_entry->next;
            free(old_entry);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&crc_manager.lock);
}

// Function to retrieve entries for a specific RNTI within a time range
void* get_entries_for_rnti(unsigned int rnti, time_t start_time, time_t end_time, Entry **results) {
    pthread_mutex_lock(&crc_manager.lock);

    *results = NULL;
    Entry **current_result = results;

    for (Entry *entry = crc_manager.head; entry != NULL; entry = entry->next) {
        if (entry->pdu.crc_tag.RNTI == rnti &&
            entry->retention_time > start_time &&
            entry->retention_time < end_time) {

            Entry *new_entry = create_entry(entry->pdu);
            if (!new_entry) break;

            *current_result = new_entry;
            current_result = &new_entry->next;
        }
    }

    pthread_mutex_unlock(&crc_manager.lock);
    return NULL;
}

// Function to configure retention period
void set_retention_period(unsigned int seconds) {
    pthread_mutex_lock(&crc_manager.lock);

    crc_manager.retention_period_seconds = seconds;

    pthread_mutex_unlock(&crc_manager.lock);
}

// Cleanup function to free all entries and resources
void cleanup_crc_manager() {
    pthread_mutex_lock(&crc_manager.lock);

    Entry *entry;
    while (crc_manager.head) {
        entry = crc_manager.head;
        crc_manager.head = entry->next;
        free(entry);
    }

    pthread_mutex_unlock(&crc_manager.lock);
}
```

### Key Considerations:

- **Concurrency**: Uses `pthread_mutex_t` to ensure thread safety when accessing/modifying the list of entries.
- **Memory Management**: Dynamically allocates and frees memory for each entry. The cleanup function ensures no memory leaks.
- **Scalability**: Efficiently handles large numbers of notifications using a linked list structure, with minimal locking time.
- **Configuration Flexibility**: Provides an API to set retention periods dynamically.
- **Error Handling**: Includes basic error handling for memory allocation failures and logs errors to `stderr`.

This implementation should be integrated within a larger system that handles external dependencies like cell identifier mappings.']

