#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ENTRIES 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;  // for thread safety
} CRCIndicationList;

// Function to generate a random number
static inline uint8_t random_crc_flag() {
    return rand() % 2;  // Randomly returns 0 or 1
}

// Initialize the list
void init_CRC_Indication_List(CRCIndicationList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->count = 0;
}

// Add a new entry to the list
int add_entry(CRCIndicationList* list) {
    if (pthread_mutex_lock(&list->lock)) return -1;

    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -2;  // Indicate that the maximum number of entries has been reached
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3;  // Memory allocation failure
    }

    new_node->data.RX_UE_INFORMATION_TAG = rand();  // Randomly set tag
    new_node->data.RNTI = rand() % 65536;           // Randomly set RNTI
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = random_crc_flag();

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

// Reset the list
void reset_CRC_Indication_List(CRCIndicationList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

// Free the entire list
void free_CRC_Indication_List(CRCIndicationList* list) {
    reset_CRC_Indication_List(list);
    pthread_mutex_destroy(&list->lock);
}

// Example serialization function (details omitted)
size_t serialize_CRC_Indication_List(const CRCIndicationList* list, uint8_t** buffer) {
    size_t size = 0;
    Node* current = list->head;

    if (!current) return 0; // Empty list

    pthread_mutex_lock(&list->lock);

    while (current) {
        // Calculate the required buffer size for serialization
        size += sizeof(current->data.RX_UE_INFORMATION_TAG)
               + sizeof(current->data.RNTI)
               + sizeof(current->data.CRC_INDICATION_REL8_TAG);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    *buffer = (uint8_t*)malloc(size);
    if (!*buffer) return 0;

    size_t offset = 0;
    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current) {
        memcpy(*buffer + offset, &current->data.RX_UE_INFORMATION_TAG, sizeof(current->data.RX_UE_INFORMATION_TAG));
        offset += sizeof(current->data.RX_UE_INFORMATION_TAG);

        memcpy(*buffer + offset, &current->data.RNTI, sizeof(current->data.RNTI));
        offset += sizeof(current->data.RNTI);

        memcpy(*buffer + offset, &current->data.CRC_INDICATION_REL8_TAG, sizeof(current->data.CRC_INDICATION_REL8_TAG));
        offset += sizeof(current->data.CRC_INDICATION_REL8_TAG);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return size;
}

// Example deserialization function (details omitted)
void deserialize_CRC_Indication_List(CRCIndicationList* list, const uint8_t* buffer, size_t size) {
    reset_CRC_Indication_List(list);

    size_t offset = 0;
    while (offset < size) {
        if (add_entry(list) != 0) break; // Handle error

        Node* current = list->head;
        while (current && current->next) current = current->next;

        memcpy(&current->data.RX_UE_INFORMATION_TAG, buffer + offset, sizeof(current->data.RX_UE_INFORMATION_TAG));
        offset += sizeof(current->data.RX_UE_INFORMATION_TAG);

        memcpy(&current->data.RNTI, buffer + offset, sizeof(current->data.RNTI));
        offset += sizeof(current->data.RNTI);

        memcpy(&current->data.CRC_INDICATION_REL8_TAG, buffer + offset, sizeof(current->data.CRC_INDICATION_REL8_TAG));
        offset += sizeof(current->data.CRC_INDICATION_REL8_TAG);
    }
}

// Example unit test (simplified)
void test_CRC_Indication_List() {
    CRCIndicationList list;
    init_CRC_Indication_List(&list);

    for (size_t i = 0; i < MAX_ENTRIES + 10; ++i) { // Test adding beyond max entries
        int result = add_entry(&list);
        if (result == -2 && i == MAX_ENTRIES) {
            printf("Max entry limit test passed.\n");
        }
    }

    uint8_t* serialized_data;
    size_t data_size = serialize_CRC_Indication_List(&list, &serialized_data);

    CRCIndicationList new_list;
    init_CRC_Indication_List(&new_list);
    deserialize_CRC_Indication_List(&new_list, serialized_data, data_size);

    printf("Serialized and deserialized %zu entries successfully.\n", list.count);

    free(serialized_data);
    free_CRC_Indication_List(&list);
    free_CRC_Indication_List(&new_list);
}

int main() {
    test_CRC_Indication_List();
    return 0;
}
