#define MAX_BUFFER_SIZE 1024
#define DEFAULT_BATCH_SIZE 10

typedef enum {
    STATUS_OK,
    STATUS_ERROR_MEMORY,
    STATUS_ERROR_FILE,
    STATUS_ERROR_FORMAT,
    STATUS_ERROR_CRC
} Status;

typedef struct {
    int rnti;
    int crcflag; // CRCFLAG to be validated
    uint8_t data[MAX_BUFFER_SIZE]; // Example data field for CRC information
