Status load_resource_bundle(const char *file_path, NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t *total_items) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) {
        log_debug("Error: Unable to open file.");
        return handle_error(STATUS_ERROR_FILE);
    }

    // Determine batch processing size and memory alignment settings.
    int batch_size = DEFAULT_BATCH_SIZE;
    size_t buffer_size;
    Status status = STATUS_OK;

    *pdu_list = NULL;
    *total_items = 0;

    while (!feof(fp)) {
        buffer_size = fread(NULL, 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), fp); // Determine the file block size
        if (buffer_size <= 0) break;

        NFAPI_CRC_INDICATION_PDU_T *temp_list = realloc(*pdu_list, (*total_items + batch_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_list) {
            log_debug("Error: Memory allocation failed.");
            status = handle_error(STATUS_ERROR_MEMORY);
            break;
        }
        *pdu_list = temp_list;

        for (int i = 0; i < batch_size && !feof(fp); ++i, (*total_items)++) {
            buffer_size = fread(&(*pdu_list)[*total_items], 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), fp);

            if (buffer_size != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
                // Handle partial or corrupted read
                *total_items -= i;
                status = handle_error(STATUS_ERROR_FORMAT);
                break;
            }

            if (!validate_crcflag((*pdu_list)[*total_items].crcflag)) {
                log_debug("Error: CRCFLAG validation failed.");
                status = handle_error(STATUS_ERROR_CRC);
                break;
            }
        }

        if (status != STATUS_OK) break; // Stop processing on error
    }

    fclose(fp);

    return status;
}

// Implementations for auxiliary functions.
