}

void log_debug(const char *message) {
    printf("[DEBUG] %s\n", message);
}

Status handle_error(Status status) {
    switch (status) {
        case STATUS_ERROR_MEMORY:
            printf("Memory allocation error occurred.\n");
            break;
        case STATUS_ERROR_FILE:
            printf("File operation error occurred.\n");
            break;
        case STATUS_ERROR_FORMAT:
