#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERFACES 10000

typedef struct {
    int uid;
    unsigned long packet_count;
    unsigned long byte_count;
    double error_rate; // as a percentage, e.g., 0.5 for 0.5%
    time_t timestamp;
} NetworkInterfaceStats;

typedef struct {
    NetworkInterfaceStats *interfaces;
    size_t count;
} StatsArray;

// Function to initialize the stats array
void init_stats_array(StatsArray *stats) {
    stats->interfaces = (NetworkInterfaceStats *)malloc(MAX_INTERFACES * sizeof(NetworkInterfaceStats));
    if (!stats->interfaces) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    stats->count = 0;
}

// Function to find an interface by UID
int* find_interface(StatsArray *stats, int uid) {
    for (size_t i = 0; i < stats->count; ++i) {
        if (stats->interfaces[i].uid == uid) {
            return &stats->interfaces[i];
        }
    }
    return NULL;
}

// Function to add or update an interface entry
void update_interface(StatsArray *stats, int uid, unsigned long packet_count, 
                      unsigned long byte_count, double error_rate, time_t timestamp) {
    NetworkInterfaceStats *interface = find_interface(stats, uid);
    if (interface == NULL) {
        // Add new entry if not found and there's space
        if (stats->count < MAX_INTERFACES) {
            interface = &stats->interfaces[stats->count++];
        } else {
            fprintf(stderr, "Max interfaces reached\n");
            return;
        }
    }

    interface->uid = uid;
    interface->packet_count = packet_count;
    interface->byte_count = byte_count;
    interface->error_rate = error_rate;
    interface->timestamp = timestamp;
}

// Function to calculate aggregate statistics
void calculate_aggregates(StatsArray *stats, unsigned long *total_packets, 
                          unsigned long *total_bytes, double *average_error_rate) {
    if (stats->count == 0) {
        *total_packets = 0;
        *total_bytes = 0;
        *average_error_rate = 0.0;
        return;
    }

    *total_packets = 0;
    *total_bytes = 0;
    double total_error_rate_sum = 0.0;

    for (size_t i = 0; i < stats->count; ++i) {
        (*total_packets) += stats->interfaces[i].packet_count;
        (*total_bytes) += stats->interfaces[i].byte_count;
        total_error_rate_sum += stats->interfaces[i].error_rate * stats->interfaces[i].packet_count;
    }

    *average_error_rate = total_error_rate_sum / (double)(*total_packets);
}

// Function to free allocated memory
void free_stats_array(StatsArray *stats) {
    free(stats->interfaces);
    stats->count = 0;
}

int main() {
    StatsArray stats;
    init_stats_array(&stats);

    // Example usage
    update_interface(&stats, 1, 100, 2000, 0.5, time(NULL));
    update_interface(&stats, 2, 150, 3000, 0.3, time(NULL));

    unsigned long total_packets;
    unsigned long total_bytes;
    double average_error_rate;

    calculate_aggregates(&stats, &total_packets, &total_bytes, &average_error_rate);

    printf("Total Packets: %lu\n", total_packets);
    printf("Total Bytes: %lu\n", total_bytes);
    printf("Average Error Rate: %.2f%%\n", average_error_rate * 100.0);

    free_stats_array(&stats);

    return 0;
}
