// Define the structure for network interface statistics
typedef struct {
    int uid;
    unsigned long packet_count;
    unsigned long byte_count;
    float error_rate;  // As a percentage
    time_t timestamp;
} NetworkInterfaceStats;

#define MAX_INTERFACES 10000

// Dynamic array to store network interface stats
NetworkInterfaceStats* iface_stats = NULL;
size_t current_size = 0;

// Function prototypes
void init_iface_stats();
int add_or_update_iface_stat(int uid, unsigned long packets, unsigned long bytes, float error_rate);
void calculate_aggregate_statistics(unsigned long* total_packets, unsigned long* total_bytes, float* avg_error_rate);
NetworkInterfaceStats* find_iface_by_uid(int uid);
char* serialize_to_json(NetworkInterfaceStats* stats);
NetworkInterfaceStats* deserialize_from_json(const char* json);

// Initialize the dynamic array
void init_iface_stats() {
    iface_stats = malloc(MAX_INTERFACES * sizeof(NetworkInterfaceStats));
    if (iface_stats == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Add or update an entry in the dynamic array
int add_or_update_iface_stat(int uid, unsigned long packets, unsigned long bytes, float error_rate) {
    NetworkInterfaceStats* iface = find_iface_by_uid(uid);

    if (iface == NULL && current_size < MAX_INTERFACES) {
        iface = &iface_stats[current_size++];
    }

    if (iface != NULL) {
        iface->uid = uid;
        iface->packet_count = packets;
        iface->byte_count = bytes;
        iface->error_rate = error_rate;
        iface->timestamp = time(NULL);
        return 1; // Success
    }

    return 0; // Failure or max capacity reached
}

// Find an entry by UID
NetworkInterfaceStats* find_iface_by_uid(int uid) {
    for (size_t i = 0; i < current_size; ++i) {
        if (iface_stats[i].uid == uid) {
            return &iface_stats[i];
        }
    }
    return NULL;
}

// Calculate aggregate statistics
void calculate_aggregate_statistics(unsigned long* total_packets, unsigned long* total_bytes, float* avg_error_rate) {
    unsigned long sum_packets = 0;
    unsigned long sum_bytes = 0;
    float sum_error_rates = 0.0;
    int count = 0;

    for (size_t i = 0; i < current_size; ++i) {
        if (iface_stats[i].packet_count > 0) { // Only consider active interfaces
            sum_packets += iface_stats[i].packet_count;
            sum_bytes += iface_stats[i].byte_count;
            sum_error_rates += iface_stats[i].error_rate;
            count++;
        }
    }

    *total_packets = sum_packets;
    *total_bytes = sum_bytes;

    if (count > 0) {
        *avg_error_rate = sum_error_rates / count;
    } else {
        *avg_error_rate = 0.0f; // No active interfaces
    }
}

// Serialize a NetworkInterfaceStats to JSON string
char* serialize_to_json(NetworkInterfaceStats* stats) {
    char* json = malloc(256);
    if (json == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    snprintf(json, 256, "{\"uid\":%d,\"packet_count\":%lu,\"byte_count\":%lu,"
               "\"error_rate\":%.2f,\"timestamp\":%ld}",
             stats->uid, stats->packet_count, stats->byte_count, stats->error_rate, (long)stats->timestamp);

    return json;
}

// Deserialize JSON string to NetworkInterfaceStats
NetworkInterfaceStats* deserialize_from_json(const char* json) {
    NetworkInterfaceStats* stats = malloc(sizeof(NetworkInterfaceStats));
    if (stats == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    sscanf(json, "{\"uid\":%d,\"packet_count\":%lu,\"byte_count\":%lu,"
            "\"error_rate\":%.2f,\"timestamp\":%ld}",
           &stats->uid, &stats->packet_count, &stats->byte_count,
           &stats->error_rate, (long*)&stats->timestamp);

    return stats;
}

// Example usage
int main() {
    init_iface_stats();

    add_or_update_iface_stat(1, 1000, 500000, 0.01);
    unsigned long total_packets = 0, total_bytes = 0;
    float avg_error_rate = 0.0f;

    calculate_aggregate_statistics(&total_packets, &total_bytes, &avg_error_rate);

    printf("Total Packets: %lu\n", total_packets);
    printf("Total Bytes: %lu\n", total_bytes);
    printf("Average Error Rate: %.2f%%\n", avg_error_rate * 100);

    char* json = serialize_to_json(&iface_stats[0]);
    printf("Serialized JSON: %s\n", json);
    free(json);

    NetworkInterfaceStats* new_iface = deserialize_from_json("{\"uid\":2,\"packet_count\":2000,"
                                                            "\"byte_count\":700000,\"error_rate\":0.02,"
                                                            "\"timestamp\":1682540804}");
    printf("Deserialized UID: %d, Packets: %lu\n", new_iface->uid, new_iface->packet_count);
    free(new_iface);

    // Clean up
    free(iface_stats);
    return 0;
}
```

This implementation manages network interface statistics using a dynamic array. It includes functions to add or update entries, calculate aggregate statistics, and serialize/deserialize data to/from JSON strings. The code is designed for efficient memory management and performance with up to 10,000 network interfaces.']

