#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int value;
} record;

typedef struct hash_node {
    int key;
    record rec;
    struct hash_node* next;
} hash_node;

typedef struct {
    hash_node** table;
    size_t capacity;
    pthread_mutex_t lock;
} hashtable;

void handle_memory_failure(void* ptr) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

hashtable* create_hashtable(size_t capacity) {
    hashtable* ht = malloc(sizeof(hashtable));
    handle_memory_failure(ht);

    ht->capacity = capacity;
    ht->table = calloc(capacity, sizeof(hash_node*));
    handle_memory_failure(ht->table);

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned int hash_function(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

void insert(hashtable* ht, int key, record rec) {
    unsigned int index = hash_function(key, ht->capacity);

    pthread_mutex_lock(&ht->lock);

    hash_node* new_node = malloc(sizeof(hash_node));
    handle_memory_failure(new_node);

    new_node->key = key;
    new_node->rec = rec;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;

    pthread_mutex_unlock(&ht->lock);
}

record* lookup(hashtable* ht, int key) {
    unsigned int index = hash_function(key, ht->capacity);

    pthread_mutex_lock(&ht->lock);

    for (hash_node* node = ht->table[index]; node != NULL; node = node->next) {
        if (node->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return &node->rec;
        }
    }

    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void resize_hashtable(hashtable* ht, size_t new_capacity) {
    hash_node** old_table = ht->table;
    size_t old_capacity = ht->capacity;

    ht->capacity = new_capacity;
    ht->table = calloc(new_capacity, sizeof(hash_node*));
    handle_memory_failure(ht->table);

    for (size_t i = 0; i < old_capacity; ++i) {
        hash_node* node = old_table[i];
        while (node != NULL) {
            hash_node* next_node = node->next;
            unsigned int new_index = hash_function(node->key, ht->capacity);

            node->next = ht->table[new_index];
            ht->table[new_index] = node;

            node = next_node;
        }
    }

    free(old_table);
}

void destroy_hashtable(hashtable* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        hash_node* node = ht->table[i];
        while (node != NULL) {
            hash_node* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void manage_database(size_t max_records, int value_range_min, int value_range_max) {
    size_t initial_capacity = (max_records > 10) ? max_records : 10;

    hashtable* ht = create_hashtable(initial_capacity);

    long* offsets = calloc(max_records, sizeof(long));
    handle_memory_failure(offsets);

    int* keys = malloc(max_records * sizeof(int));
    handle_memory_failure(keys);

    record* records = malloc(max_records * sizeof(record));
    handle_memory_failure(records);

    for (size_t i = 0; i < max_records; ++i) {
        offsets[i] = i;
        keys[i] = i;

        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

        insert(ht, keys[i], records[i]);

        if ((i + 1) * 100 / initial_capacity > 75) {
            resize_hashtable(ht, ht->capacity * 2);
        }
    }

    // Example lookup
    int key_to_lookup = 5;
    record* found_record = lookup(ht, key_to_lookup);
    if (found_record != NULL) {
        printf("Record for key %d: %d\n", key_to_lookup, found_record->value);
    } else {
        printf("Key %d not found.\n", key_to_lookup);
    }

    // Clean up
    destroy_hashtable(ht);
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manage_database(100, 1, 1000);
    return 0;
}
```

### Key Features:
- **Memory Management**: Uses `malloc` and `calloc` to allocate memory for various structures. Handles allocation failures gracefully.
- **Hash Table**: Implements chaining with a dynamic resizing strategy when load factor exceeds 75%.
- **Thread Safety**: Utilizes `pthread_mutex_t` to ensure thread-safe operations on the hash table.
- **Resizing Strategy**: Doubles the capacity of the hash table when needed, ensuring efficient space usage and access times.
- **Resource Cleanup**: Properly deallocates all resources at the end of execution to prevent memory leaks.']

