#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    CRC_INDICATION_REL8_TAG data;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t count;
    size_t crc_true_count;
    pthread_mutex_t lock;
} NFAPI_LIST;

NFAPI_LIST* create_list() {
    NFAPI_LIST* list = (NFAPI_LIST*)malloc(sizeof(NFAPI_LIST));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    list->crc_true_count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void append_pdu(NFAPI_LIST* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!list) return;

    CRC_INDICATION_REL8_TAG tag;
    tag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    tag.RNTI = RNTI;
    tag.CRCFLAG = rand() % 2 == 0; // Randomly set CRCFLAG

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = tag;
    new_node->next = list->head;
    list->head = new_node;

    list->count++;
    if (tag.CRCFLAG) {
        list->crc_true_count++;
    }

    pthread_mutex_unlock(&list->lock);
}

size_t get_crc_true_count(NFAPI_LIST* list) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);
    size_t count = list->crc_true_count;
    pthread_mutex_unlock(&list->lock);

    return count;
}

void cleanup_list(NFAPI_LIST* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;
    list->crc_true_count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void initialize_random() {
    srand(time(NULL));
}
```

### Explanation:

- **NFAPI_LIST Structure**: Manages the head of the linked list, a count of total elements, and a count of `CRCFLAG` set to true. A mutex lock ensures thread safety.

- **create_list Function**: Initializes a new list with its mutex lock, returning a pointer to it or NULL if allocation fails.

- **append_pdu Function**: Adds a new node to the list in a thread-safe manner, updating counts as necessary.

- **get_crc_true_count Function**: Provides a thread-safe way to retrieve the count of `CRCFLAG` set true.

- **cleanup_list Function**: Frees all allocated memory and destroys the mutex lock when the list is no longer needed.

- **initialize_random Function**: Initializes the random number generator for setting `CRCFLAG`.

This code manages dynamic memory efficiently, handles concurrency with a mutex, and provides mechanisms to ensure resource cleanup.']

