    size_t size;
    size_t capacity;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array();
int add_pdu(DynamicArray* da, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI, unsigned int CRC_INDICATION_REL8_TAG);
void free_dynamic_array(DynamicArray* da);
static void resize_if_needed(DynamicArray* da);

// Create a new dynamic array
DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = INITIAL_CAPACITY;
    return da;
}

// Add a new PDU to the dynamic array
int add_pdu(DynamicArray* da, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI, unsigned int CRC_INDICATION_REL8_TAG) {
    if (!da || da->size >= MAX_CAPACITY) return -1; // Error: Array is full or invalid

    resize_if_needed(da);

    NFAPI_CRC_INDICATION_PDU_T* new_element = &da->array[da->size++];
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

