}

// Free the dynamic array
void free_dynamic_array(DynamicArray* da) {
    if (!da) return;

    if (da->array) free(da->array);
    free(da);
}

// Resize the array if needed
static void resize_if_needed(DynamicArray* da) {
    if (da->size >= da->capacity && da->capacity < MAX_CAPACITY) {
        size_t new_capacity = da->capacity * 2;
        if (new_capacity > MAX_CAPACITY) new_capacity = MAX_CAPACITY;

        NFAPI_CRC_INDICATION_PDU_T* resized_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!resized_array) return; // Handle memory allocation failure gracefully

        da->array = resized_array;
        da->capacity = new_capacity;
    }
}

