#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
import stdlib.h>
import string.h
import time.h

// Configuration file path
#define CONFIG_FILE "config.cfg"

typedef struct {
    uint16_t rnti;
    // Other relevant fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t crc_flag;  // Randomly set CRC flag
    // Other relevant fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10000
#define MAX_LOAD_FACTOR 0.75

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

// Function declarations
HashTable* create_table(size_t capacity);
void destroy_table(HashTable* table);
size_t hash_function(uint16_t rnti, size_t capacity);
int add_pdu(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu);
int update_pdu(HashTable* table, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T new_data);
NFAPI_CRC_INDICATION_PDU_T* get_pdu(HashTable* table, uint16_t rnti);
void resize_table(HashTable* table);
size_t load_capacity_from_config();

// Create a hash table
HashTable* create_table(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

// Destroy the hash table
void destroy_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Custom hash function
size_t hash_function(uint16_t rnti, size_t capacity) {
    return (rnti * 2654435761u) % capacity;
}

// Add a PDU to the table
int add_pdu(HashTable* table, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->size / table->capacity >= MAX_LOAD_FACTOR) {
        resize_table(table);
    }

    size_t index = hash_function(pdu.rnti, table->capacity);
    Node* node = table->buckets[index];

    while (node) {
        if (node->data.rnti == pdu.rnti) {
            pthread_mutex_unlock(&table->lock);
            return -1;  // PDU with this RNTI already exists
        }
        node = node->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        fprintf(stderr, "Memory allocation failed for new node\n");
        return -1;  // Memory allocation failure
    }

    new_node->data = pdu;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    ++table->size;

    pthread_mutex_unlock(&table->lock);
    return 0;  // Success
}

// Update a PDU in the table
int update_pdu(HashTable* table, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(rnti, table->capacity);
    Node* node = table->buckets[index];

    while (node) {
        if (node->data.rnti == rnti) {
            node->data = new_data;
            pthread_mutex_unlock(&table->lock);
            return 0;  // Success
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1;  // PDU not found
}

// Retrieve a PDU from the table
NFAPI_CRC_INDICATION_PDU_T* get_pdu(HashTable* table, uint16_t rnti) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(rnti, table->capacity);
    Node* node = table->buckets[index];

    while (node) {
        if (node->data.rnti == rnti) {
            pthread_mutex_unlock(&table->lock);
            return &node->data;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;  // PDU not found
}

// Resize the hash table
void resize_table(HashTable* table) {
    size_t new_capacity = table->capacity * 2;
    Node** new_buckets = (Node**)calloc(new_capacity, sizeof(Node*));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            size_t index = hash_function(node->data.rnti, new_capacity);
            Node* next_node = node->next;
            node->next = new_buckets[index];
            new_buckets[index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Load capacity from config file
size_t load_capacity_from_config() {
    FILE* file = fopen(CONFIG_FILE, "r");
    if (!file) return INITIAL_SIZE;

    size_t capacity;
    if (fscanf(file, "%zu", &capacity) != 1) {
        fclose(file);
        return INITIAL_SIZE;  // Fallback to initial size
    }

    fclose(file);
    return capacity;
}

// Initialize the hash table with dynamic configuration
HashTable* initialize_table() {
    size_t capacity = load_capacity_from_config();
    HashTable* table = create_table(capacity);

    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
    }

    return table;
}
