// Union-Find structure and functions
typedef struct {
    int parent;
    int rank;
} UFNode;

void initializeUF(UFNode *uf, int size) {
    for (int i = 0; i < size; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

int find(UFNode *uf, int x) {
    if (uf[x].parent != x)
        uf[x].parent = find(uf, uf[x].parent);
    return uf[x].parent;
}

void unionSets(UFNode *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

bool validateTag(int tag) {
    // Placeholder for external data source validation
    return true;  // Assume all tags are valid for this example
}

int constructNFAPIDisjointList(NFAPI_CRC_INDICATION_PDU_T **list, int N) {
    if (N <= 0 || list == NULL)
        return -1;

    *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (*list == NULL)
        return -2;

    UFNode *uf = malloc(sizeof(UFNode) * (2 * N));
    initializeUF(uf, 2 * N);

    bool seenTags[N] = { false };
    bool seenRNTIs[N] = { false };

    srand(time(NULL));
    int disjointCount = 0;
    clock_t start, end;
    double creationTime = 0.0, validationTime = 0.0, ufTime = 0.0;

    for (int i = 0; i < N; ++i) {
        (*list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

        start = clock();
        int tag, rnti;
        do {
            tag = rand() % (N * 10);  // Random range for tags
        } while (!validateTag(tag) || seenTags[tag]);
        seenTags[tag] = true;

        do {
            rnti = rand() % (N * 10);  // Random range for RNTIs
        } while (seenRNTIs[rnti]);
        seenRNTIs[rnti] = true;
        end = clock();
        creationTime += ((double)(end - start)) / CLOCKS_PER_SEC;

        (*list)[i].RX_UE_INFORMATION_TAG = tag;
        (*list)[i].RNTI = rnti;

        start = clock();
        if (find(uf, tag) != find(uf, rnti)) {
            disjointCount++;
            unionSets(uf, tag, rnti);
        }
        end = clock();
        ufTime += ((double)(end - start)) / CLOCKS_PER_SEC;
    }

    // Assuming validation is done during creation
    free(uf);

    printf("Structure Creation Time: %.2f ms\n", creationTime * 1000.0);
    printf("UF Operations Time: %.2f ms\n", ufTime * 1000.0);

    return disjointCount;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int N = 100;  // Example size
    int disjointPairs = constructNFAPIDisjointList(&list, N);

    if (disjointPairs >= 0) {
        printf("Number of Disjoint Pairs: %d\n", disjointPairs);
    } else {
        printf("Error in constructing list.\n");
    }

    free(list);
    return 0;
}
