} UFData;

void UFInit(UFData *uf, int n) {
    for (int i = 0; i < n; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
        uf->active[i] = 1;
    }
}

int find(int x, UFData *uf) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf->parent[x], uf);
    return uf->parent[x];
