unsigned int fetch_RX_UE_INFORMATION_TAG();

// Thread-safe function to generate random CRCFLAG
int get_random_crcflag() {
    return rand() % 2;
}

// Error handling and recovery mechanism placeholder
void handle_error(const char* error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

EVP_CIPHER* configure_cipher(int cipher_mode) {
    EVP_CIPHER_CTX *ctx = NULL;
    EVP_CIPHER *cipher = NULL;

    switch (cipher_mode) {
        case 0:
            cipher = EVP_des_ecb();
            break;
        case 1:
            cipher = EVP_des_ede();
            break;
        case 2:
            cipher = EVP_des_ede3();
            break;
        case 3:
            cipher = EVP_des_cfb8();
            break;
        default:
            handle_error("Invalid cipher mode");
            return NULL;
    }

    if (!cipher) {
        handle_error("Failed to initialize cipher");
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        handle_error("Failed to create cipher context");
        EVP_CIPHER_free(cipher);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) {
        handle_error("Failed to initialize encryption");
        EVP_CIPHER_CTX_free(ctx);
        EVP_CIPHER_free(cipher);
        return NULL;
    }

    return ctx; // Pass context for further operations
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdu_list(int count, int cipher_mode) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        handle_error("Memory allocation failed for PDU list");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);

        pdu_list[i].RX_UE_INFORMATION_TAG = fetch_RX_UE_INFORMATION_TAG();
        pdu_list[i].RNTI = fetch_RNTI();
        memset(pdu_list[i].CRC_INDICATION_REL8_TAG, get_random_crcflag(), sizeof(pdu_list[i].CRC_INDICATION_REL8_TAG));

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);

    return pdu_list;
}

int main() {
    srand(time(NULL));

    int cipher_mode = 0; // Example: ECB mode
    EVP_CIPHER_CTX *cipher_ctx = configure_cipher(cipher_mode);
    if (!cipher_ctx) {
