        NFAPI_CRC_INDICATION_PDU_T* result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!result) {
            fprintf(stderr, "Memory allocation failed for new structures\n");
            return NULL;
        }

        // Fill with cached data
        for (int i = 0; i < available; ++i) {
            result[i] = cache[cache_count - 1 - i];
            cache[cache_count - 1 - i] = NULL;
        }
        --cache_count;

        // Initialize remaining structures
