            structures[i].CRC_INDICATION_REL8_TAG = rand() % 16;
            structures[i].CRCFLAG = (rand() & 1);
        }

        // Add unused slots to the cache if there's space
        if ((cache_count + N) <= CACHE_SIZE) {
            for (int i = 0; i < N && cache_count < CACHE_SIZE; ++i) {
                cache[cache_count++] = &structures[i];
            }
        }

        return structures;
    }
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T* structures, int N) {
