#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int cell_identity;
    // Other system information fields can be added here
} SystemInformationBlockType1;

typedef struct {
    int sib_message_id; // Generic identifier for the SIB message
    SystemInformationBlockType1 system_info;
} LTE_RRC_SIB1;

typedef struct {
    LTE_RRC_SIB1* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicSIB1Array;

DynamicSIB1Array* create_dynamic_sib1_array(size_t initial_capacity) {
    DynamicSIB1Array* dyn_array = malloc(sizeof(DynamicSIB1Array));
    if (!dyn_array) return NULL;

    dyn_array->array = calloc(initial_capacity, sizeof(LTE_RRC_SIB1));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->count = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);

    return dyn_array;
}

void destroy_dynamic_sib1_array(DynamicSIB1Array* dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        pthread_mutex_destroy(&dyn_array->lock);
        free(dyn_array);
    }
}

int resize_dynamic_sib1_array(DynamicSIB1Array* dyn_array, size_t new_capacity) {
    LTE_RRC_SIB1* new_array = realloc(dyn_array->array, new_capacity * sizeof(LTE_RRC_SIB1));
    if (!new_array) return -1;

    dyn_array->array = new_array;
    dyn_array->capacity = new_capacity;

    return 0;
}

int update_sib1_message(DynamicSIB1Array* dyn_array, int index, int cell_identity, SystemInformationBlockType1 system_info) {
    if (index >= dyn_array->count) return -1;

    pthread_mutex_lock(&dyn_array->lock);

    LTE_RRC_SIB1* sib1_msg = &dyn_array->array[index];
    sib1_msg->sib_message_id = rand(); // Generate a generic message ID
    sib1_msg->system_info.cell_identity = cell_identity;
    // Copy other system information fields here

    pthread_mutex_unlock(&dyn_array->lock);

    return 0;
}

int add_sib1_message(DynamicSIB1Array* dyn_array, int cell_identity, SystemInformationBlockType1 system_info) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->count == dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        if (resize_dynamic_sib1_array(dyn_array, new_capacity)) {
            pthread_mutex_unlock(&dyn_array->lock);
            return -1;
        }
    }

    LTE_RRC_SIB1* sib1_msg = &dyn_array->array[dyn_array->count];
    sib1_msg->sib_message_id = rand(); // Generate a generic message ID
    sib1_msg->system_info.cell_identity = cell_identity;
    // Copy other system information fields here

    dyn_array->count++;

    pthread_mutex_unlock(&dyn_array->lock);

    return 0;
}
