import os
import json
import random
import hashlib
import logging
from cryptography.fernet import Fernet

# Configure logging
logging.basicConfig(filename='script.log', level=logging.DEBUG,
                    format='%(asctime)s - %(levelname)s - %(message)s')

class ScriptError(Exception):
    """Custom exception for script errors."""
    def __init__(self, message, step):
        super().__init__(f"Step {step}: {message}")
        self.message = message
        self.step = step

def generate_structures(param_dict, n_count):
    try:
        structures = []
        for _ in range(n_count):
            structure = {
                "RX_UE_INFORMATION_TAG": random.randint(1, 10000),
                "RNTI": random.randint(1, 1000),
                "CRC_INDICATION_REL8_TAG": {
                    "CRCFLAG": random.choice([True, False])
                }
            }
            # Replace placeholders in the structure
            for key in param_dict:
                if isinstance(structure[key], int):
                    structure[key] = param_dict.get(key, structure[key])
            structures.append(structure)
        return structures
    except Exception as e:
        raise ScriptError(str(e), "generate_structures")

def replace_placeholders(config_path, param_dict):
    try:
        with open(config_path, 'r') as file:
            config_data = file.read()

        for key, value in param_dict.items():
            placeholder = f"{{{{{key}}}}}"
            if placeholder in config_data:
                config_data = config_data.replace(placeholder, str(value))
            else:
                raise ScriptError(f"Placeholder {key} not found.", "replace_placeholders")

        with open(config_path, 'w') as file:
            file.write(config_data)
    except Exception as e:
        raise ScriptError(str(e), "replace_placeholders")

def encrypt_password(passphrase, salt):
    try:
        key = Fernet.generate_key()
        cipher_suite = Fernet(key)

        # Combine passphrase and salt
        combined_passphrase_salt = f"{passphrase}{salt}".encode()

        # Hash the combination using SHA-256
        hashed_pass = hashlib.sha256(combined_passphrase_salt).digest()

        # Encrypt the hash
        encrypted_password = cipher_suite.encrypt(hashed_pass)
        return encrypted_password, key
    except Exception as e:
        raise ScriptError(str(e), "encrypt_password")

def append_encrypted_password(config_path, encrypted_password):
    try:
        with open(config_path, 'a') as file:
            file.write(f"\nEncryptedPassword: {encrypted_password.decode('utf-8')}")
    except Exception as e:
        raise ScriptError(str(e), "append_encrypted_password")

def validate_encryption(original_passphrase, salt, encrypted_password, key):
    try:
        cipher_suite = Fernet(key)

        # Combine passphrase and salt
        combined_passphrase_salt = f"{original_passphrase}{salt}".encode()

        # Hash the combination using SHA-256
        hashed_pass = hashlib.sha256(combined_passphrase_salt).digest()

        # Decrypt the encrypted password
        decrypted_password = cipher_suite.decrypt(encrypted_password.encode('utf-8'))

        return decrypted_password == hashed_pass
    except Exception as e:
        raise ScriptError(str(e), "validate_encryption")

def main():
    try:
        # Parameters
        param_dict = {
            "RX_UE_INFORMATION_TAG": 12345,
            "RNTI": 6789
        }
        n_count = 10
        config_path = 'config.kickstart'
        passphrase = input("Enter the passphrase: ")

        # Retrieve salt from environment variable
        salt = os.environ.get('PASSWORD_SALT')
        if not salt:
            raise ScriptError("Environment variable PASSWORD_SALT is not set.", "main")

        # Generate structures
        structures = generate_structures(param_dict, n_count)
        print(json.dumps(structures, indent=2))

        # Replace placeholders in the configuration file
        replace_placeholders(config_path, param_dict)

        # Encrypt password and append to config file
        encrypted_password, key = encrypt_password(passphrase, salt)
        append_encrypted_password(config_path, encrypted_password.decode('utf-8'))

        # Validate encryption
        if not validate_encryption(passphrase, salt, encrypted_password.decode('utf-8'), key):
            raise ScriptError("Password validation failed.", "main")

    except ScriptError as se:
        logging.error(se)
        print(f"An error occurred: {se}")
    except Exception as e:
        logging.error(str(e))
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()
