```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

typedef struct {
    int CellIdentity;
    char SystemInformationBlockType1[256];
} LTE_RRC_SIB1;

typedef struct {
    LTE_RRC_SIB1* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SIB1Array;

SIB1Array* create_sib1_array(size_t initial_capacity) {
    SIB1Array* array = malloc(sizeof(SIB1Array));
    if (!array) return NULL;

    array->data = calloc(initial_capacity, sizeof(LTE_RRC_SIB1));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void resize_sib1_array(SIB1Array* array) {
    size_t new_capacity = array->capacity * 2;
    LTE_RRC_SIB1* new_data = realloc(array->data, new_capacity * sizeof(LTE_RRC_SIB1));
    if (!new_data) return; // Handle memory allocation failure gracefully

    array->data = new_data;
    array->capacity = new_capacity;
}

int add_sib1_entry(SIB1Array* array, LTE_RRC_SIB1 entry) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        resize_sib1_array(array);
        if (array->data == NULL) { // Check for failed reallocation
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    array->data[array->size] = entry;
    array->size++;

    log_sib1_change(entry);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void log_sib1_change(LTE_RRC_SIB1 sib1) {
    // Implement logging logic
    printf("SIB1 changed: CellIdentity=%d, SystemInformationBlockType1=%s\n",
           sib1.CellIdentity, sib1.SystemInformationBlockType1);
}

void free_sib1_array(SIB1Array* array) {
