#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(unsigned int rxTag, unsigned int rnti, unsigned int crcTag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rxTag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = crcTag;
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    return pdu;
}

int verify_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Placeholder for actual verification logic
    return (pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0 && pdu->CRC_INDICATION_REL8_TAG != 0);
}

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List** list) {
    Node* current = (*list)->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&(*list)->lock);
    free(*list);
    *list = NULL;
}

int add_pdu(List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!verify_pdu(pdu)) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -2;

    newNode->data = *pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void serialize_list(const List* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    initialize_random();

    List* pduList = create_list();
    if (!pduList) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(i + 1, i * 100, i * 200);
        if (add_pdu(pduList, &pdu)) {
            fprintf(stderr, "Failed to add PDU\n");
        }
    }

    FILE* file = fopen("pdus.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        destroy_list(&pduList);
        return EXIT_FAILURE;
    }

    serialize_list(pduList, file);
    fclose(file);

    destroy_list(&pduList);
    return EXIT_SUCCESS;
}
```

