typedef struct {
    size_t block_size;
    size_t alignment;
    void *memory_pool;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool g_memory_pool = {0};

void initialize_memory_pool(size_t block_size, size_t alignment) {
    char *env_block_size = getenv("BLOCK_SIZE");
    char *env_alignment = getenv("ALIGNMENT");

    if (env_block_size) g_memory_pool.block_size = strtoul(env_block_size, NULL, 10);
    else g_memory_pool.block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (env_alignment) g_memory_pool.alignment = strtoul(env_alignment, NULL, 10);
    else g_memory_pool.alignment = alignof(max_align_t);

    g_memory_pool.total_blocks = MAX_STRUCTS;
    pthread_mutex_init(&g_memory_pool.lock, NULL);
}

void *allocate_from_pool(size_t size) {
    pthread_mutex_lock(&g_memory_pool.lock);

    if (g_memory_pool.used_blocks >= g_memory_pool.total_blocks) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&g_memory_pool.lock);
        return NULL;
    }

    void *ptr = malloc(g_memory_pool.block_size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory block\n");
        pthread_mutex_unlock(&g_memory_pool.lock);
        return NULL;
    }

    g_memory_pool.used_blocks++;
    printf("Allocated block %zu of size %zu bytes. Used blocks: %zu\n", 
           g_memory_pool.used_blocks, g_memory_pool.block_size, g_memory_pool.used_blocks);

    pthread_mutex_unlock(&g_memory_pool.lock);
    return ptr;
}

void free_from_pool(void *ptr) {
    pthread_mutex_lock(&g_memory_pool.lock);

    if (!ptr) {
        fprintf(stderr, "Invalid pointer to free\n");
        pthread_mutex_unlock(&g_memory_pool.lock);
        return;
    }

    g_memory_pool.used_blocks--;
    printf("Freed block. Used blocks: %zu\n", g_memory_pool.used_blocks);

    free(ptr);
    pthread_mutex_unlock(&g_memory_pool.lock);
}

