    printf("Memory Pool State: Total Blocks: %zu, Used Blocks: %zu\n",
           g_memory_pool.total_blocks, g_memory_pool.used_blocks);

    pthread_mutex_unlock(&g_memory_pool.lock);
}

int main(int argc, char *argv[]) {
