#define MAX_STRUCTURES 10000
#define FILTER_THRESHOLD_PERCENTAGE 50

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_error("Memory allocation failed");
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_list(size_t N, uint16_t minRNTI, uint16_t maxRNTI) {
    if (N <= 0 || N > MAX_STRUCTURES) {
        log_error("Invalid number of structures requested.");
        return NULL;
    }

    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *list = safe_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL;  // Memory allocation failed, already logged
    }

    uint16_t crcSetCount = 0;
    srand((unsigned int)time(NULL));  // Seed for random number generation

    for (size_t i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = safe_malloc(sizeof(void*)); // Replace with actual tag allocation
        if (!list[i].RX_UE_INFORMATION_TAG) {
            log_error("Failed to allocate RX_UE_INFORMATION_TAG");
            // Free previously allocated memory in case of failure
            for (size_t j = 0; j < i; ++j) {
                free(list[j].RX_UE_INFORMATION_TAG);
            }
            free(list);
            return NULL;
        }

        list[i].RNTI = rand() % (maxRNTI - minRNTI + 1) + minRNTI;

        // Set CRCFLAG randomly, ensuring no more than 50% of them are set
        if (crcSetCount < N * FILTER_THRESHOLD_PERCENTAGE / 100) {
            list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
            crcSetCount += list[i].CRC_INDICATION_REL8_TAG.CRCFLAG;
        } else {
            list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }
    }

    // Log memory usage statistics
    printf("Allocated %zu structures, each of size %zu bytes.\n", N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return list;
}

void deallocate_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t N) {
