    printf("Allocated %zu NFAPI_CRC_INDICATION_PDU_T structures.\n", N);

    pthread_mutex_unlock(&lock);
    return pdu_array;
}

// Function to free allocated memory for an array of NFAPI_CRC_INDICATION_PDU_T structures.
void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    if (!pdu_array) return;

