// Memory pool for efficient memory management
typedef struct {
    size_t block_size;
    void* pool;
    pthread_mutex_t lock;
    size_t num_blocks;
    size_t block_count;
} MemoryPool;

MemoryPool crc_pool = {0};

void initialize_memory_pool(size_t block_size, size_t num_blocks) {
    if (crc_pool.block_size > 0) return; // Already initialized

    crc_pool.block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    crc_pool.num_blocks = num_blocks;
    crc_pool.pool = malloc(block_size * num_blocks);
    if (!crc_pool.pool) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        exit(EXIT_FAILURE);
    }
    crc_pool.block_count = 0;
    pthread_mutex_init(&crc_pool.lock, NULL);
}

void* allocate_from_pool() {
    pthread_mutex_lock(&crc_pool.lock);
    if (crc_pool.block_count >= crc_pool.num_blocks) {
        pthread_mutex_unlock(&crc_pool.lock);
        return NULL; // Pool exhausted
    }
    void* block = ((char*)crc_pool.pool + crc_pool.block_count * crc_pool.block_size);
    memset(block, 0, crc_pool.block_size); // Zero the memory
    crc_pool.block_count++;
    pthread_mutex_unlock(&crc_pool.lock);
    return block;
}

void free_memory_pool() {
    if (crc_pool.block_size > 0) {
        free(crc_pool.pool);
        pthread_mutex_destroy(&crc_pool.lock);
        memset(&crc_pool, 0, sizeof(MemoryPool));
    }
}

