use reqwest::{Client, Url, Error};
use std::time::Duration;
use tokio;

pub struct HttpClientConfig {
    pub verify_certificate: bool,
    pub timeout: Duration,
}

impl Default for HttpClientConfig {
    fn default() -> Self {
        HttpClientConfig {
            verify_certificate: true,
            timeout: Duration::from_secs(10),
        }
    }
}

pub async fn create_http_client(config: HttpClientConfig) -> Result<Client, Error> {
    let mut builder = Client::builder()
        .timeout(config.timeout)
        .danger_accept_invalid_certs(!config.verify_certificate);

    Ok(builder.build()?)
}

pub async fn perform_request(url: &str, client: &Client) -> Result<String, reqwest::Error> {
    let response = client.get(Url::parse(url)?).send().await?;

    if response.status().is_success() {
        response.text().await
    } else {
        Err(reqwest::Error::new(
            reqwest::StatusCode::from_u16(response.status().as_u16()).unwrap(),
            "Request failed",
        ))
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let config = HttpClientConfig::default();
    let client = create_http_client(config).await?;

    match perform_request("https://example.com", &client).await {
        Ok(body) => println!("Response: {}", body),
        Err(e) => eprintln!("Request error: {}", e),
    }

    Ok(())
}
