NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int n) {
    if (n <= 0 || n > MAX_STRUCTURES) {
        return NULL;
    }

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t padding = (ALIGNMENT - (struct_size % ALIGNMENT)) % ALIGNMENT;
    size_t aligned_struct_size = struct_size + padding;
    size_t total_size = n * aligned_struct_size;

    void* ptr = NULL;
    if ((ptr = malloc(total_size)) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)(((uintptr_t)ptr + padding - 1) & ~(ALIGNMENT - 1));

    for (int i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = (unsigned long)(rand() % 10000000 + i); // Ensure uniqueness by adding index
        snprintf(array[i].CRC_INDICATION_REL8_TAG, sizeof(array[i].CRC_INDICATION_REL8_TAG), "TAG%02d", i);

        if (array[i].RX_UE_INFORMATION_TAG < 0 || array[i].RNTI == 0) {
            fprintf(stderr, "Invalid data detected at index %d\n", i);
            free(ptr);
            return NULL;
        }
    }

    // Shuffle the array
    srand((unsigned int)time(NULL));
    for (int i = n - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        NFAPI_CRC_INDICATION_PDU_T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    return array;
}

void free_allocated_array(void* ptr, size_t n) {
