} IPHeader;

typedef struct {
    uint16_t source_port;
    uint16_t dest_port;
    uint32_t seq_num;
    uint32_t ack_num;
    uint8_t data_offset;
    uint8_t flags;
    uint16_t window;
    uint16_t check;
    uint16_t urg_ptr;
} TCPHeader;

typedef struct {
    EthernetHeader eth_hdr;
    IPHeader ip_hdr;
    TCPHeader tcp_hdr;
    char payload[ETH_FRAME_LEN - sizeof(EthernetHeader) - sizeof(IPHeader) - sizeof(TCPHeader)];
} NetworkPacket;

uint16_t compute_checksum(void *buf, int len);
void generate_random_data(uint8_t *data, size_t size);

void populate_packet(NetworkPacket *packet) {
    // Generate random Ethernet header
    generate_random_data(packet->eth_hdr.dest_addr, 6);
    generate_random_data(packet->eth_hdr.src_addr, 6);
    packet->eth_hdr.eth_type = htons(0x0800); // IPv4

    // Generate random IP header
    generate_random_data((uint8_t *)&packet->ip_hdr.src_ip, sizeof(uint32_t));
    generate_random_data((uint8_t *)&packet->ip_hdr.dst_ip, sizeof(uint32_t));
    packet->ip_hdr.ver_ihl = 0x45; // IPv4, IHL=5
    packet->ip_hdr.tos = 0;
    packet->ip_hdr.total_len = htons(sizeof(IPHeader) + sizeof(TCPHeader) + sizeof(packet->payload));
    packet->ip_hdr.id = htons(rand());
    packet->ip_hdr.frag_off = 0;
    packet->ip_hdr.ttl = 64;
    packet->ip_hdr.protocol = IPPROTO_TCP;
    packet->ip_hdr.check = 0; // Placeholder for checksum
    packet->ip_hdr.saddr = packet->ip_hdr.src_ip;
    packet->ip_hdr.daddr = packet->ip_hdr.dst_ip;

    // Generate random TCP header
    generate_random_data((uint8_t *)&packet->tcp_hdr.source_port, sizeof(uint16_t));
    generate_random_data((uint8_t *)&packet->tcp_hdr.dest_port, sizeof(uint16_t));
    packet->tcp_hdr.seq_num = htonl(rand());
    packet->tcp_hdr.ack_num = htonl(rand());
    packet->tcp_hdr.data_offset = 5 << 4; // Header length 20 bytes
    packet->tcp_hdr.flags = 0x50; // PSH and ACK flags
    packet->tcp_hdr.window = htons(4096);
    packet->tcp_hdr.check = 0; // Placeholder for checksum
    packet->tcp_hdr.urg_ptr = 0;

    // Generate random payload data
    generate_random_data(packet->payload, sizeof(packet->payload));

    // Calculate and set IP header checksum
    packet->ip_hdr.check = compute_checksum(&packet->ip_hdr, sizeof(IPHeader));

    // Calculate TCP pseudo-header for checksum calculation
    uint32_t pseudo_header[4] = {
        (packet->ip_hdr.saddr & 0xFFFF) | ((packet->ip_hdr.daddr & 0xFFFF) << 16),
        (packet->ip_hdr.total_len >> 8) | (6 << 14), // Protocol and length
        packet->tcp_hdr.source_port,
        packet->tcp_hdr.dest_port
    };

    uint32_t *ptr = pseudo_header;
    uint32_t sum = 0;
    for (int i = 0; i < sizeof(pseudo_header) / sizeof(uint32_t); i++) {
        sum += *ptr++;
    }
    sum += ntohl(packet->tcp_hdr.seq_num);
    sum += ntohl(packet->tcp_hdr.ack_num);
    sum += (packet->tcp_hdr.data_offset << 8) | 0x50; // Flags + reserved
    sum += htons(sizeof(TCPHeader) + sizeof(packet->payload));

    char *tcp_buf = malloc(sizeof(TCPHeader) + sizeof(packet->payload));
    memcpy(tcp_buf, &packet->tcp_hdr, sizeof(TCPHeader));
    memcpy(tcp_buf + sizeof(TCPHeader), packet->payload, sizeof(packet->payload));

    uint16_t tcp_checksum = compute_checksum(pseudo_header, sizeof(pseudo_header));
    sum += tcp_checksum;
    if ((sum >> 16) != 0) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    packet->tcp_hdr.check = ~((uint16_t)(sum));

    free(tcp_buf);

    // Validate checksum
    uint16_t ip_checksum_calculated = compute_checksum(&packet->ip_hdr, sizeof(IPHeader));
    uint16_t tcp_checksum_calculated = compute_checksum(pseudo_header, sizeof(pseudo_header));
    if (tcp_checksum_calculated != packet->tcp_hdr.check || ip_checksum_calculated != packet->ip_hdr.check) {
        fprintf(stderr, "Checksum validation failed!\n");
    }
}

void generate_random_data(uint8_t *data, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        data[i] = rand() % 256;
    }
}

uint16_t compute_checksum(void *buf, int len) {
    uint32_t sum = 0;
    unsigned short *ptr = buf;

    while (len > 1) {
        sum += *ptr++;
        if ((sum & 0xFFFF0000) != 0)
            sum = (sum & 0xFFFF) + (sum >> 16);
        len -= 2;
    }

    if (len == 1) {
        sum += *((unsigned char *)ptr);
    }

    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~((uint16_t)sum);
}

void process_packets(NetworkPacket *packets, int packet_count) {
    for (int i = 0; i < packet_count; ++i) {
        populate_packet(&packets[i]);
    }
}

int main() {
    srand(time(NULL));
    NetworkPacket packets[MAX_PACKETS];
    process_packets(packets, MAX_PACKETS);
    return 0;
}
