#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PDU_COUNT 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} PDUList;

PDUList* create_list() {
    PDUList* list = (PDUList*)malloc(sizeof(PDUList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_PDU_COUNT) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->pdu = pdu;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void shuffle_pdu(PDUList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->count < 2) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node *i, *j, *temp;
    for (i = list->head; i != NULL; i = i->next) {
        int rand_idx = rand() % list->count;
        for (j = list->head; j != NULL && rand_idx > 0; j = j->next)
            rand_idx--;

        if (i == j || j == NULL) continue;

        temp = (Node*)malloc(sizeof(Node));
        *temp = *j;

        j->prev->next = i;
        i->prev->next = j;

        j->prev = i->prev;
        i->prev = j;

        if (i == list->head) list->head = j;
        if (j == list->tail) list->tail = i;

        free(j);
    }

    pthread_mutex_unlock(&list->lock);
}

void filter_pdu(PDUList* list, unsigned int rnti_target) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;

        if (current->pdu.RNTI == rnti_target) {
            if (current->prev) current->prev->next = next;
            if (next) next->prev = current->prev;
            if (current == list->head) list->head = next;
            if (current == list->tail) list->tail = current->prev;

            Node* to_free = current;
            current = next;
            free(to_free);
            list->count--;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    list->head = list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
