#define MAX_ENTRIES 100

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned long RNTI;
} RX_UE_INFORMATION_TAG;

