    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
    pthread_mutex_t lock;
} CRCList;

// Function prototypes
void initialize_list(CRCList *list);
int add_entry(CRCList *list, unsigned long rnti);
int update_entry(CRCList *list, unsigned long rnti, int crcflag);
NFAPI_CRC_INDICATION_PDU_T* retrieve_entries(CRCList *list, unsigned long rnti);
void destroy_list(CRCList *list);

// Helper functions
static NFAPI_CRC_INDICATION_PDU_T* create_entry(unsigned long rnti, int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) return NULL;
    entry->ue_info_tag.RNTI = rnti;
    entry->crc_rel8_tag.CRCFLAG = crcflag;
    entry->prev = entry->next = NULL;
    return entry;
}

static void insert_head(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (!list->head) {
        list->head = list->tail = entry;
    } else {
        entry->next = list->head;
        list->head->prev = entry;
        list->head = entry;
    }
}

static void remove_entry(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (entry->prev) entry->prev->next = entry->next;
    else list->head = entry->next;

    if (entry->next) entry->next->prev = entry->prev;
    else list->tail = entry->prev;

    free(entry);
}

static void evict_lru(CRCList *list) {
    if (!list->tail) return;
    remove_entry(list, list->tail);
}

// Initialize the CRC List
void initialize_list(CRCList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->count = 0;
}

// Add or update an entry in the CRC List
int add_entry(CRCList *list, unsigned long rnti) {
    int crcflag = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        evict_lru(list);
        list->count--;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = create_entry(rnti, crcflag);
    if (!entry) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: Out of memory
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->ue_info_tag.RNTI == rnti) {
            current->crc_rel8_tag.CRCFLAG = crcflag;
            remove_entry(list, current);
            insert_head(list, current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Updated existing entry
        }
        current = current->next;
    }

    insert_head(list, entry);
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Successfully added new entry
}

// Retrieve all entries for a specific RNTI
NFAPI_CRC_INDICATION_PDU_T* retrieve_entries(CRCList *list, unsigned long rnti) {
    NFAPI_CRC_INDICATION_PDU_T *entry = NULL;
    pthread_mutex_lock(&list->lock);

    entry = list->head;
    while (entry) {
        if (entry->ue_info_tag.RNTI == rnti) break;
        entry = entry->next;
    }

    pthread_mutex_unlock(&list->lock);
    return entry; // Returns NULL if not found
}

// Destroy the CRC List and free resources
void destroy_list(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    srand(time(NULL));
    CRCList list;

    initialize_list(&list);

    // Add or update entries
    add_entry(&list, 12345);
    add_entry(&list, 67890);
    add_entry(&list, 12345); // Update existing

    // Retrieve and print an entry
    NFAPI_CRC_INDICATION_PDU_T *entry = retrieve_entries(&list, 12345);
    if (entry) {
        printf("RNTI: %lu, CRCFLAG: %d\n", entry->ue_info_tag.RNTI, entry->crc_rel8_tag.CRCFLAG);
    } else {
        printf("Entry not found.\n");
    }

    // Clean up
    destroy_list(&list);

    return 0;
}
```

### Key Design Considerations:
- **Thread Safety**: The list operations are protected by a mutex to ensure thread safety.
- **Memory Management**: Uses `malloc` and `free` for dynamic memory management. Handles out-of-memory conditions gracefully.
- **LRU Eviction**: When the maximum capacity is reached, the least recently used entry (the tail of the list) is evicted.
- **Random CRCFLAG Assignment**: Each new entry has a randomly assigned `CRCFLAG`.
- **Dynamic Resizing**: The function allows for dynamic addition and updates without immediate resource exhaustion.

### Trade-offs:
- **Memory vs. Performance**: Balances memory usage with performance by limiting entries to `MAX_ENTRIES` and evicting LRU entries.
- **Responsiveness**: Ensures system responsiveness under high load by efficiently managing the list size.
- **Data Integrity**: Maintains data integrity through careful management of entry updates and deletions.

### Future Optimizations:
- Implement custom memory allocators for more efficient memory reuse.
- Consider using read-write locks if reads are significantly more frequent than writes to improve concurrency.']

