    if (!new_node) {
        thread_safe_log("Failed to allocate memory for new node.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    while (list->current_size >= MAX_SIZE) {
        pthread_cond_wait(&list->cond, &list->lock);
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    if (!list->tail) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->current_size++;

    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

