    *pdu = temp->data;

    list->head = temp->next;
    if (!list->head) {
        list->tail = NULL; // If head becomes null, the list is empty
    }

    memory_free(temp); // Using provided allocator

    list->current_size--;
    pthread_cond_signal(&list->cond);

    pthread_mutex_unlock(&list->lock);
    return 0;
}
