    return (tag ^ rnti) & 0xFF;
}

int is_unique_tag(LinkedList* list, uint16_t tag) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->num_tags_seen; ++i) {
        if (list->tags_seen[i] == tag) {
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    list->tags_seen[list->num_tags_seen++] = tag;
    pthread_mutex_unlock(&list->lock);
    return 1;
}

void clear_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        memory_free(temp);
    }
    list->head = NULL;
    pthread_mutex_lock(&list->lock);
    memset(list->tags_seen, 0, sizeof(uint16_t) * list->num_tags_seen);
    list->num_tags_seen = 0;
    pthread_mutex_unlock(&list->lock);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_unique_tag(list, pdu.RX_UE_INFORMATION_TAG)) return -1;

    Node* new_node = (Node*)memory_alloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed");
        return -1;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    size_t current_size = 0;
    Node* temp = list->head;
    while (temp != NULL) {
        ++current_size;
        temp = temp->next;
    }

    if (current_size >= list->max_size) {
        memory_free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    new_node->next = list->head;
    list->head = new_node;

    if ((time(NULL) - list->last_cleared) >= list->clear_interval) {
        clear_list(list);
    }
    pthread_mutex_unlock(&list->lock);

    async_push_to_server(&pdu, 3); // Example retry count
    return 0;
}

LinkedList* create_linked_list(size_t max_size, double clear_interval) {
    LinkedList* list = (LinkedList*)memory_alloc(sizeof(LinkedList));
    if (!list) {
        log_error("Memory allocation failed");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = max_size;
    list->last_cleared = time(NULL);
    list->clear_interval = clear_interval;
    list->tags_seen = (uint16_t*)memory_alloc(max_size * sizeof(uint16_t));
    if (!list->tags_seen) {
        log_error("Memory allocation failed");
        pthread_mutex_destroy(&list->lock);
        memory_free(list);
        return NULL;
    }
    list->num_tags_seen = 0;
    return list;
}

void destroy_linked_list(LinkedList* list) {
    clear_list(list);
    pthread_mutex_destroy(&list->lock);
    memory_free(list->tags_seen);
    memory_free(list);
}

int main() {
    LinkedList* list = create_linked_list(100, 60.0); // Example max size and interval
    if (!list) return -1;

    srand(time(NULL));
    for (size_t i = 0; i < 200; ++i) { // Attempt to add more than max_size
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 65536;
        pdu.RNTI = rand() % 4294967295;
        pdu.CRCFLAG = rolling_hash(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);

        if (add_to_list(list, pdu) != 0) {
            printf("Failed to add element\n");
        }
    }

    destroy_linked_list(list);
    return 0;
}
```

