    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    log_message("Linked list freed.");
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (list->current_memory_usage + sizeof(Node) > MAX_MEMORY_USAGE) {
        log_message("Memory threshold exceeded. Cannot add more elements.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    // Validate RNTI
    if (!validate_RNTI(new_data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        log_message("RNTI validation failed. Element not added.");
        return -2;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        perror("Failed to allocate memory for new node");
        log_message("Memory allocation failed for new element.");
        return -3;
    }

    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;
    list->current_memory_usage += sizeof(Node);

    pthread_mutex_unlock(&list->lock);

    log_message("Element successfully added to the list.");
    return 0; // Success
}

size_t serialize_list(LinkedList* list, unsigned char** buffer) {
    size_t total_size = list->current_memory_usage;
    *buffer = malloc(total_size);

    if (!(*buffer)) {
        perror("Failed to allocate memory for serialization");
        log_message("Memory allocation failed during serialization.");
        return 0; // Failure
    }

    Node* current = list->head;
    size_t offset = 0;

    while (current) {
        memcpy((*buffer) + offset, &(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    log_message("List serialized successfully.");
    return total_size; // Success
}

LinkedList* deserialize_list(const unsigned char* buffer, size_t buffer_size) {
    LinkedList* list = create_linked_list();
    if (!list) return NULL;

    const unsigned char* ptr = buffer;
    while (buffer_size > 0) {
        NFAPI_CRC_INDICATION_PDU_T data;
        memcpy(&data, ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (add_to_list(list, data) != 0) {
            log_message("Failed to add element during deserialization.");
            free_linked_list(list);
            return NULL; // Failure
        }

        ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        buffer_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    log_message("List deserialized successfully.");
    return list;
}

int main() {
