        Node* next = current->next;
        free(current);
        list->current_memory_usage -= sizeof(Node);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Function to add a new element
int add_crc_indication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->current_memory_usage + sizeof(Node) > MEMORY_THRESHOLD) {
        // Memory management strategy: remove oldest node or other logic
        return -1; // Indicate failure due to memory constraints
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->current_memory_usage += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Example function to simulate RNTI validation with retry logic
int validate_rnti(int rnti) {
    int retries = 3;
    while (retries--) {
        // Simulate external service call
        if (rand() % 2 == 0) { // Random success/failure simulation
            return 1; // Valid RNTI
        }
        sleep(1); // Exponential backoff could be applied here
    }
    return 0; // Failed to validate RNTI
}

// Function to serialize the list into a binary format
int serialize_crc_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0; // Success
}

// Function to deserialize the list from a binary format
int deserialize_crc_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_crc_indication(list, data);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0; // Success
}

int main() {
    CRCList list;
    init_crc_list(&list, MEMORY_THRESHOLD);

    srand(time(NULL)); // Seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1234, 5678, rand() % 2};
    if (validate_rnti(pdu.RNTI) && add_crc_indication(&list, pdu) == 0) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU.\n");
    }

    serialize_crc_list(&list, "crc_data.bin");

    CRCList new_list;
    init_crc_list(&new_list, MEMORY_THRESHOLD);
    deserialize_crc_list(&new_list, "crc_data.bin");

    free_crc_list(&list);
    free_crc_list(&new_list);

    return 0;
}
```

