BatchConfigurations* allocate_and_initialize_structures(int n, int batch_size, int max_retries) {
    if (n <= 0 || n > MAX_CONFIGURATIONS) {
        fprintf(stderr, "Invalid input: %d. Must be between 1 and %d.\n", n, MAX_CONFIGURATIONS);
        return NULL;
    }

    BatchConfigurations *batch = NULL;
    int total_batches = (n + batch_size - 1) / batch_size; // Ceiling division
    srand(time(NULL)); // Seed random number generator

    for (int attempt = 0; attempt <= max_retries; ++attempt) {
        batch = malloc(sizeof(BatchConfigurations));
        if (!batch) {
            fprintf(stderr, "Memory allocation failed on attempt %d. Retrying...\n", attempt + 1);
            continue;
        }

        int success = 1;
        for (int i = 0; i < total_batches && success; ++i) {
            int current_batch_size = (i == total_batches - 1) ? (n % batch_size) : batch_size;
            if (current_batch_size <= 0) break;

            if (initialize_structures(batch, current_batch_size) != 0) {
