#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    size_t true_crc_count;
} PduList;

PduList* create_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->true_crc_count = 0;

    return list;
}

void free_list(PduList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int get_random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

void append_pdu(PduList* list, int rx_ue_tag, int rnti) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->data.RNTI = rnti;
    new_node->data.crc_tag.CRCFLAG = get_random_crc_flag();

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    if (new_node->data.crc_tag.CRCFLAG) {
        list->true_crc_count++;
    }
    pthread_mutex_unlock(&list->lock);
}

size_t get_true_crc_count(const PduList* list) {
    size_t count;
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    count = list->true_crc_count;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    return count;
}

void periodic_cleanup(PduList* list, int cleanup_threshold) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && list->count > cleanup_threshold) {
        Node* to_free = current;
        current = current->next;

        if (!to_free->data.crc_tag.CRCFLAG) {
            list->head = current;
            free(to_free);
            list->count--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    srand(time(NULL));

    PduList* pdu_list = create_list();
    if (!pdu_list) {
        fprintf(stderr, "Failed to create PDU list\n");
        return 1;
    }

    for (int i = 0; i < 1000000; ++i) {
        append_pdu(pdu_list, rand(), rand());
    }

    printf("Total true CRC count: %zu\n", get_true_crc_count(pdu_list));

    periodic_cleanup(pdu_list, 500000);

    free_list(pdu_list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The list is protected by a mutex to ensure thread-safe operations.
- **Memory Management**: Nodes are dynamically allocated and freed. Periodic cleanup helps manage memory usage.
- **Random CRCFLAG**: Each node's `CRCFLAG` is randomly set.
- **Resource Cleanup**: Properly frees all allocated resources when done.
- **Scalability Considerations**: Designed to handle up to 1 million structures efficiently.

This implementation provides a foundation for managing and processing PDUs in a concurrent environment, with considerations for performance and memory management. Adjustments may be needed based on specific requirements or constraints of the deployment environment.']

