#define MAX_INTS 1000000

typedef struct {
    int *data;
    size_t count;
    pthread_mutex_t lock;
} IntList;

// Helper function to validate integer format and value
int isValid(int num) {
    return num >= INT_MIN && num <= INT_MAX;
}

// Function to add an integer to the list in a thread-safe manner
void addInteger(IntList *list, int num) {
    if (!isValid(num)) return;

    pthread_mutex_lock(&list->lock);

    if (list->count < MAX_INTS) {
        list->data[list->count++] = num;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to find and print the largest integer in the list
void printLargestInt(const IntList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count == 0) {
        printf("The list is empty.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    int max = list->data[0];
    for (size_t i = 1; i < list->count; ++i) {
        if (list->data[i] > max) {
            max = list->data[i];
        }
    }

    printf("Largest integer: %d\n", max);
    pthread_mutex_unlock(&list->lock);
}

// Function to clean up the list
void freeIntList(IntList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    list->count = 0;
}

