#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit: 1MB
#define VALID_CRCFLAG_RANGE_MIN 0x01
#define VALID_CRCFLAG_RANGE_MAX 0xFF
#define LIST_INITIAL_CAPACITY 10

typedef struct {
    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG[16]; // Placeholder size, adjust as needed
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    size_t memory_used;
    pthread_mutex_t lock;
} NFAPIList;

NFAPIList* create_nfa_list() {
    NFAPIList *list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(LIST_INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    list->capacity = LIST_INITIAL_CAPACITY;
    list->count = 0;
    list->memory_used = LIST_INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return list;
}

int add_to_nfa_list(NFAPIList *list, unsigned int rnti, const unsigned char *rx_tag) {
    if (!list || !rx_tag) return -1;

    pthread_mutex_lock(&list->lock);

    // Check memory limit
    if (list->memory_used >= MAX_MEMORY_LIMIT) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory limit reached
    }

    // Ensure unique RNTI and no consecutive duplicates
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti || 
            (i > 0 && list->data[i - 1].RNTI == rnti)) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Duplicate RNTI
        }
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = 
            (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -4; // Reallocation failed
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[list->count++];

    entry->RNTI = rnti;
    memcpy(entry->RX_UE_INFORMATION_TAG, rx_tag, sizeof(entry->RX_UE_INFORMATION_TAG));

    // Randomly assign CRCFLAG within valid range
    srand(time(NULL) + (unsigned int)rnti); // Seed with RNTI for some variation
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 
        (VALID_CRCFLAG_RANGE_MAX - VALID_CRCFLAG_RANGE_MIN + 1) + VALID_CRCFLAG_RANGE_MIN;

    list->memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void destroy_nfa_list(NFAPIList *list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}
