    struct ListNode* next;
} ListNode;

// Function to validate CRC indications based on predefined rules
int validate_crc_indication(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (RX_UE_INFORMATION_TAG < VALID_RX_UE_INFORMATION_TAG_MIN || 
        RX_UE_INFORMATION_TAG > VALID_RX_UE_INFORMATION_TAG_MAX ||
        RNTI < VALID_RNTI_MIN || RNTI > VALID_RNTI_MAX ||
        CRC_INDICATION_REL8_TAG < 0) { // Assume valid tags are non-negative
        return 1; // Invalid
    }
    return 0; // Valid
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
ListNode* create_nfa_list(int n) {
    if (n <= 0) {
        return NULL;
    }

    ListNode *head = NULL, **ptr = &head;

    for (int i = 0; i < n; ++i) {
        // Allocate memory for a new node
        ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
