        int CRC_INDICATION_REL8_TAG = rand() % 100;    // Random value between 0 and 99

        // Validate the data
        newNode->data.error_flag = validate_crc_indication(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);

        if (!newNode->data.error_flag) {
            // Populate valid data into the structure
            newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            newNode->data.RNTI = RNTI;
            newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        }

        // Set timestamp
        newNode->data.timestamp = time(NULL);
        newNode->next = NULL;

        *ptr = newNode; // Link new node to the list
        ptr = &newNode->next; // Move pointer for next iteration
    }

    return head;
}

// Cleanup function to free allocated memory
void free_nfa_list(ListNode* head) {
    ListNode* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
