['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_SIZE 100

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

bool resize_if_needed(DynamicList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? MAX_SIZE : list->capacity * 2;
        if (new_capacity > MAX_SIZE) return false;

        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    return true;
}

bool add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size > 0 && list->data[list->size - 1].RNTI == pdu.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    if (!resize_if_needed(list)) {
        pthread_mutex_unlock(&list->lock);
        return false;
