    size_t count;
    size_t max_size;
    pthread_mutex_t lock;  // Mutex for thread safety
} PduManager;

// Function to initialize the PduManager
int pdu_manager_init(PduManager *manager, size_t initial_capacity) {
    if (!manager || initial_capacity == 0) return -1;

    manager->entries = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!manager->entries) return -1; // Memory allocation failure

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->entries[i] = NULL;  // Initialize to NULL
    }

    manager->count = 0;
    manager->max_size = initial_capacity;

    pthread_mutex_init(&manager->lock, NULL);

    return 0;
}

// Function to add a new entry
int pdu_manager_add_entry(PduManager *manager, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    if (!manager || !new_pdu) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for available space or free spot to reuse
    size_t i;
    int added = 0;
    for (i = 0; i < manager->count; ++i) {
        if (manager->entries[i] == NULL) {  // Reuse freed structure
            manager->entries[i] = new_pdu;
            added = 1;
            break;
        }
    }

    if (!added && manager->count < manager->max_size) {  // Add to next spot if space exists
        manager->entries[manager->count++] = new_pdu;
    } else {
        pthread_mutex_unlock(&manager->lock);
        return -2; // No space available
    }

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Function to free the PduManager resources
void pdu_manager_destroy(PduManager *manager) {
    if (!manager) return;

    if (manager->entries) {
        for (size_t i = 0; i < manager->max_size; ++i) {
            free(manager->entries[i]);  // Free each structure
        }
        free(manager->entries);
    }

    pthread_mutex_destroy(&manager->lock);
}

