#include <stdlib.h>
#include <string.h>
#include <jansson.h>  // JSON library

#define MAX_BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NetworkSettings;

void print_usage() {
    printf("Usage: program [options] <input_files...>\n");
    printf("Options:\n");
    printf("  -o <output_file>   Specify the output file\n");
}

int parse_json(const char *filename, NetworkSettings *settings) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);

    if (!root) {
        fprintf(stderr, "Error loading JSON file %s: %s\n", filename, error.text);
        return -1;
    }

    int ret = 0;

    if (json_unpack(root, "{s:i, s:i, s:i}", 
                    "RX_UE_INFORMATION_TAG", &settings->RX_UE_INFORMATION_TAG,
                    "RNTI", &settings->RNTI,
                    "CRC_INDICATION_REL8_TAG", &settings->CRC_INDICATION_REL8_TAG) != 0) {
        fprintf(stderr, "Error parsing JSON file %s\n", filename);
        ret = -1;
    } else {
        // Apply CRCFLAG logic based on predefined rules
        settings->CRCFLAG = (settings->RX_UE_INFORMATION_TAG & 1) ? 1 : 0; // Example rule
    }

    json_decref(root);
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    const char *output_file = NULL;
    int line_count_total = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strchr(argv[i], '.') != NULL && strcmp(strrchr(argv[i], '.'), ".json") == 0) {
            NetworkSettings settings;
            if (parse_json(argv[i], &settings) != 0) {
                continue; // Skip invalid JSON files
            }

            printf("Processed network configuration from %s: RX_UE=%d, RNTI=%d, CRC_IND8=%d, CRCFLAG=%d\n",
                   argv[i],
                   settings.RX_UE_INFORMATION_TAG,
                   settings.RNTI,
                   settings.CRC_INDICATION_REL8_TAG,
                   settings.CRCFLAG);
        } else if (strchr(argv[i], '.') != NULL && strcmp(strrchr(argv[i], '.'), ".txt") == 0) {
            FILE *file = fopen(argv[i], "r");
            if (!file) {
                perror("Error opening file");
                continue;
            }

            char buffer[MAX_BUFFER_SIZE];
            int line_count = 0;

            while (fgets(buffer, sizeof(buffer), file)) {
                ++line_count;
            }
            fclose(file);

            printf("File %s has %d lines.\n", argv[i], line_count);
            line_count_total += line_count;
        } else {
            print_usage();
            return EXIT_FAILURE;
        }
    }

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("Error opening output file");
            return EXIT_FAILURE;
        }

        fprintf(out, "Total line count across all files: %d\n", line_count_total);
        fclose(out);
    } else {
        printf("No output file specified.\n");
    }

    return EXIT_SUCCESS;
}
