                if (verbose) {
                    fprintf(log_file, "Line: %sAverage word length: %.2f\n", line, avg_word_length);
                }
            }

            fclose(input_file);
        }
    }

    if (!input_file) {
        print_usage(argv[0]);
    }

    // Generate NFAPI_RX_FRAME_PDU_T structures
    NFAPI_RX_FRAME_PDU_T frames[10];  // Example: generate 10 frames
    for (int i = 0; i < 10; i++) {
        populate_nfa_rx_frame(&frames[i]);
    }

    if (log_file != stdout) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

void print_usage(const char *prog_name) {
    printf("Usage: %s [options] <input_file>\n", prog_name);
    printf("Options:\n");
    printf("  --help          Display this help and exit\n");
    printf("  -v              Verbose output\n");
    printf("  -o <output_file> Specify an output log file (default is stdout)\n");
}

double calculate_average_word_length(char *line) {
    int word_count = 0, char_count = 0;
    char *token = strtok(line, " \t\n");

    while (token != NULL) {
        word_count++;
        char_count += strlen(token);
        token = strtok(NULL, " \t\n");
    }

    return (word_count > 0) ? (double)char_count / word_count : 0.0;
}

unsigned int generate_checksum(char *data, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; i++) {
        checksum += data[i];
    }
    return checksum % 256;
}

void populate_nfa_rx_frame(NFAPI_RX_FRAME_PDU_T *frame) {
    frame->RX_UE_INFORMATION_TAG = rand() % 100;
    frame->RNTI = (unsigned short)(rand() % 65535);
    snprintf(frame->frame_header, sizeof(frame->frame_header), "HDR%03d", rand() % 1000);

    for (int i = 0; i < sizeof(frame->payload); i++) {
        frame->payload[i] = 'A' + (rand() % 26);
    }

    frame->checksum = generate_checksum(frame->payload, sizeof(frame->payload));
}
