Status_Code allocate_and_initialize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t size, float population_density) {
    if (size == 0 || size > MAX_ARRAY_SIZE || population_density < 0.0f || population_density > 1.0f) {
