    for (size_t i = 0; i < num_to_initialize; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand(); // Example initialization
        (*array)[i].RNTI = rand();
        (*array)[i].CRC_INDICATION_REL8_TAG.some_value = rand();
    }

    return STATUS_SUCCESS;
}

// Function to reconfigure population density at runtime without reallocating the entire array
Status_Code reconfigure_population_density(NFAPI_CRC_INDICATION_PDU_T *array, size_t size, float new_population_density) {
    if (array == NULL || size == 0 || new_population_density < 0.0f || new_population_density > 1.0f) {
        return STATUS_INVALID_PARAMETERS;
