// ModuleLoader.js

class ModuleLoader {
  constructor() {
    this.modules = new Map();
    this.loadingPromises = new Map();
  }

  async loadModule(moduleId, url) {
    if (this.loadingPromises.has(moduleId)) {
      return this.loadingPromises.get(moduleId);
    }

    const promise = this._loadScript(url)
      .then((moduleExports) => {
        this.modules.set(moduleId, moduleExports);
      })
      .catch((error) => {
        console.error(`Error loading module ${moduleId} from ${url}:`, error);
        // Log the error to an external monitoring service
        this.logError(error, moduleId, url);
      });

    this.loadingPromises.set(moduleId, promise);

    return promise;
  }

  async _loadScript(url) {
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = url;

      // Set up handlers for all relevant events
      script.onload = () => resolve({ moduleExports: window[url.split('/').pop().replace('.js', '')] });
      script.onerror = (errorEvent) => reject(new Error(`Failed to load ${url}: ${errorEvent.message}`));

      document.head.appendChild(script);
    });
  }

  async executeModule(moduleId, callbackName) {
    const moduleExports = this.modules.get(moduleId);

    if (!moduleExports || !moduleExports[callbackName]) {
      console.error(`Module ${moduleId} does not have a function named ${callbackName}`);
      return;
    }

    try {
      await moduleExports[callbackName]();
    } catch (error) {
      console.error(`Error executing callback ${callbackName} from module ${moduleId}:`, error);
      this.logError(error, moduleId, callbackName);
    }
  }

  logError(error, contextInfo, additionalInfo = '') {
    // Assuming there is an external logging service with a method `sendLog`
    const errorMessage = `[${new Date().toISOString()}] Error in ${contextInfo}: ${error.message} ${additionalInfo}`;
    console.error(errorMessage);

    // Example of sending the error to an external monitoring service
    fetch('https://external-logging-service.com/log', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: errorMessage, stack: error.stack })
    }).catch(console.error);
  }

  async cleanup() {
    this.modules.clear();
    this.loadingPromises.forEach(promise => promise.catch(() => {}));
    this.loadingPromises.clear();

    // Remove all script tags from the head
    document.head.querySelectorAll('script').forEach(script => document.head.removeChild(script));
  }
}

// Usage Example

const loader = new ModuleLoader();

async function main() {
  try {
    await loader.loadModule('analytics', 'https://cdn.example.com/analytics.js');
    await loader.executeModule('analytics', 'init');

    // Load more modules as needed
    await loader.loadModule('charting', 'https://cdn.example.com/charting.js');
    await loader.executeModule('charting', 'renderChart');
  } catch (error) {
    console.error('Error during module operations:', error);
  }
}

main().finally(() => loader.cleanup());
```

This script demonstrates a robust, scalable architecture for dynamically loading and executing JavaScript modules in a web application. It efficiently handles network failures, server outages, and unexpected content through promises and event handlers. The logging mechanism is integrated to facilitate monitoring and issue resolution."]

