typedef void (*ProcessListCallback)(NFAPI_CRC_INDICATION_PDU_T*, size_t);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    ProcessListCallback callback;
} CRCListManager;

static size_t totalEntriesProcessed = 0;

void log_error(const char* message) {
    // Asynchronous logging implementation
    printf("ERROR: %s\n", message);
}

int isValidRNTI(unsigned short rnti) {
    return (rnti >= VALID_RNTI_MIN && rnti <= VALID_RNTI_MAX);
}

void resizeList(CRCListManager* manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->mutex);
    NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(manager->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entries) {
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    } else {
        log_error("Memory allocation failed during list resizing");
    }
    pthread_mutex_unlock(&manager->mutex);
}

void addEntry(CRCListManager* manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!isValidRNTI(entry.RNTI)) {
        log_error("Invalid RNTI value encountered");
        return;
    }

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->entries[i].RNTI == entry.RNTI) {
            pthread_mutex_unlock(&manager->mutex);
            return; // Duplicate RNTI, skip adding
        }
    }

    if (manager->size >= manager->capacity) {
        resizeList(manager, manager->capacity * 2);
    }

    manager->entries[manager->size++] = entry;
    totalEntriesProcessed++;

    pthread_mutex_unlock(&manager->mutex);
}

void processCompletedList(CRCListManager* manager) {
    if (manager->callback && manager->size > 0) {
        manager->callback(manager->entries, manager->size);
    }

    memset(manager->entries, 0, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
}

void initializeManager(CRCListManager* manager, ProcessListCallback callback) {
    manager->entries = malloc(MAX_INITIAL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->entries) {
        log_error("Initial memory allocation failed");
        exit(EXIT_FAILURE);
    }
    manager->size = 0;
    manager->capacity = MAX_INITIAL_SIZE;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->callback = callback;
}

void finalizeManager(CRCListManager* manager) {
    free(manager->entries);
    pthread_mutex_destroy(&manager->mutex);
}

void retryLogic(int (*operation)(void*), void* arg, int max_retries) {
    int attempts = 0;
    while (attempts < max_retries) {
        if (operation(arg)) {
            return; // Success
        }
        attempts++;
        log_error("Operation failed, retrying...");
    }
    log_error("Max retries reached, operation failed");
}

void exampleCallback(NFAPI_CRC_INDICATION_PDU_T* entries, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("Processing entry: RNTI=%u, CRCFLAG=%d\n", entries[i].RNTI, entries[i].CRCFLAG);
    }
}

int main() {
    CRCListManager manager;
    initializeManager(&manager, exampleCallback);

    // Simulate adding entries
    for (int i = 0; i < 200; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry = { .RX_UE_INFORMATION_TAG = rand(), 
                                             .RNTI = rand() % VALID_RNTI_MAX + 1, 
                                             .CRC_INDICATION_REL8_TAG = rand(),
                                             .CRCFLAG = rand() % 2 };
        addEntry(&manager, entry);
    }

    processCompletedList(&manager);

    finalizeManager(&manager);

    return 0;
}
```

### Key Features:
- **Thread Safety:** Uses mutexes to ensure thread-safe access.
- **Dynamic Resizing:** List can grow dynamically based on demand.
- **Validation and Logging:** Validates RNTI values and logs errors asynchronously.
- **Callback Mechanism:** Supports processing completed lists via a callback.
- **Retry Logic:** Implements retry logic for operations with configurable retries.
- **Extensibility:** Designed to allow future modifications with minimal changes.']

