#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define INITIAL_CAPACITY 5000
#define MAX_CAPACITY 10000
#define INACTIVITY_THRESHOLD_SECONDS 300 // Example threshold

typedef struct {
    char ip_address[16];
    uint16_t port;
    int status; // e.g., connected, disconnected
    time_t last_activity;
} TCP_CONNECTION_INFO;

typedef struct {
    TCP_CONNECTION_INFO *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For simplicity using mutex for now
} ConnectionManager;

ConnectionManager* create_connection_manager() {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->connections = calloc(manager->capacity, sizeof(TCP_CONNECTION_INFO));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void free_connection_manager(ConnectionManager *manager) {
    if (manager) {
        free(manager->connections);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_connection(ConnectionManager *manager, const char *ip_address, uint16_t port, int status) {
    pthread_mutex_lock(&manager->lock);

    // Resize if needed
    if (manager->count == manager->capacity && manager->capacity < MAX_CAPACITY) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_CAPACITY)
            new_capacity = MAX_CAPACITY;

        TCP_CONNECTION_INFO *new_connections = realloc(manager->connections, new_capacity * sizeof(TCP_CONNECTION_INFO));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }

        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    TCP_CONNECTION_INFO conn_info;
    strncpy(conn_info.ip_address, ip_address, sizeof(conn_info.ip_address));
    conn_info.port = port;
    conn_info.status = status;
    conn_info.last_activity = time(NULL);

    manager->connections[manager->count++] = conn_info;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void remove_inactive_connections(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->count;) {
        if (current_time - manager->connections[i].last_activity > INACTIVITY_THRESHOLD_SECONDS && manager->connections[i].status == 1) { // Assuming 1 means connected
            memmove(&manager->connections[i], &manager->connections[i + 1],
                    (manager->count - i - 1) * sizeof(TCP_CONNECTION_INFO));
            manager->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void serialize_connections(ConnectionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->connections, sizeof(TCP_CONNECTION_INFO), manager->count, file);

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void deserialize_connections(ConnectionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fread(&manager->count, sizeof(size_t), 1, file);
    manager->connections = realloc(manager->connections, manager->count * sizeof(TCP_CONNECTION_INFO));
    fread(manager->connections, sizeof(TCP_CONNECTION_INFO), manager->count, file);

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void update_activity(ConnectionManager *manager, const char *ip_address) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->connections[i].ip_address, ip_address) == 0) {
            manager->connections[i].last_activity = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void monitor_connections(ConnectionManager *manager) {
    while (1) {
        remove_inactive_connections(manager);
        sleep(60); // Run garbage collection every minute
    }
}

int main() {
    ConnectionManager *manager = create_connection_manager();

    // Add connections, serialize/deserialize, update activities as needed

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void *)monitor_connections, manager);

    // Cleanup and shutdown logic here...

    free_connection_manager(manager);
    return 0;
}
```

**Key Points:**
- Uses a mutex for thread safety. Consider upgrading to more advanced concurrency mechanisms like spinlocks or lock-free structures if needed.
- Supports dynamic resizing up to `MAX_CAPACITY`.
- Implements basic garbage collection by removing inactive connections based on a threshold.
- Serializes and deserializes connection data in binary format for efficiency.
- Includes a monitoring function that periodically cleans up inactive connections. Adjust the sleep duration based on your needs.
- This example uses a simple mutex for simplicity; you might explore more advanced concurrency techniques as needed for high-performance scenarios.

This code provides a starting point, and further optimizations can be made depending on specific performance requirements and constraints.']

