// Define structures
typedef struct {
    int MAC_STATE;
} MAC_CONTEXT_T;

typedef struct {
    int UE_ID;
    int RRC_connection_status; // 0 for disconnected, 1 for connected
    MAC_CONTEXT_T *mac_context;
} UE_CONTEXT_T;

// Function prototypes
int add_UE_context(UE_CONTEXT_T **ue_array, size_t *size, int ue_id);
void remove_UE_context(UE_CONTEXT_T **ue_array, size_t *size, int ue_id);
void update_RRC_connection_status(UE_CONTEXT_T **ue_array, size_t size, int ue_id, int status);
void dump_active_ue_contexts_to_log(const UE_CONTEXT_T *ue_array, size_t size, const char *log_file);

// Function implementations
int add_UE_context(UE_CONTEXT_T **ue_array, size_t *size, int ue_id) {
    // Allocate or reallocate memory for the array
    UE_CONTEXT_T *new_array = realloc(*ue_array, (*size + 1) * sizeof(UE_CONTEXT_T));
    if (new_array == NULL) {
        perror("Failed to allocate memory");
        return -1;
    }

    *ue_array = new_array;

    // Initialize the new entry
    UE_CONTEXT_T *new_context = &(*ue_array)[*size];
    new_context->UE_ID = ue_id;
    new_context->RRC_connection_status = 0; // Initially disconnected

    // Allocate memory for MAC_CONTEXT_T and handle allocation failure
    new_context->mac_context = malloc(sizeof(MAC_CONTEXT_T));
    if (new_context->mac_context == NULL) {
        perror("Failed to allocate memory for MAC context");
        return -1;
    }

    // Initialize with a random MAC state
    srand(time(NULL) + ue_id);  // Seed based on UE_ID for uniqueness
    new_context->mac_context->MAC_STATE = rand() % 100;

    (*size)++;

    return 0; // Success
}

void remove_UE_context(UE_CONTEXT_T **ue_array, size_t *size, int ue_id) {
    if (*size == 0) return;

    for (size_t i = 0; i < *size; ++i) {
        if ((*ue_array)[i].UE_ID == ue_id) {
            free((*ue_array)[i].mac_context);

            // Shift elements to fill the gap
            memmove(&(*ue_array)[i], &(*ue_array)[i + 1], (*size - i - 1) * sizeof(UE_CONTEXT_T));

            // Reallocate memory for reduced size
            UE_CONTEXT_T *new_array = realloc(*ue_array, --(*size) * sizeof(UE_CONTEXT_T));
            if (new_array != NULL) {
                *ue_array = new_array;
            }
            return;
        }
    }
}

void update_RRC_connection_status(UE_CONTEXT_T **ue_array, size_t size, int ue_id, int status) {
    for (size_t i = 0; i < size; ++i) {
        if ((*ue_array)[i].UE_ID == ue_id) {
            // Update the RRC connection status
            (*ue_array)[i].RRC_connection_status = status;

            // Synchronize MAC_CONTEXT_T based on new status
            if (status == 1) { // Connected
                srand(time(NULL) + ue_id);  // Reseed for randomness consistency
                (*ue_array)[i].mac_context->MAC_STATE = rand() % 100;
            } else {
                // Clear or reset the MAC context state when disconnected
                (*ue_array)[i].mac_context->MAC_STATE = -1; // Example of a clear state
            }
            return;
        }
    }
}

void dump_active_ue_contexts_to_log(const UE_CONTEXT_T *ue_array, size_t size, const char *log_file) {
    FILE *file = fopen(log_file, "w");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        fprintf(file, "UE_ID: %d, RRC Status: %d, MAC_STATE: %d\n",
                ue_array[i].UE_ID,
                ue_array[i].RRC_connection_status,
                ue_array[i].mac_context->MAC_STATE);
    }

    fclose(file);
}
