#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SRB_ID 3

typedef struct LTE_ENB_SRB2_CONFIG {
    int SRB_ID;
    int SIB14_FLAG;
    int ENDC_FLAG;
    struct LTE_ENB_SRB2_CONFIG* next;
} LTE_ENB_SRB2_CONFIG;

typedef struct {
    LTE_ENB_SRB2_CONFIG* head;
    pthread_mutex_t lock;
} LinkedList;

void init_linked_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int is_valid_config(int SRB_ID, int SIB14_FLAG, int ENDC_FLAG) {
    return (SRB_ID >= 1 && SRB_ID <= MAX_SRB_ID) && 
           (SIB14_FLAG == 0 || SIB14_FLAG == 1) &&
           (ENDC_FLAG == 0 || ENDC_FLAG == 1);
}

void add_config(LinkedList* list, int SRB_ID, int SIB14_FLAG, int ENDC_FLAG) {
    if (!is_valid_config(SRB_ID, SIB14_FLAG, ENDC_FLAG)) {
        fprintf(stderr, "Invalid configuration parameters\n");
        return;
    }

    pthread_mutex_lock(&list->lock);

    LTE_ENB_SRB2_CONFIG* new_node = (LTE_ENB_SRB2_CONFIG*)malloc(sizeof(LTE_ENB_SRB2_CONFIG));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->SRB_ID = SRB_ID;
    new_node->SIB14_FLAG = SIB14_FLAG;
    new_node->ENDC_FLAG = ENDC_FLAG;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    LTE_ENB_SRB2_CONFIG* current = list->head;
    while (current != NULL) {
        LTE_ENB_SRB2_CONFIG* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void populate_linked_list(LinkedList* list, int configs[][3], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        add_config(list, configs[i][0], configs[i][1], configs[i][2]);
    }
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_lock` and `pthread_mutex_unlock` ensures that the linked list operations are thread-safe.
- **Memory Management**: Each node is dynamically allocated with `malloc`, and all nodes are freed properly in `free_linked_list`.
- **Validation**: Configuration parameters are validated before adding a new node to prevent invalid data from being stored.
- **Error Handling**: Basic error handling is implemented for memory allocation failures.']

['Here's a C implementation of the dynamic array management in a multi-threaded environment using pthreads for thread safety:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define INITIAL_CAPACITY 1024
#define RESIZE_THRESHOLD_FACTOR 0.75

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_dynamic_array(DynamicArray* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to resize dynamic array");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void add_pdu(DynamicArray* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity * RESIZE_THRESHOLD_FACTOR) {
        resize_dynamic_array(array);
    }

    if (array->size < array->capacity) {
        memcpy(&array->data[array->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->size++;
    } else {
        fprintf(stderr, "Failed to add element: Array is full.\n");
    }

    pthread_mutex_unlock(&array->lock);
}

void remove_pdu(DynamicArray* array, size_t index) {
    if (index >= array->size) return;

    pthread_mutex_lock(&array->lock);

    memmove(&array->data[index], &array->data[index + 1], (array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size--;

    pthread_mutex_unlock(&array->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &array->data[index];

    pthread_mutex_unlock(&array->lock);
    return pdu;
}

void free_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->data);
        free(array);
    }
}
```

### Key Points:
- **Thread Safety:** Uses `pthread_mutex_t` to ensure mutual exclusion during read/write operations.
- **Dynamic Resizing:** Resizes when the array reaches 75% capacity, doubling its size each time to balance between resizing frequency and memory usage.
- **Memory Management:** Allocates initial memory and resizes as needed using `realloc`, with checks for allocation failures.
- **Bounds Checking:** Ensures all accesses are within bounds to prevent undefined behavior.
- **Performance Considerations:** Uses a threshold factor to minimize frequent resizes, optimizing for large-scale data handling.

This code is designed to handle high-throughput environments efficiently while ensuring thread safety and preventing memory leaks.']

