#define MAX_CONNECTIONS 1024

typedef struct {
    char ip[16];
    int port;
    time_t timeout;
    time_t last_active;
    int socket_fd;
} Connection;

typedef struct {
    Connection connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
} ConnectionManager;

ConnectionManager manager = {0};

void initialize_manager() {
    pthread_mutex_init(&manager.lock, NULL);
}

int add_connection(const char* ip, int port, time_t timeout) {
    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager.connections[i].socket_fd == -1) {
            strncpy(manager.connections[i].ip, ip, sizeof(manager.connections[i].ip));
            manager.connections[i].port = port;
            manager.connections[i].timeout = timeout;
            manager.connections[i].last_active = time(NULL);
            manager.connections[i].socket_fd = -1; // No socket yet
            pthread_mutex_unlock(&manager.lock);
            return i;
        }
    }

    pthread_mutex_unlock(&manager.lock);
    return -1; // No space left
}

void remove_connection(int index) {
    if (index < 0 || index >= MAX_CONNECTIONS) return;

    pthread_mutex_lock(&manager.lock);
    close(manager.connections[index].socket_fd);
    manager.connections[index] = (Connection){0};
    pthread_mutex_unlock(&manager.lock);
}

int update_connection(int index, int port, time_t timeout) {
    if (index < 0 || index >= MAX_CONNECTIONS) return -1;

    pthread_mutex_lock(&manager.lock);

    strncpy(manager.connections[index].ip, manager.connections[index].ip, sizeof(manager.connections[index].ip));
    manager.connections[index].port = port;
    manager.connections[index].timeout = timeout;
    pthread_mutex_unlock(&manager.lock);

    return 0;
}

void reconnect_stale_connections() {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager.connections[i].socket_fd != -1 && 
            difftime(now, manager.connections[i].last_active) > manager.connections[i].timeout) {

            close(manager.connections[i].socket_fd);
            struct sockaddr_in addr;
            memset(&addr, 0, sizeof(addr));
            addr.sin_family = AF_INET;
            inet_pton(AF_INET, manager.connections[i].ip, &addr.sin_addr);
            addr.sin_port = htons(manager.connections[i].port);

            int sock = socket(AF_INET, SOCK_STREAM, 0);
            if (sock == -1) {
                perror("Socket creation failed");
                continue;
            }

            if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) == 0) {
                manager.connections[i].socket_fd = sock;
                printf("Reconnected to %s:%d\n", manager.connections[i].ip, manager.connections[i].port);
            } else {
                close(sock);
            }
        }
    }

    pthread_mutex_unlock(&manager.lock);
}

void cleanup_idle_connections() {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (difftime(now, manager.connections[i].last_active) > 2 * manager.connections[i].timeout) {
            close(manager.connections[i].socket_fd);
            memset(&manager.connections[i], 0, sizeof(Connection));
        }
    }

    pthread_mutex_unlock(&manager.lock);
}

void* monitor_connections(void* arg) {
    while (1) {
        reconnect_stale_connections();
        cleanup_idle_connections();
        sleep(5); // Adjust as needed
    }
    return NULL;
}

int main() {
    initialize_manager();

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_connections, NULL) != 0) {
        perror("Failed to create monitor thread");
        return EXIT_FAILURE;
    }

    int conn_index = add_connection("127.0.0.1", 8080, 10);
    update_connection(conn_index, 9090, 15);

    pthread_join(monitor_thread, NULL);

    remove_connection(conn_index);

    pthread_mutex_destroy(&manager.lock);

    return EXIT_SUCCESS;
}
```

