} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    mp->size = initial_size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* mp, size_t count) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + count > mp->size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* allocated = &mp->pool[mp->used];
    mp->used += count;
    pthread_mutex_unlock(&mp->lock);
    return allocated;
}

void deallocate_to_pool(MemoryPool* mp, size_t count) {
    pthread_mutex_lock(&mp->lock);
    if (count > 0) {
        mp->used -= count;
    }
    pthread_mutex_unlock(&mp->lock);
}

