#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

#define MAX_CAPACITY 10000
#define LOAD_FACTOR 0.75

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    unsigned char CRCFLAG; // Randomly set, can be 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

// Hash table entry for storing pointers to structures
typedef struct {
    unsigned int RNTI;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    int is_used;
} HashTableEntry;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
    HashTableEntry* hash_table;
    size_t hash_capacity;
} DynamicArray;

// Function prototypes
DynamicArray* init_dynamic_array(size_t initial_capacity);
void free_dynamic_array(DynamicArray* da);
int resize_if_needed(DynamicArray* da);
unsigned int hash_function(unsigned int RNTI, size_t hash_capacity);
void serialize_to_binary(const char* filename, const DynamicArray* da);
DynamicArray* deserialize_from_binary(const char* filename);
void log_changes(const char* message);

// Initialize dynamic array
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    pthread_mutex_init(&da->lock, NULL);
    pthread_rwlock_init(&da->rwlock, NULL);

    da->capacity = initial_capacity;
    da->size = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    assert(da->array != NULL);

    size_t hash_capacity = (size_t)(initial_capacity / LOAD_FACTOR) + 1;
    da->hash_table = (HashTableEntry*)calloc(hash_capacity, sizeof(HashTableEntry));
    assert(da->hash_table != NULL);

    return da;
}

// Free dynamic array
void free_dynamic_array(DynamicArray* da) {
    if (!da) return;

    for (size_t i = 0; i < da->capacity; ++i) {
        free(da->array[i]);
    }
    free(da->array);

    for (size_t i = 0; i < da->hash_capacity; ++i) {
        if (da->hash_table[i].is_used) {
            free(da->hash_table[i].pdu);
        }
    }
    free(da->hash_table);

    pthread_mutex_destroy(&da->lock);
    pthread_rwlock_destroy(&da->rwlock);
    free(da);
}

// Resize dynamic array if needed
int resize_if_needed(DynamicArray* da) {
    pthread_rwlock_wrlock(&da->rwlock);

    if (da->size >= da->capacity * LOAD_FACTOR) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_array = (NFAPI_CRC_INDICATION_PDU_T**)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_array) {
            pthread_rwlock_unlock(&da->rwlock);
            return -1;
        }

        for (size_t i = da->capacity; i < new_capacity; ++i) {
            new_array[i] = NULL;
        }

        da->array = new_array;
        da->capacity = new_capacity;

        size_t new_hash_capacity = (size_t)(new_capacity / LOAD_FACTOR) + 1;
        HashTableEntry* new_hash_table = (HashTableEntry*)realloc(da->hash_table, new_hash_capacity * sizeof(HashTableEntry));
        if (!new_hash_table) {
            pthread_rwlock_unlock(&da->rwlock);
            return -1;
        }

        memset(new_hash_table + da->hash_capacity, 0, (new_hash_capacity - da->hash_capacity) * sizeof(HashTableEntry));
        da->hash_table = new_hash_table;
        da->hash_capacity = new_hash_capacity;
    }

    pthread_rwlock_unlock(&da->rwlock);
    return 0;
}

// Hash function
unsigned int hash_function(unsigned int RNTI, size_t hash_capacity) {
    return RNTI % hash_capacity;
}

// Insert into dynamic array and handle duplicates
int insert_pdu(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_rwlock_wrlock(&da->rwlock);

    unsigned int index = resize_if_needed(da);
    if (index < 0) {
        pthread_rwlock_unlock(&da->rwlock);
        return -1;
    }

    size_t hash_index = hash_function(pdu->tag.RNTI, da->hash_capacity);
    while (da->hash_table[hash_index].is_used && da->hash_table[hash_index].RNTI != pdu->tag.RNTI) {
        hash_index = (hash_index + 1) % da->hash_capacity;
    }

    if (da->hash_table[hash_index].is_used) {
        free(da->hash_table[hash_index].pdu);
    }

    da->hash_table[hash_index].RNTI = pdu->tag.RNTI;
    da->hash_table[hash_index].pdu = pdu;
    da->hash_table[hash_index].is_used = 1;

    unsigned int array_index = hash_function(pdu->tag.RNTI, da->capacity);
    while (da->array[array_index]) {
        array_index = (array_index + 1) % da->capacity;
    }

    da->array[array_index] = pdu;
    ++da->size;

    log_changes("Inserted PDU");

    pthread_rwlock_unlock(&da->rwlock);
    return 0;
}

// Serialize to binary file
void serialize_to_binary(const char* filename, const DynamicArray* da) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_rwlock_rdlock(&da->rwlock);

    fwrite(&da->capacity, sizeof(size_t), 1, file);
    fwrite(&da->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < da->capacity; ++i) {
        if (da->array[i]) {
            CRC_INDICATION_REL8_TAG tag = { .RX_UE_INFORMATION_TAG = da->array[i]->tag.RX_UE_INFORMATION_TAG,
                                           .RNTI = da->array[i]->tag.RNTI };
            fwrite(&tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
            fwrite(&(da->array[i]->CRCFLAG), sizeof(unsigned char), 1, file);
        }
    }

    pthread_rwlock_unlock(&da->rwlock);
    fclose(file);
}

// Deserialize from binary file
DynamicArray* deserialize_from_binary(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    DynamicArray* da = init_dynamic_array(1000);

    pthread_rwlock_wrlock(&da->rwlock);

    fread(&da->capacity, sizeof(size_t), 1, file);
    fread(&da->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < da->capacity && da->size > 0; ++i) {
        CRC_INDICATION_REL8_TAG tag;
        if (fread(&tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file)) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->tag.RX_UE_INFORMATION_TAG = tag.RX_UE_INFORMATION_TAG;
            pdu->tag.RNTI = tag.RNTI;
            if (fread(&(pdu->CRCFLAG), sizeof(unsigned char), 1, file)) {
                insert_pdu(da, pdu);
            } else {
                free(pdu);
            }
        }
    }

    pthread_rwlock_unlock(&da->rwlock);
    fclose(file);

    return da;
}

// Log changes
void log_changes(const char* message) {
    // Implement logging mechanism here, e.g., using a simple file or an existing logging framework.
    printf("%s\n", message);  // Placeholder for actual logging implementation
}
