#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_CAPACITY 1000
#define MAX_ELEMENTS 50000
#define RETRY_LIMIT 3

typedef struct {
    uint32_t RNTI;
    time_t timestamp; // for prioritization based on urgency
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// External logging function prototype
void log_event(const char* message);

// Utility functions
bool is_unique(uint32_t rnti, const DynamicArray* array);
uint32_t generate_unique_rnti(const DynamicArray* array);
bool resize_array(DynamicArray *arr);

DynamicArray* init_dynamic_array() {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (!arr) {
        log_event("Memory allocation failed for dynamic array structure.");
        return NULL;
    }
    arr->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        log_event("Memory allocation failed for initial array data.");
        return NULL;
    }
    arr->size = 0;
    arr->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_dynamic_array(DynamicArray* arr) {
    if (arr) {
        free(arr->array);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

bool resize_array(DynamicArray *arr) {
    size_t new_capacity = arr->capacity * 2;
    if (new_capacity > MAX_ELEMENTS) {
        return false; // Cannot exceed maximum elements
    }

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        log_event("Memory reallocation failed.");
        return false;
    }
    arr->array = temp;
    arr->capacity = new_capacity;
    return true;
}

bool add_element(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->lock);

    for (int retries = 0; retries < RETRY_LIMIT; ++retries) {
        if (!is_unique(element.ue_info.RNTI, arr)) {
            element.ue_info.RNTI = generate_unique_rnti(arr);
        } else {
            break;
        }
    }

    if (!is_unique(element.ue_info.RNTI, arr)) {
        log_event("Failed to generate unique RNTI after retries.");
        pthread_mutex_unlock(&arr->lock);
        return false;
    }

    if (arr->size >= arr->capacity) {
        if (!resize_array(arr)) {
            pthread_mutex_unlock(&arr->lock);
            return false; // Unable to resize
        }
    }

    arr->array[arr->size++] = element;

    pthread_mutex_unlock(&arr->lock);
    return true;
}

bool is_unique(uint32_t rnti, const DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].ue_info.RNTI == rnti) {
            return false;
        }
    }
    return true;
}

uint32_t generate_unique_rnti(const DynamicArray* array) {
    // Simple example of generating a unique RNTI
    uint32_t new_rnti = rand() % (1 << 24); // Randomly pick a 24-bit number
    while (!is_unique(new_rnti, array)) {
        new_rnti = rand() % (1 << 24);
    }
    return new_rnti;
}

