from flask import Flask, request, jsonify
from threading import Lock

app = Flask(__name__)

# Simulating a simple in-memory database with thread-safe operations
tags_db = {}
lock = Lock()

def fetch_tags(resource_id):
    return tags_db.get(resource_id, set())

@app.route('/tags/<resource_id>', methods=['GET', 'POST', 'PUT', 'DELETE'])
def manage_tags(resource_id):
    action = request.method

    # Fetch existing tags
    with lock:
        resource_tags = fetch_tags(resource_id)

    if action == 'GET':
        return jsonify(list(resource_tags))

    elif action == 'POST' or action == 'PUT':
        # Expecting a JSON body containing either a single tag or a list of tags
        data = request.json
        new_tags = set(data.get('tags', [])) if isinstance(data, dict) else {data}

        with lock:
            if action == 'POST':
                resource_tags.update(new_tags)
            elif action == 'PUT':
                resource_tags.clear()
                resource_tags.update(new_tags)

            tags_db[resource_id] = resource_tags

        return jsonify(list(resource_tags))

    elif action == 'DELETE':
        tag_to_remove = request.json.get('tag')

        with lock:
            if tag_to_remove in resource_tags:
                resource_tags.remove(tag_to_remove)
                tags_db[resource_id] = resource_tags

        return jsonify(list(resource_tags)), 204

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
```

