['Below is an example implementation of a thread-safe C function to manage a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures. This code uses mutexes for synchronization and provides logging capabilities.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    int successful_ops;
    int failed_ops;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->lock, NULL);
    da->successful_ops = 0;
    da->failed_ops = 0;
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

int resize_if_needed(DynamicArray *da) {
    if (da->size >= da->capacity && da->capacity < MAX_SIZE) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    } else if (da->size >= MAX_SIZE) {
        return 0; // Max size reached, cannot resize further
    }
    return 1;
}

void add_crc_indication(DynamicArray *da, int rx_ue_tag, int rnti) {
    pthread_mutex_lock(&da->lock);

    if (resize_if_needed(da) <= 0) {
        printf("Failed to allocate memory or max size reached.\n");
        da->failed_ops++;
        pthread_mutex_unlock(&da->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    da->array[da->size] = pdu;
    da->size++;
    da->successful_ops++;

    pthread_mutex_unlock(&da->lock);
}

void log_operations(DynamicArray *da) {
    printf("Successful operations: %d\n", da->successful_ops);
    printf("Failed operations: %d\n", da->failed_ops);
}

int main() {
    DynamicArray da;
    init_dynamic_array(&da, 10);

    // Simulate adding CRC indications
    for (int i = 0; i < 150; ++i) {
        add_crc_indication(&da, i, i * 100 + 1);
    }

    log_operations(&da);
    destroy_dynamic_array(&da);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` is used to ensure that only one thread can modify the dynamic array at a time.
- **Dynamic Resizing**: The array resizes when needed, doubling its capacity until it reaches the maximum size limit.
- **Logging**: Logs successful and failed operations due to memory constraints or reaching the max size.
- **Error Handling**: Handles memory allocation failures gracefully.
- **Scalability**: Designed to handle increasing loads by resizing dynamically.']

