// Mutex for thread safety
pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu_array(size_t n, size_t max_allocation_size) {
    if (max_allocation_size == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t allocated_count = 0;

    while (allocated_count < n) {
        size_t chunk_size = (n - allocated_count > max_allocation_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) ?
                            max_allocation_size / sizeof(NFAPI_CRC_INDICATION_PDU_T) :
                            n - allocated_count;

        pthread_mutex_lock(&allocation_mutex);
        NFAPI_CRC_INDICATION_PDU_T *new_chunk = (NFAPI_CRC_INDICATION_PDU_T *)malloc(chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_chunk) {
            // Handle allocation failure
            free(array);
            pthread_mutex_unlock(&allocation_mutex);
            return NULL;
        }

        for (size_t i = 0; i < chunk_size; ++i) {
            // Populate the structure with example data.
            new_chunk[i].rx_ue_info = /* Initialize RX_UE_INFORMATION_TAG */;
            new_chunk[i].rnti = allocated_count + i; // Example RNTI
            new_chunk[i].crc_indication_rel8_tag.crcflag = (allocated_count + i) % 2 == 0 ? 1 : 0;
        }

        size_t current_size = array ? allocated_count * sizeof(NFAPI_CRC_INDICATION_PDU_T) : 0;
        NFAPI_CRC_INDICATION_PDU_T *temp_array = realloc(array, current_size + chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            free(new_chunk);
            pthread_mutex_unlock(&allocation_mutex);
            free(array);
            return NULL;
        }

        array = temp_array;
        memcpy((char *)array + current_size, new_chunk, chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        log_allocation_success(chunk_size);
        allocated_count += chunk_size;

        pthread_mutex_unlock(&allocation_mutex);
        free(new_chunk);
    }

    return array;
}
