#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int rnti;
    time_t timestamp;
    unsigned int packet_count;
} MAC_RX_RNTI_STATS_T;

typedef struct {
    MAC_RX_RNTI_STATS_T *array;
    size_t capacity;
    size_t count;
} DynamicArray;

// Function to initialize the dynamic array
void initDynamicArray(DynamicArray *dynamicArray, size_t initialCapacity) {
    dynamicArray->capacity = initialCapacity;
    dynamicArray->count = 0;
    dynamicArray->array = (MAC_RX_RNTI_STATS_T *)malloc(initialCapacity * sizeof(MAC_RX_RNTI_STATS_T));
}

// Function to resize the dynamic array
void resizeDynamicArray(DynamicArray *dynamicArray) {
    size_t newCapacity = dynamicArray->capacity * 2;
    MAC_RX_RNTI_STATS_T *newArray = (MAC_RX_RNTI_STATS_T *)realloc(dynamicArray->array, newCapacity * sizeof(MAC_RX_RNTI_STATS_T));
    if (newArray != NULL) {
        dynamicArray->array = newArray;
        dynamicArray->capacity = newCapacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to update or add a MAC_RX_RNTI_STATS_T entry
void updateDynamicArray(DynamicArray *dynamicArray, int rnti, unsigned int packetCount) {
    time_t currentTime = time(NULL);

    for (size_t i = 0; i < dynamicArray->count; ++i) {
        if (dynamicArray->array[i].rnti == rnti) {
            dynamicArray->array[i].timestamp = currentTime;
            dynamicArray->array[i].packet_count += packetCount;
            return;
        }
    }

    // If RNTI is not found, add a new entry
    if (dynamicArray->count == dynamicArray->capacity) {
        resizeDynamicArray(dynamicArray);
    }

    dynamicArray->array[dynamicArray->count].rnti = rnti;
    dynamicArray->array[dynamicArray->count].timestamp = currentTime;
    dynamicArray->array[dynamicArray->count].packet_count = packetCount;
    ++dynamicArray->count;
}

// Function to compute cumulative packet loss percentage
double computePacketLossPercentage(DynamicArray *dynamicArray, size_t expectedPackets) {
    unsigned int totalReceived = 0;
    for (size_t i = 0; i < dynamicArray->count; ++i) {
        totalReceived += dynamicArray->array[i].packet_count;
    }

    if (expectedPackets == 0) return 0.0;

    double lossPercentage = 100.0 * (1.0 - ((double)totalReceived / expectedPackets));
    return lossPercentage;
}

// Example usage
int main() {
    DynamicArray dynamicArray;
    initDynamicArray(&dynamicArray, 10);

    updateDynamicArray(&dynamicArray, 1001, 5);
    updateDynamicArray(&dynamicArray, 1002, 3);
    updateDynamicArray(&dynamicArray, 1001, 7); // Update existing entry

    printf("Packet Loss Percentage: %.2f%%\n", computePacketLossPercentage(&dynamicArray, 20));

    free(dynamicArray.array);

    return 0;
}
```

This code initializes a dynamic array of `MAC_RX_RNTI_STATS_T` structures, handles updates, resizes the array when necessary, and computes packet loss percentage. The resizing strategy doubles the capacity to minimize reallocation frequency, ensuring efficient memory usage in high-throughput scenarios.']

