#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

// Assume these are defined elsewhere
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    atomic_size_t size;
    pthread_mutex_t lock;
    // Placeholder for external logging library integration
    void (*log)(const char*);
} DynamicList;

// Function prototypes
void initialize_list(DynamicList* list, void (*log_func)(const char*));
int insert_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element);
int delete_element(DynamicList* list, int RNTI);
void cleanup_list(DynamicList* list);
NFAPI_CRC_INDICATION_PDU_T create_pdu(int RX_UE_INFORMATION_TAG, int RNTI, unsigned int CRCFLAG);

// Global configuration
#define MEMORY_CHUNK_SIZE 1024
#define MAX_MEMORY_THRESHOLD 8192
#define LOG_LEVEL_INFO 1

DynamicList global_list;
void external_log(const char* message) {
    // Implement logging logic here
    printf("%s\n", message);
}

void initialize_list(DynamicList* list, void (*log_func)(const char*)) {
    pthread_mutex_init(&list->lock, NULL);
    atomic_store(&list->size, 0);
    list->head = NULL;
    list->log = log_func;
}

int insert_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        list->log("Memory allocation failed for new node.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    atomic_fetch_add(&list->size, 1);

    if (atomic_load(&list->size) > MAX_MEMORY_THRESHOLD) {
        // Implement disk-based storage logic here
        list->log("Memory threshold exceeded. Consider swapping to disk.");
    }

    pthread_mutex_unlock(&list->lock);
    list->log("Element inserted successfully.");
    return 0;
}

int delete_element(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Element not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    atomic_fetch_sub(&list->size, 1);

    pthread_mutex_unlock(&list->lock);
    list->log("Element deleted successfully.");
    return 0;
}

void cleanup_list(DynamicList* list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    atomic_store(&list->size, 0);
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int RX_UE_INFORMATION_TAG, int RNTI, unsigned int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Set fields according to the predefined algorithm
    pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu.RNTI = RNTI;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG; // Assume a logic to set CRCFLAG
    return pdu;
}

int main() {
    initialize_list(&global_list, external_log);

    NFAPI_CRC_INDICATION_PDU_T example_pdu = create_pdu(1, 1234, 0xABCD);
    insert_element(&global_list, example_pdu);

    delete_element(&global_list, 1234);
    cleanup_list(&global_list);

    return 0;
}
```

