typedef struct Node {
    LTE_RRC_MessageType data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

void initialize_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int validate_entry(const LTE_RRC_MessageType* entry) {
    // Implement validation logic here
    return 1; // Assume valid for now
}

void add_entry(List* list, const LTE_RRC_MessageType* entry) {
    if (!validate_entry(entry)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    memcpy(&new_node->data, entry, sizeof(LTE_RRC_MessageType));
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void* background_cleanup(void* arg) {
    List* list = (List*)arg;
    while (1) {
        sleep(60); // Run cleanup every 60 seconds

        pthread_mutex_lock(&list->lock);
        Node *current = list->head, *prev = NULL;
        time_t current_time = time(NULL);

        while (current) {
            if ((current_time - current->data.Timestamp) > 3600) { // Example: remove entries older than 1 hour
                if (prev) prev->next = current->next;
                else list->head = current->next;

                Node* temp = current;
                current = current->next;
                free(temp);
            } else {
                prev = current;
                current = current->next;
            }
        }
        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

void query_entries_by_UE_ID(List* list, int UE_ID) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current) {
        if (current->data.UE_ID == UE_ID) {
            // Process or print entry
            printf("Found: UE_ID=%d, Message=%s\n", current->data.UE_ID, current->data.Message);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void query_entries_by_timestamp(List* list, time_t timestamp) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current) {
        if (current->data.Timestamp == timestamp) {
            // Process or print entry
            printf("Found: Timestamp=%ld, Message=%s\n", current->data.Timestamp, current->data.Message);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void log_performance_metrics(const char* message) {
    // Implement logging logic here
    printf("%s\n", message);
}

void shutdown_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

int main() {
    List list;
    initialize_list(&list);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, background_cleanup, &list);

    // Simulate adding entries
    LTE_RRC_MessageType entry = {1, "Hello", time(NULL)};
    add_entry(&list, &entry);

    query_entries_by_UE_ID(&list, 1);
    query_entries_by_timestamp(&list, entry.Timestamp);

    log_performance_metrics("Performance metrics logged.");

    pthread_cancel(cleanup_thread);
    pthread_join(cleanup_thread, NULL);

    shutdown_list(&list);

    return 0;
}
