#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>

typedef struct {
    int UE_ID;
    char Message[256];
    time_t Timestamp;
} LTE_RRC_MessageType;

#define MAX_FILES 100
#define MAX_MESSAGES 10000

typedef struct {
    LTE_RRC_MessageType *messages;
    size_t count;
    pthread_mutex_t lock;
    size_t valid_messages;
    double avg_age;
    double max_weighted_sum;
    double total_age;
} MessageArray;

MessageArray global_array = {0};

void validate_message(const LTE_RRC_MessageType *msg, int *valid);
double calculate_weighted_sum(const char *message);

pthread_mutex_t metrics_lock = PTHREAD_MUTEX_INITIALIZER;

void update_metrics(MessageArray *array, const LTE_RRC_MessageType *msg) {
    pthread_mutex_lock(&metrics_lock);

    array->total_age += difftime(time(NULL), msg->Timestamp);
    array->valid_messages++;

    double current_weighted_sum = calculate_weighted_sum(msg->Message);
    if (current_weighted_sum > array->max_weighted_sum) {
        array->max_weighted_sum = current_weighted_sum;
    }

    pthread_mutex_unlock(&metrics_lock);
}

void process_file(const char *file_path, MessageArray *array) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) return;

    LTE_RRC_MessageType msg;
    int valid = 0;

    while (fscanf(fp, "%d %255s %ld", &msg.UE_ID, msg.Message, &msg.Timestamp) == 3) {
        validate_message(&msg, &valid);
        if (valid) {
            pthread_mutex_lock(&array->lock);

            if (array->count < MAX_MESSAGES) {
                array->messages[array->count++] = msg;
                update_metrics(array, &msg);
            }

            pthread_mutex_unlock(&array->lock);
        }
    }

    fclose(fp);
}

void *thread_func(void *arg) {
    char **files = (char **)arg;
    MessageArray *array = &global_array;

    for (int i = 0; files[i] != NULL; ++i) {
        process_file(files[i], array);
    }

    return NULL;
}

void manage_messages(const char *directory_path) {
    pthread_t threads[10];
    DIR *dir = opendir(directory_path);
    if (!dir) return;

    struct dirent *entry;
    char file_paths[MAX_FILES][256];

    size_t file_count = 0;
    while ((entry = readdir(dir)) && file_count < MAX_FILES) {
        if (entry->d_type == DT_REG) {
            snprintf(file_paths[file_count], sizeof(file_paths[file_count]), "%s/%s", directory_path, entry->d_name);
            ++file_count;
        }
    }

    closedir(dir);

    global_array.messages = malloc(sizeof(LTE_RRC_MessageType) * MAX_MESSAGES);
    global_array.count = 0;
    pthread_mutex_init(&global_array.lock, NULL);

    size_t num_threads = file_count > 10 ? 10 : file_count;
    char **thread_files = malloc(num_threads * sizeof(char *));

    for (size_t i = 0; i < num_threads; ++i) {
        thread_files[i] = &file_paths[i * (file_count / num_threads)];
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_func, (void *)thread_files);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(thread_files);

    printf("Total Valid Messages: %zu\n", global_array.valid_messages);
    if (global_array.valid_messages > 0) {
        printf("Average Message Age: %.2f seconds\n", global_array.total_age / global_array.valid_messages);
    }
    printf("Max Weighted Sum: %.2f\n", global_array.max_weighted_sum);

    free(global_array.messages);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    manage_messages(argv[1]);

    return EXIT_SUCCESS;
}
```

