typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t max_size;
    size_t current_size;
    pthread_mutex_t lock;
} PDU_Manager;

// Initialize the PDU manager
int pdu_manager_init(PDU_Manager *manager, size_t max_elements) {
    if (!manager || max_elements == 0) return -1;

    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) return -2; // Memory allocation failure

    manager->max_size = max_elements;
    manager->current_size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    srand(time(NULL)); // Seed the random number generator
    return 0;
}

// Add a new PDU to the manager
int pdu_manager_add(PDU_Manager *manager) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);
    if (manager->current_size >= manager->max_size) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Max capacity reached
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[manager->current_size];
    pdu->RX_UE_INFORMATION_TAG = rand();  // Example random value
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2); // Random CRCFLAG

    manager->current_size++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Clean up the PDU manager resources
void pdu_manager_cleanup(PDU_Manager *manager) {
    if (!manager) return;

    free(manager->pdus);
    pthread_mutex_destroy(&manager->lock);
}

