#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure based on your specifications.
typedef struct {
    int UESRVCC_INDICATOR;
    int ECGI;  // Assuming ECGI is an integer for simplicity.
    unsigned int RRC_Cause_Bitmask;  // Bitmask to represent multiple RRC causes.
} NFAPI_RACH_INDICATION_PDU_T;

typedef struct {
    NFAPI_RACH_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArrayManager;

// Initialize the dynamic array manager
void initDynamicArrayManager(DynamicArrayManager *manager) {
    manager->size = 0;
    manager->capacity = 10;  // Initial capacity.
    manager->array = (NFAPI_RACH_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_RACH_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the dynamic array
void resizeDynamicArray(DynamicArrayManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_RACH_INDICATION_PDU_T *new_array = (NFAPI_RACH_INDICATION_PDU_T *)realloc(manager->array, new_capacity * sizeof(NFAPI_RACH_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->array = new_array;
    manager->capacity = new_capacity;
}

// Add or update an entry in the dynamic array
void addOrUpdateEntry(DynamicArrayManager *manager, NFAPI_RACH_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].ECGI == entry.ECGI) { // Assuming ECGI as unique identifier
            manager->array[i] = entry;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->size >= manager->capacity) {
        resizeDynamicArray(manager);
    }

    manager->array[manager->size++] = entry;
    pthread_mutex_unlock(&manager->lock);
}

// Iterate over the dynamic array and process entries based on RRC Cause conditions
void iterateAndProcessEntries(DynamicArrayManager *manager, void (*processFunction)(NFAPI_RACH_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        processFunction(&(manager->array[i]));
    }

    pthread_mutex_unlock(&manager->lock);
}

// Free the resources used by the dynamic array manager
void freeDynamicArrayManager(DynamicArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->array);
    manager->size = 0;
    manager->capacity = 0;

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example process function
void processRRC_Cause(NFAPI_RACH_INDICATION_PDU_T *entry) {
    // Process based on RRC Cause Bitmask, example:
    if (entry->RRC_Cause_Bitmask & 0x01) { // Check if the first cause is set
        printf("Processing RRC Cause for ECGI: %d\n", entry->ECGI);
    }
}

int main() {
    DynamicArrayManager manager;
    initDynamicArrayManager(&manager);

    NFAPI_RACH_INDICATION_PDU_T pdu1 = {1, 1001, 0x01};
    addOrUpdateEntry(&manager, pdu1);

    iterateAndProcessEntries(&manager, processRRC_Cause);

    freeDynamicArrayManager(&manager);
    return 0;
}
