        pthread_mutex_lock(&list_mutex);

        time_t now = time(NULL);
        for (int i = 0; i < lte_count; ++i) {
            if (difftime(now, lte_list[i].Timestamp) > 3600) { // Cleanup stale entries older than an hour
                memmove(lte_list + i, lte_list + i + 1, (lte_count - i - 1) * sizeof(LTE_RRC_MessageType));
                --lte_count;
                --i; // re-check the same index
            }
        }

        pthread_mutex_unlock(&list_mutex);
        sleep(60); // Run validation every minute
    }
}

bool add_lte_entry(int UE_ID, const char* Message, time_t Timestamp) {
    if (lte_count >= MAX_ENTRIES) return false;

    pthread_mutex_lock(&list_mutex);

    LTE_RRC_MessageType entry = {UE_ID, "", 0};
    strncpy(entry.Message, Message, sizeof(entry.Message));
    entry.Timestamp = Timestamp;

    lte_list[lte_count++] = entry;

    pthread_mutex_unlock(&list_mutex);
    return true;
}

bool add_crc_entry(bool valid_RX_UE_INFORMATION_TAG, int RNTI, unsigned int CRC_INDICATION_REL8_TAG) {
    if (crc_count >= MAX_ENTRIES) return false;

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T entry = {valid_RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, rand() % 2};
    crc_list[crc_count++] = entry;

    pthread_mutex_unlock(&list_mutex);
    return true;
}

LTE_RRC_MessageType* query_by_ue_id(int UE_ID) {
    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < lte_count; ++i) {
        if (lte_list[i].UE_ID == UE_ID) {
            pthread_mutex_unlock(&list_mutex);
            return &lte_list[i];
        }
    }

    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

LTE_RRC_MessageType* query_by_timestamp(time_t Timestamp) {
    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < lte_count; ++i) {
        if (lte_list[i].Timestamp == Timestamp) {
            pthread_mutex_unlock(&list_mutex);
            return &lte_list[i];
        }
    }

    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void shutdown() {
    pthread_cancel(validation_thread);
    pthread_join(validation_thread, NULL);

    free(lte_list);
    free(crc_list);
}

int main() {
    initialize_lists();

    // Example usage
    add_lte_entry(12345, "Test Message", time(NULL));
    NFAPI_CRC_INDICATION_PDU_T example_crc = {true, 6789, 0xABCD};
    add_crc_entry(example_crc.valid_RX_UE_INFORMATION_TAG, example_crc.RNTI, example_crc.CRC_INDICATION_REL8_TAG);

    LTE_RRC_MessageType* entry = query_by_ue_id(12345);
    if (entry) {
        printf("Found Message: %s\n", entry->Message);
    }

    shutdown();
    return 0;
}
