#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef enum { EVENT_TYPE_A, EVENT_TYPE_B } EventType;

typedef struct {
    int id;
    long timestamp;
    EventType type;
    char *data;
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventArray;

// Initialize dynamic array
void initEventArray(EventArray *array) {
    array->capacity = 10; // Starting with a small capacity for demonstration
    array->count = 0;
    array->events = (NetworkEvent **)malloc(array->capacity * sizeof(NetworkEvent *));
    pthread_mutex_init(&array->lock, NULL);
}

// Resize dynamic array if needed
void resizeIfNeeded(EventArray *array) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkEvent **new_events = realloc(array->events, new_capacity * sizeof(NetworkEvent *));
        if (new_events) {
            array->events = new_events;
            array->capacity = new_capacity;
        } else {
            fprintf(stderr, "Failed to resize event array.\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Add a new event
void addEvent(EventArray *array, NetworkEvent *event) {
    pthread_mutex_lock(&array->lock);

    resizeIfNeeded(array);

    // Allocate space for the data field
    char *data_copy = strdup(event->data);
    if (!data_copy) {
        fprintf(stderr, "Failed to allocate memory for event data.\n");
        exit(EXIT_FAILURE);
    }

    NetworkEvent *new_event = malloc(sizeof(NetworkEvent));
    if (!new_event) {
        free(data_copy);
        pthread_mutex_unlock(&array->lock);
        fprintf(stderr, "Failed to allocate memory for new event.\n");
        exit(EXIT_FAILURE);
    }

    *new_event = (NetworkEvent){
        .id = array->count,
        .timestamp = event->timestamp,
        .type = event->type,
        .data = data_copy
    };

    array->events[array->count++] = new_event;

    pthread_mutex_unlock(&array->lock);
}

// Retrieve events by timestamp
void getEventsByTimestamp(EventArray *array, long timestamp, NetworkEvent ***results, size_t *result_count) {
    pthread_mutex_lock(&array->lock);

    // Allocate a temporary buffer to store matching events
    *results = malloc(array->count * sizeof(NetworkEvent *));
    if (!*results) {
        fprintf(stderr, "Failed to allocate memory for results.\n");
        exit(EXIT_FAILURE);
    }

    size_t match_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i]->timestamp == timestamp) {
            (*results)[match_count++] = array->events[i];
        }
    }

    *result_count = match_count;

    pthread_mutex_unlock(&array->lock);
}

// Update event by unique identifier
void updateEvent(EventArray *array, int id, long new_timestamp, EventType new_type, const char *new_data) {
    pthread_mutex_lock(&array->lock);

    if (id < 0 || id >= array->count) {
        fprintf(stderr, "Invalid event ID.\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    // Free old data
    free(array->events[id]->data);

    // Update the event fields
    array->events[id]->timestamp = new_timestamp;
    array->events[id]->type = new_type;

    // Allocate space for the new data field
    char *new_data_copy = strdup(new_data);
    if (!new_data_copy) {
        fprintf(stderr, "Failed to allocate memory for new event data.\n");
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }

    array->events[id]->data = new_data_copy;

    pthread_mutex_unlock(&array->lock);
}

// Free the dynamic array and its resources
void freeEventArray(EventArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->events[i]->data);
        free(array->events[i]);
    }

    free(array->events);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    EventArray events;
    initEventArray(&events);

    // Example usage
    NetworkEvent event1 = { .timestamp = 123456, .type = EVENT_TYPE_A, .data = "Sample data" };
    addEvent(&events, &event1);

    long timestamp_to_find = 123456;
    NetworkEvent **results = NULL;
    size_t result_count;

    getEventsByTimestamp(&events, timestamp_to_find, &results, &result_count);

    // Update the event
    updateEvent(&events, 0, 654321, EVENT_TYPE_B, "Updated data");

    // Clean up
    free(results);
    freeEventArray(&events);

    return 0;
}
