#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define LOG_BUFFER_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG:1; // Using bit field for random CRCFLAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    FILE* log_file;
} PduList;

void initialize_list(PduList* list, size_t max_size) {
    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    list->log_file = fopen("pdu_log.txt", "a");
}

void log_pdu_action(const char* action, NFAPI_CRC_INDICATION_PDU_T pdu) {
    time_t now = time(NULL);
    char buffer[LOG_BUFFER_SIZE];
    snprintf(buffer, LOG_BUFFER_SIZE,
             "[%s] Action: %s - RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %u\n",
             ctime(&now), action, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
    fwrite(buffer, 1, strlen(buffer), list->log_file);
}

void add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_size) {
        printf("Maximum capacity exceeded. PDU queued.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->pdu = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    log_pdu_action("Created", pdu);

    pthread_mutex_unlock(&list->lock);
}

void remove_pdu(PduList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        printf("No PDUs to remove.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* temp = list->head;
    list->head = list->head->next;
    log_pdu_action("Removed", temp->pdu);

    free(temp);
    list->count--;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(PduList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;

    fclose(list->log_file);
    pthread_mutex_unlock(&list->lock);
}

void set_max_size(PduList* list, size_t new_max_size) {
    pthread_mutex_lock(&list->lock);

    if (new_max_size < list->count) {
        printf("New maximum size is less than current count. Adjusting...\n");
    }
    list->max_size = new_max_size;

    pthread_mutex_unlock(&list->lock);
}

void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
}

int main() {
    srand(time(NULL));

    PduList list;
    initialize_list(&list, 100);

    NFAPI_CRC_INDICATION_PDU_T example_pdu;
    example_pdu.RX_UE_INFORMATION_TAG = 12345;
    example_pdu.RNTI = 67890;

    generate_random_crcflag(&example_pdu);
    add_pdu(&list, example_pdu);

    // Example of removing a PDU
    remove_pdu(&list);

    set_max_size(&list, 200);

    cleanup_list(&list);

    return 0;
}
