#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Define structures for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a thread-safe list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PDUList;

// Function to initialize the PDU List
int init_pdu_list(PDUList* pdu_list, size_t max_elements) {
    if (!pdu_list) return -1;

    pdu_list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list->pdus) return -1;

    pdu_list->capacity = max_elements;
    pdu_list->count = 0;

    pthread_mutex_init(&pdu_list->lock, NULL);
    pthread_cond_init(&pdu_list->cond, NULL);

    return 0;
}

// Function to free the PDU List
void destroy_pdu_list(PDUList* pdu_list) {
    if (!pdu_list) return;

    free(pdu_list->pdus);

    pthread_mutex_destroy(&pdu_list->lock);
    pthread_cond_destroy(&pdu_list->cond);
}

// Thread-safe function to add a new PDU
int add_pdu(PDUList* pdu_list, RX_UE_INFORMATION_TAG ue_info, int rnti) {
    if (!pdu_list || pdu_list->count >= pdu_list->capacity)
        return -1;

    pthread_mutex_lock(&pdu_list->lock);

    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    new_pdu.ue_info = ue_info;
    new_pdu.rnti = rnti;
    srand((unsigned int)time(NULL));
    new_pdu.crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pdu_list->pdus[pdu_list->count++] = new_pdu;

    pthread_cond_signal(&pdu_list->cond);
    pthread_mutex_unlock(&pdu_list->lock);

    return 0;
}

// Thread-safe function to fetch a PDU (for processing)
int get_pdu(PDUList* pdu_list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu_list || !pdu)
        return -1;

    pthread_mutex_lock(&pdu_list->lock);

    while (pdu_list->count == 0) {
        pthread_cond_wait(&pdu_list->cond, &pdu_list->lock);
    }

    *pdu = pdu_list->pdus[0];
    memmove(pdu_list->pdus, pdu_list->pdus + 1, (--pdu_list->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&pdu_list->lock);

    return 0;
}

// Example usage of the PDU List
void* process_pdu(void* arg) {
    PDUList* pdu_list = (PDUList*)arg;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (get_pdu(pdu_list, &pdu) == 0) {
        // Process the PDU...
        printf("Processing PDU with RNTI: %d and CRCFLAG: %u\n", pdu.rnti, pdu.crc_tag.CRCFLAG);
    }

    return NULL;
}

int main() {
    PDUList pdu_list;
    init_pdu_list(&pdu_list, 10);

    pthread_t threads[2];
    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, process_pdu, &pdu_list);
    }

    RX_UE_INFORMATION_TAG ue_info;
    int rnti = 1;

    for (int i = 0; i < 12; ++i) { // Attempt to add more PDUs than capacity
        if (add_pdu(&pdu_list, ue_info, rnti + i) == -1) {
            printf("Failed to add PDU\n");
        }
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_pdu_list(&pdu_list);

    return 0;
}
