#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

// Function declarations
void initializeRecords(Record **records, size_t num_records, int key_min, int key_max);
void freeRecords(Record *records);
int compareByKey(const void *a, const void *b);
int compareByOffset(const void *a, const void *b);
void sortRecords(Record *records, size_t num_records, int (*compare)(const void *, const void *), int ascending);

// Thread-safe random number generator
pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned int thread_safe_random(int min, int max) {
    pthread_mutex_lock(&rand_mutex);
    unsigned int range = (max - min + 1);
    unsigned int num = rand() % range;
    pthread_mutex_unlock(&rand_mutex);
    return min + num;
}

// Function to initialize records
void initializeRecords(Record **records, size_t num_records, int key_min, int key_max) {
    *records = (Record *)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].offset = (long)i;
        (*records)[i].key = thread_safe_random(key_min, key_max);
    }
}

// Function to free records
void freeRecords(Record *records) {
    if (records != NULL) {
        free(records);
    }
}

// Comparison functions for sorting
int compareByKey(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;
    return recordA->key - recordB->key;
}

int compareByOffset(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;
    if (recordA->offset < recordB->offset)
        return -1;
    else if (recordA->offset > recordB->offset)
        return 1;
    else
        return 0;
}

// Function to sort records
void sortRecords(Record *records, size_t num_records, int (*compare)(const void *, const void *), int ascending) {
    qsort(records, num_records, sizeof(Record), compare);
    if (!ascending) {
        for (size_t i = 0; i < num_records / 2; ++i) {
            Record temp = records[i];
            records[i] = records[num_records - i - 1];
            records[num_records - i - 1] = temp;
        }
    }
}

// Example usage
int main() {
    size_t num_records = 100000;
    int key_min = 0, key_max = 100;
    Record *records;

    initializeRecords(&records, num_records, key_min, key_max);

    // Sort by key in ascending order
    sortRecords(records, num_records, compareByKey, 1);

    // Free allocated memory
    freeRecords(records);

    return 0;
}
