#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define SYSTEM_MEMORY_LIMIT 1024 * 1024 // Example: 1 MB limit
#define CACHE_SIZE 128

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* cache[CACHE_SIZE];
static int cache_index = 0;

uint32_t pseudo_random(uint32_t *seed) {
    *seed ^= (*seed << 13);
    *seed ^= (*seed >> 17);
    *seed ^= (*seed << 5);
    return *seed;
}

void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T** allocate_crc_pdu_array(size_t N, uint32_t seed) {
    if (N == 0 || SYSTEM_MEMORY_LIMIT < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_error("Invalid number of elements requested or memory limit exceeded.");
        return NULL;
    }

    // Check cache first
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i] && (N <= CACHE_SIZE - i)) {
            log_error("Using cached data structures.");
            return &cache[i];
        }
    }

    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > SYSTEM_MEMORY_LIMIT) {
        log_error("Memory allocation exceeds system-defined limits.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** array = malloc(required_memory);
    if (!array) {
        log_error("Failed to allocate memory for CRC PDU array.");
        return NULL;
    }

    // Populate the structures
    for (size_t i = 0; i < N; ++i) {
        uint32_t rx_tag = pseudo_random(&seed);
        uint16_t rnti = pseudo_random((uint32_t*)&rx_tag);
        uint8_t crc_indication_tag = pseudo_random((uint32_t*)&rnti);

        array[i].RX_UE_INFORMATION_TAG = rx_tag;
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = crc_indication_tag;
        array[i].CRCFLAG = (pseudo_random(&seed) & 1);
    }

    // Cache the newly allocated array if there's space
    if (cache_index < CACHE_SIZE) {
        cache[cache_index++] = *array;
    }

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t N) {
    if (!array || !*array) return;

    for (size_t i = 0; i < N; ++i) {
        cache[i] = NULL;
    }

    free(*array);
}

int main() {
    uint32_t seed = 123456789;
    size_t N = 256;

    NFAPI_CRC_INDICATION_PDU_T** array = allocate_crc_pdu_array(N, seed);
    if (array) {
        printf("Memory allocated for %zu structures.\n", N);

        // Simulate usage
        free_crc_pdu_array(array, N);
        printf("Memory freed successfully.\n");
    }

    return 0;
}
