<?php

function manageUserRequests($request) {
    // Determine request format
    $format = isset($_SERVER['HTTP_ACCEPT']) ? $_SERVER['HTTP_ACCEPT'] : 'application/json';

    // Validate inputs
    if (!validateInputs($request)) {
        logError("Invalid input");
        return respondWithError('Invalid input', $format);
    }

    // Authenticate user credentials with external service
    if (!authenticateUser($request)) {
        logAction('Authentication failed', $request['sub_action'], $request['email']);
        return respondWithError('Authentication failed', $format);
    }

    try {
        $db = new PDO('mysql:host=localhost;dbname=mydb', 'user', 'pass');
        // Set timeout
        $db->setAttribute(PDO::ATTR_TIMEOUT, 5);

        switch ($request['sub_action']) {
            case 'create':
                if (!isEmailUnique($db, $request['email'])) {
                    logAction('Duplicate email', 'create', $request['email']);
                    return respondWithError('Email already exists', $format);
                }

                createUserAccount($db, $request);
                logAction('User created', 'create', $request['email']);
                break;

            case 'update':
                updateUserAccount($db, $request);
                logAction('User updated', 'update', $request['id']);
                break;

            case 'delete':
                deleteUserAccount($db, $request['id']);
                logAction('User deleted', 'delete', $request['email']);
                break;

            default:
                return respondWithError('Invalid sub_action', $format);
        }

    } catch (PDOException $e) {
        logError("Database error: " . $e->getMessage());
        return respondWithError('Database connection failed', $format);
    }

    return respondWithSuccess($request['sub_action'], $format);
}

function validateInputs($request) {
    // Validation logic for 'name', 'email', and 'password'
    if (empty($request['name']) || strlen($request['name']) < 3 || strlen($request['name']) > 50) return false;
    if (!filter_var($request['email'], FILTER_VALIDATE_EMAIL)) return false;
    if (strlen($request['password']) < 6 || strlen($request['password']) > 100) return false;

    return true;
}

function authenticateUser($request) {
    // External service authentication logic
    // Mock implementation: Assume it returns true for valid credentials and false otherwise
    return true; 
}

function isEmailUnique($db, $email) {
    $stmt = $db->prepare("SELECT COUNT(*) FROM users WHERE email = :email");
    $stmt->execute([':email' => $email]);
    return $stmt->fetchColumn() == 0;
}

function createUserAccount($db, $request) {
    $passwordHash = password_hash($request['password'], PASSWORD_BCRYPT);

    $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
    $stmt->execute([
        ':name' => $request['name'],
        ':email' => $request['email'],
        ':password' => $passwordHash
    ]);
}

function updateUserAccount($db, $request) {
    $passwordHash = password_hash($request['password'], PASSWORD_BCRYPT);

    $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
    $stmt->execute([
        ':name' => $request['name'],
        ':email' => $request['email'],
        ':password' => $passwordHash,
        ':id' => $request['id']
    ]);
}

function deleteUserAccount($db, $id) {
    $stmt = $db->prepare("DELETE FROM users WHERE id = :id");
    $stmt->execute([':id' => $id]);
}

function respondWithError($message, $format) {
    switch ($format) {
        case 'application/xml':
            header('Content-Type: application/xml');
            return "<response><error>{$message}</error></response>";
        default:
            header('Content-Type: application/json');
            return json_encode(['error' => $message]);
    }
}

function respondWithSuccess($action, $format) {
    switch ($format) {
        case 'application/xml':
            header('Content-Type: application/xml');
            return "<response><success>Action {$action} completed successfully.</success></response>";
        default:
            header('Content-Type: application/json');
            return json_encode(['success' => "Action {$action} completed successfully."]);
    }
}

function logError($message) {
    // Log error message to a file or logging system
    error_log($message);
}

function logAction($message, $action, $email) {
    // Log action for auditing purposes
    error_log("{$message}: Action: {$action}, Email: {$email}");
}
