typedef struct {
    time_t TIMESTAMP;
    int EVENT_ID;
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    unsigned int SEQUENCE_NUMBER;
} LOG_RECORD;

// Global cache to reuse memory for LOG_RECORDs
static LOG_RECORD* log_cache[CACHE_SIZE] = {NULL};
static size_t cache_count = 0;

void initialize_random(unsigned int seed) {
    srand(seed);
}

unsigned int generate_sequence_number() {
    return rand();
}

LOG_RECORD* get_from_cache(size_t n) {
    for (size_t i = 0; i < cache_count; ++i) {
        if (!log_cache[i]) {
            log_cache[i] = malloc(n * sizeof(LOG_RECORD));
            if (!log_cache[i]) {
                fprintf(stderr, "Memory allocation failed in cache\n");
                return NULL;
            }
            return log_cache[i];
        }
    }
    return NULL;
}

void free_all_logs() {
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (log_cache[i]) {
            free(log_cache[i]);
            log_cache[i] = NULL;
        }
    }
    cache_count = 0;
}

LOG_RECORD* manage_log_records(size_t n, unsigned int seed) {
    if (n == 0 || n > MAX_LOGS) {
        fprintf(stderr, "Invalid number of logs requested: %zu\n", n);
        return NULL;
    }

    LOG_RECORD *logs = get_from_cache(n);

    if (!logs) {
        logs = malloc(n * sizeof(LOG_RECORD));
        if (!logs) {
            fprintf(stderr, "Memory allocation failed for log records\n");
            return NULL;
        }
    } else {
        cache_count--;
    }

    initialize_random(seed);
    for (size_t i = 0; i < n; ++i) {
        logs[i].TIMESTAMP = time(NULL);
        logs[i].EVENT_ID = rand() % 1000; // Example event ID
        snprintf(logs[i].SOURCE_IP, sizeof(logs[i].SOURCE_IP), "192.168.%d.%d", rand() % 255, rand() % 255);
        snprintf(logs[i].DESTINATION_IP, sizeof(logs[i].DESTINATION_IP), "10.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256);
        logs[i].SEQUENCE_NUMBER = generate_sequence_number();
    }

    printf("Log records successfully created\n");
    return logs;
}

void fallback_log_directory(const char *message) {
    const char *default_dir = "/var/log/default_logs";
    FILE *file = fopen(default_dir, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to write to fallback log directory: %s\n", default_dir);
    }
}

int main() {
    size_t n = 100; // Example input
    unsigned int seed = 12345;

    LOG_RECORD *logs = manage_log_records(n, seed);

    if (logs) {
        free(logs); // Free memory after usage
    } else {
        fallback_log_directory("Resource exhaustion or allocation failure occurred");
    }

    return 0;
}
