    manager->count = 0;
    manager->frames = calloc(manager->capacity, sizeof(LTE_DL_FRAME_STRUCT));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int add_frame(FrameManager *manager, int sequence_number /* Other parameters */) {
    if (sequence_number <= 0) {
        fprintf(stderr, "Invalid sequence number: %d\n", sequence_number);
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = (size_t)(manager->capacity * GROWTH_FACTOR);
        LTE_DL_FRAME_STRUCT *new_frames = realloc(manager->frames, new_capacity * sizeof(LTE_DL_FRAME_STRUCT));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->lock);
            fprintf(stderr, "Memory allocation failed during resizing\n");
            return -1;
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    LTE_DL_FRAME_STRUCT *frame = &manager->frames[manager->count++];
    frame->sequence_number = sequence_number;
    // Populate other fields for PHY_RX_TARGET and MAC_RX_TARGET here.

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_frame_manager(FrameManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->frames);
        free(manager);
    }
}

int serialize_frames(const char *filename, FrameManager *manager) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t written = fwrite(manager->frames, sizeof(LTE_DL_FRAME_STRUCT), manager->count, file);
    if (written != manager->count) {
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Failed to write all frames to the file\n");
        return -1;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

int deserialize_frames(const char *filename, FrameManager *manager) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    size_t required_capacity = (size_t)(file_size / sizeof(LTE_DL_FRAME_STRUCT));

    pthread_mutex_lock(&manager->lock);

    if (required_capacity > manager->capacity) {
        LTE_DL_FRAME_STRUCT *new_frames = realloc(manager->frames, required_capacity * sizeof(LTE_DL_FRAME_STRUCT));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->lock);
            fclose(file);
            fprintf(stderr, "Memory allocation failed during deserialization\n");
            return -1;
        }
        manager->frames = new_frames;
        manager->capacity = required_capacity;
    }

    size_t read_count = fread(manager->frames, sizeof(LTE_DL_FRAME_STRUCT), required_capacity, file);
    if (read_count != required_capacity) {
        pthread_mutex_unlock(&manager->lock);
        fclose(file);
        fprintf(stderr, "Failed to read all frames from the file\n");
        return -1;
    }

    manager->count = read_count;

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

void memory_profiler(FrameManager *manager) {
    // This function can be extended with actual profiling logic.
    printf("Current memory usage: %zu bytes\n", manager->capacity * sizeof(LTE_DL_FRAME_STRUCT));
}
