['Below is a C code snippet that demonstrates how you might implement a network service to handle multiple concurrent TCP connections using POSIX threads (pthreads) for concurrency management. This code assumes some existing infrastructure for authentication and legacy compatibility, which are abstracted in this example.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <errno.h>

#define MAX_CONNECTIONS 1024
#define BUFFER_SIZE 4096

typedef struct {
    int socket_fd;
    struct sockaddr_in client_addr;
    char buffer[BUFFER_SIZE];
    size_t buffer_len;
} connection_t;

typedef struct {
    connection_t *connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    // Additional shared resources can be added here
} network_service_t;

network_service_t service = { .lock = PTHREAD_MUTEX_INITIALIZER };

// Function prototypes for authentication and legacy compatibility (mock implementations)
int authenticate_client(int socket_fd, struct sockaddr_in client_addr);
void handle_legacy_protocol(int socket_fd);

void *connection_handler(void *arg) {
    connection_t *conn = (connection_t *)arg;

    if (!authenticate_client(conn->socket_fd, conn->client_addr)) {
        close(conn->socket_fd);
        free(conn);
        return NULL;
    }

    // Handle legacy protocol as needed
    handle_legacy_protocol(conn->socket_fd);

    while ((conn->buffer_len = read(conn->socket_fd, conn->buffer, BUFFER_SIZE)) > 0) {
        // Process data received from the client
        // For demonstration, we'll just echo it back
        write(conn->socket_fd, conn->buffer, conn->buffer_len);
    }

    if (conn->buffer_len == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
        perror("recv");
    }

    close(conn->socket_fd);
    free(conn);

    return NULL;
}

void start_network_service(int port) {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    pthread_t thread_id;

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0)) == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(port);

    // Bind socket to address and port
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", port);

    while (1) {
        connection_t *conn = malloc(sizeof(connection_t));
        if (!conn) {
            perror("malloc failed");
            continue;
        }

        conn->socket_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (conn->socket_fd < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("accept failed");
            }
            free(conn);
            continue;
        }

        memcpy(&conn->client_addr, &client_addr, sizeof(client_addr));
        conn->buffer_len = 0;

        pthread_mutex_lock(&service.lock);
        for (int i = 0; i < MAX_CONNECTIONS; ++i) {
            if (!service.connections[i]) {
                service.connections[i] = conn;
                break;
            }
        }
        pthread_mutex_unlock(&service.lock);

        if (pthread_create(&thread_id, NULL, connection_handler, (void *)conn) != 0) {
            perror("could not create thread");
            close(conn->socket_fd);
            free(conn);
        }
    }

    // Close server socket
    close(server_fd);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int port = atoi(argv[1]);

    start_network_service(port);

    return 0;
}
```

This code sets up a TCP server that listens on the specified port and accepts incoming connections. Each connection is handled in its own thread for concurrency, with a dynamic pool of connection structures to track state per client.

Key considerations:
- **Thread Safety**: The global `service.connections` array uses a mutex lock (`pthread_mutex_t`) to ensure safe concurrent access.
- **Non-blocking Sockets**: Server and client sockets are set to non-blocking mode to handle varying network loads efficiently.
- **Error Handling**: Proper checks and error messages for socket operations, memory allocations, etc., are implemented.
- **Scalability**: The code can be extended by adjusting `MAX_CONNECTIONS` and optimizing the handling logic.

Remember, this is a simplified example; real-world applications might require more robust authentication mechanisms, advanced error recovery strategies, and optimizations tailored to specific requirements.']

