void init_nfa_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->capacity = 0;
    list->count = 0;
    list->data = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

bool resize_if_needed(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list->count >= list->capacity || list->capacity == 0) {
        size_t new_capacity = list->capacity == 0 ? 16 : list->capacity * 2;
        if (new_capacity > MAX_STRUCTURES) {
            return false; // Cannot grow beyond the maximum allowed structures
        }
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            return false; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    return true;
}

bool add_pdu(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t RNTI) {
