        pthread_mutex_unlock(&list->lock);
        return false; // Memory allocation issue
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[list->count++];
    pdu->RNTI = RNTI;
    pdu->CRCFLAG = rand() % 256; // Random CRC flag

    pthread_mutex_unlock(&list->lock);
    return true;
