    init_nfa_list(&nfa_list);

    // Example usage
    for (uint16_t i = 1; i <= 10000; ++i) {
        if (!add_pdu(&nfa_list, i)) {
            fprintf(stderr, "Failed to add PDU with RNTI %u\n", i);
        }
    }

    free_nfa_list(&nfa_list);
    return 0;
}
