#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define HASH_TABLE_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArrayManager;

// Hash function for RNTI
unsigned int hash(uint32_t rnti, size_t table_size) {
    return (rnti & 0xFFFF) % table_size; // Simple modulo-based hash
}

DynamicArrayManager* create_manager(size_t initial_capacity) {
    DynamicArrayManager* manager = malloc(sizeof(DynamicArrayManager));
    if (!manager) return NULL;

    manager->table = calloc(HASH_TABLE_SIZE, sizeof(Node*));
    if (!manager->table) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        manager->table[i] = NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void free_manager(DynamicArrayManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* node = manager->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(manager->table);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_element(DynamicArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!manager) return -1;

    unsigned int index = hash(element.RNTI, HASH_TABLE_SIZE);

    pthread_mutex_lock(&manager->lock);

    Node* node = manager->table[index];
    while (node) {
        if (node->data.RNTI == element.RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate RNTI
        }
        node = node->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failure
    }

    new_node->data = element;
    new_node->next = manager->table[index];
    manager->table[index] = new_node;
    manager->size++;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void print_elements(DynamicArrayManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* node = manager->table[i];
        while (node) {
            printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %u\n",
                   node->data.RXT_UE_INFORMATION_TAG,
                   node->data.RNTI,
                   node->data.CRC_INDICATION_REL8_TAG,
                   node->data.CRCFLAG);
            node = node->next;
        }
    }
}

// Example usage
int main() {
    DynamicArrayManager* manager = create_manager(10);
    if (!manager) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = 0x01 };
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (add_element(manager, pdu) != 0) {
        printf("Failed to add element\n");
    }

    print_elements(manager);
    free_manager(manager);

    return 0;
}
```

### Key Features Implemented:
