        if (manager->records[i].CLIENT_ID == attempt) {
            return -1;
        }
    }
    return attempt;
}

// Function to initialize a new connection record
int init_connection_record(ConnectionManager *manager, int server_port, time_t timestamp) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_CONNECTIONS) {
        log_message("Max connections reached.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    TCP_CONNECTION_RECORD new_record = {0};
    int client_id, retries = 0;

    do {
        client_id = rand(); // Simple random ID generation
        if (generate_unique_client_id(manager, client_id) == -1 && retries < 3) {
            retries++;
        } else {
            break;
        }
    } while (retries <= 3);

    if (retries > 3) {
        log_message("Failed to generate unique CLIENT_ID after 3 attempts.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_record.CLIENT_ID = client_id;
    new_record.SERVER_PORT = server_port;
    new_record.CONNECTION_STATUS = 1; // Active

    manager->records[manager->count++] = new_record;

    if (store_connection_record(&new_record) != 0) {
        log_message("Failed to store connection record.");
    } else {
        qsort(manager->records, manager->count, sizeof(TCP_CONNECTION_RECORD), 
              [](const void *a, const void *b) {
                  TCP_CONNECTION_RECORD *rec_a = (TCP_CONNECTION_RECORD *)a;
                  TCP_CONNECTION_RECORD *rec_b = (TCP_CONNECTION_RECORD *)b;
                  return rec_b->CONNECTION_STATUS - rec_a->CONNECTION_STATUS ||
                         (rec_a->CONNECTION_STATUS == 1 && rec_b->CONNECTION_STATUS == 1) ? 
                         (long)(rec_a - timestamp) - (long)(rec_b - timestamp) : 0;
              });
    }

    pthread_mutex_unlock(&manager->lock);
    return client_id;
}

ConnectionManager* create_connection_manager() {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) {
        log_message("Memory allocation failed for ConnectionManager.");
        return NULL;
    }

    manager->records = calloc(MAX_CONNECTIONS, sizeof(TCP_CONNECTION_RECORD));
    if (!manager->records) {
        free(manager);
        log_message("Memory allocation failed for records array.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;

    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
