#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Ensure non-negative values for valid RNTIs
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock; // Ensure thread safety
} CRCList;

CRCList crc_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Helper function to generate a random CRCFLAG value
uint8_t generate_random_crcflag() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

bool validate_structure(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu == NULL || pdu->RNTI <= 0) {
        return false;
    }
    return true;
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, int tag, unsigned long rnti) {
    if (validate_structure(pdu)) {
        pdu->RX_UE_INFORMATION_TAG = tag;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();
    } else {
        fprintf(stderr, "Invalid PDU structure.\n");
    }
}

void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&crc_list.lock);

    if (validate_structure(pdu)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed.\n");
            pthread_mutex_unlock(&crc_list.lock);
            return;
        }

        memcpy(&(new_node->data), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = crc_list.head;
        crc_list.head = new_node;
        crc_list.count++;

        if (crc_list.count > MAX_STRUCTURES) {
            fprintf(stderr, "Exceeded maximum allowed structures.\n");
            Node* current = crc_list.head;
            crc_list.head = current->next;
            free(current);
            crc_list.count--;
        }
    } else {
        fprintf(stderr, "Invalid PDU structure. Aborting addition to list.\n");
    }

    pthread_mutex_unlock(&crc_list.lock);
}

void serialize_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu, unsigned char** buffer, size_t* length) {
    if (!validate_structure(pdu)) return;

    *length = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (unsigned char*)malloc(*length);

    if (*buffer) {
        memcpy(*buffer, pdu, *length);
    } else {
        fprintf(stderr, "Memory allocation failed for serialization.\n");
        *length = 0;
    }
}

void free_list() {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    crc_list.head = NULL;
    crc_list.count = 0;

    pthread_mutex_unlock(&crc_list.lock);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu_example = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345 };
    initialize_pdu(&pdu_example, 2, 54321);

    add_pdu_to_list(&pdu_example);

    unsigned char* buffer;
    size_t length;
    serialize_pdu(&pdu_example, &buffer, &length);

    if (buffer) {
        free(buffer);
    }

    free_list();
    return 0;
}
```

### Key Points:
