        {"./file1.txt", 9},
        {"/some/relative/path/file2.txt", 23}
    };

    size_t count = sizeof(paths) / sizeof(FilePath);
    size_t max_batch_size = 10; // Example throttling limit

    int processed = process_file_paths(paths, count, max_batch_size);

    printf("Processed %d paths\n", processed);

    // Free remaining allocated memory
    for (size_t i = 0; i < count; ++i) {
        free(paths[i].path);
    }
}

