typedef struct {
    RX_UE_INFORMATION_TAG_T RX_UE_INFORMATION_TAG;
    RNTI_T RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int num_entries, UE_ID_T* ue_ids, int probability) {
    if (num_entries <= 0 || ue_ids == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** temp_array = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (temp_array == NULL) {
        fprintf(stderr, "Memory allocation failed for temporary array.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    int allocated_size = num_entries;

    for (int i = 0; i < allocated_size; ++i) {
        temp_array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp_array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T at index %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(temp_array[j]);
            }
            free(temp_array);
            return NULL;
        }

        temp_array[i]->RX_UE_INFORMATION_TAG.RX_UE_INFORMATION_TAG = ue_ids[i % num_entries].UE_ID;
        temp_array[i]->RNTI.RNTI = rand() % 10000; // Example RNTI generation
        temp_array[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 100) < probability;

        // Check for duplicate RNTI
        for (int j = 0; j < i; ++j) {
            if (temp_array[j]->RNTI.RNTI == temp_array[i]->RNTI.RNTI) {
                fprintf(stderr, "Duplicate RNTI found at index %d. Reallocating...\n", i);
                free(temp_array[i]);

                NFAPI_CRC_INDICATION_PDU_T** new_temp_array = realloc(temp_array, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
                if (new_temp_array == NULL) {
                    fprintf(stderr, "Memory reallocation failed.\n");
                    // Free previously allocated memory
                    for (int k = 0; k <= i; ++k) {
                        free(temp_array[k]);
                    }
                    free(temp_array);
                    return NULL;
                }

                temp_array = new_temp_array;
                --i; // Retry current index after reallocation
                break;
            }
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* final_array = malloc(allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (final_array == NULL) {
        fprintf(stderr, "Memory allocation failed for final array.\n");
        // Free temporary array memory
        for (int i = 0; i < allocated_size; ++i) {
            free(temp_array[i]);
        }
        free(temp_array);
        return NULL;
    }

    // Copy data to the final array
    for (int i = 0; i < allocated_size; ++i) {
        final_array[i] = *(temp_array[i]);
        free(temp_array[i]); // Free temporary memory
    }
    free(temp_array); // Free temp array structure

    return final_array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, int num_entries) {
    if (array == NULL) return;

    for (int i = 0; i < num_entries; ++i) {
        // No dynamic memory within structures to free
    }
    free(array);
}
