import "rlc_pdu_t.h"
import "pdcp_pdu_t.h"

typedef struct {
    RLC_PDU *rlc_pdu;
    PDCP_PDU *pdcP_pdu;
} NFAPI_RX_FRAME_PDU_T;

#define INITIAL_POOL_SIZE 10

typedef struct Node {
    NFAPI_RX_FRAME_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPIDataCollection;

