NFAPIDataCollection* create_collection();
void destroy_collection(NFAPIDataCollection* collection);
int add_pdu_batch(NFAPIDataCollection* collection, NFAPI_RX_FRAME_PDU_T* batch, size_t batch_size);
int remove_pdu_batch(NFAPIDataCollection* collection, void (*remove_func)(NFAPI_RX_FRAME_PDU_T*), size_t count);
void iterate_collection(NFAPIDataCollection* collection, void (*func)(NFAPI_RX_FRAME_PDU_T*));
static Node* allocate_node(size_t pdu_size);

// Create a new data collection
NFAPIDataCollection* create_collection() {
    NFAPIDataCollection* collection = (NFAPIDataCollection*)malloc(sizeof(NFAPIDataCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->count = 0;

    return collection;
}

// Destroy the data collection
void destroy_collection(NFAPIDataCollection* collection) {
    if (!collection) return;

    Node* current = collection->head;
    while (current) {
        Node* next = current->next;
        free(current->data.rlc_pdu);
        free(current->data.pdcP_pdu);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Add a batch of PDUs
