    int CRCFLAG;
    int SEQUENCE_NUMBER;
} LOG_RECORD;

// Simple pseudo-random number generator using seed
static inline int pseudo_random(int *seed) {
    *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
    return (*seed / 65536) % 32768;
}

typedef struct CacheNode {
    LOG_RECORD record;
    struct CacheNode* next;
} CacheNode;

CacheNode* cache_head = NULL;

LOG_RECORD* allocate_log_records(int N, int seed) {
    if (N <= 0 || N > MAX_LOG_RECORDS) {
        fprintf(stderr, "Error: Invalid number of records requested.\n");
        return NULL;
    }

    LOG_RECORD* records = NULL;

    // Attempt to reuse cached nodes
    for (CacheNode** curr = &cache_head; *curr != NULL && N > 0;) {
        CacheNode* node = *curr;
        if (N >= 1) {
            records = realloc(records, sizeof(LOG_RECORD) * ((records == NULL) ? 1 : (N - 1)) + 1);
            if (!records) {
                fprintf(stderr, "Memory allocation failed.\n");
                return NULL;
            }

            memcpy(&records[N - 1], &node->record, sizeof(LOG_RECORD));
            N--;
        }
        *curr = node->next;
        free(node);
    }

    // Allocate additional memory if needed
    if (N > 0) {
        records = realloc(records, sizeof(LOG_RECORD) * N);
        if (!records) {
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }
    }

    // Initialize remaining records with pseudo-random values
    for (int i = MAX_LOG_RECORDS - N; i < MAX_LOG_RECORDS; i++) {
        LOG_RECORD* record = &records[i];

        record->TIMESTAMP = time(NULL);
        record->EVENT_ID = rand() % 1000;
        snprintf(record->SOURCE_IP, sizeof(record->SOURCE_IP), "192.168.1.%d", rand() % 255);
        snprintf(record->DESTINATION_IP, sizeof(record->DESTINATION_IP), "10.0.0.%d", rand() % 255);
        record->CRC_INDICATION_REL8_TAG = pseudo_random(&seed) & 0xFFFF;
        record->CRCFLAG = (pseudo_random(&seed) % 2 == 0) ? 1 : 0;
        record->SEQUENCE_NUMBER = pseudo_random(&seed);

        // Add to cache
        CacheNode* new_node = malloc(sizeof(CacheNode));
        if (!new_node) {
            fprintf(stderr, "Memory allocation for cache failed.\n");
            continue; // Proceed without caching this node
        }
        memcpy(&new_node->record, record, sizeof(LOG_RECORD));
        new_node->next = cache_head;
        cache_head = new_node;
    }

    return records;
}

void free_log_records_cache() {
    while (cache_head != NULL) {
        CacheNode* temp = cache_head;
        cache_head = cache_head->next;
        free(temp);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <number_of_records> <seed>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int N = atoi(argv[1]);
    int seed = atoi(argv[2]);

    LOG_RECORD* records = allocate_log_records(N, seed);
    if (!records) {
        fprintf(stderr, "Failed to allocate log records.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    printf("Allocated %d records.\n", N);

    free(records);
    free_log_records_cache();

    return EXIT_SUCCESS;
}
