            free_mac_pdu(mac_pdus, i); // Free previously allocated PDUs
            return NULL;
        }

        mac_pdus[i].data->data = NULL;  // Initialize with NULL pointer
        mac_pdus[i].data->length = 0;   // And zero length
        memset(&mac_pdus[i].trailer.crc, 0, sizeof(mac_pdus[i].trailer.crc)); // Zero out CRC
    }

    return mac_pdus;
}

// Free the allocated memory for MAC_PDU_T array
void free_mac_pdu(MAC_PDU_T* mac_pdu_array, size_t num_pdus) {
