    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->elements[i]);
    }
    free(manager->elements);

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

int add_to_list(DynamicListManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!validate_crc(pdu)) return -1;

    pthread_mutex_lock(&manager->lock);

    while (manager->count >= manager->max_elements) {
        // Wait for space to become available
        pthread_cond_wait(&manager->cond, &manager->lock);
    }

    manager->elements[manager->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->elements[manager->count]) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    memcpy(manager->elements[manager->count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (manager->count % LOG_INTERVAL == 0) {
        log_info("Logged CRC Indication PDU");
    }

    manager->count++;
    pthread_cond_signal(&manager->cond);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void process_list(DynamicListManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        // Process each element
        log_info("Processing CRC Indication PDU");
    }

    pthread_mutex_unlock(&manager->lock);
}

void resize_list(DynamicListManager *manager, size_t new_max_elements) {
    pthread_mutex_lock(&manager->lock);

    if (new_max_elements < manager->count) {
        // Handle error: cannot reduce max below current count
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T **new_elements = (NFAPI_CRC_INDICATION_PDU_T **)realloc(manager->elements, new_max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!new_elements) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->elements = new_elements;
    memset(new_elements + manager->count, 0, (new_max_elements - manager->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    manager->max_elements = new_max_elements;

    pthread_mutex_unlock(&manager->lock);
}
