        log_error("Memory allocation failed for new node.");
        return 0;
    }

    new_node->data = crc_pdu;

    pthread_mutex_lock(&list->lock);
    if (is_full(list)) {
        free_node(new_node);
        pthread_mutex_unlock(&list->lock);
        log_info("List is full, unable to add new CRC indication.");
        return 0;
