#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_CONFIGS 1000
#define RESIZE_FACTOR 2

typedef struct {
    int param1;
    float param2;
} LTEPHYTESTPARAMS_T;

typedef struct {
    LTEPHYTESTPARAMS_T settings;
} LTE_PHY_TEST_CONFIG;

typedef struct {
    LTE_PHY_TEST_CONFIG *configs;
    size_t count;
    size_t capacity;
    atomic_size_t allocations;
    atomic_size_t deallocations;
    pthread_mutex_t lock;
} ConfigArray;

void log_config(const LTE_PHY_TEST_CONFIG *config) {
    printf("Config: param1=%d, param2=%.2f\n", config->settings.param1, config->settings.param2);
}

int validate_params(const LTEPHYTESTPARAMS_T *params) {
    return params->param1 >= 0 && params->param2 > 0.0;
}

void resize_array(ConfigArray *array) {
    size_t new_capacity = array->capacity * RESIZE_FACTOR;
    if (new_capacity > MAX_CONFIGS) {
        new_capacity = MAX_CONFIGS;
    }

    LTE_PHY_TEST_CONFIG *new_configs = realloc(array->configs, new_capacity * sizeof(LTE_PHY_TEST_CONFIG));
    if (!new_configs) {
        fprintf(stderr, "Memory allocation failed during resize\n");
        return;
    }

    array->capacity = new_capacity;
    atomic_fetch_add(&array->allocations, 1);
    free(array->configs);
    array->configs = new_configs;
}

void init_config_array(ConfigArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->capacity = 10; // Initial capacity
    array->allocations = 0;
    array->deallocations = 0;

    LTE_PHY_TEST_CONFIG *configs = malloc(array->capacity * sizeof(LTE_PHY_TEST_CONFIG));
    if (!configs) {
        fprintf(stderr, "Initial memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    atomic_fetch_add(&array->allocations, 1);
    array->configs = configs;
}

void add_config(ConfigArray *array, LTEPHYTESTPARAMS_T params) {
    pthread_mutex_lock(&array->lock);

    if (!validate_params(&params)) {
        fprintf(stderr, "Invalid parameters\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    if (array->count == array->capacity) {
        resize_array(array);
    }

    if (array->count >= array->capacity) {
        fprintf(stderr, "Maximum capacity reached\n");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    array->configs[array->count].settings = params;
    log_config(&array->configs[array->count]);

    array->count++;
    pthread_mutex_unlock(&array->lock);
}

void free_config_array(ConfigArray *array) {
    pthread_mutex_lock(&array->lock);

    if (array->configs) {
        free(array->configs);
        atomic_fetch_add(&array->deallocations, 1);
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

void log_performance(const ConfigArray *array) {
    size_t allocs = atomic_load(&array->allocations);
    size_t deallocs = atomic_load(&array->deallocations);

    printf("Allocations: %zu, Deallocations: %zu\n", allocs, deallocs);
}

int main() {
    ConfigArray array;
    init_config_array(&array);

    LTEPHYTESTPARAMS_T params1 = {10, 2.5};
    add_config(&array, params1);

    LTEPHYTESTPARAMS_T params2 = {-1, 3.0}; // Invalid
    add_config(&array, params2);

    log_performance(&array);
    free_config_array(&array);

    return 0;
}
```

