- **Validation and Logging**: Validates parameters before adding them and logs each configuration.
- **Error Handling**: Gracefully handles memory allocation failures and invalid parameters.
- **Performance Monitoring**: Logs the number of allocations and deallocations for performance analysis.']

['Below is a C code implementation for the described task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_SIZE 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int *value;
} record;

typedef struct {
    pthread_mutex_t lock;
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    size_t count;
} hash_table;

unsigned int hash_function(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

hash_table* create_hash_table(size_t initial_capacity) {
    hash_table *table = malloc(sizeof(hash_table));
    if (!table) return NULL;

    table->offsets = calloc(initial_capacity, sizeof(long));
    table->keys = calloc(initial_capacity, sizeof(int));
    table->records = calloc(initial_capacity, sizeof(record*));

    pthread_mutex_init(&table->lock, NULL);
    table->capacity = initial_capacity;
    table->count = 0;

    return table;
}

void free_hash_table(hash_table *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i]) {
            free(table->records[i]->value);
            free(table->records[i]);
        }
    }

    free(table->offsets);
    free(table->keys);
    free(table->records);

    pthread_mutex_destroy(&table->lock);
    free(table);
}

int resize_hash_table(hash_table *table) {
    size_t new_capacity = table->capacity * 2;
    long *new_offsets = realloc(table->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(table->keys, new_capacity * sizeof(int));
    record **new_records = realloc(table->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return -1;
    }

    for (size_t i = table->capacity; i < new_capacity; ++i) {
        new_offsets[i] = 0;
        new_keys[i] = 0;
        new_records[i] = NULL;
    }

    table->offsets = new_offsets;
    table->keys = new_keys;
    table->records = new_records;
    table->capacity = new_capacity;

    return 0;
}

void insert_record(hash_table *table, int key, record *rec) {
    pthread_mutex_lock(&table->lock);

    if ((float)table->count / table->capacity > LOAD_FACTOR_THRESHOLD) {
        if (resize_hash_table(table) != 0) {
            printf("Failed to resize hash table\n");
            pthread_mutex_unlock(&table->lock);
            return;
        }
    }

    unsigned int index = hash_function(key, table->capacity);

    while (table->records[index]) {
        index = (index + 1) % table->capacity;
    }

    table->keys[index] = key;
    table->records[index] = rec;
    table->count++;

    pthread_mutex_unlock(&table->lock);
}

void initialize_records(int num_records, int value_range_min, int value_range_max, record **output_records) {
    for (int i = 0; i < num_records; ++i) {
        output_records[i] = malloc(sizeof(record));
        if (!output_records[i]) break;

        output_records[i]->value = malloc(sizeof(int));
        if (!output_records[i]->value) {
            free(output_records[i]);
            break;
        }

        output_records[i]->value[0] = value_range_min + rand() % (value_range_max - value_range_min + 1);
    }
}

void populate_hash_table(hash_table *table, int num_records, int key_range_min, int key_range_max) {
    record **records = malloc(num_records * sizeof(record*));

    if (!records) return;

    initialize_records(num_records, 0, 100, records);

    for (int i = 0; i < num_records; ++i) {
        if (!records[i]) break;

        int key = key_range_min + rand() % (key_range_max - key_range_min + 1);
        insert_record(table, key, records[i]);
    }

    free(records);
}

void *thread_function(void *arg) {
    hash_table *table = (hash_table *)arg;
    populate_hash_table(table, 10, 0, 100);

    return NULL;
}

int main(int argc, char **argv) {
    int num_records = INITIAL_SIZE;
    int key_range_min = 0;
    int key_range_max = 100;
    int value_range_min = 0;
    int value_range_max = 100;
    int concurrency_level = 4;

    hash_table *table = create_hash_table(INITIAL_SIZE);

    if (!table) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[concurrency_level];

    for (int i = 0; i < concurrency_level; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, (void *)table)) {
            fprintf(stderr, "Error creating thread\n");
            free_hash_table(table);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < concurrency_level; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_hash_table(table);

    return EXIT_SUCCESS;
}
```

This code implements a hash table with dynamic resizing, memory management, and concurrent insertion support using mutex locks. It handles allocation failures by attempting to resize the table or gracefully stopping operations if memory cannot be expanded. The `main` function creates multiple threads for concurrent insertions into the hash table.']

