    private final ConcurrentHashMap<String, Post> postCache = new ConcurrentHashMap<>();

    public SocialMediaFeedProcessor(ApiClient apiClient) {
        this.apiClient = apiClient;
    }

    public List<ProcessedPost> fetchRelevantPosts(List<Post> posts, UserPreferences preferences) throws InterruptedException, ExecutionException {
        Predicate<Post> filterPredicate = createFilterPredicate(preferences);
        return posts.parallelStream()
                    .filter(filterPredicate)
                    .map(this::processPost)
                    .collect(Collectors.toList());
    }

    private ProcessedPost processPost(Post post) {
        Post cachedPost = postCache.get(post.getId());
        if (cachedPost != null) {
            return cachedPost;
        }

        switch (post.getType()) {
            case TEXT:
                // Handle text post
                break;
            case IMAGE:
                // Handle image post
                break;
            case VIDEO:
                // Handle video post
                break;
            default:
                throw new IllegalArgumentException("Unsupported post type");
        }

        Post processedPost = fetchAndCachePostDetails(post);
        return convertToProcessedPost(processedPost, preferences);
    }

    private Post fetchAndCachePostDetails(Post post) {
        try {
            Post detailedPost = apiClient.fetchPostDetails(post.getId());
            postCache.putIfAbsent(detailedPost.getId(), detailedPost);
            return detailedPost;
        } catch (NetworkException e) {
            // Handle network failure
            return handleNetworkError(e, post);
        }
    }

    private ProcessedPost convertToProcessedPost(Post post, UserPreferences preferences) {
        // Convert the Post object to a ProcessedPost based on user preferences
        return new ProcessedPost(post);
    }

    private Predicate<Post> createFilterPredicate(UserPreferences preferences) {
        return post -> {
            boolean matches = true;
            if (preferences.getCategories() != null && !preferences.getCategories().isEmpty()) {
                matches &= preferences.getCategories().contains(post.getCategory());
            }
            // Additional filtering logic based on preferences
            return matches;
        };
    }

    private Post handleNetworkError(NetworkException e, Post post) {
        // Implement retry logic or return a default/fallback post
        return post;  // Fallback to original post or cached version
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

