const fs = require('fs').promises;
const path = require('path');
const util = require('util');
const readdir = util.promisify(fs.readdir);

async function readFilesWithFilter(directory, extension) {
  try {
    const files = await readdir(directory);
    const filteredPaths = files.filter(file => file.endsWith(extension));

    const readStreamBatchSize = 10;
    let promises = [];
    for (let i = 0; i < filteredPaths.length; i += readStreamBatchSize) {
      const batch = filteredPaths.slice(i, i + readStreamBatchSize);
      const readPromises = batch.map(filePath => 
        fs.readFile(path.join(directory, filePath), 'utf-8')
          .then(content => logSuccess(filePath))
          .catch(err => logError(filePath, err))
      );
      promises.push(...readPromises);

      // Wait for the current batch to complete before processing the next one
      if (i + readStreamBatchSize >= filteredPaths.length || promises.length >= 100) {
        await Promise.all(promises);
        promises = [];
      }
    }

    return await Promise.all(promises).then(results => 
      results.filter(result => result !== undefined)
    );
  } catch (error) {
    console.error('Error reading directory:', error);
    throw error;
  }
}

function logSuccess(filePath) {
  // Integrate with third-party logging service
  console.log(`Successfully read file: ${filePath}`);
  return filePath; // Or content, based on how you want to handle it
}

function logError(filePath, error) {
  // Integrate with third-party logging service
  console.error(`Failed to read file: ${filePath}, Error: ${error.message}`);
  return undefined;
}

