import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ServiceManager {
    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(5);
    private final Map<String, BackgroundService> services = new ConcurrentHashMap<>();
    private int minServices;
    private int maxServices;
    private long startDelayRangeMin;
    private long startDelayRangeMax;
    private String monitoringApiEndpoint;

    public ServiceManager(int initialServices, int minServices, int maxServices, 
                          long startDelayRangeMin, long startDelayRangeMax, String monitoringApiEndpoint) {
        this.minServices = Math.max(5, minServices);
        this.maxServices = Math.min(20, maxServices);
        this.startDelayRangeMin = startDelayRangeMin;
        this.startDelayRangeMax = startDelayRangeMax;
        this.monitoringApiEndpoint = monitoringApiEndpoint;

        for (int i = 0; i < initialServices; i++) {
            startNewService();
        }
    }

    public void scaleServices(int targetCount) {
        int currentSize = services.size();
        if (targetCount > currentSize && currentSize < maxServices) {
            while (services.size() < targetCount) {
                startNewService();
            }
        } else if (targetCount < currentSize && currentSize > minServices) {
            List<String> toStop = new ArrayList<>(services.keySet());
            Collections.shuffle(toStop);
            for (String id : toStop) {
                stopService(id);
                if (services.size() == targetCount) break;
            }
        }
    }

    private void startNewService() {
        String serviceId = UUID.randomUUID().toString();
        long delay = startDelayRangeMin + new Random().nextLong(startDelayRangeMax - startDelayRangeMin);

        BackgroundService service = new BackgroundService(serviceId, monitoringApiEndpoint);
        services.put(serviceId, service);

        scheduler.schedule(() -> {
            if (!service.start()) {
                logger.severe("Failed to start service: " + serviceId);
                notifyMonitoringSystem("Fail to start", serviceId);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    private void stopService(String serviceId) {
        BackgroundService service = services.get(serviceId);
        if (service != null) {
            service.stop();
            services.remove(serviceId);
            logger.info("Stopped service: " + serviceId);
        }
    }

    public void healthCheck() {
        for (BackgroundService service : services.values()) {
            if (!service.checkHealth()) {
                logger.warning("Service failure detected: " + service.getId());
                notifyMonitoringSystem("Service down", service.getId());
            }
        }
    }

    private void notifyMonitoringSystem(String message, String serviceId) {
        // Simulate sending data to an external monitoring system.
        System.out.println("Alert - " + message + " for Service ID: " + serviceId + ", Endpoint: " + monitoringApiEndpoint);
    }

    public void monitorPerformance() {
        ScheduledExecutorService healthScheduler = Executors.newScheduledThreadPool(1);
        healthScheduler.scheduleAtFixedRate(this::healthCheck, 0, 10, TimeUnit.MINUTES);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            services.values().forEach(service -> service.stop());
            scheduler.shutdown();
            try {
                if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                    scheduler.shutdownNow();
                }
            } catch (InterruptedException e) {
                scheduler.shutdownNow();
            }
        }));
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager(
                5, // initial services
                5, // min services
                20, // max services
                1000L, // start delay range min (ms)
                5000L, // start delay range max (ms)
                "http://monitoring.api.endpoint" // monitoring API endpoint
        );

        manager.monitorPerformance();
    }
}

