<?php

class PasswordUpdater {
    private $db;
    private $authServiceClient;
    private $logger;

    public function __construct($db, $authServiceClient, $logger) {
        $this->db = $db;
        $this->authServiceClient = $ authServiceClient;
        $this->logger = $logger;
    }

    private function validatePasswordStrength($password) {
        // Example criteria: at least 8 characters, 1 uppercase letter, 1 number, and 1 special character
        return preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/', $password);
    }

    private function retryWithExponentialBackoff(callable $operation) {
        $maxRetries = 5;
        $delay = 100; // Initial delay in milliseconds
        for ($i = 0; $i < $maxRetries; $i++) {
            try {
                return $operation();
            } catch (\Exception $e) {
                if ($i == $maxRetries - 1) throw $e;
                usleep($delay * 1000);
                $delay *= 2;
            }
        }
    }

    private function updatePasswordInDatabase($userId, $newHashedPassword) {
        // Using a transaction to ensure atomicity
        try {
            $this->db->beginTransaction();

            // Update the password hash in the database
            $stmt = $this->db->prepare("UPDATE users SET password_hash = :password_hash WHERE id = :id FOR UPDATE");
            $stmt->execute([':password_hash' => $newHashedPassword, ':id' => $userId]);

            $this->db->commit();
        } catch (\Exception $e) {
            $this->db->rollBack();
            throw $e;
        }
    }

    public function updatePassword($userId, $oldPassword, $newPassword) {
        if (!$this->validatePasswordStrength($newPassword)) {
            $this->logger->error("Password strength validation failed for user {$userId}");
            return false;
        }

        try {
            // Verify old password (assuming a method exists)
            if (!$this->verifyOldPassword($userId, $oldPassword)) {
                $this->logger->error("Old password verification failed for user {$userId}");
                return false;
            }

            // Hash the new password
            $newHashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

            // Update the password in the database atomically
            $this->updatePasswordInDatabase($userId, $newHashedPassword);

            // Verify with external authentication service
            $verifyOperation = function() use ($userId, $newHashedPassword) {
                return $this->authServiceClient->verifyPasswordChange($userId, $newHashedPassword);
            };

            $result = $this->retryWithExponentialBackoff($verifyOperation);

            if (!$result) {
                throw new \Exception("External authentication service verification failed");
            }

            // Log successful password change
            $this->logger->info("Password successfully updated for user {$userId}");

            return true;
        } catch (\Exception $e) {
            $this->logger->error("Failed to update password for user {$userId}: " . $e->getMessage());
            return false;
        }
    }

    private function verifyOldPassword($userId, $oldPassword) {
        // Example method - implementation depends on system specifics
        $stmt = $this->db->prepare("SELECT password_hash FROM users WHERE id = :id");
        $stmt->execute([':id' => $userId]);
        $user = $stmt->fetch();

        return password_verify($oldPassword, $user['password_hash']);
    }
}
