// Message class to manage messages with ID, timestamp, and priority
public class CustomMessage
{
    public DateTime Timestamp { get; private set; }
    public Guid MessageId { get; private set; }
    public int Priority { get; private set; }

    public CustomMessage(DateTime timestamp, Guid messageId, int priority)
    {
        Timestamp = timestamp;
        MessageId = messageId;
        Priority = priority;
    }
}

public class MessageManager
{
    private readonly ConcurrentDictionary<Guid, CustomMessage> messages;
    private readonly DateTime minTimestamp;
    private readonly DateTime maxTimestamp;
    private readonly int maxLength;

    public MessageManager(DateTime minTimestamp, DateTime maxTimestamp, int maxLength)
    {
        this.minTimestamp = minTimestamp;
        this.maxTimestamp = maxTimestamp;
        this.maxLength = maxLength;
        messages = new ConcurrentDictionary<Guid, CustomMessage>();
    }

    public bool AddMessage(CustomMessage message)
    {
        if (message.Timestamp < minTimestamp || message.Timestamp > maxTimestamp ||
            message.MessageId == Guid.Empty || messages.ContainsKey(message.MessageId))
        {
            return false;
        }

        // Assuming the content length validation is done elsewhere
        return messages.TryAdd(message.MessageId, message);
    }

    public bool UpdateMessage(Guid messageId, DateTime timestamp, int priority)
    {
        if (timestamp < minTimestamp || timestamp > maxTimestamp) return false;

        var existing = messages.TryGetValue(messageId, out CustomMessage message) && message != null;

        if (!existing) return false;

        return messages.TryUpdate(
            messageId,
            new CustomMessage(timestamp, messageId, priority),
            message
        );
    }

    public CustomMessage GetMessage(Guid messageId)
    {
        return messages.GetValueOrDefault(messageId, new CustomMessage(DateTime.MinValue, Guid.Empty, 0));
    }

    public IEnumerable<CustomMessage> GetAllMessages()
    {
        return messages.Values.OrderBy(m => m.Timestamp);
    }

    private static uint GenerateRandomCrcFlag(int minRange, int maxRange)
    {
        return (uint)UnityEngine.Random.Range(minRange, maxRange + 1);
    }

    public List<NFAPI_CRC_INDICATION_PDU_T> PopulateNfaPduList()
    {
        var nfaPduList = new List<NFAPI_CRC_INDICATION_PDU_T>();

        for (int i = 0; i < 1000; i++) // Example count
        {
            nfaPduList.Add(new NFAPI_CRC_INDICATION_PDU_T
            {
                RxUeInformationTag = new RX_UE_INFORMATION_TAG(), 
                Rnti = new RNTI(),
                CrcIndicationRel8Tag = new CRC_INDICATION_REL8_TAG { CRCFLAG = GenerateRandomCrcFlag(0, 255) }
            });
        }

        return nfaPduList;
    }
}
