using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Diagnostics;

public class Program
{
    private static readonly byte[] key = Encoding.UTF8.GetBytes("YourTripleDESEncryptionKey123"); // Must be 24 bytes for Triple DES
    private static readonly byte[] iv = Encoding.UTF8.GetBytes("YourTripleDESIV123456"); // Must be 8 bytes

    public static (string decryptedMessage, CompilationMetrics metrics, string staticAnalysisSummary) processAndCompileRust(string encryptedMessage, string base64Encoded, string dependencyList)
    {
        string decryptedMessage = null;
        CompilationMetrics metrics = new CompilationMetrics();
        string staticAnalysisSummary = "";

        try
        {
            // Decrypt the Base64-encoded message
            var cipherTextBytes = Convert.FromBase64String(base64Encoded);
            using (var tripleDES = TripleDESCryptoServiceProvider.Create())
            {
                tripleDES.Key = key;
                tripleDES.IV = iv;

                using (var decryptor = tripleDES.CreateDecryptor(tripleDES.Key, tripleDES.IV))
                {
                    using (var msDecrypt = new MemoryStream(cipherTextBytes))
                    {
                        using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {
                            using (var srDecrypt = new StreamReader(csDecrypt))
                            {
                                decryptedMessage = srDecrypt.ReadToEnd();
                            }
                        }
                    }
                }
            }

            // Validate integrity
            if (!ValidateIntegrity(decryptedMessage))
            {
                Log("Decryption failed: checksum validation error.");
