    if (!logger) logger = log_default;  // Assign default logger if none is set
    logger("Starting allocation of PDU array.");

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
