#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_KEY 1000
#define MAX_OFFSET 100000
#define HASH_TABLE_SIZE 1024

typedef struct {
    int value;
    int key_reference;
    long offset;
} record;

typedef struct hash_node {
    record rec;
    struct hash_node *next;
} hash_node;

hash_node *hash_table[HASH_TABLE_SIZE];
pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash(int key, long offset) {
    return ((key ^ (int)(offset)) % HASH_TABLE_SIZE);
}

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

int is_valid_key_offset_pair(int key, long offset) {
    return key >= 0 && key <= MAX_KEY && offset >= 0 && offset <= MAX_OFFSET;
}

int add_to_hash_table(record rec) {
    unsigned int index = hash(rec.key_reference, rec.offset);
    pthread_mutex_lock(&hash_table_lock);

    for (hash_node *node = hash_table[index]; node != NULL; node = node->next) {
        if (node->rec.key_reference == rec.key_reference && node->rec.offset == rec.offset) {
            pthread_mutex_unlock(&hash_table_lock);
            return 0;
        }
    }

    hash_node *new_node = malloc(sizeof(hash_node));
    if (!new_node) {
        pthread_mutex_unlock(&hash_table_lock);
        return -1;
    }
    new_node->rec = rec;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&hash_table_lock);
    return 1;
}

record *create_records(int num, int *keys, long *offsets) {
    if (num <= 0 || !keys || !offsets) {
        return NULL;
    }

    record *records = malloc(num * sizeof(record));
    if (!records) {
        return NULL;
    }

    init_hash_table();

    for (int i = 0; i < num; ++i) {
        int key = keys[i];
        long offset = offsets[i];

        if (!is_valid_key_offset_pair(key, offset)) {
            free(records);
            records = NULL;
            break;
        }

        record rec = { .value = i, .key_reference = key, .offset = offset };

        if (add_to_hash_table(rec) != 1) {
            free(records);
            records = NULL;
            break;
        }

        records[i] = rec;
    }

    return records;
}

void destroy_records(record *records, int num) {
    if (!records) return;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_node *node = hash_table[i];
        while (node != NULL) {
            hash_node *temp = node;
            node = node->next;
            free(temp);
        }
        hash_table[i] = NULL;
    }

    pthread_mutex_destroy(&hash_table_lock);
    free(records);
}

void stress_test() {
    int keys[] = {1, 2, 3, 4, 5};
    long offsets[] = {10L, 20L, 30L, 40L, 50L};

    record *records = create_records(5, keys, offsets);
    if (records) {
        printf("Records created successfully.\n");
        destroy_records(records, 5);
        printf("Records destroyed successfully.\n");
    } else {
        printf("Failed to create records.\n");
    }

    // Add more tests for edge cases like empty input, etc.
}

int main() {
    stress_test();
    return 0;
}
```

### Explanation:
- **Data Structures:** 
  - `record` structure holds the data.
  - A simple hash table with chaining is used to ensure no duplicate key-offset pairs exist.

- **Concurrency:**
  - A mutex protects shared resources, ensuring thread-safe operations when accessing or modifying the hash table.

- **Memory Management:**
  - Records are dynamically allocated and deallocated. Proper cleanup of memory ensures there are no leaks.

- **Stress Testing:**
  - The `stress_test` function demonstrates basic usage and can be extended to cover additional edge cases. 

This setup is designed for scalability, low-latency access (through direct hashing), and high-throughput scenarios by managing concurrent accesses efficiently.']

