#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_ID 65535
#define MAX_RF_CHAIN_ID 7
#define MAX_RX_SYMBOLS 2048
#define RETRY_LIMIT 3

typedef struct {
    int UE_ID;
    int RF_CHAIN_ID;
    unsigned char* rx_buffer;
} LTE_PHY_RX_FRAME;

typedef struct {
    LTE_PHY_RX_FRAME** frames;
    size_t num_frames;
    size_t max_frames;
    pthread_mutex_t mutex;
} FrameManager;

int initialize_frame_manager(FrameManager* manager, size_t max_frames) {
    if (manager == NULL || max_frames == 0) return -1;

    manager->frames = calloc(max_frames, sizeof(LTE_PHY_RX_FRAME*));
    if (!manager->frames) return -1;

    manager->num_frames = 0;
    manager->max_frames = max_frames;

    pthread_mutex_init(&manager->mutex, NULL);
    return 0;
}

void cleanup_frame_manager(FrameManager* manager) {
    if (manager == NULL) return;

    for (size_t i = 0; i < manager->num_frames; ++i) {
        if (manager->frames[i] != NULL) {
            free(manager->frames[i]->rx_buffer);
            free(manager->frames[i]);
        }
    }

    free(manager->frames);
    pthread_mutex_destroy(&manager->mutex);
}

int add_frame(FrameManager* manager, int ue_id, int rf_chain_id, size_t m_rx_symbols) {
    if (manager == NULL || ue_id < 0 || ue_id > MAX_UE_ID || rf_chain_id < 0 || rf_chain_id > MAX_RF_CHAIN_ID || m_rx_symbols == 0) return -1;

    pthread_mutex_lock(&manager->mutex);

    if (manager->num_frames >= manager->max_frames) {
        pthread_mutex_unlock(&manager->mutex);
        return -2;
    }

    LTE_PHY_RX_FRAME* frame = malloc(sizeof(LTE_PHY_RX_FRAME));
    if (!frame) {
        pthread_mutex_unlock(&manager->mutex);
        return -3;
    }

    frame->UE_ID = ue_id;
    frame->RF_CHAIN_ID = rf_chain_id;
    frame->rx_buffer = malloc(m_rx_symbols * sizeof(unsigned char));
    if (!frame->rx_buffer) {
        free(frame);
        pthread_mutex_unlock(&manager->mutex);
        return -4;
    }

    manager->frames[manager->num_frames++] = frame;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int send_frame_over_network(LTE_PHY_RX_FRAME* frame, int api_version) {
    if (frame == NULL || api_version < 1) return -1;

    // Simulated external API call with error handling and retry logic
    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        int result = simulated_network_send(frame, api_version);

        if (result == 0) { // Assuming 0 is success code
            return 0;
        } else if (result != -1) { // Any other non-failure error
            break;
        }

        printf("Retrying send operation... Attempt %d\n", attempt + 1);
    }

    return -1; // Network failure after retries
}

void* async_send_frames(void* arg) {
    FrameManager* manager = (FrameManager*)arg;

    for (size_t i = 0; i < manager->num_frames; ++i) {
        int result = send_frame_over_network(manager->frames[i], 1); // Using version 1 as an example
        if (result != 0) {
            printf("Failed to send frame UE_ID: %d, RF_CHAIN_ID: %d\n", 
                   manager->frames[i]->UE_ID, manager->frames[i]->RF_CHAIN_ID);
        }
    }

    return NULL;
}

void start_async_frame_transmission(FrameManager* manager) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, async_send_frames, (void*)manager)) {
        printf("Failed to create thread for asynchronous frame transmission.\n");
        return;
    }

    // Optionally, join the thread if synchronous operation is desired
    pthread_detach(thread_id);
}

int main() {
    FrameManager manager;
    initialize_frame_manager(&manager, 10000);

    // Example usage
    add_frame(&manager, 1, 0, MAX_RX_SYMBOLS); 
    start_async_frame_transmission(&manager);

    cleanup_frame_manager(&manager);
    return 0;
}

// Simulated network send function for demonstration purposes.
int simulated_network_send(LTE_PHY_RX_FRAME* frame, int api_version) {
    // Implementation-specific network logic goes here
    // Return 0 on success, -1 on failure, other values for non-fatal errors
    return rand() % 2; // Randomly simulate success/failure for illustration
}
