    char *data_buffer;
    size_t buffer_size;
    time_t timeout_value; // in seconds
} TCP_SOCKET;

typedef struct {
    TCP_SOCKET **sessions;
    size_t session_count;
    pthread_mutex_t mutex;
    size_t max_sessions;
} SessionManager;

// Function prototypes
SessionManager* create_session_manager(size_t max_sessions);
TCP_SOCKET* add_session(SessionManager *manager, int session_id, time_t timeout_value);
void adjust_buffer_size(TCP_SOCKET *session, size_t new_size);
void handle_network_conditions(SessionManager *manager);
void free_resources(SessionManager *manager);

// Create a SessionManager with a maximum number of sessions
SessionManager* create_session_manager(size_t max_sessions) {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = (TCP_SOCKET**)calloc(max_sessions, sizeof(TCP_SOCKET*));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    manager->session_count = 0;
    manager->max_sessions = max_sessions;

    return manager;
}

// Add a new session to the SessionManager
TCP_SOCKET* add_session(SessionManager *manager, int session_id, time_t timeout_value) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->session_count >= manager->max_sessions) {
        // Handle backpressure: refuse new connection or log it
        printf("Max sessions reached. Refusing new connection.\n");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    TCP_SOCKET *new_session = (TCP_SOCKET*)malloc(sizeof(TCP_SOCKET));
    if (!new_session) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    new_session->SESSION_ID = session_id;
    new_session->buffer_size = INITIAL_BUFFER_SIZE;
    new_session->data_buffer = (char*)calloc(new_session->buffer_size, sizeof(char));
    new_session->timeout_value = timeout_value;

    manager->sessions[manager->session_count++] = new_session;

    pthread_mutex_unlock(&manager->mutex);
    return new_session;
}

// Adjust the buffer size dynamically based on traffic conditions
void adjust_buffer_size(TCP_SOCKET *session, size_t new_size) {
    if (new_size > session->buffer_size) {
        char *new_buffer = (char*)realloc(session->data_buffer, new_size);
        if (!new_buffer) return; // Handle failure: maintain old buffer and log error
        memset(new_buffer + session->buffer_size, 0, new_size - session->buffer_size);
        session->data_buffer = new_buffer;
    }
    session->buffer_size = new_size;
}

// Simulate handling network conditions to adjust buffers dynamically
void handle_network_conditions(SessionManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->session_count; ++i) {
        // Example condition: if traffic is high, increase buffer size
        size_t new_size = /* logic to determine new size based on conditions */;

        adjust_buffer_size(manager->sessions[i], new_size);
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Free allocated resources for all sessions and the manager itself
void free_resources(SessionManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->session_count; ++i) {
        if (manager->sessions[i]) {
            free(manager->sessions[i]->data_buffer);
            free(manager->sessions[i]);
        }
    }

    free(manager->sessions);
    pthread_mutex_unlock(&manager->mutex);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
