        NFAPI_CRC_INDICATION_PDU_T pdu = {rx_ue_info_tags[i], rntis[i]};
        CRC_INDICATION_REL8_TAG crc_tag = {.CRCFLAG = rand() % 2}; // Randomly set CRCFLAG

        Node* new_node = create_node(pdu, crc_tag);
        if (!new_node) {
            pthread_mutex_unlock(&mutex);
            continue;
        }

        tail->next = new_node;
        tail = new_node;

        pthread_mutex_unlock(&mutex);
    }

    return dummy_head.next;
}

