### Function 2: DNS Query Resolver

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

#define IP_BUFFER_SIZE (4 * sizeof(unsigned char)) // IPv4 address size in bytes

// Error codes for the DNS resolver function.
enum {
    DNS_SUCCESS = 0,
    DNS_ERROR_INVALID_HOSTNAME,
    DNS_ERROR_RESOLVING
};

int resolve_dns(const char* hostname, unsigned char ip_buffer[IP_BUFFER_SIZE]) {
    if (!hostname) return DNS_ERROR_INVALID_HOSTNAME;

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return DNS_ERROR_RESOLVING;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_buffer, &(ipv4->sin_addr), IP_BUFFER_SIZE);
        break; // Use the first result
    }

    freeaddrinfo(res);

    if (memcmp(ip_buffer, "\0\0\0\0", IP_BUFFER_SIZE) == 0) {
        return DNS_ERROR_RESOLVING;
    }

    return DNS_SUCCESS;
}
```

