// Define the Node for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked List structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;  // For thread safety
} CRC_Indication_List;

// Function to initialize the linked list with thread safety
int init_crc_list(CRC_Indication_List* list) {
    if (!list) return -1;  // Invalid input parameter

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        return -2;  // Mutex initialization failed
    }

    return 0;  // Success
}

// Function to add an element to the linked list
int add_crc_indication(CRC_Indication_List* list, uint32_t rx_ue_info_tag, uint16_t rnti) {
    if (!list || !rnti) return -1;  // Invalid input parameter

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;  // Memory allocation failed

    // Populate the node with random CRCFLAG
    srand(time(NULL));  // Seed the random number generator
    int crcflag = rand() % 2;

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);  // Lock the list for thread safety
    new_node->next = list->head;      // Insert at head
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0;  // Success
}

// Function to free all resources associated with the linked list
void free_crc_list(CRC_Indication_List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);  // Destroy the mutex
}

// API Documentation:
//
// init_crc_list(CRC_Indication_List* list): Initializes a new linked list. Returns 0 on success,
// -1 if the input parameter is invalid, or -2 if mutex initialization fails.
//
// add_crc_indication(CRC_Indication_List* list, uint32_t rx_ue_info_tag, uint16_t rnti):
// Adds an NFAPI_CRC_INDICATION_PDU_T to the linked list. Returns 0 on success,
// -1 for invalid input parameters, or -2 if memory allocation fails.
//
// free_crc_list(CRC_Indication_List* list): Frees all resources associated with the linked list.

int main() {
    CRC_Indication_List list;

    // Initialize the linked list
    if (init_crc_list(&list) != 0) {
        fprintf(stderr, "Failed to initialize the list.\n");
        return EXIT_FAILURE;
