Message* create_message(unsigned long messageID) {
    Message *newMsg = (Message*) malloc(sizeof(Message));
    if (!newMsg) return NULL;

    newMsg->timestamp = time(NULL);  // Set current timestamp
    newMsg->messageID = messageID;
    srand(time(0));  // Seed random number generator
    newMsg->priorityLevel = rand() % 10;  // Example priority level assignment

    // Randomly set CRCFLAG
    newMsg->nfaPdu.CRCFLAG = rand() % 2;

    // Initialize other fields as necessary
    newMsg->next = NULL;

    return newMsg;
}

void add_or_update_message(MessageCollection *collection, unsigned long messageID, int priorityLevel) {
    pthread_mutex_lock(&collection->lock);

    Message *current = collection->head;
    Message *prev = NULL;

    while (current != NULL && current->messageID != messageID) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        // Add new message
        Message *newMessage = create_message(messageID);
        if (!newMessage) {
            pthread_mutex_unlock(&collection->lock);
            return;  // Handle allocation failure gracefully
        }

        newMessage->priorityLevel = priorityLevel;
        newMessage->next = collection->head;
        collection->head = newMessage;

    } else {
        // Update existing message
        current->priorityLevel = priorityLevel;
    }

    pthread_mutex_unlock(&collection->lock);
}

Message* get_message_by_id(MessageCollection *collection, unsigned long messageID) {
    pthread_mutex_lock(&collection->lock);

    Message *current = collection->head;
    while (current != NULL && current->messageID != messageID) {
        current = current->next;
    }

    Message *result = current;  // Result could be NULL if not found

    pthread_mutex_unlock(&collection->lock);

    return result;
}

void free_collection(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    Message *current = collection->head;
    while (current != NULL) {
        Message *next = current->next;
        free(current);
        current = next;
    }

    collection->head = NULL;

    pthread_mutex_unlock(&collection->lock);
}

// Initialize the message collection
void init_message_collection(MessageCollection *collection) {
    collection->head = NULL;
    if (pthread_mutex_init(&collection->lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        exit(EXIT_FAILURE);
    }
}

// Clean up the message collection
void destroy_message_collection(MessageCollection *collection) {
    free_collection(collection);
    pthread_mutex_destroy(&collection->lock);
}

