void log_operation(const char* operation) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        time_t now = time(NULL);
        fprintf(file, "%s - %s\n", ctime(&now), operation);
        fclose(file);
    }
}

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    array->add_success_count = 0;
    array->add_failure_count = 0;

    if (!array->data) {
        free(array);
        return NULL;
    }

    log_operation("DynamicArray created");
    return array;
}

void delete_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->data);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);

    log_operation("DynamicArray deleted");
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            array->add_failure_count++;
            log_operation("Failed to add element due to memory allocation");
            return -1;
        }

        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = element;
    array->add_success_count++;

    pthread_mutex_unlock(&array->lock);

    log_operation("Element added successfully");
    return 0;
}

int update_element(DynamicArray* array, unsigned int rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == rnti) {
            array->data[i] = new_data;
            log_operation("Element updated successfully");
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);

    log_operation("Failed to update element - RNTI not found");
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray* array, unsigned int rnti) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!result) {
                pthread_mutex_unlock(&array->lock);
                log_operation("Failed to retrieve element due to memory allocation");
                return NULL;
            }
            *result = array->data[i];
            log_operation("Element retrieved successfully");
            pthread_mutex_unlock(&array->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&array->lock);

    log_operation("Failed to retrieve element - RNTI not found");
    return NULL;
}

int delete_element(DynamicArray* array, unsigned int rnti) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == rnti) {
            memmove(&array->data[i], &array->data[i + 1], (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->size--;
            log_operation("Element deleted successfully");
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);

    log_operation("Failed to delete element - RNTI not found");
    return -1;
}

void compact_array(DynamicArray* array) {
    if (array->size < array->capacity / 2) {
        size_t new_capacity = array->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_data) {
            pthread_mutex_lock(&array->lock);
            array->data = new_data;
            array->capacity = new_capacity;
            pthread_mutex_unlock(&array->lock);

            log_operation("Array compacted successfully");
        }
    }
}

void iterate_reverse(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array->lock);

    for (int i = array->size - 1; i >= 0; --i) {
        callback(&array->data[i]);
    }

    pthread_mutex_unlock(&array->lock);

    log_operation("Array iterated in reverse order");
}

void random_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
}
