#include <time.h>

#define MAX_LIST_SIZE 5000
#define LOG_FILE_PATH "log.txt"

typedef struct {
    int CELL_ID;
    float TX_POWER;
    char PHY_TEST_INDICATION[256];
} LTE_PHY_TEST_MESSAGE;

typedef struct Node {
    LTE_PHY_TEST_MESSAGE data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    int successful_allocations;
    int failed_allocations;
    FILE* log_file;
} MessageList;

typedef struct {
    int cell_id_history[24];
    time_t timestamps[24];
    pthread_mutex_t lock;
} CellHistory;

CellHistory history;
MessageList list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, 0, 0, NULL};
int ongoing_sessions = 0;
size_t total_attempts = 0;

void log_error(const char* message) {
    if (!list.log_file) {
        list.log_file = fopen(LOG_FILE_PATH, "a");
        if (!list.log_file) return;
    }
    fprintf(list.log_file, "%s\n", message);
}

int is_valid_cell_id(int cell_id) {
    pthread_mutex_lock(&history.lock);

    time_t now = time(NULL);
    for (int i = 0; i < 24; ++i) {
        if (difftime(now, history.timestamps[i]) < 86400 && history.cell_id_history[i] == cell_id)
            return 0;
    }

    // Shift history
    for (int i = 23; i > 0; --i) {
        history.cell_id_history[i] = history.cell_id_history[i - 1];
        history.timestamps[i] = history.timestamps[i - 1];
    }
    history.cell_id_history[0] = cell_id;
    history.timestamps[0] = now;

    pthread_mutex_unlock(&history.lock);
    return 1;
}

void add_message(LTE_PHY_TEST_MESSAGE message) {
    if (list.size >= MAX_LIST_SIZE || !is_valid_cell_id(message.CELL_ID)) {
        log_error("Failed to allocate memory or invalid cell ID");
        list.failed_allocations++;
        return;
    }

    pthread_mutex_lock(&list.lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for new node");
        list.failed_allocations++;
        pthread_mutex_unlock(&list.lock);
        return;
    }

    memcpy(&new_node->data, &message, sizeof(LTE_PHY_TEST_MESSAGE));
    new_node->next = NULL;

    if (list.head && strcmp((char*)list.head->data.PHY_TEST_INDICATION,
                            message.PHY_TEST_INDICATION) == 0 &&
        list.head->data.CELL_ID == message.CELL_ID) {
        free(new_node);
        log_error("Consecutive duplicate cell ID detected");
        pthread_mutex_unlock(&list.lock);
        return;
    }

    if (list.head) {
        Node* current = list.head;
        while (current->next && strcmp((char*)current->next->data.PHY_TEST_INDICATION,
                                      message.PHY_TEST_INDICATION) != 0) {
            current = current->next;
        }
        if (current->next && current->next->data.CELL_ID == message.CELL_ID) {
            free(new_node);
            log_error("Consecutive duplicate cell ID detected");
            pthread_mutex_unlock(&list.lock);
            return;
        }
    }

    new_node->next = list.head;
    list.head = new_node;
    list.size++;
    list.successful_allocations++;

    pthread_mutex_unlock(&list.lock);
}

void start_test_session() {
    pthread_mutex_lock(&history.lock);
    ongoing_sessions++;
    total_attempts++;
    pthread_mutex_unlock(&history.lock);
}

void end_test_session() {
    pthread_mutex_lock(&history.lock);
    if (ongoing_sessions > 0) ongoing_sessions--;
    pthread_mutex_unlock(&history.lock);
}

// Example usage
int main() {
    LTE_PHY_TEST_MESSAGE message = {1, -10.5, "Test"};
    start_test_session();
    add_message(message);
    end_test_session();

    return 0;
}
```

### Key Features:
- **Concurrency**: Uses `pthread_mutex_t` for thread-safe access to shared resources.
- **Dynamic Memory Management**: Efficiently handles allocation and checks list size constraints.
- **Cell ID Validation**: Maintains a history of cell IDs for the past 24 hours to prevent reuse.
- **Logging**: Logs failed operations, ensuring minimal performance impact with file-based logging.
- **Error Handling**: Gracefully manages memory failures and logs errors appropriately.

This code ensures thread safety, efficient memory use, and robust error handling while managing test sessions and logging errors effectively.']

