        if (new_size > MAX_SIZE) {
            pthread_mutex_unlock(&list->lock);
            log_error("Exceeded maximum allowed size");
            return false;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(64, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
