```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE 1000

typedef struct {
    uint16_t rnti;
} RNTI_TAG;

typedef struct {
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    time_t timestamp;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI_TAG rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_random_seed(unsigned int seed) {
    srand(seed);
}

uint16_t generate_unique_rnti(uint16_t start, uint16_t end, uint16_t* used_rntis, size_t used_count) {
    while (1) {
        uint16_t rnti = start + rand() % (end - start + 1);
        for (size_t i = 0; i < used_count; ++i) {
            if (used_rntis[i] == rnti) continue;
        }
        return rnti;
    }
}

void log_memory_usage(const char* message, size_t current_size) {
    printf("%s: %zu bytes\n", message, sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_size);
}

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    array->data = new_data;
    array->capacity = new_capacity;
    log_memory_usage("Resized Dynamic Array", new_capacity);
    return 0;
}

void populate_array(DynamicArray* array, size_t N, uint16_t rnti_start, uint16_t rnti_end) {
    if (N <= 0 || N > MAX_SIZE) return;

    pthread_mutex_lock(&array->lock);

    if (array->size + N > array->capacity) {
        size_t new_capacity = (array->capacity * 2 > array->size + N) ? array->capacity * 2 : array->size + N;
        if (resize_dynamic_array(array, new_capacity) != 0) {
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    uint16_t* used_rntis = (uint16_t*)malloc(array->size * sizeof(uint16_t));
    for (size_t i = 0; i < array->size; ++i) {
        used_rntis[i] = array->data[i].rnti;
    }

    time_t current_time = time(NULL);

    for (size_t i = array->size; i < array->size + N; ++i) {
        array->data[i].rx_ue_info_tag.timestamp = current_time;
        array->data[i].rnti.rnti = generate_unique_rnti(rnti_start, rnti_end, used_rntis, array->size);
        array->data[i].crc_indication_rel8_tag.crcflag = rand() % 2;

        if (i == array->capacity - 1) {
            size_t new_capacity = array->capacity * 2;
            free(used_rntis);
            pthread_mutex_unlock(&array->lock);

            if (resize_dynamic_array(array, new_capacity) != 0) return;

            used_rntis = (uint16_t*)malloc(new_capacity * sizeof(uint16_t));
            for (size_t j = 0; j < array->size; ++j) {
                used_rntis[j] = array->data[j].rnti.rnti;
            }
        }
    }

    free(used_rntis);
    array->size += N;

    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    free(array->data);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    init_random_seed(42); // For reproducibility

    DynamicArray* array = create_dynamic_array(10);
    if (!array) return -1;

    populate_array(array, 15, 1000, 2000);

    for (size_t i = 0; i < array->size; ++i) {
        printf("RNTI: %d, CRCFLAG: %d, Timestamp: %ld\n",
               array->data[i].rnti.rnti,
               array->data[i].crc_indication_rel8_tag.crcflag,
               array->data[i].rx_ue_info_tag.timestamp);
    }

    free_dynamic_array(array);

    return 0;
}
