#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 50 * 1024 * 1024 // 50 MB
#define LENGTH_THRESHOLD 100
#define SUFFIX "Suffix"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set between 0 and 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to process strings
char* process_string(const char* str) {
    size_t len = strlen(str);
    if (len < LENGTH_THRESHOLD) {
        char* new_str = malloc(len + strlen(SUFFIX) + 1);
        if (!new_str) return NULL;
        strcpy(new_str, str);
        strcat(new_str, SUFFIX);
        return new_str;
    }
    return NULL;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure
int add_pdu(Node** head) {
    pthread_mutex_lock(&lock);

    if (pthread_mutex_trylock(&lock) != 0) {
        pthread_mutex_unlock(&lock);
        return -1; // Memory usage too high or lock busy
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    int current_usage = sizeof(*head) * 1024; // Approximate memory used by the list structure

    for (Node* iter = *head; iter != NULL; iter = iter->next) {
        current_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    if (current_usage + sizeof(Node) > MAX_MEMORY_USAGE) {
        free(new_node);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rand() % 100; // Example generation
    new_node->data.RNTI = rand() % 1000;
    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 10;
    new_node->data.CRCFLAG = rand() % 2;

    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

// Function to remove all nodes from the list, deallocating memory
void clear_list(Node** head) {
    pthread_mutex_lock(&lock);

    Node* current = *head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    *head = NULL;

    pthread_mutex_unlock(&lock);
}

// Function to log operations
void log_operation(const char* message) {
    static FILE* log_file = NULL;
    if (!log_file) {
        log_file = fopen("operations.log", "a");
        if (!log_file) return; // Error opening file, continue silently
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file); // Ensure the operation is logged immediately
}

int main() {
    Node* pdu_list = NULL;

    for (int i = 0; i < 100; ++i) {
        if (add_pdu(&pdu_list) != 0) {
            log_operation("Failed to add PDU due to memory constraints.");
            break;
        }
    }

    // Example usage of process_string
    char* processed = process_string("ExampleString");
    if (processed) {
        printf("Processed String: %s\n", processed);
        free(processed);
    } else {
        log_operation("String processing failed or exceeded length threshold.");
    }

    clear_list(&pdu_list);

    fclose(log_file);
    pthread_mutex_destroy(&lock);

    return 0;
}
