#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_QUEUES 8

typedef struct {
    // Add necessary fields to store buffer information
} RX_BUFFER_INFO;

typedef struct {
    // Define the required queue parameters
    size_t descriptor_count;
} RX_QUEUE_PARAMETERS;

typedef struct {
    RX_BUFFER_INFO **rx_buffers;
    size_t num_rx_queues;
    pthread_mutex_t mutex;  // Mutex for thread safety
} NIC_RX_QUEUE_CONFIG;

typedef struct {
    void *tx_buffers;
    size_t num_tx_queues;
    pthread_mutex_t mutex;  // Mutex for thread safety
} NIC_TX_QUEUE_CONFIG;

typedef struct {
    NIC_RX_QUEUE_CONFIG rx_queue_config;
    NIC_TX_QUEUE_CONFIG tx_queue_config;
    pthread_mutex_t config_mutex;  // Global mutex for overall configuration
} NIC_DRIVER_CONFIG;

int initialize_nic_configuration(NIC_DRIVER_CONFIG *config, size_t num_rx_queues, size_t num_tx_queues,
                                 RX_QUEUE_PARAMETERS *rx_params, size_t rx_buffers_per_queue) {
    if (!config || !rx_params || (num_rx_queues > MAX_QUEUES)) return -1;  // Error handling

    pthread_mutex_init(&config->config_mutex, NULL);

    config->rx_queue_config.num_rx_queues = num_rx_queues;
    config->rx_queue_config.rx_buffers = malloc(sizeof(RX_BUFFER_INFO*) * num_rx_queues);
    if (!config->rx_queue_config.rx_buffers) {
        perror("Failed to allocate memory for RX buffers");
        return -1;  // Memory allocation failure
    }

    pthread_mutex_init(&config->rx_queue_config.mutex, NULL);

    for (size_t i = 0; i < num_rx_queues; ++i) {
        config->rx_queue_config.rx_buffers[i] = malloc(sizeof(RX_BUFFER_INFO*) * rx_params[i].descriptor_count);
        if (!config->rx_queue_config.rx_buffers[i]) {
            perror("Failed to allocate memory for RX queue buffers");
            // Free previously allocated resources
            for (size_t j = 0; j < i; ++j) free(config->rx_queue_config.rx_buffers[j]);
            free(config->rx_queue_config.rx_buffers);
            pthread_mutex_destroy(&config->rx_queue_config.mutex);
            return -1;
        }

        for (size_t j = 0; j < rx_params[i].descriptor_count; ++j) {
            config->rx_queue_config.rx_buffers[i][j] = malloc(sizeof(RX_BUFFER_INFO));
            if (!config->rx_queue_config.rx_buffers[i][j]) {
                perror("Failed to allocate RX buffer");
                free(config->rx_queue_config.rx_buffers[i]);
