static uint64_t uniqueTagCounter = 0;

uint64_t generateUniqueTag(uint32_t rnti) {
    static const uint64_t prime_multiplier = 6364136223846793005ULL;
    time_t current_time = time(NULL);

    // Create a pseudo-unique tag using RNTI, timestamp and unique counter
    uint64_t tag = ((uint64_t)rnti << 32) | (current_time & 0xFFFFFFFFULL);
    uniqueTagCounter++;
    return (tag * prime_multiplier) ^ uniqueTagCounter;
}

