```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Mock definitions for demonstration purposes.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_THREADS 4
#define RETRY_LIMIT 3

// Mock logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

typedef struct {
    size_t batch_size;
    int seed;
    pthread_mutex_t lock;
} Config;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    int retries;
} Task;

// Thread pool structure
typedef struct {
    pthread_t threads[MAX_THREADS];
    Config config;
    pthread_mutex_t task_queue_lock;
    pthread_cond_t task_ready;
    Task tasks[10]; // Arbitrary queue size for demonstration.
    int task_count;
} ThreadPool;

ThreadPool *create_thread_pool(size_t batch_size, int seed) {
    ThreadPool *pool = (ThreadPool *)malloc(sizeof(ThreadPool));
    pool->config.batch_size = batch_size;
    pool->config.seed = seed;
    pthread_mutex_init(&pool->config.lock, NULL);
    pthread_mutex_init(&pool->task_queue_lock, NULL);
    pthread_cond_init(&pool->task_ready, NULL);
    pool->task_count = 0;

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&pool->threads[i], NULL, thread_function, pool);
    }

    return pool;
}

void destroy_thread_pool(ThreadPool *pool) {
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_cancel(pool->threads[i]);
    }
    pthread_mutex_destroy(&pool->config.lock);
    pthread_mutex_destroy(&pool->task_queue_lock);
    pthread_cond_destroy(&pool->task_ready);

    free(pool);
}

void *thread_function(void *arg) {
    ThreadPool *pool = (ThreadPool *)arg;
    while (1) {
        pthread_mutex_lock(&pool->task_queue_lock);
        while (pool->task_count == 0) {
            pthread_cond_wait(&pool->task_ready, &pool->task_queue_lock);
        }

        Task task = pool->tasks[--pool->task_count];
        pthread_mutex_unlock(&pool->task_queue_lock);

        process_task(task, &pool->config);
    }
    return NULL;
}

void enqueue_task(ThreadPool *pool, NFAPI_CRC_INDICATION_PDU_T *data, size_t size) {
    Task task = { .data = data, .size = size, .retries = 0 };

    pthread_mutex_lock(&pool->task_queue_lock);
    pool->tasks[pool->task_count++] = task;
    pthread_cond_signal(&pool->task_ready);
    pthread_mutex_unlock(&pool->task_queue_lock);
}

void process_task(Task task, Config *config) {
    for (size_t i = 0; i < task.size; ++i) {
        if (!allocate_and_initialize_pdu(&(task.data[i]), config)) {
            if (++task.retries > RETRY_LIMIT) {
                log_message("Max retry limit reached. Task failed.");
                return;
            }
            log_message("Retrying task...");
            process_task(task, config);
            return;
        }
    }

    log_message("Task completed successfully.");
}

int allocate_and_initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, Config *config) {
    srand(config->seed + (unsigned int)(pdu - &((NFAPI_CRC_INDICATION_PDU_T){0})));

    // Simulate allocation and initialization
    pdu->RX_UE_INFORMATION_TAG = rand() % 100;
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) == 0 ? 1 : 0;

    if (!pdu->RX_UE_INFORMATION_TAG || !pdu->RNTI) {
        log_message("Failed to initialize PDU.");
        return 0; // Simulate failure
    }

    log_message("PDU initialized successfully.");
    return 1;
}

void generate_batches(ThreadPool *pool, size_t total_size) {
    for (size_t i = 0; i < total_size; i += pool->config.batch_size) {
        NFAPI_CRC_INDICATION_PDU_T *batch = malloc(pool->config.batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!batch) {
            log_message("Memory allocation failed.");
            continue;
        }

        size_t current_batch_size = (i + pool->config.batch_size > total_size)
                                    ? total_size - i
                                    : pool->config.batch_size;

        enqueue_task(pool, batch, current_batch_size);
    }
}

int main() {
    ThreadPool *pool = create_thread_pool(5, 12345);

    generate_batches(pool, 20); // Example usage

    sleep(2); // Allow some time for threads to process tasks.

    destroy_thread_pool(pool);

    return 0;
}
```

