#define CRCFLAG_VALID_MAX 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned long memory_usage; // Track the current memory usage
} NFAPIMemoryPool;

// External library callbacks (placeholders)
void generate_RX_UE_INFORMATION_TAG(int* tag) {
    *tag = rand() % 1000; // Example logic
}

void generate_RNTI(int* rnti) {
    *rnti = rand() % 500; // Example logic
}

NFAPIMemoryPool* create_memory_pool(size_t initial_capacity) {
    NFAPIMemoryPool* pool = (NFAPIMemoryPool*)malloc(sizeof(NFAPIMemoryPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->memory_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity;

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool->memory_usage);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

int resize_memory_pool(NFAPIMemoryPool* pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return 0;

    NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(pool->pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_pool) return -1;

    pool->capacity = new_capacity;
    pool->memory_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity;
    pool->pool = new_pool;

    return 0;
}

void free_memory_pool(NFAPIMemoryPool* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->pool);
        free(pool);
    }
}

int validate_and_set_crcflag(int crc_flag, int default_value) {
    return (crc_flag >= CRCFLAG_VALID_MIN && crc_flag <= CRCFLAG_VALID_MAX) ? crc_flag : default_value;
}

void add_structure(NFAPIMemoryPool* pool, unsigned long seed) {
    if (!pool || pool->count == pool->capacity) {
        if (resize_memory_pool(pool, pool->capacity * 2)) {
            fprintf(stderr, "Failed to resize memory pool\n");
            return;
        }
    }

    srand(seed);

    pthread_mutex_lock(&pool->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pool[pool->count++];
    generate_RX_UE_INFORMATION_TAG(&(pdu->RX_UE_INFORMATION_TAG));
    generate_RNTI(&(pdu->RNTI));

    int crc_flag = rand() % 3; // Random CRCFLAG between 0 and 2
    pdu->CRC_INDICATION_REL8_TAG = rand(); // Example tag
    pdu->CRCFLAG = validate_and_set_crcflag(crc_flag, 1);

    pthread_mutex_unlock(&pool->lock);
}

void monitor_and_reclaim_memory(NFAPIMemoryPool* pool) {
    if (pool->memory_usage > MAX_MEMORY_USAGE_THRESHOLD && pool->count < pool->capacity / 2) {
        size_t new_capacity = pool->capacity / 2;
        if (!resize_memory_pool(pool, new_capacity)) {
            printf("Memory reclaimed. New capacity: %zu\n", new_capacity);
        }
    }
}

void log_status(NFAPIMemoryPool* pool) {
    fprintf(stdout, "Valid structures count: %zu\n", pool->count);
}

int main() {
    NFAPIMemoryPool* pool = create_memory_pool(INITIAL_SIZE);
    if (!pool) return EXIT_FAILURE;

    for (unsigned long i = 0; i < 100; ++i) { // Example loop to populate structures
        add_structure(pool, i);
        monitor_and_reclaim_memory(pool);
    }

    log_status(pool);

    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
