            frames[i].TX_SAMPLE[2*j + 1] = ((double)rand() / RAND_MAX - 0.5); // imag part
        }

        // Allocate and initialize RX sample array, initially as a copy of TX samples
        frames[i].RX_SAMPLE = malloc(2 * samples_per_symbol * sizeof(float));
