#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* batch;
    size_t count;
} BatchData;

pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
int current_logging_level = 1; // Example logging level
int max_concurrent_threads = MAX_THREADS;

void log_message(int level, const char* message) {
    if (level <= current_logging_level) {
        printf("%s\n", message);
    }
}

BatchData generate_batch(size_t batch_size) {
    BatchData data;
    pthread_mutex_lock(&config_mutex);

    if (batch_size == 0) {
        log_message(1, "Invalid batch size: zero");
        pthread_mutex_unlock(&config_mutex);
        return (BatchData){NULL, 0};
    }

    data.batch = malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data.batch) {
        log_message(1, "Failed to allocate memory for batch");
        pthread_mutex_unlock(&config_mutex);
        return (BatchData){NULL, 0};
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = 0; i < batch_size; ++i) {
        data.batch[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        data.batch[i].RNTI = rand() % 5000;
        data.batch[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }

    log_message(2, "Batch successfully generated");
    pthread_mutex_unlock(&config_mutex);

    return (BatchData){data.batch, batch_size};
}

void process_batch(BatchData* data) {
    // Placeholder for processing logic
    log_message(3, "Processing batch...");
    free(data->batch);
}

int retry_with_backoff(int attempt) {
    int backoff_time = 1 << attempt;
    if (attempt > 0) {
        sleep(backoff_time); // Exponential backoff
    }
    return rand() % 2; // Simulate network condition success or failure
}

void* thread_function(void* arg) {
    BatchData* data = (BatchData*)arg;
    int retry_count = 0;
    const int max_retries = 5;

    while (retry_count < max_retries) {
        if (retry_with_backoff(retry_count)) {
            process_batch(data);
            log_message(2, "Batch processed successfully");
            break;
        } else {
            log_message(1, "Network failure, retrying...");
            retry_count++;
        }
    }

    if (retry_count == max_retries) {
        log_message(1, "Max retries reached, batch failed");
    }

    pthread_exit(NULL);
}

void manage_batches(size_t batch_size) {
    BatchData data = generate_batch(batch_size);

    if (!data.batch) return; // Handle allocation failure

    pthread_t threads[max_concurrent_threads];
    int active_threads = 0;

    for (size_t i = 0; i < batch_size && active_threads < max_concurrent_threads; ++i, ++active_threads) {
        if (pthread_create(&threads[i], NULL, thread_function, &data)) {
            log_message(1, "Failed to create thread");
            continue;
        }
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void update_configuration(int new_logging_level, int new_max_concurrent_threads) {
    pthread_mutex_lock(&config_mutex);

    current_logging_level = new_logging_level;
    max_concurrent_threads = (new_max_concurrent_threads > 0 && new_max_concurrent_threads <= MAX_THREADS)
                             ? new_max_concurrent_threads : MAX_THREADS;

    log_message(2, "Configuration updated");

    pthread_mutex_unlock(&config_mutex);
}

int main() {
    size_t batch_size = 10; // Example size

    manage_batches(batch_size);

    update_configuration(2, 8); // Update configuration dynamically

    return 0;
}
```

