#define MAX_IP_LENGTH 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int resolveDNSAndAllocateCRCIndications(const char* hostname, int N, int networkInterface) {
    struct addrinfo hints, *res, *p;
    u_char ipAddress[MAX_IP_LENGTH];
    NFAPI_CRC_INDICATION_PDU_T *crcArray = NULL;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        perror("DNS resolution failed");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else {
            continue;
        }

        inet_ntop(p->ai_family, addr, ipAddress, sizeof(ipAddress));
        printf("Resolved IP: %s\n", ipAddress);
        break;
    }

    freeaddrinfo(res);

    crcArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray) {
        perror("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < N; ++i) {
        crcArray[i].RX_UE_INFORMATION_TAG = rand() % 256;
        crcArray[i].RNTI = rand() % 65536;

        // Determine CRCFLAG based on a predefined logic
        if ((crcArray[i].RX_UE_INFORMATION_TAG & 0x1F) == (crcArray[i].RNTI & 0xF)) {
            crcArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        } else {
            crcArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }
    }

    // Dummy validation of allocated memory
    for (int i = 0; i < N; ++i) {
        if (!(crcArray[i].RX_UE_INFORMATION_TAG >= 0 && crcArray[i].RNTI >= 0)) {
            free(crcArray);
            return -1;
        }
    }

    // Assume networkInterface is used appropriately here
    printf("Allocated structures for interface %d\n", networkInterface);

    // Release allocated memory when no longer needed
    free(crcArray);

    return 0; // Success
}
