import threading

typedef enum {
    LOG_EVENT_TYPE_A,
    LOG_EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    char *message;
} NetworkEventLogEntry;

typedef struct {
    size_t capacity;
    size_t count;
    NetworkEventLogEntry *entries;
    pthread_mutex_t lock;
} LogArray;

// Initialize the log array
void init_log_array(LogArray *log_array, size_t initial_capacity) {
    log_array->capacity = initial_capacity;
    log_array->count = 0;
    log_array->entries = malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    pthread_mutex_init(&log_array->lock, NULL);
}

// Resize the log array
void resize_log_array(LogArray *log_array) {
    size_t new_capacity = log_array->capacity * 2;
    NetworkEventLogEntry *new_entries = realloc(log_array->entries, new_capacity * sizeof(NetworkEventLogEntry));
    if (new_entries) {
        log_array->entries = new_entries;
        log_array->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize log array\n");
        exit(EXIT_FAILURE);
    }
}

// Add a new entry to the log array
void add_log_entry(LogArray *log_array, time_t timestamp, EventType event_type, const char *message) {
    pthread_mutex_lock(&log_array->lock);

    if (log_array->count >= log_array->capacity) {
        resize_log_array(log_array);
    }

    NetworkEventLogEntry *entry = &log_array->entries[log_array->count++];
    entry->timestamp = timestamp;
    entry->event_type = event_type;
    entry->message = strdup(message);

    pthread_mutex_unlock(&log_array->lock);
}

// Print all log entries
void print_log_entries(LogArray *log_array) {
    for (size_t i = 0; i < log_array->count; ++i) {
        NetworkEventLogEntry *entry = &log_array->entries[i];
        printf("Timestamp: %ld, Event Type: %d, Message: %s\n",
               entry->timestamp, entry->event_type, entry->message);
    }
}

// Free the log array
void free_log_array(LogArray *log_array) {
    pthread_mutex_lock(&log_array->lock);

    for (size_t i = 0; i < log_array->count; ++i) {
        free(log_array->entries[i].message);
    }

    free(log_array->entries);
    pthread_mutex_unlock(&log_array->lock);
    pthread_mutex_destroy(&log_array->lock);
}

// Example usage
int main() {
    LogArray log_array;
    init_log_array(&log_array, 10);

    add_log_entry(&log_array, time(NULL), LOG_EVENT_TYPE_A, "First log entry");
    add_log_entry(&log_array, time(NULL), LOG_EVENT_TYPE_B, "Second log entry");

    print_log_entries(&log_array);
    free_log_array(&log_array);

    return 0;
}
```

This code provides a thread-safe dynamic array implementation for `NetworkEventLogEntry` structures. It includes mechanisms for resizing the array to accommodate new entries and ensures safe concurrent access using mutex locks. The design supports future extensions by allowing additional fields in the structure with minimal changes.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    EVENT_TYPE_INFO,
    EVENT_TYPE_WARNING,
    EVENT_TYPE_ERROR
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    char message[256];
} NetworkEventLogEntry;

typedef struct {
    NetworkEventLogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
    size_t max_size;
    void (*notification_callback)(void);
} NetworkEventLog;

// Notification callback function prototype
void default_notification_callback(void);

NetworkEventLog* initialize_log(size_t initial_capacity, size_t max_size, void (*notification_callback)(void)) {
    NetworkEventLog *log = (NetworkEventLog *)malloc(sizeof(NetworkEventLog));
    if (!log) return NULL;

    log->entries = (NetworkEventLogEntry *)calloc(initial_capacity, sizeof(NetworkEventLogEntry));
    if (!log->entries) {
        free(log);
        return NULL;
    }

    pthread_rwlock_init(&log->lock, NULL);
    log->capacity = initial_capacity;
    log->count = 0;
    log->max_size = max_size;
    log->notification_callback = notification_callback ? notification_callback : default_notification_callback;

    return log;
}

void append_entry(NetworkEventLog *log, EventType event_type, const char *message) {
    pthread_rwlock_wrlock(&log->lock);

    if (log->count == log->capacity) {
        size_t new_capacity = log->capacity * 2;
        NetworkEventLogEntry *new_entries = realloc(log->entries, new_capacity * sizeof(NetworkEventLogEntry));

        if (!new_entries) {
            pthread_rwlock_unlock(&log->lock);
            return; // Handle memory allocation failure
        }

        log->entries = new_entries;
        log->capacity = new_capacity;
    }

    time_t now = time(NULL);
    NetworkEventLogEntry *entry = &log->entries[log->count++];
    entry->timestamp = now;
    entry->event_type = event_type;
    strncpy(entry->message, message, sizeof(entry->message) - 1);

    if (log->count > log->max_size) {
        memmove(log->entries, log->entries + 1, (--log->count) * sizeof(NetworkEventLogEntry));
        if (log->notification_callback) log->notification_callback();
    }

    pthread_rwlock_unlock(&log->lock);
}

void print_log(NetworkEventLog *log) {
    pthread_rwlock_rdlock(&log->lock);

    for (size_t i = 0; i < log->count; ++i) {
        printf("Timestamp: %ld, Event Type: %d, Message: %s\n",
               log->entries[i].timestamp,
               log->entries[i].event_type,
               log->entries[i].message);
    }

    pthread_rwlock_unlock(&log->lock);
}

void clear_log(NetworkEventLog *log) {
    pthread_rwlock_wrlock(&log->lock);

    memset(log->entries, 0, sizeof(NetworkEventLogEntry) * log->capacity);
    log->count = 0;

    pthread_rwlock_unlock(&log->lock);
}

void free_log(NetworkEventLog *log) {
    if (log) {
        free(log->entries);
        pthread_rwlock_destroy(&log->lock);
        free(log);
    }
}

// Default notification callback
void default_notification_callback(void) {
    printf("Log reached maximum capacity. Oldest entries discarded.\n");
}
```

This code provides a thread-safe, dynamic logging system using reader-writer locks (`pthread_rwlock_t`) to balance performance and synchronization overhead. The log dynamically resizes as needed and uses memory efficiently with `calloc` for initial allocation and `realloc` for resizing. It includes mechanisms for appending entries, iterating over the log, clearing it, and notifying when capacity is exceeded.']

