    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    size_t current_size = 0;
    int retry_count;

    list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand(time(NULL));

    while (1) {
        for (size_t i = 0; i < max_size; ++i) {
            uint16_t RX_TAG = rand() % MAX_RNTI + 1;
            uint16_t RNTI = rand() % MAX_RNTI + 1;

            if (!validate_data(RX_TAG, RNTI)) {
                log_error("Invalid data encountered");
                continue;
            }

            NFAPI_CRC_INDICATION_PDU_T *pdu = &list[i];
            pdu->RX_UE_INFORMATION_TAG = RX_TAG;
            pdu->RNTI = RNTI;
            pdu->CRC_TAG.CRCFLAG = rand() % 2;

            current_size++;
        }

        if (current_size > 0 && cb) {
            cb(list, current_size);
        }

        total_entries_processed += current_size;

        // Check for resize necessity
        if (current_size == max_size) {
            size_t new_max_size = max_size * 2;
            NFAPI_CRC_INDICATION_PDU_T* temp_list = realloc(list, new_max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!temp_list) {
                log_error("Memory reallocation failed");
                free(list);
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            list = temp_list;
            max_size = new_max_size;
        }

        // Retry logic
        retry_count = 0;
        while (retry_count < RETRY_LIMIT) {
            if (/* Check for hardware/network failure condition */) {
                log_error("Hardware/network failure, retrying...");
                retry_count++;
                sleep(1); // Backoff before retrying
            } else {
                break; // Exit retry loop if no failures
            }
        }

        if (retry_count == RETRY_LIMIT) {
            log_error("Max retries reached");
            free(list);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Break condition or sleep for some time to simulate real-world conditions
        break;
    }

    pthread_mutex_unlock(&lock);
    return list;
}

void process_completed_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t count) {
    // Process the completed list (asynchronously)
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = manage_crc_indications(INITIAL_MAX_SIZE, process_completed_list);
    if (!list) {
        fprintf(stderr, "Failed to manage CRC indications.\n");
        return EXIT_FAILURE;
    }

    // Free the allocated memory
    free(list);

    return EXIT_SUCCESS;
}
