    PHY_TASK* phy_task_ptr;
    MAC_TASK* mac_task_ptr;
} MAC_CONTEXT;

// External service mock functions
PHY_TASK* initialize_phy_task() {
    // Simulate external service call with random delay or failure rate.
    return (PHY_TASK*)malloc(sizeof(PHY_TASK));
}

MAC_TASK* initialize_mac_task() {
    // Simulate external service call with random delay or failure rate.
    return (MAC_TASK*)malloc(sizeof(MAC_TASK));
}

// Function to validate and allocate MAC_CONTEXT array
MAC_CONTEXT* allocate_mac_contexts(size_t N) {
    if (N == 0) {
        fprintf(stderr, "Invalid input size: Must be greater than zero.\n");
        return NULL;
    }

    // Allocate memory for the MAC_CONTEXT array
    MAC_CONTEXT* contexts = (MAC_CONTEXT*)malloc(N * sizeof(MAC_CONTEXT));
    if (!contexts) {
        perror("Memory allocation failed for MAC_CONTEXT array");
        return NULL;
    }

    // Use threads to initialize PHY_TASK and MAC_TASK in parallel
    auto phy_task_initializer = [&](size_t i) {
        contexts[i].phy_task_ptr = initialize_phy_task();
        if (!contexts[i].phy_task_ptr) {
            fprintf(stderr, "Failed to allocate PHY_TASK for index %zu\n", i);
            // Handle failure case, e.g., freeing partially allocated array
            free_mac_contexts(contexts, N);  // Helper function to clean up
            return;
        }
    };

    auto mac_task_initializer = [&](size_t i) {
        contexts[i].mac_task_ptr = initialize_mac_task();
        if (!contexts[i].mac_task_ptr) {
            fprintf(stderr, "Failed to allocate MAC_TASK for index %zu\n", i);
            free(contexts[i].phy_task_ptr);  // Clean up already allocated PHY_TASK
            free_mac_contexts(contexts, N);
            return;
        }
    };

    std::vector<thread> phy_threads;
    std::vector<thread> mac_threads;

    for (size_t i = 0; i < N; ++i) {
        phy_threads.push_back(thread(phy_task_initializer, i));
        mac_threads.push_back(thread(mac_task_initializer, i));
    }

    for (auto& t : phy_threads) t.join();
    for (auto& t : mac_threads) t.join();

    // Optional: Implement readiness checks and logging as necessary
    return contexts;
}

// Helper function to free allocated MAC_CONTEXT array.
void free_mac_contexts(MAC_CONTEXT* contexts, size_t N) {
    if (!contexts) return;

    for (size_t i = 0; i < N; ++i) {
        if (contexts[i].phy_task_ptr) {
            free(contexts[i].phy_task_ptr);
        }
        if (contexts[i].mac_task_ptr) {
            free(contexts[i].mac_task_ptr);
        }
    }

    free(contexts);
}
