#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *array;
    pthread_mutex_t mutex;
} CRCArray;

// Custom file interface
typedef struct {
    void (*serialize)(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *data, size_t count);
    int (*deserialize)(NFAPI_CRC_INDICATION_PDU_T **data, size_t *count, const char *filename);
} FileInterface;

// Initialize CRCArray
CRCArray* crc_array_init(size_t initial_capacity) {
    CRCArray *arr = (CRCArray*)malloc(sizeof(CRCArray));
    if (!arr) return NULL;

    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);

    arr->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(arr->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    return arr;
}

// Free CRCArray
void crc_array_free(CRCArray *arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    pthread_mutex_unlock(&arr->mutex);

    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

// Resize array if necessary
int resize_if_necessary(CRCArray *arr, size_t new_size) {
    pthread_mutex_lock(&arr->mutex);

    if (new_size > arr->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *temp = realloc(arr->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!temp) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }

        arr->array = temp;
        arr->capacity = new_size;
    }

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Add a new entry
int crc_array_add(CRCArray *arr, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    if (resize_if_necessary(arr, arr->size + 1) != 0)
        return -1;

    pthread_mutex_lock(&arr->mutex);
    arr->array[arr->size] = new_entry;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);

    return 0;
}

// File interface implementation
void custom_serialize(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *data, size_t count) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    fclose(file);
}

int custom_deserialize(NFAPI_CRC_INDICATION_PDU_T **data, size_t *count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    size_t items = filesize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(items * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!*data) {
        fclose(file);
        return -1;
    }

    fread(*data, sizeof(NFAPI_CRC_INDICATION_PDU_T), items, file);
    fclose(file);

    *count = items;
    return 0;
}

// Usage example
int main() {
    // Initialize CRCArray with initial capacity
    CRCArray *array = crc_array_init(10);

    if (!array) {
        fprintf(stderr, "Failed to initialize array\n");
        return EXIT_FAILURE;
    }

    // Example File Interface setup
    FileInterface file_ops = { custom_serialize, custom_deserialize };

    // Add entries (example)
    for (size_t i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry = {
            .RX_UE_INFORMATION_TAG = i,
            .RNTI = i * 2,
            .crc_tag = {.CRCFLAG = rand() % 2}
        };

        if (crc_array_add(array, entry) != 0) {
            fprintf(stderr, "Failed to add entry\n");
            crc_array_free(array);
            return EXIT_FAILURE;
        }
    }

    // Serialize to file
    file_ops.serialize("data.bin", array->array, array->size);

    // Deserialize from file
    NFAPI_CRC_INDICATION_PDU_T *deserialized_data = NULL;
    size_t deserialized_count = 0;

    if (file_ops.deserialize(&deserialized_data, &deserialized_count, "data.bin") == 0) {
        printf("Deserialization successful: %zu entries\n", deserialized_count);
    }

    // Clean up
    crc_array_free(array);
    free(deserialized_data);

    return EXIT_SUCCESS;
}
