        memset(&frame_array[i], 0, sizeof(NFAPI_RX_FRAME_INFO));

        // Initialize RX_FRAME_HEADER
        snprintf(frame_array[i].rx_frame_header.header, sizeof(frame_array[i].rx_frame_header.header), "FrameHeader_%zu", i);

        // Initialize RX_RLC_PDU
        snprintf(frame_array[i].rx_rlc_pdu.pdu, sizeof(frame_array[i].rx_rlc_pdu.pdu), "RLCPDU_%zu", i);

