        snprintf(frame_array[i].ue_information_tag.header, sizeof(frame_array[i].ue_information_tag.header), "UE_Info_%zu", i);

        // Allocate and initialize AM_PDU array for each frame
        frame_array[i].am_pdus = (NFAPI_RLC_AM_PDU*)malloc(num_am_pdus * sizeof(NFAPI_RLC_AM_PDU));
        if (!frame_array[i].am_pdus) {
            *error_code = -3; // Memory allocation error code for AM PDUs
            log_message("Error: Failed to allocate memory for AM PDUs");

            // Free previously allocated resources before returning
            for (size_t j = 0; j < i; ++j) {
                free(frame_array[j].am_pdus);
            }
            free(frame_array);
            return NULL;
        }

        for (size_t j = 0; j < num_am_pdus; ++j) {
            snprintf(frame_array[i].am_pdus[j].am_pdu, sizeof(frame_array[i].am_pdus[j].am_pdu), "AM_PDU_%zu_%zu", i, j);
        }
    }

    *error_code = 0; // Success
    log_message("Initialization of RX frame array completed successfully");
    return frame_array;
}

