    pthread_mutex_lock(&mutex);
    if (current_size >= MAX_LIST_SIZE) {
        fprintf(stderr, "List is full\n");
        pthread_mutex_unlock(&mutex);
        return false;
    }
    list[current_size++] = pdu;
    pthread_mutex_unlock(&mutex);
    return true;
}

// Function to serialize the list into binary format
size_t serialize_list(uint8_t *buffer, size_t buffer_size) {
    pthread_mutex_lock(&mutex);
    if (current_size == 0 || buffer == NULL) {
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    size_t offset = 0;
    for (size_t i = 0; i < current_size && offset + sizeof(NFAPI_CRC_INDICATION_PDU_T) <= buffer_size; ++i) {
        memcpy(buffer + offset, &list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_unlock(&mutex);
    return offset;
}

