        pthread_mutex_unlock(&mutex);
        return 0;
    }

    size_t count = buffer_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (count > MAX_LIST_SIZE) {
        count = MAX_LIST_SIZE;
    }

    for (size_t i = 0; i < count; ++i) {
        memcpy(&list[i], buffer + (i * sizeof(NFAPI_CRC_INDICATION_PDU_T)), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    current_size = count;
    pthread_mutex_unlock(&mutex);
    return count;
}

