['Here's a C implementation of a high-performance dynamic array management system for `NFAPI_L1_API_T` structures, with considerations for concurrency, scalability, and usability:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int L1_EVENT_RX_DLSCH_DEMOD_RESULT_TAG;
} NFAPI_L1_API_T;

typedef struct Node {
    int rnti;
    int count;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RNTI_Counts;

typedef struct {
    NFAPI_L1_API_T* array;
    size_t capacity;
    size_t size;
    RNTI_Counts rnti_counts;
    pthread_rwlock_t rwlock;
    pthread_mutex_t resize_lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = malloc(initial_capacity * sizeof(NFAPI_L1_API_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;

    pthread_rwlock_init(&da->rwlock, NULL);
    pthread_mutex_init(&da->resize_lock, NULL);

    da->rnti_counts.head = NULL;
    pthread_mutex_init(&da->rnti_counts.lock, NULL);

    return da;
}

void free_dynamic_array(DynamicArray* da) {
    if (!da) return;

    Node* current = da->rnti_counts.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_destroy(&da->rwlock);
    pthread_mutex_destroy(&da->resize_lock);

    pthread_mutex_destroy(&da->rnti_counts.lock);

    free(da->array);
    free(da);
}

void resize_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->resize_lock);

    size_t new_capacity = da->capacity * 2;
    NFAPI_L1_API_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_L1_API_T));
    if (!new_array) {
        pthread_mutex_unlock(&da->resize_lock);
        return; // Handle error appropriately
    }

    da->array = new_array;
    da->capacity = new_capacity;

    pthread_mutex_unlock(&da->resize_lock);
}

void add_event(DynamicArray* da, NFAPI_L1_API_T event) {
    pthread_rwlock_wrlock(&da->rwlock);

    if (da->size >= da->capacity) {
        resize_dynamic_array(da);
    }

    da->array[da->size++] = event;

    pthread_mutex_lock(&da->rnti_counts.lock);
    Node* current = da->rnti_counts.head;
    while (current) {
        if (current->rnti == event.RNTI) {
            current->count++;
            break;
        }
        current = current->next;
    }

    if (!current) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&da->rnti_counts.lock);
            pthread_rwlock_unlock(&da->rwlock);
            return; // Handle error appropriately
        }
        new_node->rnti = event.RNTI;
        new_node->count = 1;
        new_node->next = da->rnti_counts.head;
        da->rnti_counts.head = new_node;
    }

    pthread_mutex_unlock(&da->rnti_counts.lock);
    pthread_rwlock_unlock(&da->rwlock);
}

int get_event_count(DynamicArray* da) {
    pthread_rwlock_rdlock(&da->rwlock);
    int count = da->size;
    pthread_rwlock_unlock(&da->rwlock);
    return count;
}

void query_rnti_counts(const DynamicArray* da, void (*callback)(int rnti, int count)) {
    pthread_mutex_lock((pthread_mutex_t*)&da->rnti_counts.lock);

    Node* current = da->rnti_counts.head;
    while (current) {
        callback(current->rnti, current->count);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&da->rnti_counts.lock);
}

// Example usage
void print_rnti_count(int rnti, int count) {
    printf("RNTI: %d, Count: %d\n", rnti, count);
}

int main() {
    DynamicArray* da = create_dynamic_array(10);

    NFAPI_L1_API_T event1 = {1, 1001, 2001};
    add_event(da, event1);

    NFAPI_L1_API_T event2 = {2, 1002, 2002};
    add_event(da, event2);

    NFAPI_L1_API_T event3 = {3, 1001, 2003};
    add_event(da, event3);

    printf("Total events: %d\n", get_event_count(da));

    query_rnti_counts(da, print_rnti_count);

    free_dynamic_array(da);
    return 0;
}
