typedef enum {
    MSG_TYPE_1,
    MSG_TYPE_2,
    // Add other message types as needed
} RRC_MESSAGE_TYPE;

typedef struct {
    uint16_t length;
    unsigned char data[];
} RRC_MSG_DATA;

typedef struct {
    RRC_MESSAGE_TYPE type;
    int cell_id;
    RRC_MSG_DATA* msg_data;
} NFAPI_RRC_MSG_T;

typedef struct Node {
    NFAPI_RRC_MSG_T message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    _Atomic size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray* arr) {
    arr->head = NULL;
    atomic_store(&arr->count, 0);
    pthread_mutex_init(&arr->lock, NULL);
}

// Function to create a new message
NFAPI_RRC_MSG_T* create_message(RRC_MESSAGE_TYPE type, int cell_id, const unsigned char* payload, size_t length) {
    NFAPI_RRC_MSG_T* msg = malloc(sizeof(NFAPI_RRC_MSG_T));
    if (!msg) return NULL;

    msg->type = type;
    msg->cell_id = cell_id;
    msg->msg_data = (RRC_MSG_DATA*)malloc(sizeof(RRC_MSG_DATA) + length);
    if (!msg->msg_data) {
        free(msg);
        return NULL;
    }
    msg->msg_data->length = length;
    memcpy(msg->msg_data->data, payload, length);

    return msg;
}

// Add a message to the dynamic array
void add_message(DynamicArray* arr, NFAPI_RRC_MSG_T* message) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->message = *message;
    new_node->next = NULL;

    pthread_mutex_lock(&arr->lock);
    new_node->next = arr->head;
    arr->head = new_node;
    atomic_fetch_add(&arr->count, 1);
    pthread_mutex_unlock(&arr->lock);
}

// Free a single message
void free_message(NFAPI_RRC_MSG_T* msg) {
    if (msg) {
        free(msg->msg_data);
        free(msg);
    }
}

// Free the entire dynamic array
void free_dynamic_array(DynamicArray* arr) {
    Node* current = arr->head;
    while (current) {
        Node* next = current->next;
        free_message(&current->message);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&arr->lock);
}

// Example of logging function
