#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_TAGS 10
#define HASH_TABLE_SIZE 10007

typedef struct {
    char **tags;
    size_t tag_count;
} Metadata;

typedef struct Event {
    int event_id;
    time_t timestamp;
    Metadata metadata;
    struct Event *next; // For chaining in hash table
} Event;

typedef struct {
    Event **table;
    pthread_rwlock_t locks[HASH_TABLE_SIZE];
} EventHashTable;

// Function prototypes
void initialize_event_table(EventHashTable *ht);
int hash_function(int event_id, size_t table_size);
Event* create_event(int event_id, time_t timestamp, char **tags, size_t tag_count);
void insert_event(EventHashTable *ht, Event *event);
Event* get_event(EventHashTable *ht, int event_id);
void delete_event(EventHashTable *ht, int event_id);
void free_event_table(EventHashTable *ht);

// Initialize the hash table
void initialize_event_table(EventHashTable *ht) {
    ht->table = (Event**)calloc(HASH_TABLE_SIZE, sizeof(Event*));
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_rwlock_init(&ht->locks[i], NULL);
    }
}

// Simple hash function
int hash_function(int event_id, size_t table_size) {
    return event_id % table_size;
}

// Create a new event
Event* create_event(int event_id, time_t timestamp, char **tags, size_t tag_count) {
    Event *event = (Event*)malloc(sizeof(Event));
    event->event_id = event_id;
    event->timestamp = timestamp;

    // Allocate memory for tags
    event->metadata.tags = (char**)malloc(tag_count * sizeof(char*));
    event->metadata.tag_count = tag_count;
    for (size_t i = 0; i < tag_count; ++i) {
        event->metadata.tags[i] = strdup(tags[i]);
    }
    event->next = NULL;

    return event;
}

// Insert an event into the hash table
void insert_event(EventHashTable *ht, Event *event) {
    int index = hash_function(event->event_id, HASH_TABLE_SIZE);
    pthread_rwlock_wrlock(&ht->locks[index]);

    // Add to beginning for simplicity
    event->next = ht->table[index];
    ht->table[index] = event;

    pthread_rwlock_unlock(&ht->locks[index]);
}

// Retrieve an event by ID
Event* get_event(EventHashTable *ht, int event_id) {
    int index = hash_function(event_id, HASH_TABLE_SIZE);
    pthread_rwlock_rdlock(&ht->locks[index]);

    Event *current = ht->table[index];
    while (current != NULL) {
        if (current->event_id == event_id) {
            pthread_rwlock_unlock(&ht->locks[index]);
            return current;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&ht->locks[index]);
    return NULL;
}

// Delete an event by ID
void delete_event(EventHashTable *ht, int event_id) {
    int index = hash_function(event_id, HASH_TABLE_SIZE);
    pthread_rwlock_wrlock(&ht->locks[index]);

    Event **current = &ht->table[index];
    while (*current != NULL) {
        if ((*current)->event_id == event_id) {
            Event *to_delete = *current;
            *current = to_delete->next;

            // Free metadata tags
            for (size_t i = 0; i < to_delete->metadata.tag_count; ++i) {
                free(to_delete->metadata.tags[i]);
            }
            free(to_delete->metadata.tags);
            free(to_delete);

            pthread_rwlock_unlock(&ht->locks[index]);
            return;
        }
        current = &(*current)->next;
    }

    pthread_rwlock_unlock(&ht->locks[index]);
}

// Free the entire hash table
void free_event_table(EventHashTable *ht) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Event *current = ht->table[i];
        while (current != NULL) {
            Event *to_delete = current;
            current = current->next;

            // Free metadata tags
            for (size_t j = 0; j < to_delete->metadata.tag_count; ++j) {
                free(to_delete->metadata.tags[j]);
            }
            free(to_delete->metadata.tags);
            free(to_delete);
        }

        pthread_rwlock_destroy(&ht->locks[i]);
    }
    free(ht->table);
}

// Example usage
int main() {
    EventHashTable ht;
    initialize_event_table(&ht);

    char *tags[] = {"tag1", "tag2"};
    Event *event = create_event(1, time(NULL), tags, 2);
    insert_event(&ht, event);

    Event *retrieved = get_event(&ht, 1);
    if (retrieved) {
        printf("Event ID: %d\n", retrieved->event_id);
    }

    delete_event(&ht, 1);
    free_event_table(&ht);

    return 0;
}
```

### Design Documentation and Justification

1. **Concurrency**: The use of `pthread_rwlock_t` allows for concurrent read access while ensuring exclusive write access. This is crucial for high-performance scenarios where multiple threads may need to read event data simultaneously.

2. **Hash Table**: A hash table with chaining resolves collisions efficiently, allowing for fast insertion, deletion, and retrieval operations. The choice of a prime number for the table size helps in distributing keys more uniformly.

3. **Memory Management**: Each event dynamically allocates memory for its metadata tags to handle variable-length data efficiently. Careful management ensures no memory leaks occur during deletions.

4. **Scalability**: The design supports horizontal scaling by allowing multiple instances of the library to manage different subsets of events. This can be further enhanced with distributed hash tables or sharding strategies if needed.

5. **Operational Flexibility**: While the current implementation focuses on event ID-based operations, additional functions can be added for querying based on timestamp ranges or metadata tags. These would involve iterating over entries and applying filters, potentially using more advanced data structures like interval trees for timestamps.

6. **Maintainability**: The code is modular with clear separation of concerns. Each function has a single responsibility, making it easier to understand and modify. Comments and consistent naming conventions further enhance readability.

7. **Trade-offs**: The use of chaining in the hash table may lead to longer chains under heavy load, but this is mitigated by using a sufficiently large prime number for the table size. The trade-off between memory usage and speed favors performance, which is critical under peak loads.

This library design balances efficiency, flexibility, and maintainability, making it suitable for integration into larger network infrastructure systems with high concurrency requirements.']

