#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define BUFFER_SIZE 1024

typedef struct {
    unsigned int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG CRC_INFO;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T buffer[BUFFER_SIZE];
    size_t head;
    size_t tail;
    bool is_full;
} CircularBuffer;

bool initialize_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->is_full = false;
    return true;
}

bool is_rnti_present(CircularBuffer *cb, unsigned int rnti) {
    for (size_t i = cb->tail; i != cb->head; i = (i + 1) % BUFFER_SIZE) {
        if (cb->buffer[i].RNTI == rnti) {
            return true;
        }
    }
    return false;
}

bool add_pdu(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (is_rnti_present(cb, pdu.RNTI)) {
        return false; // RNTI already present
    }

    cb->buffer[cb->head] = pdu;

    if (cb->is_full) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else if ((cb->head + 1) % BUFFER_SIZE == cb->tail) {
        cb->is_full = true;
    }

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    return true;
}

void iterate_and_print(CircularBuffer *cb, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    size_t start = cb->tail;
    size_t end = cb->head;

    for (size_t i = start; !(i == end && cb->is_full); i = (i + 1) % BUFFER_SIZE) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %u\n", cb->buffer[i].RX_UE_INFORMATION_TAG);
        fprintf(file, "RNTI: %u\n", cb->buffer[i].RNTI);
        fprintf(file, "CRCFLAG: %d\n", cb->buffer[i].CRC_INFO.CRCFLAG);
        fprintf(file, "\n");
    }

    fclose(file);
}

void simulate_random_data(CircularBuffer *cb) {
    srand(time(NULL));
    for (int i = 0; i < 2048; ++i) { // Simulating more data than buffer size
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.RNTI = rand() % 5000;
        pdu.CRC_INFO.CRCFLAG = rand() & 1; // Randomly set CRCFLAG

        add_pdu(cb, pdu);
    }
}

int main() {
    CircularBuffer cb;
    initialize_buffer(&cb);

    simulate_random_data(&cb);

    iterate_and_print(&cb, "buffer_contents.txt");

    return 0;
}
