#define MAX_EVENTS 1000000
#define THRESHOLD_ANOMALIES 10

typedef struct Metadata {
    char *tag;
    struct Metadata *next;
} Metadata;

typedef struct NetworkEvent {
    int eventID;
    time_t timestamp;
    Metadata *metadataTags;
    struct NetworkEvent *next;
} NetworkEvent;

typedef struct {
    NetworkEvent *head;
    pthread_mutex_t mutex;
    size_t count;
    size_t anomaliesDetected;
} EventList;

typedef enum { DEBUG, INFO, ERROR } LogLevel;

void log_message(LogLevel level, const char *message) {
    // Placeholder for external logging library integration
    printf("Log [%d]: %s\n", level, message);
}

EventList* init_event_list() {
    EventList *list = malloc(sizeof(EventList));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->anomaliesDetected = 0;
    return list;
}

void insert_event(EventList *list, int eventID) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_EVENTS) {
        log_message(ERROR, "Resource exhaustion: Max events reached.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    NetworkEvent *newEvent = malloc(sizeof(NetworkEvent));
    newEvent->eventID = eventID;
    newEvent->timestamp = time(NULL);
    newEvent->metadataTags = NULL;
    newEvent->next = list->head;
    list->head = newEvent;
    list->count++;

    pthread_mutex_unlock(&list->mutex);

    log_message(INFO, "Inserted event.");
}

NetworkEvent* get_event(EventList *list, int eventID) {
    pthread_mutex_lock(&list->mutex);
    NetworkEvent *current = list->head;

    while (current != NULL) {
        if (current->eventID == eventID) {
            pthread_mutex_unlock(&list->mutex);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void delete_event(EventList *list, int eventID) {
    pthread_mutex_lock(&list->mutex);

    NetworkEvent **indirect = &list->head;

    while (*indirect != NULL) {
        NetworkEvent *entry = *indirect;
        if (entry->eventID == eventID) {
            *indirect = entry->next;
            free(entry);
            list->count--;
            pthread_mutex_unlock(&list->mutex);

            log_message(INFO, "Deleted event.");
            return;
        }
        indirect = &entry->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

void check_anomalies(EventList *list) {
    // Placeholder for anomaly detection logic
    list->anomaliesDetected++;
    if (list->anomaliesDetected >= THRESHOLD_ANOMALIES) {
        notify_threshold_exceeded();
    }
}

void notify_threshold_exceeded() {
    log_message(ERROR, "Anomaly threshold exceeded. Notifying...");

    // Placeholder for external messaging service integration
    // Retry logic and failure handling should be implemented here
}

void free_event_list(EventList *list) {
    pthread_mutex_lock(&list->mutex);

    NetworkEvent *current = list->head;
    while (current != NULL) {
        NetworkEvent *next = current->next;
        Metadata *meta = current->metadataTags;

        while (meta != NULL) {
            Metadata *temp = meta;
            meta = meta->next;
            free(temp->tag);
            free(temp);
        }

        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    EventList *eventList = init_event_list();

    insert_event(eventList, 1);
    NetworkEvent *retrievedEvent = get_event(eventList, 1);

    if (retrievedEvent) {
        log_message(DEBUG, "Retrieved event successfully.");
    }

    delete_event(eventList, 1);
    check_anomalies(eventList);

    free_event_list(eventList);
    return 0;
}
