            float noise_real = sqrtf(noise_variance) * ((rand() % 1000) - 500.0f) / 500.0f; // Gaussian noise
            float noise_imag = sqrtf(noise_variance) * ((rand() % 1000) - 500.0f) / 500.0f;

            frames[i].RX_SAMPLE[j] = complex(real_part + noise_real, imag_part + noise_imag);
        }
