using System;
using System.Collections.Concurrent;
using System.Threading;

public class Message
{
    public long Timestamp { get; set; }
    public Guid Id { get; private set; }
    public int PriorityLevel { get; set; }

    public Message(long timestamp, int priorityLevel)
    {
        Timestamp = timestamp;
        Id = Guid.NewGuid();
        PriorityLevel = priorityLevel;
    }
}

public class MessageManager
{
    private readonly ConcurrentDictionary<Guid, Message> messages = new ConcurrentDictionary<Guid, Message>();
    private readonly long minTimestampRange;
    private readonly long maxTimestampRange;
    private const int MaxContentLength = 256; // Example length

    public MessageManager(long minTimestamp, long maxTimestamp)
    {
        if (minTimestamp > maxTimestamp) throw new ArgumentException("Invalid timestamp range");
        minTimestampRange = minTimestamp;
        maxTimestampRange = maxTimestamp;
    }

    public bool AddMessage(Message message)
    {
        if (!IsWithinTimeRange(message.Timestamp) || messages.ContainsKey(message.Id))
            return false;

        messages.TryAdd(message.Id, message);
        return true;
    }

    public bool UpdateMessage(Guid messageId, int newPriorityLevel)
    {
        if (messages.TryGetValue(messageId, out var message))
        {
            message.PriorityLevel = newPriorityLevel;
            return true;
        }
        return false;
    }

    public Message GetMessageById(Guid messageId)
    {
        messages.TryGetValue(messageId, out var message);
        return message;
    }

    private bool IsWithinTimeRange(long timestamp) =>
        timestamp >= minTimestampRange && timestamp <= maxTimestampRange;

    // Example of locking for more complex operations
    public void PerformThreadSafeOperation(Action<MessageManager> operation)
    {
        lock (messages)
        {
            operation(this);
        }
    }
}
