    uint8_t OFDM_SYMBOL_INDEX;
    complex float TX_SAMPLE[1024]; // Assuming 1024 points per symbol
    complex float RX_SAMPLE[1024];
} LTE_PHY_TEST_FRAME;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_noise(complex float *samples, int length, float noise_level) {
    for (int i = 0; i < length; ++i) {
        samples[i].real += ((float)rand() / RAND_MAX - 0.5f) * noise_level;
        samples[i].imag += ((float)rand() / RAND_MAX - 0.5f) * noise_level;
    }
}

void populate_frames(LTE_PHY_TEST_FRAME **frames, int num_elements, float snr_threshold) {
    if (!frames || !*frames) return;

    for (int i = 0; i < num_elements; ++i) {
        (*frames)[i].OFDM_SYMBOL_INDEX = rand() % 14; // Example range
        for (int j = 0; j < 1024; ++j) {
            // Simulate TX samples and add noise to RX samples
            complex float tx_sample = {cos(2 * M_PI * j / 1024), sin(2 * M_PI * j / 1024)};
            (*frames)[i].TX_SAMPLE[j] = tx_sample;
            float noise_level = NOISE_LEVEL_BASELINE / (snr_threshold + 1); // Dynamic adjustment
            add_noise(&(*frames)[i].RX_SAMPLE[j], 1, noise_level);
        }
    }
}

int validate_tag(uint16_t tag) {
    return tag >= VALID_TAG_MIN && tag <= VALID_TAG_MAX;
}

int validate_rnti(uint16_t rnti) {
    return rnti >= VALID_RNTI_MIN && rnti <= VALID_RNTI_MAX;
}

void create_and_populate_list(NFAPI_CRC_INDICATION_PDU_T **list, int num_elements, float crcflag_threshold, float snr_measurement) {
    if (!list || !*list) return;

    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < num_elements && i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &(*list)[i];

        entry->RX_UE_INFORMATION_TAG = rand() % (VALID_TAG_MAX - VALID_TAG_MIN + 1) + VALID_TAG_MIN;
        if (!validate_tag(entry->RX_UE_INFORMATION_TAG)) continue;

        entry->RNTI = rand() % (VALID_RNTI_MAX - VALID_RNTI_MIN + 1) + VALID_RNTI_MIN;
        if (!validate_rnti(entry->RNTI)) continue;

        entry->CRC_INDICATION_REL8_TAG = rand() % 256; // Example range
        entry->CRCFLAG = rand() & 1; // Randomly set to 0 or 1

        if (entry->CRCFLAG < crcflag_threshold) {
            --i;
            continue;
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    LTE_PHY_TEST_FRAME *frames = malloc(MAX_ELEMENTS * sizeof(LTE_PHY_TEST_FRAME));

    create_and_populate_list(&nfa_list, 5000, 1, 10.0f);
    populate_frames(&frames, 5000, 10.0f);

    // Free resources
    free(nfa_list);
    free(frames);

    return 0;
}
```

**Notes:**

- The code uses `pthread_mutex_t` for thread safety.
- Random noise is added to simulate channel conditions.
- Dynamic resizing is implicitly handled by ensuring operations do not exceed the maximum number of elements (`MAX_ELEMENTS`).
- Validation functions ensure tags and RNTI values are within valid ranges.
- A configurable filtering mechanism excludes entries based on `CRCFLAG`.
- The function is designed for integration with external systems, assuming existing APIs for handling UE information.

This code serves as a template; you'll need to adjust it according to your specific system architecture and requirements."]

