    char error_correction_algorithm[50]; // e.g., "LDPC", "Turbo"
} LTE_TRANSPORT_CHANNEL_CONFIG_T;

// Define RNTI (Radio Network Temporary Identifier)
typedef unsigned short RNTI;

// Define LTE UE CONTEXT structure
typedef struct {
    LTE_TRANSPORT_CHANNEL_CONFIG_T transport_channel_config;
    RNTI rnti;
    LTE_PHY_TEST_FRAME phy_test_frame;
} LTE_UE_CONTEXT;

// Node for the dynamic list
typedef struct Node {
    LTE_UE_CONTEXT data;
    struct Node* next;
} Node;

// Dynamic list structure
typedef struct {
    Node* head;
    size_t size;
} UE_LIST;

// Function prototypes
void initialize_ue_list(UE_LIST* list);
void add_ue_context(UE_LIST* list, const LTE_UE_CONTEXT* context);
LTE_UE_CONTEXT* get_ue_context(UE_LIST* list, RNTI rnti);
int remove_ue_context(UE_LIST* list, RNTI rnti);
void free_ue_list(UE_LIST* list);

// Function implementations
void initialize_ue_list(UE_LIST* list) {
    list->head = NULL;
    list->size = 0;
}

void add_ue_context(UE_LIST* list, const LTE_UE_CONTEXT* context) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    memcpy(&new_node->data, context, sizeof(LTE_UE_CONTEXT));
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
}

LTE_UE_CONTEXT* get_ue_context(UE_LIST* list, RNTI rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL; // Not found
}

int remove_ue_context(UE_LIST* list, RNTI rnti) {
    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.rnti == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->size--;
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }
    return -1; // Not found
}

void free_ue_list(UE_LIST* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
}

// Simulate noise for RX samples
void simulate_noise(Complex* rx_samples, size_t num_samples) {
    float noise_level = 0.1; // Adjust as needed
    for (size_t i = 0; i < num_samples; ++i) {
        float noise_real = ((float)rand() / RAND_MAX - 0.5) * 2 * noise_level;
        float noise_imag = ((float)rand() / RAND_MAX - 0.5) * 2 * noise_level;
        rx_samples[i].real += noise_real;
        rx_samples[i].imag += noise_imag;
    }
}

// Example usage
int main() {
    UE_LIST ue_list;
    initialize_ue_list(&ue_list);

    LTE_UE_CONTEXT context = { .transport_channel_config = { .modulation_scheme = 16, .coding_rate = 3/4 }, .rnti = 1 };
    add_ue_context(&ue_list, &context);

    LTE_UE_CONTEXT* found_context = get_ue_context(&ue_list, 1);
    if (found_context) {
        printf("Found UE CONTEXT with RNTI: %u\n", found_context->rnti);
    }

    simulate_noise(found_context->phy_test_frame.rx_samples, sizeof(found_context->phy_test_frame.rx_samples) / sizeof(Complex));

    remove_ue_context(&ue_list, 1);
    free_ue_list(&ue_list);

    return 0;
}
