void destroyMeasurementReportArray(MeasurementReportArray *array) {
    Node *current = array->head;
    while (current != NULL) {
        Node *next = current->next;
        if (current->report.qos_tag) {
            free(current->report.qos_tag);
        }
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&array->lock);
    free(array);
