    pthread_mutex_lock(&array->lock);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return;
    }

    new_node->report = report;
    new_node->next = array->head;
    array->head = new_node;

    pthread_mutex_unlock(&array->lock);
}

void deleteReport(MeasurementReportArray *array, int measurement_object_id) {
    pthread_mutex_lock(&array->lock);

    Node **indirect = &array->head;
    while (*indirect != NULL) {
        if ((*indirect)->report.measurement_object_id == measurement_object_id) {
            Node *node_to_delete = *indirect;
            *indirect = node_to_delete->next;

            if (node_to_delete->report.qos_tag) {
                free(node_to_delete->report.qos_tag);
            }

            free(node_to_delete);
            break;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&array->lock);
}

LTE_RRC_EUTRA_MEASUREMENT_REPORT* getReport(MeasurementReportArray *array, int measurement_object_id) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current != NULL) {
        if (current->report.measurement_object_id == measurement_object_id) {
            pthread_mutex_unlock(&array->lock);
            return &current->report;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void updateReport(MeasurementReportArray *array, int measurement_object_id, LTE_RRC_EUTRA_MEASUREMENT_REPORT new_report) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current != NULL) {
