    uint32_t RNTI;
    bool CRCFLAG; // Assume true or false
} CRC_INDICATION_REL8_TAG;

// Function to check if values are within valid ranges.
bool validate_values(uint16_t tag, uint32_t rnti) {
    return (tag > 0 && tag < 65536) && (rnti > 0);
}

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pds(uint32_t N, const char* log_file_path) {
    // Initialize logging file
    FILE *log_file = fopen(log_file_path, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    uint32_t valid_count = 0;

    for (uint32_t i = 0; i < N; ++i) {
        // Generate random values
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 65536 + 1;
        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.RNTI = rand() % 4294967295 + 1; // Random RNTI within valid range
        crc_tag.CRCFLAG = rand() % 2 == 0;

        // Validate values
        if (validate_values(pdus[i].RX_UE_INFORMATION_TAG, crc_tag.RNTI)) {
            pdus[i].CRC_INDICATION_REL8_TAG = crc_tag;
            valid_count++;

            // Log the details
            fprintf(log_file, "Index: %u, Tag: %u, RNTI: %u, CRCFLAG: %s\n", 
                    i, pdus[i].RX_UE_INFORMATION_TAG, crc_tag.RNTI,
                    crc_tag.CRCFLAG ? "true" : "false");
        }
    }

    pthread_mutex_unlock(&lock);

    fclose(log_file);

    printf("Total validly allocated structures: %u\n", valid_count);

    return pdus;
}

void free_nfa_pds(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus) {
        free(pdus);
    }
}
