#include <stdio.h>
#include <stdlib.h>
import pthread.h

typedef struct {
    int id; // Unique identifier for the measurement object
} MEASUREMENT_OBJECT;

typedef struct {
    float value; // Measurement value
} MEASUREMENT_VALUE;

typedef struct {
    int qos_priority_level; // QoS priority level, optional field
} QUALITY_OF_SERVICE_TAG;

typedef struct {
    MEASUREMENT_OBJECT mo;
    MEASUREMENT_VALUE mv;
    QUALITY_OF_SERVICE_TAG *qos_tag; // Optional quality of service tag
} LTE_RRC_EUTRA_MEASUREMENT_REPORT;

typedef struct {
    LTE_RRC_EUTRA_MEASUREMENT_REPORT* reports;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} MeasurementReportManager;

// Function prototypes
MeasurementReportManager* create_manager(size_t initial_capacity);
int insert_report(MeasurementReportManager* manager, LTE_RRC_EUTRA_MEASUREMENT_REPORT report);
int delete_report_by_id(MeasurementReportManager* manager, int mo_id);
LTE_RRC_EUTRA_MEASUREMENT_REPORT* get_report_by_id(MeasurementReportManager* manager, int mo_id);
void free_manager(MeasurementReportManager* manager);

MeasurementReportManager* create_manager(size_t initial_capacity) {
    MeasurementReportManager* manager = malloc(sizeof(*manager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->reports = malloc(initial_capacity * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
    if (!manager->reports) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

int insert_report(MeasurementReportManager* manager, LTE_RRC_EUTRA_MEASUREMENT_REPORT report) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_RRC_EUTRA_MEASUREMENT_REPORT* new_reports = realloc(manager->reports, new_capacity * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));

        if (!new_reports) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }

        manager->reports = new_reports;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->reports[i].mo.id == report.mo.id) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Duplicate ID
        }
    }

    manager->reports[manager->count++] = report;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int delete_report_by_id(MeasurementReportManager* manager, int mo_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->reports[i].mo.id == mo_id) {
            free(manager->reports[i].qos_tag); // Free optional QoS tag
            memmove(&manager->reports[i], &manager->reports[i + 1], 
                    (manager->count - i - 1) * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -3; // ID not found
}

LTE_RRC_EUTRA_MEASUREMENT_REPORT* get_report_by_id(MeasurementReportManager* manager, int mo_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->reports[i].mo.id == mo_id) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->reports[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // ID not found
}

void free_manager(MeasurementReportManager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->reports[i].qos_tag); // Free optional QoS tag
        }

        free(manager->reports);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
