['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define COMPRESSION_THRESHOLD 8000

typedef struct {
    int id; // Unique identifier for measurement object
} MEASUREMENT_OBJECT;

typedef struct {
    double value;
} MEASUREMENT_VALUE;

typedef struct {
    int qos_priority_level;
} QUALITY_OF_SERVICE_TAG;

typedef struct {
    MEASUREMENT_OBJECT measurement_object;
    MEASUREMENT_VALUE measurement_value;
    QUALITY_OF_SERVICE_TAG *quality_of_service_tag;
} LTE_RRC_EUTRA_MEASUREMENT_REPORT;

typedef struct Node {
    LTE_RRC_EUTRA_MEASUREMENT_REPORT report;
    int priority; // Used for priority queue
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PriorityQueue;

// Dynamic array structure
typedef struct {
    LTE_RRC_EUTRA_MEASUREMENT_REPORT *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MeasurementArray;

void initMeasurementArray(MeasurementArray* ma, size_t initial_capacity) {
    ma->array = (LTE_RRC_EUTRA_MEASUREMENT_REPORT*)malloc(initial_capacity * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
    if (!ma->array) exit(EXIT_FAILURE);
    ma->capacity = initial_capacity;
    ma->size = 0;
    pthread_mutex_init(&ma->lock, NULL);
}

void freeMeasurementArray(MeasurementArray* ma) {
    for (size_t i = 0; i < ma->size; ++i) {
        if (ma->array[i].quality_of_service_tag) {
            free(ma->array[i].quality_of_service_tag);
        }
    }
    free(ma->array);
    pthread_mutex_destroy(&ma->lock);
}

void resizeMeasurementArray(MeasurementArray* ma, size_t new_capacity) {
    LTE_RRC_EUTRA_MEASUREMENT_REPORT *new_array = (LTE_RRC_EUTRA_MEASUREMENT_REPORT*)realloc(ma->array, new_capacity * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
    if (!new_array) exit(EXIT_FAILURE);
    ma->array = new_array;
    ma->capacity = new_capacity;
}

void insertMeasurementReport(MeasurementArray* ma, LTE_RRC_EUTRA_MEASUREMENT_REPORT report) {
    pthread_mutex_lock(&ma->lock);
    if (ma->size == ma->capacity) {
        resizeMeasurementArray(ma, ma->capacity * 2);
    }
    ma->array[ma->size++] = report;
    pthread_mutex_unlock(&ma->lock);

    // Log insertion
    printf("Inserted report with ID: %d\n", report.measurement_object.id);
}

void deleteMeasurementReport(MeasurementArray* ma, int id) {
    pthread_mutex_lock(&ma->lock);
    for (size_t i = 0; i < ma->size; ++i) {
        if (ma->array[i].measurement_object.id == id) {
            if (ma->array[i].quality_of_service_tag) {
                free(ma->array[i].quality_of_service_tag);
            }
            memmove(&ma->array[i], &ma->array[i + 1], (ma->size - i - 1) * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
            ma->size--;
            break;
        }
    }
    pthread_mutex_unlock(&ma->lock);

    // Log deletion
    printf("Deleted report with ID: %d\n", id);
}

LTE_RRC_EUTRA_MEASUREMENT_REPORT* getMeasurementReport(MeasurementArray* ma, int id) {
    pthread_mutex_lock(&ma->lock);
    for (size_t i = 0; i < ma->size; ++i) {
        if (ma->array[i].measurement_object.id == id) {
            pthread_mutex_unlock(&ma->lock);
            return &ma->array[i];
        }
    }
    pthread_mutex_unlock(&ma->lock);
    return NULL;
}

void initPriorityQueue(PriorityQueue* pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

void insertPriorityNode(PriorityQueue* pq, LTE_RRC_EUTRA_MEASUREMENT_REPORT report, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) exit(EXIT_FAILURE);

    new_node->report = report;
    new_node->priority = priority;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);
    Node** current = &(pq->head);
    while (*current && (*current)->priority > priority) {
        current = &((*current)->next);
    }
    new_node->next = *current;
    *current = new_node;
    pthread_mutex_unlock(&pq->lock);

    // Log insertion
    printf("Inserted priority node with ID: %d and priority: %d\n", report.measurement_object.id, priority);
}

void freePriorityQueue(PriorityQueue* pq) {
    Node* current = pq->head;
    while (current) {
        Node* next = current->next;
        if (current->report.quality_of_service_tag) {
            free(current->report.quality_of_service_tag);
        }
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pq->lock);
}

void batchInsertReports(MeasurementArray* ma, LTE_RRC_EUTRA_MEASUREMENT_REPORT reports[], size_t count) {
    pthread_mutex_lock(&ma->lock);
    if (ma->size + count > ma->capacity) {
        resizeMeasurementArray(ma, (ma->capacity + count) * 2);
    }
    memcpy(&ma->array[ma->size], reports, count * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
    ma->size += count;
    pthread_mutex_unlock(&ma->lock);

    // Log batch insertion
    printf("Batch inserted %zu reports\n", count);
}

void batchDeleteReports(MeasurementArray* ma, int ids[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        deleteMeasurementReport(ma, ids[i]);
    }

    // Log batch deletion
    printf("Batch deleted %zu reports\n", count);
}

void compressDataStructure(MeasurementArray* ma) {
    if (ma->size > COMPRESSION_THRESHOLD) {
        resizeMeasurementArray(ma, ma->capacity / 2);
    }
}

// Logging and monitoring
void logPerformanceMetrics(const char* operation, int status, double latency, size_t memory_usage) {
    printf("Operation: %s, Status: %d, Latency: %.2f ms, Memory Usage: %zu bytes\n", operation, status, latency, memory_usage);
}

// Retry mechanism for network disruptions
void retryInsertion(MeasurementArray* ma, LTE_RRC_EUTRA_MEASUREMENT_REPORT report) {
    int retries = 3;
    while (retries--) {
        // Simulate network disruption handling
        if (rand() % 2 == 0) { // Randomly simulate success or failure
            insertMeasurementReport(ma, report);
            logPerformanceMetrics("Insert", 1, 0.5, ma->capacity * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
            return;
        }
        usleep(100000); // Back-off strategy: wait for 100 ms before retrying
    }
    logPerformanceMetrics("Insert", 0, 0.5, ma->capacity * sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
}

int main() {
    MeasurementArray ma;
    PriorityQueue pq;

    initMeasurementArray(&ma, 10);
    initPriorityQueue(&pq);

    // Example usage
    LTE_RRC_EUTRA_MEASUREMENT_REPORT report = {{1}, {100.0}, NULL};
    insertMeasurementReport(&ma, report);
    insertPriorityNode(&pq, report, 5);

    LTE_RRC_EUTRA_MEASUREMENT_REPORT reports[2] = {{{2}, {200.0}, NULL}, {{3}, {300.0}, NULL}};
    batchInsertReports(&ma, reports, 2);

    int ids[] = {1, 2};
    batchDeleteReports(&ma, ids, 2);

    compressDataStructure(&ma);

    retryInsertion(&ma, report);

    freePriorityQueue(&pq);
    freeMeasurementArray(&ma);

    return 0;
}
