        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    size_t allocated_size;
    size_t current_size;
} DynamicList;

// Dummy logging functions
void log_info(const char* message) { printf("INFO: %s\n", message); }
void log_warning(const char* message) { printf("WARNING: %s\n", message); }

DynamicList* create_dynamic_list(size_t max_size) {
    if (max_size > MAX_STRUCTURES) {
        log_warning("Requested size exceeds maximum allowed limit.");
        return NULL;
    }

    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        log_warning("Failed to allocate memory for list structure.");
        return NULL;
    }

    list->structures = calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->structures) {
        free(list);
        log_warning("Failed to allocate memory for structures.");
        return NULL;
    }

    list->allocated_size = max_size;
    list->current_size = 0;

    log_info("Dynamic list created successfully.");
    return list;
}

int add_structure(DynamicList *list) {
    if (list->current_size >= list->allocated_size) {
        log_warning("Reached maximum size limit. Cannot add more structures.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *structure = &list->structures[list->current_size];
    structure->RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
    structure->RNTI = rand() % 1000; // Example RNTI

    srand(time(NULL) + list->current_size); // Seed with current time and index
    structure->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    list->current_size++;
    log_info("Structure added successfully.");
    return 0;
}

size_t serialize_list(const DynamicList *list, unsigned char **output) {
    if (!list || !output) return 0;

    size_t total_size = list->current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *output = malloc(total_size);
    if (!*output) {
        log_warning("Failed to allocate memory for serialization.");
        return 0;
    }

    memcpy(*output, list->structures, total_size);
    log_info("Serialization completed successfully.");
    return total_size;
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        if (list->structures) {
            free(list->structures);
        }
        free(list);
        log_info("Dynamic list freed successfully.");
    }
}
