complex float* generate_rx_sample(complex float* txSample, size_t length, double noiseLevel) {
    complex float* rxSample = (complex float*)malloc(length * sizeof(complex float));
    for (size_t i = 0; i < length; ++i) {
        // Simulate multipath fading
        double fadeFactor = 1.0 + ((double)rand() / RAND_MAX - 0.5);

        // Simulate shadowing
        double shadowingFactor = 1.0 + ((double)rand() / RAND_MAX - 0.5);

        // Simulate interference and noise
        complex float noise = (complex float){((double)rand() / RAND_MAX - 0.5) * noiseLevel,
                                              ((double)rand() / RAND_MAX - 0.5) * noiseLevel};

        rxSample[i] = txSample[i] * fadeFactor * shadowingFactor + noise;
    }
    return rxSample;
}

