    pseudo_random_seed ^= (pseudo_random_seed >> 35);
    pseudo_random_seed ^= (pseudo_random_seed << 4);
    return (uint16_t)(pseudo_random_seed & 0xFFFF);
}

int init_dynamic_list(DynamicList* list, size_t initial_capacity) {
