    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) return -1;
    list->size = 0;
    list->capacity = initial_capacity;
    list->allocations = 1; // Initial allocation
    list->reallocations = 0;
    return 0;
}

void free_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_structure(DynamicList* list, uint64_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    if (list->size >= MAX_STRUCTURES) return -1; // Max structures reached

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate tag
        }
    }

