        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Reallocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
        list->reallocations++;
    }

    NFAPI_CRC_INDICATION_PDU_T* struct_ptr = &list->data[list->size++];
    struct_ptr->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    struct_ptr->RNTI = RNTI;
    struct_ptr->CRCFLAG = generate_crcflag();

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void log_statistics(const DynamicList* list) {
    printf("Allocations: %u, Reallocations: %u\n", list->allocations, list->reallocations);
}
