// Memory pool manager mockup
void* memory_pool_allocate(size_t size) {
    return malloc(size);
}

void memory_pool_free(void* ptr) {
    free(ptr);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCList;

// Callback functions
void (*on_max_capacity_reached)(size_t new_capacity) = NULL;
void (*on_reallocation_occurred)(size_t old_capacity, size_t new_capacity) = NULL;

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList* list = (CRCList*)memory_pool_allocate(sizeof(CRCList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_allocate(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        memory_pool_free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(CRCList* list) {
    if (list) {
        memory_pool_free(list->data);
        pthread_mutex_destroy(&list->lock);
        memory_pool_free(list);
    }
}

uint8_t pseudo_random_byte(uint32_t seed) {
    // Simple LCG for demonstration
    return (uint8_t)((seed * 1103515245 + 12345) & 0xFF);
}

int add_crc_indication(CRCList* list, uint32_t tag, uint16_t rnti, uint32_t seed) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (on_max_capacity_reached) on_max_capacity_reached(new_capacity);

        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_allocate(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }

        memcpy(new_data, list->data, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (on_reallocation_occurred) on_reallocation_occurred(list->capacity, new_capacity);

        memory_pool_free(list->data);
        list->data = new_data;
        list->capacity = new_capacity;
    }

    uint8_t crc_flag = pseudo_random_byte(seed++);
    list->data[list->count].RX_UE_INFORMATION_TAG = tag;
    list->data[list->count].RNTI = rnti;
    list->data[list->count].CRCFLAG = crc_flag;

    printf("Tag: %u, RNTI: %u, CRCFLAG: %d\n", tag, rnti, crc_flag);

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_crc_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(list->count), 1, file);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);

    fclose(file);
}

int deserialize_crc_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(count), 1, file);

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_allocate(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fclose(file);
        return -1;
    }

    fread(new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    memory_pool_free(list->data);
    list->data = new_data;
    list->count = count;

    fclose(file);
    return 0;
}

// Example usage
int main() {
    CRCList* crc_list = create_crc_list(10);
    if (!crc_list) {
        fprintf(stderr, "Failed to create CRC list.\n");
        return EXIT_FAILURE;
    }

    for (uint32_t i = 0; i < 20; ++i) {
        add_crc_indication(crc_list, i, i * 2, i);
    }

    serialize_crc_list(crc_list, "crc_data.bin");

    destroy_crc_list(crc_list);

    return EXIT_SUCCESS;
}
