    int someInfo;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG* crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Plugin architecture for CRC_INDICATION_REL8_TAG
typedef struct {
    const char* name;
    CRC_INDICATION_REL8_TAG *(*create)();
    void (*destroy)(CRC_INDICATION_REL8_TAG*);
} crc_indication_plugin_t;

#define MAX_ELEMENTS 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t count;
    pthread_mutex_t mutex;
    crc_indication_plugin_t *plugins;
    size_t plugin_count;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(crc_indication_plugin_t *plugins, size_t plugin_count);
void destroy_dynamic_array(DynamicArray* array);
bool add_element(DynamicArray* array, RX_UE_INFORMATION_TAG rx_ue_info_tag, unsigned long rnti, crc_indication_plugin_t* plugin);
void remove_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T *element);

// Plugin example
CRC_INDICATION_REL8_TAG* create_default_crc_indicator() {
    CRC_INDICATION_REL8_TAG* tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!tag) return NULL;
    tag->crcFlag = rand(); // Randomly set for demonstration purposes
    return tag;
}

void destroy_default_crc_indicator(CRC_INDICATION_REL8_TAG* tag) {
    free(tag);
}

// Main functions
DynamicArray* create_dynamic_array(crc_indication_plugin_t *plugins, size_t plugin_count) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = array->tail = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->plugins = plugins;
    array->plugin_count = plugin_count;

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (!array) return;

    NFAPI_CRC_INDICATION_PDU_T *current = array->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current->crc_indication_rel8_tag);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&array->mutex);
    free(array);
}

bool add_element(DynamicArray* array, RX_UE_INFORMATION_TAG rx_ue_info_tag, unsigned long rnti, crc_indication_plugin_t* plugin) {
    if (!array || !plugin || array->count >= MAX_ELEMENTS) return false;

    pthread_mutex_lock(&array->mutex);

    NFAPI_CRC_INDICATION_PDU_T *new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        pthread_mutex_unlock(&array->mutex);
        return false;
    }

    new_element->rx_ue_information_tag = rx_ue_info_tag;
    new_element->rnti = rnti;
    new_element->crc_indication_rel8_tag = plugin->create();
    if (!new_element->crc_indication_rel8_tag) {
        free(new_element);
        pthread_mutex_unlock(&array->mutex);
        return false;
    }

    new_element->next = NULL;

    if (array->tail) {
        array->tail->next = new_element;
    } else {
        array->head = new_element;
    }

    array->tail = new_element;
    array->count++;

    pthread_mutex_unlock(&array->mutex);
    return true;
}

void remove_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (!array || !element) return;

    pthread_mutex_lock(&array->mutex);

    if (array->head == element) {
        array->head = element->next;
    }

    if (array->tail == element) {
        array->tail = NULL; // Handle as needed, possibly track previous element
    }

    free(element->crc_indication_rel8_tag);
    free(element);

    array->count--;

    pthread_mutex_unlock(&array->mutex);
}

// Example usage and plugin setup
int main() {
    crc_indication_plugin_t plugins[] = {
        {"default", create_default_crc_indicator, destroy_default_crc_indicator}
    };

    DynamicArray* dynamic_array = create_dynamic_array(plugins, sizeof(plugins) / sizeof(crc_indication_plugin_t));

    RX_UE_INFORMATION_TAG rx_ue_info_tag = {.someInfo = 1};
    unsigned long rnti = 12345;

    add_element(dynamic_array, rx_ue_info_tag, rnti, &plugins[0]);

    // Additional operations...

    destroy_dynamic_array(dynamic_array);

    return 0;
}
