typedef struct {
    unsigned long rx_bytes;
    unsigned long tx_bytes;
} TrafficStats;

typedef struct {
    int ue_id;
    time_t last_update_time;
    TrafficStats traffic_stats;
} UEStatsRecord;

int get_current_time(time_t *current_time) {
    // Fallback mechanism to handle unreliable system time
    if (!(*current_time = time(NULL))) {
        fprintf(stderr, "Failed to retrieve current time. Using a fixed timestamp.\n");
        *current_time = 1625097600; // A fallback static timestamp
    }
    return (*current_time >= 0); // Check for valid timestamp
}

int fetch_ue_ids(int *ue_ids, int num_ues) {
    // Example logic to fill ue_ids from a predefined list with no duplicates
    const int total_possible_ids = 10000;
    if (num_ues > total_possible_ids) {
        fprintf(stderr, "Requested UEs exceed the available unique IDs.\n");
        return 0; // Failure due to insufficient unique IDs
    }

    for (int i = 0; i < num_ues; ++i) {
        ue_ids[i] = rand() % total_possible_ids + 1;

        // Ensure uniqueness by checking and regenerating if necessary
        for (int j = 0; j < i; ++j) {
            while (ue_ids[i] == ue_ids[j]) {
                ue_ids[i] = rand() % total_possible_ids + 1;
            }
        }
    }

    return 1; // Success
}

UEStatsRecord* initialize_ue_stats(int num_ues, int *ue_ids) {
    if (num_ues <= 0 || !ue_ids) {
        fprintf(stderr, "Invalid number of UEs or UE IDs provided.\n");
        return NULL;
    }

    UEStatsRecord *records = malloc(num_ues * sizeof(UEStatsRecord));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for UE stats records.\n");
        return NULL;
    }

    time_t current_time;
    if (!get_current_time(&current_time)) {
        free(records);
        return NULL; // Early exit on failure to get valid system time
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator

    for (int i = 0; i < num_ues; ++i) {
        records[i].ue_id = ue_ids[i];

        // Simulate random traffic stats generation
        records[i].traffic_stats.rx_bytes = rand() % 1000000;
        records[i].traffic_stats.tx_bytes = rand() % 1000000;

        // Assign the same current time to all records initially
        records[i].last_update_time = current_time;
    }

    return records;
}

// Example usage of above function
int main() {
    int num_ues = 10;  // Number of UEs for demonstration purposes
    int *ue_ids = malloc(num_ues * sizeof(int));

    if (!fetch_ue_ids(ue_ids, num_ues)) {
        free(ue_ids);
        return EXIT_FAILURE;
    }

    UEStatsRecord *records = initialize_ue_stats(num_ues, ue_ids);

    // Cleanup
    if (records) {
        free(records);
    }
    free(ue_ids);

    return EXIT_SUCCESS;
}
