#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <limits.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>

// Helper function to check if a path is symbolic link
int is_symlink(const char *path) {
    struct stat path_stat;
    return lstat(path, &path_stat) == 0 && S_ISLNK(path_stat.st_mode);
}

// Function to get relative directory path up to the specified level
char* process_file_paths(char **file_paths, int num_files, int *max_levels, char ***relative_paths) {
    if (num_files <= 0 || file_paths == NULL || max_levels == NULL || relative_paths == NULL)
        return NULL;

    // Allocate memory for storing results
    *relative_paths = malloc(num_files * sizeof(char*));
    if (*relative_paths == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (int i = 0; i < num_files; ++i) {
        const char *path = file_paths[i];
        int max_level = max_levels[i];

        // Check if the path is a symbolic link
        if (is_symlink(path)) {
            (*relative_paths)[i] = NULL;
            continue;
        }

        char *current_path = strdup(path);
        if (!current_path) {
            perror("Failed to duplicate string");
            for (int j = 0; j < i; ++j)
                free((*relative_paths)[j]);
            free(*relative_paths);
            return NULL;
        }

        int level = 0;
        char *token, *path_copy, *last_delim;
        path_copy = strdup(path);
        if (!path_copy) {
            perror("Failed to duplicate string");
            free(current_path);
            for (int j = 0; j < i; ++j)
                free((*relative_paths)[j]);
            free(*relative_paths);
            return NULL;
        }

        token = strtok_r(path_copy, "/", &last_delim);
        while (token != NULL && level <= max_level) {
            char *next_token = strtok_r(NULL, "/", &last_delim);
            if (!next_token) break; // End of path

            char new_path[PATH_MAX];
            snprintf(new_path, sizeof(new_path), "%s/%s", current_path, token);

            struct stat path_stat;
            if (stat(new_path, &path_stat) != 0 || !S_ISDIR(path_stat.st_mode)) {
                free(current_path);
                free(path_copy);
                (*relative_paths)[i] = NULL;
                break;
            }

            free(current_path);
            current_path = strdup(new_path);
            if (!current_path) {
                perror("Failed to duplicate string");
                free(path_copy);
                for (int j = 0; j < i; ++j)
                    free((*relative_paths)[j]);
                free(*relative_paths);
                return NULL;
            }

            level++;
            token = next_token;
        }

        // Store result
        if (level <= max_level) {
            (*relative_paths)[i] = current_path;
        } else {
            (*relative_paths)[i] = NULL;
            free(current_path);
        }
        free(path_copy);
    }

    return *relative_paths;
}

// Example usage: Define main to test the function
int main() {
    char *paths[] = {"/home/user/docs/project/file.txt", "/another/path/to/file"};
    int levels[] = {2, 3};
    char **result;

    result = process_file_paths(paths, 2, levels, &result);

    for (int i = 0; i < 2; ++i) {
        if (result[i]) {
            printf("Relative path: %s\n", result[i]);
            free(result[i]); // Free each allocated string
        } else {
            printf("Path processing failed or exceeded max level.\n");
        }
    }

    free(result); // Free the array of pointers
    return 0;
}
```

**Explanation**: 

This C function, `process_file_paths`, processes a list of file paths and returns their relative directory paths up to specified levels. It handles symbolic links by skipping them to prevent potential infinite loops. Memory is managed carefully with dynamic allocations for each path result, and the function checks input validity upfront. The example usage in `main` demonstrates how to call this function and handle its results appropriately.']

