// nfa_crc.h
#ifndef NFA_CRC_H
#define NFA_CRC_H

#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG *crc_tag;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *prev, *next;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Function prototypes
DoublyLinkedList* create_list();
void destroy_list(DoublyLinkedList *list);
int add_pdu(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T remove_pdu(DoublyLinkedList *list);

// Plugin architecture
typedef void (*CRCPluginInitFunc)();
typedef int (*CRCPluginProcessFunc)(DoublyLinkedList *list);

typedef struct {
    CRCPluginInitFunc init;
    CRCPluginProcessFunc process;
} CRCPlugin;

void register_crc_plugin(CRCPlugin plugin);
int execute_plugins(DoublyLinkedList *list);

// Sliding window
typedef struct {
    DoublyLinkedList *data_points;
    size_t max_size;
    pthread_mutex_t lock;
} SlidingWindow;

SlidingWindow* create_window(size_t max_size);
void destroy_window(SlidingWindow *window);
int add_data_point(SlidingWindow *window, NFAPI_CRC_INDICATION_PDU_T pdu);

#endif // NFA_CRC_H

// nfa_crc.c
#include "nfa_crc.h"
#include <string.h>
#include <time.h>

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DoublyLinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->data.crc_tag);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node *new_node = malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T remove_pdu(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T pdu = {NULL, 0};
    if (list->head != NULL) {
        Node *node_to_remove = list->head;
        pdu = node_to_remove->data;

        list->head = node_to_remove->next;
        if (list->head == NULL) {
            list->tail = NULL;
        } else {
            list->head->prev = NULL;
        }
        free(node_to_remove->data.crc_tag);
        free(node_to_remove);

        pthread_mutex_unlock(&list->lock);
        return pdu;
    }

    pthread_mutex_unlock(&list->lock);
    return pdu; // Empty PDU
}

void register_crc_plugin(CRCPlugin plugin) {
    static CRCPlugin *plugins = NULL;
    static int count = 0;

    if (!plugins) {
        plugins = malloc(sizeof(CRCPlugin));
    } else {
        plugins = realloc(plugins, (count + 1) * sizeof(CRCPlugin));
    }

    plugins[count++] = plugin;
}

int execute_plugins(DoublyLinkedList *list) {
    for (int i = 0; i < count; ++i) {
        if (plugins[i].init) {
            plugins[i].init();
        }
        if (plugins[i].process) {
            plugins[i].process(list);
        }
    }
    return 0;
}

SlidingWindow* create_window(size_t max_size) {
    SlidingWindow *window = malloc(sizeof(SlidingWindow));
    window->data_points = create_list();
    window->max_size = max_size;
    pthread_mutex_init(&window->lock, NULL);
    return window;
}

void destroy_window(SlidingWindow *window) {
    destroy_list(window->data_points);
    pthread_mutex_destroy(&window->lock);
    free(window);
}

int add_data_point(SlidingWindow *window, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&window->lock);

    int size = 0;
    Node *current = window->data_points->head;
    while (current != NULL) {
        ++size;
        current = current->next;
    }

    if (size >= window->max_size) {
        remove_pdu(window->data_points);
    }

    add_pdu(window->data_points, pdu);

    pthread_mutex_unlock(&window->lock);
    return 0;
}

// Example plugin
typedef struct {
    CRCPlugin base;
} MyCRCPlugin;

void my_plugin_init() {
    // Initialization code
}

int my_plugin_process(DoublyLinkedList *list) {
    // Processing code
    return 0;
}

CRCPlugin create_my_crc_plugin() {
    MyCRCPlugin plugin;
    plugin.base.init = my_plugin_init;
    plugin.base.process = my_plugin_process;
    return plugin.base;
}
