#define LIST_SIZE 1000
#define RETRY_LIMIT 3
#define TIMEOUT_MS 500

// Mutex for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int size) {
    NFAPI_CRC_INDICATION_PDU_T* nfa_list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));  // Seed for random number generation
    for (int i = 0; i < size; ++i) {
        nfa_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;  // Example value
        nfa_list[i].RNTI = rand() % 10000;  // Example value
        nfa_list[i].crc_tag.CRC_INDICATION_REL8_TAG = rand() % 100;  // Example value
        nfa_list[i].crc_tag.CRCFLAG = rand() % 2;  // Randomly set to 0 or 1
    }

    return nfa_list;
}

int populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    pthread_mutex_lock(&list_mutex);

    int retry_count = 0;
    while (retry_count < RETRY_LIMIT) {
        *list = create_nfa_list(size);
        if (*list != NULL) {
            pthread_mutex_unlock(&list_mutex);
            return 0; // Success
        }

        retry_count++;
        printf("Retrying memory allocation (%d/%d)\n", retry_count, RETRY_LIMIT);

        // Simulate a timeout with sleep
        struct timespec ts;
        ts.tv_sec = TIMEOUT_MS / 1000;
        ts.tv_nsec = (TIMEOUT_MS % 1000) * 1000000L;

        nanosleep(&ts, NULL);
    }

    pthread_mutex_unlock(&list_mutex);
    return -1; // Failure
}

void serialize_nfa_list(const NFAPI_CRC_INDICATION_PDU_T* list, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("File open failed");
        return;
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    fclose(file);
}

void deserialize_nfa_list(NFAPI_CRC_INDICATION_PDU_T** list, int size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("File open failed");
        return;
    }

    *list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        perror("Memory allocation for deserialization failed");
        fclose(file);
        return;
    }

    fread(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    fclose(file);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* nfa_list = NULL;

    if (populate_nfa_list(&nfa_list, LIST_SIZE) != 0) {
        fprintf(stderr, "Failed to populate NFA list\n");
        return EXIT_FAILURE;
    }

    serialize_nfa_list(nfa_list, LIST_SIZE, "nfa_data.bin");

    NFAPI_CRC_INDICATION_PDU_T* deserialized_list = NULL;
    deserialize_nfa_list(&deserialized_list, LIST_SIZE, "nfa_data.bin");

    // Cleanup
    free(nfa_list);
    free(deserialized_list);

    return EXIT_SUCCESS;
}
