#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint64_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t lock;
} PDULIST;

uint32_t generate_unique_tag(uint32_t *last_tag) {
    return (*last_tag)++;
}

uint64_t pseudo_random_crcflag(uint64_t seed, uint32_t index) {
    // Simple LCG (Linear Congruential Generator)
    const uint64_t a = 6364136223846793005;
    const uint64_t c = 1;
    return (a * (seed + index) + c);
}

PDULIST* create_pdu_list() {
    PDULIST *list = malloc(sizeof(PDULIST));
    if (!list) {
        perror("Failed to allocate memory for PDU list");
        return NULL;
    }

    list->pdus = calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        perror("Failed to allocate memory for PDUs");
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_pdu_list(PDULIST *list) {
    if (list) {
        free(list->pdus);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_pdu_to_list(PDULIST *list, uint16_t rnti, uint64_t seed, int *alloc_count, int *realloc_count) {
    if (!list || list->count >= MAX_STRUCTURES) {
        return -1; // List is full or invalid
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(list->pdus, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    list->pdus = new_pdus;
    (*realloc_count)++;

    uint32_t last_tag = 0;

    // Ensure uniqueness of RX_UE_INFORMATION_TAG across the entire list
    for (size_t i = 0; i < list->count; ++i) {
        while (1) {
            uint32_t new_tag = generate_unique_tag(&last_tag);
            int unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (list->pdus[j].RX_UE_INFORMATION_TAG == new_tag) {
                    unique = 0;
                    break;
                }
            }
            if (unique) {
                list->pdus[i].RX_UE_INFORMATION_TAG = new_tag;
                break;
            }
        }
    }

    // Add the new PDU
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdus[list->count];
    new_pdu->RX_UE_INFORMATION_TAG = generate_unique_tag(&last_tag);
    new_pdu->RNTI = rnti;
    new_pdu->CRCFLAG = pseudo_random_crcflag(seed, list->count);

    (*alloc_count)++;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void log_allocations(int allocs, int reallocs) {
    printf("Allocations: %d\n", allocs);
    printf("Reallocations: %d\n", reallocs);
}
