typedef struct ModulationScheme {
    char *scheme;
} ModulationScheme;

typedef struct CRCFlag {
    int flag;
} CRCFlag;

typedef struct PHYMessage {
    unsigned int frame_number;
    ModulationScheme *modulation_scheme;
    CRCFlag *crc_flag;
    struct PHYMessage *prev, *next;
} PHYMessage;

typedef struct DynamicArray {
    PHYMessage *head, *tail;
    size_t count;
    pthread_mutex_t mutex;
    size_t max_size;
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *array, size_t max_size) {
    array->head = NULL;
    array->tail = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->max_size = max_size;
}

// Add a new PHY message
int add_phy_message(DynamicArray *array, unsigned int frame_number) {
    pthread_mutex_lock(&array->mutex);

    if (array->count >= array->max_size) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }

    PHYMessage *new_msg = malloc(sizeof(PHYMessage));
    new_msg->frame_number = frame_number;
    new_msg->modulation_scheme = malloc(sizeof(ModulationScheme));
    new_msg->crc_flag = malloc(sizeof(CRCFlag));

    if (!new_msg || !new_msg->modulation_scheme || !new_msg->crc_flag) {
        free(new_msg);
        pthread_mutex_unlock(&array->mutex);
        return -2; // Memory allocation failed
    }

    strcpy(new_msg->modulation_scheme->scheme, "Default");
    new_msg->crc_flag->flag = 0;

    if (array->tail) {
        array->tail->next = new_msg;
        new_msg->prev = array->tail;
        array->tail = new_msg;
    } else {
        array->head = new_msg;
        array->tail = new_msg;
        new_msg->prev = NULL;
    }
    new_msg->next = NULL;

    array->count++;
    pthread_mutex_unlock(&array->mutex);
    return 0; // Success
}

// Iterate over the messages
void iterate_phy_messages(DynamicArray *array, void (*callback)(PHYMessage *)) {
    pthread_mutex_lock(&array->mutex);

    PHYMessage *current = array->head;
    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&array->mutex);
}

// Free the dynamic array
void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);

    PHYMessage *current = array->head;
    while (current) {
        PHYMessage *temp = current;
        current = current->next;

        free(temp->modulation_scheme);
        free(temp->crc_flag);
        free(temp);
    }

    array->head = NULL;
    array->tail = NULL;
    array->count = 0;

    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

// Plugin architecture placeholder
void register_modulation_scheme(void *scheme) {
    // Implementation for registering new modulation schemes
}

void register_crc_algorithm(void *algorithm) {
    // Implementation for registering new CRC algorithms
}

// Example usage of the library
int main() {
    DynamicArray array;
    init_dynamic_array(&array, 100);

    add_phy_message(&array, 1);
    iterate_phy_messages(&array, [](PHYMessage *msg) {
        printf("Frame Number: %u\n", msg->frame_number);
    });

    free_dynamic_array(&array);
    return 0;
}
