// Memory pool for efficient memory management
#define POOL_SIZE 100000

NFAPI_CRC_INDICATION_PDU_T* pool[POOL_SIZE];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pool() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool[i] = NULL;
    }
    pthread_mutex_unlock(&pool_lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool() {
    NFAPI_CRC_INDICATION_PDU_T* node = NULL;

    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool[i] == NULL) {
            node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pool[i] = node;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);

    return node;
}

void free_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool[i] != NULL) {
            free(pool[i]);
            pool[i] = NULL;
        }
    }
}

// Linked list to store the CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} CRC_Indications_List;

CRC_Indications_List* initialize_list() {
    CRC_Indications_List* list = (CRC_Indications_List*)malloc(sizeof(CRC_Indications_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void free_list(CRC_Indications_List *list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        // Memory is managed by the pool
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void populate_crc_indications(CRC_Indications_List *list, int num_elements) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_node = allocate_from_pool();
    NFAPI_CRC_INDICATION_PDU_T* last_node = list->head;

    for (int i = 0; i < num_elements; ++i) {
        if (!new_node) break; // Pool exhausted

        new_node->ue_info_tag.RX_UE_INFORMATION_TAG = rand(); // Assign random values
        new_node->rnti.RNTI = rand();
        new_node->crc_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        if (last_node == NULL) {
            list->head = new_node;
        } else {
            last_node->next = new_node;
        }
        last_node = new_node;

        // Allocate next node from the pool
        new_node = allocate_from_pool();
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    initialize_memory_pool();

    CRC_Indications_List *crc_list = initialize_list();
    if (!crc_list) return 1;

    populate_crc_indications(crc_list, 100000);

    free_list(crc_list);
    free_memory_pool();

    return 0;
}
