#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Error logging
void log_error(const char *message) {
    FILE *log_file = fopen("error.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Logging processed elements
void log_processed(int count) {
    FILE *log_file = fopen("processed.log", "w");
    if (log_file != NULL) {
        fprintf(log_file, "Total elements processed: %d\n", count);
        fclose(log_file);
    }
}

// Comparator function for qsort
int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pdu_b = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pdu_a->RNTI - pdu_b->RNTI;
}

// Function to write sorted data to file
void write_to_file(NFAPI_CRC_INDICATION_PDU_T *array, size_t n) {
    FILE *file = fopen("crc_indications.txt", "w");
    if (file != NULL) {
        for (size_t i = 0; i < n; ++i) {
            fprintf(file, "%d,%d,%d\n",
                    array[i].RX_UE_INFORMATION_TAG,
                    array[i].RNTI,
                    array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
        fclose(file);
    } else {
        log_error("Failed to open file for writing.");
    }
}

// Dynamic memory allocation and processing
NFAPI_CRC_INDICATION_PDU_T *process_cyclic_indications(size_t N, int *error_code) {
    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        log_error("Mutex init failed.");
        *error_code = 1;
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed.");
        *error_code = 2;
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example random value
        array[i].RNTI = rand() % 10000; // Example random value
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    qsort(array, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);
    write_to_file(array, N);

    log_processed(N);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return array;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
