#define MAX_BATCH_SIZE 100

// Mutex for thread-safe memory allocation logging
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_cri_pdu_list(size_t n, size_t max_batch_size) {
    if (n <= 0 || max_batch_size == 0) return NULL;

    size_t batch_size = n < max_batch_size ? n : max_batch_size;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        log_memory_failure("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T list");
        return NULL;
    }

    for (size_t i = 0; i < batch_size; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = generate_random_rx_ue_information_tag();
        pdu_list[i].RNTI = generate_random_rnti();

        CRC_INDICATION_REL8_TAG* crc_indication_rel8_tag = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!crc_indication_rel8_tag) {
            log_memory_failure("Failed to allocate memory for CRC_INDICATION_REL8_TAG");
            free_nfa_cri_pdu_list(pdu_list, i);
            return NULL;
        }

        crc_indication_rel8_tag->CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        pdu_list[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
    }

    if (n > max_batch_size) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdu_list = allocate_nfa_cri_pdu_list(n - max_batch_size, max_batch_size);
        if (!new_pdu_list) {
            free_nfa_cri_pdu_list(pdu_list, batch_size);
            return NULL;
        }

        size_t total_elements = batch_size + (size_t)(n > max_batch_size ? new_pdu_list : 0);
        NFAPI_CRC_INDICATION_PDU_T* final_pdu_list = realloc(pdu_list, total_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!final_pdu_list) {
            log_memory_failure("Failed to reallocate memory for combined NFAPI_CRC_INDICATION_PDU_T list");
            free_nfa_cri_pdu_list(pdu_list, batch_size);
            free_nfa_cri_pdu_list(new_pdu_list, n - max_batch_size);
            return NULL;
        }

        memcpy(final_pdu_list + batch_size, new_pdu_list, (n - max_batch_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free_nfa_cri_pdu_list(new_pdu_list, n - max_batch_size);

        pdu_list = final_pdu_list;
    }

    return pdu_list;
}

void free_nfa_cri_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t count) {
    if (!pdu_list) return;

    for (size_t i = 0; i < count; ++i) {
        free(pdu_list[i].crc_indication_rel8_tag);
    }
    free(pdu_list);
