#define INITIAL_SIZE 10

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    int protocolType;
} Header;

typedef struct {
    Header header;
    char *payloadData;
    size_t payloadSize;
    time_t timestamp;
} Packet;

typedef struct {
    Packet **packets;
    size_t size;
    size_t capacity;
} PacketArray;

void initializePacketArray(PacketArray *array) {
    array->capacity = INITIAL_SIZE;
    array->size = 0;
    array->packets = (Packet **)malloc(array->capacity * sizeof(Packet *));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void resizePacketArray(PacketArray *array) {
    size_t newCapacity = array->capacity * 2;
    Packet **newPackets = (Packet **)realloc(array->packets, newCapacity * sizeof(Packet *));
    if (!newPackets) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->packets = newPackets;
    array->capacity = newCapacity;
}

void addOrUpdatePacket(PacketArray *array, const char *sourceIP, const char *destinationIP, int protocolType, const char *payloadData, size_t payloadSize) {
    time_t currentTime = time(NULL);

    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->packets[i]->header.sourceIP, sourceIP) == 0 &&
            strcmp(array->packets[i]->header.destinationIP, destinationIP) == 0 &&
            array->packets[i]->header.protocolType == protocolType) {

            free(array->packets[i]->payloadData);
            array->packets[i]->payloadSize = payloadSize;
            array->packets[i]->payloadData = (char *)malloc(payloadSize);
            if (!array->packets[i]->payloadData) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            memcpy(array->packets[i]->payloadData, payloadData, payloadSize);
            array->packets[i]->timestamp = currentTime;
            return;
        }
    }

    if (array->size == array->capacity) {
        resizePacketArray(array);
    }

    Packet *newPacket = (Packet *)malloc(sizeof(Packet));
    if (!newPacket) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    strncpy(newPacket->header.sourceIP, sourceIP, sizeof(newPacket->header.sourceIP) - 1);
    newPacket->header.sourceIP[sizeof(newPacket->header.sourceIP) - 1] = '\0';
    strncpy(newPacket->header.destinationIP, destinationIP, sizeof(newPacket->header.destinationIP) - 1);
    newPacket->header.destinationIP[sizeof(newPacket->header.destinationIP) - 1] = '\0';
    newPacket->header.protocolType = protocolType;

    newPacket->payloadSize = payloadSize;
    newPacket->payloadData = (char *)malloc(payloadSize);
    if (!newPacket->payloadData) {
        free(newPacket);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(newPacket->payloadData, payloadData, payloadSize);
    newPacket->timestamp = currentTime;

    array->packets[array->size++] = newPacket;
}

Packet *retrievePacketByTimestamp(PacketArray *array, time_t timestamp) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i]->timestamp == timestamp) {
            return array->packets[i];
        }
    }
    return NULL;
}

void freePacketArray(PacketArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->packets[i]->payloadData);
        free(array->packets[i]);
    }
    free(array->packets);
    array->packets = NULL;
    array->size = 0;
    array->capacity = 0;
}

// Example usage
int main() {
    PacketArray packetArray;
    initializePacketArray(&packetArray);

    addOrUpdatePacket(&packetArray, "192.168.1.1", "192.168.1.2", 6, "Hello, World!", strlen("Hello, World!"));

    time_t timestamp = time(NULL);
    Packet *retrievedPacket = retrievePacketByTimestamp(&packetArray, timestamp);
    if (retrievedPacket) {
        printf("Retrieved packet with payload: %s\n", retrievedPacket->payloadData);
    }

    freePacketArray(&packetArray);
    return 0;
}
```

