    fwrite(&list->size, sizeof(size_t), 1, file);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

int deserialize_list(const char *filename, NFAPICRCList *list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

