```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define CRCFLAG_RANGE {0, 1} // Example range

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void log_overflow() {
    fprintf(stderr, "Overflow: Maximum number of entries exceeded.\n");
}

int validate_tags(NFAPI_CRC_INDICATION_PDU_T pdu) {
    return (pdu.RX_UE_INFORMATION_TAG >= 0 && 
            pdu.RNTI >= 0 &&
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG >= CRCFLAG_RANGE[0] &&
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG <= CRCFLAG_RANGE[1]);
}

DynamicArray* create_dynamic_array() {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->size = 0;
    arr->capacity = 10; // Initial capacity
    arr->array = malloc(arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

void destroy_dynamic_array(DynamicArray *arr) {
    if (arr) {
        free(arr->array);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

int add_element(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!validate_tags(element)) return -1;

    pthread_mutex_lock(&arr->lock);

    if (arr->size >= MAX_ENTRIES) {
        log_overflow();
        pthread_mutex_unlock(&arr->lock);
        return -2;
    }

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&arr->lock);
            return -3; // Memory allocation failure
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }

    arr->array[arr->size++] = element;

    pthread_mutex_unlock(&arr->lock);
    return 0;
