    memcpy(&list->data[list->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    pthread_mutex_lock(&(log->log_mutex));
    log->insert_count++;
    pthread_mutex_unlock(&(log->log_mutex));

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void crc_list_serialize(const CrcList* list, const char* filename) {
