    NFAPIEvent *newEvents = (NFAPIEvent *)realloc(array->events, newCapacity * sizeof(NFAPIEvent));
    if (newEvents) {
        array->events = newEvents;
        array->capacity = newCapacity;
    }
}

// Add a new event
void addEvent(EventArray *array, const char *deviceIdentifier, time_t timestamp, unsigned int crcTag) {
    if (array->count == array->capacity) {
        resizeEventArray(array);
    }

    NFAPIEvent *event = &array->events[array->count++];
    strncpy(event->DeviceIdentifier, deviceIdentifier, sizeof(event->DeviceIdentifier));
    event->Timestamp = timestamp;
    event->CRC_INDICATION_REL8_TAG = crcTag;
    event->CRCFLAG = rand() % 2; // Random CRCFLAG
}

// Retrieve events by timestamp range
NFAPIEvent* getEventsByTimestamp(EventArray *array, time_t start, time_t end, size_t *resultCount) {
    NFAPIEvent *results = (NFAPIEvent *)malloc(array->count * sizeof(NFAPIEvent));
    *resultCount = 0;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->events[i].Timestamp >= start && array->events[i].Timestamp <= end) {
            results[(*resultCount)++] = array->events[i];
        }
    }

    return results;
}

// Update event by index
void updateEvent(EventArray *array, size_t index, const char *deviceIdentifier, time_t timestamp, unsigned int crcTag) {
