        // Introduce noise
        nfapiArray[i].rxUeInformationTag.tagLength = generateNoise(nfapiArray[i].rxUeInformationTag.tagLength, noiseSeed);

        nfapiArray[i].crcFlag = crcFlag;
    }

    return nfapiArray;
}

// Function to free the allocated memory.
