#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int signal_strength;  // in dBm
    float error_rate;     // percentage
    float packet_loss_ratio; // percentage
    float latency;        // milliseconds
} FrameStatistics;

#define NUM_STATS 100

FrameStatistics* init_frame_statistics() {
    FrameStatistics* stats = (FrameStatistics*)malloc(NUM_STATS * sizeof(FrameStatistics));
    if (!stats) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Function to populate the statistics
    void populate_statistics() {
        for (int i = 0; i < NUM_STATS; ++i) {
            pthread_mutex_lock(&lock);

            stats[i].timestamp = time(NULL); // Get current time

            // Simulate dynamic values reflecting real-world conditions
            stats[i].signal_strength = rand() % 100 - 120; // Signal strength between -120dBm and -20dBm
            stats[i].error_rate = (rand() % 1000) / 10.0f;   // Error rate as a float percentage
            stats[i].packet_loss_ratio = (rand() % 1000) / 10000.0f; // Packet loss ratio as a float percentage
            stats[i].latency = rand() % 50 + 1; // Latency between 1ms and 50ms

            pthread_mutex_unlock(&lock);
        }
    }

    // Create threads to simulate real-time updates
    const int num_threads = 4;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))populate_statistics, NULL)) {
            perror("Failed to create thread");
            free(stats);
            return NULL;
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);

    return stats;
}

void cleanup_frame_statistics(FrameStatistics* stats) {
    if (stats) {
        free(stats);
    }
}

int main() {
    FrameStatistics* frame_stats = init_frame_statistics();

    if (!frame_stats) {
        fprintf(stderr, "Error initializing frame statistics\n");
        return EXIT_FAILURE;
    }

    // Example usage
    for (int i = 0; i < NUM_STATS && i < 10; ++i) { // Just print first 10 entries for demonstration
        printf("Index %d: Time: %ld, Signal: %d dBm, Error Rate: %.2f%%, Packet Loss: %.4f%%, Latency: %.1f ms\n",
               i,
               frame_stats[i].timestamp,
               frame_stats[i].signal_strength,
               frame_stats[i].error_rate,
               frame_stats[i].packet_loss_ratio * 100.0f,
               frame_stats[i].latency);
    }

    cleanup_frame_statistics(frame_stats);

    return EXIT_SUCCESS;
}
