#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define MAX_PACKETS 1000

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    size_t packetSize;
    time_t timestamp;
} TCP_PACKET_STATS;

typedef struct {
    TCP_PACKET_STATS* packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int paused;
} PacketBuffer;

void initBuffer(PacketBuffer* buffer) {
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->cond, NULL);
    buffer->paused = 0;
}

void destroyBuffer(PacketBuffer* buffer) {
    for (int i = 0; i < buffer->count; ++i) {
        free(buffer->packets[i]);
    }
    pthread_mutex_destroy(&buffer->lock);
    pthread_cond_destroy(&buffer->cond);
}

void validatePacket(const char* packet, size_t size) {
    // Placeholder for packet validation logic
}

void* processPackets(void* arg) {
    PacketBuffer* buffer = (PacketBuffer*)arg;
    while (1) {
        pthread_mutex_lock(&buffer->lock);

        while (buffer->paused || buffer->count == 0) {
            pthread_cond_wait(&buffer->cond, &buffer->lock);
        }

        TCP_PACKET_STATS* stats = malloc(sizeof(TCP_PACKET_STATS));
        if (!stats) continue;

        // Simulate packet processing
        strcpy(stats->sourceIP, "192.168.1.1");
        strcpy(stats->destinationIP, "192.168.1.2");
        stats->packetSize = BUFFER_SIZE;
        stats->timestamp = time(NULL);

        buffer->packets[buffer->count++] = stats;

        pthread_mutex_unlock(&buffer->lock);
    }
    return NULL;
}

void pauseProcessing(PacketBuffer* buffer) {
    pthread_mutex_lock(&buffer->lock);
    buffer->paused = 1;
    pthread_mutex_unlock(&buffer->lock);
}

void resumeProcessing(PacketBuffer* buffer) {
    pthread_mutex_lock(&buffer->lock);
    buffer->paused = 0;
    pthread_cond_signal(&buffer->cond);
    pthread_mutex_unlock(&buffer->lock);
}

void addPacket(PacketBuffer* buffer, const char* packet, size_t size) {
    validatePacket(packet, size);

    pthread_mutex_lock(&buffer->lock);

    if (buffer->count < MAX_PACKETS) {
        TCP_PACKET_STATS* stats = malloc(sizeof(TCP_PACKET_STATS));
        if (!stats) {
            pthread_mutex_unlock(&buffer->lock);
            return;
        }

        strcpy(stats->sourceIP, "192.168.1.1");
        strcpy(stats->destinationIP, "192.168.1.2");
        stats->packetSize = size;
        stats->timestamp = time(NULL);

        buffer->packets[buffer->count++] = stats;

        pthread_cond_signal(&buffer->cond);
    }

    pthread_mutex_unlock(&buffer->lock);
}

void processDataStream() {
    PacketBuffer buffer;
    initBuffer(&buffer);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, processPackets, &buffer);

    // Simulate incoming packets
    const char* packet = "sample_packet_data";
    for (int i = 0; i < BUFFER_SIZE * 10; ++i) {
        addPacket(&buffer, packet, strlen(packet));
        if (i % 100 == 0) {
            pauseProcessing(&buffer);
            sleep(1); // Simulate processing pause
            resumeProcessing(&buffer);
        }
    }

    pthread_join(thread_id, NULL);
    destroyBuffer(&buffer);
}

int main() {
    processDataStream();
    return 0;
}
