['Below is a C code implementation that addresses your requirements for managing an array of `NFAPI_CRC_INDICATION_PDU_T` structures within a distributed network environment. The function uses thread-safe mechanisms to ensure no data races occur in a multi-threaded context, handling memory allocation dynamically and incorporating error checking.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// External functions for logging and storage
void log_event(const char* message);
int persist_structure(NFAPI_CRC_INDICATION_PDU_T* pdu);

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* structures;
    size_t count;
} NFAPI_CRC_MANAGER;

// Function prototypes
NFAPI_CRC_MANAGER* init_crc_manager();
void free_crc_manager(NFAPI_CRC_MANAGER* manager);
int add_pseudo_random_structure(NFAPI_CRC_MANAGER* manager);

// Utility function for logging duplicates
void log_duplicate_retries(int retries) {
    char message[100];
    snprintf(message, sizeof(message), "Duplicate RNTI found. Retry count: %d", retries);
    log_event(message);
}

NFAPI_CRC_MANAGER* init_crc_manager() {
    NFAPI_CRC_MANAGER* manager = malloc(sizeof(NFAPI_CRC_MANAGER));
    if (!manager) {
        perror("Failed to allocate memory for CRC manager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->structures = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->structures) {
        free(manager);
        perror("Failed to allocate memory for structures");
        return NULL;
    }

    manager->count = 0;
    return manager;
}

void free_crc_manager(NFAPI_CRC_MANAGER* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->structures);
    free(manager);
}

int add_pseudo_random_structure(NFAPI_CRC_MANAGER* manager) {
    if (!manager || manager->count >= MAX_STRUCTURES) return -1;

    pthread_mutex_lock(&manager->lock);

    int retries = 0;
    unsigned int rnti;
    NFAPI_CRC_INDICATION_PDU_T new_pdu;

    do {
        srand(time(NULL)); // Seed for randomness
        rnti = rand() % (UINT_MAX / 2); // Generate a pseudo-random RNTI
        new_pdu.RX_UE_INFORMATION_TAG = rand(); // Simulate valid tag
        new_pdu.CRC_INDICATION_REL8_TAG = rand() % 10; // Random REL8 tag
        new_pdu.CRCFLAG = rand() % 2; // CRC flag randomization

        int is_duplicate = 0;
        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->structures[i].RNTI == rnti) {
                is_duplicate = 1;
                break;
            }
        }

        if (is_duplicate && retries++ < 3) {
            log_duplicate_retries(retries);
            continue;
        } else if (!is_duplicate || retries >= 3) {
            new_pdu.RNTI = rnti;
            manager->structures[manager->count++] = new_pdu;

            // Persist the structure
            if (persist_structure(&new_pdu) != 0) {
                perror("Failed to persist structure");
            }

            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    } while (retries < 3);

    pthread_mutex_unlock(&manager->lock);
