#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <zlib.h> // For compression

// Enum for event types and logging levels.
typedef enum {
    RX_UE_INFORMATION_TAG,
    CRC_INDICATION_REL8_TAG
} EventType;

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

// Structure to hold a network log entry.
typedef struct NetworkEventLogEntry {
    time_t timestamp;
    EventType eventType;
    char message[256];
    LogLevel level;
} NetworkEventLogEntry;

// Global variables for dynamic array and synchronization.
static NetworkEventLogEntry *logArray = NULL;
static size_t capacity = 0, count = 0;
static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t logCondVar = PTHREAD_COND_INITIALIZER;

// Function to initialize the dynamic array with a specific initial capacity.
void initDynamicArray(size_t initialCapacity) {
    pthread_mutex_lock(&logMutex);
    logArray = malloc(initialCapacity * sizeof(NetworkEventLogEntry));
    if (!logArray) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    capacity = initialCapacity;
    pthread_mutex_unlock(&logMutex);
}

// Function to add an entry to the dynamic array.
void logEvent(EventType eventType, LogLevel level, const char *message) {
    NetworkEventLogEntry newEntry;
    time(&newEntry.timestamp);
    newEntry.eventType = eventType;
    strncpy(newEntry.message, message, sizeof(newEntry.message));
    newEntry.level = level;

    pthread_mutex_lock(&logMutex);

    if (count >= capacity) {
        // Double the size to minimize reallocations.
        size_t newCapacity = capacity * 2;
        logArray = realloc(logArray, newCapacity * sizeof(NetworkEventLogEntry));
        if (!logArray) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        capacity = newCapacity;
    }

    logArray[count++] = newEntry;
    pthread_cond_signal(&logCondVar);

    pthread_mutex_unlock(&logMutex);
}

// Background thread function for periodic flushing.
void *flushLogEntries(void *arg) {
    while (1) {
        pthread_mutex_lock(&logMutex);
        pthread_cond_wait(&logCondVar, &logMutex);

        // Compress and write to disk logic here
        // Example with zlib:
        FILE *compressedFile = fopen("log.gz", "wb");
        if (!compressedFile) {
            perror("Failed to open compressed file for writing");
            continue;
        }

        z_stream stream;
        memset(&stream, 0, sizeof(stream));
        deflateInit(&stream, Z_BEST_COMPRESSION);

        const size_t bufferSize = 4096;
        char in[bufferSize], out[bufferSize];
        int flush = Z_NO_FLUSH;

        for (size_t i = 0; i < count && flush != Z_STREAM_END;) {
            stream.next_in = (Bytef *)logArray + (i * sizeof(NetworkEventLogEntry));
            stream.avail_in = sizeof(NetworkEventLogEntry);

            do {
                stream.next_out = (Bytef *)out;
                stream.avail_out = bufferSize;

                deflate(&stream, flush);
                size_t have = bufferSize - stream.avail_out;
                if (fwrite(out, 1, have, compressedFile) != have || ferror(compressedFile)) {
                    perror("Failed to write compressed data");
                    break;
                }
            } while (stream.avail_out == 0);

            flush = i++ == count - 1 ? Z_FINISH : Z_NO_FLUSH;
        }

        deflateEnd(&stream);
        fclose(compressedFile);

        pthread_mutex_unlock(&logMutex);
    }

    return NULL;
}

// Function to start the flushing background thread.
void startFlushingThread() {
    pthread_t flushThreadId;
    if (pthread_create(&flushThreadId, NULL, flushLogEntries, NULL) != 0) {
        perror("Failed to create flushing thread");
        exit(EXIT_FAILURE);
    }
}

// Example function to iterate and print log entries.
void printLogEntries() {
    pthread_mutex_lock(&logMutex);
    for (size_t i = 0; i < count; ++i) {
        printf("%s: %s\n", ctime(&(logArray[i].timestamp)), logArray[i].message);
    }
    pthread_mutex_unlock(&logMutex);
}

// Entry point
int main() {
    initDynamicArray(100); // Start with an initial capacity.
    startFlushingThread();

    // Simulate logging events
    for (int i = 0; i < 200; ++i) {
        logEvent(RX_UE_INFORMATION_TAG, INFO, "Simulated RX event.");
        logEvent(CRC_INDICATION_REL8_TAG, DEBUG, "CRC flag random value set.");
    }

    printLogEntries();

    // Cleanup
    free(logArray);
    pthread_mutex_destroy(&logMutex);

    return 0;
}
```

This code initializes a dynamic array to manage `NetworkEventLogEntry` structures efficiently. It uses mutexes and condition variables to ensure thread safety during concurrent writes. A background thread periodically flushes the log entries to disk in a compressed format using zlib for compression, minimizing real-time impact. Adjustments can be made based on specific system requirements or constraints.']

