#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_PDU_COUNT 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int count;
} PduList;

PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_node(Node* node) {
    free(node);
}

void add_pdu(PduList* list, int rx_tag, int rnti) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Set random CRCFLAG
    srand(time(NULL)); // For demonstration; use a better RNG for actual usage.
    new_node->pdu.CRCFLAG = rand() % 2;

    new_node->pdu.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->pdu.RNTI = rnti;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    // Log the addition
    printf("PDU added: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", rx_tag, rnti);
}

void remove_pdu(PduList* list) {
    if (pthread_mutex_lock(&list->lock)) return;

    Node* temp = list->head;
    if (!temp) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->head = temp->next;
    destroy_node(temp);
    list->count--;

    // Log the removal
    printf("PDU removed\n");

    pthread_mutex_unlock(&list->lock);
}

void cleanup_pdu_list(PduList* list) {
    while (pthread_mutex_trylock(&list->lock) == 0) {
        Node* current = list->head;
        Node* next;

        while (current) {
            next = current->next;
            destroy_node(current);
            current = next;
        }

        list->head = NULL;
        list->count = 0;
        pthread_mutex_unlock(&list->lock);
    }
}

void free_pdu_list(PduList* list) {
    cleanup_pdu_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    PduList* pdu_list = create_pdu_list();
    if (!pdu_list) {
        fprintf(stderr, "Failed to initialize PDU list\n");
        return EXIT_FAILURE;
    }

    add_pdu(pdu_list, 123, 456);

    remove_pdu(pdu_list);

    cleanup_pdu_list(pdu_list);
    free_pdu_list(pdu_list);

    return EXIT_SUCCESS;
}
```

