#include <string.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_LIMIT 1024 * 1024 // 1MB limit for illustration
#define RNTI_RANGE 10000
#define VALID_CRCFLAG_MIN 0
#define VALID_CRCFLAG_MAX 255
#define MAX_RETRIES 3

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for memory management and logging
static size_t allocated_memory = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int log_verbosity_level = 1; // Adjust based on operational needs

// Function to retrieve RNTI from an external source with retry mechanism
unsigned int get_rnti_with_retry() {
    unsigned int rnti;
    int attempts = 0;

    while (attempts < MAX_RETRIES) {
        // Simulate retrieval from an external data source
        if ((rand() % 10) < 8) { // Simulating occasional connectivity issues
            rnti = rand() % RNTI_RANGE;
            break; // Successful retrieval
        }
        attempts++;
    }

    if (attempts == MAX_RETRIES) {
        fprintf(stderr, "Failed to retrieve RNTI after retries.\n");
        return 0; // Indicating failure
    }

    return rnti;
}

// Function to validate CRCFLAG
int is_valid_crcflag(unsigned char crcflag) {
    return (crcflag >= VALID_CRCFLAG_MIN && crcflag <= VALID_CRCFLAG_MAX);
}

// Main function to create and manage NFAPI_CRC_INDICATION_PDU_T structures
int generate_nfa_api_pdus(NFAPI_CRC_INDICATION_PDU_T **pdulist, int count) {
    if (!pdulist || count <= 0) return -1;

    *pdulist = NULL;
    unsigned int last_rnti = 0; // Track the RNTI to avoid consecutive duplicates
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(struct_size);
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(*pdulist);
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        // Check memory limit
        allocated_memory += struct_size;
        if (allocated_memory > MEMORY_LIMIT) {
            free(pdu);
            free(*pdulist);
            pthread_mutex_unlock(&mutex);
            return -2; // Memory limit exceeded
        }

        pdu->RX_UE_INFORMATION_TAG = rand(); // Populate with valid data

        unsigned int rnti;
        do {
            rnti = get_rnti_with_retry();
        } while (rnti == last_rnti);

        if (!rnti) {
            free(pdu);
            continue; // Skip this iteration due to RNTI retrieval failure
        }

        pdu->RNTI = rnti;
        last_rnti = rnti;

        pdu->CRC_INDICATION_REL8_TAG = rand(); // Populate with valid data

        unsigned char crcflag = rand() % (VALID_CRCFLAG_MAX - VALID_CRCFLAG_MIN + 1) + VALID_CRCFLAG_MIN;
        if (!is_valid_crcflag(crcflag)) {
            free(pdu);
            continue; // Skip this iteration due to invalid CRCFLAG
        }

        pdu->CRCFLAG = crcflag;

        *pdulist = realloc(*pdulist, (i + 1) * struct_size);
        (*pdulist)[i] = *pdu;
    }

    pthread_mutex_unlock(&mutex);

    if (log_verbosity_level > 0) {
        printf("Successfully generated %d NFAPI_CRC_INDICATION_PDU_T structures.\n", count);
    }

    return 0; // Success
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    int result = generate_nfa_api_pdus(&pdus, 100);

    if (result == 0) {
        printf("PDUs generated successfully.\n");
    } else {
        printf("Error generating PDUs: %d\n", result);
    }

    // Cleanup
    free(pdus);

    return 0;
}
