    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->contexts[i]->UE_ID == UE_ID) {
            free(arr->contexts[i]->NASMessage.data);
            free(arr->contexts[i]);
            arr->contexts[i] = arr->contexts[--arr->size];
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

// Update NAS message asynchronously
void *update_nas_message(void *arg) {
    UEContextInfo *context = (UEContextInfo *)arg;
    // Simulate receiving new payload size and data update
    context->NASMessage.payload_size += 10; // Example change
    context->NASMessage.data = realloc(context->NASMessage.data, context->NASMessage.payload_size);

    return NULL;
}

// Asynchronously update NAS message for a given UE_ID
int async_update_nas_message(DynamicArray *arr, int UE_ID) {
    pthread_t thread;

    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->contexts[i]->UE_ID == UE_ID) {
            pthread_create(&thread, NULL, update_nas_message, arr->contexts[i]);
            pthread_detach(thread);
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

// Clean up dynamic array
void cleanup_dynamic_array(DynamicArray *arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->contexts[i]->NASMessage.data);
        free(arr->contexts[i]);
    }
    free(arr->contexts);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

// Example usage
int main() {
    DynamicArray *arr = init_dynamic_array();

    add_context(arr, 1, CONNECTED, 100);
    async_update_nas_message(arr, 1);
    remove_context(arr, 1);

    cleanup_dynamic_array(arr);
    return 0;
}
