#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define the CRC indication PDU structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set to 0 or 1
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node of the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list structure with a mutex for concurrency control
typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} CRCLinkedList;

// Function prototypes
CRCLinkedList* create_list();
void destroy_list(CRCLinkedList* list);
int insert_node(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data);
int delete_node(CRCLinkedList* list, uint32_t RX_UE_INFORMATION_TAG);
NFAPI_CRC_INDICATION_PDU_T* find_node(CRCLinkedList* list, uint32_t RX_UE_INFORMATION_TAG);
void initialize_node(NFAPI_CRC_INDICATION_PDU_T* node);

// Create and initialize a new linked list
CRCLinkedList* create_list() {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->count = 0;

    return list;
}

// Destroy the linked list and free memory
void destroy_list(CRCLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Insert a new node into the linked list
int insert_node(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->count >= 10000) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    initialize_node(&new_node->data);
    new_node->data.RX_UE_INFORMATION_TAG = data.RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = data.RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Delete a node from the linked list
int delete_node(CRCLinkedList* list, uint32_t RX_UE_INFORMATION_TAG) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current == list->tail) {
        list->tail = prev;
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Find a node in the linked list
NFAPI_CRC_INDICATION_PDU_T* find_node(CRCLinkedList* list, uint32_t RX_UE_INFORMATION_TAG) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

// Initialize the fields of a node
void initialize_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    node->RX_UE_INFORMATION_TAG = 0;
    node->RNTI = 0;
    node->CRC_INDICATION_REL8_TAG.CRCFLAG = -1; // Invalid initial value
}
```

