#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 1000

typedef enum {
    MESSAGE_TYPE_A,
    MESSAGE_TYPE_B,
    // Add more message types as needed
} NAS_MESSAGE_TYPE;

typedef struct {
    NAS_MESSAGE_TYPE type;
    unsigned int sequence_number;
    char *content;
} NR_NAS_MESSAGE_T;

typedef struct {
    NR_NAS_MESSAGE_T *messages;
    size_t capacity;
    size_t count;
} DynamicArray;

size_t getBufferSize(NAS_MESSAGE_TYPE type) {
    switch (type) {
        case MESSAGE_TYPE_A:
            return 128; // Example buffer size for message type A
        case MESSAGE_TYPE_B:
            return 256; // Example buffer size for message type B
        default:
            return 64; // Default size for unknown types
    }
}

void resizeArray(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    if (new_capacity > 50000) {
        new_capacity = 50000;
    }

    NR_NAS_MESSAGE_T *new_messages = realloc(array->messages, new_capacity * sizeof(NR_NAS_MESSAGE_T));
    if (!new_messages) {
        perror("Failed to resize array");
        exit(EXIT_FAILURE);
    }

    array->messages = new_messages;
    array->capacity = new_capacity;
}

void addMessage(DynamicArray *array, NR_NAS_MESSAGE_T message) {
    if (array->count >= array->capacity) {
        resizeArray(array);
    }

    size_t buffer_size = getBufferSize(message.type);
    message.content = malloc(buffer_size);

    if (!message.content) {
        perror("Failed to allocate memory for message content");
        exit(EXIT_FAILURE);
    }

    // Initialize the content with zeros
    memset(message.content, 0, buffer_size);

    array->messages[array->count++] = message;
}

void removeMessage(DynamicArray *array, size_t index) {
    if (index >= array->count) {
        fprintf(stderr, "Invalid index\n");
        return;
    }

    free(array->messages[index].content);
    for (size_t i = index; i < array->count - 1; ++i) {
        array->messages[i] = array->messages[i + 1];
    }
    --array->count;

    if (array->count > 0 && array->count <= array->capacity / 4) {
        size_t new_capacity = array->capacity / 2;
        if (new_capacity < INITIAL_CAPACITY) {
            new_capacity = INITIAL_CAPACITY;
        }

        NR_NAS_MESSAGE_T *new_messages = realloc(array->messages, new_capacity * sizeof(NR_NAS_MESSAGE_T));
        if (!new_messages && new_capacity != array->capacity) {
            perror("Failed to shrink array");
            exit(EXIT_FAILURE);
        }

        array->messages = new_messages;
        array->capacity = new_capacity;
    }
}

void serializeArray(const DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        exit(EXIT_FAILURE);
    }

    fwrite(&array->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < array->count; ++i) {
        fwrite(&array->messages[i].type, sizeof(NAS_MESSAGE_TYPE), 1, file);
        fwrite(&array->messages[i].sequence_number, sizeof(unsigned int), 1, file);

        size_t buffer_size = getBufferSize(array->messages[i].type);
        fwrite(&buffer_size, sizeof(size_t), 1, file);
        fwrite(array->messages[i].content, buffer_size, 1, file);
    }

    fclose(file);
}

DynamicArray deserializeArray(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        exit(EXIT_FAILURE);
    }

    DynamicArray array;
    array.capacity = INITIAL_CAPACITY;
    array.count = 0;
    array.messages = malloc(array.capacity * sizeof(NR_NAS_MESSAGE_T));

    if (!array.messages) {
        perror("Failed to allocate memory for messages");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fread(&array.count, sizeof(size_t), 1, file);

    if (array.count > array.capacity) {
        size_t new_capacity = array.count;
        NR_NAS_MESSAGE_T *new_messages = realloc(array.messages, new_capacity * sizeof(NR_NAS_MESSAGE_T));

        if (!new_messages) {
            perror("Failed to resize array during deserialization");
            fclose(file);
            free(array.messages);
            exit(EXIT_FAILURE);
        }

        array.messages = new_messages;
        array.capacity = new_capacity;
    }

    for (size_t i = 0; i < array.count; ++i) {
        fread(&array.messages[i].type, sizeof(NAS_MESSAGE_TYPE), 1, file);
        fread(&array.messages[i].sequence_number, sizeof(unsigned int), 1, file);

        size_t buffer_size;
        fread(&buffer_size, sizeof(size_t), 1, file);

        array.messages[i].content = malloc(buffer_size);

        if (!array.messages[i].content) {
            perror("Failed to allocate memory for message content during deserialization");
            fclose(file);
            // Free previously allocated contents
            while (--i >= 0) free(array.messages[i].content);
            free(array.messages);
            exit(EXIT_FAILURE);
        }

        fread(array.messages[i].content, buffer_size, 1, file);
    }

    fclose(file);
    return array;
}

void freeArray(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i].content);
    }

    free(array->messages);
    array->messages = NULL;
    array->capacity = 0;
    array->count = 0;
}
