    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to manage the list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    size_t count;
    pthread_mutex_t mutex;
} NFAPICRCList;

// Logger function for demonstration purposes.
void log_message(const char *message) {
    printf("%s\n", message);
}

// Function to initialize the list
int init_nfapi_crc_list(NFAPICRCList *nfapi_list) {
    nfapi_list->list = NULL;
    nfapi_list->count = 0;
    if (pthread_mutex_init(&nfapi_list->mutex, NULL) != 0) {
        log_message("Mutex initialization failed");
        return -1;
    }
    return 0;
}

// Function to add an element to the list
int add_nfapi_crc_pdu(NFAPICRCList *nfapi_list) {
    pthread_mutex_lock(&nfapi_list->mutex);

    NFAPI_CRC_INDICATION_PDU_T **new_list = realloc(nfapi_list->list, (nfapi_list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!new_list) {
        log_message("Memory allocation failed for list expansion");
        pthread_mutex_unlock(&nfapi_list->mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        free(new_list);
        log_message("Memory allocation failed for PDU");
        pthread_mutex_unlock(&nfapi_list->mutex);
        return -1;
    }

    // Set the structure fields with random values
    pdu->rx_ue_info.value = rand() % 0xFFFFFFFF;  // Random RX_UE_INFORMATION_TAG
    pdu->rnti = (RNTI)rand();                     // Random RNTI
    pdu->crc_rel8_tag.CRCFLAG = rand() & 1;       // Random CRCFLAG

    new_list[nfapi_list->count] = pdu;
    nfapi_list->list = new_list;
    ++nfapi_list->count;

    log_message("Successfully added a PDU");
    pthread_mutex_unlock(&nfapi_list->mutex);

    return 0;
}

// Function to free the list
void free_nfapi_crc_list(NFAPICRCList *nfapi_list) {
    pthread_mutex_lock(&nfapi_list->mutex);

    for (size_t i = 0; i < nfapi_list->count; ++i) {
        free(nfapi_list->list[i]);
    }
    free(nfapi_list->list);

    if (pthread_mutex_destroy(&nfapi_list->mutex) != 0) {
        log_message("Mutex destruction failed");
    }

    nfapi_list->list = NULL;
    nfapi_list->count = 0;

    pthread_mutex_unlock(&nfapi_list->mutex);
    log_message("Resources freed successfully");
}

// Benchmarking function for performance evaluation
void benchmark_performance(NFAPICRCList *nfapi_list, int iterations) {
    const char *start_msg = "Benchmark start";
    const char *end_msg = "Benchmark end";

    log_message(start_msg);

    // Simulate high-load conditions by adding many elements
    for (int i = 0; i < iterations; ++i) {
        add_nfapi_crc_pdu(nfapi_list);
    }

    log_message(end_msg);
}

// Main function to demonstrate usage
int main() {
    NFAPICRCList nfapi_list;
    if (init_nfapi_crc_list(&nfapi_list) != 0) {
        return EXIT_FAILURE;
    }

    // Example benchmark with 10000 iterations
    benchmark_performance(&nfapi_list, 10000);

    free_nfapi_crc_list(&nfapi_list);

    return EXIT_SUCCESS;
}
