// Define structures as per your requirements.
typedef struct {
    int UE_ID;
} NFAPI_UE_ID_T;

typedef struct {
    unsigned char CRCFLAG; // 0 or 1 based on probability
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Utility function to log messages.
void log_message(const char *message) {
    printf("%s\n", message);
}

// Function to allocate and initialize the array of structures.
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(
    NFAPI_UE_ID_T *ue_ids, int num_ue_ids, float crc_flag_probability, bool *error_occurred) {

    // Validate inputs
    if (!ue_ids || num_ue_ids <= 0 || !error_occurred) {
        log_message("Invalid input parameters.");
        return NULL;
    }

    // Hash table to check for duplicate RNTI values.
    int *rnti_hash_table = (int *)calloc(num_ue_ids, sizeof(int));
    if (!rnti_hash_table) {
        log_message("Memory allocation failure for hash table.");
        *error_occurred = true;
        return NULL;
    }

    // Validate and prepare RNTIs to avoid duplicates.
    int unique_rnti_count = 0;
    for (int i = 0; i < num_ue_ids; ++i) {
        if (!rnti_hash_table[ue_ids[i].UE_ID]) { // Assuming UE_ID is used as a proxy for RNTI
            rnti_hash_table[ue_ids[i].UE_ID] = 1;
            unique_rnti_count++;
        }
    }

    free(rnti_hash_table);

    if (unique_rnti_count == 0) {
        log_message("No valid unique RNTIs found.");
        *error_occurred = true;
        return NULL;
    }

    // Allocate memory for the PDU array.
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(unique_rnti_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        log_message("Memory allocation failure for pdu_array.");
        *error_occurred = true;
        return NULL;
    }

    int index = 0;
    bool seen_rntis[num_ue_ids] = {false};

    // Populate the structures with unique RNTIs.
    for (int i = 0; i < num_ue_ids && index < unique_rnti_count; ++i) {
        if (!seen_rntis[ue_ids[i].UE_ID]) {
            pdu_array[index].RX_UE_INFORMATION_TAG = i + 1;
            pdu_array[index].RNTI = ue_ids[i].UE_ID;

            // Set CRCFLAG based on probability
            if ((rand() / (float)RAND_MAX) < crc_flag_probability) {
                pdu_array[index].CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
            } else {
                pdu_array[index].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
            }

            seen_rntis[ue_ids[i].UE_ID] = true;
            index++;
        }
    }

    log_message("Successfully created CRC indication PDU array.");
    *error_occurred = false;
    return pdu_array;
}

// Example usage
int main() {
    NFAPI_UE_ID_T ue_ids[] = {{1}, {2}, {3}, {2}, {4}};
    int num_ue_ids = sizeof(ue_ids) / sizeof(ue_ids[0]);
    float crc_flag_probability = 0.5;
    bool error_occurred;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = create_crc_indication_pdu_array(
        ue_ids, num_ue_ids, crc_flag_probability, &error_occurred);

    if (error_occurred) {
        log_message("An error occurred during PDU array creation.");
    } else if (pdu_array) {
        // Use the pdu_array...

        free(pdu_array);
    }

    return 0;
}
