int compare_rnti(const void *a, const void *b);

// Global lock for thread safety
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t n) {
    pthread_mutex_lock(&list_lock);
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&list_lock);
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t n) {
    pthread_mutex_lock(&list_lock);
    free(list);
    pthread_mutex_unlock(&list_lock);
}

int populate_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t n, int mode) {
    srand((unsigned)time(NULL));
    uint16_t used_rnti[MAX_RNTI + 1] = {0};

    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&list_lock);

        // Find a unique RNTI
        int rnti_found = 0;
        while (!rnti_found) {
            uint16_t rnti = rand() % (MAX_RNTI + 1);
            if (!used_rnti[rnti]) {
                used_rnti[rnti] = 1;
                list[i].rnti = rnti;
                // Initialize other fields as necessary
                rnti_found = 1;
            }
        }

        pthread_mutex_unlock(&list_lock);
    }

    qsort(list, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    if (mode) {
        printf("List populated in test mode\n");
    } else {
        printf("List populated in production mode\n");
    }

    return 0;
}

int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *entry_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *entry_b = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return entry_a->rnti - entry_b->rnti;
}

// Example usage
int main() {
    size_t n = 1000; // Number of structures
    NFAPI_CRC_INDICATION_PDU_T *list;

    initialize_list(&list, n);
    populate_list(list, n, 1); // Use 1 for test mode, 0 for production mode

    destroy_list(list, n);
    return 0;
}
