// Define LTEPHYTIMER structure
typedef struct {
    uint32_t id;
    uint64_t timeout_ms;
    uint8_t config_settings[256];
} LTEPHYTIMER;

// Node for the linked list of timers
typedef struct TimerNode {
    LTEPHYTIMER timer;
    struct TimerNode* next;
} TimerNode;

// Dynamic list structure with thread-safe mechanisms
typedef struct {
    TimerNode* head;
    pthread_mutex_t lock;
    size_t count;
} TimerList;

// Function to initialize the dynamic list
void initTimerList(TimerList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

// Function to add a timer to the list
int addTimer(TimerList* list, LTEPHYTIMER timer) {
    TimerNode* new_node = (TimerNode*)malloc(sizeof(TimerNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new timer node.\n");
        return -1;
    }

    memcpy(&new_node->timer, &timer, sizeof(LTEPHYTIMER));
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Add to the head of the list
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove a timer from the list by id
int removeTimer(TimerList* list, uint32_t id) {
    pthread_mutex_lock(&list->lock);

    TimerNode *current = list->head, *prev = NULL;

    while (current != NULL && current->timer.id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Timer not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to clear all timers and release resources
void clearTimers(TimerList* list) {
    pthread_mutex_lock(&list->lock);

    TimerNode *current = list->head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

// Function to log the status of timers
void logTimerStatus(const TimerList* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    TimerNode* current = list->head;
    printf("Current number of timers: %zu\n", list->count);

    while (current != NULL) {
        printf("Timer ID: %u, Timeout: %" PRIu64 " ms\n", current->timer.id, current->timer.timeout_ms);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

// Example usage
int main() {
    TimerList timer_list;
    initTimerList(&timer_list);

    // Add example timers
    LTEPHYTIMER timer1 = { .id = 1, .timeout_ms = 1000, .config_settings = {0} };
    addTimer(&timer_list, timer1);

    LTEPHYTIMER timer2 = { .id = 2, .timeout_ms = 2000, .config_settings = {1} };
    addTimer(&timer_list, timer2);

    // Log the status of timers
    logTimerStatus(&timer_list);

    // Remove a timer and log again
    removeTimer(&timer_list, 1);
    logTimerStatus(&timer_list);

    // Clear all timers before exiting
    clearTimers(&timer_list);

    return 0;
}
