    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} CRC_Indication_List;

void initialize_list(CRC_Indication_List *list) {
    list->count = 0;
    list->capacity = 10; // Initial capacity
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        fprintf(stderr, "Failed to allocate memory for CRC_Indication_List\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->mutex, NULL);
}

void validate_and_add_entry(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (entry.RX_UE_INFORMATION_TAG <= 0 || entry.RNTI <= 0) {
        fprintf(stderr, "Validation error: Invalid RX_UE_INFORMATION_TAG or RNTI\n");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    // Resize array if necessary
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            fprintf(stderr, "Failed to reallocate memory for CRC_Indication_List\n");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    // Add entry
    list->entries[list->count++] = entry;

    pthread_mutex_unlock(&list->mutex);
}

void update_entry(CRC_Indication_List *list, int rnti, NFAPI_CRC_INDICATION_PDU_T updated_entry) {
    if (updated_entry.RX_UE_INFORMATION_TAG <= 0 || updated_entry.RNTI <= 0) {
        fprintf(stderr, "Validation error: Invalid RX_UE_INFORMATION_TAG or RNTI\n");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == rnti) {
            list->entries[i] = updated_entry;
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void remove_entry(CRC_Indication_List *list, int rnti) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == rnti) {
            memmove(&list->entries[i], &list->entries[i + 1],
                    (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void iterate_and_transform(CRC_Indication_List *list, unsigned char (*transform)(unsigned char)) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        list->entries[i].CRC_INDICATION_REL8_TAG = transform(list->entries[i].CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_unlock(&list->mutex);
}

unsigned char example_transform(unsigned char tag) {
    // Example transformation using bitwise operations
    return (tag << 1) | (tag >> 7);  // Rotate left by one bit
}

void free_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->mutex);

    free(list->entries);
    list->count = 0;
    list->capacity = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
