```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RNTI 65535
#define MIN_RNTI 1

typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned int CRCFLAG:1;
        // Additional fields can be added here
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { ERROR, WARNING, INFO, DEBUG } LogLevel;

void log_message(LogLevel level, const char* message) {
    static const char* levels[] = {"ERROR", "WARNING", "INFO", "DEBUG"};
    printf("[%s] %s\n", levels[level], message);
}

int is_rnti_in_use(unsigned short rnti, unsigned short *used_rntis, int count) {
    for (int i = 0; i < count; ++i) {
        if (used_rntis[i] == rnti) return 1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int n, LogLevel log_level) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        log_message(log_level, "Memory allocation failed");
        return NULL;
    }

    unsigned short used_rntis[n];
    memset(used_rntis, 0, n * sizeof(unsigned short));

    srand(time(NULL)); // Seed for randomness
    int created_count = 0;

    for (int i = 0; i < n; ++i) {
        int success = 0;
        while (!success) {
            unsigned short rnti = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
            if (!is_rnti_in_use(rnti, used_rntis, created_count)) {
                pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
                pdu_list[i].RNTI = rnti;
                pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

                used_rntis[created_count++] = rnti;
                success = 1;
            }
        }
    }

    log_message(log_level, "Successfully created CRC indication structures");

    // Export to text-based format
    FILE *file = fopen("crc_indications.txt", "w");
    if (!file) {
        log_message(log_level, "Failed to open file for export");
        free(pdu_list);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
                pdu_list[i].RX_UE_INFORMATION_TAG,
                pdu_list[i].RNTI,
                pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    fclose(file);
    log_message(log_level, "Successfully exported structures to file");

    return pdu_list;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T *pdu_list) {
    if (pdu_list) free(pdu_list);
}

int main() {
    int n = 10; // Number of structures
    LogLevel log_level = INFO;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = generate_crc_indications(n, log_level);

    if (pdu_list) {
        // Use the pdu_list as needed
        cleanup(pdu_list);
    }

    return 0;
}
