    NFAPI_CRC_INDICATION_PDU_T *data;
    time_t timestamp;
} HistoryEntry;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static HistoryEntry history[MAX_HISTORY_ENTRIES];
static int history_count = 0;

void log_event(const char *event, size_t size, size_t id) {
    // Placeholder for logging integration
