NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_list(size_t N, size_t *id_out) {
    if (N <= 0 || id_out == NULL) return NULL;

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed for size %zu\n", N);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    log_event("Allocation", N * sizeof(NFAPI_CRC_INDICATION_PDU_T), (size_t)time(NULL));

    for (size_t i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 1000;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        list[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    *id_out = (size_t)time(NULL);

    if (history_count < MAX_HISTORY_ENTRIES) {
        history[history_count++] = (HistoryEntry){*id_out, list, time(NULL)};
    } else {
        free(history[0].data); // Clear the oldest entry
        for (int i = 1; i < MAX_HISTORY_ENTRIES; ++i) {
            history[i - 1] = history[i];
        }
        history[MAX_HISTORY_ENTRIES - 1] = (HistoryEntry){*id_out, list, time(NULL)};
    }

    pthread_mutex_unlock(&lock);
    return list;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_history(size_t id) {
    if (id == 0 || id >= MAX_HISTORY_ENTRIES) return NULL;

    pthread_mutex_lock(&lock);

    for (int i = 0; i < history_count; ++i) {
        if (history[i].id == id) {
            log_event("Retrieval", sizeof(NFAPI_CRC_INDICATION_PDU_T), id);
            pthread_mutex_unlock(&lock);
            return history[i].data;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void free_nfa_list(size_t id, NFAPI_CRC_INDICATION_PDU_T *list) {
    if (!list) return;

    log_event("Deallocation", sizeof(NFAPI_CRC_INDICATION_PDU_T), id);

    for (int i = 0; i < history_count; ++i) {
        if (history[i].id == id && history[i].data == list) {
            pthread_mutex_lock(&lock);
            free(list);
            for (int j = i; j < history_count - 1; ++j) {
                history[j] = history[j + 1];
            }
            --history_count;
            pthread_mutex_unlock(&lock);
            break;
        }
    }
}

void clear_old_history_entries() {
    time_t now = time(NULL);

    pthread_mutex_lock(&lock);

    for (int i = 0; i < history_count; ++i) {
        if (difftime(now, history[i].timestamp) > 3600) { // Remove entries older than an hour
            free(history[i].data);
            for (int j = i; j < history_count - 1; ++j) {
                history[j] = history[j + 1];
            }
            --history_count;
            --i;
        }
    }

    pthread_mutex_unlock(&lock);
}

// Example usage
int main() {
    size_t id;
    NFAPI_CRC_INDICATION_PDU_T *list = allocate_nfa_list(10, &id);

    if (list) {
        NFAPI_CRC_INDICATION_PDU_T *retrieved_list = get_from_history(id);

        // Process retrieved list...

        free_nfa_list(id, list);
    }

    clear_old_history_entries();

    return 0;
}
