#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MAX_MEMORY_USAGE (5 * 1024 * 1024) // 5 MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
        // Add other members as needed for REL8_TAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t element_count;
    size_t memory_usage;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->element_count = 0;
    list->memory_usage = sizeof(CRCList);
    return list;
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->element_count >= MAX_ELEMENTS || 
        (list->memory_usage + sizeof(Node)) > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Resource limit reached
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;

    list->element_count++;
    list->memory_usage += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void initialize_random() {
    srand((unsigned int)time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T create_random_pdu(uint32_t ue_info, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = ue_info;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void simulate_input(CRCList* list, uint32_t ue_info, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu = create_random_pdu(ue_info, rnti);
    if (add_element(list, pdu) != 0) {
        fprintf(stderr, "Failed to add element: Resource limit reached or memory allocation failed.\n");
    }
}

int main(int argc, char* argv[]) {
    initialize_random();

    CRCList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    // Simulate high-throughput scenario
    for (uint32_t i = 0; i < MAX_ELEMENTS; ++i) {
        simulate_input(list, i, (uint16_t)(i % 1024));
    }

    destroy_list(list);
    return 0;
}
```

