typedef struct {
    int UE_ID;
    time_t timestamp;
    uint8_t *raw_data_buffer;
} NFAPI_RX_FRAME_T;

typedef struct FrameNode {
    NFAPI_RX_FRAME_T frame;
    struct FrameNode* next;
} FrameNode;

FrameNode* frame_queue_head = NULL;
FrameNode* frame_queue_tail = NULL;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    // Simple error logging function
    fprintf(stderr, "Error: %s\n", message);
}

void enqueue_frame(NFAPI_RX_FRAME_T frame) {
    FrameNode* new_node = (FrameNode*)malloc(sizeof(FrameNode));
    if (!new_node) {
        log_error("Failed to allocate memory for queue node");
        return;
    }

    new_node->frame = frame;
    new_node->next = NULL;

    pthread_mutex_lock(&queue_mutex);
    if (frame_queue_tail == NULL) {
        frame_queue_head = frame_queue_tail = new_node;
    } else {
        frame_queue_tail->next = new_node;
        frame_queue_tail = new_node;
    }
    pthread_mutex_unlock(&queue_mutex);
}

int initialize_rx_frame_array(NFAPI_RX_FRAME_T *rx_frames, size_t num_frames, size_t buffer_size) {
    for (size_t i = 0; i < num_frames; ++i) {
        rx_frames[i].UE_ID = -1;
        rx_frames[i].timestamp = time(NULL);

        // Align the buffer to cache line boundary for better performance
        size_t alignment = 64; // Typically cache line size is 64 bytes
        void *ptr = NULL;

        if (posix_memalign(&ptr, alignment, buffer_size) != 0 || ptr == NULL) {
            log_error("Failed to allocate memory for RX data buffer");
            return -1;
        }

        rx_frames[i].raw_data_buffer = ptr;
    }

    return 0; // Success
}

void free_rx_frame_array(NFAPI_RX_FRAME_T *rx_frames, size_t num_frames) {
    for (size_t i = 0; i < num_frames; ++i) {
        if (rx_frames[i].raw_data_buffer != NULL) {
            free(rx_frames[i].raw_data_buffer);
            rx_frames[i].UE_ID = -1;
            rx_frames[i].timestamp = 0;
        }
    }
}

// Design choices and trade-offs
/*
 * - We use heap-based memory allocation for the RX data buffer to allow dynamic resizing based on network conditions.
 *   This is more flexible than stack allocation, especially in a multi-threaded environment where each thread can manage its own stack independently.
 * 
 * - A queue mechanism is implemented using a linked list to handle situations when buffers cannot be allocated due to resource constraints. This helps
 *   prevent buffer overflow and allows for deferring processing of frames until resources are available.
 * 
 * - The error logging system provides a simple way to record allocation failures, aiding in debugging under high-load conditions.
 * 
 * - Memory alignment is handled using `posix_memalign` to ensure that the RX data buffers align with cache lines (typically 64 bytes), optimizing memory
 *   bandwidth and performance on most modern architectures. This trade-off between slightly more complex memory handling and improved performance is justified
 *   in high-throughput scenarios.
 */

