    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    size_t max_size;
} CRCList;

// Function prototypes
CRCList* create_crc_list(size_t max_size);
void destroy_crc_list(CRCList* list);
bool insert_crc_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T* get_random_pdu(CRCList* list);
void garbage_collect(CRCList* list);

// Create a new CRC list with a specified maximum size
CRCList* create_crc_list(size_t max_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = max_size;

    return list;
}

// Destroy the CRC list and free resources
void destroy_crc_list(CRCList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Insert a new CRC PDU into the list
bool insert_crc_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count >= list->max_size) return false;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Retrieve a random CRC PDU from the list
NFAPI_CRC_INDICATION_PDU_T* get_random_pdu(CRCList* list) {
    if (!list || !list->head) return NULL;

    size_t index = rand() % list->count;
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current; ++i) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

// Periodic garbage collection to free unused structures
void garbage_collect(CRCList* list) {
    // Implement logic to identify and remove unused nodes
    // This is a placeholder for actual garbage collection logic
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if (/* condition to check if node is unused */) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            list->count--;
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    // Example usage
    CRCList* crc_list = create_crc_list(100);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3};
    insert_crc_pdu(crc_list, pdu);

    NFAPI_CRC_INDICATION_PDU_T* random_pdu = get_random_pdu(crc_list);
    if (random_pdu) {
        printf("Random PDU: RX=%d, RNTI=%d, CRC_TAG=%d\n",
               random_pdu->RX_UE_INFORMATION_TAG,
               random_pdu->RNTI,
               random_pdu->CRC_INDICATION_REL8_TAG);
    }

    garbage_collect(crc_list);
    destroy_crc_list(crc_list);

    return 0;
}
