['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535
#define MIN_RNTI 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Linked list head pointer
Node* head = NULL;

// Helper function to insert a new node at the end of the linked list
void append_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&lock);
}

// Helper function to check if RNTI is already used
int rnti_exists(int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Function to generate and populate the list
void generate_nfa_list(int count, int valid_range_min, int valid_range_max) {
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        int rnti;
        do {
            rnti = rand() % (valid_range_max - valid_range_min + 1) + valid_range_min;
        } while (rnti_exists(rnti));

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i; // Example value
        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 100; // Example range
        pdu.CRCFLAG = rand() % 2;

        append_node(pdu);
    }
}

// Function to export the list to a text-based format
void export_list_to_file(const char* filename) {
    pthread_mutex_lock(&lock);

    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                current->data.RX_UE_INFORMATION_TAG,
                current->data.RNTI,
                current->data.CRC_INDICATION_REL8_TAG,
                current->data.CRCFLAG);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&lock);
}

// Function to generate a report
void generate_report(const char* filename) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    int count = 0;
    while (current != NULL) {
        ++count;
        current = current->next;
    }

    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open report file for writing\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    fprintf(file, "Number of structures created: %d\n", count);

    fclose(file);
    pthread_mutex_unlock(&lock);
}

// Cleanup function to free allocated memory
void cleanup() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    int num_structures = 10;
    int valid_range_min = MIN_RNTI;
    int valid_range_max = MAX_RNTI;

    generate_nfa_list(num_structures, valid_range_min, valid_range_max);

    export_list_to_file("nfa_list.txt");
    generate_report("report.txt");

    cleanup();

    return 0;
}
```

