    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: u8,
    crcflag: bool,
}

fn populate_crc_indication_list(
    n: usize, // Number of structures to populate
) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    // Retrieve or create the directory path for CRC indication data
    let dir_path = match env::var("CRC_INDICATION_LIST_DIR") {
        Ok(path) => PathBuf::from(path),
        Err(_) => {
            let timestamped_dir = format!("/tmp/crc-indications/{}", chrono::Utc::now().format("%Y%m%d%H%M%S"));
            if let Err(e) = fs::create_dir_all(&Path::new(&timestamped_dir)) {
                error!("Failed to create directory: {:?}", e);
                return vec![]; // Exit early on failure
            }
            env::set_var("CRC_INDICATION_LIST_DIR", &timestamped_dir);
            PathBuf::from(timestamped_dir)
        }
    };

    let mut rng = thread_rng();
    let crc_list = Arc::new(Mutex::new(Vec::with_capacity(n)));

    for _ in 0..n {
        // Generate random data
        let rx_ue_information_tag: u32 = rng.gen();
        let rnti: u16 = rng.gen();
        let crc_indication_rel8_tag: u8 = rng.gen();
        let crcflag: bool = rng.gen();

        let pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag,
            crcflag,
        };

        if let Ok(mut list) = Arc::try_unwrap(crc_list.clone()) {
            list.push(pdu);
        } else {
            // Handle the case where the lock couldn't be acquired
            error!("Failed to acquire lock for CRC indication PDU");
        }
    }

    // Attempt to write data to file in a thread-safe manner
    if let Ok(mut list) = Arc::try_unwrap(crc_list) {
        let path = dir_path.join("crc_indications_data.txt");

        match File::create(&path) {
            Ok(mut file) => {
                for pdu in &list {
                    let write_result = writeln!(file, "{:?}, {:?}, {:?}, {:?}", 
                        pdu.rx_ue_information_tag,
                        pdu.rnti,
                        pdu.crc_indication_rel8_tag,
                        pdu.crcflag);

                    if let Err(e) = write_result {
                        error!("Failed to write PDU: {:?}", e);
                    } else {
                        info!("Successfully wrote PDU");
                    }
                }
            },
            Err(e) => {
                error!("Failed to create file: {:?}", e);
            }
        }
    }

    // Return the populated list
    Vec::new()  // Placeholder, in practice this would return the actual populated list
}

fn main() {
    // Initialize logging
    env_logger::Builder::from_default_env()
        .filter(None, LevelFilter::Info)
        .init();

    // Populate the CRC indication list with a sample size
    let _ = populate_crc_indication_list(1000);
}
