// Helper function to calculate checksum
int calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simple checksum example
    return pdu->RNTI + strlen(pdu->RX_UE_INFORMATION_TAG);
}

// Function to initialize log buffer
void init_log_buffer() {
    pthread_mutex_init(&logBuffer.lock, NULL);
}

// Function to add a log entry
void add_log_entry(int index) {
    pthread_mutex_lock(&logBuffer.lock);
    logBuffer.entries[logBuffer.end].index = index;
    logBuffer.entries[logBuffer.end].timestamp = time(NULL);
    logBuffer.end = (logBuffer.end + 1) % LOG_SIZE;
    if (logBuffer.end == logBuffer.start) {
        logBuffer.start = (logBuffer.start + 1) % LOG_SIZE; // Overwrite oldest entry
    }
    pthread_mutex_unlock(&logBuffer.lock);
}

// Function to allocate and initialize structures
NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_structures(int num_ues, int network_condition) {
    if (num_ues > MAX_UES) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    for (int i = 0; i < num_ues; ++i) {
        pthread_mutex_lock(&mutex);

        // Simulate network condition affecting CRCFLAG
        int crcflag = rand() % 2;
        if (network_condition > 5) {
            crcflag = !crcflag; // Example adjustment based on condition
        }

        pdus[i].RNTI = i + 1;
        snprintf(pdus[i].RX_UE_INFORMATION_TAG, sizeof(pdus[i].RX_UE_INFORMATION_TAG), "UE_%d_INFO", i);

        CRC_INDICATION_REL8_TAG tag = {.CRCFLAG = crcflag};
        pthread_mutex_unlock(&mutex);

        // Validate and reinitialize if necessary
        int checksum = calculate_checksum(&pdus[i]);
        ChecksumData expectedChecksum = {.checksum = checksum}; // Example

        if (checksum != expectedChecksum.checksum) {
            pthread_mutex_lock(&mutex);
            snprintf(pdus[i].RX_UE_INFORMATION_TAG, sizeof(pdus[i].RX_UE_INFORMATION_TAG), "UE_%d_INFO_REINIT", i);
            crcflag = rand() % 2; // Reinitialize CRCFLAG
            tag.CRCFLAG = crcflag;
            pthread_mutex_unlock(&mutex);

            add_log_entry(i); // Log failed validation
        }
    }

    return pdus;
}

// Function to free allocated structures
void free_structures(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}

