    env->indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!env->indication_list) {
        log_message("Memory allocation failed");
        return;
    }

    pthread_mutex_init(&env->lock, NULL);
    env->count = max_ues;

    for (size_t i = 0; i < env->count; ++i) {
        unsigned int ue_info_tag = rand(); // Simulate external config
        unsigned int rnti = rand();

        initialize_structure(&env->indication_list[i], ue_info_tag, rnti);

        if (!validate_structure(&env->indication_list[i])) {
            log_message("Validation failed, re-initializing structure");
            initialize_structure(&env->indication_list[i], ue_info_tag, rnti);
        }
    }

    // Periodic validation and logging
    while (1) {
        pthread_mutex_lock(&env->lock);
        for (size_t i = 0; i < env->count; ++i) {
            if (!validate_structure(&env->indication_list[i])) {
                log_message("Validation failed during periodic check, re-initializing structure");
                initialize_structure(&env->indication_list[i], env->indication_list[i].RX_UE_INFORMATION_TAG, env->indication_list[i].RNTI);
            }
        }
        pthread_mutex_unlock(&env->lock);

        sleep(5); // Check periodically
    }
}

void cleanup(TestEnvironment *env) {
    if (env->indication_list) {
        free(env->indication_list);
    }
    pthread_mutex_destroy(&env->lock);
}
