    if (!used) return -1;

    for (size_t i = 0; i < maxCells; ++i) {
        uint16_t cellID;
        do {
            cellID = rand() % (maxID - minID + 1) + minID;
        } while (used[cellID - minID]);

        used[cellID - minID] = 1;
        cellIDs[i] = cellID;
    }

    free(used);
    return 0;
}

int generateRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

NFAPI_CELLINFO_PDU_T* generateCellInfoList(size_t nCells, size_t *count, const char **error) {
