        return NULL;
    }

    NFAPI_CELLINFO_PDU_T *cellInfoArray = calloc(nCells, sizeof(NFAPI_CELLINFO_PDU_T));
    if (!cellInfoArray) {
        *error = "Memory allocation failed for cell info array.";
        return NULL;
    }

    uint16_t cellIDs[MAX_CELLS];
    if (generateUniqueCellIDs(cellIDs, nCells, CELL_ID_MIN, CELL_ID_MAX) != 0) {
        free(cellInfoArray);
        *error = "Failed to generate unique cell IDs.";
        return NULL;
    }

    for (size_t i = 0; i < nCells; ++i) {
        cellInfoArray[i].CELL_ID = cellIDs[i];
        cellInfoArray[i].PCI = (uint8_t)generateRandomInt(0, PCI_RANGE);
        cellInfoArray[i].RSSI = (int8_t)generateRandomInt(RSSI_MIN, RSSI_MAX);
    }

    *count = nCells;
    return cellInfoArray;
}

void exportToJson(const NFAPI_CELLINFO_PDU_T *cellInfoArray, size_t count, const char **error) {
