        fprintf(file, "  { \"CELL_ID\": %u, \"PCI\": %u, \"RSSI\": %d }",
                cellInfoArray[i].CELL_ID, cellInfoArray[i].PCI, cellInfoArray[i].RSSI);
    }
    fprintf(file, "\n]");

    fclose(file);
