    if (!new_node) return;

    new_node->value = value;
    new_node->next = *head_ref;
    *head_ref = new_node;
}

void initializeList(MeasurementList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
