int addMeasurementToDoublyLinkedList(MeasurementList* list, int measurementReportTag, int rrcMeasurementsRel16Tag, float value) {
    if (!validateMeasurementReport(measurementReportTag, rrcMeasurementsRel16Tag)) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    NFAPI_RRC_MEASUREMENT_PDU_T* new_pdu = (NFAPI_RRC_MEASUREMENT_PDU_T*)malloc(sizeof(NFAPI_RRC_MEASUREMENT_PDU_T));
