    addMeasurement(&(new_pdu->results), value);

    if (list->head == NULL) {
        list->head = new_pdu;
        list->tail = new_pdu;
    } else {
        list->tail->next = new_pdu;
        new_pdu->prev = list->tail;
        list->tail = new_pdu;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void freeMeasurementList(MeasurementList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_RRC_MEASUREMENT_PDU_T* current = list->head;
    while (current != NULL) {
        MeasurementResult* result_current = current->results;
        while (result_current != NULL) {
            MeasurementResult* temp_result = result_current;
            result_current = result_current->next;
            free(temp_result);
        }
        NFAPI_RRC_MEASUREMENT_PDU_T* temp_pdu = current;
        current = current->next;
        free(temp_pdu);
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void iterateListForward(MeasurementList* list) {
