NFAPI_RRC_MEASUREMENT_PDU_T* initialize_measurement_list(int num_elements) {
    if (num_elements <= 0) return NULL;

    NFAPI_RRC_MEASUREMENT_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < num_elements; ++i) {
        // Dynamically allocate a new node.
        NFAPI_RRC_MEASUREMENT_PDU_T* new_node = (NFAPI_RRC_MEASUREMENT_PDU_T*)malloc(sizeof(NFAPI_RRC_MEASUREMENT_PDU_T));
        if (!new_node) {
            perror("Failed to allocate memory for a new measurement node");
            continue; // Handle allocation failure gracefully.
        }

        // Populate the node with example data and valid tags.
        new_node->MEASUREMENT_REPORT_TAG = i + 1;
        new_node->RRC_MEASUREMENTS_REL16_TAG = i + 2;

        // Allocate memory for measurement results.
        new_node->measurement_results = (MEASUREMENT_RESULTS_T*)malloc(sizeof(MEASUREMENT_RESULTS_T));
        if (!new_node->measurement_results) {
            perror("Failed to allocate memory for measurement results");
            free(new_node);
            continue; // Handle allocation failure gracefully.
        }

        // Validate the integrity of the measurement report before adding it to the list.
        TAG_STATUS status = validate_measurement_report(new_node);
        if (status == INVALID_TAG) {
            fprintf(stderr, "Invalid measurement report at index %d\n", i);
            free(new_node->measurement_results);
            free(new_node);
            continue;
        }

        new_node->next = NULL;

        // Use a mutex to ensure thread safety while modifying the linked list.
        pthread_mutex_lock(&list_mutex);

        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node;
        }
        tail = new_node;

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

// Function to free all allocated resources for the linked list.
void cleanup_measurement_list(NFAPI_RRC_MEASUREMENT_PDU_T* head) {
    NFAPI_RRC_MEASUREMENT_PDU_T *current, *next;

    pthread_mutex_lock(&list_mutex);

    current = head;
    while (current != NULL) {
        next = current->next;
        free(current->measurement_results);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list_mutex);
}

int main() {
    int num_elements = 10; // Example number of elements to initialize.
    NFAPI_RRC_MEASUREMENT_PDU_T* measurement_list = initialize_measurement_list(num_elements);

    // Use the list for processing...

    cleanup_measurement_list(measurement_list);
    return 0;
}
