} RX_QUALITY_METRICS;

typedef struct LTE_PHY_RX_FRAME_INFO {
    // Assume other fields are defined here
    RX_QUALITY_METRICS quality_metrics;
    // TX_POWER_LEVEL would be here too, but we're not using it in this task
} LTE_PHY_RX_FRAME_INFO;

typedef struct Node {
    LTE_PHY_RX_FRAME_INFO data;
    struct Node* next;
} Node;

// Error codes
#define SUCCESS 0
#define MEMORY_ERROR 1

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_linked_list(Node** head, size_t M, unsigned int seed) {
    pthread_mutex_lock(&list_lock);

    if (!head) {
        pthread_mutex_unlock(&list_lock);
        return MEMORY_ERROR;
    }

    *head = NULL;
    srand(seed); // Initialize the random number generator

    for (size_t i = 0; i < M; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&list_lock);
            return MEMORY_ERROR;
        }

        LTE_PHY_RX_FRAME_INFO* frame_info = &new_node->data;
        frame_info->quality_metrics.SINR = rand() % 100; // Example range
        frame_info->quality_metrics.RSRP = rand() % -110 + (-80); // Example range in dBm
        frame_info->quality_metrics.RSRQ = rand() % 30; // Example range

        new_node->next = *head;
        *head = new_node;

        validate_and_adjust_quality(&frame_info->quality_metrics);
    }

    pthread_mutex_unlock(&list_lock);
    return SUCCESS;
}

void validate_and_adjust_quality(RX_QUALITY_METRICS* metrics) {
    if (metrics->SINR < 0 || metrics->RSRP > -50 || metrics->RSRQ < 0) {
        printf("Adjusting quality metrics due to validation failure.\n");
        // Adjust based on some logic
        metrics->SINR = (metrics->SINR < 0) ? 5 : metrics->SINR;
        metrics->RSRP = (metrics->RSRP > -50) ? -70 : metrics->RSRP;
        metrics->RSRQ = (metrics->RSRQ < 0) ? 1 : metrics->RSRQ;
    }
}

void free_linked_list(Node* head) {
    pthread_mutex_lock(&list_lock);

    Node* current = head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list_lock);
}
