NFAPI_CRC_INDICATION_PDU_T* generate_nfa_crc_pdu_array(size_t count) {
    if (count == 0) return NULL;

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pduArray = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) return NULL;

