        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag value
        pduArray[i].RNTI = rand() % 10000;                 // Example RNTI value

        // Randomly set CRCFLAG in CRC_INDICATION_REL8_TAG
        pduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    return pduArray;
}

unsigned char* compute_md5_hash(const char* data, size_t* hash_size) {
    if (!data || !hash_size) return NULL;

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;

    if (MD5_Init(&ctx) != 1) {
        *hash_size = 0;
        return NULL;
    }

    if (MD5_Update(&ctx, data, strlen(data)) != 1) {
        *hash_size = 0;
        return NULL;
    }

    if (MD5_Final(hash, &ctx) != 1) {
        *hash_size = 0;
        return NULL;
    }

    *hash_size = MD5_DIGEST_LENGTH;
    unsigned char* hash_str = malloc(*hash_size);
    if (!hash_str) {
        *hash_size = 0;
        return NULL;
    }

    memcpy(hash_str, hash, *hash_size);

    return hash_str;
}

