// Global Variables
pthread_mutex_t allocationMutex = PTHREAD_MUTEX_INITIALIZER;
int loggingToFile = 0; // 1 for file, 0 for console

// Function Declarations
void logMessage(const char *message);
NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateNFAPICRCIndicationPduArray(size_t count);

