    NFAPI_CRC_INDICATION_PDU_T* pduArray = allocateAndPopulateNFAPICRCIndicationPduArray(numElements);

    if (pduArray != NULL) {
        // Use the array as needed
    }

    free(pduArray); // Clean up
    return 0;
}

// Implementation

void logMessage(const char *message) {
    FILE *logFile = loggingToFile ? fopen("log.txt", "a") : stdout;
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }
    fprintf(logFile, "%s\n", message);
    if (loggingToFile) {
        fclose(logFile);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateNFAPICRCIndicationPduArray(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *pduArray = NULL;
    double totalTime = 0.0;

    pthread_mutex_lock(&allocationMutex);

    pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduArray == NULL) {
        logMessage("Error: Memory allocation failed.");
        pthread_mutex_unlock(&allocationMutex);
        return NULL;
    }

    clock_t start, end;
    for (size_t i = 0; i < count; ++i) {
        start = clock();

        pduArray[i].rxUeInformationTag.RNTI = rand() % 10000; // Random RNTI
        pduArray[i].rxUeInformationTag.crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Random CRCFLAG

        end = clock();
        totalTime += (double)(end - start) / CLOCKS_PER_SEC;
    }

    pthread_mutex_unlock(&allocationMutex);

    double averageTimePerStructure = totalTime / count;
    char logBuffer[256];
    snprintf(logBuffer, sizeof(logBuffer), "Created %zu structures. Average time per structure: %.5f seconds.",
             count, averageTimePerStructure);
    logMessage(logBuffer);

    return pduArray;
}
