#define MAX_CHANNELS 100
#define RETRY_LIMIT 3

// Mock function to simulate fetching external data (e.g., from a network source)
int fetchExternalData(int *rb_start, int *rb_count) {
    // Simulate potential delays or failures in data retrieval
    if (rand() % 10 < 2) { // 20% chance of failure
        return -1; // Failure to fetch data
    }
    *rb_start = rand() % 50 + 1;
    *rb_count = rand() % 25 + 1;
    return 0; // Success
}

void generate_phy_channel_stats(LTE_PHY_CHANNEL_STATS_T *channels, int num_channels) {
    for (int i = 0; i < num_channels; ++i) {
        channels[i].CHANNEL_ID = i + 1;

        int retries = 0;
        while (retries < RETRY_LIMIT) {
            if (fetchExternalData(&channels[i].RB_START, &channels[i].RB_COUNT) == 0) {
                break;
            }
            retries++;
        }

        channels[i].QUALITY.SNR = (double)(rand() % 100) / 10.0;
        channels[i].QUALITY.RSRP = rand() % 200 - 140; // Typical RSRP range in dBm
        channels[i].QUALITY.RSRQ = rand() % 40 - 20;   // Typical RSRQ range in dB

        if (retries == RETRY_LIMIT) {
            printf("Failed to fetch data for channel ID %d after %d retries.\n", i + 1, RETRY_LIMIT);
        }
    }
}

unsigned char* compute_sha256(const char *data, size_t len, unsigned int *hash_len) {
    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    unsigned char *result;

    if (SHA256_Init(&sha256) != 1 ||
        SHA256_Update(&sha256, data, len) != 1 ||
        SHA256_Final(hash, &sha256) != 1) {
        return NULL; // Handle exceptions gracefully
    }

    *hash_len = SHA256_DIGEST_LENGTH;
    result = (unsigned char*)malloc(*hash_len);
    if (!result) {
        return NULL; // Memory allocation failure
    }
    memcpy(result, hash, *hash_len);

    return result;
}

int main() {
    srand((unsigned int)time(NULL)); // Seed random number generator

    LTE_PHY_CHANNEL_STATS_T channels[MAX_CHANNELS];
    generate_phy_channel_stats(channels, MAX_CHANNELS);

    const char *test_string = "Example data for SHA-256";
    unsigned int hash_len;

    unsigned char *hash = compute_sha256(test_string, strlen(test_string), &hash_len);
    if (hash) {
        printf("SHA-256 Hash: ");
        for (unsigned int i = 0; i < hash_len; ++i) {
            printf("%02x", hash[i]);
        }
        printf("\n");
        free(hash);
    } else {
        fprintf(stderr, "Failed to compute SHA-256 hash.\n");
    }

    return 0;
}
