#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int frequency_band;
    int bandwidth;
    double center_frequency;
    double measurement_duration;
} MeasurementRequest;

typedef struct Node {
    MeasurementRequest request;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RequestList;

void init_request_list(RequestList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

MeasurementRequest create_measurement_request(int frequency_band, int bandwidth,
                                              double center_frequency, double measurement_duration) {
    MeasurementRequest request = {frequency_band, bandwidth, center_frequency, measurement_duration};
    return request;
}

void add_request(RequestList* list, MeasurementRequest request) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new request");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list->lock);
    new_node->request = request;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete_request(RequestList* list, int frequency_band) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->request.frequency_band == frequency_band) {
        list->head = current->next;
        free(current);
        current = list->head;
    }

    while (current != NULL) {
        if (current->request.frequency_band == frequency_band) {
            prev->next = current->next;
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void modify_request(RequestList* list, int frequency_band, MeasurementRequest new_request) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL && current->request.frequency_band != frequency_band) {
        current = current->next;
    }

    if (current != NULL) {
        current->request = new_request;
    } else {
        fprintf(stderr, "Request with frequency band %d not found.\n", frequency_band);
    }

    pthread_mutex_unlock(&list->lock);
}

void free_request_list(RequestList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    RequestList request_list;
    init_request_list(&request_list);

    // Example usage
    MeasurementRequest req1 = create_measurement_request(2, 20, 2412.0, 5.0);
    add_request(&request_list, req1);

    // Modify a request
    MeasurementRequest modified_req = create_measurement_request(2, 20, 2437.0, 10.0);
    modify_request(&request_list, 2, modified_req);

    // Delete a request
    delete_request(&request_list, 2);

    free_request_list(&request_list);

    return 0;
}
