    void (*log_callback)(const char *);
} ConfigStructure;

ConfigStructure* init_config(size_t initial_size, void (*log_callback)(const char *)) {
    ConfigStructure *config = malloc(sizeof(ConfigStructure));
    if (!config) return NULL;

    config->requests = calloc(initial_size, sizeof(MeasurementRequest));
    if (!config->requests) {
        free(config);
        return NULL;
    }

    config->count = 0;
    pthread_mutex_init(&config->lock, NULL);
    config->log_callback = log_callback;

    // Register with external API for firmware updates
    register_firmware_update_listener();

    return config;
}

void add_request(ConfigStructure *config, MeasurementRequest req) {
    if (!config || !config->log_callback) return;

    pthread_mutex_lock(&config->lock);

    if (config->count == 0) {
        // Double the size for initial growth
        config->requests = realloc(config->requests, 2 * sizeof(MeasurementRequest));
    } else if (config->count >= (size_t)(-1) / sizeof(MeasurementRequest)) {
        pthread_mutex_unlock(&config->lock);
        config->log_callback("Memory allocation limit reached");
        return;
    }

    config->requests[config->count++] = req;

    pthread_mutex_unlock(&config->lock);

    // Log the addition
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Added request: Band %d, CenterFreq %.2f", 
             req.frequency_band, req.center_frequency);
    config->log_callback(log_msg);
}

void remove_request(ConfigStructure *config, size_t index) {
    if (!config || !config->log_callback || index >= config->count) return;

    pthread_mutex_lock(&config->lock);

    memmove(&config->requests[index], &config->requests[index + 1],
            (config->count - index - 1) * sizeof(MeasurementRequest));
    config->count--;

    pthread_mutex_unlock(&config->lock);

    // Log the removal
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Removed request at index %zu", index);
    config->log_callback(log_msg);
}

void modify_request(ConfigStructure *config, size_t index, MeasurementRequest req) {
    if (!config || !config->log_callback || index >= config->count) return;

    pthread_mutex_lock(&config->lock);

    config->requests[index] = req;

    pthread_mutex_unlock(&config->lock);

    // Log the modification
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Modified request at index %zu: Band %d, CenterFreq %.2f", 
             index, req.frequency_band, req.center_frequency);
    config->log_callback(log_msg);
}

void cleanup_config(ConfigStructure *config) {
    if (!config) return;

    pthread_mutex_destroy(&config->lock);

    free(config->requests);
    free(config);
}

void register_firmware_update_listener() {
