    printf("Registered firmware update listener.\n");
}

// Example log callback function
void example_log_callback(const char *message) {
    printf("[LOG]: %s\n", message);
}

int main() {
    ConfigStructure *config = init_config(4, example_log_callback);

    if (!config) {
        fprintf(stderr, "Failed to initialize configuration structure.\n");
        return EXIT_FAILURE;
    }

    MeasurementRequest req1 = {2, 20, 2400.5, 10.0, -30};
    add_request(config, req1);

