void destroy_list(CRCList* list);
int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry);
int remove_entry(CRCList* list, int RNTI);
int update_entry(CRCList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_data);
