void initialize_list(CRCList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicates
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == entry.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate entry
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    new_node->data = entry;
    set_random_crcflag(&new_node->data); // Set CRCFLAG randomly
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_entry(CRCList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Entry not found
    }

    if (prev == NULL) { // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int update_entry(CRCList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data = new_data;
            set_random_crcflag(&new_data); // Set CRCFLAG randomly
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* entry) {
    entry->CRCFLAG = rand() % 2; // Randomly sets CRCFLAG to 0 or 1
}
