['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define CRCFLAG_RANGE 2 // CRC flags can be 0 or 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    atomic_int entry_count;
    atomic_size_t memory_usage;
    void (*generate_RX_UE_INFORMATION_TAG)(int*);
    void (*generate_RNTI)(int*);
    int random_seed;
} DynamicList;

void init_dynamic_list(DynamicList* list, void (*gen_tag)(int*), void (*gen_rnti)(int*)) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    atomic_store(&list->entry_count, 0);
    atomic_store(&list->memory_usage, 0);
    list->generate_RX_UE_INFORMATION_TAG = gen_tag;
    list->generate_RNTI = gen_rnti;
}

void cleanup_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int add_entry(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    if (atomic_load(&list->entry_count) >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    list->generate_RX_UE_INFORMATION_TAG(&new_node->data.RX_UE_INFORMATION_TAG);
    list->generate_RNTI(&new_node->data.RNTI);

    int crc_flag = rand_r(&(list->random_seed)) % CRCFLAG_RANGE;
    new_node->data.CRC_INDICATION_REL8_TAG = rand(); // Assuming a valid value is returned
    new_node->data.CRCFLAG = (crc_flag == 0 || crc_flag == 1) ? crc_flag : 0; // Default to 0 if invalid

    new_node->next = list->head;
    list->head = new_node;

    atomic_fetch_add(&list->entry_count, 1);
    atomic_fetch_add(&list->memory_usage, sizeof(Node));

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int remove_entry(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Entry not found
    }

    if (prev == NULL) { // Head node is to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    atomic_fetch_sub(&list->entry_count, 1);
    atomic_fetch_sub(&list->memory_usage, sizeof(Node));

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int update_entry(DynamicList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T updated_data) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Entry not found
    }

    current->data.CRC_INDICATION_REL8_TAG = updated_data.CRC_INDICATION_REL8_TAG;
    int crc_flag = (updated_data.CRCFLAG == 0 || updated_data.CRCFLAG == 1) ? updated_data.CRCFLAG : 0;
    current->data.CRCFLAG = crc_flag;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void log_list_state(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    printf("Current entry count: %d\n", atomic_load(&list->entry_count));
    printf("Current memory usage: %zu bytes\n", atomic_load(&list->memory_usage));

    Node* current = list->head;
    while (current != NULL) {
        printf("Entry - RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void set_random_seed(DynamicList* list, int seed) {
    list->random_seed = seed;
}
```

