} NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU;

// Node structure for the linked list
typedef struct Node {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU data;
    struct Node* next;
} Node;

// Dynamic List structure
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_entry(DynamicList* list, NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU pdu) {
    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

void remove_entry(DynamicList* list, const RX_UE_INFORMATION_TAG* tag) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && memcmp(&current->data.rx_ue_info_tag, tag, sizeof(RX_UE_INFORMATION_TAG)) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->mutex);
}

void update_entry(DynamicList* list, const RX_UE_INFORMATION_TAG* tag, SEQUENCE_ERROR_INFO new_seq_error_info) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current != NULL && memcmp(&current->data.rx_ue_info_tag, tag, sizeof(RX_UE_INFORMATION_TAG)) != 0) {
        current = current->next;
    }

    if (current != NULL) {
        current->data.sequence_error_info = new_seq_error_info;
    }

    pthread_mutex_unlock(&list->mutex);
}

void randomize_sequence_flags(DynamicList* list) {
    srand(time(NULL));
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;
    while (current != NULL) {
        current->data.sequence_error_info.sequence_flag = rand() % 2; // Randomly set to 0 or 1
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Example usage of the list
int main() {
    DynamicList* my_list = create_list();

    NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU pdu1 = { .sequence_error_info = {0} };
    add_entry(my_list, pdu1);

    NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU pdu2 = { .sequence_error_info = {0} };
    add_entry(my_list, pdu2);

    randomize_sequence_flags(my_list);

    SEQUENCE_ERROR_INFO new_seq_err = { 1 };
    update_entry(my_list, &pdu1.rx_ue_info_tag, new_seq_err);

    destroy_list(my_list);
    return 0;
}
