    CURLcode res;
    int retries = 0;

    while (retries <= maxRetries) {
        res = curl_easy_perform(curl);

        if (res == CURLE_OK) {
            return curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
        }

        // Simulate handling network failure
        logMetrics("Network failure encountered", -1);
        retries++;
    }

    return -1;  // Indicate failure after maxRetries
