    int optimalRetries = static_cast<int>(std::ceil(5.0 / (latency + 1e-6))); // Example formula

    struct curl_slist* headers = nullptr;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    std::string primaryServerUrl = "http://primary-server-url";
    std::string secondaryServerUrl = "http://secondary-server-url";

    int statusCode = -1;

    try {
        if (getNetworkLatency() > 0.2) { // Example threshold for high latency
            curl_easy_setopt(curl, CURLOPT_URL, secondaryServerUrl.c_str());
        } else {
            curl_easy_setopt(curl, CURLOPT_URL, primaryServerUrl.c_str());
        }

        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        statusCode = updateStatisticsWithRetries(curl, curl_easy_getinfo(curl, CURLINFO_EFFECTIVE_URL), optimalRetries);

    } catch (const std::exception& e) {
        logMetrics("Exception occurred: " + std::string(e.what()), -1);
    }

    logMetrics("Update completed", statusCode);

    if (headers)
        curl_slist_free_all(headers);

    curl_easy_cleanup(curl);
}

void runPeriodically() {
    while (true) {
        updateUserStatistics();

        std::this_thread::sleep_for(std::chrono::minutes(15));
    }
}

int main() {
