    int db_result = store_summary_statistics(count, sum, average);
    if (db_result != SUCCESS) {
        // Handle database error
        Node *current = head;
        while (current) {
            Node *next = current->next;
            free(current);
            current = next;
        }
        return ERR_DB_CONNECTION;
    }

    // Processed list is now available in 'head'
    return SUCCESS;
