    while (getline(&line, &len, file) != -1) {
        // Remove potential newline characters
        line[strcspn(line, "\r\n")] = '\0';

        if (!validate_data(line)) {
            log_error("Invalid data: %s", line);
            continue;
        }

        process_line(line);
    }

    free(line);
    fclose(file);

    return EXIT_SUCCESS;
}
```']

