    size_t count;
} AllocationResult;

typedef struct {
    pthread_mutex_t lock;
    size_t success_count;
    size_t fail_count;
} AllocationStatistics;

// Assumptions:
// 1. System RAM is known and provided by a custom function `get_total_system_ram()`.
// 2. A random number generator `rand()` is used for setting CRCFLAG.
// 3. The memory management framework provides a thread-safe lock mechanism via `pthread_mutex_t`.

size_t get_total_system_ram();
void* custom_allocate(size_t size);
void custom_deallocate(void* ptr);

// Function to allocate an array of NFAPI_CRC_INDICATION_PDU_T structures
AllocationResult allocate_crc_pdu_array(size_t num_structures) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    AllocationStatistics stats = {pthread_mutex_init(&mutex, NULL), 0, 0};

    if (num_structures <= 0) {
        return (AllocationResult){NULL, 0};
    }

    size_t total_ram = get_total_system_ram();
    const double MAX_MEMORY_USAGE_RATIO = 0.40;
    size_t max_allocatable_memory = total_ram * MAX_MEMORY_USAGE_RATIO;

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t required_memory = num_structures * structure_size;

    pthread_mutex_lock(&mutex);

    if (required_memory > max_allocatable_memory) {
        stats.fail_count++;
        pthread_mutex_unlock(&mutex);
        return (AllocationResult){NULL, 0};
    }

    void* memory_ptr = custom_allocate(required_memory);

    if (!memory_ptr) {
        stats.fail_count++;
        pthread_mutex_unlock(&mutex);
        return (AllocationResult){NULL, 0};
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)memory_ptr;

    for (size_t i = 0; i < num_structures; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 10;
    }

    stats.success_count++;
    pthread_mutex_unlock(&mutex);

    return (AllocationResult){array, num_structures};
}

// Function to validate the integrity of allocated structures
bool validate_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t count) {
