            array[i].CRC_INDICATION_REL8_TAG < 0) {
            return false;
        }
    }

    return true;
}

// Function to provide allocation statistics
void get_allocation_statistics(AllocationStatistics* stats, size_t* success_count, size_t* fail_count) {
    pthread_mutex_lock(&stats->lock);
    *success_count = stats->success_count;
    *fail_count = stats->fail_count;
    pthread_mutex_unlock(&stats->lock);
}

// Example usage of the functions
int main() {
    AllocationResult result = allocate_crc_pdu_array(100);

    if (result.array) {
        printf("Allocation successful, count: %zu\n", result.count);

        if (validate_crc_pdu_array(result.array, result.count)) {
            printf("Validation successful.\n");
        } else {
            printf("Validation failed.\n");
        }

        // Assuming custom_deallocate is the deallocator
