void initialize_configuration(ThreadSafeConfig *config, RadioMeasurementParameters input_requests[], size_t num_input_requests) {
    pthread_mutex_lock(&config->lock);

    config->requests = NULL;
    size_t max_requests = (MAX_MEMORY_USAGE / REQUEST_SIZE < MAX_REQUESTS) ? (MAX_MEMORY_USAGE / REQUEST_SIZE) : MAX_REQUESTS;

    if (num_input_requests > max_requests) {
        LOG_INFO("Too many requests (%zu), limiting to %zu", num_input_requests, max_requests);
        num_input_requests = max_requests;
    }

    config->requests = (RadioMeasurementParameters *)malloc(num_input_requests * REQUEST_SIZE);

    for (size_t i = 0; i < num_input_requests; ++i) {
        if (!is_valid_frequency_band(input_requests[i].frequency_band) || 
            !is_valid_measurement_params(&input_requests[i])) {
            LOG_INFO("Invalid request at index %zu, skipping.", i);
            continue;
        }

        config->requests[i] = input_requests[i];
    }

    log_memory_usage(num_input_requests * REQUEST_SIZE, num_input_requests);

    pthread_mutex_unlock(&config->lock);
}

void free_configuration(ThreadSafeConfig *config) {
    pthread_mutex_lock(&config->lock);

    if (config->requests != NULL) {
        free(config->requests);
        config->requests = NULL;
    }

    pthread_mutex_unlock(&config->lock);
}

