    pthread_mutex_init(&config.lock, NULL);

    initialize_configuration(&config, example_requests, sizeof(example_requests) / REQUEST_SIZE);

    free_configuration(&config);
    pthread_mutex_destroy(&config.lock);

    return 0;
}
