["```javascript
const { promisify } = require('util');
const axios = require('axios');
const timeoutPromise = promisify(setTimeout);

async function logMetrics(details) {
    try {
        await axios.post('https://metrics-service.example.com/log', details);
    } catch (error) {
        console.error('Failed to log metrics:', error);
    }
}

function reduceArray(array, initialValue, reducer, options) {
    return array.reduce((accPromise, currentElement) => {
        return accPromise.then(acc =>
            timeoutPromise(options.perStepTimeout).then(() =>
                promisify(reducer)(acc, currentElement)
            ).catch(err => err)
        );
    }, Promise.resolve(initialValue));
}

async function robustAsyncReduction(inputArrays, initialValue, reducer, options = {}) {
    const { concurrencyLimit = 50, globalTimeout = 30000, perStepTimeout = 500 } = options;

    let activeTasks = [];
    const results = new Array(inputArrays.length);
    const startTime = Date.now();

    for (let i = 0; i < inputArrays.length; i++) {
        if (activeTasks.length >= concurrencyLimit) {
            await Promise.race(activeTasks.map(task => task.catch(() => undefined)));
        }

        const array = inputArrays[i];
        const timeoutPromiseWithFallback = promisify(setTimeout)(globalTimeout, 'Task Timeout').then(() =>
            ({ error: new Error('Global Timeout') })
        );

        const task = reduceArray(array, initialValue, reducer, { perStepTimeout }).then(result => ({
            result,
            status: 'success'
        })).catch(error => ({
            error,
            status: 'failure'
        }));

        activeTasks.push(Promise.race([task, timeoutPromiseWithFallback]).finally(async () => {
            const endTime = Date.now();
            const duration = endTime - startTime;
            await logMetrics({
                timestamp: new Date().toISOString(),
                index: i,
                duration,
                success: !task.error,
                failureReason: task.error ? task.error.message : undefined
            });
        }));

        if (activeTasks.length >= concurrencyLimit) {
            await Promise.race(activeTasks.map(task => task.catch(() => undefined)));
        }
    }

    return Promise.all(activeTasks).then(results => results.filter(result => !result.error));
}

// Test cases

async function testRobustAsyncReduction() {
    const arrays = [
        [1, 2, 3, 4, 5],
        Array.from({ length: 10000 }, (_, i) => i),
        [10, 'a', { b: 20 }, undefined],
        // Add more edge cases as needed
    ];

    const initialValue = 0;
    const reducer = async (acc, val) => typeof val === 'number' ? acc + val : acc;

    try {
        const results = await robustAsyncReduction(arrays, initialValue, reducer, { globalTimeout: 10000 });
        console.log('Results:', results);

        // Add more tests to validate behavior under edge cases
    } catch (error) {
        console.error('Test failed:', error);
    }
}

testRobustAsyncReduction();
