function copyBufferedData(chunks, numBytes) {
    'use strict';

    let totalLength = 0;
    for (let chunk of chunks) {
        totalLength += chunk.length;
    }

    if (totalLength < numBytes) {
        throw new Error('Not enough data in the chunks');
    }

    const resultBuffer = Buffer.allocUnsafe(numBytes);
    let offset = 0;

    for (let chunk of chunks) {
        const bytesToCopy = Math.min(chunk.length, numBytes - offset);
        if (bytesToCopy > 0) {
            chunk.copy(resultBuffer, offset, 0, bytesToCopy);
            offset += bytesToCopy;
        }
        if (offset >= numBytes) break;
    }

    return resultBuffer.slice(0, numBytes);
}
```

