#include <stdio.h>
#include <stdlib.h>
import<stdatomic.h>
#include<string.h>

#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    _Atomic(int) CRCFLAG; // Atomic for thread safety
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For logging errors and reallocating pool
} DynamicPool;

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
    // Add backtrace or more detailed error information here if needed.
}

DynamicPool* create_pool(size_t initial_capacity) {
    DynamicPool *dp = malloc(sizeof(DynamicPool));
    if (!dp) {
        log_error("Failed to allocate memory for DynamicPool");
        return NULL;
    }

    dp->pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dp->pool) {
        log_error("Failed to allocate initial pool memory");
        free(dp);
        return NULL;
    }

    dp->capacity = initial_capacity;
    dp->count = 0;

    pthread_mutex_init(&dp->lock, NULL);

    return dp;
}

void* custom_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_error("Memory allocation failed");
    }
    return ptr;
}

int add_pdu(DynamicPool *dp, int RX_UE_INFORMATION_TAG, int RNTI, unsigned char CRC_INDICATION_REL8_TAG) {
    if (atomic_load_explicit(&dp->count, memory_order_acquire) >= dp->capacity) {
        pthread_mutex_lock(&dp->lock);
        size_t new_capacity = dp->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_pool) {
            pthread_mutex_unlock(&dp->lock);
            return -1; // Allocation failed
        }

        memcpy(new_pool, dp->pool, dp->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(dp->pool);
        dp->pool = new_pool;
        dp->capacity = new_capacity;

        pthread_mutex_unlock(&dp->lock);
    }

    size_t index = atomic_fetch_add_explicit(&dp->count, 1, memory_order_relaxed);

    if (index < dp->capacity) {
        dp->pool[index].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        dp->pool[index].RNTI = RNTI;
        dp->pool[index].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        atomic_store_explicit(&dp->pool[index].CRCFLAG, rand() % 2, memory_order_relaxed);
    } else {
        atomic_fetch_sub_explicit(&dp->count, 1, memory_order_release); // Rollback
        return -1; // Overflow after reallocation
    }

    return 0;
}

void destroy_pool(DynamicPool *dp) {
    if (dp) {
        free(dp->pool);
        pthread_mutex_destroy(&dp->lock);
        free(dp);
    }
}

// Example usage:
int main() {
    DynamicPool *pool = create_pool(10);

    if (!pool) return 1;

    for (int i = 0; i < 20; ++i) { // Simulate adding more than initial capacity
        add_pdu(pool, i, i + 100, i % 256);
    }

    destroy_pool(pool);
    return 0;
}
```

### Key Points:

- **Atomic Operations**: Used for thread-safe counting and accessing elements.
- **Custom Memory Allocator**: `custom_alloc` function is defined to manage memory allocations. It logs errors on allocation failures.
- **Dynamic Pool Management**: The pool can grow dynamically when it reaches capacity, using a mutex lock only for this operation to minimize performance impact.
- **Thread Safety**: Ensures thread safety without traditional locks by leveraging atomic operations and minimal use of mutexes.
- **Error Logging**: Logs memory allocation errors with potential for detailed backtrace or additional information.
- **Extensibility**: The design allows easy addition of new fields in the `NFAPI_CRC_INDICATION_PDU_T` structure without altering core logic.']

