#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to hold TIFF metadata
typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    char compression_type[20];
    double resolution_x; // DPI or DPC
    double resolution_y; // DPI or DPC
    double physical_size_width; // in inches or centimeters
    double physical_size_height; // in inches or centimeters
} TIFFMetadata;

// Define a structure to cache metadata for repeated images
typedef struct {
    char* image_id;
    TIFFMetadata metadata;
} MetadataCache;

#define CACHE_SIZE 1000
static MetadataCache cache[CACHE_SIZE];
static int cache_count = 0;

// Function prototypes
int parseTIFF(const char *filename, TIFFMetadata *metadata, int output_metric);
void calculateResolution(TIFFMetadata *metadata, int output_metric);

// Main function to parse a TIFF image file and extract metadata
int parseTIFF(const char *filename, TIFFMetadata *metadata, int output_metric) {
    // Check for cached metadata first
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(cache[i].image_id, filename) == 0) {
            memcpy(metadata, &cache[i].metadata, sizeof(TIFFMetadata));
            return 1;
        }
    }

    // Open the TIFF file
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return 0;
    }

    // Initialize metadata with default values
    metadata->bits_per_sample = -1;
    metadata->samples_per_pixel = -1;
    strcpy(metadata->compression_type, "");
    metadata->resolution_x = 0.0;
    metadata->resolution_y = 0.0;
    metadata->physical_size_width = 0.0;
    metadata->physical_size_height = 0.0;

    // Parse TIFF header and extract necessary information
    unsigned char header[4];
    fread(header, sizeof(unsigned char), 4, file);

    if (header[0] != 'I' || header[1] != 'I' || header[2] != 'F') {
        fprintf(stderr, "Not a valid TIFF file: %s\n", filename);
        fclose(file);
        return 0;
    }

    // Parse the TIFF directory entries
    unsigned short byte_order = (header[3] << 8) | header[2];
    int little_endian = (byte_order == 0x4949); // Little endian

    if (!little_endian && byte_order != 0x4D4D) { // Big endian
        fprintf(stderr, "Unsupported TIFF byte order\n");
        fclose(file);
        return 0;
    }

    fseek(file, 4, SEEK_SET);
    unsigned int offset_to_first_ifd;
    fread(&offset_to_first_ifd, sizeof(unsigned int), 1, file);

    if (little_endian) {
        offset_to_first_ifd = __builtin_bswap32(offset_to_first_ifd);
    }

    // Read Image File Directory
    fseek(file, offset_to_first_ifd, SEEK_SET);
    unsigned short num_directory_entries;
    fread(&num_directory_entries, sizeof(unsigned short), 1, file);

    if (little_endian) {
        num_directory_entries = __builtin_bswap16(num_directory_entries);
    }

    for (int i = 0; i < num_directory_entries; ++i) {
        unsigned short tag;
        unsigned short type;
        unsigned int count;
        unsigned int value_offset;

        fread(&tag, sizeof(unsigned short), 1, file);
        if (little_endian) {
            tag = __builtin_bswap16(tag);
        }

        fread(&type, sizeof(unsigned short), 1, file);
        if (little_endian) {
            type = __builtin_bswap16(type);
        }

        fread(&count, sizeof(unsigned int), 1, file);
        if (little_endian) {
            count = __builtin_bswap32(count);
        }

        fread(&value_offset, sizeof(unsigned int), 1, file);
        if (little_endian) {
            value_offset = __builtin_bswap32(value_offset);
        }

        switch (tag) {
            case 258: // BitsPerSample
                metadata->bits_per_sample = *(unsigned short *)(file + value_offset - offset_to_first_ifd);
                if (little_endian) {
                    metadata->bits_per_sample = __builtin_bswap16(metadata->bits_per_sample);
                }
                break;
            case 277: // SamplesPerPixel
                metadata->samples_per_pixel = *(unsigned short *)(file + value_offset - offset_to_first_ifd);
                if (little_endian) {
                    metadata->samples_per_pixel = __builtin_bswap16(metadata->samples_per_pixel);
                }
                break;
            case 259: // Compression
                strcpy(metadata->compression_type, "No compression");
                if (count == 4) {
                    unsigned short comp_method = *(unsigned short *)(file + value_offset - offset_to_first_ifd);
                    if (little_endian) {
                        comp_method = __builtin_bswap16(comp_method);
                    }
                    switch (comp_method) {
                        case 1: strcpy(metadata->compression_type, "PackBits"); break;
                        case 2: strcpy(metadata->compression_type, "CCITT Group 3"); break;
                        case 32773: strcpy(metadata->compression_type, "Deflate/ZIP"); break;
                        default: fprintf(stderr, "Unsupported compression type\n");
                    }
                }
                break;
            case 282: // XResolution
                metadata->resolution_x = *(unsigned int *)(file + value_offset - offset_to_first_ifd) / 
                                         *(unsigned int *)(file + value_offset - offset_to_first_ifd + 4);
                if (little_endian) {
                    unsigned int num = __builtin_bswap32(*(unsigned int *)(file + value_offset - offset_to_first_ifd));
                    unsigned int denom = __builtin_bswap32(*(unsigned int *)(file + value_offset - offset_to_first_ifd + 4));
                    metadata->resolution_x = num / (double)denom;
                }
                break;
            case 283: // YResolution
                metadata->resolution_y = *(unsigned int *)(file + value_offset - offset_to_first_ifd) / 
                                         *(unsigned int *)(file + value_offset - offset_to_first_ifd + 4);
                if (little_endian) {
                    unsigned int num = __builtin_bswap32(*(unsigned int *)(file + value_offset - offset_to_first_ifd));
                    unsigned int denom = __builtin_bswap32(*(unsigned int *)(file + value_offset - offset_to_first_ifd + 4));
                    metadata->resolution_y = num / (double)denom;
                }
                break;
            case 254: // ImageWidth
                metadata->physical_size_width = *(unsigned int *)(file + value_offset - offset_to_first_ifd);
                if (little_endian) {
                    metadata->physical_size_width = __builtin_bswap32(metadata->physical_size_width);
                }
                break;
            case 255: // ImageLength
                metadata->physical_size_height = *(unsigned int *)(file + value_offset - offset_to_first_ifd);
                if (little_endian) {
                    metadata->physical_size_height = __builtin_bswap32(metadata->physical_size_height);
                }
                break;
        }
    }

    fclose(file);

    // Calculate effective resolution
    calculateResolution(metadata, output_metric);

    // Cache the metadata for future use
    if (cache_count < CACHE_SIZE) {
        cache[cache_count].image_id = strdup(filename);
        memcpy(&cache[cache_count++].metadata, metadata, sizeof(TIFFMetadata));
    }

    return 1;
}

// Function to calculate effective resolution based on physical size and pixel dimensions
void calculateResolution(TIFFMetadata *metadata, int output_metric) {
    if (metadata->physical_size_width == 0 || metadata->physical_size_height == 0) {
        fprintf(stderr, "Physical size not available for accurate resolution calculation\n");
        return;
    }

    double dpi_x = metadata->resolution_x;
    double dpi_y = metadata->resolution_y;

    // Convert inches to centimeters if needed
    if (output_metric) {
        dpi_x *= 2.54;
        dpi_y *= 2.54;
        metadata->physical_size_width /= 2.54;
        metadata->physical_size_height /= 2.54;
    }

    // Calculate effective resolution
    double effective_res_x = dpi_x * (metadata->physical_size_width / dpi_x);
    double effective_res_y = dpi_y * (metadata->physical_size_height / dpi_y);

    printf("Effective Resolution: %.2f DPI X, %.2f DPI Y\n", effective_res_x, effective_res_y);
}

// Example usage
int main() {
    TIFFMetadata metadata;
    if (parseTIFF("example.tiff", &metadata, 1)) { // 1 for metric output
        printf("Bits Per Sample: %d\n", metadata.bits_per_sample);
        printf("Samples Per Pixel: %d\n", metadata.samples_per_pixel);
        printf("Compression Type: %s\n", metadata.compression_type);
    }
    return 0;
}
