['Below is a C code implementation that addresses your task requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_ELEMENTS 2048
#define KEY_SIZE 16

typedef struct {
    unsigned char *pdcpsdu;
    size_t sdusize;
    int sequence_number;
    unsigned char integrity_protection_tag[KEY_SIZE];
} PDCP_PDU;

typedef struct {
    PDCP_PDU pdcp_array[MAX_ELEMENTS];
    atomic_int count; // Atomic counter for thread safety
    pthread_mutex_t mutex; // Mutex for operations that require locks
} PDPC_Manager;

// Function to generate a random integrity key
void generate_random_key(unsigned char *key, size_t length) {
    if (key != NULL && length > 0) {
        srand((unsigned int)time(NULL));
        for (size_t i = 0; i < length; ++i) {
            key[i] = rand() % 256;
        }
    }
}

// Initialize PDPC_Manager
int init_pdcp_manager(PDPC_Manager *manager) {
    if (!manager) return -1;

    atomic_init(&manager->count, 0);
    pthread_mutex_init(&manager->mutex, NULL);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        manager->pdcp_array[i].pdcpsdu = NULL;
        manager->pdcp_array[i].sdusize = 0;
        manager->pdcp_array[i].sequence_number = -1;
    }

    return 0;
}

// Add a PDCP_PDU to the manager
int add_pdu(PDPC_Manager *manager, unsigned char *pdcpsdu, size_t sdusize) {
    if (!manager || !pdcpsdu || sdusize == 0)
        return -1;

    int index = atomic_fetch_add(&manager->count, 1);
    if (index >= MAX_ELEMENTS) {
        atomic_fetch_sub(&manager->count, 1);
        return -2; // Out of space
    }

    pthread_mutex_lock(&manager->mutex);

    manager->pdcp_array[index].pdcpsdu = malloc(sdusize);
    if (!manager->pdcp_array[index].pdcpsdu) {
        atomic_fetch_sub(&manager->count, 1);
        pthread_mutex_unlock(&manager->mutex);
        return -3; // Memory allocation failure
    }
    memcpy(manager->pdcp_array[index].pdcpsdu, pdcpsdu, sdusize);
    manager->pdcp_array[index].sdusize = sdusize;
    manager->pdcp_array[index].sequence_number = index;  // Example sequence number assignment

    generate_random_key(manager->pdcp_array[index].integrity_protection_tag, KEY_SIZE);

    pthread_mutex_unlock(&manager->mutex);
    return index; // Return the index where the PDU was added
}

// Remove a PDCP_PDU from the manager by index
void remove_pdu(PDPC_Manager *manager, int index) {
    if (!manager || index < 0 || index >= MAX_ELEMENTS)
        return;

    pthread_mutex_lock(&manager->mutex);

    free(manager->pdcp_array[index].pdcpsdu);
    manager->pdcp_array[index].pdcpsdu = NULL;
    manager->pdcp_array[index].sdusize = 0;
    manager->pdcp_array[index].sequence_number = -1;

    pthread_mutex_unlock(&manager->mutex);

    atomic_fetch_sub(&manager->count, 1); // Decrement count atomically
}

// Monitor and log the current state of PDPC_Manager
void monitor_pdcp_manager(PDPC_Manager *manager) {
    if (!manager)
        return;

    printf("Current PDCP count: %d\n", atomic_load(&manager->count));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (manager->pdcp_array[i].pdcpsdu != NULL) {
            printf("Index %d - Sequence Number: %d, Size: %zu\n",
                   i,
                   manager->pdcp_array[i].sequence_number,
                   manager->pdcp_array[i].sdusize);
        }
    }
}

// Cleanup PDPC_Manager
void cleanup_pdcp_manager(PDPC_Manager *manager) {
    if (!manager)
        return;

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (manager->pdcp_array[i].pdcpsdu != NULL) {
            free(manager->pdcp_array[i].pdcpsdu);
        }
    }

    pthread_mutex_destroy(&manager->mutex);
}

// Main function to demonstrate usage
int main() {
    PDPC_Manager manager;

    if (init_pdcp_manager(&manager) == -1) {
        fprintf(stderr, "Failed to initialize PDPC Manager\n");
        return EXIT_FAILURE;
    }

    unsigned char pdu_data[] = {0x01, 0x02, 0x03}; // Example PDCP SDU
