#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define the structure for network packet header
typedef struct {
    uint8_t protocol_version;
    uint32_t src_ip;  // IP addresses as unsigned integers
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t checksum_flag;
    size_t payload_size;
} PacketHeader;

// Define the structure for the collection item
typedef struct PacketItem {
    PacketHeader header;
    struct PacketItem *next;
} PacketItem;

// Define the scalable, thread-safe packet header collection
typedef struct {
    PacketItem *head;
    pthread_mutex_t lock;
    size_t processed_packets;
} PacketCollection;

// Function to initialize the packet collection
void initPacketCollection(PacketCollection *collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->processed_packets = 0;
}

// External logging function stub (replace with actual implementation)
void logPacket(const PacketHeader *header) {
    // Logging logic here
    printf("Logging packet: %u.%u.%u.%u -> %u.%u.%u.%u\n",
           (header->src_ip >> 24) & 0xFF, (header->src_ip >> 16) & 0xFF,
           (header->src_ip >> 8) & 0xFF, header->src_ip & 0xFF,
           (header->dst_ip >> 24) & 0xFF, (header->dst_ip >> 16) & 0xFF,
           (header->dst_ip >> 8) & 0xFF, header->dst_ip & 0xFF);
}

// Function to add a packet header
void addPacketHeader(PacketCollection *collection, const PacketHeader *header) {
    pthread_mutex_lock(&collection->lock);

    // Allocate memory for the new item and copy header data
    PacketItem *new_item = (PacketItem *)malloc(sizeof(PacketItem));
    if (!new_item) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    new_item->header = *header;
    new_item->next = collection->head;

    // Insert the new item at the beginning of the list
    collection->head = new_item;

    // Update processed packets count and log the packet
    collection->processed_packets++;
    logPacket(header);

    pthread_mutex_unlock(&collection->lock);
}

// Function to update a packet header (assuming unique IP + port as key)
void updatePacketHeader(PacketCollection *collection, const PacketHeader *header) {
    pthread_mutex_lock(&collection->lock);

    // Iterate through the list to find and update the matching item
    for (PacketItem *item = collection->head; item != NULL; item = item->next) {
        if (item->header.src_ip == header->src_ip &&
            item->header.dst_ip == header->dst_ip &&
            item->header.src_port == header->src_port &&
            item->header.dst_port == header->dst_port) {
            item->header = *header;
            logPacket(header);
            break;  // Update done, exit loop
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to iterate over packet headers and check integrity
void iterateAndCheckIntegrity(PacketCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (PacketItem *item = collection->head; item != NULL; item = item->next) {
        // Example integrity check: ensure checksum flag is set if payload size > 0
        if (item->header.payload_size > 0 && !item->header.checksum_flag) {
            fprintf(stderr, "Integrity issue detected for packet with src IP %u.%u.%u.%u\n",
                    (item->header.src_ip >> 24) & 0xFF,
                    (item->header.src_ip >> 16) & 0xFF,
                    (item->header.src_ip >> 8) & 0xFF, item->header.src_ip & 0xFF);
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to free the collection
void destroyPacketCollection(PacketCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    PacketItem *current = collection->head;
    while (current != NULL) {
        PacketItem *next = current->next;
        free(current);
        current = next;
    }

    collection->head = NULL;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    // Example usage
    PacketCollection collection;
    initPacketCollection(&collection);

    PacketHeader header1 = { 1, 0xC0A80001, 0xC0A80002, 12345, 80, 1, 1024 };
    addPacketHeader(&collection, &header1);

    iterateAndCheckIntegrity(&collection);

    destroyPacketCollection(&collection);
    return 0;
}
