SharedResourceList resource_list = { .data = {0}, .mutex = PTHREAD_MUTEX_INITIALIZER, .count = 0 };

void initialize_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    memset(structure, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int add_structure(SharedResourceList *list, NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_NUM_STRUCTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Resource exhausted
    }

    initialize_structure(structure);

    list->data[list->count++] = structure;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int remove_structure(SharedResourceList *list, int index) {
    pthread_mutex_lock(&list->mutex);

    if (index < 0 || index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index
    }

    free(list->data[index]);
    for (size_t i = index; i < list->count - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }

    list->data[--list->count] = NULL;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void cleanup_resource_list(SharedResourceList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
