CRCDynamicArray* create_crc_array() {
    CRCDynamicArray* array = (CRCDynamicArray*)malloc(sizeof(CRCDynamicArray));
    if (!array) return NULL;

    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_crc_array(CRCDynamicArray* array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

