        pdu.RX_UE_INFORMATION_TAG = rx_ue_tag;
        pdu.RNTI = rnti;
        pdu.CRCFLAG = generate_random_crcflag();

        array->data[array->count++] = pdu;
    }

    pthread_mutex_unlock(&array->lock);
}

void remove_pdu(CRCDynamicArray* array, int index) {
    if (index < 0 || index >= array->count) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = index; i < array->count - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }

    --array->count;

    pthread_mutex_unlock(&array->lock);
}

void handle_message_queue(CRCDynamicArray* array, int (*message_fetcher)(int*, int*)) {
