CRC_Container container = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void log_event(const char* message) {
    printf("%s\n", message); // Simplified logging for demonstration
}

int allocate_crc_array(int N, int priority_level) {
    pthread_mutex_lock(&container.mutex);

    if (N > MAX_SIZE) {
        log_event("Error: Requested size exceeds maximum limit.");
        pthread_mutex_unlock(&container.mutex);
        return -1;
    }

    if (container.size < N) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(container.data, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_event("Error: Memory allocation failed.");
            pthread_mutex_unlock(&container.mutex);
            return -1;
        }
        container.data = new_data;

        for (int i = container.size; i < N; ++i) {
            // Initialize new structures
            container.data[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Random tag
            container.data[i].RNTI = rand() % 1000 + 1; // Random RNTI
            container.data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
            container.success_count[i] = 0; // Initialize success count
        }
    }

    log_event("Array allocated/realized successfully.");
    container.size = N;

    pthread_mutex_unlock(&container.mutex);
    return 0;
}

void reset_crc_flags() {
    pthread_mutex_lock(&container.mutex);

    for (int i = 0; i < container.size; ++i) {
        container.data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
    }

    log_event("CRC flags reset successfully.");

    pthread_mutex_unlock(&container.mutex);
}

void delete_structure_by_rnti(int RNTI) {
    pthread_mutex_lock(&container.mutex);

    for (int i = 0; i < container.size; ++i) {
        if (container.data[i].RNTI == RNTI) {
            memmove(&container.data[i], &container.data[i + 1], 
                    (container.size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            for (int j = i; j < container.size - 1; ++j) {
                container.success_count[j] = container.success_count[j + 1];
            }
            container.size--;
            log_event("Structure deleted successfully.");
            break;
        }
    }

    pthread_mutex_unlock(&container.mutex);
}

void increment_success_count(int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&container.mutex);

    for (int i = 0; i < container.size; ++i) {
        if (container.data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            container.success_count[i]++;
            log_event("Success count incremented.");
            break;
        }
    }

    pthread_mutex_unlock(&container.mutex);
}

// Example usage
