    allocate_crc_array(10, 1); // Allocate initial array with priority level

    // Simulate a successful CRC check
    increment_success_count(container.data[0].RX_UE_INFORMATION_TAG);

    // Reset all CRC flags
    reset_crc_flags();

    // Delete specific structure by RNTI
    if (container.size > 0) {
        delete_structure_by_rnti(container.data[0].RNTI);
    }

