#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_HISTORY 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Assuming a single byte for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HistoryEntry {
    size_t id;
    NFAPI_CRC_INDICATION_PDU_T *data;
    time_t timestamp;
    struct HistoryEntry *next;
} HistoryEntry;

typedef struct {
    HistoryEntry *head;
    pthread_mutex_t lock;
} HistoryList;

HistoryList history = {NULL, PTHREAD_MUTEX_INITIALIZER};

void log_event(const char *event) {
    // Placeholder for logging integration
    printf("%s\n", event);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    if (count <= 0) {
        log_event("Error: Invalid allocation size.");
        return NULL;
    }

    pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!pdu_list) {
        log_event("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand();
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand();
        pdu_list[i].CRCFLAG = rand() % 256;
    }

    log_event("Memory allocated successfully.");
    return pdu_list;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list) {
    if (pdu_list) {
        free(pdu_list);
        log_event("Memory deallocated successfully.");
    }
}

HistoryEntry* create_history_entry(size_t id, NFAPI_CRC_INDICATION_PDU_T *data) {
    HistoryEntry *entry = malloc(sizeof(HistoryEntry));
    if (!entry) {
        log_event("Failed to allocate history entry.");
        return NULL;
    }

    entry->id = id;
    entry->data = data;
    entry->timestamp = time(NULL);
    entry->next = NULL;

    return entry;
}

void add_to_history(size_t id, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&history.lock);

    if (history.head == NULL || history.head->id != id) {
        HistoryEntry *new_entry = create_history_entry(id, data);
        if (!new_entry) return;

        new_entry->next = history.head;
        history.head = new_entry;
    }

    pthread_mutex_unlock(&history.lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_history(size_t id) {
    pthread_mutex_lock(&history.lock);

    HistoryEntry *current = history.head;
    while (current) {
        if (current->id == id) {
            pthread_mutex_unlock(&history.lock);
            return current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&history.lock);
    log_event("History entry not found.");
    return NULL;
}

void clear_old_history() {
    time_t now = time(NULL);
    pthread_mutex_lock(&history.lock);

    HistoryEntry *current = history.head;
    HistoryEntry *prev = NULL;

    while (current) {
        if (difftime(now, current->timestamp) > 60) { // Clear entries older than 60 seconds
            HistoryEntry *to_delete = current;
            if (prev == NULL) {
                history.head = current->next;
            } else {
                prev->next = current->next;
            }
            free(to_delete->data);
            free(to_delete);
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&history.lock);
}

int main() {
    size_t N = 10; // Example user input
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = allocate_pdu(N);

    if (pdu_list) {
        size_t id = rand(); // Generate a unique identifier for the history
        add_to_history(id, pdu_list);

        // Retrieve from history
        NFAPI_CRC_INDICATION_PDU_T *retrieved_pdu = get_from_history(id);
        if (retrieved_pdu) {
            printf("Retrieved PDU with ID: %zu\n", id);
        }

        // Periodically clear old history entries
        clear_old_history();

        free_pdu(pdu_list);
    }

    return 0;
}
