#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the network interface statistics structure
typedef struct {
    unsigned long packet_count;
    unsigned long byte_count;
    float error_rate;
    float latency_ms;
} NetworkStats;

// Function prototypes
void initialize_and_populate_stats(const char *filename, NetworkStats **stats_array, size_t *count,
                                   unsigned long min_packet_count, unsigned long min_byte_count);
static void parse_trace_file(const char *filename, NetworkStats **stats_array, size_t *count);
static int should_include_entry(unsigned long packet_count, unsigned long byte_count,
                                unsigned long min_packet_count, unsigned long min_byte_count);

// Mutex for thread-safe operations (if needed in future extensions)
pthread_mutex_t stats_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_and_populate_stats(const char *filename, NetworkStats **stats_array, size_t *count,
                                   unsigned long min_packet_count, unsigned long min_byte_count) {
    // Initialize the mutex if you plan to use thread-safe operations
    pthread_mutex_init(&stats_mutex, NULL);

    // Parse the trace file and populate stats_array
    parse_trace_file(filename, stats_array, count);

    // Free resources used by mutex (if initialized)
    pthread_mutex_destroy(&stats_mutex);
}

static void parse_trace_file(const char *filename, NetworkStats **stats_array, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Temporary storage for reading stats
    NetworkStats temp_stats;
    size_t capacity = 10;
    *stats_array = malloc(capacity * sizeof(NetworkStats));
    if (!*stats_array) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return;
    }

    size_t current_size = 0;

    while (fscanf(file, "%lu %lu %f %f", &temp_stats.packet_count,
                  &temp_stats.byte_count, &temp_stats.error_rate,
                  &temp_stats.latency_ms) == 4) {

        if (should_include_entry(temp_stats.packet_count, temp_stats.byte_count,
                                 min_packet_count, min_byte_count)) {
            if (current_size >= capacity) {
                capacity *= 2;
                *stats_array = realloc(*stats_array, capacity * sizeof(NetworkStats));
                if (!*stats_array) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    fclose(file);
                    return;
                }
            }

            (*stats_array)[current_size++] = temp_stats;
        }
    }

    *count = current_size;

    fclose(file);
}

static int should_include_entry(unsigned long packet_count, unsigned long byte_count,
                                unsigned long min_packet_count, unsigned long min_byte_count) {
    return (packet_count >= min_packet_count && byte_count >= min_byte_count);
}
```

### Explanation

1. **Data Structure**: Defined `NetworkStats` to hold statistics for each network interface entry.

2. **File Parsing and Error Handling**: Implemented file reading logic within `parse_trace_file`, gracefully handling errors with `perror`.

3. **Dynamic Memory Management**: Used dynamic arrays, doubling the size when needed, ensuring efficient memory usage.

4. **Filtering Mechanism**: Implemented in `should_include_entry` to discard entries not meeting thresholds.

5. **Concurrency Considerations**: Introduced a mutex for potential future thread-safety needs without complicating initial implementation.

6. **Configuration Flexibility**: Thresholds are passed as parameters, allowing easy configuration changes.

7. **Modularity and Documentation**: Modularized functions (`initialize_and_populate_stats`, `parse_trace_file`, `should_include_entry`) to maintain clarity and facilitate future updates.']

