    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    struct HistoryEntry* next;
} HistoryEntry;

typedef struct {
    pthread_mutex_t mutex;
    HistoryEntry* head;
    size_t count;
} CRCHistory;

// Thread-safe history manager
CRCHistory crc_history = {PTHREAD_MUTEX_INITIALIZER, NULL, 0};

void log_event(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(size_t n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        log_event("Memory allocation failed for PDU list.");
        return NULL;
    }

    pthread_mutex_lock(&crc_history.mutex);
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < n; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 10000; // Example tag
        pdu_list[i].RNTI = rand() % 500;                     // Example RNTI
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 10;   // Example CRC tag
        pdu_list[i].CRCFLAG = (rand() % 2) == 0;
    }

    log_event("PDU list allocated and initialized.");
    pthread_mutex_unlock(&crc_history.mutex);

    return pdu_list;
}

void add_to_history(const char* unique_id, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    pthread_mutex_lock(&crc_history.mutex);

    HistoryEntry* entry = (HistoryEntry*)malloc(sizeof(HistoryEntry));
    if (!entry) {
        log_event("Memory allocation failed for history entry.");
        pthread_mutex_unlock(&crc_history.mutex);
        return;
    }

    entry->unique_id = strdup(unique_id);
    entry->pdu = pdu;
    entry->timestamp = time(NULL);
    entry->next = crc_history.head;
    crc_history.head = entry;
    crc_history.count++;

    if (crc_history.count > MAX_HISTORY_SIZE) {
        HistoryEntry* to_remove = crc_history.head;
        crc_history.head = crc_history.head->next;
        free(to_remove->unique_id);
        free(to_remove);
        crc_history.count--;
    }

    log_event("Added entry to history.");
    pthread_mutex_unlock(&crc_history.mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_history(const char* unique_id) {
    pthread_mutex_lock(&crc_history.mutex);

    for (HistoryEntry* current = crc_history.head; current != NULL; current = current->next) {
        if (strcmp(current->unique_id, unique_id) == 0) {
            log_event("Retrieved entry from history.");
            pthread_mutex_unlock(&crc_history.mutex);
            return &(current->pdu);
        }
    }

    log_event("Entry not found in history.");
    pthread_mutex_unlock(&crc_history.mutex);
    return NULL;
}

