#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_RETRIES 3
#define INITIAL_BATCH_SIZE 10
#define MAX_PDUS_PER_BATCH 100
#define CACHE_SIZE 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *head;
    pthread_mutex_t lock;
} PDCache;

PDCache cache = {.head = NULL, .lock = PTHREAD_MUTEX_INITIALIZER};
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void init_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        CacheNode *node = malloc(sizeof(CacheNode));
        if (!node) break;
        node->next = cache.head;
        cache.head = node;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    int retries = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    while (retries < MAX_RETRIES) {
        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu) return pdu;

        perror("Memory allocation failed");
        sleep(1);  // Delay before retrying
        retries++;
    }

    fprintf(stderr, "Failed to allocate memory after %d attempts\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        free(pdu);
    }
}

void process_pdus(int batch_size);

void async_logging(int crc_flag, int pdu_id) {
    // Simulate asynchronous logging to an external service
    printf("Asynchronously logging CRCFLAG %d for PDU ID %d\n", crc_flag, pdu_id);
}

void manage_list(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    int batch_size = INITIAL_BATCH_SIZE;
    int processed_pdus = 0;

    while (processed_pdus < count) {
        pthread_mutex_lock(&globalLock);

        if ((count - processed_pdus) > MAX_PDUS_PER_BATCH) {
            batch_size = MAX_PDUS_PER_BATCH;
        } else {
            batch_size = count - processed_pdus;
        }

        pthread_mutex_unlock(&globalLock);

        process_pdus(batch_size);

        // Simulate system load adjustment
        if (rand() % 2 == 0) { 
            batch_size += rand() % 5;  // Increase batch size slightly
        } else {
            batch_size = batch_size > INITIAL_BATCH_SIZE ? batch_size - rand() % 3 : batch_size;
        }

        processed_pdus += batch_size;
    }
}

void process_pdus(int batch_size) {
    pthread_t threads[batch_size];
    NFAPI_CRC_INDICATION_PDU_T *pdus[batch_size];

    for (int i = 0; i < batch_size; ++i) {
        pdus[i] = allocate_pdu();

        srand(time(NULL) + i); // Seed random number generator
        pdus[i]->RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i]->RNTI = rand() % 1000;
        pdus[i]->CRC_INDICATION_REL8_TAG = rand() % 50;
        pdus[i]->CRCFLAG = rand() & 1;

        pthread_create(&threads[i], NULL, (void *(*)(void *))log_pdu_async, pdus[i]);
    }

    for (int i = 0; i < batch_size; ++i) {
        pthread_join(threads[i], NULL);
        free_pdu(pdus[i]);
    }
}

void* log_pdu_async(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) arg;

    // Simulate logging with minimal delay
    async_logging(pdu->CRCFLAG, pdu->RX_UE_INFORMATION_TAG);

    pthread_mutex_lock(&cache.lock);
    CacheNode *new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        perror("Cache node allocation failed");
        pthread_mutex_unlock(&cache.lock);
        return NULL;
    }

    new_node->pdu = pdu;
    new_node->next = cache.head;
    cache.head = new_node;

    pthread_mutex_unlock(&cache.lock);

    return NULL;
}

int main() {
    init_cache();

    size_t num_pdus = 500; // Example total PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdus[num_pdus];

    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i] = allocate_pdu();
    }

    manage_list(pdus, num_pdus);

    // Cleanup remaining cache nodes
    while (cache.head != NULL) {
        CacheNode *temp = cache.head;
        cache.head = cache.head->next;
        free(temp);
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        free_pdu(pdus[i]);
    }

    return 0;
}
```

