#include <stdbool.h>

#define MAX_BATCH_SIZE 100

typedef struct {
    int LAI;        // Location Area Identity
    int RNTI;       // Radio Network Temporary Identifier
    int PDCP_SN;    // Protocol Data Unit Sequence Number
    bool ACK_FLAG;
} LTE_PDCP_PDU_T;

// Thread-safe memory pool for managing dynamically allocated structures
typedef struct {
    pthread_mutex_t lock;
    LTE_PDCP_PDU_T *pool[MAX_BATCH_SIZE];
    size_t count;
} MemoryPool;

MemoryPool *init_memory_pool() {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    pthread_mutex_init(&mp->lock, NULL);
    mp->count = 0;
    for (int i = 0; i < MAX_BATCH_SIZE; ++i) {
        mp->pool[i] = NULL;
    }
    return mp;
}

void free_memory_pool(MemoryPool *mp) {
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

LTE_PDCP_PDU_T* allocate_pdu(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->count < MAX_BATCH_SIZE) {
        LTE_PDCP_PDU_T *pdu = malloc(sizeof(LTE_PDCP_PDU_T));
        mp->pool[mp->count++] = pdu;
        pthread_mutex_unlock(&mp->lock);
        return pdu;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // No available memory
}

void free_pdu(MemoryPool *mp, LTE_PDCP_PDU_T *pdu) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->count; ++i) {
        if (mp->pool[i] == pdu) {
            free(mp->pool[i]);
            memmove(&mp->pool[i], &mp->pool[i + 1], sizeof(LTE_PDCP_PDU_T*) * (mp->count - i - 1));
            --mp->count;
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

bool is_unique_pdcpsn(MemoryPool *mp, int pdcpsn) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->count; ++i) {
        if (mp->pool[i] && mp->pool[i]->PDCP_SN == pdcpsn) {
            pthread_mutex_unlock(&mp->lock);
            return false;
        }
    }
    pthread_mutex_unlock(&mp->lock);
    return true;
}

void fetch_external_data(LTE_PDCP_PDU_T *pdu) {
    // Simulate fetching data from an external source with random values
    pdu->LAI = rand() % 1000;       // Random LAI
    pdu->RNTI = rand() % 5000;      // Random RNTI
}

void populate_pdu_list(MemoryPool *mp, LTE_PDCP_PDU_T **list, size_t *size, int batch_size) {
    pthread_t threads[batch_size];
    int thread_args[batch_size];

    for (int i = 0; i < batch_size; ++i) {
        if ((list[i] = allocate_pdu(mp)) == NULL) {
            fprintf(stderr, "Failed to allocate memory for PDU\n");
            break;
        }

        // Fetch external data
        fetch_external_data(list[i]);

        // Generate unique PDCP_SN
        do {
            list[i]->PDCP_SN = rand() % 4096; // Random sequence number
        } while (!is_unique_pdcpsn(mp, list[i]->PDCP_SN));

        // Randomly set ACK_FLAG
        list[i]->ACK_FLAG = rand() % 2 == 0;

        thread_args[i] = i;
        pthread_create(&threads[i], NULL, (void *(*)(void *))populate_pdu_list_thread, &thread_args[i]);
    }

    for (int i = 0; i < batch_size; ++i) {
        if (list[i]) {
            pthread_join(threads[i], NULL);
        }
    }

    *size = batch_size;
}

void* populate_pdu_list_thread(void *arg) {
    int index = *(int *)arg;
    sleep(rand() % 3); // Simulate network latency
    printf("Thread %d completed PDU population.\n", index);
    return NULL;
}

int main() {
    srand(time(NULL));

    MemoryPool *mp = init_memory_pool();
    LTE_PDCP_PDU_T *pdu_list[MAX_BATCH_SIZE];
    size_t pdu_size;

    populate_pdu_list(mp, pdu_list, &pdu_size, MAX_BATCH_SIZE);

    for (size_t i = 0; i < pdu_size; ++i) {
        printf("PDU %zu: LAI=%d, RNTI=%d, PDCP_SN=%d, ACK_FLAG=%s\n",
               i, pdu_list[i]->LAI, pdu_list[i]->RNTI,
               pdu_list[i]->PDCP_SN, pdu_list[i]->ACK_FLAG ? "true" : "false");
        free_pdu(mp, pdu_list[i]);
    }

    free_memory_pool(mp);
    return 0;
}
