    memset(&pdu->crc_indication_rel8_tag, 0, sizeof(pdu->crc_indication_rel8_tag));

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* add_crc_pdu(void) {
    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < MAX_STRUCTS; ++i) {
        if (manager.structs[i] == NULL) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pdu == NULL) {
                pthread_mutex_unlock(&manager.lock);
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }

            int init_result = initialize_structure(pdu);
            if (init_result != 0) {
                free(pdu);
                pthread_mutex_unlock(&manager.lock);
                return NULL;
            }

            manager.structs[i] = pdu;
            pthread_mutex_unlock(&manager.lock);
            printf("Added PDU with sequence number %u at timestamp %ld\n", pdu->sequence_number, pdu->timestamp);
            return pdu;
        }
    }

    pthread_mutex_unlock(&manager.lock);
    fprintf(stderr, "Max structures reached.\n");
    return NULL;
}

void free_manager_resources(void) {
    pthread_mutex_lock(&manager.lock);

    for (int i = 0; i < MAX_STRUCTS; ++i) {
        if (manager.structs[i] != NULL) {
            free(manager.structs[i]);
            manager.structs[i] = NULL;
        }
    }

    pthread_mutex_unlock(&manager.lock);
}

