['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 100
#define TIMEOUT_INTERVAL 60 // seconds

typedef struct CRC_INDICATION_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct UE_INFORMATION_TAG {
    unsigned long RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t last_access_time;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    int size;
    pthread_mutex_t lock;
} CRC_LIST;

CRC_LIST crc_list = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_crc_list() {
    crc_list.head = NULL;
    crc_list.tail = NULL;
    crc_list.size = 0;
}

int add_to_crc_list(NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&crc_list.lock);

    if (crc_list.size >= MAX_LIST_SIZE) {
        // Evict LRU
        NFAPI_CRC_INDICATION_PDU_T* lru_node = crc_list.head;
        if (lru_node) {
            crc_list.head = lru_node->next;
            if (crc_list.head) {
                crc_list.head->prev = NULL;
            } else {
                crc_list.tail = NULL; // List becomes empty
            }
            free(lru_node);
            crc_list.size--;
        }
    }

    node->last_access_time = time(NULL);

    if (!crc_list.head) {
        crc_list.head = node;
        crc_list.tail = node;
    } else {
        crc_list.tail->next = node;
        node->prev = crc_list.tail;
        crc_list.tail = node;
    }

    crc_list.size++;
    pthread_mutex_unlock(&crc_list.lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_node(unsigned long rnti) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->ue_info_tag.RNTI = rnti;
    node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    node->last_access_time = time(NULL);
    node->next = NULL;
    node->prev = NULL;

    return node;
}

void cleanup_expired_nodes() {
    pthread_mutex_lock(&crc_list.lock);

    NFAPI_CRC_INDICATION_PDU_T* current = crc_list.head;
    while (current) {
        if (difftime(time(NULL), current->last_access_time) > TIMEOUT_INTERVAL) {
            NFAPI_CRC_INDICATION_PDU_T* to_remove = current;

            if (to_remove->prev) {
                to_remove->prev->next = to_remove->next;
            } else {
                crc_list.head = to_remove->next;
            }

            if (to_remove->next) {
                to_remove->next->prev = to_remove->prev;
            } else {
                crc_list.tail = to_remove->prev;
            }

            current = to_remove->next;
            free(to_remove);
            crc_list.size--;
        } else {
            current->last_access_time = time(NULL); // Refresh access time
            current = current->next;
        }
    }

    pthread_mutex_unlock(&crc_list.lock);
}

void serialize_crc_list(const char* filename) {
    pthread_mutex_lock(&crc_list.lock);

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T* current = crc_list.head;
    while (current) {
        fwrite(&(current->ue_info_tag), sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&(current->crc_indication_rel8_tag), sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        fwrite(&current->last_access_time, sizeof(time_t), 1, file);

        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&crc_list.lock);
}

void deserialize_crc_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&crc_list.lock);

    while (1) {
        RX_UE_INFORMATION_TAG ue_info_tag;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
        time_t last_access_time;

        size_t result = fread(&ue_info_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        if (result == 0) break;

        result = fread(&crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        if (result == 0) break;

        result = fread(&last_access_time, sizeof(time_t), 1, file);
        if (result == 0) break;

        NFAPI_CRC_INDICATION_PDU_T* node = create_crc_node(ue_info_tag.RNTI);
        if (!node) {
            // Handle memory allocation failure
            break;
        }

        node->crc_indication_rel8_tag.CRCFLAG = crc_indication_rel8_tag.CRCFLAG;
        node->last_access_time = last_access_time;

        add_to_crc_list(node);
    }

    fclose(file);
    pthread_mutex_unlock(&crc_list.lock);
}

void access_node(unsigned long rnti) {
    pthread_mutex_lock(&crc_list.lock);

    NFAPI_CRC_INDICATION_PDU_T* current = crc_list.head;
    while (current) {
        if (current->ue_info_tag.RNTI == rnti) {
            // Move accessed node to tail (LRU update)
            if (current != crc_list.tail) {
                if (current->prev) {
                    current->prev->next = current->next;
                }
                if (current->next) {
                    current->next->prev = current->prev;
                }

                if (crc_list.head == current) {
                    crc_list.head = current->next;
                }

                current->next = NULL;
                current->prev = crc_list.tail;

                if (crc_list.tail) {
                    crc_list.tail->next = current;
                }
                crc_list.tail = current;

                if (!crc_list.head) {
                    crc_list.head = crc_list.tail;
                }
            }

            current->last_access_time = time(NULL);
            pthread_mutex_unlock(&crc_list.lock);
            return;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&crc_list.lock);
}

// Note: The code above assumes that the caller will periodically call `cleanup_expired_nodes()`.
