#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1000
#define ACCESS_TIMEOUT_INTERVAL 60000 // in milliseconds

typedef struct {
    unsigned int example_field; // Placeholder for PHYCH_DEMOD_PARAMS fields
} PHYCH_DEMOD_PARAMS;

typedef struct {
    unsigned int example_field; // Placeholder for SRS_RSRP_REPORT fields
} SRS_RSRP_REPORT;

typedef struct {
    unsigned int example_field; // Placeholder for PHYCH_DEMOD_RESULT fields
} PHYCH_DEMOD_RESULT;

typedef struct NFAPI_LTE_RX_MSG_T {
    PHYCH_DEMOD_PARAMS params;
    SRS_RSRP_REPORT report;
    PHYCH_DEMOD_RESULT result;
    time_t last_access_time;
} NFAPI_LTE_RX_MSG_T;

typedef struct {
    NFAPI_LTE_RX_MSG_T *array[MAX_ARRAY_SIZE];
    size_t count;
    pthread_mutex_t lock;
} MessageArrayManager;

MessageArrayManager* create_message_array_manager() {
    MessageArrayManager* manager = (MessageArrayManager*)malloc(sizeof(MessageArrayManager));
    if (!manager) return NULL;

    memset(manager->array, 0, sizeof(NFAPI_LTE_RX_MSG_T*) * MAX_ARRAY_SIZE);
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void cleanup_expired_entries(MessageArrayManager* manager) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->count; ++i) {
        if ((current_time - manager->array[i]->last_access_time) > ACCESS_TIMEOUT_INTERVAL / 1000) {
            free(manager->array[i]);
            manager->array[i] = NULL;
            --manager->count;

            for (size_t j = i; j < manager->count; ++j) {
                manager->array[j] = manager->array[j + 1];
            }
            manager->array[manager->count] = NULL;
        }
    }
}

NFAPI_LTE_RX_MSG_T* add_message(MessageArrayManager* manager, const PHYCH_DEMOD_PARAMS* params,
                                const SRS_RSRP_REPORT* report, const PHYCH_DEMOD_RESULT* result) {
    pthread_mutex_lock(&manager->lock);

    cleanup_expired_entries(manager);

    if (manager->count >= MAX_ARRAY_SIZE) {
        free(manager->array[0]);
        for (size_t i = 1; i < manager->count; ++i) {
            manager->array[i - 1] = manager->array[i];
        }
        manager->array[manager->count - 1] = NULL;
        --manager->count;
    }

    NFAPI_LTE_RX_MSG_T* new_message = (NFAPI_LTE_RX_MSG_T*)malloc(sizeof(NFAPI_LTE_RX_MSG_T));
    if (!new_message) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    *new_message = (NFAPI_LTE_RX_MSG_T){
        .params = { *(const PHYCH_DEMOD_PARAMS*)params },
        .report = { *(const SRS_RSRP_REPORT*)report },
        .result = { *(const PHYCH_DEMOD_RESULT*)result },
        .last_access_time = time(NULL)
    };

    manager->array[manager->count++] = new_message;

    pthread_mutex_unlock(&manager->lock);
    return new_message;
}

void access_message(MessageArrayManager* manager, size_t index) {
    if (index >= manager->count) return;

    pthread_mutex_lock(&manager->lock);

    if (manager->array[index]) {
        manager->array[index]->last_access_time = time(NULL);
    }

    pthread_mutex_unlock(&manager->lock);
}

int serialize_array(MessageArrayManager* manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]) {
            fwrite(manager->array[i], sizeof(NFAPI_LTE_RX_MSG_T), 1, file);
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

int deserialize_array(MessageArrayManager* manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < MAX_ARRAY_SIZE && i < count; ++i) {
        NFAPI_LTE_RX_MSG_T* message = (NFAPI_LTE_RX_MSG_T*)malloc(sizeof(NFAPI_LTE_RX_MSG_T));
        if (!message) break;

        fread(message, sizeof(NFAPI_LTE_RX_MSG_T), 1, file);
        manager->array[i] = message;
    }
    manager->count = count < MAX_ARRAY_SIZE ? count : MAX_ARRAY_SIZE;

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

void destroy_message_array_manager(MessageArrayManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i]);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
