    static int num_fields = sizeof(fields) / sizeof(fields[0]);

    if (num_fields > max_size) {
        log_error("Critical field list size exceeds maximum allowed.");
        return 0;
    }

    // Allocate memory for the critical fields
    *critical_field_list = (char **)malloc(num_fields * sizeof(char *));
    if (!*critical_field_list) {
        log_error("Memory allocation failed for critical field list.");
        return 0;
    }

    // Populate with data from external source simulation
    for (int i = 0; i < num_fields; ++i) {
        (*critical_field_list)[i] = strdup(fields[i]);
        if (!(*critical_field_list)[i]) {
            log_error("Memory allocation failed for a critical field string.");
            // Free previously allocated strings on failure
            while (--i >= 0) free((*critical_field_list)[i]);
            free(*critical_field_list);
            return 0;
        }
    }

    return 1; // Success
}

// Example of freeing the dynamically allocated memory
void free_lte_rrc_cme_causes(LTE_RRC_CME_Cause *causes, int size) {
    if (!causes) return;

    for (int i = 0; i < size; ++i) {
        for (char **field_list = causes[i].critical_field_list; field_list && *field_list; ++field_list) {
            free(*field_list);
        }
        free(causes[i].critical_field_list);
    }

    free(causes);
}

