uint16_t fetchNextValidRNTI(uint16_t previousRNTI, int totalRNTIs);

NFAPI_CRC_INDICATION_PDU_T* generateNFAPICRCIndications(int numPDUs, uint32_t seed, int logPdus) {
    if (numPDUs <= 0 || numPDUs > 1000000) return NULL;

    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory for PDUs");
        return NULL;
    }

    uint16_t previousRNTI = 0xFFFF; // Initialize with an invalid RNTI
    int totalRNTIs = 65535; // Assuming a maximum of 2^16 - 1 RNTI values

    for (int i = 0; i < numPDUs; ++i) {
        pdus[i].RNTI = fetchNextValidRNTI(previousRNTI, totalRNTIs);
        pdus[i].crcTag.CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1

        if (!validateCRCIndicationTag(&pdus[i].crcTag)) {
            fprintf(stderr, "Invalid CRC_INDICATION_REL8_TAG at index %d\n", i);
            free(pdus);
            return NULL;
        }

        previousRNTI = pdus[i].RNTI;

        if (logPdus) {
            printf("Generated PDU %d: RNTI=0x%04X, CRCFLAG=%u\n", i,
                   pdus[i].RNTI, pdus[i].crcTag.CRCFLAG);
        }
    }

    return pdus;
}

int validateCRCIndicationTag(const CRC_INDICATION_REL8_TAG *tag) {
    // Placeholder for actual validation logic
    return 1; // Assume all tags are valid for this example
}

uint16_t fetchNextValidRNTI(uint16_t previousRNTI, int totalRNTIs) {
    uint16_t newRNTI;
    do {
        newRNTI = rand() % totalRNTIs;
    } while (newRNTI == previousRNTI);
    return newRNTI;
}

void freePDUList(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}
