### Java Code: Network Component

```java
import java.io.IOException;
import java.net.Socket;
import java.util.logging.Level;
import java.util.logging.Logger;

public class NetworkComponent {

    private static final Logger logger = Logger.getLogger(NetworkComponent.class.getName());
    private Socket socket;

    public enum ConnectionState {
        CLOSED, ESTABLISHING, ACTIVE, ERROR
    }

    private ConnectionState state;

    public NetworkComponent() {
        this.state = ConnectionState.CLOSED;
    }

    public boolean connect(String host, int port) {
        if (state != ConnectionState.CLOSED) return false;

        try {
            socket = new Socket(host, port);
            state = ConnectionState.ACTIVE;
            logger.log(Level.INFO, "Connected to server at {0}:{1}", new Object[]{host, port});
            return true;
        } catch (IOException e) {
            state = ConnectionState.ERROR;
            logger.log(Level.SEVERE, "Failed to connect", e);
        }
        return false;
    }

    public void close() {
        if (state == ConnectionState.CLOSED || socket == null) return;

        try {
            socket.close();
            state = ConnectionState.CLOSED;
            logger.log(Level.INFO, "Connection closed");
        } catch (IOException e) {
            logger.log(Level.WARNING, "Failed to close connection", e);
        }
    }

    public boolean isConnected() {
        return state == ConnectionState.ACTIVE;
    }

    // Add additional methods for handling network operations as needed.
}
```

