#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_PACKET_LIST_SIZE 1000
#define PACKET_STRUCTURE_SIZE sizeof(NetworkPacket)
#define MAX_PACKET_SIZE 1500

typedef struct {
    unsigned char mac_header[14];
    unsigned short vlan_tag;
    unsigned char ip_header[20];
    unsigned short checksum;
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketList;

void initialize_packet_list(PacketList *list) {
    list->count = 0;
    list->capacity = INITIAL_PACKET_LIST_SIZE;
    list->packets = malloc(list->capacity * PACKET_STRUCTURE_SIZE);
    if (!list->packets) {
        fprintf(stderr, "Failed to allocate memory for packet list.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void resize_packet_list(PacketList *list) {
    size_t new_capacity = list->capacity * 2;
    NetworkPacket *new_packets = realloc(list->packets, new_capacity * PACKET_STRUCTURE_SIZE);
    if (!new_packets) {
        fprintf(stderr, "Failed to reallocate memory for packet list.\n");
        exit(EXIT_FAILURE);
    }
    list->packets = new_packets;
    list->capacity = new_capacity;
}

void process_packet(const unsigned char *packet_data, size_t length) {
    // Validate checksum or other processing
    // Assuming `compute_checksum` is a function that computes the checksum.
    unsigned short received_checksum = *(unsigned short *)(packet_data + length - 2);
    if (received_checksum == compute_checksum(packet_data, length - 2)) {
        printf("Packet is valid.\n");
    } else {
        printf("Packet is invalid. Checksum mismatch.\n");
    }
}

void add_packet(PacketList *list, const unsigned char *packet_data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        resize_packet_list(list);
    }

    size_t packet_index = list->count;
    memcpy(list->packets[packet_index].mac_header, packet_data, 14);
    list->packets[packet_index].vlan_tag = *(unsigned short *)(packet_data + 14);
    memcpy(list->packets[packet_index].ip_header, packet_data + 16, 20);
    list->packets[packet_index].checksum = *(unsigned short *)(packet_data + MAX_PACKET_SIZE - 2);

    process_packet(packet_data, MAX_PACKET_SIZE);
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

unsigned short compute_checksum(const unsigned char *data, size_t length) {
    unsigned long sum = 0;
    for (size_t i = 0; i < length; i += 2) {
        if (i + 1 < length) {
            sum += data[i] << 8 | data[i + 1];
        } else {
            sum += data[i] << 8;
        }
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~sum;
}

void cleanup_packet_list(PacketList *list) {
    free(list->packets);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    PacketList packet_list;
    initialize_packet_list(&packet_list);

    // Simulate receiving packets (dummy data for illustration)
    unsigned char dummy_packet[MAX_PACKET_SIZE] = {0};
    for (int i = 0; i < 10000; ++i) {
        add_packet(&packet_list, dummy_packet);
    }

    cleanup_packet_list(&packet_list);
    return 0;
}
```

