} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    time_t timestamp;
    int sequenceNumber;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head;
    int size;
    pthread_mutex_t lock;
    // Memory pool management structures would go here
} NFAPI_LIST;

// Function to initialize the list
void initNfaapiList(NFAPI_LIST *list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to add an element to the list
int addElement(NFAPI_LIST *list, NFAPI_CRC_INDICATION_PDU_T pdu, int max_size) {
    if (pthread_mutex_lock(&list->lock)) return -1;

    if (list->size >= max_size) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    NFAPI_CRC_INDICATION_PDU *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    newNode->rxUeInfoTag = pdu.rxUeInformationTag;
    newNode->rnti = pdu.rnti;
    newNode->crcIndicationRel8Tag.crcFlag = rand() % 2;
    newNode->timestamp = time(NULL);
    newNode->sequenceNumber = list->size + 1; // Assuming sequence starts at 1
    newNode->next = list->head;

    list->head = newNode;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to serialize the list to a binary file
int serializeList(const NFAPI_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU *current = list->head;

    while (current) {
        size_t written = fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU), 1, file);
        if (written != 1) {
            fclose(file);
            pthread_mutex_unlock(&list->lock);
            return -2; // Write error
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0; // Success
}

// Function to deserialize the list from a binary file
int deserializeList(NFAPI_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);
    while (fread(list->head ? &list->head : NULL, sizeof(NFAPI_CRC_INDICATION_PDU), 1, file)) {
        NFAPI_CRC_INDICATION_PDU *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failed
        }

        memcpy(newNode, list->head ? &list->head : NULL, sizeof(NFAPI_CRC_INDICATION_PDU));
        newNode->next = list->head;
        list->head = newNode;

        if (feof(file)) break;
    }

    if (ferror(file)) {
        // Clean up
        NFAPI_CRC_INDICATION_PDU *current = list->head;
        while (current) {
            NFAPI_CRC_INDICATION_PDU *nextNode = current->next;
            free(current);
            current = nextNode;
        }
        pthread_mutex_unlock(&list->lock);
        fclose(file);
        return -3; // Read error
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0; // Success
}

// Main function for demonstration purposes
int main() {
    NFAPI_LIST list;
    initNfaapiList(&list);

    srand(time(NULL)); // Seed random number generator

    const int max_size = 10;

    for (int i = 0; i < max_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .rxUeInformationTag = i, .rnti = i + 100 };
        if (addElement(&list, pdu, max_size) != 0) {
            fprintf(stderr, "Error adding element\n");
        }
    }

    const char *filename = "nfaapi_list.bin";

    if (serializeList(&list, filename) != 0) {
        fprintf(stderr, "Error serializing list\n");
    } else {
        printf("Serialized list to %s\n", filename);
    }

    NFAPI_LIST new_list;
    initNfaapiList(&new_list);

    if (deserializeList(&new_list, filename) != 0) {
        fprintf(stderr, "Error deserializing list\n");
    } else {
        printf("Deserialized list from %s\n", filename);
    }

    // Clean up the original list
    NFAPI_CRC_INDICATION_PDU *current = list.head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU *nextNode = current->next;
        free(current);
        current = nextNode;
    }
    pthread_mutex_destroy(&list.lock);

    // Clean up the new list
    current = new_list.head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU *nextNode = current->next;
        free(current);
        current = nextNode;
    }
    pthread_mutex_destroy(&new_list.lock);

    return 0;
}
