} CRCDynamicList;

CRCDynamicList* createCRCList() {
    CRCDynamicList* crclist = (CRCDynamicList*)malloc(sizeof(CRCDynamicList));
    if (!crclist) return NULL;

    crclist->list = NULL;
    crclist->count = 0;
    pthread_mutex_init(&crclist->mutex, NULL);
    return crclist;
}

int addCRCEntry(CRCDynamicList* crclist, int rnti) {
    if (pthread_mutex_lock(&crclist->mutex)) return -1;

    if (crclist->count >= MAX_UE_CAPACITY) {
        pthread_mutex_unlock(&crclist->mutex);
        fprintf(stderr, "Exceeded maximum UE capacity.\n");
        return -2;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(crclist->list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crclist->count + 1));
    if (!new_list) {
        pthread_mutex_unlock(&crclist->mutex);
        fprintf(stderr, "Memory allocation failed.\n");
        return -3;
    }

    crclist->list = new_list;
    int rx_tag = rand() % 256; // Simulate random RX_UE_INFORMATION_TAG
    int crc_rel8_tag = rand() % 256; // Simulate random CRC_INDICATION_REL8_TAG
    int crcflag = rand() % 2; // Randomly set CRCFLAG

    crclist->list[crclist->count] = (NFAPI_CRC_INDICATION_PDU_T){
        .RNTI = rnti,
        .RX_UE_INFORMATION_TAG = rx_tag,
        .CRC_INDICATION_REL8_TAG = crc_rel8_tag,
        .CRCFLAG = crcflag
    };
    crclist->count++;

    pthread_mutex_unlock(&crclist->mutex);
    return 0;
}

void resetCRCDynamicList(CRCDynamicList* crclist) {
    if (pthread_mutex_lock(&crclist->mutex)) return;

    free(crclist->list);
    crclist->list = NULL;
    crclist->count = 0;

    pthread_mutex_unlock(&crclist->mutex);
}

void destroyCRCDynamicList(CRCDynamicList* crclist) {
    if (!crclist) return;

    resetCRCDynamicList(crclist);
    pthread_mutex_destroy(&crclist->mutex);
    free(crclist);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    CRCDynamicList* crc_list = createCRCList();
    if (!crc_list) {
        fprintf(stderr, "Failed to create CRC list.\n");
        return 1;
    }

    for (int i = 0; i < MAX_UE_CAPACITY + 10; ++i) { // Test exceeding capacity
        int result = addCRCEntry(crc_list, i);
        if (result != 0) {
            fprintf(stderr, "Error adding CRC entry: %d\n", result);
        }
    }

    resetCRCDynamicList(crc_list);

    destroyCRCDynamicList(crc_list);
    return 0;
}
```

### Key Features:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that concurrent access is managed safely.
- **Dynamic Memory Management**: Efficiently reallocates memory as new entries are added, and frees memory upon reset or destruction.
- **Error Handling**: Handles cases where the number of UEs exceeds capacity or if memory allocation fails.
- **Reset Functionality**: Allows resetting the list without losing data structure integrity, enabling reuse.']

