#define MAX_POOL_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[10]; // Example size
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->capacity = 0;
    array->count = 0;
    array->data = NULL;
    pthread_mutex_init(&array->lock, NULL);
}

int resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1; // Memory allocation failed
    array->data = new_data;
    array->capacity = new_capacity;
    return 0;
}

int add_element(DynamicArray *array, const NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        if (new_capacity > MAX_POOL_SIZE) new_capacity = MAX_POOL_SIZE;

        int result = resize_dynamic_array(array, new_capacity);
        if (result != 0) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
    }

    memcpy(&array->data[array->count], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_dynamic_array(DynamicArray *array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->count = 0;
    pthread_mutex_destroy(&array->lock);
}

int main() {
    DynamicArray array;
    init_dynamic_array(&array);

    srand(time(NULL)); // Seed for random number generation

    const int N = 100; // Example size
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 65536;
        pdu.RNTI = rand() % 65536;
        memset(pdu.CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu.CRC_INDICATION_REL8_TAG));

        if (add_element(&array, &pdu) != 0) {
            fprintf(stderr, "Failed to add element due to memory allocation error.\n");
            break;
        }
    }

    free_dynamic_array(&array);
    return 0;
}
```

### Assumptions and Trade-offs:
1. **Thread Safety**: The use of `pthread_mutex_t` ensures thread safety for concurrent access.
2. **Memory Management**: Dynamic resizing is done using `realloc`, which may be slower than contiguous allocations but handles varying loads efficiently.
3. **Cache Locality**: Using a dynamic array helps maintain cache locality, as elements are stored contiguously in memory.
4. **Error Handling**: Graceful handling of allocation failures ensures the application does not crash.
5. **Logging and Monitoring**: Simple error logging is included; more sophisticated monitoring would require additional infrastructure.
6. **Pre-allocated Pool Strategy**: Not implemented due to complexity, but could be added for specific use cases where predictability in allocation patterns exists.

This implementation balances performance, memory usage, and thread safety, making it suitable for high-throughput network environments.']

