```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Assuming these are placeholders for actual types
    int RxUeInformationTag;
    int Rnti;
    int CRCIndicationRel15Tag;
} NRUEContext;

typedef struct {
    NRUEContext *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;  // For concurrency control
} DynamicArray;

// Initialize the dynamic array
void initDynamicArray(DynamicArray *dynArr) {
    dynArr->size = 0;
    dynArr->capacity = 10;  // Initial capacity
    dynArr->array = (NRUEContext *)malloc(dynArr->capacity * sizeof(NRUEContext));
    pthread_mutex_init(&dynArr->lock, NULL);
}

// Resize the dynamic array when needed
void resizeDynamicArray(DynamicArray *dynArr) {
    size_t newCapacity = dynArr->capacity * 2;
    NRUEContext *newArray = (NRUEContext *)realloc(dynArr->array, newCapacity * sizeof(NRUEContext));
    if (newArray) {
        dynArr->array = newArray;
        dynArr->capacity = newCapacity;
    } else {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
}

// Add a new NRUEContext
void addNRUEContext(DynamicArray *dynArr, NRUEContext context) {
    pthread_mutex_lock(&dynArr->lock);

    if (dynArr->size == dynArr->capacity) {
        resizeDynamicArray(dynArr);
    }

    dynArr->array[dynArr->size++] = context;

    pthread_mutex_unlock(&dynArr->lock);
}

// Update an NRUEContext by index
void updateNRUEContext(DynamicArray *dynArr, size_t index, NRUEContext newContext) {
    if (index < dynArr->size) {
        pthread_mutex_lock(&dynArr->lock);

        dynArr->array[index] = newContext;

        pthread_mutex_unlock(&dynArr->lock);
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
}

// Iterate over the array and apply a function to each NRUEContext
void iterateNRUEContext(DynamicArray *dynArr, void (*func)(NRUEContext *)) {
    pthread_mutex_lock(&dynArr->lock);

    for (size_t i = 0; i < dynArr->size; ++i) {
        func(&(dynArr->array[i]));
    }

    pthread_mutex_unlock(&dynArr->lock);
}

// Free the dynamic array
void freeDynamicArray(DynamicArray *dynArr) {
    pthread_mutex_lock(&dynArr->lock);

    free(dynArr->array);
    dynArr->size = 0;
    dynArr->capacity = 0;

    pthread_mutex_unlock(&dynArr->lock);
    pthread_mutex_destroy(&dynArr->lock);
}

// Example usage of the iterate function
void printNRUEContext(NRUEContext *context) {
    printf("RxUeInformationTag: %d, Rnti: %d, CRCIndicationRel15Tag: %d\n",
           context->RxUeInformationTag, context->Rnti, context->CRCIndicationRel15Tag);
}

int main() {
    DynamicArray dynArr;
    initDynamicArray(&dynArr);

    NRUEContext context1 = {1, 2, 3};
    addNRUEContext(&dynArr, context1);

    NRUEContext context2 = {4, 5, 6};
    addNRUEContext(&dynArr, context2);

    iterateNRUEContext(&dynArr, printNRUEContext);

    updateNRUEContext(&dynArr, 0, (NRUEContext){7, 8, 9});

    iterateNRUEContext(&dynArr, printNRUEContext);

    freeDynamicArray(&dynArr);
    return 0;
}
```

### Key Points:
- **Memory Efficiency**: Uses dynamic resizing to handle growing arrays efficiently.
- **Concurrency**: Employs a mutex for thread-safe operations.
- **Scalability**: The dynamic array can grow as needed, and the use of locks ensures safe concurrent access.
- **Performance**: Minimal locking scope to reduce latency; efficient memory management with realloc.
- **Future Expansions**: Structs and functions are designed to be easily extendable.']

