#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NFAPI_CRS_INDICATIONS 1000
#define MAX_LTE_RRC_EUTRA_MEASUREMENT_REPORTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int MEASUREMENT_OBJECT;
    int MEASUREMENT_VALUE;
    struct {
        int QoS_PRIORITY_LEVEL;
    } QUALITY_OF_SERVICE_TAG;
} LTE_RRC_EUTRA_MEASUREMENT_REPORT;

typedef struct Node {
    LTE_RRC_EUTRA_MEASUREMENT_REPORT report;
    int priority;
    struct Node* next;
} PriorityQueueNode;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
} CRCIndicationManager;

typedef struct {
    PriorityQueueNode* head;
    size_t count;
} Priority_Queue;

CRCIndicationManager* create_crc_manager() {
    CRCIndicationManager* manager = malloc(sizeof(CRCIndicationManager));
    if (!manager) return NULL;
    manager->array = calloc(MAX_NFAPI_CRS_INDICATIONS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count = 0;
    return manager;
}

void destroy_crc_manager(CRCIndicationManager* manager) {
    if (manager) {
        free(manager->array);
        free(manager);
    }
}

int update_crc_flags(CRCIndicationManager* manager, int condition) {
    if (!manager || manager->count == 0) return -1;

    for (size_t i = 0; i < manager->count; ++i) {
        manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        // Adjust based on external condition
        if (condition > 5) {
            manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG ^= 1;
        }
    }

    return 0;
}

int add_crc_indication(CRCIndicationManager* manager, int rx_ue_tag, int rnti) {
    if (!manager || manager->count >= MAX_NFAPI_CRS_INDICATIONS) return -1;

    NFAPI_CRC_INDICATION_PDU_T* pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    return 0;
}

Priority_Queue* create_priority_queue() {
    Priority_Queue* queue = malloc(sizeof(Priority_Queue));
    if (!queue) return NULL;
    queue->head = NULL;
    queue->count = 0;
    return queue;
}

void destroy_priority_queue(Priority_Queue* queue) {
    PriorityQueueNode* current = queue->head;
    while (current) {
        PriorityQueueNode* next = current->next;
        free(current);
        current = next;
    }
    free(queue);
}

int insert_to_priority_queue(Priority_Queue* queue, LTE_RRC_EUTRA_MEASUREMENT_REPORT report, int priority) {
    if (!queue) return -1;

    PriorityQueueNode* new_node = malloc(sizeof(PriorityQueueNode));
    if (!new_node) return -1;
    new_node->report = report;
    new_node->priority = priority;
    new_node->next = NULL;

    if (!queue->head || queue->head->priority < priority) {
        new_node->next = queue->head;
        queue->head = new_node;
    } else {
        PriorityQueueNode* current = queue->head;
        while (current->next && current->next->priority >= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    queue->count++;
    return 0;
}

void process_measurement_reports_batch(Priority_Queue* queue, LTE_RRC_EUTRA_MEASUREMENT_REPORT reports[], int priorities[], size_t count) {
    if (!queue || !reports || !priorities || count == 0) return;

    for (size_t i = 0; i < count; ++i) {
        insert_to_priority_queue(queue, reports[i], priorities[i]);
    }
}

void log_performance_metrics(CRCIndicationManager* manager, Priority_Queue* queue) {
    printf("CRC Manager Count: %zu\n", manager->count);
    printf("Priority Queue Count: %zu\n", queue->count);
}

int main() {
    srand(time(NULL));

    CRCIndicationManager* crc_manager = create_crc_manager();
    if (!crc_manager) return EXIT_FAILURE;

    Priority_Queue* pq = create_priority_queue();
    if (!pq) {
        destroy_crc_manager(crc_manager);
        return EXIT_FAILURE;
    }

    // Example usage
    add_crc_indication(crc_manager, 1, 100);
    update_crc_flags(crc_manager, 6);

    LTE_RRC_EUTRA_MEASUREMENT_REPORT reports[2] = {
        {1, 200}, {2, 300}
    };
    int priorities[2] = {5, 10};
    process_measurement_reports_batch(pq, reports, priorities, 2);

    log_performance_metrics(crc_manager, pq);

    destroy_crc_manager(crc_manager);
    destroy_priority_queue(pq);

    return EXIT_SUCCESS;
}
```']

