        printf("%s\n", message);
    }
}

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_array(size_t N, unsigned int seed, double error_rate, LogLevel log_level) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t initialized_count = 0;

    if (N == 0) {
        log_message(log_level, "No structures to initialize.");
        goto cleanup;
    }

    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_message(LOG_ERROR, "Memory allocation failed completely.");
        goto cleanup;
    }

    srand(seed);

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);

        // Simulate error rate
        if ((double)rand() / RAND_MAX < error_rate) {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Failed to initialize structure at index %zu.", i);
            log_message(LOG_ERROR, log_msg);
            pthread_mutex_unlock(&lock);
            continue;
        }

        array[i].RX_UE_INFORMATION_TAG = rand() & 0xFFFF; // Example value
        array[i].RNTI = rand() & 0xFFFFFFFF;             // Example value
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0;

        initialized_count++;
        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "Successfully initialized structure at index %zu.", i);
        log_message(LOG_INFO, log_msg);

        pthread_mutex_unlock(&lock);
    }

cleanup:
    if (initialized_count == 0 && array) {
        free(array);
        array = NULL;
    }

    pthread_mutex_destroy(&lock);
    return array ? (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, initialized_count * sizeof(NFAPI_CRC_INDICATION_PDU_T)) : NULL;
}

// Example usage
int main() {
    size_t N = 10;
    unsigned int seed = 12345;
    double error_rate = 0.1;
    LogLevel log_level = LOG_INFO;

    NFAPI_CRC_INDICATION_PDU_T *array = initialize_crc_array(N, seed, error_rate, log_level);

    if (array) {
        printf("Successfully initialized %zu structures.\n", array ? (NFAPI_CRC_INDICATION_PDU_T*)malloc(array - 0) / sizeof(NFAPI_CRC_INDICATION_PDU_T) : 0);
        free(array);
    } else {
        printf("Failed to initialize any structures.\n");
    }

    return 0;
}
