    FRAME_TYPE_UNSUPPORTED
} FRAME_TYPE;

typedef struct {
    FRAME_TYPE frame_type;
    unsigned int subframe_index;
    int crc_flag;  // Non-zero if CRC is valid
} PHY_RX_FRAME_INFO_T;

#define LOG_ERROR(...) printf("ERROR: " __VA_ARGS__)
#define LOG_SUCCESS(...) printf("SUCCESS: " __VA_ARGS__)

PHY_RX_FRAME_INFO_T* initialize_frames(size_t N, unsigned int seed, double error_rate, size_t *successful_count) {
    if (N == 0 || error_rate < 0.0 || error_rate > 1.0) {
        LOG_ERROR("Invalid input parameters");
        return NULL;
    }

    srand(seed);

    PHY_RX_FRAME_INFO_T *frames = (PHY_RX_FRAME_INFO_T *)malloc(N * sizeof(PHY_RX_FRAME_INFO_T));
    if (!frames) {
        LOG_ERROR("Memory allocation failed for frames array");
        return NULL;
    }

    size_t success_count = 0;

    for (size_t i = 0; i < N; ++i) {
        double rand_val = (double)rand() / RAND_MAX;

        if (rand_val < error_rate) {
            LOG_ERROR("Failed to initialize frame at index %zu due to simulated error rate", i);
            continue;
        }

        frames[i].frame_type = FRAME_TYPE(rand_val * 3); // Randomly assign supported types
        if (frames[i].frame_type == FRAME_TYPE_UNSUPPORTED) {
            LOG_ERROR("Unsupported frame type encountered at index %zu, skipping initialization", i);
            free(frames);
            return NULL;
        }

        frames[i].subframe_index = rand() % 1024; // Example subframe index generation
        frames[i].crc_flag = (rand_val > 0.5) ? 1 : 0; // Randomly set CRC flag

        LOG_SUCCESS("Successfully initialized frame at index %zu", i);
        success_count++;
    }

    *successful_count = success_count;

    if (success_count == 0) {
        free(frames);
        return NULL;
    }

    return frames;
}

void cleanup_frames(PHY_RX_FRAME_INFO_T *frames) {
    if (frames) {
        free(frames);
    }
}
```

This code defines a C function `initialize_frames` that manages a dynamic array of `PHY_RX_FRAME_INFO_T` structures. The function takes parameters for the total number of structures, a seed for random generation, and an error rate probability. It populates each structure with valid data while handling memory allocation failures and initialization errors due to the specified error rate. Logging is included to track successes and failures during initialization. The function returns a pointer to the allocated array or `NULL` if allocation fails completely. A cleanup function `cleanup_frames` is also provided for freeing the allocated memory.']

