// Define the event type and payload structure
typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B
} EventType;

typedef struct {
    // Example payload fields; can be extended for more types
    int data;
    char message[256];
} Payload;

// Notification structure containing timestamp, event type, and payload
typedef struct {
    time_t timestamp;
    EventType eventType;
    Payload payload;
} EventNotification;

// Node in the doubly linked list
struct EventNode {
    EventNotification notification;
    struct EventNode *prev;
    struct EventNode *next;
};

// List to manage events with a mutex for concurrency control
typedef struct {
    struct EventNode *head;
    pthread_mutex_t lock;
} EventList;

// Initialize an event list
EventList* create_event_list() {
    EventList* list = (EventList*) malloc(sizeof(EventList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new event to the list
void add_event(EventList *list, const EventNotification *event) {
    struct EventNode* node = (struct EventNode*) malloc(sizeof(struct EventNode));
    if (!node) return;

    *node = (struct EventNode){
        .notification = *event,
        .prev = NULL,
        .next = list->head
    };

    pthread_mutex_lock(&list->lock);
    if (list->head) {
        list->head->prev = node;
    }
    list->head = node;
    pthread_mutex_unlock(&list->lock);
}

// Remove an event from the list by timestamp
void remove_event(EventList *list, time_t timestamp) {
    pthread_mutex_lock(&list->lock);

    struct EventNode* current = list->head;
    while (current) {
        if (current->notification.timestamp == timestamp) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            }

            free(current);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Retrieve events within a specified time range
void get_events(EventList *list, time_t start, time_t end, EventNotification **out_events, size_t *count) {
    pthread_mutex_lock(&list->lock);

    struct EventNode* current = list->head;
    while (current) {
        if (current->notification.timestamp >= start && current->notification.timestamp <= end) {
            out_events[*count] = &current->notification;
            (*count)++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the list and its contents
void free_event_list(EventList *list) {
    struct EventNode* node = list->head;
    while (node) {
        struct EventNode* next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    // Configuration options can be added as needed

    // Create an event list
    EventList *event_list = create_event_list();

    // Add events (example)
    EventNotification new_event = { .timestamp = time(NULL), .eventType = EVENT_TYPE_A, .payload = {.data = 42} };
    add_event(event_list, &new_event);

    // Retrieve and print events within a specific range
    time_t start_time = time(NULL) - 3600; // last hour
    time_t end_time = time(NULL);
    EventNotification *events[100];
    size_t event_count = 0;

    get_events(event_list, start_time, end_time, events, &event_count);

    for (size_t i = 0; i < event_count; i++) {
        printf("Event: %d at %ld\n", events[i]->eventType, events[i]->timestamp);
    }

    // Clean up
    free_event_list(event_list);

    return 0;
}
