TCP_CONNECTION_STATS_T* manage_dynamic_array(int N, int seed, double error_rate_probability, int *success_count) {
    if (N <= 0 || error_rate_probability < 0.0 || error_rate_probability > 1.0) {
        log_message(LOG_LEVEL_ERROR, "Invalid input parameters.");
        return NULL;
