        array[i].PACKET_COUNT = (uint32_t)rand();

        initialized_count++;
    }

    if (success_count != NULL) {
        *success_count = initialized_count;
    }

    log_message(LOG_LEVEL_INFO, "Successfully initialized %d structures out of %d.", initialized_count, N);

    return array;
}

// Example usage
