typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void init_dynamic_list(DynamicList *list) {
    list->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        perror("Failed to allocate initial array");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_dynamic_list(DynamicList *list) {
    free(list->array);
    pthread_mutex_destroy(&list->lock);
}

static void resize_if_needed(DynamicList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * RESIZE_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to resize array");
            exit(EXIT_FAILURE);
        }
        list->array = new_array;
        list->capacity = new_capacity;
    }
}

void add_crc_indication_pdu(DynamicList *list, RX_UE_INFORMATION_TAG ue_info, int rnti, CRC_INDICATION_PDU_T crc_pdu) {
    pthread_mutex_lock(&list->lock);

    resize_if_needed(list);

    NFAPI_CRC_INDICATION_PDU_T pdu = {ue_info, rnti, crc_pdu};
    list->array[list->size++] = pdu;

