#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

#define MAX_RNTI 16384
#define MIN_RNTI 1

typedef struct {
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    INSUFFICIENT_RESOURCES
} Status;

pthread_mutex_t rnti_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

Status populate_nfa_api_crc_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t count, int *successful_allocations, bool enable_logging) {
    if (count == 0 || list == NULL || successful_allocations == NULL) return INSUFFICIENT_RESOURCES;

    *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) return INSUFFICIENT_RESOURCES;

    int used_rnti[MAX_RNTI] = {0};
    pthread_mutex_lock(&rnti_pool_mutex);

    srand((unsigned int)time(NULL)); // Seed the random number generator
    *successful_allocations = 0;

    for (size_t i = 0; i < count; ++i) {
        bool allocated = false;
        while (!allocated) {
            int rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;

            if (used_rnti[rnti] == 0) {
                used_rnti[rnti] = 1;
                (*list)[i].ue_info_tag.rnti = rnti;
                (*list)[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRC flag
                ++(*successful_allocations);
                allocated = true;

                if (enable_logging) {
                    printf("Allocated RNTI: %d, CRC Flag: %d\n", rnti, (*list)[i].crc_indication_rel8_tag.CRCFLAG);
                }
            }
        }
    }

    pthread_mutex_unlock(&rnti_pool_mutex);

    return SUCCESS;
}

void free_nfa_api_crc_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) {
        free(list);
    }
}
