#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RLC_ID 255
#define MAX_PDCP_ID 255

typedef struct {
    unsigned char rlc_id;
    unsigned char pdcp_id;
} MAC_CONTEXT_KEY;

typedef struct MAC_PACKET_T {
    void *data;
    size_t size;
    struct MAC_PACKET_T *next;
} MAC_PACKET_T;

typedef struct MAC_CONTEXT_T {
    MAC_CONTEXT_KEY key;
    MAC_PACKET_T *packet_list_head;
    pthread_mutex_t lock; // For thread safety
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T **contexts;
    size_t count;
    pthread_mutex_t contexts_lock; // Protect the entire collection
} MAC_CONTEXT_COLLECTION;

#define SUCCESS 0
#define ERROR -1

MAC_CONTEXT_COLLECTION* create_mac_context_collection() {
    MAC_CONTEXT_COLLECTION *collection = (MAC_CONTEXT_COLLECTION*)malloc(sizeof(MAC_CONTEXT_COLLECTION));
    if (!collection) return NULL;
    collection->contexts = NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->contexts_lock, NULL);
    return collection;
}

int add_mac_context(MAC_CONTEXT_COLLECTION *collection, unsigned char mac_rlc_amp_id, unsigned char mac_pdcp_id, MAC_PACKET_T *pdu) {
    if (!collection || mac_rlc_amp_id > MAX_RLC_ID || mac_pdcp_id > MAX_PDCP_ID) return ERROR;

    pthread_mutex_lock(&collection->contexts_lock);

    // Check for existing context with the same ID combination
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->contexts[i]->key.rlc_id == mac_rlc_amp_id &&
            collection->contexts[i]->key.pdcp_id == mac_pdcp_id) {
            pthread_mutex_unlock(&collection->contexts_lock);
            return ERROR;
        }
    }

    // Create new context
    MAC_CONTEXT_T *new_context = (MAC_CONTEXT_T*)malloc(sizeof(MAC_CONTEXT_T));
    if (!new_context) {
        pthread_mutex_unlock(&collection->contexts_lock);
        return ERROR;
    }

    new_context->key.rlc_id = mac_rlc_amp_id;
    new_context->key.pdcp_id = mac_pdcp_id;
    new_context->packet_list_head = NULL;

    // Initialize mutex for the context
    pthread_mutex_init(&new_context->lock, NULL);

    size_t old_count = collection->count;
    collection->contexts = (MAC_CONTEXT_T**)realloc(collection->contexts, sizeof(MAC_CONTEXT_T*) * (old_count + 1));
    if (!collection->contexts) {
        free(new_context);
        pthread_mutex_unlock(&collection->contexts_lock);
        return ERROR;
    }

    collection->contexts[old_count] = new_context;
    collection->count++;

    // Add PDU to the context
    pthread_mutex_lock(&new_context->lock);
    MAC_PACKET_T *current = new_context->packet_list_head;
    if (!current) {
        new_context->packet_list_head = pdu;
    } else {
        while (current->next) {
            current = current->next;
        }
        current->next = pdu;
    }
    pthread_mutex_unlock(&new_context->lock);

    pthread_mutex_unlock(&collection->contexts_lock);
    return SUCCESS;
}

void free_mac_packet(MAC_PACKET_T *packet) {
    if (!packet) return;
    MAC_PACKET_T *temp;
    while (packet) {
        temp = packet;
        packet = packet->next;
        free(temp->data); // Assuming data was dynamically allocated
        free(temp);
    }
}

void destroy_mac_context_collection(MAC_CONTEXT_COLLECTION *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->contexts_lock);

    for (size_t i = 0; i < collection->count; ++i) {
        pthread_mutex_lock(&collection->contexts[i]->lock);
        free_mac_packet(collection->contexts[i]->packet_list_head);
        pthread_mutex_unlock(&collection->contexts[i]->lock);

        pthread_mutex_destroy(&collection->contexts[i]->lock);
        free(collection->contexts[i]);
    }

    free(collection->contexts);
    pthread_mutex_unlock(&collection->contexts_lock);

    pthread_mutex_destroy(&collection->contexts_lock);
    free(collection);
}
