```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONFIGURATIONS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int id;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    int success_count;
    int failure_count;
} NFAPI_CRC_INDICATION_ARRAY;

NFAPI_CRC_INDICATION_ARRAY* create_array(size_t n) {
    if (n > MAX_CONFIGURATIONS) {
        fprintf(stderr, "Requested configuration exceeds maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_ARRAY* array = malloc(sizeof(NFAPI_CRC_INDICATION_ARRAY));
    if (!array) {
        perror("Memory allocation failed for array structure");
        return NULL;
    }

    array->size = 0;
    array->capacity = n;
    array->success_count = 0;
    array->failure_count = 0;

    array->array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        perror("Memory allocation failed for data");
        free(array);
        return NULL;
    }

    return array;
}

void populate_array(NFAPI_CRC_INDICATION_ARRAY* array, double probability, unsigned int seed) {
    pthread_mutex_lock(&lock);

    srand(seed);
    for (size_t i = 0; i < array->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.id = i + 1;
        pdu.crc_tag.RX_UE_INFORMATION_TAG = rand(); // Example random data
        pdu.crc_tag.RNTI = rand() % 1024; // Example RNTI

        double rand_val = (double)rand() / RAND_MAX;
        pdu.crc_tag.CRCFLAG = (rand_val < probability) ? 1 : 0;

        array->array[i] = pdu;
    }

    array->size = array->capacity;
    pthread_mutex_unlock(&lock);
}

void serialize_array(const NFAPI_CRC_INDICATION_ARRAY* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);
    fclose(file);
}

void deserialize_array(NFAPI_CRC_INDICATION_ARRAY* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fread(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);
    fclose(file);
}

void destroy_array(NFAPI_CRC_INDICATION_ARRAY* array) {
    if (array) {
        free(array->array);
        free(array);
    }
}

void log_statistics(const NFAPI_CRC_INDICATION_ARRAY* array) {
    printf("Initialization Success: %d\n", array->success_count);
    printf("Initialization Failure: %d\n", array->failure_count);
}

int main() {
    size_t n = 1000;
    double probability = 0.5;
    unsigned int seed = time(NULL);

    NFAPI_CRC_INDICATION_ARRAY* array = create_array(n);
    if (array) {
        populate_array(array, probability, seed);
        serialize_array(array, "configurations.bin");
        deserialize_array(array, "configurations.bin");

        log_statistics(array);
        destroy_array(array);
    }

    return 0;
}
```

