#define MAX_TRANSACTION_ID 10000
#define RETRY_LIMIT 3

typedef struct {
    int transaction_id;
    size_t payload_size;
    char *payload;
} RRC_MESSAGE_T;

typedef struct {
    // Placeholder for context data; assume more fields here
