RRC_UE_CONTEXT fetch_ue_context(int ue_id) {
    // Simulate fetching UE context from an external source
    if (ue_id < 0) return (RRC_UE_CONTEXT){ .ue_id = -1 }; // Error case
    return (RRC_UE_CONTEXT){ .ue_id = ue_id };
}

bool fetch_rrc_message(int transaction_id, RRC_MESSAGE_T *message) {
    // Simulate fetching RRC message from an external source
    if (transaction_id < 0 || transaction_id > MAX_TRANSACTION_ID) return false;
    message->transaction_id = transaction_id;
    message->payload_size = rand() % 1024; // Random payload size for demonstration
    message->payload = malloc(message->payload_size);
    if (!message->payload) return false;
    memset(message->payload, 0x42, message->payload_size); // Fill with dummy data
    return true;
}

NFAPI_RX_FRAME_T* initialize_nfa_rx_frames(size_t frame_count, int *error_code) {
    NFAPI_RX_FRAME_T *frames = malloc(frame_count * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        *error_code = -1; // Memory allocation error
        return NULL;
    }

    for (size_t i = 0; i < frame_count; ++i) {
        frames[i].ue_context = fetch_ue_context(i); // Fetch UE context

        size_t message_retry_count = 0;
        bool success = false;

        while (message_retry_count < RETRY_LIMIT && !success) {
            RRC_MESSAGE_T *messages = malloc(MAX_TRANSACTION_ID * sizeof(RRC_MESSAGE_T));
            if (!messages) {
                *error_code = -2; // Memory allocation error
                return NULL;
            }

            size_t message_count = 0;
            for (int tid = 1; tid <= MAX_TRANSACTION_ID && message_count < MAX_TRANSACTION_ID; ++tid) {
                RRC_MESSAGE_T new_message;
                if (fetch_rrc_message(tid, &new_message)) {
                    memcpy(&messages[message_count], &new_message, sizeof(RRC_MESSAGE_T));
                    messages[message_count].payload = strdup(new_message.payload); // Duplicate payload
                    free(new_message.payload);
                    message_count++;
                } else {
                    break;
                }
            }

            if (message_count > 0) {
                frames[i].messages = messages;
                frames[i].message_count = message_count;
                success = true;
            } else {
                free(messages); // Free memory on failure
                message_retry_count++;
            }
        }

        if (!success) {
            *error_code = -3; // Retry limit exceeded or other fetch errors
            for (size_t j = 0; j < i; ++j) { // Clean up previously allocated frames
                free(frames[j].messages);
            }
            free(frames);
            return NULL;
        }
    }

    *error_code = 0; // Success
    return frames;
}

void cleanup_nfa_rx_frames(NFAPI_RX_FRAME_T *frames, size_t frame_count) {
    if (!frames) return;

    for (size_t i = 0; i < frame_count; ++i) {
        free(frames[i].messages); // Free message payloads and structures
    }
    free(frames);
}

// Example usage
int main() {
    int error_code;
    size_t frame_count = 10000; // Example frame count

    NFAPI_RX_FRAME_T *frames = initialize_nfa_rx_frames(frame_count, &error_code);

    if (frames) {
        printf("Frames initialized successfully.\n");
        cleanup_nfa_rx_frames(frames, frame_count);
    } else {
        fprintf(stderr, "Failed to initialize frames. Error code: %d\n", error_code);
    }

    return 0;
}
