int add_message_to_frame(NFAPI_RX_FRAME_T *frame, RRC_MESSAGE_T *message) {
    if (frame->message_count >= frame->capacity) {
        size_t new_capacity = frame->capacity == 0 ? 4 : frame->capacity * 2;
        if (resize_nfa_rx_frame(frame, new_capacity) != 0)
            return -1;
