    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_RX_FRAME_T **frames = (NFAPI_RX_FRAME_T **)malloc(num_frames * sizeof(NFAPI_RX_FRAME_T *));
