    for (size_t i = 0; i < num_frames; ++i) {
        frames[i] = init_nfa_rx_frame(4); // Initial capacity of 4 messages
        if (!frames[i]) break;
    }

    size_t total_messages = 0;
    size_t total_payload_size = 0;

    while (total_messages < max_messages && total_payload_size < payload_threshold) {
        RRC_MESSAGE_T *message = (RRC_MESSAGE_T *)malloc(sizeof(RCC_MESSAGE_T));
        if (!message) break;

        message->payload_size = rand() % 256 + 1; // Random size between 1 and 256
        message->payload = (uint8_t *)malloc(message->payload_size);
        if (!message->payload) {
            free(message);
            break;
        }

        memcpy(message->payload, "Valid Payload", message->payload_size < 14 ? message->payload_size : 13); // Mock payload

        pthread_mutex_lock(&lock);
        size_t frame_index = total_messages % num_frames; // Round-robin distribution
        if (add_message_to_frame(frames[frame_index], message) != 0) {
            free_rrc_message(message);
        } else {
            total_messages++;
            total_payload_size += message->payload_size;
        }
        pthread_mutex_unlock(&lock);

        // Simulate external validation delay
        struct timespec wait_time = {0, 10000000}; // 10ms nanosecond sleep
        nanosleep(&wait_time, NULL);
    }

    return frames; // Caller responsible for freeing resources
}

void free_nfa_rx_frames(NFAPI_RX_FRAME_T **frames, size_t num_frames) {
    if (!frames) return;

    for (size_t i = 0; i < num_frames; ++i) {
        free_nfa_rx_frame(frames[i]);
    }

    free(frames);
}
