typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    array->size = 0;
    return array;
}

int is_rnti_unique(DynamicArray* array, unsigned short rnti) {
    Node* current = array->head;
    while (current) {
        if (current->data.RNTI == rnti)
            return 0; // Not unique
        current = current->next;
    }
    return 1; // Unique
}

int add_structure(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!is_rnti_unique(array, new_data.RNTI)) {
        fprintf(stderr, "Error: RNTI %u already exists.\n", new_data.RNTI);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        return -2;
    }

    new_node->data = new_data;
    new_node->next = array->head;
    array->head = new_node;
    array->size++;

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_structure(DynamicArray* array, unsigned short rnti) {
    Node* current = array->head;
    while (current) {
        if (current->data.RNTI == rnti)
            return &current->data;
        current = current->next;
    }
    fprintf(stderr, "Error: RNTI %u not found.\n", rnti);
    return NULL; // Not found
}

int remove_structure(DynamicArray* array, unsigned short rnti) {
    Node *current = array->head, *prev = NULL;

    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                array->head = current->next;

            free(current);
            array->size--;
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    fprintf(stderr, "Error: RNTI %u not found.\n", rnti);
    return -1; // Not found
}

void iterate_structures(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = array->head;
    while (current) {
        callback(&current->data);
        current = current->next;
    }
}

void free_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(array);
}

// Example usage callback
void print_structure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
