#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_PDUS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI; // Assume RNTI is an integer for simplicity.
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus[MAX_PDUS];
    atomic_int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    _Bool pool_initialized; // Memory pool status
} PduPool;

PduPool pdu_pool = { .size = 0, .pool_initialized = 0 };

// Logging function stub (to be integrated with existing framework)
void log_info(const char* message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(int rnti) {
    pthread_mutex_lock(&pdu_pool.lock);

    if (!pdu_pool.pool_initialized) {
        for (int i = 0; i < MAX_PDUS; ++i)
            pdu_pool.pdus[i] = NULL;
        pdu_pool.pool_initialized = 1;

        log_info("Initialized PDU pool.");
    }

    // Ensure unique RNTI
    for (int i = 0; i < pdu_pool.size; ++i) {
        if (pdu_pool.pdus[i]->RNTI == rnti) {
            pthread_mutex_unlock(&pdu_pool.lock);
            log_info("Duplicate RNTI found. Allocation failed.");
            return NULL;
        }
    }

    // Allocate PDU
    if (pdu_pool.size < MAX_PDUS) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            log_info("Memory allocation failed.");
            pthread_mutex_unlock(&pdu_pool.lock);
            return NULL;
        }

        new_pdu->RNTI = rnti;
        // Initialize other fields
        memset(new_pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        pdu_pool.pdus[pdu_pool.size++] = new_pdu;

        log_info("PDU allocated successfully.");
    } else {
        log_info("Reached maximum PDU limit. Allocation failed.");
        pthread_mutex_unlock(&pdu_pool.lock);
        return NULL;
    }

    pthread_mutex_unlock(&pdu_pool.lock);
    return new_pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    pthread_mutex_lock(&pdu_pool.lock);

    for (int i = 0; i < pdu_pool.size; ++i) {
        if (pdu_pool.pdus[i] == pdu) {
            free(pdu);
            // Remove from the array
            memmove(&pdu_pool.pdus[i], &pdu_pool.pdus[i + 1],
                    sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (pdu_pool.size - i - 1));
            --pdu_pool.size;

            log_info("PDU deallocated successfully.");
            break;
        }
    }

    pthread_mutex_unlock(&pdu_pool.lock);
}

void initialize_pool() {
    pthread_mutex_init(&pdu_pool.lock, NULL);
    pthread_cond_init(&pdu_pool.cond, NULL);

    log_info("PDU pool and synchronization primitives initialized.");
}

void cleanup_pool() {
    pthread_mutex_lock(&pdu_pool.lock);

    for (int i = 0; i < pdu_pool.size; ++i) {
        free(pdu_pool.pdus[i]);
    }

    pthread_mutex_unlock(&pdu_pool.lock);

    pthread_mutex_destroy(&pdu_pool.lock);
    pthread_cond_destroy(&pdu_pool.cond);

    log_info("PDU pool and synchronization primitives destroyed.");
}

// Testing setup
int main() {
    initialize_pool();

    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu(12345); // Example RNTI
    if (pdu) {
        // Use the PDU...
    }

    free_pdu(pdu);

    cleanup_pool();
    return 0;
}
```

