    new_node->next = array->head;
    array->head = new_node;
    array->count++;
    array->cumulative_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (array->cumulative_size > array->max_size) {
        array->max_size = array->cumulative_size;
    }

