        if (current->data.RNTI == rnti) {
            if (prev) prev->next = current->next;
            else array->head = current->next;

            free(current);
            array->count--;
            array->cumulative_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);

            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    return -1; // Not found
}

// Implement batch operations, priority handling, and other features as needed

void print_statistics(DynamicArray* array) {
    printf("Total Structures: %d\n", array->count);
    printf("Cumulative Size: %zu bytes\n", array->cumulative_size);
    printf("Max Size: %zu bytes\n", array->max_size);
    printf("Cache Hits: %lu, Cache Misses: %lu\n", array->cache_hits, array->cache_misses);
}

// Usage example
int main() {
    DynamicArray* array = init_dynamic_array();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = 10, .priority = 5 };
    add_structure(array, pdu1);

    print_statistics(array);

    remove_structure(array, 100);
    free_dynamic_array(array);

    return 0;
}
```

This implementation uses a singly linked list for simplicity and efficient memory management with a custom memory pool. It includes basic operations to add, find, and remove structures while maintaining unique `RNTI` values. The code also tracks statistics like cache hits/misses and cumulative size.

You can extend this base by implementing batch operations, priority handling, and further optimizing for concurrency as needed.']

