// Main function to manage the list of structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t count) {
    if (count == 0) return NULL;

    // Dynamically allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
