        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        validate_memory(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    log_message("INFO", "List created successfully.");
    return list;
}

// Validate memory bounds and alignment
void validate_memory(NFAPI_CRC_INDICATION_PDU_T *element, size_t element_size) {
    if (!element || (uintptr_t(element) % sizeof(void*) != 0)) {
        log_message("WARNING", "Memory validation failed: misalignment or NULL pointer.");
    }
}

// Serialize list to binary format
void serialize_list(const NFAPI_CRC_INDICATION_PDU_T *list, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message("ERROR", "Failed to open file for serialization.");
        return;
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    fclose(file);

    log_message("INFO", "Serialization completed successfully.");
}

// Filter list by RNTI range
size_t filter_list_by_rnti_range(NFAPI_CRC_INDICATION_PDU_T **list, size_t *count, unsigned short min_rnti, unsigned short max_rnti) {
    if (!*list || !count) return 0;

    size_t original_count = *count;
    size_t filtered_index = 0;

    for (size_t i = 0; i < original_count; ++i) {
        if ((*list)[i].RNTI >= min_rnti && (*list)[i].RNTI <= max_rnti) {
            (*list)[filtered_index++] = (*list)[i];
        }
    }

    *count = filtered_index;
    log_message("INFO", "Filtering by RNTI range completed.");
    return filtered_index;
}

// Free allocated list
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        free(list);
        log_message("INFO", "Memory freed successfully.");
    }
}

// Thread-safe wrapper for list operations
NFAPI_CRC_INDICATION_PDU_T* thread_safe_create_nfa_list(size_t count) {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *result = create_nfa_list(count);
    pthread_mutex_unlock(&list_mutex);

    return result;
}

