    char *password;
} UserAccount;

#define MAX_USERS 100

UserAccount userAccounts[MAX_USERS];
int currentSize = 0;

// Helper function to find a user by ID
UserAccount* findUserById(int id) {
    for (int i = 0; i < currentSize; ++i) {
        if (userAccounts[i].id == id) {
            return &userAccounts[i];
        }
    }
    return NULL;
}

// Helper function to validate user data against schema
int isValidUserData(const char *name, const char *email, const char *password) {
    // Basic validation logic (expand as needed)
    if (!name || strlen(name) == 0) return 0;
    if (!email || strchr(email, '@') == NULL) return 0;
    if (!password || strlen(password) < 6) return 0;
    return 1;
}

// Function to create or update a user account
json_t* createOrUpdateUserAccount(json_t *request) {
    json_error_t error;

    int id = request ? json_integer_value(json_object_get(request, "id")) : -1;
    const char *name = json_string_value(json_object_get(request, "name"));
    const char *email = json_string_value(json_object_get(request, "email"));
    const char *password = json_string_value(json_object_get(request, "password"));
    const char *sub_action = json_string_value(json_object_get(request, "sub_action"));

    if (!name || !email || !password) {
        return json_pack("{s:s}", "message", "error");
    }

    UserAccount *user;
    if (id != -1 && sub_action && strcmp(sub_action, "update") == 0) {
        user = findUserById(id);
        if (!user) {
            return json_pack("{s:s}", "message", "error: user not found");
        }
    } else {
        if (currentSize >= MAX_USERS) {
            return json_pack("{s:s}", "message", "error: max users reached");
        }
        user = &userAccounts[currentSize++];
        user->id = id != -1 ? id : currentSize; // Assign new ID if not provided
    }

    if (!isValidUserData(name, email, password)) {
        return json_pack("{s:s}", "message", "error: invalid data");
    }

    free(user->name);
    free(user->email);
    free(user->password);

    user->name = strdup(name);
    user->email = strdup(email);
    user->password = strdup(password);

    if (!user->name || !user->email || !user->password) {
        // Handle memory allocation failure
        free(user->name);
        free(user->email);
        free(user->password);
        return json_pack("{s:s}", "message", "error: memory allocation failed");
    }

    return json_pack("{s:s}", "message", "success");
}

int main() {
    // Example usage
    json_t *request = json_loads("{\"id\": 1, \"name\": \"John Doe\", \"email\": \"john@example.com\", \"password\": \"secure123\", \"sub_action\": \"update\"}", 0, NULL);
    json_t *response = createOrUpdateUserAccount(request);

    printf("%s\n", json_dumps(response, JSON_INDENT(2)));
    json_decref(request);
    json_decref(response);

    return 0;
}
