            #endif
            list->error = true;
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            release_rnti(rnti);
            #ifdef LOGGING_ENABLED
