        pthread_mutex_unlock(&list->lock);

    #ifdef LOGGING_ENABLED
        printf("Allocated RNTI: %d, CRCFLAG: %d\n", rnti, pdu->CRCFLAG);
    #endif
    }

    if (!list->error) {
        #ifdef LOGGING_ENABLED
        printf("Successfully allocated %d PDUs\n", list->num_pdu);
        #endif
    }
}

int main() {
    srand(time(NULL));
    PDUList *pdu_list = create_pdu_list(10);
    populate_pdu_list(pdu_list, 15);

    if (pdu_list->error) {
        destroy_pdu_list(pdu_list);
        cleanup_rnti_pool();
        return -1;
    }

    // Use the populated list...

    destroy_pdu_list(pdu_list);
    cleanup_rnti_pool();

