```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a task structure
typedef struct Task {
    int id;
    char description[256];
    time_t deadline;
    int completed;
} Task;

// Define a list node
typedef struct ListNode {
    Task *task;
    struct ListNode *next;
} ListNode;

// Define the task list
typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} TaskList;

// Function prototypes
TaskList* create_task_list();
void destroy_task_list(TaskList *list);
int add_task(TaskList *list, const char *description, time_t deadline);
int remove_task(TaskList *list, int id);
int update_task(TaskList *list, int id, const char *description, time_t deadline, int completed);
void summarize_tasks(const TaskList *list);

// Create a new task list
TaskList* create_task_list() {
    TaskList *list = (TaskList*)malloc(sizeof(TaskList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the task list and free memory
void destroy_task_list(TaskList *list) {
    ListNode *current = list->head;
    while (current) {
        ListNode *next = current->next;
        free(current->task);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new task
int add_task(TaskList *list, const char *description, time_t deadline) {
    pthread_mutex_lock(&list->lock);

    Task *new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_task->id = rand();  // Simple ID generation
    strncpy(new_task->description, description, sizeof(new_task->description));
    new_task->deadline = deadline;
    new_task->completed = 0;

    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        free(new_task);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->task = new_task;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove a task by ID
int remove_task(TaskList *list, int id) {
    pthread_mutex_lock(&list->lock);

    ListNode **current = &list->head;
    while (*current) {
        if ((*current)->task->id == id) {
            ListNode *to_delete = *current;
            *current = (*current)->next;
            free(to_delete->task);
            free(to_delete);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Task not found
}

// Update a task by ID
int update_task(TaskList *list, int id, const char *description, time_t deadline, int completed) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current) {
        if (current->task->id == id) {
            strncpy(current->task->description, description, sizeof(current->task->description));
            current->task->deadline = deadline;
            current->task->completed = completed;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Task not found
}

// Provide a summary of tasks
void summarize_tasks(const TaskList *list) {
    time_t now = time(NULL);

    printf("Upcoming and Overdue Tasks:\n");
    ListNode *current = list->head;
    while (current) {
        if (!current->task->completed) {
            char status[20] = "Overdue";
            if (difftime(current->task->deadline, now) > 0) {
                strcpy(status, "Upcoming");
            }
            printf("Task ID: %d, Description: %s, Deadline: %ld, Status: %s\n",
                   current->task->id,
                   current->task->description,
                   current->task->deadline,
                   status);
        }
        current = current->next;
    }
}

// Example usage
int main() {
    TaskList *list = create_task_list();
    if (!list) return 1;

    add_task(list, "Design module", time(NULL) + 86400); // 1 day from now
    add_task(list, "Implement feature", time(NULL) - 86400); // 1 day ago

    summarize_tasks(list);

    remove_task(list, list->head->task->id);
    summarize_tasks(list);

    destroy_task_list(list);
    return 0;
}
```

### Key Points:
