#define MAX_LOG_MESSAGE_LENGTH 256

typedef struct {
    time_t LOG_TIMESTAMP;
    int LOG_LEVEL;
    char LOG_MESSAGE[MAX_LOG_MESSAGE_LENGTH];
} LOG_RECORD_T;

// Mock external logging service for timestamp generation
time_t get_current_timestamp() {
    return time(NULL);
}

LOG_RECORD_T* allocate_log_records(size_t M) {
    if (M == 0) return NULL;

    LOG_RECORD_T *log_records = NULL;
    size_t attempt_size;

    // Try to allocate memory and handle allocation failure gracefully
    for (attempt_size = M; attempt_size > 0; attempt_size /= 2) {
        log_records = malloc(attempt_size * sizeof(LOG_RECORD_T));
        if (log_records != NULL) break;

        printf("Memory allocation failed, retrying with smaller size...\n");
    }

    // Check for ultimate failure after attempts
    if (log_records == NULL) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    void initialize_log_record(LOG_RECORD_T *record) {
        pthread_mutex_lock(&lock);
        record->LOG_TIMESTAMP = get_current_timestamp();
        record->LOG_LEVEL = 0; // Default level
        memset(record->LOG_MESSAGE, 0, MAX_LOG_MESSAGE_LENGTH);
        pthread_mutex_unlock(&lock);
    }

    for (size_t i = 0; i < attempt_size; ++i) {
        initialize_log_record(&log_records[i]);
    }

    return log_records;
}

void free_log_records(LOG_RECORD_T *records) {
    if (records != NULL) {
        free(records);
    }
}
```

