// Define the structure as per LTE specification format
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_FLAG; // Assuming 1 byte for CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node structure for doubly-linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
    struct ListNode* prev;
} ListNode;

// Function to initialize and populate the list
ListNode* init_and_populate_list(size_t num_nodes) {
    if (num_nodes == 0) return NULL;

    // Initialize random seed for CRCFLAG generation
    srand((unsigned int)time(NULL));

    ListNode *head = malloc(sizeof(ListNode));
    if (!head) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    head->prev = NULL;
    ListNode *current = head;

    for (size_t i = 0; i < num_nodes; ++i) {
        ListNode *new_node = malloc(sizeof(ListNode));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            // Clean up previously allocated nodes
            while (head != NULL) {
                ListNode *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_node->data.RX_UE_INFORMATION_TAG = (uint16_t)(rand() % 65536); // Example tag generation
        new_node->data.RNTI = (uint16_t)(rand() % 65536); // Example RNTI generation
        new_node->data.CRC_FLAG = (uint8_t)(rand() & 1); // Random CRCFLAG

        new_node->next = NULL;
        if (i < num_nodes - 1) {
            current->next = new_node;
            new_node->prev = current;
            current = new_node;
        } else {
            current->next = new_node;
            new_node->prev = current;
        }
    }

    return head;
}

// Function to free the list
void free_list(ListNode* head) {
    ListNode *current = head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }
}

// Example usage of the above functions
int main() {
    size_t num_nodes = 10; // Number of nodes to initialize
    ListNode* list_head = init_and_populate_list(num_nodes);

    if (list_head) {
        // List is initialized and populated successfully
        ListNode *current = list_head;
        while (current != NULL) {
            printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_FLAG: %d\n",
                   current->data.RX_UE_INFORMATION_TAG,
                   current->data.RNTI,
                   current->data.CRC_FLAG);
            current = current->next;
        }

        // Free the list
        free_list(list_head);
    } else {
        fprintf(stderr, "Failed to initialize and populate the list\n");
    }

    return 0;
}
