    char measurement_object[256];
    double measurement_value;
    int qos_priority_level; // Optional
} LTE_RRC_EUTRA_MEASUREMENT_REPORT;

typedef struct {
    int rnti;
    int rx_ue_information_tag;
    int crc_indication_rel8_tag;  // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Priority Queue Node
typedef struct {
    LTE_RRC_EUTRA_MEASUREMENT_REPORT report;
    int qos_priority_level;
} PriorityQueueNode;

// Priority Queue Structure
typedef struct {
    PriorityQueueNode *nodes;
    int size;
    int capacity;
} PriorityQueue;

// Thread Safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Global Data Structures
PriorityQueue pq;
NFAPI_CRC_INDICATION_PDU_T crc_indications[MAX_REPORTS];

// Function Prototypes
void initialize_priority_queue(PriorityQueue *pq, int capacity);
void enqueue_report(PriorityQueue *pq, LTE_RRC_EUTRA_MEASUREMENT_REPORT report, int qos_priority_level);
LTE_RRC_EUTRA_MEASUREMENT_REPORT dequeue_report(PriorityQueue *pq);
void compress_reports();
void log_operation(const char* message);

// Initialize the Priority Queue
void initialize_priority_queue(PriorityQueue *pq, int capacity) {
    pq->nodes = (PriorityQueueNode *)malloc(sizeof(PriorityQueueNode) * capacity);
    pq->size = 0;
    pq->capacity = capacity;
}

// Enqueue Report with QoS Priority
void enqueue_report(PriorityQueue *pq, LTE_RRC_EUTRA_MEASUREMENT_REPORT report, int qos_priority_level) {
    pthread_mutex_lock(&mutex);

    if (pq->size == pq->capacity) {
        log_operation("Priority Queue Full, Compressing...");
        compress_reports();
    }

    // Insert into PriorityQueue based on QoS priority level
    int i = pq->size - 1;
    while (i >= 0 && pq->nodes[i].qos_priority_level < qos_priority_level) {
        if (i + 1 < pq->capacity) {
            pq->nodes[i + 1] = pq->nodes[i];
        }
        i--;
    }

    pq->nodes[i + 1] = (PriorityQueueNode){.report = report, .qos_priority_level = qos_priority_level};
    pq->size++;

    pthread_mutex_unlock(&mutex);
}

// Dequeue Report from Priority Queue
LTE_RRC_EUTRA_MEASUREMENT_REPORT dequeue_report(PriorityQueue *pq) {
    pthread_mutex_lock(&mutex);

    if (pq->size == 0) {
        log_operation("Priority Queue Empty");
        pthread_mutex_unlock(&mutex);
        return (LTE_RRC_EUTRA_MEASUREMENT_REPORT){0}; // Return invalid report
    }

    LTE_RRC_EUTRA_MEASUREMENT_REPORT report = pq->nodes[0].report;
    for (int i = 1; i < pq->size; i++) {
        if (i < pq->capacity) {
            pq->nodes[i - 1] = pq->nodes[i];
        }
    }

    pq->size--;
    pthread_mutex_unlock(&mutex);

    return report;
}

// Function to Compress Reports
void compress_reports() {
    // Logic for compression when exceeding threshold
    log_operation("Compressed reports based on defined criteria.");
}

// Log Operation for monitoring and error handling
void log_operation(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Main Function to Simulate Processing
int main() {
    initialize_priority_queue(&pq, QUEUE_SIZE);

    // Simulation of processing reports
    for (int i = 0; i < MAX_REPORTS; i++) {
        LTE_RRC_EUTRA_MEASUREMENT_REPORT report = {
            .valid = 1,
            .measurement_object = "Object",
            .measurement_value = rand() % 100,
            .qos_priority_level = rand() % 10
        };

        enqueue_report(&pq, report, report.qos_priority_level);
    }

    // Dequeue all reports for processing
    while (pq.size > 0) {
        LTE_RRC_EUTRA_MEASUREMENT_REPORT report = dequeue_report(&pq);

        if (report.valid) {
            NFAPI_CRC_INDICATION_PDU_T pdu = {
                .rnti = rand(),
                .rx_ue_information_tag = rand(),
                .crc_indication_rel8_tag = rand() % 256
            };
            // Process PDU
        }
    }

    free(pq.nodes);
    return 0;
}
```

