#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure definitions
typedef struct {
    size_t length;
    void *data;
} PHY_TransformConfig;

typedef struct {
    PHY_TransformConfig config;
    // Additional fields can be added here
} LTEPHY_TransformData;

// Node for the linked list
typedef struct TransformNode {
    LTEPHY_TransformData transform;
    struct TransformNode* next;
} TransformNode;

// Dynamic array structure with thread-safe operations
typedef struct {
    TransformNode* head;
    TransformNode* tail;
    pthread_rwlock_t lock; // Read-write lock for concurrency control
} TransformArray;

// Function prototypes
TransformArray* create_transform_array();
void add_transform(TransformArray* array, LTEPHY_TransformData transform);
LTEPHY_TransformData remove_transform(TransformArray* array, int index);
int iterate_transforms(const TransformArray* array, void (*func)(const LTEPHY_TransformData*, void*), void* arg);

// Create a new dynamic array
TransformArray* create_transform_array() {
    TransformArray* array = malloc(sizeof(TransformArray));
    if (!array) return NULL;

    array->head = NULL;
    array->tail = NULL;
    pthread_rwlock_init(&array->lock, NULL);
    return array;
}

// Add a transform to the dynamic array
void add_transform(TransformArray* array, LTEPHY_TransformData transform) {
    TransformNode* new_node = malloc(sizeof(TransformNode));
    if (!new_node) return;

    new_node->transform = transform;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&array->lock);
    if (array->tail) {
        array->tail->next = new_node;
        array->tail = new_node;
    } else {
        array->head = array->tail = new_node;
    }
    pthread_rwlock_unlock(&array->lock);
}

// Remove a transform from the dynamic array by index
LTEPHY_TransformData remove_transform(TransformArray* array, int index) {
    TransformNode *prev = NULL, *current = array->head;

    pthread_rwlock_wrlock(&array->lock);

    for (int i = 0; current != NULL && i < index; ++i) {
        prev = current;
        current = current->next;
    }

    LTEPHY_TransformData removed_transform = {0};

    if (current == NULL) {
        pthread_rwlock_unlock(&array->lock);
        return removed_transform;
    }

    if (prev == NULL) {
        array->head = current->next;
    } else {
        prev->next = current->next;
    }

    if (current == array->tail) {
        array->tail = prev;
    }

    removed_transform = current->transform;

    free(current);
    pthread_rwlock_unlock(&array->lock);

    return removed_transform;
}

// Iterate over the transforms
int iterate_transforms(const TransformArray* array, void (*func)(const LTEPHY_TransformData*, void*), void* arg) {
    int index = 0;
    const TransformNode *current;

    pthread_rwlock_rdlock(&array->lock);
    current = array->head;

    while (current != NULL) {
        func(&(current->transform), arg);
        current = current->next;
        ++index;
    }
    pthread_rwlock_unlock(&array->lock);

    return index;
}

// Example function to free resources
void destroy_transform_array(TransformArray* array) {
    if (!array) return;

    TransformNode *node = array->head, *tmp;

    pthread_rwlock_wrlock(&array->lock);
    while (node != NULL) {
        tmp = node->next;
        free(node->transform.config.data); // Free the buffer
        free(node);
        node = tmp;
    }
    pthread_rwlock_unlock(&array->lock);

    pthread_rwlock_destroy(&array->lock);
    free(array);
}

// Example usage
void print_transform(const LTEPHY_TransformData* transform, void* arg) {
    (void)arg;  // Unused parameter
    printf("Transform data length: %zu\n", transform->config.length);
}

int main() {
    TransformArray* array = create_transform_array();

    // Create and add some transforms
    for (size_t i = 0; i < 5; ++i) {
        LTEPHY_TransformData transform;
        transform.config.data = malloc(10 * sizeof(int));  // Example buffer allocation
        transform.config.length = 10;

        add_transform(array, transform);
    }

    iterate_transforms(array, print_transform, NULL);

    destroy_transform_array(array);
    return 0;
}
```

This code implements a thread-safe dynamic array using a linked list and read-write locks. It provides functions to add, remove, and iterate over `LTEPHY_TransformData` structures while ensuring memory is managed correctly with respect to allocation and deallocation of the data buffers within each structure.']

