#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1000
#define MAX_POOL_SIZE 10000

typedef struct {
    uint8_t rx_ue_information_tag;
    uint16_t rnti;
    uint32_t crc_indication_rel8_tag;
    int crcflag; // Randomly set to either 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    size_t pool_size;
    Node** pool;
} CrcIndicationList;

// Function to initialize the list
void initCrcIndicationList(CrcIndicationList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->pool_size = INITIAL_POOL_SIZE;
    list->pool = (Node**)malloc(list->pool_size * sizeof(Node*));
    for (size_t i = 0; i < list->pool_size; ++i) {
        list->pool[i] = (Node*)malloc(sizeof(Node));
    }
}

// Function to free the list
void freeCrcIndicationList(CrcIndicationList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    for (size_t i = 0; i < list->pool_size; ++i) {
        free(list->pool[i]);
    }
    free(list->pool);
    pthread_mutex_destroy(&list->lock);
}

// Function to get a node from the pool
Node* getNodeFromPool(CrcIndicationList* list) {
    if (list->size < list->pool_size) {
        return list->pool[list->size++];
    } else {
        // Pool is full, resize if possible
        if (list->pool_size < MAX_POOL_SIZE) {
            size_t new_pool_size = list->pool_size * 2;
            Node** new_pool = (Node**)realloc(list->pool, new_pool_size * sizeof(Node*));
            for (size_t i = list->pool_size; i < new_pool_size; ++i) {
                new_pool[i] = (Node*)malloc(sizeof(Node));
            }
            list->pool = new_pool;
            list->pool_size = new_pool_size;
        } else {
            // Pool cannot be resized further
            return NULL;
        }
    }
    return getNodeFromPool(list);
}

// Function to insert a node into the list
void insertCrcIndication(CrcIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = getNodeFromPool(list);
    if (new_node == NULL) {
        // Handle pool overflow gracefully
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    // Log the operation (assuming a logging function is available)
    // logOperation("Insert", pdu);

    pthread_mutex_unlock(&list->lock);
}

// Function to generate a random CRC flag
int getRandomCrcFlag() {
    return rand() % 2;
}

// Example usage of the list
void processNetworkData(CrcIndicationList* list) {
    srand(time(NULL));
    for (size_t i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_information_tag = rand() % 256;
        pdu.rnti = rand() % 65536;
        pdu.crc_indication_rel8_tag = rand();
        pdu.crcflag = getRandomCrcFlag();

        insertCrcIndication(list, pdu);
    }
}

int main() {
    CrcIndicationList list;
    initCrcIndicationList(&list);

    processNetworkData(&list);

    freeCrcIndicationList(&list);
    return 0;
}
