    snprintf(config.ip_address, sizeof(config.ip_address), "%d.%d.%d.%d",
             rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    snprintf(config.subnet_mask, sizeof(config.subnet_mask), "%d.%d.%d.%d",
             (rand() % 2) ? 255 : 0, (rand() % 2) ? 255 : 0,
             (rand() % 2) ? 255 : 0, (rand() % 2) ? 255 : 0);
    snprintf(config.gateway, sizeof(config.gateway), "%d.%d.%d.%d",
             rand() % 256, rand() % 256, rand() % 256, rand() % 256);

    config.active_services = malloc(50); // Placeholder for actual size
    if (config.active_services) {
        snprintf(config.active_services, 50, "service%d", rand() % 100);
    }

    return config;
}

int populate_cache(int seed, int initial_pool_size) {
    pool_size = initial_pool_size > 0 ? initial_pool_size : DEFAULT_POOL_SIZE;

    cache_pool = malloc(pool_size * sizeof(CacheEntry));
    if (!cache_pool) {
        log_message("Memory allocation failed for cache pool.");
        return 0;
    }

    pthread_mutex_init(&global_lock, NULL);

    int success_count = 0;
    for (size_t i = 0; i < pool_size; ++i) {
        pthread_mutex_init(&cache_pool[i].lock, NULL);
        cache_pool[i].in_use = 0;

        NETWORK_IF_CONFIG_T config = generate_random_config(seed + i);

        if (config.active_services) {
            log_message("Configuration created successfully.");
            success_count++;
        } else {
            log_message("Failed to allocate memory for active services.");
        }
    }

    return success_count;
}

void free_cache() {
    for (size_t i = 0; i < pool_size; ++i) {
        pthread_mutex_destroy(&cache_pool[i].lock);
        if (cache_pool[i].config.active_services) {
            free(cache_pool[i].config.active_services);
        }
    }
    pthread_mutex_destroy(&global_lock);
    free(cache_pool);
}

int main(int argc, char *argv[]) {
    int seed = time(NULL);
    int initial_pool_size = DEFAULT_POOL_SIZE;

    if (argc > 1) {
        seed = atoi(argv[1]);
    }
    if (argc > 2) {
        initial_pool_size = atoi(argv[2]);
    }

    int success_count = populate_cache(seed, initial_pool_size);
    printf("Successfully initialized %d configurations.\n", success_count);

    free_cache();
    return 0;
}
```

