typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode;

typedef struct {
    PoolNode* head;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    size_t count;
} StructurePool;

StructurePool pool = {NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0};

void log_creation(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Placeholder for logging framework integration
    time_t now = time(NULL);
    printf("Created at %s, CRCFLAG: %d\n", ctime(&now), pdu->crc_indication_rel8_tag.crcflag);
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

uint16_t get_updated_rnti() {
    // Placeholder for external data source integration
    return rand() & 0xFFFF; // Simulate RNTI retrieval
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&pool.lock);

    if (pool.head) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(pool.head->data);
        PoolNode* temp = pool.head;
        pool.head = pool.head->next;
        pool.count--;
        pthread_mutex_unlock(&pool.lock);
        return pdu;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    pthread_mutex_unlock(&pool.lock);
    return pdu;
}

void release_structure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    PoolNode* node = malloc(sizeof(PoolNode));
    if (!node) {
        log_error("Memory allocation failed for pool node");
        free(pdu);
        return;
    }

    memcpy(&(node->data), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_lock(&pool.lock);

    node->next = pool.head;
    pool.head = node;
    pool.count++;

    pthread_cond_signal(&pool.cond_var);
    pthread_mutex_unlock(&pool.lock);
}

int populate_structures(int n) {
    int success_count = 0;

    for (int i = 0; i < n && success_count < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_structure();
        if (!pdu) continue;

        pdu->rx_ue_information_tag = rand(); // Simulate RX_UE_INFORMATION_TAG
        pdu->rnti = get_updated_rnti();
        pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRCFLAG

        log_creation(pdu);
        release_structure(pdu);
        success_count++;
    }

    return success_count;
}

void* rnti_update_thread(void* arg) {
