    if (!list || list->capacity >= MAX_LIST_SIZE) return;

    size_t newCapacity = list->capacity * 2 < MAX_LIST_SIZE ? list->capacity * 2 : MAX_LIST_SIZE;
    NFAPI_CRC_INDICATION_PDU_T* newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
    if (!newData) return;

    list->data = newData;
    list->capacity = newCapacity;
}

bool validateCRCFlags(const DynamicList* list) {
    if (!list || list->size == 0) return true;

    int firstFlag = atoi(list->data[0].CRC_INDICATION_REL8_TAG);
    for (size_t i = 1; i < list->size; ++i) {
        if (atoi(list->data[i].CRC_INDICATION_REL8_TAG) != firstFlag) return false;
    }
    return true;
}

void freeList(DynamicList* list) {
    if (!list || !list->data) return;
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}
