#define MAX_PCI_REPORTS 5000
#define INITIAL_BUFFER_SIZE 100

typedef struct {
    uint16_t cell_id;
    int cqi;
    int mcs;
} PCI_Report;

typedef struct {
    PCI_Report *reports;
    size_t count;
