void log_allocation_failure(const char* message) {}
void log_memory_usage(size_t usage) {}
void log_execution_time(double time_taken) {}

// Function prototypes
PCI_List* create_pci_list();
int add_pci_report(PCI_List *list, uint16_t cell_id, int cqi, int mcs);
void destroy_pci_list(PCI_List *list);
void validate_report(int cqi, int mcs);
void log_error(const char* message);

double get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

PCI_List* create_pci_list() {
    PCI_List *list = malloc(sizeof(PCI_List));
    if (!list) {
        log_allocation_failure("Failed to allocate PCI_List");
        return NULL;
    }
    list->reports = malloc(INITIAL_BUFFER_SIZE * sizeof(PCI_Report));
    if (!list->reports) {
        free(list);
        log_allocation_failure("Failed to allocate initial buffer for PCI reports");
        return NULL;
    }
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_pci_report(PCI_List *list, uint16_t cell_id, int cqi, int mcs) {
    if (cqi < 1 || cqi > 15 || mcs < 0 || mcs > 27) {
        log_error("Invalid CQI or MCS values");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    size_t new_count = list->count + 1;
    if (new_count > list->capacity) {
        size_t new_capacity = (new_count < INITIAL_BUFFER_SIZE * 2) ? INITIAL_BUFFER_SIZE * 2 : new_count;
        PCI_Report *new_reports = realloc(list->reports, new_capacity * sizeof(PCI_Report));
        if (!new_reports) {
            log_allocation_failure("Failed to reallocate buffer for PCI reports");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->reports = new_reports;
        list->capacity = new_capacity;
    }

    PCI_Report report = {cell_id, cqi, mcs};
    list->reports[list->count] = report;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_pci_list(PCI_List *list) {
    if (list) {
        free(list->reports);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void log_error(const char* message) {
    // Log error to a file or monitoring system
    fprintf(stderr, "Error: %s\n", message);
}

void compute_and_log_metrics(PCI_List *list) {
    if (list->count == 0) return;

    int total_cqi = 0;
    int total_mcs = 0;

    for (size_t i = 0; i < list->count; ++i) {
        total_cqi += list->reports[i].cqi;
        total_mcs += list->reports[i].mcs;
    }

    double avg_cqi = (double)total_cqi / list->count;
    double avg_mcs = (double)total_mcs / list->count;

    printf("Average CQI: %.2f, Average MCS: %.2f\n", avg_cqi, avg_mcs);
}

void* pci_report_worker(void *arg) {
    PCI_List *list = (PCI_List*)arg;
    // Simulate adding reports
    for (int i = 0; i < MAX_PCI_REPORTS / 30; ++i) {
        add_pci_report(list, rand() % 1000, rand() % 15 + 1, rand() % 28);
    }
    return NULL;
}

int main() {
    PCI_List *list = create_pci_list();
    if (!list) return -1;

    pthread_t threads[30];
    double start_time = get_current_time();

    for (int i = 0; i < 30; ++i) {
        if (pthread_create(&threads[i], NULL, pci_report_worker, list)) {
            log_error("Failed to create thread");
        }
    }

    for (int i = 0; i < 30; ++i) {
        pthread_join(threads[i], NULL);
    }

    compute_and_log_metrics(list);

    double end_time = get_current_time();
    printf("Execution time: %.2f seconds\n", end_time - start_time);

    destroy_pci_list(list);
    return 0;
}
