// Function to initialize the list
NFAPI_List* nfa_list_init(size_t max_capacity) {
    NFAPI_List* list = malloc(sizeof(NFAPI_List));
    if (!list) return NULL;

    list->head = NULL;
    list->capacity = max_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->current_size = 0;
    return list;
}

// Function to add a new element
bool nfa_list_add(NFAPI_List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->current_size >= list->capacity) return false;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return false;

    *new_node->data = *pdu;
    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);

    // Randomly set CRCFLAG
    if (pthread_self() % 2 == 0) { // Simulate randomness
        pdu->crc_tag.CRCFLAG = true;
    } else {
        pdu->crc_tag.CRCFLAG = false;
    }

    return true;
}

// Function to resize the list
bool nfa_list_resize(NFAPI_List* list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);

    if (new_capacity < list->current_size) {
        pthread_mutex_unlock(&list->lock);
        return false; // Cannot shrink below current size
    }

    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Function to free the list
void nfa_list_free(NFAPI_List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Dummy function to simulate memory usage monitoring
bool is_memory_usage_exceeding_threshold() {
    // For illustration; actual implementation would check system metrics
    return false;
}

// Function to perform garbage collection
void nfa_list_garbage_collect(NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    if (is_memory_usage_exceeding_threshold()) {
        Node* current = list->head;
        while (current && list->current_size > list->capacity / 2) { // Example threshold
            Node* to_delete = current;
            current = current->next;
            free(to_delete);
            list->current_size--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to dynamically reconfigure the maximum allowed size of the list
bool nfa_list_reconfigure_max_capacity(NFAPI_List* list, size_t new_max_capacity) {
    return nfa_list_resize(list, new_max_capacity);
}
