        fprintf(stderr, "Invalid count: %d\n", count);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    bool success = false;

    for (int retries = 0; retries < MAX_RETRIES && !success; ++retries) {
        int allocatedSize = count + (count / 10); // Allocate extra to minimize reallocations
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * allocatedSize);

        if (!array) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        bool uniqueRNTIs[allocatedSize] = { false };
        int filledCount = 0;

        for (int i = 0; i < count; ++i) {
            unsigned int rnti;
            do {
                rnti = rand() % (MAX_RNTI + 1);
            } while (!isValidRNTIRange(rnti) || uniqueRNTIs[rnti]);

            if (filledCount >= allocatedSize / 10) { // Ensure space for more elements
