            array[filledCount].CRCFLAG = rand() % 2 == 0; // Randomly set CRCFLAG

            uniqueRNTIs[rnti] = true;
            filledCount++;
        }

        if (filledCount == count) {
            success = true;
        } else {
            fprintf(stderr, "Retry %d: Not enough unique RNTIs found\n", retries + 1);
            free(array);
            array = NULL;
        }
    }

    if (!success) {
        fprintf(stderr, "Failed to create a valid NFAPI_CRC_INDICATION_PDU_T array after %d retries\n", MAX_RETRIES);
        return NULL;
    }

    // Resize the array to the exact needed size
    array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!array) {
        fprintf(stderr, "Memory reallocation failed\n");
        return NULL;
    }

    printf("Array created successfully with %d unique RNTIs\n", count);
    return array;
