    pthread_mutex_t lock;
} TransportBlockArray;

TransportBlockArray* createTransportBlockArray(size_t initial_capacity) {
    TransportBlockArray* array = (TransportBlockArray*)malloc(sizeof(TransportBlockArray));
    if (!array) return NULL;

    array->blocks = (LTE_DL_FRAME_TRANSPORTBLOCK*)calloc(initial_capacity, sizeof(LTE_DL_FRAME_TRANSPORTBLOCK));
    if (!array->blocks) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int addTransportBlock(TransportBlockArray* array, LTE_DL_FRAME_TRANSPORTBLOCK block) {
    if (!array || !pthread_mutex_lock(&array->lock)) return -1;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->blocks[i].TRANSPORT_BLOCK_ID == block.TRANSPORT_BLOCK_ID) {
            pthread_mutex_unlock(&array->lock);
            return -2; // Duplicate ID
        }
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_DL_FRAME_TRANSPORTBLOCK* new_blocks = (LTE_DL_FRAME_TRANSPORTBLOCK*)realloc(array->blocks, new_capacity * sizeof(LTE_DL_FRAME_TRANSPORTBLOCK));
        if (!new_blocks) {
            pthread_mutex_unlock(&array->lock);
            return -3; // Memory allocation failed
        }
        array->blocks = new_blocks;
        array->capacity = new_capacity;
    }

    array->blocks[array->count++] = block;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int removeTransportBlock(TransportBlockArray* array, int TRANSPORT_BLOCK_ID) {
    if (!array || !pthread_mutex_lock(&array->lock)) return -1;

    size_t index = (size_t)-1;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->blocks[i].TRANSPORT_BLOCK_ID == TRANSPORT_BLOCK_ID) {
            index = i;
            break;
        }
    }

    if (index == (size_t)-1) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Not found
    }

    for (size_t i = index; i < array->count - 1; ++i) {
        array->blocks[i] = array->blocks[i + 1];
    }
    --array->count;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int updateTransportBlock(TransportBlockArray* array, LTE_DL_FRAME_TRANSPORTBLOCK block) {
    if (!array || !pthread_mutex_lock(&array->lock)) return -1;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->blocks[i].TRANSPORT_BLOCK_ID == block.TRANSPORT_BLOCK_ID) {
            array->blocks[i] = block;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -2; // Not found
}

void freeTransportBlockArray(TransportBlockArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);
    free(array->blocks);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}
