#define MAX_INSTANCES 2048

typedef struct {
    uint32_t version;
    // Other RF_RX_FRAME_INFO fields...
} RF_RX_FRAME_INFO;

typedef struct {
    uint16_t DCI_FLAG;
    // Other PDSCH_DCI_INFO fields...
} PDSCH_DCI_INFO;

typedef struct {
    RF_RX_FRAME_INFO frame_info;
    uint8_t rx_pdu_flags;
    PDSCH_DCI_INFO dci_info;
} LTE_PHY_RX_PDU_T;

// Function to generate a valid random DCI_FLAG
uint16_t generate_valid_dci_flag() {
    // Example validation logic; adjust as needed for actual constraints
    return (rand() % 256) | (1 << 10); // Ensuring bit 10 is set, just an example
}

// Memory allocation function with alignment and error handling
LTE_PHY_RX_PDU_T* allocate_lte_phy_rx_pdu_array(size_t count) {
    if (count > MAX_INSTANCES) return NULL;

    size_t size = sizeof(LTE_PHY_RX_PDU_T) * count;
    // Allocate memory aligned to cache line for better performance
    void* ptr = _mm_malloc(size, 64);
    if (!ptr) return NULL; // Handle allocation failure

    LTE_PHY_RX_PDU_T* pdu_array = (LTE_PHY_RX_PDU_T*)ptr;
    pthread_mutex_t lock;

    // Initialize mutex for thread-safe access
    if (pthread_mutex_init(&lock, NULL) != 0) {
        _mm_free(ptr);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        pdu_array[i].frame_info.version = 1; // Initialize with valid values
        pdu_array[i].rx_pdu_flags = rand() & 0xFF; // Example initialization
        pdu_array[i].dci_info.DCI_FLAG = generate_valid_dci_flag();
    }

    return (LTE_PHY_RX_PDU_T*)ptr;
}

// Function to free allocated memory and destroy mutex
void free_lte_phy_rx_pdu_array(LTE_PHY_RX_PDU_T* pdu_array, pthread_mutex_t* lock) {
    if (!pdu_array || !lock) return;

    pthread_mutex_destroy(lock);
    _mm_free(pdu_array); // Free aligned memory
}

// Example usage in a multithreaded environment
void* thread_function(void* arg) {
    LTE_PHY_RX_PDU_T* pdu_array = allocate_lte_phy_rx_pdu_array(1024);
    if (!pdu_array) return NULL;

    // Thread-safe operations using mutex lock
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Simulate processing...

    free_lte_phy_rx_pdu_array(pdu_array, &lock);
    return NULL;
}

int main() {
    pthread_t threads[MAX_INSTANCES];

    for (int i = 0; i < MAX_INSTANCES; ++i) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < MAX_INSTANCES; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
