void insert_measurement_report(LTE_RRC_EUTRA_MEASUREMENT_REPORT* report, int priority) {
    if (queue_size >= MAX_MEASUREMENT_REPORTS) return;

    MeasurementNode* new_node = (MeasurementNode*)malloc(sizeof(MeasurementNode));
    new_node->report = *report;
    new_node->priority = priority;
    new_node->next = NULL;

    // Insert based on priority
    MeasurementNode** current = &priority_queue_head;
    while (*current != NULL && (*current)->priority > priority) {
        current = &(*current)->next;
    }
    new_node->next = *current;
    *current = new_node;
    ++queue_size;
}

void process_measurement_reports(LTE_RRC_EUTRA_MEASUREMENT_REPORT** reports,
                                 size_t* count, int operation, LTE_RRC_EUTRA_MEASUREMENT_REPORT* new_report, size_t batch_size) {
