                reports[*count + i] = new_report + i;
                int priority = rand() % 10; // Simulate dynamic QoS priority level determination
                insert_measurement_report(reports[*count + i], priority);
            }
            *count += batch_size;
            break;

        case 1: // Delete
            for (size_t i = 0; i < batch_size && *count > 0; ++i) {
                free(*reports);
                reports[i] = reports[(*count) - 1];
                (*count)--;
            }
            break;
    }
}

