#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import time.h
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI; // Radio Network Temporary Identifier
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set flag for CRC indication
    time_t last_active_time; // Timestamp of the last activity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *sessions[MAX_SESSIONS];
    int session_count;
    pthread_mutex_t mutex; // Mutex for thread safety
} SessionManager;

// Function to initialize the Session Manager
void initSessionManager(SessionManager *manager) {
    manager->session_count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

// Add a new UE session
int addUESession(SessionManager *manager, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&manager->mutex);

    // Check for existing session with the same RNTI
    for (int i = 0; i < manager->session_count; ++i) {
        if (manager->sessions[i]->RNTI == RNTI) {
            manager->sessions[i]->last_active_time = time(NULL);
            pthread_mutex_unlock(&manager->mutex);
            return 1;
        }
    }

    // Add new session
    if (manager->session_count < MAX_SESSIONS) {
        NFAPI_CRC_INDICATION_PDU_T *new_session = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_session) {
            pthread_mutex_unlock(&manager->mutex);
            return 0; // Memory allocation failure
        }

        new_session->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_session->RNTI = RNTI;
        new_session->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        new_session->CRCFLAG = rand() % 256; // Randomly set CRCFLAG
        new_session->last_active_time = time(NULL);

        manager->sessions[manager->session_count++] = new_session;
    }

    pthread_mutex_unlock(&manager->mutex);
    return (manager->session_count < MAX_SESSIONS);
}

// Remove a UE session by RNTI
void removeUESession(SessionManager *manager, int RNTI) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->session_count; ++i) {
        if (manager->sessions[i]->RNTI == RNTI) {
            free(manager->sessions[i]);
            // Shift remaining sessions
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (manager->session_count - i - 1));
            manager->session_count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Purge inactive sessions
void purgeInactiveSessions(SessionManager *manager) {
    time_t current_time = time(NULL);
    int threshold = 5 * 60; // 5 minutes

    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->session_count; ++i) {
        if (difftime(current_time, manager->sessions[i]->last_active_time) > threshold) {
            free(manager->sessions[i]);
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (manager->session_count - i - 1));
            manager->session_count--;
            --i; // Adjust index after removal
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

