    int rx_timestamp;
    PHY_STATS phy_stats;
    RX_PAYLOAD_INFO rx_payload_info;
} LTEPHY_RX_FRAME_INFO;

typedef struct LTEPHY_TX_FRAME_INFO {
    int tx_timestamp;
    size_t frame_size;
    int transmission_flags;
    int transmission_priority_tag; // Optional
} LTEPHY_TX_FRAME_INFO;

typedef struct PriorityNode {
    LTEPHY_RX_FRAME_INFO *frame_info;
    float priority_metric; // Signal quality metrics, for example
    struct PriorityNode *next;
} PriorityNode;

PriorityNode* priorityQueue[PRIORITY_QUEUE_SIZE];
int queueSize = 0;

// Utility function to insert into the priority queue
void insertIntoPriorityQueue(LTEPHY_RX_FRAME_INFO *frame_info, float priority_metric) {
    if (queueSize >= PRIORITY_QUEUE_SIZE) return; // Handle overflow

    PriorityNode *newNode = (PriorityNode *)malloc(sizeof(PriorityNode));
    newNode->frame_info = frame_info;
    newNode->priority_metric = priority_metric;
    newNode->next = NULL;

    int i = queueSize++;
    while (i > 0 && priorityQueue[(i - 1) / 2]->priority_metric < newNode->priority_metric) {
        priorityQueue[i] = priorityQueue[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    priorityQueue[i] = newNode;
}

// Utility function to manage dynamic arrays
void manageDynamicArrays(LTEPHY_RX_FRAME_INFO **rxFrames, LTEPHY_TX_FRAME_INFO **txFrames,
