        free(newRxFrame);
        return;
    }
    payloadInfo->payload_size = 128; // Example size
    payloadInfo->payload = (unsigned char *)malloc(payloadInfo->payload_size);
    if (!payloadInfo->payload) {
        perror("Failed to allocate memory for RX payload");
        free(payloadInfo);
        free(newRxFrame);
        return;
    }
    memset(payloadInfo->payload, 0xAA, payloadInfo->payload_size); // Example payload

    newRxFrame->rx_payload_info = *payloadInfo;
    free(payloadInfo);

    rxFrames[*rxFrameCount] = newRxFrame;
    (*rxFrameCount)++;

    if (*rxFrameCount > COMPRESSION_THRESHOLD) {
        printf("Compressing RX frames due to high count.\n");
        // Implement compression logic here
    }

    // Add the frame info to priority queue based on some metric
    insertIntoPriorityQueue(newRxFrame, newRxFrame->phy_stats.rssi);

    // Example of adding a new TX_FRAME_INFO
    LTEPHY_TX_FRAME_INFO *newTxFrame = (LTEPHY_TX_FRAME_INFO *)malloc(sizeof(LTEPHY_TX_FRAME_INFO));
    if (!newTxFrame) {
