    newTxFrame->frame_size = 256;         // Example size
    newTxFrame->transmission_flags = 1;   // Example flag

    txFrames[*txFrameCount] = newTxFrame;
    (*txFrameCount)++;
}

// Function to initialize the priority queue
void initPriorityQueue() {
    for (int i = 0; i < PRIORITY_QUEUE_SIZE; ++i) {
        priorityQueue[i] = NULL;
    }
}

// Example function to free memory of dynamic arrays
void cleanup(LTEPHY_RX_FRAME_INFO **rxFrames, LTEPHY_TX_FRAME_INFO **txFrames,
             int rxFrameCount, int txFrameCount) {
    for (int i = 0; i < rxFrameCount; ++i) {
        if (rxFrames[i]) {
