#define MAX_LIST_SIZE 1024

typedef struct {
    uint32_t RNTI;
    // Assume RX_UE_INFORMATION_TAG is a defined structure
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_LIST_SIZE) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    // Simulate random CRCFLAG setting
    srand(time(NULL) ^ (uintptr_t)new_node);
    new_node->data.crc_ind_rel8_tag.CRCFLAG = rand() % 2;

    return 0;
}

int verify_crc(Node* node) {
    if (!node || node->data.crc_ind_rel8_tag.CRCFLAG < 0 || 
        node->data.crc_ind_rel8_tag.CRCFLAG > 1)
        return -1;
    return 0;
}

void integrity_check(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (verify_crc(current)) {
            fprintf(stderr, "CRC verification failed for node\n");
            // Handle the error as needed
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void process_incoming_data(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    insert_node(list, data);
    integrity_check(list);
}

