#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define maximum values based on system specifications.
#define MAX_RNTI 65535
#define INITIAL_CAPACITY 10
#define RETRY_LIMIT 3

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // pseudo-randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety.
pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int *rnti_cache;
    size_t capacity;
    size_t size;
} RNTICache;

RNTICache rnti_cache = {NULL, 0, 0};

int is_valid_rnti(unsigned short rnti) {
    // Simulated external data source check (for example purposes).
    return rnti > 0 && rnti <= MAX_RNTI;
}

void initialize_rnti_cache(size_t capacity) {
    pthread_mutex_lock(&array_mutex);
    if (rnti_cache.capacity < capacity) {
        free(rnti_cache.rnti_cache);
        rnti_cache.rnti_cache = calloc(capacity, sizeof(int));
        rnti_cache.capacity = capacity;
        memset(rnti_cache.rnti_cache, 0, capacity * sizeof(int));
    }
    pthread_mutex_unlock(&array_mutex);
}

int check_and_store_rnti(unsigned short rnti) {
    if (rnti > rnti_cache.capacity)
        return -1;

    pthread_mutex_lock(&array_mutex);
    int result = rnti_cache.rnti_cache[rnti];
    rnti_cache.rnti_cache[rnti] = 1;
    pthread_mutex_unlock(&array_mutex);

    return result;
}

void free_rnti_cache() {
    pthread_mutex_lock(&array_mutex);
    if (rnti_cache.rnti_cache) {
        free(rnti_cache.rnti_cache);
        rnti_cache.rnti_cache = NULL;
    }
    pthread_mutex_unlock(&array_mutex);
}

int generate_unique_rnti(size_t *capacity, int retries) {
    unsigned short rnti;
    for (size_t i = 0; i < retries && i <= *capacity; ++i) {
        do {
            rnti = rand() % MAX_RNTI + 1;
        } while (!is_valid_rnti(rnti) || check_and_store_rnti(rnti));

        return rnti;
    }
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* manage_crc_array(size_t *size, int retries) {
    size_t capacity = INITIAL_CAPACITY;
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array)
        return NULL;

    srand(time(NULL)); // Seed random number generator
    initialize_rnti_cache(MAX_RNTI);

    for (size_t i = 0; i < *size; ++i) {
        int retry_count = 0;
        NFAPI_CRC_INDICATION_PDU_T pdu;

        do {
            unsigned short rnti = generate_unique_rnti(&capacity, retries);
            if (rnti == -1) {
                printf("Failed to allocate unique RNTI after %d retries\n", retry_count);
                break;
            }
            pdu.RX_UE_INFORMATION_TAG = rand(); // Example initialization
            pdu.RNTI = rnti;
            pdu.CRC_INDICATION_REL8_TAG = rand() & 0xFF; // Example initialization
            pdu.CRCFLAG = rand() % 2;

            if (array[i].RNTI == 0) {
                array[i] = pdu;
                break;
            }
        } while (++retry_count < retries);

        // Dynamic resizing if capacity is reached.
        if (i + 1 >= capacity && i < *size - 1) {
            size_t new_capacity = capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) {
                printf("Failed to reallocate array\n");
                free(array);
                free_rnti_cache();
                return NULL;
            }
            array = new_array;
            capacity = new_capacity;
        }
    }

    *size = i; // Update size based on actual allocations

    free_rnti_cache();
    return array;
}

// Example usage
int main() {
    size_t array_size = 20;
    NFAPI_CRC_INDICATION_PDU_T* crc_array = manage_crc_array(&array_size, RETRY_LIMIT);

    if (crc_array) {
        for (size_t i = 0; i < array_size; ++i) {
            printf("RNTI: %u, CRCFLAG: %d\n", crc_array[i].RNTI, crc_array[i].CRCFLAG);
        }
        free(crc_array);
    }

    return 0;
}
