}

NFAPI_CRC_INDICATION_PDU_T* initialize_pdu_array(size_t max_size) {
    size_t i;
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;

    if (max_size > MAX_NFAPI_CRC_INDIGATION_PDU_T_SIZE) {
        log_performance_metrics("Exceeded maximum allowable PDU array size.");
        return NULL;
    }

    pdu_array = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        log_performance_metrics("Memory allocation failed for PDU array.");
        return NULL;
    }

    pthread_rwlock_wrlock(&rwlock);

    for (i = 0; i < max_size; ++i) {
        PduHashEntry *entry = malloc(sizeof(PduHashEntry));
        if (!entry) {
            log_performance_metrics("Memory allocation failed for hash map entry.");
            break;
        }

        pthread_mutex_init(&entry->lock, NULL);

        // Initialize the structure with unique identifiers
        entry->pdu.RX_UE_INFORMATION_TAG = rand();  // Randomly generate a unique tag
        entry->pdu.RNTI = rand() % 65536;           // Random RNTI (0 to 65535)
        entry->pdu.CRC_INDICATION_REL8_TAG = rand() % 2;  // Random binary flag

        HASH_ADD_INT(pdu_map, pdu.RX_UE_INFORMATION_TAG, entry);
    }

    if (i < max_size) {
        // Clean up on partial initialization
        while (pdu_map) {
            PduHashEntry *current_entry = pdu_map;
            HASH_DEL(pdu_map, current_entry);
            pthread_mutex_destroy(&current_entry->lock);
            free(current_entry);
        }
        free(pdu_array);
        log_performance_metrics("Failed to initialize all PDUs. Rolled back.");
    } else {
        // Successfully initialized
        log_performance_metrics("Successfully initialized PDU array.");
    }

    pthread_rwlock_unlock(&rwlock);

    return pdu_array;
}

void cleanup_pdu_map() {
    pthread_rwlock_wrlock(&rwlock);
    while (pdu_map) {
        PduHashEntry *current_entry = pdu_map;
        HASH_DEL(pdu_map, current_entry);
        pthread_mutex_destroy(&current_entry->lock);
        free(current_entry);
    }
    pthread_rwlock_unlock(&rwlock);
}

int main() {
