    if (pdu_array) {
        printf("PDU array initialized with %zu elements.\n", max_size);
    } else {
        fprintf(stderr, "Failed to initialize PDU array.\n");
    }

    cleanup_pdu_map();
    free(pdu_array);

    return 0;
}
