#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

// Constants for valid ranges (example values)
#define RX_UE_INFORMATION_TAG_MIN 0x1000
#define RX_UE_INFORMATION_TAG_MAX 0xFFFF
#define RNTI_MIN 0x1
#define RNTI_MAX 0xFF

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint8_t RNTI;
    struct {
        _Atomic int CRCFLAG; // Using atomic for thread-safe flag access
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Lock-free linked list header
typedef struct {
    _Atomic(Node*) head;
    pthread_mutex_t mutex; // Fallback lock if necessary
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    atomic_store(&list->head, NULL);
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to check tag validity
int is_valid_tag(uint16_t RX_UE_INFORMATION_TAG, uint8_t RNTI) {
    return (RX_UE_INFORMATION_TAG >= RX_UE_INFORMATION_TAG_MIN &&
            RX_UE_INFORMATION_TAG <= RX_UE_INFORMATION_TAG_MAX &&
            RNTI >= RNTI_MIN && RNTI <= RNTI_MAX);
}

// Function to generate a random value with fallback strategy
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Retry logic or alternative strategies (example: reduced allocation)
        for (int i = 0; i < 5 && !ptr; ++i) {
            ptr = malloc(size / 2); // Example of an alternative strategy
        }
    }
    return ptr;
}

// Function to insert unique elements into the linked list
void populate_linked_list(LinkedList* list, size_t count) {
    Node** last_ptr = &atomic_load(&list->head);
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < count;) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        uint16_t rand_tag = (rand() % (RX_UE_INFORMATION_TAG_MAX - RX_UE_INFORMATION_TAG_MIN + 1)) + RX_UE_INFORMATION_TAG_MIN;
        uint8_t rand_rnti = (rand() % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN;

        if (!is_valid_tag(rand_tag, rand_rnti)) continue;

        // Check for duplicate RNTI
        Node* current = atomic_load(&list->head);
        int is_duplicate = 0;
        while (current) {
            if (current->data.RNTI == rand_rnti) {
                is_duplicate = 1;
                break;
            }
            current = current->next;
        }

        if (!is_duplicate) {
            Node* new_node = safe_malloc(sizeof(Node));
            if (!new_node) continue; // Handle allocation failure gracefully

            pdu.RX_UE_INFORMATION_TAG = rand_tag;
            pdu.RNTI = rand_rnti;
            atomic_store(&pdu.CRC_INDICATION_REL8_TAG.CRCFLAG, rand() % 2);

            new_node->data = pdu;
            new_node->next = NULL;

            *last_ptr = new_node;
            last_ptr = &new_node->next;

            ++i; // Successfully added a unique element
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to iterate and print the linked list contents
void print_linked_list(LinkedList* list) {
    Node* current = atomic_load(&list->head);

    while (current) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               atomic_load(&current->data.CRC_INDICATION_REL8_TAG.CRCFLAG));
        current = current->next;
    }
}

// Function to remove an element by RNTI
void remove_by_rnti(LinkedList* list, uint8_t rnti) {
    Node** current_ptr = &atomic_load(&list->head);

    while (*current_ptr) {
        Node* entry = *current_ptr;

        if (entry->data.RNTI == rnti) {
            *current_ptr = entry->next;
            free(entry);
            return; // Remove only the first occurrence
        }

        current_ptr = &entry->next;
    }
}

void destroy_linked_list(LinkedList* list) {
    Node* current = atomic_load(&list->head);

    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}
