    uint8_t CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_SIZE 10000
#define INITIAL_CAPACITY 1024

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t n, size_t max_size) {
    if (n > MAX_SIZE || n * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_size) {
        fprintf(stderr, "Error: Requested number of elements exceeds limits.\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    size_t capacity = INITIAL_CAPACITY;
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < n; ++i) {
        if (i >= capacity) {
            capacity *= 2;
            NFAPI_CRC_INDICATION_PDU_T* temp = realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!temp) {
                perror("Failed to reallocate memory");
                free(array);
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            array = temp;
        }

        array[i].RX_UE_INFORMATION_TAG = rand() % 0xFFFF; // Simulated valid tag
        array[i].RNTI = rand() % 0xFFFF; // Simulated RNTI value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Simulated tag
        array[i].CRCFLAG = rand() % 2;
        array[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
