#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Assume this is a single byte for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void free_node(Node* node) {
    free(node);
}

int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->count >= MAX_ELEMENTS) return -1; // Full list

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_pdu_by_rnti(CRCList* list, int rnti) {
    if (!list || !rnti) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free_node(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

int update_crcflag(CRCList* list, int rnti, unsigned char new_flag) {
    if (!list || !rnti) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            current->data.CRCFLAG = new_flag;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void free_crc_list(CRCList* list) {
    if (!list) return;

    Node *current = list->head, *next_node = NULL;
    while (current) {
        next_node = current->next;
        free_node(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Dummy cache implementation
typedef struct {
    int rnti_cache[MAX_ELEMENTS];
    unsigned char crcflag_cache[MAX_ELEMENTS];
} RNTICache;

RNTICache* create_rnti_cache() {
    RNTICache* cache = (RNTICache*)malloc(sizeof(RNTICache));
    if (!cache) return NULL;

    memset(cache->rnti_cache, 0, sizeof(int) * MAX_ELEMENTS);
    memset(cache->crcflag_cache, 0, sizeof(unsigned char) * MAX_ELEMENTS);
    return cache;
}

int get_crcflag_from_cache(RNTICache* cache, int rnti) {
