        if (cache->rnti_cache[i] == rnti) {
            return cache->crcflag_cache[i];
        }
    }
    return -1; // Not found
}

void update_crcflag_in_cache(RNTICache* cache, int rnti, unsigned char crcflag) {
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (cache->rnti_cache[i] == rnti || cache->rnti_cache[i] == 0) {
            cache->rnti_cache[i] = rnti;
            cache->crcflag_cache[i] = crcflag;
            break;
        }
    }
}

void free_rnti_cache(RNTICache* cache) {
    if (!cache) return;

    free(cache);
}
