#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_SIZE 10000

typedef struct {
    int connection_id;
    char source_ip[INET_ADDRSTRLEN];
    char destination_ip[INET_ADDRSTRLEN];
    uint16_t source_port;
    uint16_t dest_port;
    time_t last_activity;
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD *records[MAX_SIZE];
    size_t count;
    pthread_mutex_t mutex;
} ConnectionList;

int is_valid_ip(const char *ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) != 0;
}

ConnectionList* create_connection_list() {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    if (!list) return NULL;

    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    for (size_t i = 0; i < MAX_SIZE; ++i) {
        list->records[i] = NULL;
    }
    return list;
}

void destroy_connection_list(ConnectionList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
    }
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_record(ConnectionList *list, int connection_id,
               const char *source_ip, const char *dest_ip,
               uint16_t source_port, uint16_t dest_port) {
    if (!is_valid_ip(source_ip) || !is_valid_ip(dest_ip)) return -1;

    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // List is full
    }

    TCP_CONNECTION_RECORD *record = malloc(sizeof(TCP_CONNECTION_RECORD));
    if (!record) {
        pthread_mutex_unlock(&list->mutex);
        return -3; // Memory allocation failed
    }

    record->connection_id = connection_id;
    strncpy(record->source_ip, source_ip, INET_ADDRSTRLEN);
    strncpy(record->destination_ip, dest_ip, INET_ADDRSTRLEN);
    record->source_port = source_port;
    record->dest_port = dest_port;
    time(&record->last_activity);

    list->records[list->count++] = record;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

int remove_record(ConnectionList *list, int connection_id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]->connection_id == connection_id) {
            free(list->records[i]);
            memmove(&list->records[i], &list->records[i + 1],
                    (list->count - i - 1) * sizeof(TCP_CONNECTION_RECORD *));
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Record not found
}

int update_timestamp(ConnectionList *list, int connection_id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]->connection_id == connection_id) {
            time(&list->records[i]->last_activity);
            pthread_mutex_unlock(&list->mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Record not found
}
