    uint64_t additional_memory_usage = sizeof(nfaapi_rx_pdu_rxinfo_t); // Adjust based on actual structure

    if (manager->current_memory_usage + additional_memory_usage > MEMORY_LIMIT) {
        printf("Memory limit exceeded\n");
        return -1;
