    if (manager->packet_count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_RX_PDU_T **new_packets = (NFAPI_RX_PDU_T **)realloc(manager->packets, new_capacity * sizeof(NFAPI_RX_PDU_T *));
        if (!new_packets) return -1;

        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }

    manager->packets[manager->packet_count] = packet;
    ++manager->packet_count;
    manager->current_memory_usage += additional_memory_usage;

    return 0;
}

NFAPI_RX_PDU_T* get_packet_by_sequence_number(PacketManager *manager, uint32_t sequence_number) {
    if (!manager) return NULL;

    for (size_t i = 0; i < manager->packet_count; ++i) {
        if (manager->packets[i]->ue_info_tag.sequence_number == sequence_number) {
            return manager->packets[i];
        }
    }

    return NULL;
}

int main() {
    PacketManager *manager = create_packet_manager(1024);

    // Example usage
    NFAPI_RX_PDU_T *packet = (NFAPI_RX_PDU_T *)malloc(sizeof(NFAPI_RX_PDU_T));
    packet->ue_info_tag.sequence_number = 1;
    packet->rnti.rnti = 12345;
