CRCListManager crc_list_manager = {0};

// Thread-safe function to initialize the list manager
void init_crc_list_manager() {
    pthread_mutex_init(&crc_list_manager.lock, NULL);
    pthread_rwlock_init(&crc_list_manager.rwlock, NULL);
    crc_list_manager.count = 0;
