}

// Thread-safe function to add a new structure
int add_structure(int RX_UE_INFORMATION_TAG, unsigned int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_rwlock_wrlock(&crc_list_manager.rwlock);

    if (crc_list_manager.count >= MAX_LIST_SIZE) {
        pthread_rwlock_unlock(&crc_list_manager.rwlock);
        return -1; // List full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_structure = realloc(crc_list_manager.list, 
                                                        (crc_list_manager.count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_structure) {
        pthread_rwlock_unlock(&crc_list_manager.rwlock);
