    NFAPI_CRC_INDICATION_PDU_T new_pdu = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, rand() % 2};
    crc_list_manager.list[crc_list_manager.count++] = new_pdu;

    pthread_rwlock_unlock(&crc_list_manager.rwlock);
    return 0; // Success
}

// Thread-safe function to remove a structure by RNTI
int remove_structure_by_rnti(unsigned int RNTI) {
    pthread_rwlock_wrlock(&crc_list_manager.rwlock);

    for (size_t i = 0; i < crc_list_manager.count; ++i) {
        if (crc_list_manager.list[i].RNTI == RNTI) {
            for (size_t j = i; j < crc_list_manager.count - 1; ++j) {
                crc_list_manager.list[j] = crc_list_manager.list[j + 1];
            }
            crc_list_manager.count--;
            NFAPI_CRC_INDICATION_PDU_T *shrinked_list = realloc(crc_list_manager.list, 
                                                                crc_list_manager.count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (shrinked_list) {
                crc_list_manager.list = shrinked_list;
            }
            pthread_rwlock_unlock(&crc_list_manager.rwlock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&crc_list_manager.rwlock);
    return -1; // Not found
}

// Thread-safe function to update CRCFLAGS based on criteria (example: RNTI even)
void update_crc_flags() {
    pthread_rwlock_wrlock(&crc_list_manager.rwlock);

    for (size_t i = 0; i < crc_list_manager.count; ++i) {
        if (crc_list_manager.list[i].RNTI % 2 == 0) {
            crc_list_manager.list[i].CRCFLAG = 1;
        } else {
            crc_list_manager.list[i].CRCFLAG = 0;
        }
    }

    pthread_rwlock_unlock(&crc_list_manager.rwlock);
}

// Function to calculate and print statistics
void print_statistics() {
    printf("Processed CRC Indications: %d\n", crc_list_manager.processed_crc_count);

    pthread_mutex_lock(&crc_list_manager.lock);
    unsigned int unique_rntis[MAX_LIST_SIZE] = {0};
    size_t unique_rnti_count = 0;

    for (size_t i = 0; i < crc_list_manager.count; ++i) {
        int found = 0;
        for (size_t j = 0; j < unique_rnti_count; ++j) {
            if (unique_rntis[j] == crc_list_manager.list[i].RNTI) {
                found = 1;
                break;
            }
        }
        if (!found) {
            unique_rntis[unique_rnti_count++] = crc_list_manager.list[i].RNTI;
        }
    }

    printf("Unique RNTIs: %zu\n", unique_rnti_count);
    double avg_processing_time_ns = crc_list_manager.processed_crc_count > 0 ? 
                                    (double)crc_list_manager.total_processing_time_ns / crc_list_manager.processed_crc_count : 0.0;
    printf("Average Processing Time (ns): %.2f\n", avg_processing_time_ns);

    pthread_mutex_unlock(&crc_list_manager.lock);
}

// Simulate processing of each structure within real-time constraints
void process_structures() {
    struct timespec start, end;

    for (size_t i = 0; i < crc_list_manager.count; ++i) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Simulated processing logic (e.g., updating CRCFLAG)

        clock_gettime(CLOCK_MONOTONIC, &end);
        unsigned long long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        crc_list_manager.total_processing_time_ns += elapsed_ns;
        crc_list_manager.processed_crc_count++;
    }
}

int main() {
    init_crc_list_manager();

    // Example usage
    add_structure(1, 1234, 5678);
    update_crc_flags();
    process_structures();
    print_statistics();

    remove_structure_by_rnti(1234);

    free(crc_list_manager.list);
    pthread_mutex_destroy(&crc_list_manager.lock);
    pthread_rwlock_destroy(&crc_list_manager.rwlock);

