#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define CHUNK_SIZE 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG:1; // Use bit field for CRCFLAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

int init_dynamic_array(DynamicArray *da) {
    pthread_mutex_init(&da->lock, NULL);
    da->capacity = CHUNK_SIZE;
    da->count = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        pthread_mutex_destroy(&da->lock);
        return -1; // Memory allocation failure
    }
    return 0;
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->count = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0;
}

int add_pdu(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);

    if (!validate_pdu(&pdu)) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Invalid PDU
    }

    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity + CHUNK_SIZE;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory reallocation failure
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    da->array[da->count++] = pdu;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

void log_allocation(int success, int type) {
    printf("Allocation Type: %s, Success: %d\n", (type == 1 ? "Initial" : "Realloc"), success);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    DynamicArray da;
    if (init_dynamic_array(&da) != 0) {
        fprintf(stderr, "Failed to initialize dynamic array.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 50; ++i) { // Example usage
        NFAPI_CRC_INDICATION_PDU_T pdu = {i + 1, rand() % 100 + 1, {0}};
        int result = add_pdu(&da, pdu);
        log_allocation(result == 0, da.count == CHUNK_SIZE ? 2 : 1);
    }

    free_dynamic_array(&da);

    return EXIT_SUCCESS;
}
