['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_RETRIES 5

typedef struct LTE_DL_CCCH_Message {
    int message_id;
    // Other fields for the message...
} LTE_DL_CCCH_Message;

typedef struct LTE_UERadioState {
    uint64_t ue_id;
    int ref_count;
    struct LTE_DL_CCCH_Message* messages_head;
    pthread_mutex_t lock;
} LTE_UERadioState;

typedef struct MessagePoolNode {
    LTE_DL_CCCH_Message message;
    struct MessagePoolNode* next;
} MessagePoolNode;

typedef struct {
    MessagePoolNode* free_list;
    pthread_mutex_t pool_lock;
} MessagePool;

typedef struct {
    LTE_UERadioState** radio_states;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
    MessagePool message_pool;
} RadioStateManager;

// Function prototypes
void initializeMessagePool(MessagePool* pool, size_t initial_size);
LTE_DL_CCCH_Message* allocateMessageFromPool(MessagePool* pool);
void deallocateMessageToPool(MessagePool* pool, LTE_DL_CCCH_Message* message);

void initializeRadioStateManager(RadioStateManager* manager, size_t capacity) {
    pthread_rwlock_init(&manager->rwlock, NULL);
    manager->radio_states = malloc(capacity * sizeof(LTE_UERadioState*));
    manager->capacity = capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->message_pool.pool_lock, NULL);
    initializeMessagePool(&manager->message_pool, 100); // Initial pool size
}

void finalizeRadioStateManager(RadioStateManager* manager) {
    pthread_rwlock_destroy(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        LTE_UERadioState* state = manager->radio_states[i];
        if (state) {
            pthread_mutex_lock(&state->lock);
            LTE_DL_CCCH_Message* message = state->messages_head;
            while (message) {
                LTE_DL_CCCH_Message* next = message->next;
                deallocateMessageToPool(&manager->message_pool, message);
                message = next;
            }
            pthread_mutex_unlock(&state->lock);
            free(state);
        }
    }

    free(manager->radio_states);

    // Cleanup the message pool
}

LTE_UERadioState* findOrAllocateRadioState(RadioStateManager* manager, uint64_t ue_id) {
    pthread_rwlock_rdlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->radio_states[i] && manager->radio_states[i]->ue_id == ue_id) {
            pthread_rwlock_unlock(&manager->rwlock);
            return manager->radio_states[i];
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);

    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (!manager->radio_states[i]) {
            LTE_UERadioState* state = malloc(sizeof(LTE_UERadioState));
            state->ue_id = ue_id;
            state->ref_count = 1;
            state->messages_head = NULL;
            pthread_mutex_init(&state->lock, NULL);
            manager->radio_states[i] = state;
            pthread_rwlock_unlock(&manager->rwlock);
            return state;
        }
    }

    if (manager->count < manager->capacity) {
        LTE_UERadioState* state = malloc(sizeof(LTE_UERadioState));
        state->ue_id = ue_id;
        state->ref_count = 1;
        state->messages_head = NULL;
        pthread_mutex_init(&state->lock, NULL);
        manager->radio_states[manager->count++] = state;
        pthread_rwlock_unlock(&manager->rwlock);
        return state;
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return NULL; // Handle full capacity scenario appropriately
}

void addMessageToRadioState(RadioStateManager* manager, uint64_t ue_id, LTE_DL_CCCH_Message* message) {
    LTE_UERadioState* state = findOrAllocateRadioState(manager, ue_id);

    if (state) {
        pthread_mutex_lock(&state->lock);

        message->next = state->messages_head;
        state->messages_head = message;

        pthread_mutex_unlock(&state->lock);
    }
}

void retryWithBackoff(void (*operation)(void), int max_retries, double base_delay) {
    for (int attempt = 0; attempt < max_retries; ++attempt) {
        operation();

        if (/* check if the operation succeeded */) {
            return;
        }

        // Exponential back-off
        double delay = base_delay * pow(2.0, attempt);
        usleep((useconds_t)(delay * 1e6));
    }
}

void initializeMessagePool(MessagePool* pool, size_t initial_size) {
    pool->free_list = NULL;

    pthread_mutex_lock(&pool->pool_lock);
    for (size_t i = 0; i < initial_size; ++i) {
        MessagePoolNode* node = malloc(sizeof(MessagePoolNode));
        node->next = pool->free_list;
        pool->free_list = node;
    }
    pthread_mutex_unlock(&pool->pool_lock);
}

LTE_DL_CCCH_Message* allocateMessageFromPool(MessagePool* pool) {
    pthread_mutex_lock(&pool->pool_lock);

    if (!pool->free_list) {
        // No free message, handle allocation or wait
        pthread_mutex_unlock(&pool->pool_lock);
        return NULL; // Or handle allocation logic
    }

    MessagePoolNode* node = pool->free_list;
    LTE_DL_CCCH_Message* message = &node->message;
    pool->free_list = node->next;

    pthread_mutex_unlock(&pool->pool_lock);
    return message;
}

void deallocateMessageToPool(MessagePool* pool, LTE_DL_CCCH_Message* message) {
    MessagePoolNode* node = (MessagePoolNode*)message;

    pthread_mutex_lock(&pool->pool_lock);
    node->next = pool->free_list;
    pool->free_list = node;
    pthread_mutex_unlock(&pool->pool_lock);
}
``` 

This code provides a multi-threaded C library component for managing LTE_UERadioState instances. It includes thread safety mechanisms, memory pooling, and an exponential back-off strategy for retrying failed operations. The implementation is designed to handle high-throughput scenarios with considerations for scalability and performance optimization. Adjustments may be necessary based on specific system requirements or API integrations.']

