#include <thread>
#include <atomic>
#include <unordered_map>

// Assuming a predefined maximum size for traffic statistics buffer.
const int MAX_TRAFFIC_STATS_SIZE = 100;

enum class RRCState {
    IDLE,
    CONNECTED
};

struct UEInstance {
    uint32_t id;
    RRCState rrcState;
    double uplinkTraffic; // in bytes per second

    bool matchesCriteria(RRCState state, double trafficThreshold) const {
        return (rrcState == state && uplinkTraffic >= trafficThreshold);
    }
};

struct FrameStatistics {
    std::chrono::time_point<std::chrono::steady_clock> timestamp;
    std::vector<UEInstance> activeUes;
    std::vector<double> trafficStatsBuffer;

    void clearOutdatedData() {
        if (trafficStatsBuffer.size() > MAX_TRAFFIC_STATS_SIZE) {
            trafficStatsBuffer.erase(trafficStatsBuffer.begin(), 
                                     trafficStatsBuffer.begin() + trafficStatsBuffer.size() - MAX_TRAFFIC_STATS_SIZE);
        }
    }
};

class FrameStatisticsManager {
public:
    FrameStatisticsManager(size_t bufferSize)
        : bufferSize(bufferSize), shouldRun(true) {}

    ~FrameStatisticsManager() { stop(); }

    void start() {
        thread = std::thread(&FrameStatisticsManager::populateAndManageStats, this);
    }

    void stop() {
        shouldRun.store(false);
        if (thread.joinable()) {
            thread.join();
        }
    }

    void updateFilter(RRCState state, double trafficThreshold) {
        std::unique_lock lock(filterMutex);
        filterState = state;
        trafficThresholdValue = trafficThreshold;
    }

private:
    size_t bufferSize;
    std::atomic<bool> shouldRun;
    std::thread thread;
    mutable std::shared_mutex dataMutex;
    std::mutex filterMutex;

    RRCState filterState{RRCState::IDLE};
    double trafficThresholdValue{0.0};

    // Simulated registration table
    std::unordered_map<uint32_t, UEInstance> registrationTable;

    void populateAndManageStats() {
        while (shouldRun.load()) {
            FrameStatistics stats;
            stats.timestamp = std::chrono::steady_clock::now();

            {
                std::shared_lock lock(dataMutex);
                auto iterBegin = registrationTable.begin();
                auto iterEnd = registrationTable.end();

                for (auto it = iterBegin; it != iterEnd; ++it) {
                    const UEInstance& ue = it->second;
                    if (ue.matchesCriteria(filterState, trafficThresholdValue)) {
                        stats.activeUes.push_back(ue);
                    }
                }

                // Simulate periodic clearing of outdated data
                stats.clearOutdatedData();
            }

            {
                std::unique_lock lock(dataMutex);
                statisticsBuffer.push_back(std::move(stats));
                if (statisticsBuffer.size() > bufferSize) {
                    statisticsBuffer.erase(statisticsBuffer.begin());
                }
            }

            // Log current status
            logStatus();

            // Sleep for a defined period to simulate frame intervals
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void logStatus() const {
        std::cout << "Current active UEs count: "
                  << statisticsBuffer.back().activeUes.size()
                  << ", Timestamp: "
                  << std::chrono::duration_cast<std::chrono::seconds>(
                         statisticsBuffer.back().timestamp.time_since_epoch()).count()
                  << std::endl;
    }

    // Buffer to store frame statistics
    std::vector<FrameStatistics> statisticsBuffer;

    void simulateRegistrationTableUpdates() {
        while (shouldRun.load()) {
            std::this_thread::sleep_for(std::chrono::seconds(5));

            {
                std::unique_lock lock(dataMutex);
                // Simulate updates to the registration table, e.g., adding a new UE
                registrationTable[registrationTable.size()] = {static_cast<uint32_t>(registrationTable.size()), RRCState::CONNECTED, 100.0};
            }
        }
    }
};

// Usage example (not part of solution)
int main() {
    FrameStatisticsManager manager(10);

    // Start frame statistics management
    manager.start();

    std::this_thread::sleep_for(std::chrono::seconds(20));

    // Stop the manager gracefully
    manager.stop();

    return 0;
}
