// Define constants
#define MAX_ELEMENTS 2048

// Structures definition
typedef struct {
    int ue_id;
    char rrc_state[10];
} RRCState;

typedef struct {
    uint32_t timestamp;
    RRCState *ue_list;
    size_t ue_count;
    double uplink_traffic_stats; // Buffer for uplink traffic stats
} FrameStatistics;

typedef struct {
    uint8_t pdcp_sdu[256];  // Assume a fixed maximum PDCP SDU length
    uint16_t sequence_number;
    uint8_t integrity_key[32];
} PDCHdr;

typedef struct {
    PDCHdr header;
} LTE_Phy_Layer_CPDU;

// Function prototypes
void initialize_statistics(FrameStatistics **frame_stats, size_t *size);
void cleanup_statistics(FrameStatistics **frame_stats, size_t size);
int add_frame_statistic(FrameStatistics **frame_stats, size_t *size, FrameStatistics new_entry);
int update_pdcphdr(LTE_Phy_Layer_CPDU **pdpdu_array, size_t *array_size, LTE_Phy_Layer_CPDU new_pdu);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_statistics(FrameStatistics **frame_stats, size_t *size) {
    pthread_mutex_lock(&mutex);
    *frame_stats = (FrameStatistics *)calloc(MAX_ELEMENTS, sizeof(FrameStatistics));
    if (*frame_stats == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *size = 0;
    pthread_mutex_unlock(&mutex);
}

void cleanup_statistics(FrameStatistics **frame_stats, size_t size) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; ++i) {
        if ((*frame_stats)[i].ue_list != NULL) {
            free((*frame_stats)[i].ue_list);
        }
    }
    free(*frame_stats);
    *frame_stats = NULL;
    pthread_mutex_unlock(&mutex);
}

int add_frame_statistic(FrameStatistics **frame_stats, size_t *size, FrameStatistics new_entry) {
    if (*size >= MAX_ELEMENTS) return -1; // Array is full

    pthread_mutex_lock(&mutex);

    (*frame_stats)[*size].timestamp = new_entry.timestamp;
    (*frame_stats)[*size].ue_list = (RRCState *)malloc(new_entry.ue_count * sizeof(RRCState));
    if ((*frame_stats)[*size].ue_list == NULL) {
        fprintf(stderr, "Memory allocation failed for UE list\n");
        pthread_mutex_unlock(&mutex);
