#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct NetworkEvent {
    int id;
    time_t timestamp;
    char data[256]; // Example event data, adjust as necessary
} NetworkEvent;

typedef struct EventNode {
    NetworkEvent event;
    struct EventNode* next;
} EventNode;

typedef struct DynamicEventList {
    EventNode* head;
    size_t capacity;
    size_t count;
    size_t max_capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} DynamicEventList;

DynamicEventList* initialize_event_list(size_t max_capacity) {
    DynamicEventList* list = malloc(sizeof(DynamicEventList));
    if (!list) return NULL;

    list->head = NULL;
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->max_capacity = max_capacity;

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);

    return list;
}

void destroy_event_list(DynamicEventList* list) {
    EventNode* current = list->head;
    while (current) {
        EventNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

void add_event(DynamicEventList* list, NetworkEvent new_event) {
    pthread_mutex_lock(&list->lock);

    while (list->count >= list->max_capacity) {
        // Remove the oldest event to make room
        if (list->head) {
            EventNode* temp = list->head;
            list->head = list->head->next;
            free(temp);
            list->count--;
        }
    }

    EventNode* new_node = malloc(sizeof(EventNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle allocation failure gracefully
    }

    new_node->event = new_event;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_cond_signal(&list->cond_var); // Notify any waiting threads

    pthread_mutex_unlock(&list->lock);
}

void get_latest_events(DynamicEventList* list, NetworkEvent* buffer, size_t num) {
    pthread_mutex_lock(&list->lock);

    size_t n = (num < list->count) ? num : list->count;
    EventNode* current = list->head;

    for (size_t i = 0; i < n && current != NULL; i++) {
        buffer[i] = current->event;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Usage example
int main() {
    DynamicEventList* event_list = initialize_event_list(100);

    NetworkEvent new_event = {1, time(NULL), "First Event"};
    add_event(event_list, new_event);

    NetworkEvent buffer[10];
    get_latest_events(event_list, buffer, 5);

    destroy_event_list(event_list);

    return 0;
}
```

This implementation uses a linked list to manage the dynamic event storage. It employs mutexes and condition variables for thread-safe access and ensures that memory is managed efficiently by removing old events when the capacity threshold is exceeded. The `add_event` function handles concurrent additions, while `get_latest_events` retrieves the most recent events in a thread-safe manner.']

