MAC_PDU* create_mac_pdu_array(size_t num_elements, size_t pdcp_size) {
    if (num_elements == 0 || pdcp_size == 0) {
        return NULL; // Handle invalid input
    }

    // Allocate memory for the array of MAC_PDUs
    MAC_PDU *array = (MAC_PDU*)malloc(num_elements * sizeof(MAC_PDU));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Iterate over each element to initialize and allocate necessary fields.
    for (size_t i = 0; i < num_elements; ++i) {
        array[i].PDCP_PDU = (uint8_t*)malloc(pdcp_size);
        if (!array[i].PDCP_PDU) {
            fprintf(stderr, "Memory allocation failed for PDCP_PDU\n");

            // Free previously allocated memory on failure
            while (--i > 0) {
                free(array[i].PDCP_PDU);
            }
            free(array);

            return NULL;
        }

        array[i].SAP_ID = /* Assign appropriate value */;
        array[i].PDUSessionID = /* Assign appropriate value */;
        array[i].SequenceNumber = i + 1; // Ensure unique SequenceNumbers
        array[i].Timestamp = /* Capture current timestamp */;

        // Handle additional initialization if necessary
    }

    return array;
}

// Function to free the allocated memory for MAC_PDU structures.
void free_mac_pdu_array(MAC_PDU *array, size_t num_elements) {
    if (array == NULL) {
        return;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        free(array[i].PDCP_PDU); // Free the dynamically allocated PDCP_PDU data
    }

