} NetworkTopology;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_crc_array(size_t max_size, size_t current_size) {
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < current_size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        array[i].RNTI = rand() % 1000 + 1;
        array[i].CRC_INDICATION_REL8_TAG = (rand() % 10) * 2;
        array[i].CRCFLAG = rand() % 2;
        array[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&mutex);
    return array;
}

void resize_crc_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* current_size, size_t max_size) {
    if (*current_size >= max_size) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*array, 2 * max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            perror("Memory reallocation failed");
            pthread_mutex_unlock(&mutex);
            return;
        }

        memset(new_array + *current_size, 0, (max_size - *current_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        free(*array);
        *array = new_array;
        max_size *= 2;

        pthread_mutex_unlock(&mutex);
    }
}

NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* generate_measurement_reports(size_t num_reports) {
    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* reports = (NFAPI_RRC_MEASUREMENT_REPORT_PDU_T*)malloc(num_reports * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));

