        reports[i].RRC_Measurement_Report_Identifier = rand() % 10000 + 1;
        reports[i].Measurement_Report_Type = rand() % 5 + 1;
        reports[i].PHY_Measurement_Results = (float)(rand() % 1000) / 10.0;
    }

    return reports;
}

NetworkTopology* create_network_topology(size_t num_base_stations, size_t num_terminals) {
    NetworkTopology* topology = (NetworkTopology*)malloc(sizeof(NetworkTopology));

    if (!topology) {
        perror("Memory allocation failed for network topology");
        return NULL;
    }

    topology->base_stations = (NetworkEntity*)calloc(num_base_stations, sizeof(NetworkEntity));
    topology->terminals = (NetworkEntity*)calloc(num_terminals, sizeof(NetworkEntity));

    if (!topology->base_stations || !topology->terminals) {
        perror("Memory allocation failed for network entities");
        free(topology->base_stations);
        free(topology->terminals);
        free(topology);
        return NULL;
    }

    topology->num_base_stations = num_base_stations;
    topology->num_terminals = num_terminals;

    for (size_t i = 0; i < num_base_stations; ++i) {
        snprintf(topology->base_stations[i].IP_Address, sizeof(topology->base_stations[i].IP_Address), "192.168.1.%zu", i + 1);
        snprintf(topology->base_stations[i].MAC_Address, sizeof(topology->base_stations[i].MAC_Address), "00:0A:95:%02X:%02X:%02X",
                 rand() % 256, rand() % 256, rand() % 256);
        topology->base_stations[i].bandwidth = rand() % 100 + 1;
        topology->base_stations[i].latency = rand() % 50 + 1;
    }

    for (size_t i = 0; i < num_terminals; ++i) {
        snprintf(topology->terminals[i].IP_Address, sizeof(topology->terminals[i].IP_Address), "192.168.2.%zu", i + 1);
        snprintf(topology->terminals[i].MAC_Address, sizeof(topology->terminals[i].MAC_Address), "00:0A:95:%02X:%02X:%02X",
                 rand() % 256, rand() % 256, rand() % 256);
        topology->terminals[i].bandwidth = rand() % 100 + 1;
        topology->terminals[i].latency = rand() % 50 + 1;
    }

    return topology;
}

void free_network_topology(NetworkTopology* topology) {
    if (topology) {
        free(topology->base_stations);
        free(topology->terminals);
        free(topology);
    }
}

int main() {
    srand(time(NULL));

    size_t current_size = 0;
    size_t max_size = 1000;
    NFAPI_CRC_INDICATION_PDU_T* crc_array = allocate_and_initialize_crc_array(max_size, current_size);

    if (!crc_array) return EXIT_FAILURE;

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        resize_crc_array(&crc_array, &current_size, max_size);

        if (!crc_array) break;

        crc_array[current_size].RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        crc_array[current_size].RNTI = rand() % 1000 + 1;
        crc_array[current_size].CRC_INDICATION_REL8_TAG = (rand() % 10) * 2;
        crc_array[current_size].CRCFLAG = rand() % 2;
        crc_array[current_size].timestamp = time(NULL);

        ++current_size;
    }

    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* reports = generate_measurement_reports(100);

    NetworkTopology* topology = create_network_topology(10, 20);

    if (!topology) {
        free(crc_array);
        free(reports);
        return EXIT_FAILURE;
    }

    // Simulate processing and cleanup
    free(crc_array);
    free(reports);
    free_network_topology(topology);

    return EXIT_SUCCESS;
}
