#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int TX_POWER_LEVEL;
    int RECEIVED_QUALITY;
    long TIMESTAMP;
} TX_RX_STATS;

typedef struct {
    void* CellConfig;  // Placeholder for actual cell configuration structure
    TX_RX_STATS* stats;
    size_t num_stats;
    pthread_mutex_t lock;
} CELL_INFO;

typedef struct {
    CELL_INFO** cells;
    size_t capacity;
    size_t size;
    pthread_rwlock_t rwlock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0)
        return NULL;

    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array)
        return NULL;

    array->cells = calloc(initial_capacity, sizeof(CELL_INFO*));
    if (!array->cells) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;

    pthread_rwlock_init(&array->rwlock, NULL);

    return array;
}

void resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    CELL_INFO** new_cells = realloc(array->cells, new_capacity * sizeof(CELL_INFO*));
    if (!new_cells)
        return;  // Handle failure gracefully

    for (size_t i = array->capacity; i < new_capacity; ++i)
        new_cells[i] = NULL;

    array->cells = new_cells;
    array->capacity = new_capacity;
}

int add_cell_info(DynamicArray* array, void* cell_config) {
    pthread_rwlock_wrlock(&array->rwlock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        resize_dynamic_array(array, new_capacity);
        if (!array->cells)
            goto cleanup;  // Handle failure gracefully
    }

    CELL_INFO* cell_info = malloc(sizeof(CELL_INFO));
    if (!cell_info) {
        pthread_rwlock_unlock(&array->rwlock);
        return -1;  // Memory allocation failed
    }

    cell_info->CellConfig = cell_config;
    cell_info->stats = NULL;
    cell_info->num_stats = 0;

    pthread_mutex_init(&cell_info->lock, NULL);

    array->cells[array->size++] = cell_info;

cleanup:
    pthread_rwlock_unlock(&array->rwlock);
    return (array->cells ? 0 : -1); // Return success or failure
}

void update_tx_rx_stats(DynamicArray* array, size_t index, TX_RX_STATS stats) {
    if (index >= array->size)
        return;

    pthread_rwlock_rdlock(&array->rwlock);

    CELL_INFO* cell_info = array->cells[index];

    pthread_mutex_lock(&cell_info->lock);

    // Resize the stats array as needed
    size_t new_num_stats = cell_info->num_stats + 1;
    TX_RX_STATS* new_stats = realloc(cell_info->stats, new_num_stats * sizeof(TX_RX_STATS));
    if (new_stats) {
        cell_info->stats = new_stats;
        cell_info->stats[cell_info->num_stats] = stats;
        cell_info->num_stats = new_num_stats;
    }

    pthread_mutex_unlock(&cell_info->lock);

    pthread_rwlock_unlock(&array->rwlock);
}

void free_dynamic_array(DynamicArray* array) {
    if (!array)
        return;

    pthread_rwlock_wrlock(&array->rwlock);

    for (size_t i = 0; i < array->size; ++i) {
        CELL_INFO* cell_info = array->cells[i];
        pthread_mutex_destroy(&cell_info->lock);
        free(cell_info->stats);
        free(cell_info);
    }

    free(array->cells);

    pthread_rwlock_unlock(&array->rwlock);

    pthread_rwlock_destroy(&array->rwlock);
    free(array);
}

// Optional logging
void log_changes(const char* message) {
#ifdef ENABLE_LOGGING
    printf("%s\n", message);  // Simple console logging for demonstration purposes
#endif
}
```

### Explanation:
- **DynamicArray Structure**: Manages a dynamic array of `CELL_INFO` pointers, with read-write locks to allow concurrent access.
- **Concurrency**: Uses read-write locks (`pthread_rwlock_t`) to minimize contention during read operations and ensure exclusive access when writing or modifying the array structure.
- **Memory Management**: Efficiently resizes the array using `realloc`. Handles memory allocation failures gracefully without crashing.
- **Logging Mechanism**: Optional logging is implemented with a macro toggle, minimizing performance impact in production environments.
- **Thread Safety**: Ensures all accesses to `CELL_INFO` and its `TX_RX_STATS` are protected by locks, both at the cell level (using `pthread_mutex_t`) and array level (using read-write locks).']

