#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE (10 * 1024 * 1024) // 10 MB limit for demonstration
#define INITIAL_SIZE 1000
#define RESIZE_FACTOR 2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to initialize the dynamic array
DynamicArray* init_dynamic_array(size_t initial_size) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = initial_size;
    pthread_mutex_init(&da->mutex, NULL);

    // Ensure at least one element has CRCFLAG set to zero
    srand(time(NULL));
    for (size_t i = 0; i < initial_size; ++i) {
        da->array[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        da->array[i].RNTI = rand() % 100000 + 1;
        da->array[i].CRC_INDICATION_REL8_TAG = rand();
        da->array[i].CRCFLAG = (i == 0) ? 0 : (rand() & 1);
    }

    return da;
}

// Function to safely resize the dynamic array
int resize_dynamic_array(DynamicArray* da, size_t new_size) {
    pthread_mutex_lock(&da->mutex);

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(da->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        pthread_mutex_unlock(&da->mutex);
        return -1;
    }

    da->array = temp;
    for (size_t i = da->size; i < new_size; ++i) {
        da->array[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        da->array[i].RNTI = rand() % 100000 + 1;
        da->array[i].CRC_INDICATION_REL8_TAG = rand();
        da->array[i].CRCFLAG = (rand() & 1);
    }

    da->size = new_size;
    pthread_mutex_unlock(&da->mutex);

    return 0;
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray* da) {
    if (!da) return;

    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_unlock(&da->mutex);

    pthread_mutex_destroy(&da->mutex);
    free(da);
}

// Example usage function to demonstrate concurrent access
void* thread_function(void* arg) {
    DynamicArray* da = (DynamicArray*)arg;
    pthread_mutex_lock(&da->mutex);

    // Simulate some operations on the array
    for (size_t i = 0; i < da->size; ++i) {
        if ((da->array[i].RX_UE_INFORMATION_TAG + da->array[i].RNTI) % 2 == 0) {
            da->array[i].CRCFLAG ^= 1;
        }
    }

    pthread_mutex_unlock(&da->mutex);
    return NULL;
}

int main() {
    size_t initial_size = INITIAL_SIZE;
    DynamicArray* da = init_dynamic_array(initial_size);

    if (!da) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    const int num_threads = 4;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, da);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Resize the array if needed
    size_t new_size = initial_size * RESIZE_FACTOR;
    if (resize_dynamic_array(da, new_size) != 0) {
        fprintf(stderr, "Failed to resize dynamic array\n");
    }

    free_dynamic_array(da);

    return EXIT_SUCCESS;
}
```

