unsigned int calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    unsigned int checksum = 0;
    const char *data = (const char *)pdu;
    for (size_t i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        checksum += data[i];
    }
