    validation_log[log_head].failed_index = index;
    validation_log[log_head].timestamp = time(NULL);
    log_head = (log_head + 1) % LOG_SIZE;
    pthread_mutex_unlock(&lock);
}

int validate_structure(const NFAPI_CRC_INDICATION_PDU_T *pdu, unsigned int expected_checksum) {
    return calculate_checksum(pdu) == expected_checksum;
}

