    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
