            log_validation_failure(i);
            initialize_pdu(&pdus[i]); // Reinitialize on failure
        }
    }

    total_created += num;
    *created = (int)num;

    pthread_mutex_unlock(&lock);

    return pdus;
}

void destroy_structures(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t num) {
    if (!pdus) return;

    free(pdus);

    pthread_mutex_lock(&lock);
