#define MAX_STRUCTURES 1000

typedef struct {
    uint32_t SOURCE_IP;
    uint32_t DESTINATION_IP;
    uint16_t PORT;
    uint32_t PAYLOAD_SIZE;
    uint64_t SEQ_NUMBER;
    uint32_t CHECKSUM;
} DATA_PACKET_T;

// Global variables for tracking and synchronization
static size_t total_structures_created = 0;
static pthread_mutex_t creation_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t capacity_available = PTHREAD_COND_INITIALIZER;

void log_warning(const char *message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

uint32_t generate_checksum(DATA_PACKET_T *packet) {
    // Simple checksum generation based on other fields
    return (packet->SOURCE_IP ^ packet->DESTINATION_IP ^ 
            (packet->PORT << 16) ^ packet->PAYLOAD_SIZE ^ 
            (packet->SEQ_NUMBER & 0xFFFFFFFF));
}

int validate_structure(const DATA_PACKET_T *packet) {
    uint32_t expected_checksum = generate_checksum((DATA_PACKET_T *)packet);
    return (expected_checksum == packet->CHECKSUM);
}

DATA_PACKET_T* allocate_data_packets(size_t num_structures, size_t max_structures) {
    if (num_structures > max_structures) {
        log_warning("Requested number of structures exceeds the maximum allowable limit.");
        num_structures = max_structures;
    }

    DATA_PACKET_T *packets = NULL;

    pthread_mutex_lock(&creation_lock);
    while ((total_structures_created + num_structures) > MAX_STRUCTURES) {
        pthread_cond_wait(&capacity_available, &creation_lock);
    }

    size_t new_total = total_structures_created + num_structures;
    packets = (DATA_PACKET_T *)malloc(num_structures * sizeof(DATA_PACKET_T));
    if (!packets) {
        perror("Failed to allocate memory for data packets");
        pthread_mutex_unlock(&creation_lock);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_structures; ++i) {
        DATA_PACKET_T *packet = &packets[i];
        packet->SOURCE_IP = rand() % 256;
        packet->DESTINATION_IP = rand() % 256;
        packet->PORT = rand() % 65536;
        packet->PAYLOAD_SIZE = rand() % (1024 * 1024);
        packet->SEQ_NUMBER = total_structures_created + i;

        packet->CHECKSUM = generate_checksum(packet);

        if (!validate_structure(packet)) {
            fprintf(stderr, "Validation failed for structure at index %zu\n", i);
            free(packets);
            pthread_mutex_unlock(&creation_lock);
            return NULL;
        }
    }

    total_structures_created += num_structures;

    if (total_structures_created >= MAX_STRUCTURES) {
        pthread_cond_broadcast(&capacity_available); // Wake up any waiting threads
    }

    pthread_mutex_unlock(&creation_lock);

    return packets;
}

void deallocate_data_packets(DATA_PACKET_T *packets, size_t num_structures) {
    free(packets);
    pthread_mutex_lock(&creation_lock);
    total_structures_created -= num_structures;
    pthread_cond_broadcast(&capacity_available); // Wake up any waiting threads
    pthread_mutex_unlock(&creation_lock);
}

int main() {
    size_t requested_structures = 500; // Example usage

    DATA_PACKET_T *data_packets = allocate_data_packets(requested_structures, MAX_STRUCTURES);
    if (data_packets) {
        printf("Successfully allocated %zu data packets.\n", requested_structures);

        // Use the data_packets...

        deallocate_data_packets(data_packets, requested_structures);
        printf("Deallocated data packets.\n");
    } else {
        fprintf(stderr, "Failed to allocate data packets.\n");
    }

    return 0;
}
