// Define structure for NetworkFrameStatistics
typedef struct {
    unsigned long timestamp;
    int signalStrength; // in dBm
    float errorRate;    // percentage of errors
} NetworkFrameStatistics;

// Function to read dynamic list of integers from standard input
int* readIntegers(int* size) {
    printf("Enter the number of integers: ");
    scanf("%d", size);

    int* array = (int*)malloc(*size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers:\n", *size);
    for (int i = 0; i < *size; ++i) {
        scanf("%d", &array[i]);
    }

    return array;
}

// Helper function to find and print the largest integer
void printLargestInteger(int* array, int size) {
    if (size <= 0) {
        printf("No integers to process.\n");
        return;
    }

    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    printf("The largest integer is: %d\n", max);
}

// Function to simulate network conditions and initialize statistics
void populateNetworkFrameStatistics(NetworkFrameStatistics* stats, int numFrames) {
    for (int i = 0; i < numFrames; ++i) {
        stats[i].timestamp = i * 1000; // Simulate sequential timestamps in ms
        stats[i].signalStrength = rand() % 101 - 100; // dBm range from -100 to 0
        stats[i].errorRate = (float)(rand() % 1001) / 10.0f; // error rate from 0.0 to 100.0
    }
}

// Thread-safe wrapper for processing statistics
void* processNetworkStatistics(void* args) {
    NetworkFrameStatistics* stats = (NetworkFrameStatistics*)args;

    // Example processing: find frames with high error rates
    for (int i = 0; i < 10; ++i) { // Assuming 10 frames to keep it concise
        if (stats[i].errorRate > 50.0f) {
            printf("Frame %d has a high error rate of %.1f%%\n", 
                   stats[i].timestamp / 1000, stats[i].errorRate);
        }
    }

    return NULL;
}

int main() {
    int numIntegers;
    int* integers = readIntegers(&numIntegers);

    printLargestInteger(integers, numIntegers);
    free(integers);

    const int numFrames = 10; // Simulate with 10 frames
    NetworkFrameStatistics stats[numFrames];
    populateNetworkFrameStatistics(stats, numFrames);

    pthread_t thread;
    if (pthread_create(&thread, NULL, processNetworkStatistics, stats) != 0) {
        fprintf(stderr, "Failed to create a thread\n");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}
