#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define RNTI_RANGE_LOW 1
#define RNTI_RANGE_HIGH 10000

typedef struct {
    int rnti;
    int value;
    time_t timestamp;
} record;

typedef struct {
    record *records[MAX_RECORDS];
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

// External logging function prototype
void external_log(const char *message);

RecordManager* initialize_manager() {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) {
        external_log("Failed to allocate memory for Record Manager");
        return NULL;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int generate_unique_rnti(record *rec) {
    int attempts = 0;
    while (attempts < 3) {
        rec->rnti = rand() % (RNTI_RANGE_HIGH - RNTI_RANGE_LOW + 1) + RNTI_RANGE_LOW;
        // Check for uniqueness, assuming a function exists
        if (!is_rnti_duplicate(rec->rnti)) {
            return 0; // Success
        }
        attempts++;
    }
    external_log("Failed to generate unique RNTI after 3 attempts");
    return -1; // Failure
}

int add_record(RecordManager *manager, int value) {
    if (!manager || manager->count >= MAX_RECORDS) {
        external_log("Invalid input or maximum records reached");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    record *new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&manager->lock);
        external_log("Failed to allocate memory for new record");
        return -1;
    }

    srand((unsigned int)time(NULL)); // Seed with current time
    new_record->value = value;

    if (generate_unique_rnti(new_record) != 0) {
        free(new_record);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_record->timestamp = time(NULL);

    manager->records[manager->count++] = new_record;

    // Persist record to storage
    if (!persist_record_to_storage(new_record)) {
        external_log("Failed to persist record");
        free(new_record); // Cleanup on failure
        manager->records[--manager->count] = NULL;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void cleanup_manager(RecordManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Assume these functions are implemented elsewhere
int is_rnti_duplicate(int rnti);
int persist_record_to_storage(record *rec);

// Main function for demonstration purposes
int main() {
    RecordManager *manager = initialize_manager();
    if (!manager) return -1;

    // Example usage
    add_record(manager, 42); // Add a record with value 42

    cleanup_manager(manager);
    return 0;
}
