#define BUFFER_SIZE 1024
#define CHECKSUM_LEN sizeof(uint16_t)
#define MAX_PACKETS 10

typedef struct {
    unsigned char* buffer;
    size_t capacity;
    size_t length;
    uint32_t timeout_ms; // Timeout in milliseconds for packet processing
} NetworkInterface;

uint16_t calculate_checksum(const unsigned char *data, size_t len) {
    uint32_t sum = 0;
    while (len > 1) {
        uint32_t word = *(const uint16_t*)data;
        sum += ntohs(word);
        data += sizeof(uint16_t);
        len -= sizeof(uint16_t);
    }
    if (len) {
        sum += (*((uint8_t*)data)) << 8;
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return htons(~sum);
}

void* process_packets(void *arg) {
    NetworkInterface *netif = (NetworkInterface *)arg;
    // Simulate packet processing logic
    while (1) {
        if (netif->length > 0) {
            uint16_t checksum = calculate_checksum(netif->buffer, netif->length);
            if (checksum == 0) { // Assuming valid packets have a checksum of zero for simplicity
                printf("Packet processed successfully\n");
                netif->length = 0; // Clear the buffer after processing
            }
        }
    }
}

void configure_network_interface(NetworkInterface *netif, size_t capacity, uint32_t timeout_ms) {
