    netif->capacity = capacity;
    netif->buffer = (unsigned char *)malloc(capacity);
    if (!netif->buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        exit(EXIT_FAILURE);
    }
    memset(netif->buffer, 0, capacity);

    netif->length = 0;
    netif->timeout_ms = timeout_ms;

    pthread_t processing_thread;
    if (pthread_create(&processing_thread, NULL, process_packets, (void*)netif)) {
        fprintf(stderr, "Failed to create packet processing thread\n");
        exit(EXIT_FAILURE);
    }
    pthread_detach(processing_thread);

    // Implement flow control logic here
