    printf("Network interface configured with capacity: %zu bytes and timeout: %u ms\n", capacity, timeout_ms);
}

void free_network_interface(NetworkInterface *netif) {
    if (netif->buffer) {
        free(netif->buffer);
        netif->buffer = NULL;
    }
    pthread_mutex_destroy(&(netif->mutex));
}

