    if (!configurations) {
        logMessage(LOG_LEVEL_ERROR, "Memory allocation failed.\n");
        stats.failureCount += count;
        pthread_mutex_unlock(&lock);
        return;
    }
    pthread_mutex_unlock(&lock);

    initializeConfigurations(&configurations, count);

    for (size_t i = 0; i < count; ++i) {
        // Set uniqueId
        configurations[i].uniqueId = rand();

        // Randomly set CRCFLAG
        configurations[i].crcFlag = rand() % 2;

        // Validate structure integrity
        size_t checksum = calculateChecksum(&configurations[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (checksum == SIZE_MAX) {
            logMessage(LOG_LEVEL_ERROR, "Memory corruption detected for configuration ID: %lu\n", configurations[i].uniqueId);
            stats.failureCount++;
        } else {
            stats.successCount++;
        }
    }

    free(configurations);

    // Log statistics
    logMessage(LOG_LEVEL_INFO, "Initialization completed with %d successes and %d failures.\n",
               stats.successCount, stats.failureCount);
}

int validateInputParameters(size_t count) {
    if (count > MAX_CONFIGURATIONS || count == 0) {
        return 0;
    }
    return 1;
}

void initializeConfigurations(NFAPI_CRC_INDICATION_PDU_T **configurations, size_t count) {
