        (*configurations)[i].valid = 1; // Assume valid
        (*configurations)[i].rnti = rand(); // Random RNTI value
    }
}

size_t calculateChecksum(const NFAPI_CRC_INDICATION_PDU_T *data, size_t length) {
    unsigned char *bytes = (unsigned char *)data;
    size_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += bytes[i];
    }
    if (checksum == SIZE_MAX) { // Simulate a corruption scenario
        return SIZE_MAX;
    }
    return checksum;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    size_t numConfigs = 10000; // Example batch size
    processConfigurations(numConfigs);

    return 0;
}
