        unsigned long rnti = rand();
        int retries = 0;

        // Ensure unique RNTI within the current structures
        while (!is_rnti_unique(rnti, structures, count) && retries < RETRY_LIMIT) {
            rnti = rand();
            retries++;
        }

        if (retries == RETRY_LIMIT) {
