            continue; // Skip this iteration
        }

        new_structure.RNTI = rnti;
        new_structure.CRC_INDICATION_REL8_TAG = rand() % 10 + 1; // Simulate valid CRC tag
        new_structure.CRCFLAG = (rand() % 2) != 0; // Randomly set CRCFLAG

        structures[count++] = new_structure;

