            send_via_message_broker(&new_structure); // Offload to secondary queue for less urgent indications
        }
    }

    *actual_count = count;
    bool storage_success = store_persistently(structures, count);

    pthread_mutex_unlock(&mutex);

    if (!storage_success) {
        log_event("Failed to persist data in the external storage system.");
        free(structures);
        return NULL;
    }

    return structures;
}

