// Assuming these are defined elsewhere
typedef struct {
    int valid;
    int pci;
} LTEPHY_RX_UE;

typedef struct {
    LTEPHY_RX_UE ue_info;
    uint32_t crc_checksum_flag;
} LTE_PHY_RX_stat;

typedef struct {
    LTE_PHY_RX_stat *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* init_dynamic_array(size_t initial_capacity);
int resize_dynamic_array(DynamicArray *array, size_t new_capacity);
void add_statistic(DynamicArray *array, LTEPHY_RX_UE ue_info, uint32_t crc_checksum_flag);
LTE_PHY_RX_stat* query_stat_by_pci(DynamicArray *array, int pci);
void set_interval_and_thresholds(DynamicArray *array, size_t interval, uint32_t threshold);
void cleanup_dynamic_array(DynamicArray *array);

// Initialize the dynamic array
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = calloc(initial_capacity, sizeof(LTE_PHY_RX_stat));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    // Logging initialization
    printf("DynamicArray initialized with capacity %zu.\n", initial_capacity);
    return array;
}

// Resize the dynamic array
int resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    LTE_PHY_RX_stat *new_data = realloc(array->data, new_capacity * sizeof(LTE_PHY_RX_stat));
    if (!new_data) return -1;

    array->data = new_data;
    array->capacity = new_capacity;

    // Logging resizing
    printf("DynamicArray resized to capacity %zu.\n", new_capacity);
    return 0;
}

// Add a new statistic entry
void add_statistic(DynamicArray *array, LTEPHY_RX_UE ue_info, uint32_t crc_checksum_flag) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (resize_dynamic_array(array, new_capacity) != 0) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed during resize.\n");
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    LTE_PHY_RX_stat *stat = &array->data[array->count++];
    stat->ue_info = ue_info;
    stat->crc_checksum_flag = crc_checksum_flag;

    // Logging addition
    printf("Added statistic for PCI %d.\n", ue_info.pci);

    pthread_mutex_unlock(&array->lock);
}

// Query statistic by PCI
LTE_PHY_RX_stat* query_stat_by_pci(DynamicArray *array, int pci) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].ue_info.pci == pci) {
            LTE_PHY_RX_stat *stat = &array->data[i];

            // Logging query
            printf("Queried statistic for PCI %d.\n", pci);

            pthread_mutex_unlock(&array->lock);
            return stat;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

// Set statistical intervals and thresholds
void set_interval_and_thresholds(DynamicArray *array, size_t interval, uint32_t threshold) {
    // Implement logic to handle intervals and thresholds if needed.
    // Logging setting intervals and thresholds
    printf("Set interval %zu and threshold %u.\n", interval, threshold);
}

// Cleanup the dynamic array
void cleanup_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    free(array->data);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);

    // Logging cleanup
    printf("DynamicArray cleaned up.\n");
}

// Unit tests for the implementation
void test_dynamic_array() {
    DynamicArray *array = init_dynamic_array(2);
    if (!array) {
        printf("Failed to initialize dynamic array.\n");
        return;
    }

    LTEPHY_RX_UE ue1 = { .valid = 1, .pci = 100 };
    uint32_t crc_flag1 = rand();
    add_statistic(array, ue1, crc_flag1);

    LTEPHY_RX_UE ue2 = { .valid = 1, .pci = 200 };
    uint32_t crc_flag2 = rand();
    add_statistic(array, ue2, crc_flag2);

    LTE_PHY_RX_stat *stat = query_stat_by_pci(array, 100);
    if (stat) {
        printf("Found statistic for PCI %d with CRC flag %u.\n", stat->ue_info.pci, stat->crc_checksum_flag);
    } else {
        printf("Statistic not found for PCI 100.\n");
    }

    cleanup_dynamic_array(array);
}

int main() {
    srand(time(NULL));
    test_dynamic_array();
    return 0;
}
```

