['Below is a C library designed to manage a dynamic pool of network connection requests with the specified features. This code includes data structures, functions, and mechanisms for high concurrency, automatic cleanup, efficient memory management, logging, and configuration.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_BACKLOG 1024

typedef struct {
    char session_id[64];
    char client_ip[16];
    time_t timeout;
} ConnectionRequest;

typedef struct Node {
    ConnectionRequest *request;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    size_t count;
} ConnectionPool;

typedef struct {
    ConnectionPool pool;
    pthread_t cleanup_thread;
    int is_running;
} NetworkManager;

void init_pool(ConnectionPool *pool) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->count = 0;
}

ConnectionRequest* create_request(const char *session_id, const char *client_ip, time_t timeout) {
    ConnectionRequest *req = malloc(sizeof(ConnectionRequest));
    if (!req) return NULL;

    strncpy(req->session_id, session_id, sizeof(req->session_id) - 1);
    req->session_id[sizeof(req->session_id) - 1] = '\0';

    strncpy(req->client_ip, client_ip, sizeof(req->client_ip) - 1);
    req->client_ip[sizeof(req->client_ip) - 1] = '\0';

    req->timeout = timeout;
    return req;
}

void add_request(NetworkManager *manager, ConnectionRequest *req) {
    pthread_mutex_lock(&manager->pool.lock);

    if (manager->pool.count >= MAX_BACKLOG) {
        // Handle backlog overflow
        printf("Max backlog reached. Dropping request.\n");
        free(req);
    } else {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&manager->pool.lock);
            return;
        }

        new_node->request = req;
        new_node->next = manager->pool.head;
        manager->pool.head = new_node;
        manager->pool.count++;
    }

    pthread_mutex_unlock(&manager->pool.lock);
}

void cleanup_expired_requests(NetworkManager *manager) {
    time_t now = time(NULL);

    Node *current = manager->pool.head;
    Node *prev = NULL;

    while (current != NULL) {
        if (difftime(now, current->request->timeout) > 0) {
            Node *to_delete = current;

            if (prev == NULL) {
                manager->pool.head = current->next;
            } else {
                prev->next = current->next;
            }

            free(to_delete->request);
            free(to_delete);

            pthread_mutex_lock(&manager->pool.lock);
            manager->pool.count--;
            pthread_mutex_unlock(&manager->pool.lock);
        } else {
            prev = current;
        }
        current = current->next;
    }
}

void* cleanup_thread_func(void *arg) {
    NetworkManager *manager = (NetworkManager*)arg;

    while (manager->is_running) {
        cleanup_expired_requests(manager);
        sleep(1); // Adjust the interval based on requirements
    }

    return NULL;
}

void start_cleanup(NetworkManager *manager) {
    pthread_create(&manager->cleanup_thread, NULL, cleanup_thread_func, manager);
    manager->is_running = 1;
}

void stop_cleanup(NetworkManager *manager) {
    manager->is_running = 0;
    pthread_join(manager->cleanup_thread, NULL);
}

void log_connections(ConnectionPool *pool) {
    Node *current = pool->head;

    while (current != NULL) {
        printf("Session ID: %s, Client IP: %s\n", current->request->session_id, current->request->client_ip);
        current = current->next;
    }
}

void shutdown(NetworkManager *manager) {
    stop_cleanup(manager);

    Node *current = manager->pool.head;
    while (current != NULL) {
        Node *to_delete = current;
        current = current->next;

        free(to_delete->request);
        free(to_delete);
    }

    pthread_mutex_destroy(&manager->pool.lock);
}

int main() {
    NetworkManager manager;
    init_pool(&manager.pool);

    start_cleanup(&manager);

    // Example usage
    ConnectionRequest *req1 = create_request("session_001", "192.168.0.1", time(NULL) + 10);
    add_request(&manager, req1);

    log_connections(&manager.pool);

    sleep(15); // Let the cleanup thread run

    shutdown(&manager);

    return 0;
}
```

This library manages a pool of network connection requests with features for concurrency, automatic expiration handling, efficient memory management, and logging. Adjustments can be made to suit specific resource constraints or additional requirements.']

['Below is a C implementation that addresses your requirements for managing a dynamically resizable array of `LTE_PHY_RX_stat` structures, with considerations for memory management, thread safety, logging, and scalability.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int ue_id;
    int pci;
    unsigned long timestamp;
    uint32_t checksum; // Example field for data integrity
} LTEPHY_RX_UE;

typedef struct {
    LTEPHY_RX_UE* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    atomic_int interval_threshold;
    atomic_int stat_interval;
} LTE_PHY_RX_stat;

// Function prototypes
LTE_PHY_RX_stat* create_lte_phy_rx_stat(size_t initial_capacity);
void free_lte_phy_rx_stat(LTE_PHY_RX_stat* array);
int resize_array(LTE_PHY_RX_stat* array, size_t new_capacity);
void set_statistical_parameters(LTE_PHY_RX_stat* array, int interval, int threshold);
uint32_t calculate_checksum(const LTEPHY_RX_UE* ue);
void log_message(const char* message, int level);

// Logging levels
enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
};

// Create and initialize the LTE_PHY_RX_stat structure
LTE_PHY_RX_stat* create_lte_phy_rx_stat(size_t initial_capacity) {
    LTE_PHY_RX_stat* array = (LTE_PHY_RX_stat*)malloc(sizeof(LTE_PHY_RX_stat));
    if (!array) {
        log_message("Memory allocation failed for LTE_PHY_RX_stat", LOG_ERROR);
        return NULL;
    }

    array->data = (LTEPHY_RX_UE*)calloc(initial_capacity, sizeof(LTEPHY_RX_UE));
    if (!array->data) {
        free(array);
        log_message("Memory allocation failed for LTEPHY_RX_UE data", LOG_ERROR);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initial_capacity;
    array->count = 0;

    atomic_store(&array->interval_threshold, 10); // Default threshold
    atomic_store(&array->stat_interval, 5);       // Default interval

    return array;
}

// Free the LTE_PHY_RX_stat structure and its resources
void free_lte_phy_rx_stat(LTE_PHY_RX_stat* array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->data);
        pthread_mutex_unlock(&array->lock);

        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

// Resize the internal data array
int resize_array(LTE_PHY_RX_stat* array, size_t new_capacity) {
    if (!array || !pthread_mutex_lock(&array->lock)) return 0;

    LTEPHY_RX_UE* new_data = (LTEPHY_RX_UE*)realloc(array->data, new_capacity * sizeof(LTEPHY_RX_UE));
    if (!new_data) {
        log_message("Memory reallocation failed", LOG_ERROR);
        pthread_mutex_unlock(&array->lock);
        return 0;
    }

    array->capacity = new_capacity;
    array->data = new_data;

    pthread_mutex_unlock(&array->lock);
    return 1;
}

// Set statistical parameters
void set_statistical_parameters(LTE_PHY_RX_stat* array, int interval, int threshold) {
    if (!array || !pthread_mutex_lock(&array->lock)) return;

    atomic_store(&array->stat_interval, interval);
    atomic_store(&array->interval_threshold, threshold);

    pthread_mutex_unlock(&array->lock);
}

// Calculate checksum for LTEPHY_RX_UE
uint32_t calculate_checksum(const LTEPHY_RX_UE* ue) {
    if (!ue) return 0;
    uint32_t checksum = 0;
    checksum += ue->ue_id;
    checksum += ue->pci;
    checksum += (ue->timestamp & 0xFFFFFFFF);
    return ~checksum;
}

// Log messages with timestamps
void log_message(const char* message, int level) {
    time_t now = time(NULL);
    struct tm* t = localtime(&now);

    printf("[%02d-%02d %02d:%02d:%02d] [%s]: %s\n",
           t->tm_mon + 1, t->tm_mday, t->tm_hour,
           t->tm_min, t->tm_sec, level == LOG_INFO ? "INFO" :
           level == LOG_WARNING ? "WARNING" : "ERROR", message);
}

// Unit tests and further functions would be implemented similarly
