NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t n, uint32_t seed) {
    pthread_mutex_lock(&lock);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
