#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 0xFFFFF

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    CRC_INDICATION_REL8_TAG_T tag;
    // Other fields can be added here as needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock; // Using a mutex for simplicity, consider lock-free alternatives
} Collection;

Collection* create_collection() {
    Collection* coll = (Collection*)malloc(sizeof(Collection));
    if (!coll) return NULL;
    coll->head = NULL;
    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

bool is_valid_rnti(uint16_t rnti) {
    return rnti <= MAX_RNTI;
}

bool insert_pdu(Collection* coll, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_valid_rnti(pdu.tag.RNTI)) return false;

    pthread_mutex_lock(&coll->lock);

    Node** curr = &coll->head;
    while (*curr) {
        if ((*curr)->data.tag.RNTI == pdu.tag.RNTI) {
            pthread_mutex_unlock(&coll->lock);
            return false; // Duplicate RNTI, do not insert
        }
        curr = &(*curr)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&coll->lock);
        return false; // Memory allocation failure
    }
    *curr = new_node;
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_unlock(&coll->lock);
    return true;
}

void print_collection(Collection* coll) {
    pthread_mutex_lock(&coll->lock);

    Node* curr = coll->head;
    while (curr) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n",
               curr->data.tag.RX_UE_INFORMATION_TAG,
               curr->data.tag.RNTI,
               curr->data.tag.CRCFLAG);
        curr = curr->next;
    }

    pthread_mutex_unlock(&coll->lock);
}

bool remove_pdu(Collection* coll, uint16_t rnti) {
    if (!is_valid_rnti(rnti)) return false;

    pthread_mutex_lock(&coll->lock);

    Node** curr = &coll->head;
    while (*curr) {
        if ((*curr)->data.tag.RNTI == rnti) {
            Node* to_delete = *curr;
            *curr = (*curr)->next;
            free(to_delete);
            pthread_mutex_unlock(&coll->lock);
            return true;
        }
        curr = &(*curr)->next;
    }

    pthread_mutex_unlock(&coll->lock);
    return false; // RNTI not found
}

void destroy_collection(Collection* coll) {
    pthread_mutex_lock(&coll->lock);

    Node* curr = coll->head;
    while (curr) {
        Node* to_delete = curr;
        curr = curr->next;
        free(to_delete);
    }

    pthread_mutex_unlock(&coll->lock);
    pthread_mutex_destroy(&coll->lock);
    free(coll);
}

int main() {
    Collection* coll = create_collection();
    if (!coll) return 1;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{.RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRCFLAG = 0}};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {{.RX_UE_INFORMATION_TAG = 2, .RNTI = 200, .CRCFLAG = 1}};

    insert_pdu(coll, pdu1);
    insert_pdu(coll, pdu2);

    print_collection(coll);

    remove_pdu(coll, 100);
    print_collection(coll);

    destroy_collection(coll);
    return 0;
}
