```c
#include <stdio.h>
#include <stdlib.h>
import "json-c/json.h"
#include <pthread.h>
#include <unistd.h>

#define MAX_UE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node* node) {
    free(node);
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        Node* entry = *current;
        if (entry->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            entry->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Already exists
        }
        current = &entry->next;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    *current = new_node;
    pthread_mutex_unlock(&list->lock);
    return 1;
}

void log_operation(const char* message) {
    FILE* log_file = fopen("operation.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int load_configuration(const char* filename, List* list) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(length + 1);
    fread(buffer, 1, length, file);
    fclose(file);

    if (!buffer) return -2;

    struct json_object* parsed_json;
    struct json_object* ue_info_array;
    struct json_object* entry;

    parsed_json = json_tokener_parse(buffer);
    free(buffer);

    if (json_object_get_type(parsed_json) != json_type_array)
        return -3; // Not an array

    json_object_object_get_ex(parsed_json, "UE_INFORMATION", &ue_info_array);

    int n_entries = json_object_array_length(ue_info_array);
    for (int i = 0; i < n_entries; ++i) {
        entry = json_object_array_get_idx(ue_info_array, i);

        struct json_object* rx_ue_tag;
        struct json_object* rnti;
        struct json_object* crc_indication_rel8_tag;
        struct json_object* crcflag;

        if (json_object_object_get_ex(entry, "RX_UE_INFORMATION_TAG", &rx_ue_tag) &&
            json_object_object_get_ex(entry, "RNTI", &rnti) &&
            json_object_object_get_ex(entry, "CRC_INDICATION_REL8_TAG", &crc_indication_rel8_tag) &&
            json_object_object_get_ex(entry, "CRCFLAG", &crcflag)) {

            NFAPI_CRC_INDICATION_PDU_T data;
            data.RX_UE_INFORMATION_TAG = (int)json_object_get_int(rx_ue_tag);
            data.RNTI = (int)json_object_get_int(rnti);
            json_object_array_get_all(crc_indication_rel8_tag, &data.CRC_INDICATION_REL8_TAG, 4);
            data.CRCFLAG = (uint8_t)json_object_get_boolean(crcflag);

            if (add_to_list(list, data) == -1) {
                log_operation("Failed to allocate memory for new NFAPI_CRC_INDICATION_PDU_T entry.");
                json_object_put(parsed_json);
                return -4;
            }
        } else {
            log_operation("Corrupted configuration entry skipped.");
        }
    }

    json_object_put(parsed_json);
    return 0; // Success
}

void* thread_safe_update(void* arg) {
    List* list = (List*)arg;
    NFAPI_CRC_INDICATION_PDU_T data;
    data.RX_UE_INFORMATION_TAG = rand() % MAX_UE;
    data.RNTI = rand() % MAX_UE;
    for (int i = 0; i < 4; ++i) {
        data.CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }
    data.CRCFLAG = rand() & 1;

    if (add_to_list(list, data) == 1) {
        char log_msg[100];
        sprintf(log_msg, "Added new entry: RX_UE=%d RNTI=%d", data.RX_UE_INFORMATION_TAG, data.RNTI);
        log_operation(log_msg);
    } else {
        log_operation("Failed to add new entry due to memory constraints.");
    }

    return NULL;
}

int main() {
    List* list = create_list();

    if (load_configuration("config.json", list) != 0) {
        log_operation("Failed to load configuration file.");
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, thread_safe_update, list);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_list(list);

    return 0;
}
