#include <pthread.h>
#include <time.h>

// Define the structure for network interface statistics.
typedef struct {
    time_t timestamp;
    unsigned long packet_count;
    unsigned long byte_count;
    double error_rate;
} NetworkStats;

// Define a dynamic array structure
typedef struct {
    NetworkStats *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety in a distributed system.
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *array) {
    array->size = 0;
    array->capacity = 10;
    array->data = malloc(array->capacity * sizeof(NetworkStats));
    pthread_mutex_init(&array->lock, NULL);
}

// Resize the dynamic array when necessary
void resize_dynamic_array(DynamicArray *array) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(NetworkStats));
    }
}

// Update network statistics in the dynamic array
void update_statistics(DynamicArray *array, unsigned long packets, unsigned long bytes, double errors) {
    pthread_mutex_lock(&array->lock);

    resize_dynamic_array(array);

    // Create a new entry with current timestamp and provided stats
    NetworkStats *new_stat = &array->data[array->size++];
    time_t now = time(NULL);
    new_stat->timestamp = now;
    new_stat->packet_count = packets;
    new_stat->byte_count = bytes;
    new_stat->error_rate = errors;

    pthread_mutex_unlock(&array->lock);
}

// Function to flush statistics to a logging system (stubbed for illustration)
void flush_statistics_to_logging(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    // Simulate sending the data to a distributed logging system
    for (size_t i = 0; i < array->size; ++i) {
        printf("Timestamp: %ld, Packets: %lu, Bytes: %lu, Error Rate: %.2f\n",
               array->data[i].timestamp,
               array->data[i].packet_count,
               array->data[i].byte_count,
               array->data[i].error_rate);
    }

    // Clear the array after flushing
    array->size = 0;

    pthread_mutex_unlock(&array->lock);
}

// Cleanup function to free allocated resources
void cleanup_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    DynamicArray stats_array;
    init_dynamic_array(&stats_array);

    // Simulate updating statistics
    update_statistics(&stats_array, 100, 2000, 0.01);
    update_statistics(&stats_array, 150, 3000, 0.02);

    // Periodically flush the statistics to a logging system
    flush_statistics_to_logging(&stats_array);

    cleanup_dynamic_array(&stats_array);

    return 0;
}
