// Initialize the list
void initialize_list(NFAPICRCIndicationList *list) {
    list->data = malloc(INITIAL_LIST_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        log_message("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T list.");
        exit(EXIT_FAILURE);
    }
    list->capacity = INITIAL_LIST_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Destroy the list and free resources
void destroy_list(NFAPICRCIndicationList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

// Load configuration from a JSON file
void load_config(const char* filepath, int *rnti_increment, int *crcflag_base) {
    json_error_t error;
    json_t *root = json_load_file(filepath, 0, &error);

    if (!root) {
        log_message("Failed to open configuration file.");
        return;
    }

    const char *json_rnti_increment = json_string_value(json_object_get(root, "rnti_increment"));
    const char *json_crcflag_base = json_string_value(json_object_get(root, "crcflag_base"));

    if (json_rnti_increment) {
        *rnti_increment = atoi(json_rnti_increment);
    }

    if (json_crcflag_base) {
        *crcflag_base = atoi(json_crcflag_base);
    }

    json_decref(root);
}

// Update the list with new entries
void update_list(NFAPICRCIndicationList *list, size_t num_new_entries, const int rnti_increment, const int crcflag_base) {
    pthread_mutex_lock(&list->lock);

    if (list->size + num_new_entries > list->capacity) {
        size_t new_capacity = list->capacity;
        while (new_capacity < list->size + num_new_entries) {
            new_capacity *= 2;
        }
        NFAPI_CRC_INDICATION_PDU_T *temp_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) {
            log_message("Failed to reallocate memory for NFAPI_CRC_INDICATION_PDU_T list.");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->data = temp_data;
        list->capacity = new_capacity;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_new_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[list->size + i];
        entry->RX_UE_INFORMATION_TAG = rand();
        entry->RNTI = list->size + i * rnti_increment;
        entry->CRC_INDICATION_REL8_TAG = rand() % 256; // Example tag value
        entry->CRCFLAG = crcflag_base + (rand() % 2);
        entry->timestamp = time(NULL); // Timestamp for telemetry data

        log_message("Added new NFAPI_CRC_INDICATION_PDU_T entry.");
    }

    list->size += num_new_entries;
    pthread_mutex_unlock(&list->lock);
}

// Log messages to a file or console
void log_message(const char *message) {
    FILE *log_file = fopen("system_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        printf("%s\n", message); // Fallback to console
    }
}

// Main function for demonstration purposes
int main() {
    NFAPICRCIndicationList list;
    initialize_list(&list);

    int rnti_increment = 1, crcflag_base = 0;
    load_config("config.json", &rnti_increment, &crcflag_base);

    update_list(&list, 20, rnti_increment, crcflag_base); // Add 20 new entries

    destroy_list(&list);

    return 0;
}
