```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <json-c/json.h>

#define MAX_RNTI 1024 // Define maximum number of RNTIs
#define LOGGING_ENABLED 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Configuration structure
typedef struct {
    int rnti_pool_size;
    int reclamation_policy;
    int validation_frequency;
    int logging_enabled;
} Config;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
int available_rntis[MAX_RNTI] = {0};
NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
size_t pdu_count = 0;
Config current_config = {MAX_RNTI, 1, 10, LOGGING_ENABLED};

// Logging utility
void log_info(const char* message) {
    if (current_config.logging_enabled) {
        printf("INFO: %s\n", message);
    }
}

// Load configuration from JSON file
int load_configuration(const char *filename) {
    struct json_object *parsed_json;
    struct json_object *rnti_pool_size, *reclamation_policy, *validation_frequency, *logging_enabled;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char*)malloc(length + 1);
    fread(buffer, 1, length, file);
    buffer[length] = '\0';

    parsed_json = json_tokener_parse(buffer);
    free(buffer);
    fclose(file);

    if (!parsed_json) return -1;

    if (json_object_object_get_ex(parsed_json, "rnti_pool_size", &rnti_pool_size)) {
        current_config.rnti_pool_size = json_object_get_int(rnti_pool_size);
    }
    if (json_object_object_get_ex(parsed_json, "reclamation_policy", &reclamation_policy)) {
        current_config.reclamation_policy = json_object_get_int(reclamation_policy);
    }
    if (json_object_object_get_ex(parsed_json, "validation_frequency", &validation_frequency)) {
        current_config.validation_frequency = json_object_get_int(validation_frequency);
    }
    if (json_object_object_get_ex(parsed_json, "logging_enabled", &logging_enabled)) {
        current_config.logging_enabled = json_object_get_boolean(logging_enabled);
    }

    log_info("Configuration loaded successfully.");
    return 0;
}

// Initialize available RNTI pool
void initialize_rnti_pool() {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < MAX_RNTI; ++i) {
        available_rntis[i] = i + 1;
    }
    pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_config.rnti_pool_size);
    pthread_mutex_unlock(&list_lock);
}

// Function to manage dynamic list
int manage_dynamic_nfa_pdu_list(size_t count) {
    if (pthread_mutex_trylock(&list_lock)) return -1;

    size_t needed_rntis = 0;
    for (size_t i = 0; i < pdu_count; ++i) {
        int rnti = pdu_list[i].RNTI;
        if (rnti == 0 || available_rntis[rnti - 1] != rnti) {
            needed_rntis++;
        }
    }

    if (pdu_count + count > current_config.rnti_pool_size) {
        pthread_mutex_unlock(&list_lock);
        return -2; // Insufficient RNTI pool size
    }

    for (size_t i = 0; i < count; ++i) {
        int rnti;
        do {
            if (needed_rntis > 0 && available_rntis[needed_rntis - 1]) {
                rnti = available_rntis[--needed_rntis];
            } else {
                pthread_mutex_unlock(&list_lock);
                return -3; // Insufficient resources
            }
        } while (rnti == 0);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rnti;
        pdu.CRCFLAG = rand() % 2;

        available_rntis[rnti - 1] = 0; // Mark RNTI as used
        pdu_list[pdu_count++] = pdu;

        log_info("Allocated and initialized a new PDU.");
    }

    pthread_mutex_unlock(&list_lock);
    return 0;
}

// Periodic validation of the RNTI pool
void validate_rnti_pool() {
    while (1) {
        sleep(current_config.validation_frequency);

        pthread_mutex_lock(&list_lock);
        for (size_t i = 0; i < pdu_count; ++i) {
            if (pdu_list[i].RNTI != 0 && available_rntis[pdu_list[i].RNTI - 1] == pdu_list[i].RNTI) {
                log_info("Inconsistency detected in RNTI pool.");
                available_rntis[pdu_list[i].RNTI - 1] = 0; // Revalidate
            }
        }
        pthread_mutex_unlock(&list_lock);
    }
}

// Example usage
int main() {
    srand(time(NULL));
    load_configuration("config.json");

    initialize_rnti_pool();
    if (manage_dynamic_nfa_pdu_list(10) != 0) {
        log_info("Error managing dynamic list.");
        return -1;
    }

    pthread_t validation_thread;
    if (pthread_create(&validation_thread, NULL, (void*)validate_rnti_pool, NULL)) {
        log_info("Failed to create validation thread.");
        return -2;
    }

    // Join the validation thread in a real application
    pthread_join(validation_thread, NULL);

    free(pdu_list);
    return 0;
}
