#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Assuming CRCFLAG is an integer for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety during memory allocation
pthread_mutex_t alloc_mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_nfa_api_crc_indications(NFAPI_CRC_INDICATION_PDU_T **array, size_t *size) {
    if (array == NULL || size == NULL) return -1;

    pthread_mutex_lock(&alloc_mutex);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*size + 1));
    if (temp == NULL) {
        printf("Error: Memory allocation failed\n");
        pthread_mutex_unlock(&alloc_mutex);
        return -2;
    }

    // Initialize the new structure
    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    srand((unsigned int)time(NULL) ^ pthread_self()); // Seed with time and thread ID for variability

    new_pdu.RX_UE_INFORMATION_TAG = rand() % MAX_RNTI + 1; // Assuming 0 is invalid
    new_pdu.RNTI = rand() % MAX_RNTI + 1;

    int crcflag_candidate;
    do {
        crcflag_candidate = rand() % 2;
    } while ((*size > 0) && (crcflag_candidate != (*array)[(*size - 1)].CRCFLAG));

    new_pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Random value for tag
    new_pdu.CRCFLAG = crcflag_candidate;

    // Check for RNTI uniqueness
    for (size_t i = 0; i < *size; ++i) {
        if ((*array)[i].RNTI == new_pdu.RNTI) {
            printf("Error: Duplicate RNTI found\n");
            free(temp);
            pthread_mutex_unlock(&alloc_mutex);
            return -3;
        }
    }

    // Add the new structure to the array
    temp[*size] = new_pdu;
    *array = temp;
    (*size)++;

    pthread_mutex_unlock(&alloc_mutex);

    return 0;
}

