            printf("Test failed at iteration %d with status code: %d\n", i, status);
            break;
        }
    }

    for (int i = 0; i < size; ++i) {
        printf("Entry %zu -> RNTI: %u, CRCFLAG: %d\n", i + 1, array[i].RNTI, array[i].CRCFLAG);
    }

    // Free allocated memory
    free(array);
}

int main() {
