// Function to initialize AES-256-CBC cipher context
EVP_CIPHER_CTX *initialize_aes_256_cbc_cipher(const char *password, const unsigned char salt[16], int iterations) {
    if (password == NULL || strlen(password) == 0) {
        fprintf(stderr, "Error: Password is null or empty.\n");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context.\n");
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[16]; // AES block size is 16 bytes

    // Derive a 256-bit key using PBKDF2
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                          iterations, EVP_sha256(), 32, key) <= 0) {
        fprintf(stderr, "Error deriving encryption key.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Generate a random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating initialization vector (IV).\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher context with AES-256-CBC
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption operation.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up and disable the cipher context
void cleanup_cipher_context(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}
