        log_error("Invalid input parameters.");
        return;
    }

    clock_t start_time = clock();
    unsigned long initial_rss = get_resident_set_size();

    for (size_t i = 0; i < *size; ++i) {
        // Simulate varying network conditions by introducing a delay
        if (rand() % 10 == 0) {
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = 10000000L; // 10 ms delay
