#define KEY_SIZE 32 // 256 bits for AES-256
#define IV_SIZE 16  // Block size for AES

// Function to derive a key from the password using PBKDF2 with a salt and specified iterations.
int derive_key_and_iv(const char *password, const unsigned char *salt, int salt_len,
                      unsigned char *key, int key_len, unsigned char *iv, int iv_len) {
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 128, EVP_sha256(), key_len + iv_len, iv) == 0) {
        fprintf(stderr, "Error deriving key and IV\n");
        return 0;
    }
    memcpy(key, iv, key_len);
    return 1;
}

// Helper function to generate a secure random salt
int generate_salt(unsigned char *salt, int salt_len) {
    if (!RAND_bytes(salt, salt_len)) {
        fprintf(stderr, "Error generating salt\n");
        return 0;
    }
    return 1;
}

// Helper function to generate a cryptographically secure IV
int generate_iv(unsigned char *iv, int iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Error generating IV\n");
        return 0;
    }
    return 1;
}

// Function to initialize AES-256-CBC cipher context
EVP_CIPHER_CTX* init_cipher_context(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    unsigned char salt[8];
    if (!generate_salt(salt, sizeof(salt))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[KEY_SIZE + IV_SIZE], iv[IV_SIZE];
    if (!derive_key_and_iv(password, salt, sizeof(salt), key, KEY_SIZE, iv, IV_SIZE)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Store salt and other secure information as needed for decryption
    // Secure storage implementation would go here

    return ctx;
}

// Function to encrypt data using the initialized context
int encrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len) {
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, ciphertext_len, plaintext, plaintext_len)) {
        fprintf(stderr, "Error during encryption\n");
        return 0;
    }

    int len = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + *ciphertext_len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        return 0;
    }
    *ciphertext_len += len;

    return 1;
}

// Function to decrypt data using the initialized context
int decrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len) {
    if (1 != EVP_DecryptUpdate(ctx, plaintext, plaintext_len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error during decryption\n");
        return 0;
    }

    int len = 0;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + *plaintext_len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        return 0;
    }
    *plaintext_len += len;

    return 1;
}

// Function to clean up cipher context
void cleanup_cipher_context(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
