#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

#define AES_256_KEY_SIZE 32
#define IV_SIZE 16

typedef enum {
    MODE_CBC,
    MODE_CFB,
    MODE_OFB
} EncryptionMode;

typedef struct {
    int mode;
    int pbkdf2_iterations;
} CipherConfig;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *key;
    unsigned char *iv;
} CipherContext;

CipherContext* initialize_cipher(const char *password, size_t password_len, const CipherConfig *config) {
    if (password == NULL || password_len == 0 || config == NULL) return NULL;

    CipherContext *cipher_ctx = malloc(sizeof(CipherContext));
    if (!cipher_ctx) return NULL;

    cipher_ctx->key = malloc(AES_256_KEY_SIZE);
    if (!cipher_ctx->key) {
        free(cipher_ctx);
        return NULL;
    }

    cipher_ctx->iv = malloc(IV_SIZE);
    if (!cipher_ctx->iv) {
        free(cipher_ctx->key);
        free(cipher_ctx);
        return NULL;
    }

    if (RAND_bytes(cipher_ctx->iv, IV_SIZE) != 1 || RAND_bytes(cipher_ctx->key, AES_256_KEY_SIZE) != 1) {
        fprintf(stderr, "Failed to generate random key or IV\n");
        free(cipher_ctx->iv);
        free(cipher_ctx->key);
        free(cipher_ctx);
        return NULL;
    }

    cipher_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx->ctx) {
        free(cipher_ctx->iv);
        free(cipher_ctx->key);
        free(cipher_ctx);
        return NULL;
    }

    const EVP_CIPHER *evp_cipher;
    switch (config->mode) {
        case MODE_CBC:
            evp_cipher = EVP_aes_256_cbc();
            break;
        case MODE_CFB:
            evp_cipher = EVP_aes_256_cfb1(); // Example for 1-byte shift register
            break;
        case MODE_OFB:
            evp_cipher = EVP_aes_256_ofb();
            break;
        default:
            fprintf(stderr, "Unsupported encryption mode\n");
            cleanup_cipher(cipher_ctx);
            return NULL;
    }

    if (!EVP_CipherInit_ex(cipher_ctx->ctx, evp_cipher, NULL, cipher_ctx->key, cipher_ctx->iv, 1)) {
        fprintf(stderr, "Cipher initialization failed\n");
        cleanup_cipher(cipher_ctx);
        return NULL;
    }

    return cipher_ctx;
}

void cleanup_cipher(CipherContext *cipher_ctx) {
    if (cipher_ctx) {
        if (cipher_ctx->ctx) EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx->key);
        free(cipher_ctx->iv);
        free(cipher_ctx);
    }
}

int main() {
    const char *password = "secure_password";
    CipherConfig config = {MODE_CBC, 10000};

    CipherContext *cipher_ctx = initialize_cipher(password, strlen(password), &config);
    if (!cipher_ctx) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        return EXIT_FAILURE;
    }

    // Example usage
    printf("Cipher initialized successfully.\n");

    cleanup_cipher(cipher_ctx);
    return EXIT_SUCCESS;
}
```

### Documentation and Usage

1. **Initialization**:
   - Use `initialize_cipher` with a password, its length, and a `CipherConfig` structure specifying the mode and PBKDF2 iterations.
   - Ensure the password is non-zero in length.

2. **Modes Supported**:
   - CBC: AES-256-CBC
   - CFB: AES-256-CFB (1-byte shift register example)
   - OFB: AES-256-OFB

3. **Error Handling**:
   - Check for `NULL` returns to handle initialization failures.
   - Use `cleanup_cipher` to release resources.

4. **Memory Management**:
   - The library dynamically allocates memory for the IV, key, and cipher context.
   - Ensure `cleanup_cipher` is called when done with the cipher context to prevent leaks.

5. **Integration**:
   - Easily integrate into larger applications by including this header file.
   - Extendable to support more modes or key derivation algorithms in the future.

This code provides a flexible foundation for symmetric encryption using AES-256, with secure key derivation and robust error handling.']

