#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RRP_SIZE 256

typedef struct {
    int ue_id;
    char rrp[MAX_RRP_SIZE];
} NF_ALU_CONFIG_REQUEST;

typedef struct ConfigNode {
    NF_ALU_CONFIG_REQUEST data;
    struct ConfigNode* next;
} ConfigNode;

typedef struct {
    ConfigNode* head;
    pthread_mutex_t lock;
    size_t max_entries;
} ConfigList;

ConfigList* create_config_list(size_t max_entries) {
    ConfigList* list = (ConfigList*)malloc(sizeof(ConfigList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_entries = max_entries;
    return list;
}

void free_config_list(ConfigList* list) {
    ConfigNode* current = list->head;
    while (current) {
        ConfigNode* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_or_update_entry(ConfigList* list, int ue_id, const char* rrp) {
    if (!list || !rrp) return -1;

    pthread_mutex_lock(&list->lock);

    ConfigNode *current = list->head, *prev = NULL;
    while (current && current->data.ue_id != ue_id) {
        prev = current;
        current = current->next;
    }

    if (current) {  // Update existing entry
        strncpy(current->data.rrp, rrp, MAX_RRP_SIZE);
    } else {  // Add new entry
        if (count_entries(list) >= list->max_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1;  // List is full
        }
        current = (ConfigNode*)malloc(sizeof(ConfigNode));
        if (!current) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        current->data.ue_id = ue_id;
        strncpy(current->data.rrp, rrp, MAX_RRP_SIZE);
        current->next = list->head;
        list->head = current;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int get_entry(ConfigList* list, int ue_id, char* rrp) {
    if (!list || !rrp) return -1;

    pthread_mutex_lock(&list->lock);

    ConfigNode* current = list->head;
    while (current && current->data.ue_id != ue_id) {
        current = current->next;
    }

    int result = (current) ? 0 : -1;
    if (result == 0) {
        strncpy(rrp, current->data.rrp, MAX_RRP_SIZE);
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

size_t count_entries(ConfigList* list) {
    size_t count = 0;
    ConfigNode* current = list->head;
    while (current) {
        count++;
        current = current->next;
    }
    return count;
}

void cleanup_expired(ConfigList* list, int (*is_expired)(int ue_id)) {
    if (!list || !is_expired) return;

    pthread_mutex_lock(&list->lock);

    ConfigNode *current = list->head, *prev = NULL;
    while (current) {
        if (is_expired(current->data.ue_id)) {
            ConfigNode* to_delete = current;
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}
