// Function to dynamically allocate memory for the list of structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_list(size_t count) {
    if (count > 10000) {
        fprintf(stderr, "Requested allocation exceeds maximum limit of 10,000.\n");
        return NULL;
    }

    // Allocate memory using posix_memalign to ensure cache line alignment
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int result = posix_memalign((void**)&list, 64, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (result != 0) {
        fprintf(stderr, "Memory allocation failed due to system constraints.\n");
        return NULL;
    }

    // Initialize each structure
    for (size_t i = 0; i < count; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Example initialization
        list[i].RNTI = rand() % 65536;                  // Example initialization
        list[i].CRCFLAG = calculate_crcflag(list[i].RNTI, list[i].RX_UE_INFORMATION_TAG);
    }

    printf("Memory allocated successfully for %zu entries.\n", count);

    return list;
}

