#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define SYSTEM_LIMIT 1000

typedef struct {
    int field1;
    char name[50];
} NFAPI_CRC_INDICATION_PDU_T;

extern void resetBlueslip();
extern void log_blueslip(const char* message);

static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *object_pool[SYSTEM_LIMIT] = {0};
static int pool_size = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_size > 0) {
        NFAPI_CRC_INDICATION_PDU_T *structure = object_pool[--pool_size];
        pthread_mutex_unlock(&pool_mutex);
        return structure;
    }
    pthread_mutex_unlock(&pool_mutex);

    NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structure == NULL) {
        log_blueslip("Memory allocation failed");
        resetBlueslip();
        return NULL;
    }
    return structure;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&pool_mutex);
    object_pool[pool_size++] = structure;
    pthread_mutex_unlock(&pool_mutex);
}

NFAPI_CRC_INDICATION_PDU_T** generateCRCIndications(int N, int seed) {
    if (N > SYSTEM_LIMIT || N <= 0) {
        log_blueslip("Invalid number of structures requested");
        resetBlueslip();
        return NULL;
    }

    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T **indication_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (indication_array == NULL) {
        log_blueslip("Memory allocation for array failed");
        resetBlueslip();
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        indication_array[i] = allocate_structure();
        if (indication_array[i] == NULL) {
            log_blueslip("Failed to allocate structure at index %d", i);
            resetBlueslip();

            while (--i >= 0) {
                deallocate_structure(indication_array[i]);
            }
            free(indication_array);
            return NULL;
        }

        indication_array[i]->field1 = rand() % 100; // Example field assignment
        snprintf(indication_array[i]->name, sizeof(indication_array[i]->name), "Test_%d", i + 1);
    }

    log_blueslip("Module: generateCRCIndications");
    printf("Total structures allocated: %d\n", N);
    for (int i = 0; i < N; ++i) {
        printf("Structure Name: %s\n", indication_array[i]->name);
    }

    return indication_array;
}

void freeCRCIndications(NFAPI_CRC_INDICATION_PDU_T** indications, int N) {
    if (!indications) return;

    for (int i = 0; i < N; ++i) {
