typedef struct {
    unsigned int RNTI;
    char RX_UE_INFORMATION_TAG[16];
    char CRC_INDICATION_REL8_TAG[16];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 100
#define LOAD_FACTOR 0.75

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

// Function prototypes
NFAPI_CRC_LIST* create_list();
void destroy_list(NFAPI_CRC_LIST* list);
bool add_pdu(NFAPI_CRC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* pdu);
bool validate_crcflag_uniqueness(const NFAPI_CRC_LIST* list, bool crcflag);

// Create a new list
NFAPI_CRC_LIST* create_list() {
    NFAPI_CRC_LIST *list = (NFAPI_CRC_LIST*) malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = INITIAL_SIZE;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Destroy the list
void destroy_list(NFAPI_CRC_LIST* list) {
    if (!list) return;

    free(list->array);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Check uniqueness of CRCFLAG
bool validate_crcflag_uniqueness(const NFAPI_CRC_LIST* list, bool crcflag) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->array[i].CRCFLAG == crcflag) return false;
    }
    return true;
}

// Add a new PDU to the list
bool add_pdu(NFAPI_CRC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (!validate_crcflag_uniqueness(list, pdu->CRCFLAG)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    if (list->size >= list->capacity * LOAD_FACTOR) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }

        list->array = new_array;
        list->capacity = new_capacity;
    }

    list->array[list->size] = *pdu;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Example usage
int main() {
    NFAPI_CRC_LIST* list = create_list();
    if (!list) return 1;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RNTI = 1234, .CRCFLAG = true };
    // Populate RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG appropriately
    strcpy(pdu.RX_UE_INFORMATION_TAG, "example_tag");
    strcpy(pdu.CRC_INDICATION_REL8_TAG, "crc_rel8_tag");

    if (add_pdu(list, &pdu)) {
        printf("PDU added successfully.\n");
    } else {
        printf("Failed to add PDU.\n");
    }

    destroy_list(list);
    return 0;
}
