```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ENTRIES 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} CRCList;

void initCRCList(CRCList *list) {
    list->size = 0;
    list->capacity = 10; // Initial capacity
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->mutex, NULL);
}

void destroyCRCList(CRCList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}

bool resizeCRCList(CRCList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_data) {
        perror("Failed to reallocate memory");
        return false;
    }
    list->data = new_data;
    list->capacity = new_capacity;
    return true;
}

bool addCRCIndication(CRCList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RX_UE_INFORMATION_TAG == 0 || element.RNTI == 0) {
        fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG or RNTI\n");
        return false;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (!resizeCRCList(list, new_capacity)) {
            fprintf(stderr, "Failed to resize list\n");
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }

    if (list->size >= MAX_ENTRIES) {
        fprintf(stderr, "Overflow: Maximum number of entries exceeded\n");
        pthread_mutex_unlock(&list->mutex);
        exit(EXIT_FAILURE);
    }

    list->data[list->size++] = element;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T *getCRCIndication(CRCList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[index];
    pthread_mutex_unlock(&list->mutex);

    return element;
}

bool removeCRCIndication(CRCList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return false;
    }

    pthread_mutex_lock(&list->mutex);

    memmove(&list->data[index], &list->data[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - index - 1));
    list->size--;

    if (list->size < list->capacity / 4 && list->capacity > 10) {
        size_t new_capacity = list->capacity / 2;
        resizeCRCList(list, new_capacity);
    }

    pthread_mutex_unlock(&list->mutex);
    return true;
}

int main() {
    CRCList list;
    initCRCList(&list);

    NFAPI_CRC_INDICATION_PDU_T element = {1, 1, {.CRCFLAG = rand() % 2}};
    addCRCIndication(&list, element);

    NFAPI_CRC_INDICATION_PDU_T *retrieved = getCRCIndication(&list, 0);
    if (retrieved) {
        printf("Retrieved CRCFLAG: %d\n", retrieved->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    removeCRCIndication(&list, 0);

    destroyCRCList(&list);
    return 0;
}
```

### Key Points:
