using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESService
{
    private static readonly object _lock = new object();

    public static string DecryptBase64Message(string base64Message, List<byte[]> keys, byte[] iv)
    {
        if (base64Message == null) throw new ArgumentNullException(nameof(base64Message));
        if (keys == null || keys.Count == 0) throw new ArgumentException("Keys list cannot be null or empty", nameof(keys));
        if (iv == null || iv.Length != 8 && iv.Length != 16) throw new ArgumentException("IV must be either 8 bytes for ECB mode or 16 bytes for CBC mode.");

        byte[] encryptedData;
        try
        {
            encryptedData = Convert.FromBase64String(base64Message);
        }
        catch (FormatException ex)
        {
            LogError("Invalid Base64 format", ex);
            return null; // Or throw a custom exception depending on error handling strategy.
        }

        foreach (var key in keys)
        {
            try
            {
                lock (_lock)
                {
                    using var tripleDes = new TripleDESCryptoServiceProvider { Key = key, IV = iv, Mode = CipherMode.CBC };
                    using var decryptor = tripleDes.CreateDecryptor();
                    using var msDecrypt = new MemoryStream(encryptedData);
                    using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
                    using var srDecrypt = new StreamReader(csDecrypt);

                    string decryptedMessage = srDecrypt.ReadToEnd();

                    LogSuccess("Decryption successful with key ID: " + ArrayToString(key));

                    return decryptedMessage;
                }
            }
            catch (CryptographicException ex)
            {
                LogError($"Decryption failed for key ID: {ArrayToString(key)}", ex);
                // Continue to the next key
            }
        }

        LogError("All decryption attempts failed.");
        return null; // Or throw a custom exception depending on error handling strategy.
    }

    private static void LogSuccess(string message)
    {
        Console.WriteLine("[SUCCESS] " + message); // Replace with your logging mechanism.
    }

    private static void LogError(string message, Exception ex = null)
    {
        Console.Error.WriteLine($"[ERROR] {message}. Exception: {ex?.Message}"); // Replace with your logging mechanism.
    }

    private static string ArrayToString(byte[] array)
    {
        return BitConverter.ToString(array).Replace("-", "");
    }
}

// Unit tests
public class TripleDESServiceTests
{
    [Test]
    public void TestSuccessfulDecryption()
    {
        var base64Message = Convert.ToBase64String(Encoding.UTF8.GetBytes("Hello World"));
        byte[] key1 = Encoding.UTF8.GetBytes("0123456789012345"); // Example 16-byte key for Triple DES.
        byte[] iv = Encoding.UTF8.GetBytes("12345678"); // Example 8-byte IV for CBC mode.

        var keys = new List<byte[]> { key1 };

        string result = TripleDESService.DecryptBase64Message(base64Message, keys, iv);
        Assert.AreEqual("Hello World", result);
