// Function to initialize the configuration manager
void init_config_manager(LTE_PHY_ConfigManager *manager) {
    pthread_rwlock_init(&manager->rwlock, NULL);
    manager->num_params = 0;
}

// Validate integrity of the configuration data
int validate_configuration(const LTE_PHY_Param *params, int num_params) {
    for (int i = 0; i < num_params; ++i) {
        if (strlen(params[i].value) == 0 || params[i].parameter_id <= 0) {
            return 0; // Invalid data
        }
    }
    return 1;
}

// Load configuration from external service with error handling
int load_configuration(LTE_PHY_ConfigManager *manager) {
    LTE_PHY_Param params[MAX_CONFIG_PARAMS];
    int result = external_config_service_fetch(params, &manager->num_params);

    if (result != EXTERNAL_SUCCESS || !validate_configuration(params, manager->num_params)) {
        return 0; // Failed to load or validate configuration
    }

    pthread_rwlock_wrlock(&manager->rwlock);
    for (int i = 0; i < manager->num_params; ++i) {
        manager->config_params[i] = params[i];
    }
    pthread_rwlock_unlock(&manager->rwlock);

    return 1;
}

// Get configuration parameter value
const char* get_param_value(LTE_PHY_ConfigManager *manager, int param_id) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (int i = 0; i < manager->num_params; ++i) {
        if (manager->config_params[i].parameter_id == param_id) {
            const char* value = manager->config_params[i].value;
            pthread_rwlock_unlock(&manager->rwlock);
            return value;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return NULL; // Parameter not found
}

// Update configuration parameter value, thread-safe
int update_param_value(LTE_PHY_ConfigManager *manager, int param_id, const char *value) {
    if (strlen(value) == 0 || param_id <= 0) return 0;

    pthread_rwlock_wrlock(&manager->rwlock);

    for (int i = 0; i < manager->num_params; ++i) {
        if (manager->config_params[i].parameter_id == param_id) {
            strncpy(manager->config_params[i].value, value, sizeof(manager->config_params[i].value) - 1);
            pthread_rwlock_unlock(&manager->rwlock);
            return 1;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Parameter not found
}

// Cache eviction strategy can be implemented as needed based on specific access patterns

