}

void resize_list_if_needed(NFAPICRCIndicationList *list, size_t max_memory) {
    size_t current_size = list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (current_size >= max_memory) return; // No need to grow

    size_t new_capacity = list->capacity * 2;
    while ((new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > max_memory) {
        new_capacity /= 2;
        if (new_capacity <= list->capacity) break;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void destroy_list(NFAPICRCIndicationList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

void generate_random_crc_flag(uint8_t *crc_flag, unsigned int seed, size_t timeout_ms) {
    srand(seed);
    time_t start = time(NULL);
    while (time(NULL) - start < timeout_ms / 1000.0) {
        if ((*crc_flag = rand() % 2)) return;
    }
}

void populate_list(NFAPICRCIndicationList *list, size_t n, unsigned int seed, uint16_t rnti_min, uint16_t rnti_max, size_t max_memory) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < n; ++i) {
        resize_list_if_needed(list, max_memory);

        if (list->count >= list->capacity) break;

        uint8_t crc_flag;
        generate_random_crc_flag(&crc_flag, seed + i, 100); // Random timeout of 100ms

        RX_UE_INFORMATION_TAG rx_ue_info = { .crc_tag = { .CRCFLAG = crc_flag } };
        if (rnti_min <= (list->data[list->count].rx_ue_info.crc_tag.CRCFLAG + rand() % (rnti_max - rnti_min)) && 
