        FILE *file = fopen(output_filename, "wb");
        if (file != NULL) {
            fwrite(&compressed_size, sizeof(compressed_size), 1, file);
            fwrite(compressed_data, compressed_size, 1, file);
            fclose(file);
        }
    }

    free(compressed_data);
}

