#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 65535

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
    size_t count;
} NFAPIList;

NFAPIList* create_nfa_list() {
    NFAPIList *list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

int validate_rnti(uint16_t rnti) {
    // Example validation: RNTI should be non-zero and within valid range
    return rnti > 0 && rnti <= MAX_RNTI;
}

void* serialize_list(NFAPIList *list, char **output, size_t *size) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    // Calculate required buffer size
    size_t bufferSize = sizeof(size_t); // for count
    while (current != NULL) {
        bufferSize += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    char *buffer = (char*)malloc(bufferSize);
    if (!buffer) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    size_t offset = 0;
    memcpy(buffer + offset, &list->count, sizeof(size_t));
    offset += sizeof(size_t);

    current = list->head;
    while (current != NULL) {
        memcpy(buffer + offset, &(current->pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    *output = buffer;
    *size = bufferSize;

    pthread_mutex_unlock(&list->lock);
    return buffer;
}

int deserialize_list(char *input, size_t input_size, NFAPIList **list) {
    if (!list || !input || input_size < sizeof(size_t)) {
        return -1; // Error
    }

    size_t count;
    memcpy(&count, input, sizeof(size_t));

    NFAPIList *nfa_list = create_nfa_list();
    if (!nfa_list) {
        return -2; // Memory allocation error
    }

    ListNode **current_ptr = &(nfa_list->head);
    size_t offset = sizeof(size_t);

    for (size_t i = 0; i < count && offset + sizeof(NFAPI_CRC_INDICATION_PDU_T) <= input_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)(input + offset);

        // Validate RNTI
        if (!validate_rnti(pdu->rnti)) {
            free(nfa_list);  // Clean up on error
            return -3;       // Invalid RNTI error
        }

        ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
        if (!new_node) {
            free(nfa_list);
            return -4;  // Memory allocation failure
        }

        new_node->pdu = *pdu;
        new_node->next = NULL;

        *current_ptr = new_node;
        current_ptr = &new_node->next;

        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    nfa_list->count = count;  // Update the count
    *list = nfa_list;
    return 0; // Success
}

int add_pdu_to_list(NFAPIList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!list || !pdu || !validate_rnti(pdu->rnti)) {
        return -1; // Error
    }

    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        return -2; // Memory allocation error
    }

    new_node->pdu = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        ListNode *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_nfa_list(NFAPIList *list) {
    if (!list) return;

    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example unit test function
void test_add_and_serialize() {
    NFAPIList *nfa_list = create_nfa_list();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{.RNTI = 123}, .rnti = 123, {.CRCFLAG = 1}};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {{.RNTI = 456}, .rnti = 456, {.CRCFLAG = 0}};

    add_pdu_to_list(nfa_list, &pdu1);
    add_pdu_to_list(nfa_list, &pdu2);

    char *serialized_data;
    size_t serialized_size;

    serialize_list(nfa_list, &serialized_data, &serialized_size);
    if (serialized_data) {
        printf("Serialization successful, data size: %zu\n", serialized_size);
        free(serialized_data);
    }

    NFAPIList *deserialized_list = NULL;
    deserialize_list(serialized_data, serialized_size, &deserialized_list);

    if (deserialized_list != NULL && deserialized_list->count == 2) {
        printf("Deserialization successful\n");
    }

    free_nfa_list(nfa_list);
    free_nfa_list(deserialized_list);
}

int main() {
    test_add_and_serialize();
    return 0;
}
