#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>

// Define structure and constants
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RX_UE_INFO 1000
#define MIN_RNTI 1
#define MAX_RNTI 500

// Global variables
NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
size_t pool_size = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Utility function to generate a random number within a range
uint16_t random_rnti() {
    return MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
}

// Function to validate the structure
bool is_valid_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->RX_UE_INFORMATION_TAG >= MAX_RX_UE_INFO || pdu->RNTI < MIN_RNTI || pdu->RNTI > MAX_RNTI)
        return false;

    // Ensure no two consecutive structures have the same RNTI
    pthread_mutex_lock(&pool_mutex);
    if (pool_size > 0 && pool[pool_size - 1].RNTI == pdu->RNTI) {
        pthread_mutex_unlock(&pool_mutex);
        return false;
    }
    pthread_mutex_unlock(&pool_mutex);

    return true;
}

// Function to add a new PDU structure
bool add_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!is_valid_pdu(pdu))
        return false;

    pthread_mutex_lock(&pool_mutex);

    // Resize pool if needed
    size_t new_size = pool_size + 1;
    NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) {
        pthread_mutex_unlock(&pool_mutex);
        return false;
    }

    pool = new_pool;
    pool[pool_size] = *pdu;
    pool_size++;

    pthread_mutex_unlock(&pool_mutex);
    return true;
}

// Function to create a new PDU and add it to the pool
bool create_and_add_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Populate structure with random values
    pdu.RX_UE_INFORMATION_TAG = rand() % MAX_RX_UE_INFO;
    do {
        pdu.RNTI = random_rnti();
    } while (!is_valid_pdu(&pdu));

    pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Example tag value
    pdu.CRCFLAG = rand() % 2 == 0;

    return add_pdu(&pdu);
}

// Function to free the pool memory
void cleanup_pool() {
    pthread_mutex_lock(&pool_mutex);
    free(pool);
    pool = NULL;
    pool_size = 0;
    pthread_mutex_unlock(&pool_mutex);
}

int main() {
    srand(time(NULL));

    // Example usage: add PDUs in a multi-threaded manner
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))create_and_add_pdu, NULL)) {
            perror("Failed to create thread");
        }
    }

    // Join all threads
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_pool();

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses a mutex (`pthread_mutex_t`) to ensure thread-safe access to the shared pool.
- **Memory Management**: Dynamically resizes the pool using `realloc` to manage memory efficiently and prevent fragmentation.
- **Validation**: Checks that `RX_UE_INFORMATION_TAG` and `RNTI` are within valid ranges, and prevents consecutive structures from having the same `RNTI`.
- **Concurrency**: Uses threads to simulate concurrent operations on the pool.']

