    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicArray;

#define INITIAL_CAPACITY 16

// Error logging mechanism
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) {
        log_error("Memory allocation failed for dynamic array.");
        return NULL;
    }

    da->array = (NFAPI_L1_RXINFO_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_L1_RXINFO_T));
    if (!da->array) {
        free(da);
        log_error("Memory allocation failed for initial capacity.");
        return NULL;
    }

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;

    pthread_mutex_init(&da->mutex, NULL);
    pthread_cond_init(&da->cond, NULL);

    return da;
}

void resize_dynamic_array(DynamicArray* da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_L1_RXINFO_T* new_array = (NFAPI_L1_RXINFO_T*)realloc(da->array, new_capacity * sizeof(NFAPI_L1_RXINFO_T));
    if (!new_array) {
        log_error("Memory allocation failed during resize.");
        return;
    }

    da->array = new_array;
    da->capacity = new_capacity;
}

void add_to_dynamic_array(DynamicArray* da, const NFAPI_L1_RXINFO_T* info) {
    pthread_mutex_lock(&da->mutex);

    if (da->size == da->capacity) {
        resize_dynamic_array(da);
        if (!da->array) {
            pthread_mutex_unlock(&da->mutex);
            return;
        }
    }

    da->array[da->size] = *info;
    da->size++;

    pthread_cond_signal(&da->cond);

    pthread_mutex_unlock(&da->mutex);
}

NFAPI_L1_RXINFO_T* get_from_dynamic_array(DynamicArray* da, size_t index) {
    if (index >= da->size) return NULL;

    pthread_mutex_lock(&da->mutex);

    NFAPI_L1_RXINFO_T* info = &da->array[index];

    pthread_mutex_unlock(&da->mutex);

    return info;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->mutex);
        pthread_cond_destroy(&da->cond);
        free(da);
    }
}
