#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CELLS 64

typedef struct {
    // Add default settings for physical layer configuration
    int some_setting;
} PHYSICAL_LAYER_CONFIGURATION_T;

typedef struct {
    double snr; // Signal-to-Noise Ratio
} CHANNEL_CONTEXT_T;

typedef struct {
    PHYSICAL_LAYER_CONFIGURATION_T *phy_config;
    CHANNEL_CONTEXT_T *chan_context;
} NR_CELL_CONFIG_T;

NR_CELL_CONFIG_T* initialize_cell_configs(int num_cells, int *error_code) {
    if (num_cells > MAX_CELLS) {
        *error_code = -1; // Error: Requested cells exceed maximum limit
        return NULL;
    }

    NR_CELL_CONFIG_T *cell_list = malloc(num_cells * sizeof(NR_CELL_CONFIG_T));
    if (!cell_list) {
        *error_code = -2; // Error: Memory allocation failed for cell list
        return NULL;
    }

    for (int i = 0; i < num_cells; ++i) {
        cell_list[i].phy_config = malloc(sizeof(PHYSICAL_LAYER_CONFIGURATION_T));
        if (!cell_list[i].phy_config) {
            *error_code = -3; // Error: Memory allocation failed for phy config
            goto cleanup;
        }

        // Initialize with default settings
        cell_list[i].phy_config->some_setting = 0;

        cell_list[i].chan_context = malloc(sizeof(CHANNEL_CONTEXT_T));
        if (!cell_list[i].chan_context) {
            *error_code = -4; // Error: Memory allocation failed for chan context
            goto cleanup;
        }

        // Initialize with a randomly generated SNR value
        srand(time(NULL) + i); // Seed based on time and index to ensure variety
        cell_list[i].chan_context->snr = (double)(rand() % 101) / 10.0; // Random SNR between 0.0 and 10.0
    }

    *error_code = 0; // Success
    return cell_list;

cleanup:
    for (int j = 0; j < i; ++j) {
        free(cell_list[j].phy_config);
        free(cell_list[j].chan_context);
    }
    free(cell_list);

    return NULL;
}

void free_cell_configs(NR_CELL_CONFIG_T *cell_list, int num_cells) {
    if (!cell_list) return;

    for (int i = 0; i < num_cells; ++i) {
        free(cell_list[i].phy_config);
        free(cell_list[i].chan_context);
    }
    free(cell_list);
}

// Example usage
int main() {
    int error_code;
    NR_CELL_CONFIG_T *cells = initialize_cell_configs(10, &error_code);

    if (error_code == 0) {
        printf("Successfully initialized cell configurations.\n");
        // Perform operations on cells...

        free_cell_configs(cells, 10);
    } else {
        fprintf(stderr, "Error initializing cell configurations: %d\n", error_code);
    }

    return 0;
}
```

### Key Points:
- **Error Handling**: The function uses an `error_code` to indicate different types of errors that might occur during initialization.
- **Memory Management**: Ensures all allocated memory is freed in case of any allocation failure using a cleanup label for clarity and efficiency.
- **Randomization**: Utilizes `srand()` seeded with the current time plus the index to generate diverse SNR values across calls.
- **Extensibility**: The structure allows easy integration of additional configurations by modifying the existing structures or adding new ones.']

