#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_VERSION 100

typedef struct {
    int phyLayerType;
    int version;
} LTEPHYLayerConfig;

typedef struct {
    LTEPHYLayerConfig *configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTEPHYManager;

LTEPHYManager* initialize_manager() {
    LTEPHYManager *manager = malloc(sizeof(LTEPHYManager));
    if (!manager) return NULL;

    manager->capacity = 10; // Initial capacity
    manager->count = 0;
    manager->configs = malloc(manager->capacity * sizeof(LTEPHYLayerConfig));
    if (!manager->configs) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_configuration(LTEPHYManager *manager, int phyLayerType, int version) {
    pthread_mutex_lock(&manager->lock);

    if (version > MAX_VERSION) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid version
    }

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTEPHYLayerConfig *new_configs = realloc(manager->configs, new_capacity * sizeof(LTEPHYLayerConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    manager->configs[manager->count++] = (LTEPHYLayerConfig){phyLayerType, version};

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void remove_outdated_configurations(LTEPHYManager *manager, int retention) {
    pthread_mutex_lock(&manager->lock);

    size_t valid_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].version >= retention) {
            manager->configs[valid_count++] = manager->configs[i];
        }
    }

    manager->count = valid_count;

    pthread_mutex_unlock(&manager->lock);
}

void iterate_configurations(LTEPHYManager *manager, void (*callback)(LTEPHYLayerConfig *)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        callback(&manager->configs[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void serialize_manager(LTEPHYManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    fwrite(&manager->count, sizeof(manager->count), 1, file);
    fwrite(manager->configs, sizeof(LTEPHYLayerConfig), manager->count, file);

    fclose(file);
    pthread_mutex_unlock(&manager->lock);
}

int deserialize_manager(LTEPHYManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t count;
    fread(&count, sizeof(count), 1, file);

    LTEPHYLayerConfig *new_configs = realloc(manager->configs, count * sizeof(LTEPHYLayerConfig));
    if (!new_configs) {
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    manager->configs = new_configs;
    manager->capacity = count;

    fread(manager->configs, sizeof(LTEPHYLayerConfig), count, file);

    manager->count = count;
    fclose(file);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_manager(LTEPHYManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->configs);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
