        return -1;
    }

    if (list->count >= list->capacity) {
        resize_list(list);
    }

    list->data[list->count++] = *pdu;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Main function to allocate and populate the list
List* create_nfa_list(size_t N) {
    List *list = (List *)malloc(sizeof(List));
    if (!list) {
        LOG_ERROR("Memory allocation failed for list structure");
        return NULL;
    }

    init_list(list, N);

    int retry_count;
    for (size_t i = 0; i < N; ++i) {
        int RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG;

        for (retry_count = 0; retry_count < CACHE_MAX_RETRIES; ++retry_count) {
            if (get_external_data(&RX_UE_INFORMATION_TAG, &RNTI, &CRC_INDICATION_REL8_TAG) == 0) break;
            LOG_ERROR("External API call failed. Retrying... %d/%d", retry_count + 1, CACHE_MAX_RETRIES);
        }

        if (retry_count == CACHE_MAX_RETRIES) {
            LOG_ERROR("Failed to retrieve data from external source after %d attempts.", CACHE_MAX_RETRIES);
            free(list->data);
            pthread_mutex_destroy(&list->mutex);
            free(list);
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG};

        if (add_to_list(list, &pdu) != 0) {
            LOG_ERROR("Failed to add data to list");
            free(list->data);
            pthread_mutex_destroy(&list->mutex);
            free(list);
            return NULL;
        }
    }

    return list;
}

// Usage example
