#define MAX_POLICIES 256

typedef struct {
    int id;
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
} InterfaceConfig;

typedef struct {
    char policy_id[32];
    // Additional policy attributes
} SecurityPolicy;

typedef struct {
    InterfaceConfig config;
    SecurityPolicy* policies;
    size_t num_policies;
} NetworkInterface;

int isValidIPAddress(const char *ip) {
    int parts = 0, num;
    char buf[16];
    const char *s = ip;
    while (*s) {
        if (*s == '.') {
            if (sscanf(buf, "%d", &num) != 1 || num < 0 || num > 255) return 0;
            parts++;
            buf[0] = '\0';
        } else if (*s >= '0' && *s <= '9') {
            strncat(buf, s, 1);
        } else return 0;
        s++;
    }
    if (sscanf(buf, "%d", &num) != 1 || num < 0 || num > 255) return 0;
    return parts == 3;
}

int checkIPOverlap(const InterfaceConfig *config1, const InterfaceConfig *config2) {
    // Simple example to demonstrate overlap checking
    if (strcmp(config1->ip_address, config2->ip_address) == 0 &&
        strcmp(config1->subnet_mask, config2->subnet_mask) == 0) {
        return 1;
    }
    return 0;
}

NetworkInterface* initializeNetworkInterface(int num_configs, InterfaceConfig *configs[], int policy_counts[]) {
    if (num_configs <= 0 || !configs) return NULL;

    NetworkInterface **interfaces = malloc(num_configs * sizeof(NetworkInterface *));
    if (!interfaces) return NULL;

    for (int i = 0; i < num_configs; ++i) {
        if (!isValidIPAddress(configs[i]->ip_address)) {
            // Handle invalid IP
            fprintf(stderr, "Invalid IP address for interface %d\n", configs[i]->id);
            continue;
        }

        interfaces[i] = malloc(sizeof(NetworkInterface));
        if (!interfaces[i]) return NULL;

        memcpy(&interfaces[i]->config, configs[i], sizeof(InterfaceConfig));

        // Check for overlapping IPs
        for (int j = 0; j < i; ++j) {
            if (checkIPOverlap(configs[i], &interfaces[j]->config)) {
                fprintf(stderr, "Overlapping IP detected between interfaces %d and %d\n", configs[i]->id, interfaces[j]->config.id);
                free(interfaces[i]);
                continue;
            }
        }

        interfaces[i]->num_policies = policy_counts[i] > MAX_POLICIES ? MAX_POLICIES : policy_counts[i];
        interfaces[i]->policies = malloc(interfaces[i]->num_policies * sizeof(SecurityPolicy));
        if (!interfaces[i]->policies) {
            free(interfaces[i]);
            return NULL;
        }

        // Initialize policies dynamically (example)
        for (size_t k = 0; k < interfaces[i]->num_policies; ++k) {
            snprintf(interfaces[i]->policies[k].policy_id, sizeof(interfaces[i]->policies[k].policy_id), "Policy_%zu", k);
        }
    }

    return interfaces;
}

void cleanupNetworkInterfaces(NetworkInterface **interfaces, int num_configs) {
    if (!interfaces) return;

    for (int i = 0; i < num_configs; ++i) {
        if (interfaces[i]) {
            free(interfaces[i]->policies);
            free(interfaces[i]);
        }
    }

    free(interfaces);
}
