    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Constants for the valid range of CRCFLAG
#define MIN_CRCFLAG 0x0001 // Example minimum value, adjust as needed
#define MAX_CRCFLAG 0xFFFF // Example maximum value, adjust as needed

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pdu_array(size_t n) {
    if (n > 50000) return NULL; // Enforce the limit of 50,000 entries

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    pthread_t threads[4];
    size_t chunk_size = n / 4; // Assuming a quad-core system for threading

    // Worker function to populate array sections concurrently
    void* worker(void* arg) {
        size_t start_idx = *(size_t*)arg;
        size_t end_idx = (start_idx + chunk_size < n) ? start_idx + chunk_size : n;

        for (size_t i = start_idx; i < end_idx; ++i) {
            pthread_mutex_lock(&mutex); // Ensure thread-safe access

            array[i].RX_UE_INFORMATION_TAG = rand() % 0xFFFF;
            array[i].RNTI = rand() % 0xFFFF;

            uint32_t crcflag = (rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1)) + MIN_CRCFLAG;
            if (crcflag < MIN_CRCFLAG || crcflag > MAX_CRCFLAG) {
                // Handle invalid CRCFLAG, though unlikely due to validation
                continue;
            }
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

            pthread_mutex_unlock(&mutex);
        }

        return NULL;
    }

    // Create threads for concurrent processing
    for (int i = 0; i < 4; ++i) {
        size_t* start_idx = malloc(sizeof(size_t));
        if (!start_idx) {
            perror("Failed to allocate memory");
            free(array);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
        *start_idx = i * chunk_size;
        pthread_create(&threads[i], NULL, worker, (void*)start_idx);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
        free((void*)(size_t)threads[i]); // Free memory allocated for start index
    }

    pthread_mutex_destroy(&mutex); // Clean up mutex

    return array;
}

// Function to free the dynamically allocated array
