#define MAX_BANDWIDTH 100  // Maximum bandwidth setting (example value)
#define MIN_FREQUENCY 800  // Minimum frequency in MHz (example value)
#define MAX_FREQUENCY 2600 // Maximum frequency in MHz (example value)

typedef struct {
    int bandwidth;
    int frequency;
    int antenna_selection;
} LTE_PHY_RX_CONFIG;

typedef struct {
    LTE_PHY_RX_CONFIG *configs;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicConfigList;

// Function to initialize a dynamic list of configurations
DynamicConfigList* init_dynamic_list() {
    DynamicConfigList* list = malloc(sizeof(DynamicConfigList));
    if (!list) return NULL;
    list->configs = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to validate individual configuration
int validate_config(LTE_PHY_RX_CONFIG *config) {
    if (config == NULL)
        return 0;

    if (config->bandwidth <= 0 || config->bandwidth > MAX_BANDWIDTH) {
        loguru::error("Invalid bandwidth: {}", config->bandwidth);
        return 0;
    }

    if (config->frequency < MIN_FREQUENCY || config->frequency > MAX_FREQUENCY) {
        loguru::error("Invalid frequency: {}", config->frequency);
        return 0;
    }

    // Assuming antenna selection is a valid integer (0 or 1 for example)
    if (config->antenna_selection < 0 || config->antenna_selection > 1) {
        loguru::error("Invalid antenna selection: {}", config->antenna_selection);
        return 0;
    }

    return 1;
}

// Function to add a new configuration
int add_config(DynamicConfigList *list, LTE_PHY_RX_CONFIG *config) {
    if (!validate_config(config))
        return -1;

    pthread_mutex_lock(&list->lock);

    list->configs = realloc(list->configs, (list->count + 1) * sizeof(LTE_PHY_RX_CONFIG));
    if (list->configs == NULL) {
        pthread_mutex_unlock(&list->lock);
        loguru::error("Memory allocation failed");
        return -2;
    }

    list->configs[list->count] = *config;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    loguru::info("Configuration added successfully: bandwidth={}, frequency={}, antenna_selection={}",
                 config->bandwidth, config->frequency, config->antenna_selection);
    return 0;
}

// Function to free the dynamic list
void destroy_dynamic_list(DynamicConfigList *list) {
    if (!list)
        return;

    pthread_mutex_lock(&list->lock);

    free(list->configs);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Unit tests for the dynamic list management
void test_dynamic_list() {
    DynamicConfigList *list = init_dynamic_list();

    assert(list != NULL && "Initialization failed");

    LTE_PHY_RX_CONFIG valid_config = {20, 1800, 1};
    int res = add_config(list, &valid_config);
    assert(res == 0 && "Adding valid config failed");

    LTE_PHY_RX_CONFIG invalid_config = {-10, 3000, 2}; // Invalid configuration
    res = add_config(list, &invalid_config);
    assert(res != 0 && "Invalid config was added successfully");

    destroy_dynamic_list(list);

    loguru::info("All tests passed successfully.");
}

int main() {
    loguru::init(argc, argv); // Initialize Loguru
    test_dynamic_list();
    return 0;
}
