        log_error("Measurement report count exceeds maximum allowed.");
        return;
    }

    PriorityQueueNode* priority_queue = NULL;

    for (size_t i = 0; i < n; ++i) {
        int qos_priority = calculate_qos_priority(reports[i].QOS_TAG);
        pthread_mutex_lock(&global_lock);

        PriorityQueueNode* new_node = create_node(&reports[i], qos_priority);
        insert_priority_queue(&priority_queue, new_node);

        pthread_mutex_unlock(&global_lock);
    }

    // Process the priority queue
    while (priority_queue) {
        LTE_RRC_EUTRA_MEASUREMENT_REPORT report = pop_priority_queue(&priority_queue);
        process_measurement_report(report);
    }
}

