void initialize_priority_queue(PriorityQueueNode** head) {
    *head = NULL;
}

PriorityQueueNode* create_node(const LTE_RRC_EUTRA_MEASUREMENT_REPORT* report, int priority) {
    PriorityQueueNode* new_node = malloc_allocation(sizeof(PriorityQueueNode));
    if (!new_node) {
        log_error("Memory allocation failed for priority queue node.");
        return NULL;
    }
    memcpy(&new_node->report, report, sizeof(LTE_RRC_EUTRA_MEASUREMENT_REPORT));
    new_node->priority = priority;
    new_node->next = NULL;
    return new_node;
}

void insert_priority_queue(PriorityQueueNode** head, PriorityQueueNode* node) {
    if (!head || !node) return;

    if (*head == NULL || (*head)->priority < node->priority) {
        node->next = *head;
        *head = node;
    } else {
        PriorityQueueNode* current = *head;
        while (current->next && current->next->priority >= node->priority) {
            current = current->next;
        }
        node->next = current->next;
        current->next = node;
    }
}

LTE_RRC_EUTRA_MEASUREMENT_REPORT pop_priority_queue(PriorityQueueNode** head) {
    if (!head || !*head) return (LTE_RRC_EUTRA_MEASUREMENT_REPORT){0};

    PriorityQueueNode* temp = *head;
    LTE_RRC_EUTRA_MEASUREMENT_REPORT report = temp->report;
    *head = (*head)->next;

    free_allocation(temp);
    return report;
}

