#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535
#define MIN_RNTI 1

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t count;
    pthread_mutex_t lock;
} PDU_List;

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

uint16_t generate_unique_rnti(PDU_List* pdu_list) {
    uint16_t rnti;
    do {
        rnti = (rand() % (MAX_RNTI - MIN_RNTI + 1)) + MIN_RNTI;
    } while (!pthread_mutex_trylock(&pdu_list->lock) && contains_rnti(pdu_list, rnti));

    pthread_mutex_unlock(&pdu_list->lock);
    return rnti;
}

int contains_rnti(PDU_List* pdu_list, uint16_t rnti) {
    for (size_t i = 0; i < pdu_list->count; ++i) {
        if (pdu_list->pdus[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

int create_pdu(PDU_List* pdu_list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    uint16_t rx_tag = rand() % 256; // Example tag generation
    uint8_t crc_tag = rand() % 256; // Example tag generation

    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = generate_unique_rnti(pdu_list);
    pdu->CRC_INDICATION_REL8_TAG = crc_tag;
    pdu->CRCFLAG = rand() & 1; // Random CRC flag (0 or 1)

    return 0;
}

int populate_pdu_list(PDU_List* pdu_list, size_t num_pdus) {
    if (num_pdus == 0) return -1;

    pdu_list->pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list->pdus) return -2;

    pthread_mutex_init(&pdu_list->lock, NULL);
    pdu_list->count = 0;

    for (size_t i = 0; i < num_pdus; ++i) {
        if (create_pdu(pdu_list, &pdu_list->pdus[pdu_list->count])) {
            fprintf(stderr, "Failed to create PDU at index %zu\n", i);
            break;
        }
        pdu_list->count++;
    }

    return 0;
}

void free_pdu_list(PDU_List* pdu_list) {
    if (pdu_list && pdu_list->pdus) {
        free(pdu_list->pdus);
        pthread_mutex_destroy(&pdu_list->lock);
    }
}

int export_pdus_to_text(const PDU_List* pdu_list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return -1;

    for (size_t i = 0; i < pdu_list->count; ++i) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %d\n",
                pdu_list->pdus[i].RX_UE_INFORMATION_TAG,
                pdu_list->pdus[i].RNTI,
                pdu_list->pdus[i].CRC_INDICATION_REL8_TAG,
                pdu_list->pdus[i].CRCFLAG);
    }

    fclose(file);
    return 0;
}

void generate_report(const PDU_List* pdu_list, const char* filename) {
    int exported = export_pdus_to_text(pdu_list, filename);
    if (exported != 0) {
        fprintf(stderr, "Failed to export PDUs to %s\n", filename);
    } else {
        printf("Successfully created and exported %zu structures.\n", pdu_list->count);
    }
}

int main() {
    initialize_random_seed();

    size_t num_pdus = 100; // Example number of PDUs
    PDU_List pdu_list;

    if (populate_pdu_list(&pdu_list, num_pdus) != 0) {
        fprintf(stderr, "Failed to populate PDU list.\n");
        return EXIT_FAILURE;
    }

    generate_report(&pdu_list, "pdus.txt");
    free_pdu_list(&pdu_list);

    return EXIT_SUCCESS;
}
