['Here's a C implementation for managing a dynamic array of `NetworkEvent` structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint64_t timestamp;
    int event_type;
    char *data;
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    uint64_t allocation_successes;
    uint64_t allocation_failures;
} EventManager;

EventManager* create_event_manager(size_t initial_capacity) {
    EventManager *em = malloc(sizeof(EventManager));
    if (!em) return NULL;

    em->events = calloc(initial_capacity, sizeof(NetworkEvent *));
    if (!em->events) {
        free(em);
        return NULL;
    }

    em->capacity = initial_capacity;
    em->count = 0;
    pthread_mutex_init(&em->lock, NULL);
    em->allocation_successes = 0;
    em->allocation_failures = 0;

    return em;
}

int add_event(EventManager *em, NetworkEvent *event) {
    if (!em || !event) return -1;

    pthread_mutex_lock(&em->lock);

    if (em->count == em->capacity) {
        size_t new_capacity = em->capacity * 2;
        NetworkEvent **new_events = realloc(em->events, new_capacity * sizeof(NetworkEvent *));
        if (!new_events) {
            pthread_mutex_unlock(&em->lock);
            em->allocation_failures++;
            return -1;
        }
        em->events = new_events;
        em->capacity = new_capacity;
        em->allocation_successes++;
    }

    em->events[em->count++] = event;

    pthread_mutex_unlock(&em->lock);
    return 0;
}

NetworkEvent* get_event_by_timestamp(EventManager *em, uint64_t timestamp) {
    if (!em) return NULL;

    pthread_mutex_lock(&em->lock);

    for (size_t i = 0; i < em->count; ++i) {
        if (em->events[i]->timestamp == timestamp) {
            NetworkEvent *event = malloc(sizeof(NetworkEvent));
            if (!event) {
                pthread_mutex_unlock(&em->lock);
                return NULL;
            }
            memcpy(event, em->events[i], sizeof(NetworkEvent));
            event->data = strdup(em->events[i]->data);
            pthread_mutex_unlock(&em->lock);
            return event;
        }
    }

    pthread_mutex_unlock(&em->lock);
    return NULL;
}

int update_event(EventManager *em, uint64_t timestamp, int new_event_type, const char *new_data) {
    if (!em || !new_data) return -1;

    pthread_mutex_lock(&em->lock);

    for (size_t i = 0; i < em->count; ++i) {
        if (em->events[i]->timestamp == timestamp) {
            free(em->events[i]->data);
            em->events[i]->event_type = new_event_type;
            em->events[i]->data = strdup(new_data);
            pthread_mutex_unlock(&em->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&em->lock);
    return -1;
}

void free_event_manager(EventManager *em) {
    if (!em) return;

    pthread_mutex_lock(&em->lock);

    for (size_t i = 0; i < em->count; ++i) {
        free(em->events[i]->data);
        free(em->events[i]);
    }
    free(em->events);
    pthread_mutex_unlock(&em->lock);

    pthread_mutex_destroy(&em->lock);
    free(em);
}

void log_allocation_stats(EventManager *em) {
    if (!em) return;

    printf("Allocation Successes: %lu\n", em->allocation_successes);
    printf("Allocation Failures: %lu\n", em->allocation_failures);
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread-safe operations.
- **Memory Management**: Efficiently reallocates memory when capacity is exceeded.
- **Logging**: Tracks allocation successes and failures.
- **Error Handling**: Gracefully handles errors, such as failed allocations.
- **Data Integrity**: Validates inputs and ensures data integrity during updates.']

