// Function prototypes
int addConfig(ConfigList *list, const char *identifier, InterfaceType interfaceType, unsigned int subnetMask, int retryTimeout);
int removeConfig(ConfigList *list, const char *identifier);
NetworkInterfaceConfig* getConfig(const ConfigList *list, const char *identifier);
void resizeConfigList(ConfigList *list);

// Function implementations
int addConfig(ConfigList *list, const char *identifier, InterfaceType interfaceType, unsigned int subnetMask, int retryTimeout) {
    if (retryTimeout < MIN_TIMEOUT || retryTimeout > MAX_RETRIES) return -1;

    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->configs[i].identifier, identifier) == 0)
            goto cleanup;
    }

    if (list->count >= list->capacity) {
        resizeConfigList(list);
    }

    strncpy(list->configs[list->count].identifier, identifier, sizeof(list->configs[0].identifier) - 1);
    list->configs[list->count].interfaceType = interfaceType;
    list->configs[list->count].subnetMask = subnetMask;
    list->configs[list->count].retryTimeout = retryTimeout;
    ++list->count;

cleanup:
    pthread_rwlock_unlock(&list->lock);
    return (list->count > list->capacity) ? -1 : 0;
}

int removeConfig(ConfigList *list, const char *identifier) {
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->configs[i].identifier, identifier) == 0) {
            memmove(&list->configs[i], &list->configs[i + 1], sizeof(NetworkInterfaceConfig) * (list->count - i - 1));
            --list->count;
            break;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

NetworkInterfaceConfig* getConfig(const ConfigList *list, const char *identifier) {
    pthread_rwlock_rdlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->configs[i].identifier, identifier) == 0) {
            NetworkInterfaceConfig* config = &list->configs[i];
            pthread_rwlock_unlock(&list->lock);
            return config;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

void resizeConfigList(ConfigList *list) {
    size_t newCapacity = list->capacity * 2;
    NetworkInterfaceConfig* newConfigs = realloc(list->configs, newCapacity * sizeof(NetworkInterfaceConfig));
    if (newConfigs) {
        list->configs = newConfigs;
        list->capacity = newCapacity;
    }
}

void initConfigList(ConfigList *list) {
    list->configs = malloc(INITIAL_SIZE * sizeof(NetworkInterfaceConfig));
    list->count = 0;
    list->capacity = INITIAL_SIZE;
    pthread_rwlock_init(&list->lock, NULL);
}

void destroyConfigList(ConfigList *list) {
