// Define metadata structure for storage requests
typedef struct {
    unsigned long transaction_id;
    char resource_type[50];
    int status_flag; // 0: pending, 1: in_progress, 2: completed
} StorageRequestMetadata;

// Define NICP device configuration structure
typedef struct {
    StorageRequestMetadata *requests;
    size_t request_count;
    size_t buffer_size;
    pthread_mutex_t lock;
} NICPConfig;

// Function to initialize a NICPConfig with an initial buffer size
void initNICPConfig(NICPConfig *config, size_t initial_buffer_size) {
    config->request_count = 0;
    config->buffer_size = initial_buffer_size;
    config->requests = (StorageRequestMetadata *)malloc(config->buffer_size * sizeof(StorageRequestMetadata));
    if (!config->requests) {
        perror("Failed to allocate memory for NICPConfig");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&config->lock, NULL);
}

// Function to dynamically adjust buffer size based on load
void adjustBufferSize(NICPConfig *config, size_t new_size) {
    pthread_mutex_lock(&config->lock);
    StorageRequestMetadata *new_requests = (StorageRequestMetadata *)realloc(config->requests, new_size * sizeof(StorageRequestMetadata));
    if (!new_requests) {
        perror("Failed to reallocate memory for NICPConfig");
        pthread_mutex_unlock(&config->lock);
        exit(EXIT_FAILURE);
    }
    config->buffer_size = new_size;
    config->requests = new_requests;
    pthread_mutex_unlock(&config->lock);
}

// Function to add a storage request metadata
void addStorageRequest(NICPConfig *config, StorageRequestMetadata request) {
    pthread_mutex_lock(&config->lock);
    if (config->request_count >= config->buffer_size) {
        adjustBufferSize(config, config->buffer_size * 2); // Double the buffer size
    }
    config->requests[config->request_count++] = request;
    pthread_mutex_unlock(&config->lock);
}

// Function to integrate with external monitoring service and adjust configurations
void monitorAndAdjust(NICPConfig *config) {
    // Simulate receiving I/O load and consistency error updates
    size_t io_load = rand() % 100; // Dummy value for demonstration
