    // Adjust buffer based on I/O load (simplified logic)
    if (io_load > 80) {
        adjustBufferSize(config, config->buffer_size + 100); // Increase buffer size
    } else if (io_load < 20 && config->buffer_size > 100) {
        adjustBufferSize(config, config->buffer_size - 50); // Decrease buffer size
    }

    // Log performance metrics and configuration changes
    printf("Current I/O Load: %zu%%, Consistency Errors: %d\n", io_load, consistency_errors);
    printf("Buffer Size Adjusted to: %zu\n", config->buffer_size);

    pthread_mutex_unlock(&config->lock);
}

// Function for logging configurations and performance metrics
