    printf("NICP Configuration Log:\n");
    for (size_t i = 0; i < config->request_count; ++i) {
        printf("Transaction ID: %lu, Resource Type: %s, Status Flag: %d\n",
               config->requests[i].transaction_id,
               config->requests[i].resource_type,
               config->requests[i].status_flag);
    }
    pthread_mutex_unlock(&config->lock);
}

// Function to clean up NICPConfig resources
void freeNICPConfig(NICPConfig *config) {
    pthread_mutex_lock(&config->lock);
    free(config->requests);
    pthread_mutex_unlock(&config->lock);
    pthread_mutex_destroy(&config->lock);
}

int main() {
    NICPConfig config;
    initNICPConfig(&config, 10);

    // Simulate adding storage requests
    for (unsigned long i = 0; i < 50; ++i) {
        StorageRequestMetadata request = { .transaction_id = i, .resource_type = "Storage", .status_flag = 0 };
        addStorageRequest(&config, request);
    }

    // Simulate monitoring and adjusting configurations
    monitorAndAdjust(&config);

    // Log current configuration
    logConfiguration(&config);

    // Clean up resources
    freeNICPConfig(&config);

    return 0;
}
