// Mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_allocation_size(size_t size, const char* filename) {
    FILE *log_file = fopen(filename, "a");
    if (log_file != NULL) {
        fprintf(log_file, "Allocated %zu bytes\n", size);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N, const char *log_filename) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: Number of elements must be positive.\n");
        return NULL;
    }

    size_t allocation_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(allocation_size);

    if (!array) {
        fprintf(stderr, "Memory allocation failed for %zu bytes.\n", allocation_size);

        log_allocation_size(0, log_filename); // Log failure as 0 bytes

        pthread_mutex_unlock(&mutex);
        return NULL; // Return empty pointer on failure
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = rand() % 10000;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    log_allocation_size(allocation_size, log_filename);

    pthread_mutex_unlock(&mutex);

    return array;
}

void cleanup_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array != NULL) {
        free(array);
    }
}
