#include <stdint.h>
#include <pthread.h>
#include <dlfcn.h>
#include <string.h>

#define MAX_ELEMENTS 1000
#define LOG_FILE "allocation_log.txt"
#define LOG_LEVEL_INFO 1

typedef struct {
    // Assume these fields are defined by the external library
} RX_UE_INFORMATION_TAG;

typedef struct {
    // Assume these fields are defined by the external library
} RNTI;

typedef struct {
    // Assume these fields are defined by the external library
} CRC_INDICATION_REL8_TAG;

// Forward declaration of NFAPI_CRC_INDICATION_PDU_T, assuming definition from a dynamic library
typedef struct {
    RX_UE_INFORMATION_TAG ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Global memory pool and mutex for thread safety
#define POOL_SIZE 1024 * 1024 // 1 MB pool size
static uint8_t memory_pool[POOL_SIZE];
static size_t pool_offset = 0;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void* custom_malloc(size_t size);
void log_message(const char* message, int level);

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_array(size_t N) {
    if (N <= 0 || N > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Invalid input. Number of elements must be between 1 and %d.\n", MAX_ELEMENTS);
        return NULL;
    }

    size_t required_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    // Check for integer overflow
    if (required_size / sizeof(NFAPI_CRC_INDICATION_PDU_T) != N) {
        fprintf(stderr, "Error: Integer overflow in memory calculation.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = custom_malloc(required_size);
    if (!array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    log_message("Memory allocated successfully.", LOG_LEVEL_INFO);

    return array;
}

void* custom_malloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);

    if (pool_offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return malloc(size); // Fallback to system allocator
    }

    void* ptr = memory_pool + pool_offset;
    pool_offset += size;

    pthread_mutex_unlock(&pool_mutex);

    memset(ptr, 0, size); // Zero-initialize the allocated block
    return ptr;
}

void log_message(const char* message, int level) {
    if (level <= LOG_LEVEL_INFO) {
        FILE* log_file = fopen(LOG_FILE, "a");
        if (log_file) {
