#define MAX_MEMORY_USAGE 1024 * 1024 // Example threshold in bytes
#define NUM_STRUCTS 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Random value
    time_t timestamp;      // For prioritizing recent structures
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *indicationArray = NULL;
size_t currentMemoryUsage = 0;

void initializeStruct(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 10000; // Random example value
    pdu->RNTI = rand() % 10000;                  // Random example value
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;// Random example value
    pdu->CRCFLAG = rand() & 1;
    pdu->timestamp = time(NULL);
}

void* manageIndications(void *arg) {
    pthread_mutex_lock(&lock);

    // Check memory constraints and initialize structures if within limits
    size_t structSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t requiredMemory = currentMemoryUsage + (NUM_STRUCTS * structSize);

    if (requiredMemory <= MAX_MEMORY_USAGE) {
        indicationArray = realloc(indicationArray, NUM_STRUCTS * structSize);
        if (!indicationArray) {
            fprintf(stderr, "Failed to allocate memory for indications.\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        currentMemoryUsage += (NUM_STRUCTS * structSize);

        // Initialize structures with valid data
        for(size_t i = 0; i < NUM_STRUCTS; ++i) {
            initializeStruct(&indicationArray[i]);
        }

    } else {
        fprintf(stderr, "Memory usage limit exceeded. Offloading less urgent indications.\n");
        // Implement offload logic here if required...
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void resetStruct(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void cleanup() {
    free(indicationArray);
    indicationArray = NULL;
    currentMemoryUsage = 0;
}

int main() {
    pthread_t threadId;

    if (pthread_create(&threadId, NULL, manageIndications, NULL) != 0) {
        fprintf(stderr, "Failed to create thread for managing indications.\n");
        return EXIT_FAILURE;
    }

    // Join the thread
    if (pthread_join(threadId, NULL) != 0) {
        fprintf(stderr, "Thread join failed.\n");
    }

    cleanup();
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
