        cache[index] = malloc(sizeof(struct cache_entry));
        if (cache[index]) {
            memcpy(&cache[index]->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            cache[index]->last_access_time = time(NULL);
        }
    } else {
        memcpy(&cache[index]->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        cache[index]->last_access_time = time(NULL);
    }
