typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
} SortedCRCList;

SortedCRCList* create_list() {
    SortedCRCList* list = malloc(sizeof(SortedCRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(SortedCRCList* list) {
    NFAPI_CRC_INDICATION_PDU_T *current, *next;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_entry(SortedCRCList* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!entry || !list) return;

    time_t now = time(NULL);
    entry->timestamp = now;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;

    while (current && (current->timestamp < entry->timestamp ||
                       (current->timestamp == entry->timestamp && current->RNTI <= entry->RNTI))) {
        prev = current;
        current = current->next;
    }

    if (!prev) {
        entry->next = list->head;
        list->head = entry;
    } else {
        entry->next = current;
        prev->next = entry;
    }

    pthread_mutex_unlock(&list->lock);
}

void purge_outdated_entries(SortedCRCList* list) {
    if (!list) return;

    time_t now = time(NULL);
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current, *next;
    current = list->head;
    while (current) {
        next = current->next;
        if ((now - current->timestamp) > EXPIRATION_THRESHOLD_SECONDS) {
            NFAPI_CRC_INDICATION_PDU_T* to_delete = current;
            if (!list->head || current == list->head)
                list->head = current->next;

            current = next;
            free(to_delete);
        } else {
            current = next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_entry(int RX_UE_INFORMATION_TAG, unsigned long RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) return NULL;

