    // Insert at the head if list is empty or position is found
    if (!head || (pdu_data.timestamp < head->data.timestamp ||
                  (pdu_data.timestamp == head->data.timestamp &&
                   pdu_data.RNTI < head->data.RNTI))) {
        new_node->next = head;
        head = new_node;
    } else {
        Node* current = head;
        while (current->next && 
               ((current->next->data.timestamp < pdu_data.timestamp) ||
                (current->next->data.timestamp == pdu_data.timestamp &&
                 current->next->data.RNTI < pdu_data.RNTI))) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    printf("Inserted node with RX_UE_INFORMATION_TAG: %u, RNTI: %u\n", 
           pdu_data.RX_UE_INFORMATION_TAG, pdu_data.RNTI);

    pthread_mutex_unlock(&lock);
}

// Function to free the entire list
void free_list() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
    pthread_mutex_unlock(&lock);
}

