```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
        uint8_t CRC_INDICATION_REL8_TAG;
    } crc_tag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    size_t count;
} DynamicArray;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to get the current timestamp
time_t current_timestamp() {
    return time(NULL);
}

// Function to generate a random CRCFLAG
int random_crcflag() {
    return rand() % 2; // Randomly set to 0 or 1
}

// Comparator for linked list sorting
int compare_list_nodes(const ListNode *a, const ListNode *b) {
    if (a->data.timestamp < b->data.timestamp)
        return -1;
    if (a->data.timestamp > b->data.timestamp)
        return 1;
    return a->data.RNTI - b->data.RNTI;
}

// Comparator for dynamic array sorting
int compare_array_entries(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *entryA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *entryB = (NFAPI_CRC_INDICATION_PDU_T *)b;

    if (entryA->timestamp < entryB->timestamp)
        return -1;
    if (entryA->timestamp > entryB->timestamp)
        return 1;
    return entryA->RNTI - entryB->RNTI;
}

// Function to add an entry to the linked list
int add_to_linked_list(ListNode **head, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list_lock);

    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

    new_node->data = new_data;
    new_node->next = NULL;

    if (*head == NULL || compare_list_nodes(new_node, *head) < 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        ListNode *current = *head;
        while (current->next && compare_list_nodes(current->next, new_node) <= 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list_lock);
    return 0;
}

// Function to add an entry to the dynamic array
int add_to_dynamic_array(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&array_lock);

    if (array->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&array_lock);
        return -1;
    }

    array->entries[array->count++] = new_data;

    qsort(array->entries, array->count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_array_entries);

    pthread_mutex_unlock(&array_lock);
    return 0;
}

// Function to purge outdated entries
void purge_outdated_entries(ListNode **head, DynamicArray *array, time_t expiration_threshold) {
    pthread_mutex_lock(&list_lock);
    pthread_mutex_lock(&array_lock);

    // Purge linked list
    ListNode *current = *head;
    ListNode *prev = NULL;

    while (current) {
        if (difftime(current->data.timestamp, current_timestamp()) > expiration_threshold) {
            ListNode *to_delete = current;
            current = current->next;
            if (prev)
                prev->next = current;
            else
                *head = current;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    // Purge dynamic array
    size_t new_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (difftime(array->entries[i].timestamp, current_timestamp()) <= expiration_threshold) {
            array->entries[new_count++] = array->entries[i];
        }
    }

    array->count = new_count;

    pthread_mutex_unlock(&list_lock);
    pthread_mutex_unlock(&array_lock);
}

// Function to initialize a NFAPI_CRC_INDICATION_PDU_T with random values
void init_random_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
    pdu->RNTI = rand() % 0xFFFF;
    pdu->crc_tag.CRCFLAG = random_crcflag();
    pdu->crc_tag.CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->timestamp = current_timestamp();
}

// Performance monitoring variables
size_t allocation_count = 0;
size_t deallocation_count = 0;
double total_allocation_time = 0.0;
double total_deallocation_time = 0.0;

void log_performance_metrics() {
    printf("Allocations: %zu, Deallocations: %zu\n", allocation_count, deallocation_count);
    if (deallocation_count > 0)
        printf("Average Allocation Time: %.6f ms, Average Deallocation Time: %.6f ms\n",
               total_allocation_time / deallocation_count * 1000,
               total_deallocation_time / deallocation_count * 1000);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    ListNode *head = NULL;
    DynamicArray array = { .count = 0 };

    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        init_random_pdu(&pdu);

        struct timespec start, end;

        clock_gettime(CLOCK_MONOTONIC, &start);
        if (add_to_linked_list(&head, pdu) == -1)
            fprintf(stderr, "Failed to add to linked list\n");
        clock_gettime(CLOCK_MONOTONIC, &end);
        total_allocation_time += (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        allocation_count++;

        clock_gettime(CLOCK_MONOTONIC, &start);
        if (add_to_dynamic_array(&array, pdu) == -1)
            fprintf(stderr, "Failed to add to dynamic array\n");
        clock_gettime(CLOCK_MONOTONIC, &end);
        total_allocation_time += (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        allocation_count++;
    }

    purge_outdated_entries(&head, &array, 3600); // Purge entries older than 1 hour

    log_performance_metrics();

    // Clean up
    pthread_mutex_destroy(&list_lock);
    pthread_mutex_destroy(&array_lock);

    while (head) {
        ListNode *to_delete = head;
        head = head->next;
        free(to_delete);
        clock_gettime(CLOCK_MONOTONIC, &start);
        deallocation_count++;
        clock_gettime(CLOCK_MONOTONIC, &end);
        total_deallocation_time += (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    }

    return 0;
}
