NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_array(int n, size_t* reallocations) {
    if (n > MAX_STRUCTURES) {
        fprintf(stderr, "Requested number of structures exceeds maximum allowed.\n");
        return NULL;
    }

    *reallocations = 0;
    int increment = INITIAL_INCREMENT;
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    while (1) {
        size_t current_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;

        if (!array) {
            array = malloc(current_size);
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(array, current_size);
            if (!temp_array) {
                increment /= 2; // Reduce the increment on failure
                if (increment < 1) {
                    free(array);
                    fprintf(stderr, "Memory allocation failed after multiple attempts.\n");
                    return NULL;
                }
                continue;
            }
            array = temp_array;
        }

        *reallocations += 1;

        for (int i = 0; i < n; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
            array[i].RNTI = rand() % 65535; // Example value
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
        }

        break;
    }

    return array;
}

void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
