typedef struct {
    uint8_t version;
    uint16_t type;
} PacketHeader;

typedef struct {
    PacketHeader header;
    size_t payloadSize;
    uint32_t checksum;
    void* payloadData; // Assuming payload is a generic block of memory
} DataPacket;

uint32_t computeChecksum(void *data, size_t size) {
    uint8_t *bytes = (uint8_t *)data;
    uint32_t checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum += bytes[i];
    }
    return checksum;
}

DataPacket* initializePackets(size_t numPackets, pthread_mutex_t *mutex, int (*payloadSource)(void **data)) {
    if (numPackets == 0 || mutex == NULL || payloadSource == NULL) {
        return NULL;
    }

    DataPacket* packets = malloc(numPackets * sizeof(DataPacket));
    if (!packets) {
        return NULL;
    }

    for (size_t i = 0; i < numPackets; ++i) {
        pthread_mutex_lock(mutex);

        // Assuming payloadSource fetches payload data and returns a pointer to it
        void* payloadData = NULL;
        size_t payloadSize = payloadSource(&payloadData);

        packets[i].header.version = 1; // Example version
        packets[i].header.type = 2;    // Example type

        packets[i].payloadSize = payloadSize;
        if (payloadData) {
            packets[i].payloadData = malloc(payloadSize);
            memcpy(packets[i].payloadData, payloadData, payloadSize);

            packets[i].checksum = computeChecksum(packets[i].payloadData, payloadSize);

            free(payloadData); // Free the temporary data fetched by payloadSource
        } else {
            packets[i].payloadData = NULL;
            packets[i].checksum = 0; // No payload means checksum is zero
        }

        pthread_mutex_unlock(mutex);
    }

    return packets;
}

void deallocatePackets(DataPacket* packets, size_t numPackets) {
    if (!packets) return;

    for (size_t i = 0; i < numPackets; ++i) {
        if (packets[i].payloadData) {
            free(packets[i].payloadData);
        }
    }

    free(packets);
}

