['Below is a C implementation that addresses your requirements for managing a pool of `NFAPI_CRC_INDICATION_PDU_T` structures. The solution includes dynamic memory management with thread safety, custom allocation strategies, and support for structure versions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <pthread.h>

#define MAX_POOL_SIZE 10000

typedef struct {
    int version;
    // Add other fields based on the version
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int capacity;
    unsigned int size;
    unsigned short rnti_counter; // To ensure unique RNTI
} PduPool;

PduPool* initialize_pool(unsigned int initial_capacity) {
    if (initial_capacity > MAX_POOL_SIZE) return NULL;

    PduPool* pool = (PduPool*)malloc(sizeof(PduPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->head = NULL;
    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->rnti_counter = 1; // Start from 1 to avoid zero

    return pool;
}

void free_pool(PduPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    Node* current = pool->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_pdu(PduPool* pool, unsigned int version) {
    if (!pool || pool->size >= pool->capacity) return -1;

    pthread_mutex_lock(&pool->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    new_node->pdu.version = version;
    new_node->pdu.RX_UE_INFORMATION_TAG = rand(); // Simulate setting this
    new_node->pdu.RNTI = pool->rnti_counter++;
    new_node->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    new_node->next = pool->head;
    pool->head = new_node;
    pool->size++;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int remove_pdu(PduPool* pool) {
    if (!pool || pool->size == 0) return -1;

    pthread_mutex_lock(&pool->lock);

    Node* to_remove = pool->head;
    if (to_remove) {
        pool->head = to_remove->next;
        free(to_remove);
        pool->size--;
    }

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void iterate_pdu_pool(PduPool* pool, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!pool || !callback) return;

    pthread_mutex_lock(&pool->lock);

    Node* current = pool->head;
    while (current) {
        callback(&(current->pdu));
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

void reset_pdu_pool(PduPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    Node* current = pool->head;
    while (current) {
        memset(&(current->pdu), 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        current->pdu.RNTI = ++(pool->rnti_counter); // Reset RNTI to maintain uniqueness
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

// Example usage of iteration callback
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        printf("Version: %u, RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRCFLAG: %d\n",
            pdu->version,
            pdu->RX_UE_INFORMATION_TAG,
            pdu->RNTI,
            pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

int main() {
    PduPool* pool = initialize_pool(1000);

    if (!pool) {
        fprintf(stderr, "Failed to initialize PDU pool.\n");
        return 1;
    }

    add_pdu(pool, 1); // Add a new PDU
    iterate_pdu_pool(pool, print_pdu);
    remove_pdu(pool);

    reset_pdu_pool(pool); // Reset all PDUs

    free_pool(pool);

    return 0;
}
```

### Key Points:

- **Thread Safety**: The code uses `pthread_mutex_t` to ensure thread-safe operations on the pool.
- **Dynamic Memory Management**: Implements a linked list for dynamic memory allocation, allowing efficient additions and removals.
- **Unique RNTI Management**: Uses an incrementing counter to ensure unique RNTI values within the pool.
- **Reset Mechanism**: Provides a function to reset all PDUs to their initial state.
- **Iteration with Callback**: Allows iteration over the pool using a callback function, enhancing flexibility.
- **Error Handling**: Includes checks for allocation failures and capacity limits.']

