    for (size_t i = 0; i < n; ++i) {
        (*pdu_list)->data[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*pdu_list)->data[i].RNTI = rand() % 10000;
        (*pdu_list)->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    }

    pthread_mutex_unlock(&(*pdu_list)->lock);
    return 0;
}

int validate_pdu_list(PduList *pdu_list) {
    if (!pdu_list || !pdu_list->data) return -1;

    pthread_mutex_lock(&pdu_list->lock);

