        if (pdu_list->data[i].RX_UE_INFORMATION_TAG <= 0 || pdu_list->data[i].RNTI <= 0) {
            pthread_mutex_unlock(&pdu_list->lock);
            return -2;
        }
    }

    pthread_mutex_unlock(&pdu_list->lock);
    return 0;
}

void free_pdu_list(PduList *pdu_list) {
    if (pdu_list) {
        pthread_mutex_destroy(&pdu_list->lock);
        free(pdu_list->data);
        free(pdu_list);
    }
}

int process_pdu_list(PduList **pdu_list, size_t n) {
    int status = allocate_pdu_list(pdu_list, n);
    if (status != 0) {
        fprintf(stderr, "Error allocating PDU list: %d\n", status);
        return -1;
    }

    status = validate_pdu_list(*pdu_list);
    if (status != 0) {
        fprintf(stderr, "Validation failed for PDU list: %d\n", status);
        free_pdu_list(*pdu_list);
        *pdu_list = NULL;
        return -2;
    }

