    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_pdu(PduManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(manager->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_pdus) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }

        manager->pdus = new_pdus;
        manager->capacity = new_capacity;
    }

    manager->pdus[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void free_pdu_manager(PduManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->pdus);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
}

void* pdu_worker(void *arg) {
    PduManager *manager = (PduManager*) arg;

    // Simulate work with PDUs
    for (size_t i = 0; i < manager->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[i];

        // Randomly set CRCFLAG for demonstration
        pdu->CRCFLAG = rand() % 256;

        // Process the PDU (e.g., log, send to another system)
        printf("Processing PDU with RNTI: %d\n", pdu->RNTI);
    }

    return NULL;
}

void process_pdus(PduManager *manager) {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, pdu_worker, manager)) {
        fprintf(stderr, "Error creating thread\n");
        return;
    }

    pthread_join(thread_id, NULL);
}

// Example usage
int main() {
    PduManager *manager = create_pdu_manager(10);

    // Simulate adding PDUs in a multithreaded environment
    for (int i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = i + 100, .CRCFLAG = 0 };
        if (add_pdu(manager, pdu)) {
            fprintf(stderr, "Failed to add PDU\n");
        }
    }

    process_pdus(manager);

    free_pdu_manager(manager);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` ensures that concurrent access to the shared data structure is handled safely.
- **Dynamic Configuration and Memory Management**: The list can grow dynamically as needed, with memory reallocation managed efficiently.
- **Randomized CRCFLAG**: For demonstration purposes, a random value is assigned to `CRCFLAG`.
- **Scalability**: The solution can handle increasing numbers of PDUs by reallocating memory when capacity is reached.
- **Error Handling**: Memory allocation and thread creation errors are checked and handled appropriately.']

