}

int allocate_pdus(PDU_Manager *manager, size_t num_pdus) {
    pthread_mutex_lock(&manager->mutex);

    if (num_pdus < 1 || num_pdus > MAX_PDUS) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Invalid number of PDUs
    }

    manager->pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
