               manager->pdus[i].RX_UE_INFORMATION_TAG,
               manager->pdus[i].RNTI,
               manager->pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    pthread_mutex_unlock(&manager->mutex);
}

int main() {
