void log_error(const char* message, FILE* log_file) {
    pthread_mutex_lock(&lock);
    fprintf(log_file, "Error: %s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&lock);
}

int simulate_signal_strength(int mean, float stddev) {
    static const double inv_sqrt_2pi = 0.3989422804014327;
    int random_value;

    // Using Box-Muller transform to generate Gaussian distribution
    do {
        double u1 = (double)rand() / RAND_MAX;
        double u2 = (double)rand() / RAND_MAX;

        double z0 = sqrt(-2.0 * log(u1)) * cos(2 * M_PI * u2);
        random_value = (int)(mean + stddev * z0);
    } while(random_value < 0);

    return random_value;
}

void generate_noise(float complex *array, size_t length) {
    for(size_t i = 0; i < length; ++i) {
        double real_part = ((double)rand() / RAND_MAX) * 2 - 1;
        double imag_part = ((double)rand() / RAND_MAX) * 2 - 1;
        array[i] = real_part + imag_part * I;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_array(size_t N, int mean_strength, float stddev, FILE* log_file) {
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T", log_file);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        array[i].RNTI = rand() % 65535;

        int signal_strength = simulate_signal_strength(mean_strength, stddev);
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (signal_strength > 50) ? 1 : 0; // Example condition
    }

    return array;
}

LTE_PHY_TEST_FRAME_T* create_lte_test_frames(size_t frame_count, size_t sample_count) {
    LTE_PHY_TEST_FRAME_T* frames = malloc(frame_count * sizeof(LTE_PHY_TEST_FRAME_T));
    if (!frames) {
        log_error("Memory allocation failed for LTE_PHY_TEST_FRAME_T", stderr);
        return NULL;
    }

    for (size_t i = 0; i < frame_count; ++i) {
        frames[i].OFDM_SYMBOL_INDEX = rand() % 1024;

        frames[i].TX_SAMPLE = malloc(sample_count * sizeof(float complex));
        if (!frames[i].TX_SAMPLE) {
            log_error("Memory allocation failed for TX_SAMPLE", stderr);
            return NULL;
        }

        frames[i].RX_SAMPLE = malloc(sample_count * sizeof(float complex));
