#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NOTIFICATIONS 1000
#define RETENTION_PERIOD_SECONDS 3600

typedef struct {
    int rnti;
    char ue_information_tag[64];
    int crc_flag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int ue_id;
    time_t timestamp;
    char *cell_ids; // Comma-separated cell IDs
} NetworkEventNotification;

typedef struct NotificationNode {
    NetworkEventNotification data;
    struct NotificationNode* next;
} NotificationNode;

typedef struct {
    NotificationNode* head;
    pthread_mutex_t lock;
} NotificationList;

// Global notification list
NotificationList notifications = {NULL, PTHREAD_MUTEX_INITIALIZER};

void initialize_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->rnti = rand() % 10000; // Random RNTI
    snprintf(pdu->ue_information_tag, sizeof(pdu->ue_information_tag), "UE%d", pdu->rnti);
    pdu->crc_indication.crc_flag = rand() % 2; // Random CRC flag (0 or 1)
}

void add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int count) {
    for(int i = 0; i < count; ++i) {
        initialize_crc_pdu(&pdu_array[i]);
    }
}

NetworkEventNotification create_notification(int ue_id, char* cell_ids) {
    NetworkEventNotification notification;
    notification.ue_id = ue_id;
    notification.timestamp = time(NULL);
    notification.cell_ids = strdup(cell_ids); // Copy cell IDs
    return notification;
}

void add_network_event(NetworkEventNotification notification) {
    pthread_mutex_lock(&notifications.lock);

    NotificationNode* new_node = malloc(sizeof(NotificationNode));
    if (!new_node) {
        perror("Failed to allocate memory for notification node");
        exit(EXIT_FAILURE);
    }
    new_node->data = notification;
    new_node->next = notifications.head;
    notifications.head = new_node;

    pthread_mutex_unlock(&notifications.lock);
}

void remove_outdated_notifications() {
    pthread_mutex_lock(&notifications.lock);

    time_t current_time = time(NULL);
    NotificationNode* prev = NULL;
    NotificationNode* node = notifications.head;

    while (node) {
        if ((current_time - node->data.timestamp) > RETENTION_PERIOD_SECONDS) {
            NotificationNode* to_delete = node;
            node = node->next;

            if (prev) {
                prev->next = node;
            } else {
                notifications.head = node;
            }

            free(to_delete->data.cell_ids);
            free(to_delete);
        } else {
            prev = node;
            node = node->next;
        }
    }

    pthread_mutex_unlock(&notifications.lock);
}

NetworkEventNotification* retrieve_notifications_for_ue(int ue_id, time_t start_time, time_t end_time) {
    NotificationNode* node = notifications.head;
    int count = 0;

    while (node) {
        if (node->data.ue_id == ue_id && node->data.timestamp >= start_time && node->data.timestamp <= end_time) {
            count++;
        }
        node = node->next;
    }

    NetworkEventNotification* results = malloc(count * sizeof(NetworkEventNotification));
    if (!results) {
        perror("Failed to allocate memory for notification results");
        exit(EXIT_FAILURE);
    }

    int index = 0;
    node = notifications.head;

    while (node) {
        if (node->data.ue_id == ue_id && node->data.timestamp >= start_time && node->data.timestamp <= end_time) {
            results[index++] = node->data;
        }
        node = node->next;
    }

    return results; // Caller is responsible for freeing this memory
}

void handle_external_service_request() {
    // Placeholder function to simulate external service requests with retries
    int retry_count = 0;
    while (retry_count < 3) {
        if (simulate_external_service_call()) {
            break; // Success
        }
        retry_count++;
        sleep(1); // Wait before retrying
    }

    if (retry_count == 3) {
        fprintf(stderr, "Failed to retrieve data from external service after retries\n");
    }
}

int simulate_external_service_call() {
    return rand() % 2; // Randomly succeed or fail for simulation purposes
}

void log_event(const char* message) {
    printf("LOG: %s\n", message); // Simple logging mechanism, replace with a more robust one if needed
}

// Example usage function
void example_usage() {
    NFAPI_CRC_INDICATION_PDU_T pdu_array[10];
    add_crc_pdu(pdu_array, 10);

    NetworkEventNotification notification = create_notification(12345, "Cell1,Cell2");
    add_network_event(notification);

    remove_outdated_notifications();

    time_t now = time(NULL);
    NetworkEventNotification* results = retrieve_notifications_for_ue(12345, now - 3600, now);
    if (results) {
        for (int i = 0; results[i].ue_id != 0; ++i) { // Assuming ue_id of 0 indicates end
            printf("UE ID: %d, Timestamp: %ld\n", results[i].ue_id, results[i].timestamp);
        }
        free(results);
    }

    handle_external_service_request();
}

int main() {
    srand(time(NULL)); // Seed random number generator
    example_usage();

    return 0;
}
