```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Assume these types are defined elsewhere
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes for external dependencies
unsigned int get_unique_rx_ue_information_tag(void);
void queue_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu);

#define MAX_THREADS 4

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    size_t start;
    size_t end;
} ThreadData;

void* generate_pdus_thread(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    size_t start = data->start;
    size_t end = data->end;
    unsigned int count = 0;

    for (size_t i = start; i < end; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Failed to allocate memory for PDU");
            continue;
        }

        pthread_mutex_lock(&lock);
        pdu->RX_UE_INFORMATION_TAG = get_unique_rx_ue_information_tag();
        pdu->RNTI = rand(); // Placeholder, replace with actual RNTI generation logic
        pthread_mutex_unlock(&lock);

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

        if (queue_pdu(pdu) != 0) {
            perror("Failed to queue PDU");
            free(pdu);
        } else {
            count++;
        }
    }

    printf("Thread completed processing %u PDUs\n", count);

    return NULL;
}

void generate_and_queue_pdus(size_t N, size_t MAX_PDUS) {
    if (N == 0 || MAX_PDUS == 0) return;

    pthread_t threads[MAX_THREADS];
    ThreadData thread_data[MAX_THREADS];

    size_t pdus_per_thread = N / MAX_THREADS;
    size_t remainder = N % MAX_THREADS;

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        thread_data[i].start = i * pdus_per_thread;
        thread_data[i].end = (i == MAX_THREADS - 1) ? 
                             (thread_data[i].start + pdus_per_thread + remainder) : 
                             (thread_data[i].start + pdus_per_thread);

        if (pthread_create(&threads[i], NULL, generate_pdus_thread, &thread_data[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    size_t N = 1000;   // Total PDUs to generate
    size_t MAX_PDUS = 100;

    generate_and_queue_pdus(N, MAX_PDUS);

    return 0;
}
```

