#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG; // Assuming CRCFLAG is a single byte
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function prototypes (assuming an external logging system)
void log_sync(const char *message);
void log_async(const char *message);

// Function to generate a pseudo-random number for RNTI and CRCFLAG
uint32_t generate_random_rnti(uint32_t last_rnti) {
    srand(time(NULL));
    uint32_t rnti;
    do {
        rnti = rand() % (1 << 16); // Example range for demonstration
    } while (rnti == last_rnti);
    return rnti;
}

uint8_t generate_random_crcflag(uint8_t last_crcflag) {
    srand(time(NULL));
    uint8_t crcflag;
    do {
        crcflag = rand() % 256; // Example range for demonstration
    } while (crcflag == last_crcflag);
    return crcflag;
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pdu_list(size_t num_elements, size_t *successful_allocations) {
    if (num_elements > MAX_ELEMENTS) {
        log_sync("Requested number of elements exceeds the maximum limit.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_sync("Memory allocation failed for the entire list.");
        return NULL;
    }

    size_t total_attempts = 0;
    size_t successful_count = 0;
    uint32_t last_rnti = 0;
    uint8_t last_crcflag = 0;

    for (size_t i = 0; i < num_elements; ++i) {
        if (total_attempts >= MAX_ELEMENTS) {
            log_sync("Exceeded maximum allocation attempts.");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *current = &list[i];

        current->RX_UE_INFORMATION_TAG = rand() % 256; // Example value
        pthread_mutex_lock(&lock);
        total_attempts++;
        while (true) {
            uint32_t rnti_candidate = generate_random_rnti(last_rnti);
            if (rnti_candidate != last_rnti) {
                current->RNTI = rnti_candidate;
                break;
            }
            if (++total_attempts >= MAX_ELEMENTS) {
                log_sync("Failed to allocate unique RNTI.");
                pthread_mutex_unlock(&lock);
                goto cleanup_failure;
            }
        }

        while (true) {
            uint8_t crcflag_candidate = generate_random_crcflag(last_crcflag);
            if (crcflag_candidate != last_crcflag) {
                current->CRCFLAG = crcflag_candidate;
                break;
            }
            if (++total_attempts >= MAX_ELEMENTS) {
                log_sync("Failed to allocate unique CRCFLAG.");
                pthread_mutex_unlock(&lock);
                goto cleanup_failure;
            }
        }

        successful_count++;
        last_rnti = current->RNTI;
        last_crcflag = current->CRCFLAG;

        pthread_mutex_unlock(&lock);
    }

cleanup_failure:
    if (successful_count == 0) {
        free(list);
        log_sync("All allocations failed.");
        list = NULL;
    } else {
        *successful_allocations = successful_count;
        log_async("Completed with %zu successful allocations out of %zu attempts.", successful_count, total_attempts);
    }

    pthread_mutex_destroy(&lock);

    return list;
}

void free_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) {
        free(list);
    }
}
```

