['Below is a C implementation for managing a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures in a high-throughput, multi-threaded environment using lock-free techniques with atomic operations:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

// Define structure for CRC indication PDU
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the lock-free linked list
struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    atomic_intptr_t next;
};

typedef struct {
    atomic_intptr_t head;
    atomic_intptr_t tail;
} LockFreeList;

LockFreeList* create_lock_free_list() {
    LockFreeList *list = malloc(sizeof(LockFreeList));
    if (!list) return NULL;

    NFAPI_CRC_INDICATION_PDU_T dummy_data = {0};
    struct node* dummy_node = malloc(sizeof(struct node));
    if (!dummy_node) {
        free(list);
        return NULL;
    }

    dummy_node->data = dummy_data;
    atomic_store(&dummy_node->next, 0);

    atomic_store(&list->head, (intptr_t)dummy_node);
    atomic_store(&list->tail, (intptr_t)dummy_node);

    return list;
}

int lock_free_push(LockFreeList *list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) return -1;

    new_node->data = data;

    while (1) {
        struct node* tail = (struct node*)atomic_load(&list->tail);
        struct node* next = (struct node*)atomic_load(&tail->next);

        if (tail == atomic_load(&list->tail)) { // Tail is still valid
            if (next == NULL) { // List not full, try to append new_node
                if (atomic_compare_exchange_weak(
                        &tail->next,
                        (intptr_t *)&next,
                        (intptr_t)new_node))
                    break;
            } else { // Try advancing the tail
                atomic_compare_exchange_weak(&list->tail, 
                                             (intptr_t *)&tail,
                                             (intptr_t)next);
            }
        }
    }

    atomic_compare_exchange_weak(&list->tail, (intptr_t *)&tail, (intptr_t)new_node);

    return 0;
}

int lock_free_pop(LockFreeList *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    while (1) {
        struct node* head = (struct node*)atomic_load(&list->head);
        struct node* tail = (struct node*)atomic_load(&list->tail);
        struct node* next = (struct node*)atomic_load(&head->next);

        if (head == atomic_load(&list->head)) { // Head is still valid
            if (head == tail) {
                if (next == NULL) return -1; // List is empty
                atomic_compare_exchange_weak(&list->tail, 
                                             (intptr_t *)&tail,
                                             (intptr_t)next);
            } else {
                *data = next->data;
                if (atomic_compare_exchange_weak(
                        &list->head,
                        (intptr_t *)&head,
                        (intptr_t)next))
                    break;
            }
        }
    }

    free(head);
    return 0;
}

void destroy_lock_free_list(LockFreeList *list) {
    NFAPI_CRC_INDICATION_PDU_T dummy_data;
    while (lock_free_pop(list, &dummy_data) == 0);

    struct node* head = (struct node*)atomic_load(&list->head);
    free(head);
    free(list);
}

// Example of usage
int main() {
    LockFreeList *list = create_lock_free_list();
    if (!list) return -1;

    // Populate list with random data
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 65536;
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        if (lock_free_push(list, pdu) != 0) {
            fprintf(stderr, "Failed to push data\n");
            destroy_lock_free_list(list);
            return -1;
        }
    }

    // Consume the list
    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (lock_free_pop(list, &pdu) == 0);

    // Clean up
    destroy_lock_free_list(list);

    return 0;
}
```

### Key Points:
- **Lock-Free Linked List**: Uses atomic operations for thread-safe push and pop operations.
- **Memory Management**: Allocates nodes dynamically; ensures cleanup to avoid memory leaks.
- **Error Handling**: Checks for allocation failures and handles them gracefully.
- **Concurrency**: Designed for concurrent access, minimizing the need for locks.']

