                printf("Successfully created connection setup request at index %d.\n", i);
            }
        } else {
            fprintf(stderr, "Failed to fetch configuration for request at index %d.\n", i);
            free(requests[i]);
            requests[i] = NULL;
        }
    }

    if (enable_logging) {
        printf("Total successful connection setup requests: %d\n", success_count);
    }

    // Returning a struct containing the array and count of successful creations
    typedef struct {
        LTE_ECM_CONNECTION_SETUP_REQUEST_T **requests;
        int success_count;
    } Result;

    Result *result = malloc(sizeof(Result));
    if (!result) {
        fprintf(stderr, "Memory allocation failed for result structure.\n");
        // Free partially allocated resources in case of failure
        for (int i = 0; i < N; ++i) {
            if (requests[i]) {
                free(requests[i]);
            }
        }
        free(requests);
        return NULL;
    }

    result->requests = requests;
    result->success_count = success_count;

    return result;
}

// Example usage
