    int N = 10;
    bool enable_logging = true;

    void *result = initialize_connection_requests(N, enable_logging);

    if (result) {
        // Clean up resources
        Result *res = (Result *)result;
        for (int i = 0; i < N; ++i) {
            if (res->requests[i]) {
                free(res->requests[i]);
            }
        }
        free(res->requests);
        free(res);
    }

    return 0;
}
