    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} Message;

// Define a node for linked list
typedef struct MessageNode {
    Message message;
    struct MessageNode *next;
} MessageNode;

// Define the message collection structure with a mutex for concurrency control
typedef struct {
    MessageNode *head;
    pthread_mutex_t lock;
} MessageCollection;

// Function prototypes
MessageCollection* create_collection();
void destroy_collection(MessageCollection *collection);
int add_message(MessageCollection *collection, Message message);
int update_message(MessageCollection *collection, int message_id, Message updated_message);
Message* get_message(MessageCollection *collection, int message_id);
void iterate_messages(MessageCollection *collection);

// Create a new message collection
MessageCollection* create_collection() {
    MessageCollection *collection = malloc(sizeof(MessageCollection));
    if (!collection) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Destroy the message collection
void destroy_collection(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    MessageNode *current = collection->head;
    while (current) {
        MessageNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Add a new message to the collection
int add_message(MessageCollection *collection, Message message) {
    pthread_mutex_lock(&collection->lock);

    // Check for duplicate ID or invalid timestamp
    if (message.timestamp == 0 || get_message(collection, message.message_id)) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Error code for duplicate ID or invalid timestamp
    }

    MessageNode *new_node = malloc(sizeof(MessageNode));
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Error code for memory allocation failure
    }
    new_node->message = message;
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

// Update an existing message by ID
int update_message(MessageCollection *collection, int message_id, Message updated_message) {
    pthread_mutex_lock(&collection->lock);

    MessageNode *current = collection->head;
    while (current) {
        if (current->message.message_id == message_id) {
            current->message = updated_message;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Error code for not found
}

// Retrieve a message by ID
Message* get_message(MessageCollection *collection, int message_id) {
    pthread_mutex_lock(&collection->lock);

    MessageNode *current = collection->head;
    while (current) {
        if (current->message.message_id == message_id) {
            pthread_mutex_unlock(&collection->lock);
            return &current->message; // Return a pointer to the message
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Not found
}

// Iterate over all messages in chronological order
void iterate_messages(MessageCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    MessageNode *current = collection->head;
    while (current) {
        printf("Message ID: %d, Priority: %d\n", current->message.message_id, current->message.priority_level);
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

// Helper function to generate a random CRCFLAG
void set_random_crcflag(CRC_INDICATION_REL8_TAG *crc_tag) {
    crc_tag->CRCFLAG = rand() % 2; // Randomly set to 0 or 1
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    MessageCollection *collection = create_collection();
    if (!collection) return -1;

    // Example usage
    CRC_INDICATION_REL8_TAG crc_tag;
    set_random_crcflag(&crc_tag);

    RX_UE_INFORMATION_TAG rx_ue_info_tag = { .RNTI = 12345 };
