        .rx_ue_info_tag = rx_ue_info_tag,
        .rnti = { .RNTI = 12345 },
        .crc_indication_rel8_tag = crc_tag
    };

    add_message(collection, message);
    iterate_messages(collection);

    destroy_collection(collection);
    return 0;
}
