#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_MESSAGE_ID 10000

typedef struct {
    uint32_t rnti;
    // Other fields as needed
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t rnti_length;
    // Other fields as needed
} RNTI;

typedef struct {
    uint8_t crcflag; // Randomly set CRCFLAG
    // Other fields as needed
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
    // Additional fields as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Message {
    uint64_t timestamp;
    uint32_t message_id;
    int priority_level;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Message* next;
} Message;

typedef struct {
    pthread_mutex_t lock;
    Message* head;
    size_t count;
} MessageCollection;

// Function prototypes
void initialize_collection(MessageCollection* collection);
int add_message(MessageCollection* collection, uint64_t timestamp, uint32_t message_id, int priority_level);
Message* get_message_by_id(const MessageCollection* collection, uint32_t message_id);
int update_message(MessageCollection* collection, uint32_t message_id, NFAPI_CRC_INDICATION_PDU_T new_pdu);
void cleanup_inactive_messages(MessageCollection* collection, int expiration_time_ms);

// Initialize the message collection
void initialize_collection(MessageCollection* collection) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->head = NULL;
    collection->count = 0;
}

// Add a new message to the collection
int add_message(MessageCollection* collection, uint64_t timestamp, uint32_t message_id, int priority_level) {
    pthread_mutex_lock(&collection->lock);

    // Check for duplicate IDs or invalid timestamps
    if (timestamp == 0 || message_id >= MAX_MESSAGE_ID) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Error code for invalid input
    }

    // Create new message node
    Message* new_message = malloc(sizeof(Message));
    if (!new_message) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Error code for allocation failure
    }

    new_message->timestamp = timestamp;
    new_message->message_id = message_id;
    new_message->priority_level = priority_level;

    // Populate NFAPI_CRC_INDICATION_PDU_T with random CRCFLAG
    new_message->pdu.crc_rel8_tag.crcflag = rand() % 2; // Randomly set to 0 or 1

    // Add the message to the collection in chronological order
    Message** current = &collection->head;
    while (*current && (*current)->timestamp <= timestamp) {
        current = &(*current)->next;
    }
    new_message->next = *current;
    *current = new_message;

    pthread_mutex_unlock(&collection->lock);
    collection->count++;
    return 0; // Success
}

// Retrieve a message by its ID
Message* get_message_by_id(const MessageCollection* collection, uint32_t message_id) {
    pthread_mutex_lock((pthread_mutex_t*)&collection->lock);

    for (Message* current = collection->head; current != NULL; current = current->next) {
        if (current->message_id == message_id) {
            pthread_mutex_unlock((pthread_mutex_t*)&collection->lock);
            return current;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t*)&collection->lock);
    return NULL; // Not found
}

// Update an existing message by ID
int update_message(MessageCollection* collection, uint32_t message_id, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&collection->lock);

    for (Message* current = collection->head; current != NULL; current = current->next) {
        if (current->message_id == message_id) {
            // Update the PDU structure
            current->pdu = new_pdu;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Message not found
}

// Cleanup inactive messages based on expiration policy
void cleanup_inactive_messages(MessageCollection* collection, int expiration_time_ms) {
    pthread_mutex_lock(&collection->lock);

    uint64_t current_time = time(NULL) * 1000; // Current time in milliseconds

    Message** current = &collection->head;
    while (*current) {
        if (current_time - (*current)->timestamp > expiration_time_ms) {
            Message* to_delete = *current;
            *current = (*current)->next;
            free(to_delete);
            collection->count--;
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Main function for demonstration purposes
int main() {
    MessageCollection collection;
    initialize_collection(&collection);

    // Example usage
    add_message(&collection, time(NULL) * 1000, 1, 5); // Add a message with current timestamp
    Message* msg = get_message_by_id(&collection, 1);   // Retrieve the message by ID
    if (msg) {
        printf("Message retrieved: ID %u\n", msg->message_id);
    }

    cleanup_inactive_messages(&collection, 3600000); // Cleanup messages older than 1 hour

    // Further operations...

    return 0;
}
```

### Key Points:
- **Concurrency**: Uses a mutex to ensure thread-safe operations.
- **Data Structure**: A linked list is used for efficient insertion in chronological order.
- **Error Handling**: Returns error codes for invalid inputs or allocation failures.
- **Cleanup**: Periodically removes inactive messages based on expiration time.
- **Random CRCFLAG**: Sets the `crcflag` randomly when adding a message.

This code provides a basic framework and can be extended with additional features like logging, distributed task handling, and dynamic memory adjustments as described in your requirements.']

