#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000000
#define RETRY_INTERVAL 100 // milliseconds
#define MAX_RETRY_COUNT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t crcflag_set_count;
} CRC_List;

CRC_List* create_list() {
    CRC_List* list = (CRC_List*)malloc(sizeof(CRC_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->crcflag_set_count = 0;
    return list;
}

void free_list(CRC_List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu, double probability) {
    return ((double)rand() / RAND_MAX < probability) ? 1 : 0;
}

void append_structure(CRC_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    if (pdu.CRCFLAG) {
        list->crcflag_set_count++;
    }
    pthread_mutex_unlock(&list->lock);
}

void process_pdu(CRC_List* list, double probability, int retries) {
    int RX_UE_TAG, RNTI;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        for (int attempt = 0; attempt <= retries; ++attempt) {
            if (retrieve_RX_UE_INFORMATION_TAG(&RX_UE_TAG) && retrieve_RNTI(&RNTI)) {
                NFAPI_CRC_INDICATION_PDU_T pdu = { RX_UE_TAG, RNTI, 0 };
                pdu.CRCFLAG = set_crcflag(&pdu, probability);

                append_structure(list, pdu);
                log_operation(pdu); // Assuming a logging function

                break;
            } else {
                if (attempt < retries) {
                    usleep(RETRY_INTERVAL * 1000);
                }
            }
        }
    }
}

void cleanup_unused_structures(CRC_List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && list->count > MAX_STRUCTURES / 2) {
        Node* to_delete = current;
        current = current->next;

        // Assuming some condition for "unused" structures
        if (!is_structure_used(to_delete->data)) {
            list->head = current;
            free(to_delete);
            list->count--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL));  // Seed the random number generator

    CRC_List* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    process_pdu(list, 0.1, MAX_RETRY_COUNT);  // Example probability and retries
    cleanup_unused_structures(list);

    printf("Total structures: %zu\n", list->count);
    printf("CRCFLAGS set count: %zu\n", list->crcflag_set_count);

    free_list(list);
    return EXIT_SUCCESS;
}
