                const std::chrono::system_clock::time_point& ts, int status,
                const TCP_CONNECTION_INFO& conn_info, 
                const REQUEST_HEADER& req_header, HTTP_METHOD method)
        : transaction_id(id), client_ip(ip), timestamp(ts), status_code(status),
