// TransactionManager class to handle transactions
class TransactionManager {
public:
    using TransactionsMap = std::map<std::chrono::system_clock::time_point, Transaction>;

private:
    mutable std::shared_mutex mutex_;
    TransactionsMap transactions_;

public:
    // Add a new transaction
    bool add_transaction(const Transaction& transaction) {
        std::unique_lock lock(mutex_);
        auto result = transactions_.insert({transaction.timestamp, transaction});
        return result.second;  // Returns true if insertion was successful (no duplicate timestamp)
