        std::unique_lock lock(mutex_);
        for (auto& [timestamp, txn] : transactions_) {
            if (txn.transaction_id == id) {
                txn.status_code = new_status;
                return true; // Transaction updated successfully
            }
        }
        return false;  // No transaction with the given ID found
    }

    // Retrieve a transaction by ID
    std::optional<Transaction> get_transaction(const std::string& id) const {
        std::shared_lock lock(mutex_);
        for (const auto& [timestamp, txn] : transactions_) {
            if (txn.transaction_id == id)
                return txn;
        }
        return {};  // No transaction with the given ID found
    }

    // Iterate over all transactions in chronological order
