} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    size_t head;
    size_t tail;
    bool paused;
} Buffer;

void buffer_init(Buffer* buffer) {
    buffer->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_BUFFER_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer->data) exit(EXIT_FAILURE);
    buffer->capacity = INITIAL_BUFFER_SIZE;
    buffer->length = 0;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->paused = false;
}

bool buffer_resize(Buffer* buffer, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(buffer->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data) return false;
    buffer->data = temp_data;
    buffer->capacity = new_capacity;
    return true;
}

bool buffer_push(Buffer* buffer, NFAPI_CRC_INDICATION_PDU_T item) {
    if (buffer->length == buffer->capacity) {
        if (!buffer_resize(buffer, buffer->capacity * 2)) return false;
    }
    buffer->data[buffer->tail] = item;
    buffer->tail = (buffer->tail + 1) % buffer->capacity;
    buffer->length++;
    return true;
}

bool buffer_pop(Buffer* buffer, NFAPI_CRC_INDICATION_PDU_T* item) {
    if (buffer->length == 0) return false;
    *item = buffer->data[buffer->head];
    buffer->head = (buffer->head + 1) % buffer->capacity;
    buffer->length--;
    return true;
}

