        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

        if (!buffer_push(buffer, pdu)) {
            fprintf(stderr, "Error: Buffer overflow\n");
            exit(EXIT_FAILURE);
        }
    }
}

void pause_processing(Buffer* buffer) {
    buffer->paused = true;
}

void resume_processing(Buffer* buffer) {
    buffer->paused = false;
}

void free_buffer(Buffer* buffer) {
    free(buffer->data);
}

