            fprintf(stderr, "Integrity check failed for NAS_PDU.\n");
            free(node->nas_pdu);
            free(node);
            pthread_mutex_unlock(&list_lock);
            return head;
        }

        // Link the node into the list
        node->next = head;
        head = node;
    }

    pthread_mutex_unlock(&list_lock);
    return head;
}

// Function to free the linked list
void free_linked_list(LTE_Uplink_SRB_Message *head) {
    pthread_mutex_lock(&list_lock);
    LTE_Uplink_SRB_Message *current = head;
    while (current != NULL) {
        LTE_Uplink_SRB_Message *next_node = current->next;
        if (current->nas_pdu != NULL) {
            free(current->nas_pdu->data);
            free(current->nas_pdu);
        }
        free(current);
        current = next_node;
    }
    pthread_mutex_unlock(&list_lock);
}

// Example usage
