```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NAS_PDU {
    int type;
    size_t length;
    char *data;
} NAS_PDU;

typedef struct RRC_Initial_Uplink_Message {
    // Assume this structure is defined elsewhere
} RRC_Initial_Uplink_Message;

typedef struct LTE_Uplink_SRB_Message {
    RRC_Initial_Uplink_Message rrc_msg;
    NAS_PDU *nas_pdu;
    time_t timestamp;
    struct LTE_Uplink_SRB_Message *prev;
    struct LTE_Uplink_SRB_Message *next;
} LTE_Uplink_SRB_Message;

typedef struct {
    LTE_Uplink_SRB_Message *head;
    LTE_Uplink_SRB_Message *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void init_list(DoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int rand_nas_type() {
    return rand() % 10; // Simulating random NAS message type
}

int verify_nas_message(const NAS_PDU *nas_pdu) {
    // Simulate verification logic
    return nas_pdu->data != NULL && nas_pdu->length > 0;
}

NAS_PDU* create_nas_pdu() {
    int type = rand_nas_type();
    size_t length = rand() % 256; // Random length for demonstration

    NAS_PDU *nas_pdu = (NAS_PDU *)malloc(sizeof(NAS_PDU));
    if (!nas_pdu) return NULL;

    nas_pdu->type = type;
    nas_pdu->length = length;
    nas_pdu->data = malloc(length);
    if (!nas_pdu->data) {
        free(nas_pdu);
        return NULL;
    }

    // Initialize data with random values
    for (size_t i = 0; i < length; ++i) {
        ((unsigned char *)nas_pdu->data)[i] = rand() % 256;
    }

    return nas_pdu;
}

void free_nas_pdu(NAS_PDU *nas_pdu) {
    if (nas_pdu) {
        free(nas_pdu->data);
        free(nas_pdu);
    }
}

int add_node(DoublyLinkedList *list, RRC_Initial_Uplink_Message rrc_msg) {
    pthread_mutex_lock(&list->lock);

    NAS_PDU *nas_pdu = create_nas_pdu();
    if (!nas_pdu || !verify_nas_message(nas_pdu)) {
        fprintf(stderr, "Failed to initialize or verify NAS PDU\n");
        free_nas_pdu(nas_pdu);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    LTE_Uplink_SRB_Message *new_node = (LTE_Uplink_SRB_Message *)malloc(sizeof(LTE_Uplink_SRB_Message));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        free_nas_pdu(nas_pdu);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->rrc_msg = rrc_msg;
    new_node->nas_pdu = nas_pdu;
    new_node->timestamp = time(NULL);
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void traverse_list(DoublyLinkedList *list, void (*callback)(LTE_Uplink_SRB_Message *)) {
    pthread_mutex_lock(&list->lock);

    LTE_Uplink_SRB_Message *current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_node(DoublyLinkedList *list, LTE_Uplink_SRB_Message *node_to_remove) {
    pthread_mutex_lock(&list->lock);

    if (!node_to_remove) return;

    if (node_to_remove->prev) {
        node_to_remove->prev->next = node_to_remove->next;
    } else {
        list->head = node_to_remove->next;
    }

    if (node_to_remove->next) {
        node_to_remove->next->prev = node_to_remove->prev;
    } else {
        list->tail = node_to_remove->prev;
    }

    free_nas_pdu(node_to_remove->nas_pdu);
    free(node_to_remove);

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(DoublyLinkedList *list) {
    traverse_list(list, (void (*)(LTE_Uplink_SRB_Message *))free_node);
    pthread_mutex_destroy(&list->lock);
}

void free_node(LTE_Uplink_SRB_Message *node) {
    free_nas_pdu(node->nas_pdu);
    free(node);
}

// Example usage
int main() {
    srand(time(NULL));
    DoublyLinkedList list;
    init_list(&list);

    // Simulate adding nodes
    for (int i = 0; i < 10000; ++i) {
        RRC_Initial_Uplink_Message rrc_msg;
        add_node(&list, rrc_msg);
    }

    // Traverse and print node details
    traverse_list(&list, [](LTE_Uplink_SRB_Message *node) {
        printf("NAS Type: %d, Length: %zu\n", node->nas_pdu->type, node->nas_pdu->length);
    });

    cleanup_list(&list);
    return 0;
}
