    for (size_t i = 0; i < N; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
        (*array)[i].RNTI = rand() % 1000; // Example initialization
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 1000; // Example initialization
        (*array)[i].CRC_FLAG = (rand() % 2 == 0) ? 1 : 0;
        (*array)[i].timestamp = time(NULL);
    }

    return 0; // Success
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array != NULL) {
        free(array);
    }
}
