LTE_Uplink_SRB_Message* init_linked_list(size_t node_count) {
    if (node_count == 0) return NULL;

    pthread_mutex_lock(&list_lock);

    LTE_Uplink_SRB_Message *head = NULL, **last_ptr = &head;

    for (size_t i = 0; i < node_count; ++i) {
        LTE_Uplink_SRB_Message *new_node = (LTE_Uplink_SRB_Message*)malloc(sizeof(LTE_Uplink_SRB_Message));
