        if (nas_pdu_status != 0) {
            log_message("Failed to initialize NAS PDU due to network conditions.");
            free(new_node);
            break;
        }

        *last_ptr = new_node;
        last_ptr = &new_node->next;
    }

    pthread_mutex_unlock(&list_lock);

    return head;
}

int simulate_network_conditions() {
    // Randomly adjust the network condition for demonstration
    srand(time(NULL));
    int rand_val = rand() % 100;

    if (rand_val < 20) current_network_condition = NETWORK_CONDITION_PACKET_LOSS;
    else if (rand_val < 50) current_network_condition = NETWORK_CONDITION_HIGH_LATENCY;
    else current_network_condition = NETWORK_CONDITION_NORMAL;

    switch (current_network_condition) {
        case NETWORK_CONDITION_NORMAL:
            return initialize_nas_pdu().length > 0 ? 0 : -1;

        case NETWORK_CONDITION_HIGH_LATENCY:
            // Simulate delay
            usleep(100000); 
            return initialize_nas_pdu().length > 0 ? 0 : -1;

        case NETWORK_CONDITION_PACKET_LOSS:
            if (rand() % 2 == 0) {
                log_message("Simulated packet loss during NAS PDU initialization.");
                return -1;
            }
            return initialize_nas_pdu().length > 0 ? 0 : -1;
    }

    return -1; // Default error
}

NAS_PDU initialize_nas_pdu() {
    int nas_type = rand() % 10 + 1; // Simulate NAS message type selection
    size_t length = (rand() % 100) + 10; // Simulate NAS PDU length

    if (length > buffer_size - sizeof(NAS_PDU)) {
        log_message("NAS PDU exceeds buffer size.");
        return (NAS_PDU){0, 0, NULL};
    }

    NAS_PDU nas_pdu;
    nas_pdu.nas_message_type = nas_type;
    nas_pdu.length = length;

    unsigned char *data = (unsigned char*)malloc(length);
    if (!data) {
        log_message("Failed to allocate memory for NAS PDU data.");
        return (NAS_PDU){0, 0, NULL};
    }

    memset(data, rand() % 256, length); // Initialize with random data
    nas_pdu.data = data;

    return nas_pdu;
}

void log_message(const char *message) {
