    if (list_head) {
        printf("Linked list initialized successfully with %zu nodes.\n", node_count);
    } else {
        printf("Failed to initialize linked list.\n");
    }

    // Free allocated resources
    LTE_Uplink_SRB_Message *current = list_head;
    while (current) {
        LTE_Uplink_SRB_Message *next = current->next;
        free(current->nas_pdu.data);
        free(current);
        current = next;
    }

    return 0;
}
