#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define constants
#define MAX_FREQUENCY_MEASUREMENTS 10

typedef struct {
    int center_frequency;
} FrequencyMeasurement;

typedef struct {
    int enb_id;
    int measurement_id;
    FrequencyMeasurement *frequency_measurements;
    size_t num_frequency_measurements;
} MeasurementReport;

typedef struct {
    MeasurementReport **reports;
    size_t num_reports;
    pthread_mutex_t lock;  // For concurrency control
} DynamicList;

// Function prototypes
DynamicList* create_dynamic_list();
void free_dynamic_list(DynamicList *list);
int add_measurement_report(DynamicList *list, int enb_id, int measurement_id);
static int validate_and_add_frequency_measurement(FrequencyMeasurement **measurements, size_t *num_measurements, int center_frequency);

// Create a new dynamic list
DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for the dynamic list");
        exit(EXIT_FAILURE);
    }

    list->reports = NULL;
    list->num_reports = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Free the dynamic list
void free_dynamic_list(DynamicList *list) {
    if (list == NULL) return;

    for (size_t i = 0; i < list->num_reports; ++i) {
        free(list->reports[i]->frequency_measurements);
        free(list->reports[i]);
    }

    free(list->reports);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new measurement report
int add_measurement_report(DynamicList *list, int enb_id, int measurement_id) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    // Allocate space for the new report
    MeasurementReport **new_reports = (MeasurementReport **)realloc(list->reports, sizeof(MeasurementReport *) * (list->num_reports + 1));
    if (!new_reports) {
        perror("Failed to reallocate memory for new measurement report");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Allocate and initialize the new measurement report
    MeasurementReport *report = (MeasurementReport *)malloc(sizeof(MeasurementReport));
    if (!report) {
        free(new_reports);  // Free reallocated memory to avoid leaks
        perror("Failed to allocate memory for a new measurement report");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    report->enb_id = enb_id;
    report->measurement_id = measurement_id;
    report->frequency_measurements = NULL;
    report->num_frequency_measurements = 0;

    // Add test frequency measurements
    for (int freq = 1800; freq <= 2100; freq += 100) {
        if (!validate_and_add_frequency_measurement(&report->frequency_measurements, &report->num_frequency_measurements, freq)) {
            perror("Failed to add a valid frequency measurement");
            free(report);
            list->reports = new_reports;
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    // Update the dynamic list
    list->reports = new_reports;
    list->reports[list->num_reports] = report;
    ++(list->num_reports);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Validate and add a frequency measurement to a report
static int validate_and_add_frequency_measurement(FrequencyMeasurement **measurements, size_t *num_measurements, int center_frequency) {
    for (size_t i = 0; i < *num_measurements; ++i) {
        if ((*measurements)[i].center_frequency == center_frequency) {
            return -1; // Duplicate frequency found
        }
    }

    FrequencyMeasurement *new_measurements = (FrequencyMeasurement *)realloc(*measurements, sizeof(FrequencyMeasurement) * (*num_measurements + 1));
    if (!new_measurements) {
        perror("Failed to reallocate memory for new frequency measurement");
        return -1;
    }

    (*measurements) = new_measurements;
    (*measurements)[*num_measurements].center_frequency = center_frequency;
    ++(*num_measurements);

    return 0;
}

// Example usage
int main() {
    DynamicList *list = create_dynamic_list();

    // Add test measurement reports
    for (int i = 1; i <= 5; ++i) {
        add_measurement_report(list, i, i*100);
    }

    // Free the list when done
    free_dynamic_list(list);

    return 0;
}
