#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_ELEMENTS 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    union {
        struct {
            unsigned int CRCFLAG:1; // 1 bit for flag, rest padding to align
            unsigned int other_fields[3]; // assuming additional fields
        } CRC_INDICATION_REL8_TAG;
    };
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    threading.Lock lock;  // For thread-safe operations
} CRC_Indication_Manager;

// Function to initialize the manager
void init_manager(CRC_Indication_Manager* manager) {
    manager->array = NULL;
    manager->count = 0;
    manager->capacity = 0;
    threading.Lock_init(&manager->lock);
}

// Function to safely add an element
int add_element(CRC_Indication_Manager* manager, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    threading.Lock_lock(&manager->lock);

    if (manager->count >= MAX_ELEMENTS) {
        printf("Error: Maximum number of elements reached.\n");
        threading.Lock_unlock(&manager->lock);
        return -1;
    }

    // Double the capacity when needed
    if (manager->capacity == 0 || manager->count == manager->capacity) {
        size_t new_capacity = (manager->capacity == 0) ? 4 : manager->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;

        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            printf("Error: Memory allocation failed.\n");
            threading.Lock_unlock(&manager->lock);
            return -1;
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &manager->array[manager->count++];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    // Set CRCFLAG to a random value (simulated with 0 or 1)
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    threading.Lock_unlock(&manager->lock);
    return 0;
}

// Function to update CRCFLAGS based on conditions
void update_crcflags(CRC_Indication_Manager* manager) {
    threading.Lock_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (/* some condition */) { // Replace with actual condition
            manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        } else {
            manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }
    }

    threading.Lock_unlock(&manager->lock);
}

// Function to serialize the array to a binary file
void serialize_to_file(CRC_Indication_Manager* manager, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Could not open file for writing.\n");
        return;
    }

    threading.Lock_lock(&manager->lock);

    size_t written_size = fwrite(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file);

    if (written_size != manager->count) {
        printf("Error: Failed to write all elements to the file.\n");
    }

    fclose(file);
    threading.Lock_unlock(&manager->lock);
}

// Function to free resources
void cleanup_manager(CRC_Indication_Manager* manager) {
    threading.Lock_lock(&manager->lock);

    if (manager->array) {
        free(manager->array);
        manager->array = NULL;
    }

    manager->count = 0;
    manager->capacity = 0;

    threading.Lock_unlock(&manager->lock);
}

// Main function for testing
int main() {
    CRC_Indication_Manager manager;
    init_manager(&manager);

    // Example of adding elements
    add_element(&manager, 12345, 67890);
    update_crcflags(&manager);
    serialize_to_file(&manager, "output.bin");

    cleanup_manager(&manager);

    return 0;
}
