#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEASUREMENT_REPORTS 1000
#define MAX_FREQUENCY_MEASUREMENTS 50
#define SIGNAL_STRENGTH_THRESHOLD 5000

typedef struct {
    int centerFrequency;
    int signalStrength;
} FrequencyMeasurement;

typedef struct {
    int eNBID;
    int measurementID;
    FrequencyMeasurement frequencies[MAX_FREQUENCY_MEASUREMENTS];
    int frequencyCount;
    int totalSignalStrength;
    pthread_mutex_t lock;
} MeasurementReport;

typedef struct {
    MeasurementReport reports[MAX_MEASUREMENT_REPORTS];
    int reportCount;
    pthread_mutex_t globalLock;
} MeasurementSystem;

void log_message(const char *message) {
    printf("%s\n", message);
}

int add_frequency_measurement(MeasurementReport *report, int centerFrequency, int signalStrength) {
    if (pthread_mutex_lock(&report->lock) != 0) return -1;

    for (int i = 0; i < report->frequencyCount; ++i) {
        if (report->frequencies[i].centerFrequency == centerFrequency) {
            pthread_mutex_unlock(&report->lock);
            return -2;
        }
    }

    int newSignalStrength = report->totalSignalStrength + signalStrength;
    if (newSignalStrength > SIGNAL_STRENGTH_THRESHOLD) {
        pthread_mutex_unlock(&report->lock);
        return -3;
    }

    report->frequencies[report->frequencyCount].centerFrequency = centerFrequency;
    report->frequencies[report->frequencyCount].signalStrength = signalStrength;
    report->totalSignalStrength = newSignalStrength;
    ++report->frequencyCount;

    pthread_mutex_unlock(&report->lock);
    return 0;
}

int create_measurement_report(MeasurementSystem *system, int eNBID, int measurementID) {
    if (pthread_mutex_lock(&system->globalLock) != 0) return -1;

    for (int i = 0; i < system->reportCount; ++i) {
        if (system->reports[i].eNBID == eNBID && 
            system->reports[i].measurementID == measurementID) {
            pthread_mutex_unlock(&system->globalLock);
            return -2;
        }
    }

    if (system->reportCount >= MAX_MEASUREMENT_REPORTS) {
        pthread_mutex_unlock(&system->globalLock);
        return -3;
    }

    MeasurementReport *newReport = &system->reports[system->reportCount++];
    newReport->eNBID = eNBID;
    newReport->measurementID = measurementID;
    newReport->frequencyCount = 0;
    newReport->totalSignalStrength = 0;

    if (pthread_mutex_init(&newReport->lock, NULL) != 0) {
        pthread_mutex_unlock(&system->globalLock);
        return -4;
    }

    log_message("Created measurement report.");
    pthread_mutex_unlock(&system->globalLock);
    return 0;
}

void destroy_measurement_system(MeasurementSystem *system) {
    for (int i = 0; i < system->reportCount; ++i) {
        pthread_mutex_destroy(&system->reports[i].lock);
    }
    pthread_mutex_unlock(&system->globalLock); // Ensure the global lock is unlocked
}

int main() {
    MeasurementSystem system;
    memset(&system, 0, sizeof(system));

    if (pthread_mutex_init(&system.globalLock, NULL) != 0) return -1;

    create_measurement_report(&system, 101, 201);
    add_frequency_measurement(&system.reports[0], 1800, 250);

    destroy_measurement_system(&system);
    pthread_mutex_destroy(&system.globalLock);

    return 0;
}
```

### Analysis of Design Choices:
- **Data Structures:** 
  - Used arrays for fixed-size lists to minimize memory overhead and ensure fast access.
  - Each `MeasurementReport` maintains its own mutex to protect frequency measurements, ensuring thread safety without excessive locking.

- **Synchronization:**
  - Implemented global lock on the measurement system level to manage concurrent modifications of the report list.
  - Individual locks for each `MeasurementReport` allow fine-grained control over concurrent access to report-specific operations.

- **Trade-offs:**
  - Trade-off between performance and memory usage by using fixed-size arrays; this simplifies synchronization and avoids dynamic allocation overhead.
  - Global lock minimizes contention during report addition, but can be a bottleneck if frequent additions/deletions occur.

- **Scalability & Extensibility:**
  - The solution is designed for concurrent access and could scale with additional optimization (e.g., read-write locks).
  - Future extensions might include dynamic memory allocation for reports or using hash maps for quick lookup by `eNBID`/`measurementID`.

- **Potential Bottlenecks:**
  - Global lock contention during high-frequency report additions.
  - Mutex operations may introduce latency under heavy load.

- **Mitigation Strategies:**
  - Consider implementing read-write locks if reads are significantly more frequent than writes, reducing the contention on global lock.
  - Evaluate partitioning reports into multiple segments to reduce global lock contention.']

