#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEASUREMENTS 1000

typedef struct {
    int centerFrequency; // Assume in MHz for simplicity
} FrequencyMeasurement;

typedef struct {
    char eNBID[16]; // Assuming fixed-length unique identifier
    char measurementID[16];
    FrequencyMeasurement *frequencyMeasurements;
    size_t numFrequencyMeasurements;
} MeasurementReport;

typedef struct {
    MeasurementReport **reports;
    size_t numReports;
    pthread_mutex_t lock; // For thread safety
} MeasurementList;

// Custom memory allocator (simple version)
#define POOL_SIZE 1024 * 1024 // 1MB pool for demonstration

char memoryPool[POOL_SIZE];
size_t nextFreeIndex = 0;

void* customAllocate(size_t size) {
    if (nextFreeIndex + size > POOL_SIZE) return NULL; // Out of memory
    void* ptr = &memoryPool[nextFreeIndex];
    nextFreeIndex += size;
    return ptr;
}

// Initialize the measurement list
MeasurementList* initMeasurementList() {
    MeasurementList *list = (MeasurementList*) customAllocate(sizeof(MeasurementList));
    if (!list) return NULL;

    list->reports = (MeasurementReport**) customAllocate(MAX_MEASUREMENTS * sizeof(MeasurementReport*));
    list->numReports = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Add a measurement report
int addMeasurementReport(MeasurementList *list, MeasurementReport *report) {
    pthread_mutex_lock(&list->lock);

    if (list->numReports >= MAX_MEASUREMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List full
    }

    list->reports[list->numReports] = report;
    list->numReports++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Populate the list with test data
void populateWithTestData(MeasurementList *list) {
    for (size_t i = 0; i < MAX_MEASUREMENTS; ++i) {
        MeasurementReport *report = (MeasurementReport*) customAllocate(sizeof(MeasurementReport));

        if (!report) continue;

        snprintf(report->eNBID, sizeof(report->eNBID), "ENB%d", (int)i);
        snprintf(report->measurementID, sizeof(report->measurementID), "MEAS%d", (int)i);

        size_t numFreqs = rand() % 10 + 1; // Random number of frequency measurements
        report->numFrequencyMeasurements = numFreqs;

        report->frequencyMeasurements = (FrequencyMeasurement*) customAllocate(numFreqs * sizeof(FrequencyMeasurement));

        for (size_t j = 0; j < numFreqs; ++j) {
            int freq = rand() % 100 + 1; // Random frequency
            while (j > 0 && report->frequencyMeasurements[j-1].centerFrequency == freq) {
                freq = rand() % 100 + 1;
            }
            report->frequencyMeasurements[j].centerFrequency = freq;
        }

        addMeasurementReport(list, report);
    }
}

// Free the list
void freeMeasurementList(MeasurementList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->numReports; ++i) {
        if (list->reports[i]) {
            customFree(list->reports[i]->frequencyMeasurements);
            customFree(list->reports[i]);
        }
    }

    customFree(list->reports);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    MeasurementList *list = initMeasurementList();
    if (!list) {
        fprintf(stderr, "Failed to initialize measurement list\n");
        return 1;
    }

    populateWithTestData(list);

    // Use the populated list...

    freeMeasurementList(list);
    return 0;
}
