void initializeEvents(NetworkEvent **events, size_t num_events, size_t max_total_payload) {
    *events = (NetworkEvent *)malloc(num_events * sizeof(NetworkEvent));
    if (*events == NULL) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }

    size_t remaining_memory = max_total_payload;
    for (size_t i = 0; i < num_events; ++i) {
