        size_t packet_size = rand() % MAX_PACKET_SIZE + 1;

        if (packet_size > MAX_PACKET_SIZE) {
            fprintf(stderr, "Payload size exceeds maximum allowed size.\n");
            continue;
        }

        if (remaining_memory < packet_size) {
            break; // No more memory to allocate
        }

        (*events)[i].id = rand(); // Random ConnectionIdentifier
        (*events)[i].timestamp = time(NULL);

        (*events)[i].data_packet.payload = (char *)malloc(packet_size);
        if ((*events)[i].data_packet.payload == NULL) {
