        buffer = NULL;
        buffer_size = 0;
        return;
    }

    NetworkEvent *new_buffer = (NetworkEvent *)realloc(buffer, (buffer_size + num_events) * sizeof(NetworkEvent));
    if (new_buffer == NULL) {
        perror("Failed to allocate memory for event buffer");
        exit(EXIT_FAILURE);
    }
    buffer = new_buffer;

    memcpy(&buffer[buffer_size], events, num_events * sizeof(NetworkEvent));
    buffer_size += num_events;
}

int main() {
    size_t num_events = 10;
    size_t max_total_payload = 10000; // Example limit

    NetworkEvent *events;
    initializeEvents(&events, num_events, max_total_payload);

    for (size_t i = 0; i < num_events; ++i) {
        if (logEvent(&events[i]) != 0) {
            bufferEvents(events + i + 1, num_events - i - 1);
            break;
        }
    }

    free(buffer); // Free any remaining buffered events
    for (size_t i = 0; i < num_events; ++i) {
        free(events[i].data_packet.payload);
    }
    free(events);

    return 0;
}
