typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ThreadSafeList;

void initThreadSafeList(ThreadSafeList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void freeNode(Node* node) {
    if (node) {
        free(node);
    }
}

void clearThreadSafeList(ThreadSafeList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        freeNode(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

int addNFAPI_CRC_INDICATION_PDU(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI found
        }
        current = current->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return -2; // Memory allocation failure
    }

    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

