// List structure with a mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

// Function to initialize the dynamic list
DynamicList* init_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to validate the NFAPI_CRC_INDICATION_PDU_T structure
int validate_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Implement schema validation logic here
    if (pdu.RNTI <= 0) {
        fprintf(stderr, "Validation error: Invalid RNTI\n");
        return 0;
    }
    // Add more validation checks as needed
    return 1;
}

// Function to check for existing RNTI in the list
int rnti_exists(DynamicList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti)
            return 1;
        current = current->next;
    }
    return 0;
}

// Function to add a new PDU to the list
void append_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_pdu(pdu)) {
        return; // Skip invalid PDUs
    }

    pthread_mutex_lock(&list->lock);

    if (rnti_exists(list, pdu.RNTI)) {
        fprintf(stderr, "Warning: RNTI %d already exists in the list\n", pdu.RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Function to free the dynamic list and prevent memory leaks
void free_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to generate a random CRCFLAG
void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    if (tag) {
        tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
}

// Example usage of the dynamic list management function
int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicList* list = init_dynamic_list();
    if (!list) return 1;

    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.ue_info_tag.RNTI = i + 1; // Example RNTI assignment
        set_random_crcflag(&pdu.crc_indication_rel8_tag);
        pdu.RNTI = pdu.ue_info_tag.RNTI;

        append_pdu(list, pdu);
    }

    free_dynamic_list(list);

    return 0;
}
