    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    int crc_status_flag; // 1 for valid, 0 for invalid
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node structure for the doubly-linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the list structure with capacity and mutex
typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    size_t max_capacity;
    pthread_mutex_t lock;
} NFAPIList;

// Function to initialize the list
void init_list(NFAPIList* list, size_t max_capacity) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->max_capacity = max_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->pdu = pdu;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to validate a PDU
int validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Add validation logic here (e.g., check for valid RNTI)
    if (!pdu || !pdu->valid_RX_UE_INFORMATION_TAG || pdu->RNTI == 0) {
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to log warnings/errors
void log_warning(const char* message) {
    fprintf(stderr, "Warning: %s\n", message);
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to add or update an entry in the list
int add_or_update_entry(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!validate_pdu(&pdu)) {
        log_error("Invalid PDU structure.");
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    Node* current = list->head;
    while (current != NULL) {
        if (current->pdu.RNTI == pdu.RNTI) {
            // Update existing entry
            current->pdu = pdu;
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
        current = current->next;
    }

    if (list->count >= list->max_capacity) {
        log_warning("List capacity exceeded. Dropping least recently used entry.");
        // Drop the oldest entry
        Node* old_node = list->head;
        if (old_node) {
            list->head = old_node->next;
            if (list->head) list->head->prev = NULL;
            free(old_node);
            list->count--;
        }
    }

    // Add new entry
    Node* new_node = create_node(pdu);
    if (!new_node) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    new_node->next = list->head;
    if (list->head) list->head->prev = new_node;
    list->head = new_node;

    if (!list->tail) {
        list->tail = new_node;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

// Function to remove an entry based on RNTI
int remove_entry(NFAPIList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->pdu.RNTI == rnti) {
            if (current->prev) current->prev->next = current->next;
            else list->head = current->next;

            if (current->next) current->next->prev = current->prev;
            else list->tail = current->prev;

            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to iterate over the list and apply transformation
void transform_list(NFAPIList* list, void (*transform)(unsigned char*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        transform(current->pdu.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example transformation function
void example_transform(unsigned char* tag) {
    for (int i = 0; i < 4; ++i) {
        tag[i] ^= 0xFF; // Simple bitwise NOT operation as an example
    }
}

// Function to free the list resources
void destroy_list(NFAPIList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
