    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

// Function declarations
void init_dynamic_list(DynamicList *list);
void free_dynamic_list(DynamicList *list);
int load_config(const char *filename, DynamicList *list);
void update_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu);
unsigned char* compute_md5_hash(const char *str, size_t *len);
void log_operation(const char *message);

// Function implementations
void init_dynamic_list(DynamicList *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_dynamic_list(DynamicList *list) {
    if (list->data) {
        free(list->data);
    }
    pthread_mutex_destroy(&list->mutex);
}

int load_config(const char *filename, DynamicList *list) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);

    if (!root) {
        log_operation("Failed to load config file.");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    size_t new_size = json_array_size(root);

    if (new_size > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_operation("Memory allocation failed.");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_size;
    }

    for (size_t i = 0; i < new_size; ++i) {
        json_t *entry = json_array_get(root, i);
        if (!json_is_object(entry)) continue;

        int RX_UE_INFORMATION_TAG = json_integer_value(json_object_get(entry, "RX_UE_INFORMATION_TAG"));
        int RNTI = json_integer_value(json_object_get(entry, "RNTI"));

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu.RNTI = RNTI;
        update_crc_flag(&pdu);

        list->data[i] = pdu;
    }

    list->size = new_size;
    pthread_mutex_unlock(&list->mutex);
    json_decref(root);
    log_operation("Config loaded successfully.");
    return 0;
}

void update_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand(time(NULL));
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

unsigned char* compute_md5_hash(const char *str, size_t *len) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), hash);

    *len = MD5_DIGEST_LENGTH;
    unsigned char *result = malloc(*len);
    if (!result) {
        log_operation("Failed to allocate memory for MD5 result.");
        return NULL;
    }
    memcpy(result, hash, *len);
    return result;
}

void log_operation(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int main() {
    DynamicList list;
    init_dynamic_list(&list);

    // Example usage
    load_config("config.json", &list);

    size_t hash_len;
    unsigned char *hash = compute_md5_hash("example_string", &hash_len);
    if (hash) {
        printf("MD5 Hash: ");
        for (size_t i = 0; i < hash_len; ++i) {
            printf("%02x", hash[i]);
        }
        printf("\n");
        free(hash);
    }

    free_dynamic_list(&list);
    return 0;
}
```

