```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_CRC_STATUS 0
#define MAX_CAPACITY_INITIAL 100

typedef struct {
    int valid_rx_ue_information_tag;
    int rnti;
    unsigned short crc_indication_rel8_tag;
    int crc_status_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
    time_t last_access_time;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t capacity;
    size_t current_size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} CRCList;

// Function declarations
CRCList* create_crc_list(size_t initial_capacity);
void destroy_crc_list(CRCList* list);
int add_or_update_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry);
int remove_entry_by_rnti(CRCList* list, int rnti);
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(CRCList* list, int rnti);
void iterate_and_transform(CRCList* list, void (*transform_func)(unsigned short*));
void handle_capacity_exceedance(CRCList* list);
void report_metrics(CRCList* list);

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);

    list->head = list->tail = NULL;
    list->capacity = initial_capacity;
    list->current_size = 0;

    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

int add_or_update_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.rnti == entry.rnti) {
            // Update existing
            current->data.crc_indication_rel8_tag = entry.crc_indication_rel8_tag;
            current->data.crc_status_flag = entry.crc_status_flag;
            current->last_access_time = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return 1; // Updated
        }
        current = current->next;
    }

    if (list->current_size >= list->capacity) {
        handle_capacity_exceedance(list);
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Memory allocation failure
    }
    *new_node = (Node){entry, NULL, list->tail, time(NULL)};

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }

    list->tail = new_node;
    ++list->current_size;

    pthread_mutex_unlock(&list->lock);
    return 1; // Added
}

int remove_entry_by_rnti(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.rnti == rnti) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            if (current == list->tail) list->tail = prev;
            free(current);
            --list->current_size;
            pthread_mutex_unlock(&list->lock);
            return 1; // Removed
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Not found
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            current->last_access_time = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void iterate_and_transform(CRCList* list, void (*transform_func)(unsigned short*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        transform_func(&(current->data.crc_indication_rel8_tag));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void handle_capacity_exceedance(CRCList* list) {
    // Remove the least recently used entry
    if (!list->head || !list->tail) return;

    Node *lru = list->head, *prev = NULL, *current = list->head;
    while (current) {
        if (current->last_access_time < lru->last_access_time) {
            lru = current;
            prev = prev ? prev : list->head; // Edge case for head
        }
        current = current->next;
    }

    if (prev == NULL) { // Removing the head node
        list->head = list->head->next;
        if (list->head == NULL) list->tail = NULL;
    } else {
        prev->next = lru->next;
        if (lru == list->tail) list->tail = prev; // Removing tail node
    }

    free(lru);
    --list->current_size;

    // Adjust capacity if needed based on historical data or current load
    // This logic can be customized to adapt dynamically
}

void report_metrics(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    printf("Current Capacity: %zu\n", list->capacity);
    printf("Current Size: %zu\n", list->current_size);

    // Additional metrics such as average load, peak load over T seconds can be implemented here

    pthread_mutex_unlock(&list->lock);
}

// Example transform function
void example_transform(unsigned short* crc_tag) {
    *crc_tag ^= 0xFFFF; // Invert bits for demonstration
}
