#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    uint8_t CRCFLAG; // True or False represented as 1 or 0
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned long long RNTI_sum; // To store the sum of RNTIs for parity check
} CRCList;

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->RNTI_sum = 0;
    return list;
}

void free_crc_list(CRCList *list) {
    if (list) {
        free(list->elements);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_element(CRCList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RNTI < 1 || element.RNTI > 65535) {
        return -1; // Invalid RNTI
    }

    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Memory allocation failed
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->RNTI_sum += element.RNTI;
    list->elements[list->count++] = element;

    // Determine CRCFLAG based on the parity of RNTI sum
    for (size_t i = 0; i < list->count; ++i) {
        list->elements[i].CRCFLAG = (list->RNTI_sum % 2 == 0);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int main() {
    // Example usage
    CRCList *crc_list = create_crc_list(10);

    NFAPI_CRC_INDICATION_PDU_T element1 = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 4567 };
    add_element(crc_list, element1);

    NFAPI_CRC_INDICATION_PDU_T element2 = { .RX_UE_INFORMATION_TAG = 124, .RNTI = 8910 };
    add_element(crc_list, element2);

    // Free the list when done
    free_crc_list(crc_list);
    return 0;
}
