#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the custom data structures
typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES 1000

// Define the network interface statistics array
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NetworkInterfaceStatsArray;

// Function prototypes
NetworkInterfaceStatsArray* init_network_stats_array(size_t initial_capacity);
int add_entry(NetworkInterfaceStatsArray *array, const NFAPI_CRC_INDICATION_PDU_T *entry);
NFAPI_CRC_INDICATION_PDU_T* get_entry(NetworkInterfaceStatsArray *array, size_t index);
int remove_entry(NetworkInterfaceStatsArray *array, size_t index);

// Initialize the network statistics array
NetworkInterfaceStatsArray* init_network_stats_array(size_t initial_capacity) {
    NetworkInterfaceStatsArray *array = (NetworkInterfaceStatsArray *)malloc(sizeof(NetworkInterfaceStatsArray));
    if (!array) return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Add an entry to the network statistics array
int add_entry(NetworkInterfaceStatsArray *array, const NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (!array || !entry) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->size >= MAX_ENTRIES) {
        fprintf(stderr, "Overflow: Maximum number of entries reached.\n");
        pthread_mutex_unlock(&array->lock);
        return -2;
    }

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -3;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    // Validate the entry before insertion
    if (entry->RX_UE_INFORMATION_TAG == 0 || entry->RNTI == 0) {
        pthread_mutex_unlock(&array->lock);
        return -4;
    }

    memcpy(&array->data[array->size], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Retrieve an entry from the network statistics array
NFAPI_CRC_INDICATION_PDU_T* get_entry(NetworkInterfaceStatsArray *array, size_t index) {
    if (!array || index >= array->size) return NULL;

    pthread_mutex_lock(&array->lock);
    NFAPI_CRC_INDICATION_PDU_T *entry = &array->data[index];
    pthread_mutex_unlock(&array->lock);

    return entry;
}

// Remove an entry from the network statistics array
int remove_entry(NetworkInterfaceStatsArray *array, size_t index) {
    if (!array || index >= array->size) return -1;

    pthread_mutex_lock(&array->lock);

    memmove(&array->data[index], &array->data[index + 1], (array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size--;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Example usage
int main() {
    NetworkInterfaceStatsArray *stats_array = init_network_stats_array(10);

    if (!stats_array) {
        fprintf(stderr, "Failed to initialize network statistics array.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Random valid tag
    entry.RNTI = rand() % 100 + 1; // Random valid RNTI
    entry.crc_tag.CRCFLAG = rand() % 2;

    if (add_entry(stats_array, &entry) != 0) {
        fprintf(stderr, "Failed to add entry.\n");
    }

    NFAPI_CRC_INDICATION_PDU_T *retrieved_entry = get_entry(stats_array, 0);
    if (retrieved_entry) {
        printf("Retrieved Entry: RX_UE_INFORMATION_TAG=%lu, RNTI=%hu, CRCFLAG=%u\n",
               retrieved_entry->RX_UE_INFORMATION_TAG,
               retrieved_entry->RNTI,
               retrieved_entry->crc_tag.CRCFLAG);
    }

    if (remove_entry(stats_array, 0) != 0) {
        fprintf(stderr, "Failed to remove entry.\n");
    }

    free(stats_array->data);
    pthread_mutex_destroy(&stats_array->lock);
    free(stats_array);

    return 0;
}
