#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int mac_entity_id;
    char **logical_channels; // Dynamic array of strings for logical channels
    size_t channel_count;
} LogicalChannelList;

typedef struct {
    int mac_entity_id;
    LogicalChannelList *channels;
    time_t last_update_timestamp;
} MECP_Message;

typedef struct {
    MECP_Message *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} MECP_Array;

// Function prototypes
MECP_Array* initialize_mecp_array();
void insert_mecp_message(MECP_Array *array, int mac_entity_id, const char **logical_channels, size_t channel_count);
int delete_mecp_message(MECP_Array *array, int mac_entity_id);
MECP_Message* retrieve_mecp_message(const MECP_Array *array, int mac_entity_id);
void serialize_mecp_messages(const MECP_Array *array, unsigned char **buffer, size_t *length);
void refresh_logical_channels(MECP_Array *array); // Placeholder for actual implementation
void free_mecp_array(MECP_Array *array);

MECP_Array* initialize_mecp_array() {
    MECP_Array *array = (MECP_Array *)malloc(sizeof(MECP_Array));
    if (!array) return NULL;

    array->messages = (MECP_Message *)malloc(INITIAL_CAPACITY * sizeof(MECP_Message));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void insert_mecp_message(MECP_Array *array, int mac_entity_id, const char **logical_channels, size_t channel_count) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MECP_Message *new_messages = (MECP_Message *)realloc(array->messages, new_capacity * sizeof(MECP_Message));
        if (!new_messages) {
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].mac_entity_id == mac_entity_id) {
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    MECP_Message *new_message = &array->messages[array->count++];
    new_message->mac_entity_id = mac_entity_id;

    new_message->channels = (LogicalChannelList *)malloc(sizeof(LogicalChannelList));
    if (!new_message->channels) {
        pthread_mutex_unlock(&array->lock);
        return;
    }

    new_message->channels->logical_channels = (char **)malloc(channel_count * sizeof(char *));
    if (!new_message->channels->logical_channels) {
        free(new_message->channels);
        pthread_mutex_unlock(&array->lock);
        return;
    }

    for (size_t i = 0; i < channel_count; ++i) {
        new_message->channels->logical_channels[i] = strdup(logical_channels[i]);
        if (!new_message->channels->logical_channels[i]) {
            while (--i >= 0) free(new_message->channels->logical_channels[i]);
            free(new_message->channels->logical_channels);
            free(new_message->channels);
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    new_message->channels->channel_count = channel_count;
    new_message->last_update_timestamp = time(NULL);

    pthread_mutex_unlock(&array->lock);
}

int delete_mecp_message(MECP_Array *array, int mac_entity_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].mac_entity_id == mac_entity_id) {
            MECP_Message *message = &array->messages[i];
            for (size_t j = 0; j < message->channels->channel_count; ++j) {
                free(message->channels->logical_channels[j]);
            }
            free(message->channels->logical_channels);
            free(message->channels);

            memmove(&array->messages[i], &array->messages[i + 1], (array->count - i - 1) * sizeof(MECP_Message));
            array->count--;

            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1;
}

MECP_Message* retrieve_mecp_message(const MECP_Array *array, int mac_entity_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].mac_entity_id == mac_entity_id) {
            return &array->messages[i];
        }
    }
    return NULL;
}

void serialize_mecp_messages(const MECP_Array *array, unsigned char **buffer, size_t *length) {
    pthread_mutex_lock((pthread_mutex_t *)&array);

    // Calculate buffer length
    size_t total_length = sizeof(size_t); // For the count of messages

    for (size_t i = 0; i < array->count; ++i) {
        MECP_Message *msg = &array->messages[i];
        total_length += sizeof(int) + sizeof(time_t); // mac_entity_id and last_update_timestamp
        total_length += sizeof(size_t); // channel_count
        for (size_t j = 0; j < msg->channels->channel_count; ++j) {
            total_length += strlen(msg->channels->logical_channels[j]) + 1; // null-terminated strings
        }
    }

    *buffer = (unsigned char *)malloc(total_length);
    if (!*buffer) {
        pthread_mutex_unlock((pthread_mutex_t *)&array);
        return;
    }

    unsigned char *ptr = *buffer;

    memcpy(ptr, &array->count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < array->count; ++i) {
        MECP_Message *msg = &array->messages[i];

        memcpy(ptr, &msg->mac_entity_id, sizeof(int));
        ptr += sizeof(int);
        memcpy(ptr, &msg->last_update_timestamp, sizeof(time_t));
        ptr += sizeof(time_t);

        size_t channel_count = msg->channels->channel_count;
        memcpy(ptr, &channel_count, sizeof(size_t));
        ptr += sizeof(size_t);

        for (size_t j = 0; j < channel_count; ++j) {
            const char *channel = msg->channels->logical_channels[j];
            size_t len = strlen(channel) + 1;
            memcpy(ptr, channel, len);
            ptr += len;
        }
    }

    *length = total_length;

    pthread_mutex_unlock((pthread_mutex_t *)&array);
}

void refresh_logical_channels(MECP_Array *array) {
    // This function should be implemented to periodically update logical channels
    // based on external data source.
}

void free_mecp_array(MECP_Array *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        MECP_Message *message = &array->messages[i];
        for (size_t j = 0; j < message->channels->channel_count; ++j) {
            free(message->channels->logical_channels[j]);
        }
        free(message->channels->logical_channels);
        free(message->channels);
    }

    free(array->messages);
    pthread_mutex_unlock(&array->lock);

    pthread_mutex_destroy(&array->lock);
    free(array);
}
