    }

    pthread_mutex_unlock(&list->lock);
}

// Merges two sorted lists
ListNode* merge_sorted_lists(ListNode* a, ListNode* b) {
    if (!a) return b;
    if (!b) return a;

    if (a->data.rnti < b->data.rnti) {
        a->next = merge_sorted_lists(a->next, b);
        return a;
    } else {
        b->next = merge_sorted_lists(a, b->next);
        return b;
    }
}

// Helper function to sort and add elements
void sort_and_add(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = *pdu;
    new_node->next = NULL;

    // Split the list
    ListNode* slow = list->head;
    ListNode* fast = list->head;
    while (fast && fast->next) {
        fast = fast->next->next;
        if (fast) {
            slow = slow->next;
        }
    }

    // Merge sort logic
    ListNode* a = list->head;
    ListNode* b = slow->next;
    slow->next = NULL;

    // Recursively split and merge
    a = merge_sorted_lists(a, sort_and_add_helper(list, a));
    b = merge_sorted_lists(b, sort_and_add_helper(list, b));

    // Merge both lists with new node
    ListNode* merged_head = merge_sorted_lists(merge_sorted_lists(a, new_node), b);
    list->head = merged_head;

    pthread_mutex_unlock(&list->lock);
}

ListNode* sort_and_add_helper(List* list, ListNode* head) {
    if (!head || !head->next) return head;

    // Split the list
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        fast = fast->next->next;
        if (fast) {
            slow = slow->next;
        }
    }

    ListNode* b = slow->next;
    slow->next = NULL;

    // Recursively sort and merge
    ListNode* a = sort_and_add_helper(list, head);
    ListNode* b_sorted = sort_and_add_helper(list, b);

    return merge_sorted_lists(a, b_sorted);
}

