} CRC_IndicationList;

// Function to create a new node using custom allocator
Node* create_node(CustomAllocator* allocator, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)allocator->allocate(sizeof(Node));
    if (!new_node) return NULL;

    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;
    return new_node;
}

// Function to add a new entry
int add_entry(CRC_IndicationList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node** current = &list->head;

    while (*current) {
        if ((*current)->data.RNTI == data.RNTI) {
            return ERROR_DUPLICATE_RNTI;
        }
        current = &(*current)->next;
    }

    Node* new_node = create_node(&list->allocator, data);
    if (!new_node) {
        return ERROR_MEMORY_ALLOCATION_FAILED;
