['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 10000

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct {
    uint64_t eventTimestamp;
    EventType eventType;
    char *eventDetails;  // Compressed or encoded details for space efficiency
} NetworkEventRecord;

// Thread-safe queue to manage retries of failed data fetches
typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    NetworkEventRecord records[MAX_EVENTS];
    int front, rear, size;
} EventQueue;

void init_event_queue(EventQueue *queue) {
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    queue->front = 0;
    queue->rear = -1;
    queue->size = 0;
}

int is_full(EventQueue *queue) {
    return (queue->size == MAX_EVENTS);
}

int is_empty(EventQueue *queue) {
    return (queue->size == 0);
}

void enqueue(EventQueue *queue, NetworkEventRecord record) {
    pthread_mutex_lock(&queue->lock);

    while (is_full(queue)) {
        pthread_cond_wait(&queue->cond_var, &queue->lock);
    }

    queue->rear = (queue->rear + 1) % MAX_EVENTS;
    queue->records[queue->rear] = record;
    queue->size++;

    pthread_mutex_unlock(&queue->lock);
    pthread_cond_signal(&queue->cond_var);
}

NetworkEventRecord dequeue(EventQueue *queue) {
    NetworkEventRecord record;

    pthread_mutex_lock(&queue->lock);

    while (is_empty(queue)) {
        pthread_cond_wait(&queue->cond_var, &queue->lock);
    }

    record = queue->records[queue->front];
    queue->front = (queue->front + 1) % MAX_EVENTS;
    queue->size--;

    pthread_mutex_unlock(&queue->lock);
    pthread_cond_signal(&queue->cond_var);

