// Thread function to process events
void* process_events(void* arg) {
    EventQueue *queue = (EventQueue*)arg;

    while (1) {
        NetworkEventRecord record = dequeue(queue);

        // Retry mechanism for fetching details
        int retries = 0;
        char *details = NULL;
        while (!details && retries < 3) {
            details = fetch_event_details(record.eventType);
            if (!details) {
                sleep(1);  // Backoff before retrying
            }
            retries++;
        }

        if (details) {
            record.eventDetails = details;
            printf("Processed Event: Timestamp=%llu, Type=%d, Details=%s\n",
                   record.eventTimestamp, record.eventType, record.eventDetails);
        } else {
            fprintf(stderr, "Failed to fetch event details after retries.\n");
        }

        free(details);  // Free memory if allocated
    }
}

// Function to initialize and populate the array of NetworkEventRecord structures
void initialize_and_populate_events(NetworkEventRecord *events, int count) {
    srand(time(NULL));
    EventQueue queue;
    init_event_queue(&queue);

    pthread_t threads[4];  // Thread pool with 4 worker threads

    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, process_events, &queue);
    }

    uint64_t currentTimestamp = time(NULL);  // Current Unix timestamp
    for (int i = 0; i < count; ++i) {
        NetworkEventRecord record;
        record.eventTimestamp = currentTimestamp + i;  // Ensure monotonically increasing timestamps
        record.eventType = rand() % 2;  // Random event type

        enqueue(&queue, record);
    }

    for (int i = 0; i < count; ++i) {
        events[i] = dequeue(&queue);  // Retrieve processed events
    }

    for (int i = 0; i < 4; ++i) {
        pthread_cancel(threads[i]);  // Gracefully terminate threads
    }
}

int main() {
