#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    union {
        struct {
            bool CRCFLAG;
        } REL8_TAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Custom allocator functions
void* custom_alloc(size_t size) {
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)custom_alloc(sizeof(DynamicArray));
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    custom_free(array->data);
    pthread_mutex_destroy(&array->lock);
    custom_free(array);
}

bool insert_pdu(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_data, array->data, array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        custom_free(array->data);
        array->data = new_data;
        array->capacity = new_capacity;
    }

    if (pdu.RNTI <= 0) {
        pthread_mutex_unlock(&array->lock);
        return false; // Invalid RNTI
    }

    array->data[array->size++] = pdu;

    pthread_mutex_unlock(&array->lock);
    return true;
}

bool delete_pdu(DynamicArray *array, int index) {
    pthread_mutex_lock(&array->lock);

    if (index < 0 || index >= array->size) {
        pthread_mutex_unlock(&array->lock);
        return false; // Invalid index
    }

    memmove(&array->data[index], &array->data[index + 1], (--array->size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&array->lock);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(DynamicArray *array, int index) {
    pthread_mutex_lock(&array->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    if (index >= 0 && index < array->size) {
        pdu = &array->data[index];
    }

    pthread_mutex_unlock(&array->lock);
    return pdu;
}

void report_memory_usage(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    printf("Memory Usage: %zu elements, Capacity: %zu\n", array->size, array->capacity);

    pthread_mutex_unlock(&array->lock);
}

// Example unit test
