    insert_pdu(array, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 101, .CRC_INDICATION_REL8_TAG = {.CRCFLAG = false}};
    insert_pdu(array, pdu2);

    printf("Inserted two PDUs.\n");

    delete_pdu(array, 0);
    printf("Deleted first PDU.\n");

    report_memory_usage(array);

    destroy_dynamic_array(array);
}

int main() {
    test_insert_and_delete();
    return 0;
}
