#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_MEMORY 10485760 // Example maximum memory limit (10MB)
#define INITIAL_SIZE 1000
#define SCALE_FACTOR 2
#define INACTIVITY_TIMEOUT 30 // seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
    time_t last_accessed; // Timestamp for inactivity tracking
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    time_t update_interval;
} CRC_Dynamic_Array;

CRC_Dynamic_Array* create_crc_array(size_t initial_size, time_t update_interval) {
    CRC_Dynamic_Array *arr = malloc(sizeof(CRC_Dynamic_Array));
    if (!arr) return NULL;

    arr->size = 0;
    arr->capacity = initial_size;
    arr->array = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&arr->lock, NULL);
    arr->update_interval = update_interval;

    return arr;
}

void free_crc_array(CRC_Dynamic_Array *arr) {
    if (arr) {
        pthread_mutex_destroy(&arr->lock);
        free(arr->array);
        free(arr);
    }
}

void resize_if_needed(CRC_Dynamic_Array *arr) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * SCALE_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&arr->lock);
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        }

        arr->capacity = new_capacity;
        arr->array = new_array;
    }

    pthread_mutex_unlock(&arr->lock);
}

void add_crc_pdu(CRC_Dynamic_Array *arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    resize_if_needed(arr);

    pthread_mutex_lock(&arr->lock);
    if (arr->size < arr->capacity) {
        arr->array[arr->size++] = pdu;
    }
    pthread_mutex_unlock(&arr->lock);
}

void update_pdu_activity(CRC_Dynamic_Array *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index < arr->size) {
        arr->array[index].last_accessed = time(NULL);
    }

    pthread_mutex_unlock(&arr->lock);
}

void garbage_collect(CRC_Dynamic_Array *arr) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&arr->lock);

    size_t write_index = 0;
    for (size_t i = 0; i < arr->size; ++i) {
        if (difftime(current_time, arr->array[i].last_accessed) > INACTIVITY_TIMEOUT) {
            // Mark as inactive but keep in place
            continue;
        }

        if (write_index != i) {
            arr->array[write_index] = arr->array[i];
        }

        write_index++;
    }

    arr->size = write_index;

    pthread_mutex_unlock(&arr->lock);
}

void* data_source_update_thread(void *arg) {
    CRC_Dynamic_Array *arr = (CRC_Dynamic_Array*) arg;

    while (1) {
        // Simulate receiving updates
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand(), .CRCFLAG = rand() % 2 };
        add_crc_pdu(arr, pdu);

        sleep(arr->update_interval);
    }

    return NULL;
}

int main() {
    CRC_Dynamic_Array *crc_array = create_crc_array(INITIAL_SIZE, 5); // Update every 5 seconds
    if (!crc_array) {
        fprintf(stderr, "Failed to initialize the dynamic array\n");
        return EXIT_FAILURE;
    }

    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, data_source_update_thread, crc_array)) {
        fprintf(stderr, "Error creating data source update thread\n");
        free_crc_array(crc_array);
        return EXIT_FAILURE;
    }

    // Periodic garbage collection
    while (1) {
        sleep(INACTIVITY_TIMEOUT / 2); // Check periodically within the timeout interval
        garbage_collect(crc_array);

        pthread_mutex_lock(&crc_array->lock);
        printf("Array size: %zu\n", crc_array->size);
        pthread_mutex_unlock(&crc_array->lock);
    }

    pthread_join(update_thread, NULL);
    free_crc_array(crc_array);
    return EXIT_SUCCESS;
}
