['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Global lock for thread-safe operations
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
} CRCList;

CRCList* create_list(size_t initial_capacity) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void resize_list(CRCList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list_lock);
    if (list->size == list->capacity) {
        resize_list(list, list->capacity * 2);
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list_lock);
}

void free_list(CRCList* list) {
    pthread_mutex_lock(&list_lock);
    free(list->data);
    free(list);
    pthread_mutex_unlock(&list_lock);
}

int log_to_file(const char* message, FILE* logfile) {
    if (logfile == NULL) {
        fprintf(stderr, "%s", message);
        return 0;
    }
    fprintf(logfile, "%s\n", message);
    return 1;
}

void manage_crc_indications(size_t N) {
    if (N < 1 || N > MAX_STRUCTURES) {
        log_to_file("Invalid input size. Must be between 1 and 1000.", NULL);
        return;
    }

    FILE* logfile = fopen("crc_indication_log.txt", "a");
    if (!logfile) {
        perror("Failed to open log file");
        return;
    }

    CRCList* list = create_list(10);
    if (!list) {
        log_to_file("Memory allocation failed for the list.", logfile);
        fclose(logfile);
        return;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 256;
        pdu.RNTI = rand() % 65536;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = rand() & 1; // Randomly set to 0 or 1

        add_pdu(list, pdu);
    }

    log_to_file("Created structures successfully.", logfile);
    fclose(logfile);

    free_list(list);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t N = atoi(argv[1]);
    manage_crc_indications(N);

    return EXIT_SUCCESS;
}
